window.KURAN_MEALS=window.KURAN_MEALS||{};window.KURAN_MEALS["kutub"]=[[{"n":1,"t":"Rahman ve Rahim olan Allah’ın adıyla"},{"n":2,"t":"Hamd, tüm alemlerin Rabbi olan Allah’a mahsustur."},{"n":3,"t":"Rahman ve Rahim"},{"n":4,"t":"Din gününün sahibi (maliki)"},{"n":5,"t":"(Allah’ım!) Yalnız sana kulluk eder, yalnız senden yardım dileriz."},{"n":6,"t":"Bizleri doğru yola ilet,"},{"n":7,"t":"Kendilerine nimet verdiklerinin yoluna; gazaba uğrayanların ve sapıkların yoluna değil."}],[{"n":1,"t":"Elif Lâm Mim"},{"n":2,"t":"Doğru olduğu kuşkusuz olan bu kitap, takva sahipleri için hidayet kaynağıdır."},{"n":3,"t":"Onlar görmediklerine inanırlar, namazı kılarlar ve kendilerine verdiğimiz rızıktan başkalarına verirler."},{"n":4,"t":"Yine onlar gerek sana ve gerekse senden önce indirilen kitaplara inanırlar ve Ahiretten hiç kuşku duymazlar."},{"n":5,"t":"İşte onlar Rabblerinden gelen hidayet yolundadırlar ve kurtuluşa erenlerdir."},{"n":6,"t":"Kâfirlere gelince onları uyarsan da uyarmasan da farketmez; onlar iman etmezler."},{"n":7,"t":"Allah onların kalblerini ve kulaklarını mühürlemiştir, onların gözlerinde perde vardır. Onları büyük bir azap beklemektedir."},{"n":8,"t":"Kimi insanlar var ki; «Allah’a ve Ahiret gününe inandık» derler, ama aslında inanmamışlardır."},{"n":9,"t":"Bunlar Allah’ı ve müminleri aldatmaya çalışırlar. Oysa sadece kendilerini aldatıyorlar, ama bunun farkında değildirler."},{"n":10,"t":"Onların kalplerinde hastalık vardır, Allah da bu hastalıklarını arttırmıştır, bu yalancılıkları yüzünden onları acı bir azab beklemektedir."},{"n":11,"t":"Onlara «yeryüzünde bozgunculuk çıkarmayın» denildiği vakit «Biz yapıcı, düzeltici kimseleriz» derler."},{"n":12,"t":"İyi bilesiniz ki, onlar bozguncuların ta kendileridir, fakat bunun farkında değildirler..."},{"n":13,"t":"Onlara «Halk nasıl iman etti ise siz de öyle iman edin» denildiği zaman «Biz hiç beyinsiz ayaktakımı gibi iman eder miyiz?» derler. Asıl beyinsiz ayaktakımı kendileridir, ama bunu bilmiyorlar."},{"n":14,"t":"Onlar müminler ile karşılaştıkları zaman «inandık» derler. Fakat şeytanları, elebaşları ile başbaşa kaldıkları zaman «Biz sizin yanınızdayız, onlarla sadece alay ediyoruz» derler."},{"n":15,"t":"Aslında onlarla alay eden ve kendilerini azgınlıkları içinde debelenmeye bırakan Allah’tır."},{"n":16,"t":"Onlar hidayet karşılığında sapıklığı satın alan kimselerdir. Bu yüzden yaptıkları ticaretten kazanç elde edememişler ve de hidayete erememişlerdir."},{"n":17,"t":"Onların durumu karanlıkta ateş yakan kimseler gibidir. Ateş etraflarını aydınlattığı zaman Allah onların aydınlıklarını gidererek kendilerini hiçbir şey göremeyecekleri koyu bir karanlıkta bırakır."},{"n":18,"t":"Onlar sağır, dilsiz ve kördürler. Bu yüzden geri dönemezler."},{"n":19,"t":"Ya da onların durumu koyu bulutlu, şimşekli ve gürültülü bir gökyüzünün yağmuruna tutulmuş, ölüm korkusu içinde yıldırımlara karşı parmakları ile kulaklarını tıkayan kimselere benzer. Allah kâfirleri çepeçevre kuşatandır."},{"n":20,"t":"Şimşek onların görme yeteneklerini nerede ise alıverecek. Çevrelerini aydınlatınca şimşeğin ışığı altında yürürler, fakat üzerlerine karanlık çökünce oldukları yerde kalakalırlar. Allah dileseydi, onların işitme ve görme yeteneklerini büsbütün giderirdi. Hiç kuşkusuz Allah her şeyi yapabilir."},{"n":21,"t":"Ey insanlar, sizi ve sizden öncekileri yaratmış olan Allah’a kulluk ediniz ki; Allah’ın azabından korunabilesiniz."},{"n":22,"t":"O ki, size yeri döşek, göğü tavan yaptı ve gökten su indirip onun aracılığı ile size rızık olarak topraktan çeşitli ürünler çıkardı. O halde O’na bile bile eşler koşmayınız."},{"n":23,"t":"Eğer kulumuz Muhammed’e indirdiğimiz Kur’ân’ın doğruluğundan şüpheli iseniz, haydi onunkilere benzer bir sure ortaya getiriniz ve davanızda sadık iseniz, bu hususta Allah’ın dışındaki şahitlerinizi yardıma çağırınız."},{"n":24,"t":"Eğer bunu yapamazsanız - ki asla yapamayacaksınız- yakıtı insanlar ile taşlar olan ve kâfirler için hazırlanmış olan Cehennem ateşinden korkunuz."},{"n":25,"t":"İman edip iyi ameller işleyenleri, ağaçları altından nehirler akan Cennetler ile müjdele. Onlara rızık olarak her yeni meyve sunulduğunda «Bu daha önce bize sunulan falanca meyvedir» derler, onlara birbirinden ayırd edemeyecekleri rızıklar verilir. Hem onlara orada el değmemiş, tertemiz eşler verilecektir. Onlar orada ebedi olarak kalacaklardır."},{"n":26,"t":"Onunla sadece fasıkları sapıklığa düşürür."},{"n":27,"t":"Onlar ki, Allah’a vermiş oldukları sözü kesin bir ahit haline getirdikten sonra bozarlar, Allah’ın sürdürülmesini emretmiş olduğu ilişkileri keserler ve yeryüzünde bozgunculuk çıkarırlar. İşte onlar hüsrana uğrayanlardır."},{"n":28,"t":"Allah’ı nasıl inkâr edersiniz ki, sizleri ölü iken o diriltti, sonra sizi öldürüp tekrar diriltecek, sonra da yine O’na döneceksiniz."},{"n":29,"t":"O ki, yeryüzünde bulunan bütün varlıkları sizin için yarattı. Sonra da göklere yönelerek onları yedi gök olarak düzenledi. O her şeyi bilir."},{"n":30,"t":"Hani Rabb’in, meleklere «Ben yeryüzünde bir halife yaratacağım» demişti. Melekler «Ya Rabbi sen yeryüzünde kargaşalık çıkaracak, kanlar dökecek birini mi yaratacaksın? Oysa biz seni överek tesbih ediyor, takdis ediyoruz» dediler. Allah meleklere «Ben sizin bilmediklerinizi bilirim’ dedi."},{"n":31,"t":"Allah, Adem’e bütün isimleri öğretti. Sonra bütün nesneleri meleklere göstererek, «Haydi, eğer davanızda haklı iseniz, bunların isimlerini bana söyleyin» dedi."},{"n":32,"t":"Melekler «Ya Rabbi, sen yücesin, bizim senin bize öğrettiklerin dışında hiçbir bilgimiz yoktur, hiç şüphesiz sen herşeyi bilirsin ve her yaptığın yerindedir» dediler."},{"n":33,"t":"Allah, Adem’e «Ey Adem, bunlara o nesnelerin adlarını bildir» dedi. Adem, meleklere bütün nesnelerin isimlerini bildirince Allah, onlara «Ben size, ’göklerin ve yerin bütün gizliliklerini, ayrıca sizin bütün açığa vurduklarınız ve içinizde sakladıklarınızı bilirim’ dememiş miydim?» dedi."},{"n":34,"t":"Hani biz meleklere «Adem’e secde ediniz» dedik de hemen secde ettiler. Yalnız iblis kaçındı, kendini büyük gördü ve kâfirlerden oldu."},{"n":35,"t":"Dedik ki; «Ey Adem, sen ve eşin Cennete yerleşiniz, oranın yiyeceklerinden istediğinizi bolbol yiyiniz, fakat şu ağaca yanaşmayınız, yoksa zalimlerden olursunuz.»"},{"n":36,"t":"Fakat Şeytan onların ayaklarını oradan kaydırarak, kendilerini içinde bulundukları nimet yurdundan çıkardı. Biz de dedik ki; «Birbirinize düşman olarak oradan aşağı inin. Yeryüzü belirli bir süreye kadar size barınak ve geçim yeri olacaktır.»"},{"n":37,"t":"Derken Adem, Rabbinden bir takım kelimeler belleyerek aldı da Rabbi onu affetti. Hiç şüphesiz O, tevbelerin kabul edicisidir ve merhametlidir."},{"n":38,"t":"Dedik ki; «Hepiniz oradan aşağı inin. Tarafımdan size bir yol gösterici geldiğinde kim benim hidayetime uyarsa onlar için korku yoktur ve onlar artık hiç üzülmezler.»"},{"n":39,"t":"Kâfir olup ayetlerimizi yalanlayanlar ise orada ebedi olarak kalıcı olmak üzere Cehennem’liktirler."},{"n":40,"t":"Ey İsrailoğulları, size bağışlamış olduğum nimetleri hatırlayın. Bana verdiğiniz sözü tutun ki, ben de size verdiğim sözü yerine getireyim. Ve sadece benden korkun."},{"n":41,"t":"Elinizin altındaki Tevrat’ı onaylayıcı olarak indirmiş olduğum Kur’an’a inanın; onu inkar edenlerin ilki olmayın; ayetlerimi bir kaç para karşılığında satmayın; yalnız benden çekinin."},{"n":42,"t":"Bile bile batılı hakkın üzerine örtüp hakkı bakışlardan gizlemeyin."},{"n":43,"t":"Namazı kılın, zekâtı verin ve rukûa varanlarla birlikte siz de rukûa’, varın."},{"n":44,"t":"Siz kitabı okuduğunuz halde insanlara (başkalarına) iyiliği emredip kendinizi unutuyor musunuz? Bunun yanlış olduğunu düşünemiyor musunuz?"},{"n":45,"t":"Sabrederek ve namaz kılarak Allah’dan yardım dileyin. Hiç şüphesiz bu, Allah’a saygı gösterenlerden başkasına ağır gelir."},{"n":46,"t":"Onlar ki, Rabbleri ile buluşacaklarını, kesinlikle O’nun huzuruna döneceklerini bilirler."},{"n":47,"t":"Ey İsrailoğulları, size bağışladığım nimetleri ve sizi diğer canlı- cansız varlıklara üstün kıldığımı hatırlayın."},{"n":48,"t":"Öyle bir günden korkun ki, o gün hiç kimse başkasının yerine bir şey ödeyemez, hiç kimseden aracılık kabul edilmez, hiç kimseden fidye alınmaz ve hiç kimse başkalarından yardım görmez."},{"n":49,"t":"Hani oğullarınızı boğazlayıp kadınlarınızı (dul) bırakmak suretiyle size çok ağır bir işkence çektiren Firavun hanedanından sizleri kurtarmıştık. Bu, sizin için Rabbinizden gelen çok büyük bir imtihandı."},{"n":50,"t":"Hani önünüze çıkan denizi yararak sizi (boğulmaktan) kurtarmış ve gözleriniz önünde Firavun ailesini boğmuştuk."},{"n":51,"t":"Hani Musa ile kırk geceliğine sözleşmiştik de siz onun arkasından buzağıyı ilâh edinerek zalimlerden olmuştunuz."},{"n":52,"t":"Sonra bu (suçunuz)un ardından belki şükredersiniz diye sizi affettik."},{"n":53,"t":"Hani doğru yola gelesiniz diye Musa’ya Kitab’ı ve Furkan’ı verdik."},{"n":54,"t":"Allah da tevbenizi kabul etti. Hiç şüphesiz O, tevbeleri kabul edendir ve merhametlidir."},{"n":55,"t":"Hani «Ey Musa, biz Allah’ı açıkça görmedikçe sana kesinlikle iman etmeyiz» dediniz de hemen arkasından bakıp dururken sizi yıldırım çarptı"},{"n":56,"t":"Sonra şükredesiniz diye sizi öldükten sonra yeniden dirilttik."},{"n":57,"t":"Size verdiğimiz rızıkların temiz olanlarından yiyin (diyerek)... Bize kötülük etmediler, fakat kötülük ettikleri yalnızca kendileriydi."},{"n":58,"t":"Hani «Şu kasabaya girin ve orada ne isterseniz bol bol yiyin, fakat kapıdan girerken secde ederek ’bizi bağışla’ deyin ki, günahlarınızı affedelim. İyilik edenlere daha fazlasını vereceğiz» dedik."},{"n":59,"t":"Fakat zalimler o sözü kendilerine söylenenden başka bir sözle değiştirdiler. Biz de yaptıkları bu kötülükten dolayı o zalimlere gökten ağır bir azap indirdik."},{"n":60,"t":"Hani Musa kavmi için su istedi de kendisine, «Elindeki değneği şu taşa vur» dedik. Bunun üzerine o taştan oniki tane pınar fışkırıvermişti. Her grubun hangi pınardan su içeceği belirlenmişti. «Allah’ın size bağışladığı rızıklardan yiyin, için ve yeryüzünde kargaşalık çıkararak azıtmayın» dedik."},{"n":61,"t":"\"Siz bayağı olan şeyle hayırlı olan şeyi değiştirmek mi istiyorsunuz? Öyle ise bir şehre inin. Sizin için istediğiniz şeyler vardır.\" demişti. Onların üstüne horluk ve yoksulluk vuruldu. Allah’tan bir gazaba da uğradılar. Bu, şüphesiz ki Allah’ın ayetlerini inkar ettiklerinden, peygamberlerini de haksız yere öldürdüklerinden idi. İşte bu ceza, isyan ettiklerinden, aşırı gittiklerinden dolayı idi."},{"n":62,"t":"Müminler ile yahudi, hıristiyan ve sabiilerden Allah’a ve Ahiret gününe inanıp iyi ameller işleyenler, hiç şüphesiz, Rabbleri katında mükâfatlarını alacaklardır; onlar için korku yoktur; onlar artık hiç üzülmeyeceklerdir."},{"n":63,"t":"Hani sizden kesin söz almış ve Tur dağını üstünüze çıkararak «size verdiğimizi kuvvetle tutun ve içindekileri hatırlayın ki, takva sahiplerinden olasınız» dedik."},{"n":64,"t":"Bunun arkasından verdiğiniz sözden döndünüz. Eğer Allah’ın üzerinizdeki fazlı ve merhameti olmasaydı kesinlikle hüsrana uğrayanlardan olurdunuz."},{"n":65,"t":"İçinizden Cumartesi yasağını çiğneyenleri bilmiş olmaktasınız. Onlara ’Aşağılık maymunlara dönün» dedik."},{"n":66,"t":"Bu cezayı, onu görenlere ve sonradan gelip işitenlere ibret ve takva sahiplerine öğüt yaptık."},{"n":67,"t":"«Cahillerden biri olmaktan Allah’a sığınırım» dedi."},{"n":68,"t":"«Rabbim ’o sığır ne yaşlı ve ne de körpe olup bu ikisi arasında orta yaşlıdır’ diyor, haydi size emredileni yapın» dedi."},{"n":69,"t":"«Rabbim, ’o sığır görenlerin gözüne hoş gelecek parlak sarı renktedir’ diyor.» dedi."},{"n":70,"t":"«Rabbine dua et de bu sığırı bize iyice tanımlasın. Biz sığırları birbirinden ayırdedemez olduk. Allah dilerse bu karışıklığın içinden çıkarız» dediler."},{"n":71,"t":"«Rabbim, ’o, boyunduruğa koşulup toprak sürmemiş, toprak sulamada kullanılmamış, özürsüz ve alacasız bir sığırdır’ diyor» dedi. Bunun üzerine onlar «İşte şimdi hakkı ile anlattın» diyerek tanımlanan sığırı kestiler, neredeyse bunu yapmayacaklardı."},{"n":72,"t":"Hani bir adam öldürmüştünüz de bu suçu birbirinize atmaya kalkmıştınız. Oysa Allah gizlediğinizi ortaya çıkaracaktı."},{"n":73,"t":"Bu amaçla «Kesilen sığırın bir parçasını o öldürülen adamın cesedine değdirin» dedik. İşte Allah böylece ölüleri diriltir ve düşünesiniz diye size ayetlerini gösterir."},{"n":74,"t":"Bütün bu olaylardan sonra kalpleriniz yine katılaştı. Şimdi onlar taş gibi, hatta taştan bile daha katıdırlar. Çünkü öyle taşlar var ki, içlerinden ırmaklar akar. Yine öyle taşlar var ki, çatlarlar da bağırlarından su fışkırır. Yine öyle taşlar var ki, Allah korkusu ile dağlardan yuvarlanıp aşağı inerler. Allah yaptıklarınızdan asla habersiz değildir."},{"n":75,"t":"Şimdi siz onların size inanacaklarını mı umuyorsunuz? Oysa onlar arasında öyle bir grup var ki, Allah’ın kelâmını işitirler ve anlamına akılları yattıktan sonra, onu bile bile değiştirirlerdi."},{"n":76,"t":"Onlar müminler ile karşılaştıklarında «inandık» derler. Fakat birbirleri ile başbaşa kaldıkları zaman «Rabbiniz katında aleyhinize delil olarak kullansınlar diye mi Allah’ın size açıkladıklarını onlara anlatıyorsunuz? Bunun yanlış olduğuna aklınız ermiyor mu?» derler."},{"n":77,"t":"Acaba onlar bilmiyorlar mı ki, Allah onların gizli tuttukları ve açığa vurdukları herşeyi bilir."},{"n":78,"t":"Onların içinde bir de ümmiler (okuma- yazma bilmeyenler) vardır ki, bunlar kitabı bilmezler. Bütün bildikleri birtakım asılsız kuruntulardır. Onlar sırf zanlara (saplantılara) kapılmışlardır."},{"n":79,"t":"Kendi elleri ile kitabı yazdıktan sonra karşılığında birkaç para elde etmek amacı ile, «Bu, Allah katından geldi» diyenlerin vay haline! Ellerinin yazdığından ötürü vay başlarına geleceklere! (Yine) Kazandıkları paradan ötürü vay başlarına geleceklere!.."},{"n":80,"t":"Sayılı günlerden başka katiyyen bize ateş dokunmayacak dediler. De ki; ’Allah’tan bu yönde söz mü aldınız - ki Allah asla sözünden caymaz- yoksa Allah hakkında bilmediğiniz bir şeyi mi söylüyorsunuz?"},{"n":81,"t":"Hayır, öyle birşey yok. Kim kötülük işler de günahı tarafından kuşatılırsa onlar ebedi olarak kalmak üzere Cehennemliktirler."},{"n":82,"t":"İman edip iyi ameller işleyenler de orada ebedi olarak kalmak üzere Cennetliktirler."},{"n":83,"t":"Hani biz İsrailoğullarından ’Allah’dan başka bir şeye tapmayınız, ana- babaya, akrabalara yetimlere ve yoksullara iyilik ediniz, namazı kılınız, zekâtı veriniz» diye söz almıştık. Fakat sonra küçük bir azınlık dışında bu sözünüzden döndünüz. Hâlâ da bu dönekliği sürdürüyorsunuz."},{"n":84,"t":"Hani birbirinizin kanını dökmeyeceksiniz, birbirinizi yurtlarınızdan sürmeyeceksiniz diye de sizden söz almıştık. Kendi tanıklığınızla bunu kabul etmiştiniz."},{"n":85,"t":"Buna rağmen biribirinizi öldürüyor ve içinizden bazılarını yurtlarından sürüyor, onlara karşı günah ve zulüm işlemek için aranızda işbirliği yapıyorsunuz. Onları sürgüne göndermeniz yasaklandığı halde sürgüne gönderiyorsunuz, sonra size esir olarak geldikleri taktirde fidye vererek kendilerini kurtarıyorsunuz. Yoksa siz kitabın bir kısmına inanıp bir kısmını inkâr mı ediyorsunuz? Oysa içinizden böyle yapanların cezası dünya hayatında perişanlıktan başka birşey değildir. Onlar Kıyamet günü de en ağır azaba çarpılacaklardır. Allah yaptıklarınızdan habersiz değildir."},{"n":86,"t":"Bunlar Ahiret karşılığında dünya hayatını satın almış kimselerdir. Bu yüzden onların ne azabı hafifletilecek ve ne de kendilerine yardım edilecektir."},{"n":87,"t":"Andolsun ki biz Musa’ya kitap verdik. Ondan sonra da birbiri ardınca peygamberler gönderdik. Meryem oğlu İsa’ya da beyyineler verdik. Ve onu Ruh-ul-Kudüs ile te’yid ettik. Demek bir peygamber ne vakit size gönüllerinizin hoşlanmadığı bir şeyi getirirse, kibirlenmek isteyeceksiniz de kiminiz tekzip edecek, kiminiz de öldüreceksiniz öyle mi?.."},{"n":88,"t":"Yahudiler; «Kalplerimiz kılıflıdır» dediler. Hayır, yalnız kâfir olduklarından dolayı Allah onları lânetledi. Onların pek azı iman eder."},{"n":89,"t":"Onlara Allah katından elleri altındaki Tevrat’ı onaylayan bir kitap (Kur’an) gelince - ki, daha önce kâfirlere karşı zafer kazanmak istedikleri halde ötedenberi bilip durdukları bu kitap kendilerine gelince- onu inkâr ettiler. Allah’ın lâneti kâfirlerin üzerinedir."},{"n":90,"t":"Onlar Allah’ın kendi bağışı olarak dilediği kuluna vahiy indirmesini çekemeyerek O’nun indirdiği kitabı inkâr etmekle benliklerini ne kötü şey karşılığında sattılar da katmerli gazaba uğradılar! Kâfirleri alçaltıcı bir azap beklemektedir."},{"n":91,"t":"Onlara ’Allah’ın indirdiğine inanın» denildiği zaman; «Biz sadece bize indirilene inanırız» derler ve ellerindeki Tevrat’ı doğrulayıcı hakk bir kitap olduğu halde Tevrat’tan başkasına inanmazlar. Onlara de ki; «Madem ki, inanıyordunuz daha önce Allah’ın peygamberini niye öldürdünüz?"},{"n":92,"t":"Musa size mucizeler ile geldi. Siz ise onun yokluğunda buzağıya taptınız. Sizler öyle zalimlersiniz!"},{"n":93,"t":"Hani sizden kesin söz almıştık; Tur’u üzerinize kaldırarak «Size verdiğimizi kuvvetle tutun ve dinleyin» dedik. Onlar ise «Dinledik ve karşı geldik» dediler. Kâfirlikleri yüzünden buzağı sevgisi kalplerine iyice işledi. De ki; «Eğer inanıyor idiyseniz, imanınız size ne kötü işler emrediyor!"},{"n":94,"t":"De ki; «Eğer iddia ettiğiniz gibi Allah katında Ahiret yurdu başka hiç kimsenin değil de sırf sizin ise o halde iddianızda samimi iseniz ölümü temenni edin.»"},{"n":95,"t":"Oysa onlar kendi elleri ile işlemiş oldukları kötülüklerden dolayı ölümü kesinlikle istemezler. Hiç şüphesiz, Allah zalimleri bilir."},{"n":96,"t":"Onları, insanların hayata en düşkünü, puta tapanlardan bile daha tutkunu olarak bulacaksın. Her biri ister ki, bin yıl yaşatılsın. Oysa uzun yaşamak kendilerini azaptan kurtaracak değildir. Hiç şüphesiz, Allah onların yaptıklarını görüyor."},{"n":97,"t":"De ki; «Kim Cebrail’e düşman olursa - ki O Allah’ın izni ile Kur’an’ı, O’na inanmayanın elleri arasındaki Tevrat’ı onaylayıcı, müminlere yol gösterici ve müjde kaynağı olarak senin kalbine indirdi:"},{"n":98,"t":"Evet, kim Allah’a, O’nun meleklerine, O’nun peygamberlerine, Cebrail’e ve Mikâil’e düşman olursa bilsin ki, Allah da kâfirlerin düşmanıdır."},{"n":99,"t":"Biz sana öyle gerçekler, açıklayıcı ayetler indirdik ki, onları sadece fasıklar inkâr eder."},{"n":100,"t":"Onlar ne zaman bir ahit yaptılar ise aralarından bir grup onu bozup bir yana atmadı mı? Aslında onların çoğu inanmaz."},{"n":101,"t":"Onlara Allah katından önlerindeki kitabı onaylayan bir peygamber gelince, kendilerine kitap verilenlerin bir grubu, Allah’ın kitabını hiç bilmiyorlarmış gibi onu arkalarına attılar."},{"n":102,"t":"\"Biz ancak fitneyiz, sakın küfretme.\" demedikçe kimseye sihir namına bir şey öğretmezlerdi. Onlardan koca ile karısının arasını ayıracak şeyler öğrendiler. Halbuki bunlar, Allah’ın izni olmadıkça o sihirle kimseye zarar verici değildiler. Onlarsa kendilerine zarar verip fayda vermeyen şeyleri öğreniyorlardı. Andolsun ki onlar sihri satın alan kimse için ahirette hiçbir nasip olmayacağını biliyorlardı. Ne fena bir şey karşılığında nefislerini sattılar. Şayet bilmiş olsalardı?"},{"n":103,"t":"Eğer onlar iman edip Allah’ın yasaklarından sakınsalardı, Allah katında elde edecekleri sevap daha hayırlı idi. Keşke bunu bilselerdi."},{"n":104,"t":"Ey müminler, sakın Peygambere; «Bizi de dinle» demeyin; «Bize bak» deyin ve onu dinleyin. Kâfirleri acı bir azap beklemektedir."},{"n":105,"t":"Ne Kitap Ehlinin kâfirleri ve ne de puta tapanlar Rabbinizden size herhangi bir iyilik inmesini istemezler. Oysa Allah rahmetini dilediğine tahsis eder. Allah büyük lütuf sahibidir."},{"n":106,"t":"Biz herhangi bir ayetin daha hayırlısını veya benzerini getirmedikçe onu ne yürürlükten kaldırır ve ne de unuttururuz. Allah’ın herşeye kadir olduğunu bilmiyor musun?"},{"n":107,"t":"Göklerin ve yeryüzünün egemenliğinin Allah’a ait olduğunu bilmiyor musun? Allah’tan başka hiçbir dostunuz ve destekçiniz yoktur."},{"n":108,"t":"Yoksa vaktiyle Musa’yı sorguya tuttukları gibi siz de peygamberinizi sorguya tutmak mı istiyorsunuz? Müminliği kâfirlik ile değiştirenler hiç kuşkusuz doğru yoldan sapmış olurlar."},{"n":109,"t":"Kitap Ehlinin çoğu gerçeğin ne olduğunu kesinlikle öğrendikten sonra sırf içlerindeki kıskançlıktan ötürü sizi iman ettikten sonra tekrar kâfirliğe döndürmek isterler. Allah’ın emri gelinceye kadar onlara aldırış etmeyin, yaptıklarını hoş görün. Hiç kuşkusuz Allah herşeye kadirdir."},{"n":110,"t":"Namazı kılın, zekâtı verin, kendi hesabınıza önceden gönderdiğiniz her iyiliği Allah katında bulursunuz. Hiç şüphesiz Allah yaptıklarınızı görür."},{"n":111,"t":"Onlar «Yahudilerden ve hıristiyanlardan başka hiç kimse Cennet’e giremeyecek» dediler. Bu onların hüsnükuruntusudur. De ki; «Eğer dediğiniz gibi ise delilinizi getirin.»"},{"n":112,"t":"Hayır, öyle değil Kim kendini Allah’a adar ve bunun yanında iyi ameller de işlerse Allah katında mutlaka mükâfatını alır. Böyleleri için korku sözkonusu değildir, onlar hiç üzülmeyeceklerdir."},{"n":113,"t":"«Hıristiyanlar hiçbir gerçeğe dayanmıyor» dediler. Hıristiyanlar da; «Yahudiler hiçbir gerçeğe dayanmıyor» dediler. Oysa hepsi de kitabı okuyorlar. Gerçeği bilmeyenler de onların dediğini söylemişlerdi. Kıyamet günü Allah, anlaşmazlığa düştükleri konularda aralarında hüküm verir."},{"n":114,"t":"Allah’ın mescidlerinde O’nun adının anılmasını engelleyen ve oraları yıkmaya çalışanlardan daha zalim kim olabilir? Oysa oralara ancak korkulu bir saygı içinde girmeleri yakışık alır. Bunları, dünyada rezil olmak, Ahirette de büyük bir azap beklemektedir."},{"n":115,"t":"Doğu da Batı da Allah’ındır. Ne tarafa dönerseniz, Allah’ın yönü o tarafa doğrudur. Şüphesiz Allah’ın kudreti herşeyi kapsar ve o herşeyi bilir."},{"n":116,"t":"Onlar; «Allah oğul edindi» dediler. O böyle bir şeyden münezzehtir. Göklerdeki ve yeryüzündeki varlıkların tümü O’nundur, hepsi O’na boyun eğmişlerdir."},{"n":117,"t":"O, göklerin ve yeryüzünün yoktan varedicisidir. O birşeyin varolmasını dileyince ona sadece «ol» der ve o da olur."},{"n":118,"t":"Bilmeyenler «Allah bizimle konuşmalı ya da bize bir mucize gelmeliydi» dediler. Onlardan öncekiler de onların dedikleri gibi söylemişlerdi. Kalpleri birbirine benzedi. Kesin iman sahiplerine ayetleri apaçık göstermişizdir."},{"n":119,"t":"Ey Muhammed! Doğrusu biz seni Kur’ân’la dosdoğru bir müjdeleyici ve uyarıcı olarak gönderdik. Sen cehennemliklerden sorumlu değilsin."},{"n":120,"t":"Eğer sana gelen bilgiden sonra onların arzularına uyacak olursan, andolsun ki, Allah tarafından ne bir dost ve ne de bir yardımcı bulamazsın."},{"n":121,"t":"Kendilerine verdiğimiz kitabı gereğince okuyanlar var ya, işte onlar ona inananlardır. Onu inkâr edenler ise hüsrana uğrayanlardır."},{"n":122,"t":"Ey İsrailoğulları, size vermiş olduğum nimetleri ve sizi bir zamanlar bütün alemlere üstün tutmuş olduğumu hatırlayın."},{"n":123,"t":"Hiç kimsenin başkası adına birşey ödeyemeyeceği, hiç kimseden fidye kabul edilmeyeceği, hiç kimseye şefaatin yarar sağlayamayacağı ve böylelerinin hiçbir yerden yardım görmeyeceği günden korkun."},{"n":124,"t":"Hani Rabbi, İbrahim’i birtakım emirler ile denemiş, o da onları yerine getirmişti. Bunun üzerine Allah; «Seni insanlara önder yapacağım» demişti. İbrahim; «Soyumdan da» deyince, Allah; «Zalimler bu taahhüdümün kapsamına asla giremezler» buyurdu."},{"n":125,"t":"Hani Kâbe’yi insanlar için toplanma ve güven yeri yapmıştık. «İbrahim’in makamını (Kâbe’nin tümünü) namaz yeri edininiz» İbrahim ile İsmail’e; «Bu evimi ziyaretçiler, kendilerini ibadete adayanlar, rüku ve secde edenler için temiz tutun» diye emir vermiştik."},{"n":126,"t":"Hani İbrahim; «Ey Rabbim, bu şehri güvenli bir yer kıl, halkından Allah a ve Ahiret gününe inananları çeşitli ürünlerle rızıklandır» dedi. Allah da; «Onlardan kâfir olanları ise kısa bir süre geçindirir, sonra Cehennem azabına katlanmak zorunda tutarım. Ne kötü akıbettir o!» buyurdu."},{"n":127,"t":"Hani İbrahim ile İsmail, Kâbe’nin duvarlarını yükseltirlerken söyle dua etmişlerdi; «Ey Rabbimiz, yaptığımızı kabul et hiç şüphesiz sen herşeyi işiten ve bilensin."},{"n":128,"t":"Ey Rabbimiz, ikimizi de sana teslim olanlardan eyle, soyumuzdan da sana teslim olan bir ümmet çıkar, bize ibadet yollarımızı göster, tevbemizi kabul buyur. Hiç şüphesiz sen tevbeleri kabul edensin ve çok merhametlisin."},{"n":129,"t":"Ey Rabbimiz, içlerinden onlara senin ayetlerini okuyacak, Kitab’ı ve hikmeti öğretecek, kendilerini kötülüklerden arıtacak bir peygamber gönder. Hiç şüphesiz sen azizsin ve hikmet sahibisin.»"},{"n":130,"t":"Benliğini aşağılığa mahkûm edenler dışında İbrahim’in dininden kim yüz çevirir. Andolsun ki, biz onu dünyada seçkinlerden kıldık. O Ahirette de salihler arasındadır."},{"n":131,"t":"Hani Rabbi ona; «Teslim ol» buyurunca o da; «Ben alemlerin Rabbine teslim oldum» dedi."},{"n":132,"t":"İbrahim (bu ilâhî buyruğu) oğullarına tavsiye etti. Yakub da; «Ey oğullarım, Allah sizin için bu dini seçti, mutlaka müslüman olarak ölünüz» dedi."},{"n":133,"t":"Yoksa siz Yakub ölmek üzereyken yanında mıydınız? Hani O oğullarına; «Benden sonra kime kulluk edeceksiniz (kime tapacaksınız?)» diye sordu. Onlar da; «Senin ve ataların İbrahim’in, İsmail’in ve İshak’ın ilâhı olan tek Allah’a kulluk edeceğiz; biz O’na teslim olmuşuz» dediler."},{"n":134,"t":"Onlar gelip geçmiş bir ümmettir. Onların kazandıkları kendilerine, sizin kazandığınız da sizedir. Siz onların yaptıklarından sorumlu tutulmazsınız."},{"n":135,"t":"Onlar size; «Yahudi veya hıristiyan olun ki, doğru yolu bulasınız» dediler. Onlara de ki; «Hayır, biz İbrahim’in dosdoğru dinine uyarız. O müşriklerden değildi.»"},{"n":136,"t":"Onlara deyin ki; «Biz Allah’a, bize indirilene, İbrahim’e, İsmail’e, İshak’a, Yakub’a ve torunlarına indirilene; Musa’ya ve İsa’ya verilene ve diğer peygamberlere Rabbleri tarafından verilene inanırız. Onlar arasında ayırım yapmayız. Biz Allah’a teslim olanlarız.»"},{"n":137,"t":"Eğer onlar sizin inandıklarınızın aynısına inanırlarsa doğru yolu bulmuş olurlar. Eğer bu inanca arka dönerlerse mutlaka çatışmaya ve çıkmaza düşerler. Onlara karşı Allah sana yetecektir. O işitendir ve bilendir."},{"n":138,"t":"Bu din, Allah’ın verdiği bir renktir. Kim Allah’tan daha iyi bir renk verebilir? Biz yalnız O’na kulluk ederiz."},{"n":139,"t":"De ki; «Bizim de sizin de Rabbiniz olan Allah hakkında bizimle çekişiyor musunuz? Bizim yaptıklarımız bize, sizin yaptıklarınız da size aittir. Biz O’na samimi olarak bağlıyız."},{"n":140,"t":"Yoksa İbrahim’in, İsmail’in, İshak’ın, Yakub’un ve torunlarının yahudi ya da hıristiyan olduklarını mı söylüyorsunuz? De ki; «Siz mi daha iyi bilirsiniz, yoksa Allah mı?» Allah tarafından kendisine bildirilen bir gerçeği saklayandan daha zalim kim olabilir? Allah yaptıklarınızdan asla gafil değildir."},{"n":141,"t":"Onlar daha önce gelip geçmiş bir ümmettir. Onların kazandıkları kendilerine, sizin kazandıklarınız da sizedir. Siz onların yaptıklarından sorumlu tutulmazsınız"},{"n":142,"t":"İnsanlardan bazı beyinsizler; «Onları daha önce yöneldikleri kıbleden çeviren sebep nedir?» diyecekler. De ki; «Doğu da Batı da Allah’ındır. O dilediğini doğru yola iletir.»"},{"n":143,"t":"Böylece sizi orta yolu benimseyen bir ümmet yaptık ki, siz insanlara örnek olasınız ve peygamber de size örnek olsun. Biz sırf Peygambere uyanları, bağlı kalanları O’na uymaktan vazgeçenlerden ayırdedelim diye daha önce yöneldiğin kıbleyi tekrar kıble yaptık. Bu değişiklik, Allah’ın doğru yolu gösterdiği kimselerden başkasına elbette ağır gelir. Allah sizin imanınızı boşa çıkaracak değildir. Hiç şüphesiz, Allah insanlara karşı şefkatli ve merhametlidir."},{"n":144,"t":"(Ey Muhammed) senin yüzünü ısrarla göğe çevirdiğini görüyoruz. Seni hoşuna gidecek bir kıbleye kesinlikle döndüreceğiz. Bundan böyle yüzünü Mescid- i Haram tarafına çevir. Nerede olursanız olun, yüzlerinizi o tarafa çevirin. Hiç şüphesiz kendilerine kitap verilenler, bu kıble değişiminin Rabblerinin buyruğuna dayanan bir gerçek olduğunu biliyorlar. Allah onların neler yaptıklarından habersiz değildir."},{"n":145,"t":"Kendilerine kitap verilenlere sen her türlü ayeti (delili) göstersen bile onlar yine senin kıblene uymazlar. Sen de onların kıblesine uyacak değilsin. Onlar birbirlerinin kıblelerine de uymazlar. Sana gelen bilgiden sonra eğer onların keyiflerine, arzularına uyacak olursan, o zaman, kesinlikle zalimlerden olursun."},{"n":146,"t":"Kendilerine kitap verdiklerimiz O’nu (Muhammed’i) oğullarını tanıdıkları gibi tanırlar. Fakat onlardan bir grup, bile bile gerçeği gizler."},{"n":147,"t":"Bu, Rabbinden gelen bir gerçektir. Bu konuda sakın kuşkuya kapılanlardan olma."},{"n":148,"t":"Herkesin yöneldiği bir yön vardır. Buna göre, hayırlı işlerde birbirinizle yarışa girin. Nerede olursanız olun, Allah sizi bir yere getirecek (toplayacak)tır. Hiç şüphesiz, Allah herşeye kadirdir."},{"n":149,"t":"Nereden yola çıkmış olursan ol, yüzünü Mescid- i Haram’a doğru çevir. Bu kesinlikle Rabbinden gelen bir gerçektir. Hiç şüphesiz, Allah neler yaptığınızdan habersiz değildir."},{"n":150,"t":"Nereden yola çıkmış olursan ol, yüzünü Mescid- i Haram’a doğru çevir. Nerede olursanız olun, yüzünüzü o tarafa çevirin ki, insanların elinde aleyhinizde kullanacakları bir bahane bulunmasın. Yalnız, zalimler başka. Onlardan da korkmayın, benden korkun. O tarafa dönün ki, size vereceğim nimeti tamama erdireyim ve böylece doğru yolu bulasınız."},{"n":151,"t":"Nitekim kendi içinizden size ayetlerimizi okuyan, sizi kötülüklerden arındıran, size Kitab’ı, hikmeti ve daha önce bilmediğiniz birçok şeyi öğreten bir peygamber gönderdik."},{"n":152,"t":"O halde siz beni hatırlayın ki, ben de sizi hatırlayayım. Bana şükredin, sakın nankörlük etmeyin."},{"n":153,"t":"Ey müminler, sabırla ve namazla Allah’tan yardım isteyin. Hiç şüphesiz Allah, sabredenler ile beraberdir."},{"n":154,"t":"Allah yolunda öldürülenlere sakın «ölüler» demeyin. Tersine onlar diridirler, ama siz farkında değilsiniz."},{"n":155,"t":"Muhakkak ki, sizi biraz korku, biraz açlık, biraz mal, cari ve ürün eksiltmesi ile deneriz. Sabredenleri müjdele."},{"n":156,"t":"Ki onların başlarına bir musibet geldiğinde; «Biz Allah için varız ve yine O’na döneceğiz» derler."},{"n":157,"t":"İşte Rabblerinden mağfiret (salâvat) ve rahmet onların üzerinedir ve doğru yolu bulanlar da onlardır."},{"n":158,"t":"Hiç şüphesiz Safa ile Merve, Allah’a ibadet sembollerindendir. Buna göre, kim Hacc veya Umre amacı ile Kâbe’yi ziyaret ederse, bu iki tepeyi tavaf etmesinde hiçbir sakınca yoktur. Kim gönüllü olarak bir iyilik yaparsa, bilsin ki, Allah karşılığını verir ve yaptığını bilir."},{"n":159,"t":"İndirdiğimiz belgeleri, biz onları Kitapta açıkladıktan sonra gizleyenler var ya, onlara hem Allah hem de bütün lânet edebilenler lânet eder."},{"n":160,"t":"Yalnız tevbe edenler, ıslâh olanlar ve gerçeği ortaya koyanlar müstesna; onları ben bağışlarım. Zira ben tevbeleri kabul ederim ve merhametliyim."},{"n":161,"t":"Ayetlerimizi inkâr etmiş ve kâfir olarak ölmüş olanlara gelince Allah’ın, meleklerin ve insanların ortak lâneti onların üzerinedir."},{"n":162,"t":"Bunlar (sürekli lânetlenmiş olarak) orada ebediyen kalırlar. Ne azapları hafifletilir ve ne de kendilerine mühlet verilir."},{"n":163,"t":"İlahınız tek bir ilahtır, O’ndan başka ilah yoktur. O, Rahman ve Rahim’dir."},{"n":164,"t":"Hiç şüphesiz göklerin ve yerin yaratılışında, gece ile gündüzün birbirini kovalamasında, insanlara yararlı şeyler ile denizde yüzen vapurlarda, Allah’ın gökten su indirip onun aracılığı ile ölü yeri dirilterek üzerine her çeşit canlıyı yaymasında, rüzgârları ve gökle yer arasında emre hazır bekleyen bulutları yönlendirmesinde, düşünen bir topluluk için birçok ayetler, deliller vardır."},{"n":165,"t":"İnsanlar arasında Allah’a çeşitli eşler koşanlar ve bu koştukları eşleri Allah’ı sever gibi sevenler vardır. Oysa müminler en çok Allah’ı severler. Zulmedenler, azabı gördükleri zaman bütün kuvvetin Allah’ta olduğunu ve Allah’ın azabının ağır olduğunu anlayacaklarını keşke şimdiden bilselerdi!"},{"n":166,"t":"İşte uyulanlar (liderler), kendilerine uyanlardan uzaklaşıverdiler, azabı gördüler ve aralarındaki bütün bağlar kesildi."},{"n":167,"t":"Uyanlar o zaman «Keşke bir daha dünyaya geri dönebilseydik de şimdi onlar bizden nasıl uzaklaştılar ise bizde onlardan öyle uzak dursaydık» derler. Böylece Allah, onlara bütün yaptıklarını hayıflanmalar biçiminde gösterir. Onlar Cehennem’den çıkamayacaklardır."},{"n":168,"t":"Ey insanlar, yeryüzünde bulunan şeylerin temiz ve helâl olanlarından yiyin; sakın Şeytan’a ayak uydurmayın, onun izinden gitmeyin. Çünkü o sizin açık düşmanınızdır."},{"n":169,"t":"O size her zaman kötülük ve çirkin davranışlar yapmanızı ve Allah hakkında bilmediğiniz şeyi uydurmanızı emreder."},{"n":170,"t":"Onlara; «Allah’ın indirdiklerine uyun» denilince; «Hayır, biz atalarımızdan gördüklerimize uyarız» derler. - Peki, ya onların ataları hiçbir şeyi düşünemeyen, doğru yolu bulamamış kimseler idiyse de mi öyle yapacaklar?"},{"n":171,"t":"Küfredenlerin misali; bağırıp çağırmadan başka bir şey duymayan, haykırıp duranınki gibidir. Onlar sağırdırlar, dilsizdirler, kördürler; düşünemezler."},{"n":172,"t":"Ey müminler, size verdiğimiz rızıkların tertemiz (helâl) olanlarından yiyin ve eğer gerçekten sırf Allah’a kulluk ediyorsanız, O’na şükredin."},{"n":173,"t":"Allah size sadece leşi, kanı, domuz etini ve Allah’tan başkası adına kesilen hayvanın etini kesinlikle haram kıldı. Fakat darda kalana, başkasının payına el uzatmamak ve zaruret miktarını aşmamak üzere bu etlerden yemek günah değildir. Hiç şüphesiz, Allah bağışlayıcı ve merhametlidir."},{"n":174,"t":"Allah’ın indirdiği kitapta bulunan birşeyi gizleyerek onu birkaç para karşılığında satanlar var ya, onlar karınlarına ateşten başka birşey indirmiyorlar. Allah Kıyamet günü onlarla konuşmaz ve kendilerini günahlardan arındırmaz. Onları acı bir azap beklemektedir."},{"n":175,"t":"Onlar hidayet karşılığında sapıklığı, mağfiret karşılığında azabı satın alanlardır. Onlar Cehennem ateşine karşı ne kadar da dayanıklıdırlar!"},{"n":176,"t":"Allah, kitabı hak içerikli olarak indirdi ve bu kitap üzerinde görüş ayrılığına düşenler gerçekten derin bir anlaşmazlık, uyuşmazlık içindedirler."},{"n":177,"t":"Yüzlerinizi Doğu ya da Batı tarafına çevirmeniz iyilik demek değildir. Asıl iyilik Allah’a, Ahiret gününe, meleklere, kitaba, peygamberlere inanan; akrabalara, yetimlere, yoksullara, yarı yolda kalanlara, dilencilere ve boyunduruk altında bulunanlara (kölelere, tutsaklara) mallarını sevmelerine rağmen yardım edenlerin; namazı kılanların, zekâtı verenlerin, antlaşma yaptıklarında yapmış oldukları antlaşmaları yerine getirenlerin; zorda, darda ve savaş zamanında sabredenlerin tutumudur. İşte doğrular (sözlerinin erleri) onlardır, takva sahipleri de onlardır."},{"n":178,"t":"Ey iman edenler! Maktüller hakkında size kısas farz edildi. Hür hür ile, köle köle ile, dişi dişi ile, fakat kimin lehine maktulün kardeşi tarafından bir şey affedilirse, ma’ruf olan emre ittiba etmeli, ona güzellikle (diyet) ödemelidir. Bu Rabb’ınız tarafından bir hafifletme ve rahmettir. Artık bundan sonra kim haddi tecavüz ederse; onun için pek acıklı bir azap vardır."},{"n":179,"t":"Ey akıl sahipleri, sizin için kısasta hayat vardır. Bu sayede adam öldürmekten sakınırsınız"},{"n":180,"t":"İçinizden biri ölmek üzereyken eğer geride mal (hayır) bırakıyorsa anaya, babaya ve yakın akrabalara geleneklere uygun biçimde vasiyyette bulunması, Allah’tan korkanlar üzerine bir borçtur."},{"n":181,"t":"Kim bu vasiyyeti, işittikten sonra değiştirirse, günahı onu değiştirenin boynunadır. Hiç şüphesiz; Allah işitendir, bilendir."},{"n":182,"t":"Kim vasiyyet edenin yanılgıya düştüğünden ya da günaha gireceğinden endişe ederek ilgililerin arasını bulursa bu yüzden günaha girmez. Hiç şüphesiz Allah bağışlayıcı ve merhametlidir."},{"n":183,"t":"Ey müminler, sizden önceki ümmetlere olduğu gibi, günahlardan arınasınız diye, sayılı günler olarak oruç tutmak size de farz kılındı."},{"n":184,"t":"İçinizden kim hasta ya da yolcu olursa tutmadığı günler sayısınca sonraki günlerde oruç tutar. Oruca dayanamayanların bir yoksulu doyuracak kadar fidye vermeleri gerekir. Kim gönüllü olarak bundan daha fazlasını verirse, bu onun için daha hayırlıdır. Ayrıca, eğer bilirseniz, oruç tutmanız sizin için daha hayırlıdır."},{"n":185,"t":"Ramazan ayı ki, o ayda Kur’an, insanlara yol gösterici, doğru yola iletici, eğri ile doğruyu birbirinden ayırt edici olarak indirildi. İçinizden kim bu aya yetişirse onu oruçla geçirsin. Kim hasta ya da yolcu olursa tutamadığı günler sayısınca sonraki günlerde oruç tutsun. Allah sizin için kolaylık ister, zorluk istemez. Bu sayılı günleri tamamlamanızı ve size doğru yolu gösterdi diye kendisini tekbir etmenizi (ululuğunu dile getirmenizi) ister, ola ki, O’na şükredersiniz."},{"n":186,"t":"Eğer kullarım sana benden sorarlarsa onlara de ki; ben kendilerine yakınım, bana dua edenin duasını, dua edince, kabul ederim. O halde onlar da benim çağrıma olumlu karşılık vererek bana iman etsinler ki, doğru yolu bulsunlar."},{"n":187,"t":"Sizin için oruç gecesi kadınlarınıza yaklaşmak helal kılındı. Onlar sizin için, siz de onlar için bir libassınız. Sizin nefislerinize hıyanet edeceğinizi Allah bildi de, tevbenizi kabul etti ve sizi bağışladı. Artık onlara yaklaşın. Ve Allah’ın hakkınızda yazdığını isteyin. Ve fecrin beyaz ipliği siyah ipliğinden seçilinceye kadar yiyin, için. Sonra geceye kadar orucu tamamlayın. Mescidlerde i’tikafta bulunduğunuz zaman kadınlarınıza yaklaşmayın. Bu, Allah’ın hudududur. Sakın onlara yaklaşmayın. İşte Allah ayetlerini insanlara böylece açıklar. Ta ki onlar korunsunlar."},{"n":188,"t":"Birbirinizin mallarını haksız yollardan yemeyin. İnsanların bir kısım mallarını günah olacak biçimde bile bile yemek için hakimlere peşkeş çekmeyin."},{"n":189,"t":"Ey Muhammed, sana hilâl aşamasındaki aylar hakkında soru soruyorlar. De ki; «Onlar insanlar ve Hacc için zaman ölçüsüdürler.» Evlere arka taraflarından girmeniz iyiliğe uygun bir davranış değildir. İyiliğe uygun davranış, kötülükten sakınarak evlere kapılarından girenlerin tutumudur. Allah’tan korkunuz ki, kurtuluşa, umduğunuza eresiniz."},{"n":190,"t":"Sizinle savaşanlar ile siz de Allah yolunda savaşın. Fakat ölçüyü kaçırmayın, saldırgan olmayın. Çünkü Allah ölçüyü elden bırakan saldırganları sevmez."},{"n":191,"t":"Onları bulduğunuz yerde öldürün. Sizi çıkardıkları, sürdükleri yerden siz de onları çıkarın. Kargaşa çıkarmak, adam öldürmekten daha ağır bir suçtur. Mescid- i Haram çevresinde onlarla savaşmayın ki, onlar da orada size karşı savaşmasınlar. Fakat eğer onlar size savaş açarlarsa onları öldürün. Kâfirlerin cezası böyledir."},{"n":192,"t":"Eğer onlar savaşmaya ve kâfirliğe son verirlerse Allah bağışlayıcıdır, merhametlidir."},{"n":193,"t":"Fitne ortadan kalkıp Allah’ın dini tam anlamı ile egemen oluncaya kadar onlarla savaşın. Eğer yaptıklarına son verirlerse zalimlerden başkasına asla saldırılmaz."},{"n":194,"t":"Haram ay, haram aya karşılıktır. Yasaklar, dokunulmazlıklar karşılıklıdır. Buna göre size saldırana, size saldırdığı kadar, siz de saldırın. Allah’tan korkun ve iyi bilin ki, Allah kendisinden korkanlarla beraberdir."},{"n":195,"t":"(Mallarınızın bir bölümünü) Allah yolunda harcayın. Sakın kendinizi, kendi ellerinizle tehlikeye atmayın. Hiç kuşkusuz Allah iyilik yapanları sever."},{"n":196,"t":"Allah için haccı da, umreyi de tamamen yapın. Fakat alıkonulursanız, kurbandan kolayınıza geleni gönderiniz. Kurban yerine gelinceye kadar başlarınızı tıraş etmeyin. Artık içinizden her kim ki hasta olursa veya başında bir eziyet bulunursa; ona oruçtan, sadakadan veya kurbandan fidye (vacip olur). Emin olduğunuz vakitte kim hac zamanına kadar umre ile istifade etmiş olursa, kolayına gelen bir kurban kesmesi (icap eder). Ancak bulamazsa, hacc günlerinde üç; döndüğünüz vakit yedi gün oruç vacip olur ki; onlar, tam on gündür. Bu, ailesi Mescid-i Haram’da bulunmayanlar içindir. Allah’tan korkun. Ve bilin ki Allah, azabı pek şiddetli olandır."},{"n":197,"t":"Hacc; bilinen aylar(da)dır. Kim bu aylarda ihrama girerek Haccı kendine farz hale getirirse bilsin ki, Haccda fuhuş söz söylemek, küfürleşmek- kavga etmek ve her türlü günah işlemek yoktur. Ne iyilik işlerseniz Allah onu bilir."},{"n":198,"t":"Rabbinizin lütuf ve keremini istemenizin hiçbir sakıncası yoktur. Arafat’tan aşağı inince Meşar- ı Haram’da Allah’ı anın. O sizi nasıl doğru yola iletti ise siz de O’nu anın. Zira O’nun yol göstermesinden önce, kuşkusuz, sapıklardan idiniz."},{"n":199,"t":"Sonra insanların dağıldığı yerden siz de dağılın ve Allah’tan bağışlama dileyin. Hiç şüphesiz Allah bağışlayıcıdır, merhametlidir."},{"n":200,"t":"Hacc ibadetini bitirdiğinizde atalarınızı andığınız gibi, hatta ondan daha ısrarlı bir şekilde Allah’ı anın. Kimi insanlar ’Ey Rabbimiz, bize dünyada güzellik ver’ derler. Böylesinin Ahirette hiçbir pay olmaz."},{"n":201,"t":"Kimi insanlar da ’Ey Rabbimiz, bize dünyada da güzellik ver, Ahirette de güzellik ver ve bizi Cehennem ateşinin azabından koru’ derler."},{"n":202,"t":"İşte onların kazandıklarından payları vardır. Allah’ın hesaplaşması çok hızlıdır."},{"n":203,"t":"Sayılı günlerde Allah’ın adını anın. Kim hemen iki gün içinde dönerse bir günahı yoktur. Kim geri kalırsa da, günahtan korunanlar için, günahı yoktur. Allah’tan korkun ve bilin ki, hepiniz O’nun huzurunda biraraya getirileceksiniz."},{"n":204,"t":"Kimi insan var ki, dünya hayatı ile ilgili konuşması hoşunuza gider ve en amansız düşman olduğu halde kalbindeki duyguların samimi olduğuna Allah’ı şahit gösterir."},{"n":205,"t":"İş başına geçince yeryüzünde kargaşa ve bozgunculuk çıkarmaya, ekini ve nesli mahvetmeye çalışır. Oysa Allah kargaşa ve bozgunculuk çıkarmayı kesinlikle sevmez."},{"n":206,"t":"Ona ’Allah’tan kork’ denilince günahları ile gururlanma damarı kabarır. Böylesi için Cehennem yeterlidir. Orası ne kötü bir barınaktır!"},{"n":207,"t":"Kimi insan da var ki, benliğini Allah’ın rızasını kazanmaya adar. Hiç kuşkusuz, Allah kullarına karşı pek şefkatlidir."},{"n":208,"t":"Ey müminler, bütün varlığınız ile İslâm’a (barışa) girin. Sakın Şeytanın izinden gitmeyin. Çünkü o sizin apaçık düşmanınızdır."},{"n":209,"t":"Size apaçık deliller geldikten sonra yine sürçerseniz, ayağınız kayarsa bilin ki Allah her zaman üstündür ve hikmet sahibidir."},{"n":210,"t":"Acaba onlar bulut gölgeleri arasından Allah’ın ve meleklerin tepelerine inmesini ve böylece işin bitirilmesini mi bekliyorlar? Oysa bütün işlerin çözümü Allah’a götürülecektir."},{"n":211,"t":"İsrailoğulları’na sor; kendilerine nice açık ayetler, deliller sunduk. Kim Allah’ın nimeti kendisine geldikten sonra onu değiştirirse hiç kuşkusuz Allah’ın azabı pek ağırdır."},{"n":212,"t":"Dünya hayatı kâfirlere cazip görünür. Bunlar müminler ile alay ederler. Oysa Allah’ın azabından sakınanlar, Kıyamet günü, kâfirlerden üstün konumdadırlar. Allah dilediğine hesapsız olarak rızık verir."},{"n":213,"t":"İnsanlar tek bir ümmetti. Allah müjdeleyici ve korkutucu peygamberler gönderdi ve onlarla beraber insanların ihtilafa düştükleri şeylerde, aralarında hüküm vermeleri için hak kitaplar indirdi. Halbuki kendilerine apaçık deliller geldikten sonra aralarındaki ihtirastan dolayı ihtilafa düşenler de, o kendilerine kitap verilenlerden başkası değildir. İşte Allah, kendi iradesiyle iman edenleri, üzerinde ittifaka düştükleri hakka ulaştırdı. Allah dilediğini doğru yola ulaştırır."},{"n":214,"t":"Acaba sizden öncekilerin başlarına gelenlerin benzeri sizin de başınıza gelmeksizin, kolayca Cennet’e gireceğinizi mi sandınız? Onlar öylesine ağır sıkıntılara ve zorluklara uğradılar, öylesine sarsıldılar ki, peygamberleri ile çevresindeki inanmışlar; Allah’ın yardımı ne zaman gelecek?» dediler. İyi bilin ki, Allah’ın yardımı yakındır."},{"n":215,"t":"Sana (Allah yolunda) ne harcayacaklarını sorarlar. De ki; «Vereceğiniz mal (hayır) ana- baba, yakın akrabalar, yetimler, yoksullar ve yolda kalmışlar içindir. Hiç şüphesiz Allah yaptığınız her hayrı bilir.»"},{"n":216,"t":"Savaş, hoşunuza giden bir iş olmadığı halde size farz kılındı. Bazan hoşunuza gitmeyen birşey hakkınızda hayırlı olabilir, buna karşılık hoşunuza giden birşey de hakkınızda kötü olabilir. Allah bilir, fakat siz bilmezsiniz."},{"n":217,"t":"\"O ayda muharebe etmek, büyük bir günahtır. Fakat; insanları Allah yolundan men etmek ve onu inkar eylemek, Mescid-i Haram’a gitmelerine engel olmak, onun ehlini oradan çıkarmaksa Allah katında daha büyük günahtır. Fitne, katilden de beterdir. Kafirlerin güçleri yetse, sizi dininizden döndürünceye kadar sizinle savaşa devam ederler. Sizden her kim dininden döner de kafir olarak ölürse, onların yaptığı ameller dünyada da ahirette de boşa gitmiştir. Ve onlar Cehennem ehlidirler. Onlar orada ebedi kalacaklardır."},{"n":218,"t":"Onlar ki, iman ettiler, yurtlarından göç ettiler ve Allah yolunda savaştılar. İşte onlar Allah’ın rahmetini umarlar. Hiç şüphesiz Allah günahları bağışlar ve O merhametlidir."},{"n":219,"t":"Sana içki ve kumar hakkında soru sorarlar. De ki; Onların ikisinde de büyük günah vardır. İnsanlara bazı yararları varsa da günahları yararlarından büyüktür. Sana Allah yolunda ne vereceklerini sorarlar. De ki; «ihtiyaçlarınızdan artakalanını verin!» Allah size ayetlerini bu şekilde açıklıyor ki düşünesiniz."},{"n":220,"t":"Sana yetimler hakkında soru sorarlar. De ki; Onların durumlarını düzeltmek hayırlı bir iştir. Eğer kendileriyle birarada yaşıyorsanız, onlar artık kardeşlerinizdir. Allah kimin işleri bozucu ve kimin düzeltici olduğunu iyi bilir. Eğer Allah dileseydi, sizi zora koşardı. Hiç şüphesiz Allah üstündür ve hikmet sahibidir."},{"n":221,"t":"İman edinceye kadar müşrike kadınları nikahlamayınız. İman eden bir cariye müşrike kadından –o sizin hoşunuza gitse de– elbette daha hayırlıdır. İman edinceye kadar müşrik erkeklerle de nikah ettirmeyin; iman eden bir köle bir müşrikten –o sizin hoşunuza gitse de– elbette daha hayırlıdır. Onlar sizi Cehennem’e çağırırlar. Allah ise, Cennet’e ve mağfirete çağırır ve tezekkür etsinler diye insanlara ayetlerini açıkça bildirir."},{"n":222,"t":"Sana kadınların aybaşı kanaması hakkında soru sorarlar. De ki; «O bir eziyet, bir rahatsızlıktır. «Aybaşı dönemlerinde kadınlardan uzak durun, temizleninceye kadar onlara yaklaşmayın. Temizlendiklerinde Allah’ın size emrettiği yoldan onlarla cinsel ilişki kurun. Hiç şüphesiz Allah tevbe edenleri ve tertemiz olanları sever."},{"n":223,"t":"Kadınlarınız sizin çocuk üreten tarlalarınızdır. O halde, tarlanıza dilediğiniz gibi varın. Kendiniz için ileriye dönük hazırlık yapın, günah işlemekten sakının ve mutlaka Allah ’a kavuşacağınızı bilin. Bunu müminlere müjdele."},{"n":224,"t":"Sakın Allah adına yaptığınız yeminleri iyilik etmeye, günahlardan sakınmaya ve insanların arasını bulmaya engel yapmayın. Hiç Şüphesiz Allah işiten ve bilendir."},{"n":225,"t":"Allah sizi ağız alışkanlığı sonucu yaptığınız yeminlerden sorumlu tutmaz, fakat kalplerinizin kazandığı (bile bile yaptığınız) yeminlerden sorumlu tutar. Hiç şüphesiz Allah, bağışlayıcıdır ve halimdir."},{"n":226,"t":"Eşlerine yaklaşmamaya yemin edenler dört ay bekleyebilirler. Eğer bu yeminlerinden dönerlerse, kuşku yok ki, Allah bağışlayıcıdır ve merhametlidir."},{"n":227,"t":"Eğer boşanmaya karar verirlerse kuşku yok ki Allah işiten ve bilendir."},{"n":228,"t":"Boşanmış kadınlar üç aybaşı boyunca kendilerini gözlem altında tutarlar. Eğer Allah’a ve Ahiret gününe inanmışlar ise Allah’ın rahimlerinde yarattığı çocuğu saklamaları kendilerine helâl değildir."},{"n":229,"t":"Boşamak iki defa olur. Bundan sonra kadını ya meşru biçimde tutmak ya da iyilikle bırakmak gerekir. Kadınlara evliyken verdiklerinizden birşey geri almak helâl değildir. Ama eğer erkek ve kadın, Allah’ın koyduğu sınırları gözetemeyeceklerinden korkarlarsa o başka. Eğer kadın ile kocanın, Allah’ın koyduğu sınırları gözetemeyeceklerinden korkarsanız kadının boşanmak için kocasına fidye vermesinde her iki taraf için de sakınca yoktur. Bunlar Allah’ın koyduğu sınırlardır, onları aşmayın. Kimler Allah’ın koyduğu sınırları aşarsa işte onlar zalimlerin ta kendileridir."},{"n":230,"t":"Eğer erkek bundan sonra karısını kesinlikle boşarsa bu kadın başkası ile evlenmedikçe artık kocasına helâl olmaz. Eğer sonraki koca, kadını boşar da Allah’ın sınırlarını gözeteceklerine inanırlarsa eski karıkocanın tekrar birbirlerine dönmelerinin sakıncası yoktur. Bunlar Allah’ın koyduğu sınırlardır, onları bilen topluluğa açık açık anlatıyor."},{"n":231,"t":"Kadınları boşayıp da bekleme sürelerini doldurdukları zaman ya onları meşru biçimde tutun ya da yine meşru biçimde bırakın. Sakın onlara zarar vererek Allah’ın sınırlarını çiğnemek amacı ile kadınları alıkoymayın. Kim bunu yaparsa kendine yazık etmiş olur. Allah’ın ayetlerini alaya almayın. Allah’ın size bağışladığı nimetleri ve öğüt vermek için indirdiği Kitabı ve hikmeti hatırınızdan çıkarmayın. Allah’tan korkun ve O’nun herşeyi bildiğini bilin."},{"n":232,"t":"Kadınları boşayıp da bekleme sürelerini doldurdukları zaman eğer daha önceki kocaları ile meşru biçimde anlaşırlarsa evlenmelerine engel olmayın. Bu, içinizdeki Allah ’a ve Ahiret gününe inananlara yönelik bir öğüttür. Bu sizin hesabınıza en temiz ve en iffetli yoldur. Allah bilir, fakat siz bilemezsiniz."},{"n":233,"t":"Anneler çocuklarını tamam iki yıl emzirirler. Bu, emzirmeyi tamamlamak isteyen içindir. Onların yiyeceği, giyeceği ma’ruf vech üzre çocuk kendisinden olana aiddir. Kimse, takatından fazlasıyla mükellef olmaz. Ne bir anne çocuğu sebebiyle, ne de bir baba çocuğu yüzünden zarara sokulmasın. Mirasçıya düşen de bunun gibidir. Eğer kendi aralarında rıza ve müşavere ile memeden kesmeyi arzu ederlerse, ikisinin üstüne de bir vebal yoktur. Çocuklarınızı emzirmek isterseniz, meşru şekilde verdiğinizi teslim etmek şartıyla, yine size vebal yoktur. Allah’tan korkun. Ve bilin ki şüphesiz Allah, yaptığınız şeyleri hakkıyla görendir."},{"n":234,"t":"Aranızdan ölenlerin geride bıraktıkları eşleri dört ay, on gün kendilerini gözetim altında tutarlar. Bu sürelerini doldurduklarında meşru olarak yaptıklarından dolayı siz sorumlu tutulmazsınız. Hiç şüphesiz ne yaparsanız Allah onu bilir."},{"n":235,"t":"Kadınları nikahla isteyeceğinizi tariz yoluyla bildirmenizden veya böyle bir arzuyu gönüllerinizde saklamanızdan dolayı size bir vebal yoktur. Allah bilmiştir ki, siz onları mutlaka hatırlayacaksınız. Fakat onlarla gizlice vaidleşmeyin. Meşru bir sözle söylemeniz müstesna, iddet nihayet bulmadıkça nikah bağını bağlamaya azmetmeyin. Ve bilin ki, şüphesiz Allah; gönüllerinizde olanı bilir. Artık O’ndan sakının. Ve yine bilin ki şüphesiz Allah, Gafur’dur, Halim’dir."},{"n":236,"t":"Kadınlara el sürmeden ya da mehirlerini belirlemeden onları boşamanızın bir sakıncası yoktur. Fakat eli geniş olan kendi gücüne göre ve eli dar olan da kendi gücüne göre olmak üzere onlara geleneklere uygun bir hediye verin. Bu, iyilikseverler için bir borçtur."},{"n":237,"t":"Eğer kadınların mehirlerini belirler de onları el sürmeden boşarsanız, kendilerinin ya da nikâhlarını akdetmeye yetkili erkeğin bağışlaması durumu dışında belirlediğiniz mehrin yarısını ödemeniz gerekir. Bağışlamanız (mehrin tamamını bırakmanız) takvaya daha yakındır. Birbirinize karşı erdemliği unutmayın. Hiç şüphesiz ne yaparsanız Allah onu görür."},{"n":238,"t":"Namazlara ve orta namaza devam edin, namaza, Allah ’a gönülden bağlı ve saygılı olarak durun."},{"n":239,"t":"Eğer korku altında iseniz namazı yürürken ya da binek hayvanının sırtında kılın. Güvene kavuştuğunuzda Allah size bilmediğiniz şeyleri nasıl öğretti ise siz de O’nun adını anın."},{"n":240,"t":"Aranızdan vefat edip de geride eşlerini bırakanlar, bir yıl boyunca evden çıkmalarına ihtiyaç bırakmayacak (oranda bir meta’ı) eşlerine vasiyyet etsinler (bıraksınlar veya varislerine havale etsinler.) Eğer kadınlar kendiliklerinden evden çıkarlarsa kendileri ile ilgili yapacakları meşru bir davranıştan dolayı size sorumluluk düşmez. Hiç şüphesiz Allah üstün iradeli ve hikmet sahibidir."},{"n":241,"t":"Boşanmış kadınların geleneklere uygun bir şekilde geçimlerini sağlamak, takva sahiplerinin boynuna borçtur."},{"n":242,"t":"Allah ayetlerini size böyle açık açık anlatıyor ki, düşünesiniz."},{"n":243,"t":"Binlerce kişilik kalabalık olarak ölüm korkusu ile yurtlarından kaçan kimseleri görmedin mi? Allah onlara önce «ölün» dedi, arkasından kendilerini yeniden diriltti. Hiç kuşkusuz Allah insanlara karşı kerem sahibidir, ama insanlar çoğunlukla şükretmezler."},{"n":244,"t":"Allah yolunda savaşınız ve Allah’ın herşeyi işittiğini ve bildiğini biliniz."},{"n":245,"t":"Kimdir o ki, Allah’a karşılıksız (güzel) borç verir de Allah da bu borcu ona kat kat fazlası ile öder. Kısıtlayan da bol bol veren de Allah’tır. Döndürüleceğiniz yer O’nun katıdır."},{"n":246,"t":"Musa sonrası dönemde yaşayan bir grup ileri gelen İsrailoğlunu görmedin mi? Bunlar Peygamberlerine ’Başımıza bir hükümdar getir de onun emri altında Allah yolunda savaşalım’ dediler. Peygamberleri onlara; ’Ya eğer savaşmak size farz kılındığında bu emre karşı gelirseniz. diye sorunca, Yurdumuzdan ve çocuklarımızdan ayrı düşürüldüğümüze göre niçin savaşmayalım ki?’ dediler. Fakat savaşmak kendilerine farz kılınınca pek azı hariç hepsi yan çizdiler. Hiç kuşkusuz Allah, zalimlerin kimler olduğunu bilir."},{"n":247,"t":"Peygamberleri onlara; Allah size hükümdar olarak Talut’u gönderdi’ deyince, ’O bize nasıl hükümdar olabilir? Hükümdarlık bize ondan daha çok yakışır. Çünkü ona bol servet verilmiş, değildir’ dediler. Peygamberleri onlara; Allah onu hükümdar olarak seçerek başınıza getirdi, Ona bilgi ve vücud gücü bakımından üstünlük bağışladı’ dedi. Allah mülkünü (egemenlik yetkisini) dilediğine verir, Allah’ın lütfu geniştir ve O, herşeyi bilir."},{"n":248,"t":"Peygamberleri onlara dedi ki; ’Talut’un hükümdarlığının belirtisi, size meleklerin taşıdığı bir sandığın gelmesidir. Bu sandıkta Rabbinizden size yönelik bir huzur ile birlikte Musa ve Harun ailelerinin geride bıraktıkları bazı önemli eşyalar vardır. Eğer mümin kimseler iseniz, bu sizin için kesin bir belirtidir."},{"n":249,"t":"\"Nice az bir topluluk Allah’ın izniyle pek çok fırkaları mağlup etmişlerdir. Allah sabredenlerle beraberdir.\""},{"n":250,"t":"Talut ve askerleri, Calut ve ordusu ile karşılaştıklarında; ’Ey Rabbimiz, üzerimize sabır yağdır, ayaklarımızı sabit kıl ve kâfirlere karşı bize zafer nasip eyle’ dediler."},{"n":251,"t":"Allah’ın izniyle onları hemen hezimete uğrattılar. Davut da Calut’u öldürdü. Allah ona mülk ve hikmet verdi. Dilemekte olduğu şeylerden de ona öğretti. Şayet Allah insanları birbiriyle def edip savmasaydı yeryüzü muhakkak ki fesada uğrardı. Ancak Allah alemler üzerine fazl u kerem sahibidir."},{"n":252,"t":"Bunlar Allah’ın ayetleridir. Bunları sana hakka bağlı olarak okuyoruz. Hiç kuşkusuz sen de peygamberlerden birisin."},{"n":253,"t":"İşte şu peygamberler. Bunların bir kısmını diğerlerinden üstün kıldık. Onlardan kimileri ile Allah konuştu, kimilerini de derecelerce yükseltti. Meryem oğlu İsa’ya açık mucizeler verdik, O’nu Ruh-ul Kuds aracılığı ile destekledik. Eğer Allah öyle dileseydi, bu peygamberlerin arkasından gelen ümmetler, kendilerine açık belgeler geldikten sonra birbirlerini öldürmezlerdi. Fakat onlar anlaşmazlığa düştüler. Onlardan kimi iman etti, kimi de kâfir oldu. Eğer Allah öyle dileseydi, onlar birbirlerini öldürmezlerdi. Ama Allah neyi dilerse onu yapar."},{"n":254,"t":"Ey müminler, ne alışverişin ne dostluğun ve ne de iltimasın sözkonusu olmadığı gün gelmeden önce size verdiğimiz rızıklardan Allah yolunda harcayın. Kâfirler, zalimlerin ta kendileridirler."},{"n":255,"t":"Allah O’dur ki kendisinden başka hiç bir ilah yoktur. Hayy ve Kayyum’dur. O’nu dalgınlık ve uyku tutmaz. Göklerde ve yerde ne varsa hepsi O’nundur. O’nun ilmi olmadan katında şefaat edecek kimdir? Önlerinde ve arkalarında ne varsa bilir. Dilediği kadarından başka O’nun ilminden hiç bir şey kavrayamazlar. Kürsisi gökleri ve yeri kaplamıştır. Onları koruyup gözetmek O’na ağırlık vermez. O, öyle ulu, öyle azametlidir."},{"n":256,"t":"Dinde zorlama yoktur. Doğruluk ile sapıklık birbirinden kesinlikle ayrılmıştır. Kim Tağut’u, azgınlığı reddederek Allah’a inanırsa kopması sözkonusu olmayan, sapasağlam bir kulpa yapışmıştır. Hiç kuşkusuz Allah herşeyi işitir, herşeyi bilir."},{"n":257,"t":"Allah müminlerin dostu, kayırıcısıdır. Onları karanlıklardan aydınlığa çıkarır. Kâfirlerin dostları ise Şeytan ve yardakçılarıdır. Bunlar, onları aydınlıktan çıkararak karanlıklara sokarlar. Onlar, orada ebedi olarak kalmak üzere Cehennemliktirler."},{"n":258,"t":"Allah kendisine iktidar verdi diye şımararak İbrahim ile Rabbi hakkında tartışmaya girişen adamı görmedin mi? İbrahim «Benim Rabbim, diriltebilen ve öldürebilendir» deyince adam «Ben de diriltebilir ve öldürebilirim» dedi. Bunun üzerine İbrahim «Allah güneşi doğudan getiriyor, sen de onu batıdan getir, bakalım» deyince o kâfir adam şaşırıp kaldı, söyleyecek söz bulamadı. Allah zalimleri hidayete erdirmez."},{"n":259,"t":"\"Artık Allah’ın her şeye kadir olduğunu biliyorum.\" dedi."},{"n":260,"t":"\"Rabbim, ölüleri nasıl dirilttiğini bana göster\" deyince \"İnanmıyor musun?\" demişti. O da \"Hayır öyle değil, ama kalbim iyice mutmain olsun\" demişti. \"Öyleyse dört çeşit kuş al, onları kendine alıştır. Sonra her dağ başına onlardan birer parça koy. Sonra onları çağır. Koşarak sana gelirler. Ve bil ki şüphesiz Allah Aziz’dir, Hakim’dir."},{"n":261,"t":"Mallarını Allah yolunda harcayanların durumu, her başağı yüz taneli yedi başak veren bir tohum tanesine benzer. Allah dilediğine kat kat verir. Allah’ın lütfu geniştir, O herşeyi bilir."},{"n":262,"t":"Mallarını Allah yolunda harcadıktan sonra sadakalarını başa kakmayanlar, onur kırma aracı olarak kullanmayanlar, sadakalarının mükafatını Allah katında alacaklardır. Onlar için korku ve üzülmek de sözkonusu olmayacaktır."},{"n":263,"t":"Tatlı söz ve hoşgörü, peşinden başa kakma ve onur kırma gelen sadakadan daha iyidir. Allah’ın hiçbir şeye ihtiyacı yoktur, O Halimdir."},{"n":264,"t":"Ey müminler, tıpkı Allah’a ve Ahiret gününe inanmadıkları halde başkalarına gösteriş olsun diye mallarını harcayanların yaptıkları gibi, sadakalarınızı başa kakarak ve onur kırma aracı haline getirerek boşa çıkarmayın. Böylesi, sağanak halindeki bir yağmura tutulunca, çır çıplak kalan toprakla örtülü bir kayaya benzer. Bunlar yaptıkları iyilikten hiçbir şey elde edemezler. Allah kâfir topluluğu doğru yola iletmez."},{"n":265,"t":"Buna karşılık mallarını Allah’ın rızasını elde etmek ve gönüllerindeki imanı pekiştirmek için harcayanların durumu da yüksekçe bir tepedeki bol yağmur alarak ürünlerini iki kat olarak veren ve bol yağmur görmediğinde de mutlaka çisinti gören verimli bir bahçe gibidir. Hiç kuşkusuz ne yaparsanız Allah onu bilir."},{"n":266,"t":"İçinizden biri ister mi ki, altından ırmaklar akan bir hurma ve üzüm bağı olsun, bağda her türlü meyve ağacı bulunsun ve hayli yaşlanmış olduğu halde bakıma muhtaç çocukları varken bu bağ ansızın esen bir samyeline tutularak yanıp kül olsun. İşte Allah, düşünürsünüz diye size ayetlerini böyle açık açık anlatıyor."},{"n":267,"t":"Ey müminler, kazandıklarınızın temiz ve kaliteli olanları ile sizin için topraktan yetiştirdiklerimizden sadaka verin, sakın kendiniz göz yummadan almayacağınız, adi ve kalitesi bozuk şeyleri vermeye kalkışmayın. İyi bilin ki Allah’ın hiçbir şeye ihtiyacı yoktur, övülmek O’na mahsustur."},{"n":268,"t":"Şeytan fakirlikle korkutarak size cimriliği, kötülük işlemeyi emreder. Oysa Allah size kendi katından bağışlama ve bol nimet vaadeder. Allah’ın lütfu geniştir, O herşeyi bilir."},{"n":269,"t":"O hikmeti dilediğine verir. Kime hikmet verilmişse ona çok hayırlı birşey verilmiş demektir. Bunu ancak akıl sahipleri düşünüp anlayabilirler."},{"n":270,"t":"Verdiğiniz her nafakayı, adadığınız her adağı kuşku yok ki, Allah bilir. Zalimler için bir yardımcı yoktur."},{"n":271,"t":"Eğer sadakaları açıktan verirseniz bu güzeldir. Şayet onları kimse görmeden fakirlere verirseniz bu sizin için daha hayırlıdır ve bu, birkısım günahlarınızın silinmesine vesile olur. Allah yaptıklarınızdan haberdardır."},{"n":272,"t":"Onları doğru yola getirmek sana düşmez, ancak Allah dilediğini doğru yola iletir. Hayır amacıyla ne infak ederseniz bu kendiniz içindir. Zaten siz sırf Allah rızasını kazanmak için infak edersiniz. Yaptığınız her hayır amaçlı harcamanın karşılığı size eksiksiz olarak verilir, kesinlikle size haksızlık yapılmaz."},{"n":273,"t":"Kendilerini Allah yoluna adamış, bu yüzden yeryüzünde (dünyalık için) koşmaya fırsat bulamayan ve hayaları yüzünden. tanımayanlar tarafından varlıklı sanılan fakirlere yardım edin. Sen onları yüz ifadelerinden tanırsın. Yüzsüzlük edip hiç kimseden birşey istemezler. Yaptığınız her hayır amaçlı harcamayı kuşku yok ki Allah bilir."},{"n":274,"t":"Mallarını gece-gündüz, gizli-açık Allah yolunda harcayanların mükâfatı Allah katında verilecektir. Onlar için bir korku sözkonusu değildir ve onlar üzülmezler de."},{"n":275,"t":"Faiz yiyenler şeytan tarafından çarpılmış kimseler gibi ayağa kalkarlar, Bu onların «alış- veriş de faiz gibidir» demelerinden dolayıdır. Oysa Allah alış- verişi helâl, faizi ise haram kılmıştır. Kim kendisine Rabbinden bir öğüt gelir- gelmez faiz yemeye son verirse geçmişte aldığı faizler kendisinden geri alınmaz. Onun işi Allah ’a kalmıştır. Fakat kimler tekrar faizciliğe dönerlerse onlar, orada ebedi olarak kalmak üzere Cehennemliktirler."},{"n":276,"t":"Allah faizi eritir. Buna karşılık sadakaları artırır. Allah (haramda ısrar eden) hiçbir günahkar kâfiri sevmez."},{"n":277,"t":"Onlar ki inandılar, iyi işler yaptılar, namazı kıldılar ve zekatı verdiler. Rabbleri katında mükafatları kendilerine mutlaka verilecektir. Onlar için artık korku sözkonusu değildir, onlar hiç üzülmeyeceklerdir"},{"n":278,"t":"Ey müminler, Allah’tan korkun ve eğer mümin iseniz henüz elinize geçmemiş faizi almaktan vazgeçin."},{"n":279,"t":"Eğer böyle yapmazsanız Allah ve Resulü tarafından açılmış bir savaşla karşı karşıya olduğunuzu bilin. Eğer faizciliğe tevbe ederseniz ana sermaye sizin olur. Böylece ne haksızlık etmiş ve ne de haksızlığa uğramış olursunuz."},{"n":280,"t":"Eğer borçlunuz darda ise eli genişleyinceye kadar ona mühlet tanıyın. Eğer bilirseniz, alacağınızı bağışlamanız sizin hesabınıza daha hayırlıdır."},{"n":281,"t":"Allah ’a döneceğiniz ve sonra hiç kimseye haksızlık edilmeksizin herkese kazancının eksiksiz olarak verileceği günden korkun."},{"n":282,"t":"Ey müminler, birbirinize belirli bir süre sonra ödenmek üzere borç verdiğiniz zaman bunu yazın. İçinizden biri bunu dürüst bir şekilde yazsın. Yazan kimse onu Allah’ın kendisine öğrettiği gibi yazmayı ihmal etmesin. Bu hesabı yazıcıya borçlu taraf yazdırsın. Ama Rabbi olan Allah’tan korksun da bu hesabı yazdırırken hiçbir şeyi eksik bırakmasın. Eğer borçlu taraf aptal, zayıf ya da nasıl yazdıracağını bilmeyen biri ise yazdırma işlemini onun yerine dürüst bir şekilde velisi yapsın. Bu işleminize erkeklerinizden iki kişiyi şahit tutunuz, eğer iki erkek şahit bulunmaz ise karşılıklı olarak onayladığınız bir erkek ile iki kadını şahit tutunuz, ta ki biri yanılınca öbürü ona hatırlatsın. Şahitler çağrıldıklarında gitmemezlik etmesinler. Borç küçük olsun büyük olsun onu vadesini belirterek yazmaktan üşenmeyiniz. Bu Allah katında en dürüstçe şahitlik için en sağlam ve sizi şüpheden uzak tutacak en kestirme yoldur. Yalnız aranızda peşin bir alışveriş olursa bu işlemi yazıya geçirmemenizin sakıncası yoktur. Alışveriş yaparken de şahit tutun. Ne yazana ne de şahide zarar verilmesin. Eğer bunlara zarar verirseniz kendi hesabınıza fasık olmuş, günaha girmiş olursunuz. Allah’tan korkun. O size nasıl hareket edeceğinizi gösteriyor. Allah herşeyi bilir."},{"n":283,"t":"Eğer yolculukta olur da işlemlerinizi yazacak birini bulamazsanız, karşılıklı olarak alınan rehinler yeterlidir. Eğer birbirinize güvenerek borç işlemi yapmış iseniz kendisine güvenilen kimse borcunu ödesin. Rabbi olan Allah’tan korksun. Sakın şahitliği saklamayın. Kim şahitliği saklı tutarsa onun kalbi günahkardır. Hiç kuşkusuz ne yaparsanız Allah onu bilir."},{"n":284,"t":"Göklerdekilerin ve yerdekilerin hepsi Allah’ındır. İçinizdekini açığa vursanız da gizli tutsanız da Allah sizi onun yüzünden hesaba çeker. Sonra dilediğini affeder ve dilediğini azaba çarptırır. Hiç şüphesiz Allah’ın herşeye gücü yeter."},{"n":285,"t":"Peygamber kendisine Rabbi tarafından indirilen gerçeklere inandı, müminler de. Hepsi birlikte Allah’a, O’nun meleklerine, O’nun kitaplarına ve O’nun peygamberlerine inandılar. ’Onun peygamberlerinden hiçbirini diğerlerinden ayırmayız. Duyduk ve uyduk. Günahlarımızı bağışlamanı dileriz, ey Rabbimiz, dönüşümüz sanadır’ dediler.»"},{"n":286,"t":"Allah hiç kimseye kapasitesini aşacak bir yükümlülük yüklemez. Herkesin kazandığı iyilik kendi yararına ve işlediği kötülük de kendi zararınadır. Ey Rabbimiz, eğer unutacak ya da yanılacak olursak bizi sorumlu tutma. Ey Rabbimiz, bizden öncekilere yüklemiş olduğun gibi bize de ağır yük yükleme. Ey Rabbimiz, bize gücümüzün yetmeyeceği yükü taşıtma, bizi affet, günahlarımızı bağışla, bize merhamet eyle, sen mevlamızsın bizim. Kâfirlere karşı yardım et bize."}],[{"n":1,"t":"Elif Lâm- Mim."},{"n":2,"t":"O, kendinden başka bir ilâh bulunmayan, diri ve yarattıklarını gözetip yöneten Allah’tır."},{"n":3,"t":"Sana daha önceki semavi kitapları onaylayan hakk içerikli kitabı indirdi. Daha önce de insanlara doğru yolu göstermek için Tevrat’ı ve İncil’i indirmişti."},{"n":4,"t":"Doğru ile eğriyi birbirinden ayıran bu kitabı da aynı amaçla indirdi. Allah’ın ayetlerini inkâr edenleri ağır bir azap beklemektedir. Hiç kuşkusuz Allah üstün iradeli ve intikam alıcıdır."},{"n":5,"t":"Hiç şüphesiz, ne yerde ve ne gökteki hiçbir şey Allah için gizli değildir."},{"n":6,"t":"Size döl yataklarında dilediği biçimi veren O’dur. O’ndan başka ilah yoktur. O, üstün iradeli ve hikmet sahibidir."},{"n":7,"t":"Sana bu Kitab’ı indiren O’dur. Bu Kitab’ın bir kısım ayetleri kesin anlamlı (muhkem)dir, bunlar onun özünü oluştururlar. Diğer kısmı da birden çok anlamlı (müteşabih)dir. Kalplerinde eğrilik olanlar fitne çıkarmak ve keyfi yorumlar yapmak amacı ile bu kitabın birden çok anlamlı ayetlerinin ardına düşerler. Oysa onların yorumunu sadece Allah bilir. Köklü bilgiye sahip olanlar ise «Bu Kitab ’a inandık, O bütünü ile Allah katından gelmiştir» derler. Bunu ancak aklı başında olanlar düşünebilirler."},{"n":8,"t":"«Ey Rabbimiz, bizleri doğru yola ilettikten sonra kalplerimizi kaydırma, bize katından rahmet bağışla, kuşkusuz sen bağışı bol olansın."},{"n":9,"t":"Ey Rabbimiz, sen geleceği kuşkusuz olan bir günde insanları kesinlikle biraraya getireceksin. Hiç şüphesiz Allah sözünden caymaz."},{"n":10,"t":"Kafirlere gelince onların ne malları ve ne de evlatları Allah’ın karşısında hiç bir işlerine yaramaz. Onlar Cehennem ateşinin yakacağıdırlar."},{"n":11,"t":"Tıpkı Firavunoğulları gibi, daha öncekilerin durumu gibi. Onlar ayetlerimizi yalanladılar. Allah da günahları yüzünden onların yakalarına yapıştı. Hiç kuşkusuz Allah’ın azabı ağırdır."},{"n":12,"t":"Orası ne fena bir barınaktır."},{"n":13,"t":"Savaşta/Bedir’de karşı karşıya gelen iki orduda sizin için bir işaret vardır. Ordunun biri Allah için savaşırken, diğeri O’nu inkâr ediyordu. Gözleriyle diğer tarafı kendilerinin iki misli gördüler. Ama Allah, dilediğini yardımıyla güçlendirir. Elbette bunda basiret/aydınlık sahipleri için bir ibret vardır."},{"n":14,"t":"Kadınlara, evlâdlara, tartı tartı biriktirilmiş altın ve gümüşe, otlağa yayılmış atlara, küçükbaş hayvanlara ve ekinlere karşı aşırı tutkunluk insanlara cazip gösterildi. Bunlar dünya hayatının nimetleridir. Oysa asıl varılacak yer Allah katındadır."},{"n":15,"t":"Size bunlardan daha hayırlı olanı haber vereyim mi? Takvalılar için Rabbleri katında sürekli kalacakları, altından ırmaklar akan Cennetler, el değmemiş eşler ve Allah’ın hoşnutluğu vardır. Hiç kuşkusuz Allah kullarını hakkıyla görür.»"},{"n":16,"t":"Bu kimseler ’Ey Rabbimiz, inandık, günahlarımızı affeyle, bizleri Cehennem ateşinin azabından koru’ derler."},{"n":17,"t":"Bunlar sabırlılar, samimî bağlılar, gönülden kulluk edenler, mallarını Allah yolunda harcayanlar ve seher vakitlerinde günahlarının bağışlanmasını dileyenlerdir."},{"n":18,"t":"Allah’tan başka ilâh olmadığına ve O’nun adaleti ayakta tuttuğuna Allah’ın kendisi, melekler ve bilgili kullar tanıktır. O’ndan başka ilâh yoktur. O üstün iradeli ve hikmet sahibidir."},{"n":19,"t":"Allah katında, Allah’tan gelen, tek ilâhî din, şeriat, düzen, medenî kurallar İslâm’dır. Kendilerine verilen kutsal kitapların hükmünce sorumlu tutulanlar, kavimlerine gelen doğru bilgilerden sonra, liderliği ve hakimiyeti hep kendi uhdelerinde tutma hırsları, hasetleri, haksızlıkları, şer’î kurallara karşı çıkmaları ve bozgunculukları sebebiyle ayrı baş çekerek ihtilâf çıkardılar. Allah’ın âyetlerini, Kur’ân’ını, birliğini gösteren delilleri inkâr edenler, küfre giren ehl-i kitap bilmelidir ki, Allah çok çabuk hesaba çeker."},{"n":20,"t":"Eğer seninle tartışmaya kalkışırlarsa de ki; ’Ben bana uyanlar ile birlikte tüm varlığım ile Allah’a teslim oldum.’ Kendilerine kitap verilenler ile kitapsız müşriklere ’Siz de teslim oldunuz mü?’ diye sor. Eğer teslim olurlarsa doğru yola girmiş olurlar. Eğer sırt dönerlerse sana düşen sadece duyurmaktır. Allah kullarını hakkıyle görür."},{"n":21,"t":"Allah’ın ayetlerini inkâr edenleri, peygamberleri sebepsiz olarak öldürenleri ve adaleti emreden insanları öldürenleri acıklı bir azapla müjdele!"},{"n":22,"t":"Onların emek ve çabaları dünyada da ahirette de boşa gitmiştir. Onlara yardım eden bulunmaz"},{"n":23,"t":"Allah’ın kitabından kendilerine bir pay verilmiş olanları görmedin mi? Bunlar aralarında hüküm versin diye Allah’ın kitabına çağırılıyorlar, fakat sonra aralarından bir grup bu kitaba karşı çıkarak sırt çeviriyor."},{"n":24,"t":"Bu olumsuz tutumları, onların ’Cehennem ateşi bize sayılı birkaç gün dışında dokunmayacak’ demelerinden kaynaklanıyor. Onların bu iftiraları dinleri konusunda kendilerini yanılgıya düşürmüştür."},{"n":25,"t":"Acaba geleceği kuşkusuz bir gün onların biraraya getirilecekleri ve hiç kimseye haksızlık edilmeksizin herkese kazandığı verileceği zaman halleri nice olur?"},{"n":26,"t":"De ki; ’Ey mülkün sahibi Allah’ım, sen mülkü (egemenliğin iktidarı) dilediğine verir, dilediğinden geri alırsın. Dilediğini üste çıkarır, dilediğini alçaltırsın. İyilik senin elindedir, senin gücün herşeye yeter."},{"n":27,"t":"Geceyi gündüze dönüştürür, gündüzü geceye dönüştürürsün. Diriyi ölüden çıkarır, ölüyü diriden çıkarırsın. Dilediklerine hesapsız rızık verirsin.’"},{"n":28,"t":"Müminler, müminleri bırakarak kafirleri dost edinmesinler. Kim böyle yaparsa artık Allah ile arasında hiçbir ilişki kalmaz. Yalnız, kafirlerin size yönelik tehlikelerinden korunabilirsiniz. Allah sizi kendinden korkmaya çağırıyor. Dönüş Allah’adır."},{"n":29,"t":"De ki; ’İçinizdeki duyguyu saklasanız da açığa vursanız da Allah onu bilir. Göklerde olanı ve yerde olanı da bilir. Allah’ın gücü herşeye yeter.’"},{"n":30,"t":"O gün herkes yapmış olduğu her iyiliği karşısında bulur, yaptığı her kötülüğü de. Yaptığı kötülükle arasında uzak bir mesafe olsun ister. Allah sizi kendisinden korkmaya çağırır. Allah, kullarına karşı şefkatlidir."},{"n":31,"t":"De ki; ’Eğer Allah’ı seviyorsanız bana uyunuz ki, Allah sizi sevsin ve günahlarınızı bağışlasın. Hiç kuşkusuz Allah bağışlayıcı ve esirgeyicidir.’"},{"n":32,"t":"De ki: ‘Allah’a ve peygambere itaat ediniz.’ Eğer bu çağrıya sırt çevirirlerse hiç şüphesiz Allah kafirleri sevmez."},{"n":33,"t":"Allah Adem’i, Nuh’u, İbrahim ailesini ve İmran ailesini seçerek alemlere üstün kıldı."},{"n":34,"t":"Bunlar birbirinden türemiş tek bir kuşaktır. Hiç şüphesiz Allah işiten ve bilendir."},{"n":35,"t":"Hani, İmran’ın karısı ’Rabbim, karnımdaki çocuğu, her türlü endişeden arınmış olarak sırf sana adadım, O’nu benden yana kabul buyur. Hiç, kuşkusuz sen işiten ve bilensin’ dedi."},{"n":36,"t":"’Rabbim, doğurduğum kız çocuğudur, oysa erkek kız gibi değildir. Ona Meryem adını taktım. O’nu ve soyunu lânetlenmiş şeytandan senin himayene havale ederim."},{"n":37,"t":"Allah tarafından geldi, hiç kuşkusuz Allah dilediğine hesapsız rızık verir’ derdi."},{"n":38,"t":"Orada Zekeriyya, Rabbine dua etti; ’Ey Rabbim, bana kendi tarafından temiz bir soy bağışla, hiç kuşkusuz sen şu duayı işitensin’ dedi."},{"n":39,"t":"Bunun üzerine Zekeriyya, mabette namaz kılarken melekler ona şöyle seslendiler; Allah sana Yahya’yı müjdeliyor. O, Allah’ın dolaysız kelimesini doğrulayan, efendi, iffetli ve salihlerden bir peygamberdir.’"},{"n":40,"t":"Zekeriyya ’Ya Rabbi, kendim iyice yaşlanmış ve karım çocuktan kesilmişken nasıl oğlum olabilir?’ dedi. O da ’Böyledir, Allah dilediğini yapar’ dedi."},{"n":41,"t":"Zekeriyya ’Rabbim, bana bunun belirtisini göster’ dedi. Allah ona şöyle buyurdu; ’Senin belirtin üç gün boyunca, işaretleşme dışında insanlarla konuşmamandır. Rabbinin adını çokça an ve sabah akşam O’nu noksanlıktan tenzih et:"},{"n":42,"t":"Hani melekler şöyle demişti; ’Ey Meryem, Allah seni seçti, arındırdı ve dünyanın kadınlarına üstün kıldı:"},{"n":43,"t":"Ey Meryem Rabbinin huzurunda saygı ile dur. Secdeye kapan ve rükua varanlarla birlikte sen de rükua var."},{"n":44,"t":"Bunlar sana vahiy yolu ile bildirdiğimiz gayb alemine ilişkin haberlerdir. Onlardan hangisi Meryem’in sorumluluğunu üstlenecek diye kalemleri ile kur’a çekerlerken sen yanlarında değildin, bu konuda çekişirken de orada değildin."},{"n":45,"t":"Hani Melekler dediler ki; ’Ey Meryem, Allah seni dolaysız Kelime’si ile müjdeliyor. Onun adı Meryemoğlu İsa Mesih’tir. O dünyada da ahirette de yüce, şanlıdır ve Allah’ın yakınlarındandır."},{"n":46,"t":"O daha beşikteyken ve yetişkinlik çağında insanlarla konuşacaktır ve salih kullarındandır."},{"n":47,"t":"’İşte böyledir, Allah dilediğini yaratır. O bir şeyin olmasına karar verince ona sadece «ol» der o da hemen oluverir.’"},{"n":48,"t":"Allah O’na Kitab’ı, Hikmet’i, Tevrat’ı ve İncil’i öğretecek."},{"n":49,"t":"O’nu, İsrailoğullarına şöyle diyecek olan bir peygamber olarak gönderecek; ’Ben size Rabbinizden mucize ile geldim. Ben sizin önünüzde çamurdan kuş biçiminde bir cisim yapar, sonra ona bir nefes üflerim de Allah’ın izni ile kuş oluverir; Doğuştan körler ile alacalık (ebras) hastalarını iyileştiririm; Allah’ın izni ile ölüleri diriltirim; evlerinizde hangi yiyeceklerinizi yediğinizi ve hangilerini sonraya bıraktığınızı haber veririm. Eğer mümin iseniz, bu sizin için ibret alacağınız kesin bir delildir."},{"n":50,"t":"Benden daha önce inen Tevrat’ı onaylayıcı olarak size haram kılınmış olan bazı şeyleri helâl ilan etmek üzere Rabbiniz tarafından kesin bir kanıtla size geldim. Allah’tan korkunuz ve bana itaat ediniz."},{"n":51,"t":"Allah benim de sizin de Rabbimizdir, O’na kulluk ediniz, doğru yol işte budur."},{"n":52,"t":"İsa, İsrailoğulları’nın inkarcı tutumlarını görünce Allah uğrunda bana yardımcı, destekçi olacak olanlar kimlerdir?’ diye sordu. Havariler ’Biz Allah’ın destekçileriyiz, Allah’a iman ettik, şahid ol ki biz müslümanız’ dediler."},{"n":53,"t":"’Ey Rabbimiz, indirmiş olduğun mesaja inandık, Peygambere uyduk, bizleri bu mesajın canlı şahitleri arasına yaz!’"},{"n":54,"t":"Hile yaptılar. Allah da onları cezalandırdı. Ve Allah hile yapanların cezasını en iyi verendir."},{"n":55,"t":"Hani Allah şöyle demişti; ’Ey İsa, ben senin canını alacak, katıma yükseltecek ve kâfirlerin iftiralarından arındıracağım, sana uyanları da kıyamet gününe kadar kâfirlere üstün kılacağım. Sonra hepiniz bana döneceksiniz ve ben anlaşmazlığa düştüğünüz konularda aranızda hüküm vereceğim.’"},{"n":56,"t":"Kâfirler var ya, onları ağır bir azaba çarptıracağım, onların hiçbir yardımcısı olmayacaktır."},{"n":57,"t":"İman edip salih ameller (iyi işler) yapanlara gelince, Allah onların mükafatlarını eksiksiz olarak verecektir, Allah zalimleri sevmez."},{"n":58,"t":"Sana okuduğumuz bu kıssalar ve direktifler, ayetlerden ve hikmetli zikirdendirler."},{"n":59,"t":"Allah katında İsa örneği, Allah’ın topraktan yarattıktan sonra \"ol\" demesi ile oluveren Adem örneği gibidir."},{"n":60,"t":"Bu anlattıklarımız Rabbinden gelen gerçektir. Sakın kuşkuya kapılanlardan olma."},{"n":61,"t":"Sana gelen bilgiden sonra kim bu konuda seninle tartışacak olursa de ki; ’Geliniz, evlatlarımızı ve evlatlarınızı, kadınlarımızı ve kadınlarınızı, kendinizi ve kendimizi biraraya çağıralım; sonra karşılıklı lânetleşerek Allah’ın lânetinin yalancıların üzerine olmasını dileyelim."},{"n":62,"t":"Bu anlatılanlar gerçek olaylardır. Allah’tan başka ilah yoktur. Hiç kuşkusuz Allah üstün iradeli ve hikmet sahibidir."},{"n":63,"t":"Eğer sırt çevirirlerse kuşkusuz Allah kimlerin bozguncu olduğunu bilir."},{"n":64,"t":"\"Ey ehl-i kitab! Hepiniz, sizinle bizim aramızda müsavi olan bir kelimeye gelin. Allah’tan başkasına kulluk etmeyelim. O’na hiçbir şeyi eş koşmayalım. Ve Allah’ı bırakıp da kimimiz kimimizi Rab ittihaz edinmesin. Eğer yüz çevirirlerse o vakit, şahit olun ki, biz müslümanız\" deyin."},{"n":65,"t":"Ey kitap ehli; ne diye İbrahim hakkında tartışıyorsunuz? Oysa Tevrat ve İncil O’ndan sonra indirildi. Bunu düşünemiyor musunuz?"},{"n":66,"t":"Diyelim ki, hakkında bilgi sahibi olduğunuz İsa konusu üzerinde tartıştınız. Peki hiç bilmediğiniz bir konu üzerinde ne diye tartışıyorsunuz? Allah bilir fakat siz bilmezsiniz."},{"n":67,"t":"İbrahim ne yahudi ve ne de hıristiyan idi. O dosdoğru bir müslümandı. müşriklerden değildi."},{"n":68,"t":"Gerçekten İbrahim’e en yakın insanlar O’na uymuş olanlar ile bu peygamber ile O’na inananlardır. Allah müminlerin dostudur."},{"n":69,"t":"Kitap ehlinin bir kısmı sizi saptırmak istedi; oysa onlar ancak kendilerini saptırırlar da bunun farkına varamazlar."},{"n":70,"t":"Ey kitap ehli, niye göz göre göre Allah’ın ayetlerini inkâr ediyorsunuz?"},{"n":71,"t":"Ey kitap ehli, niye gerçeğin üzerine batılı örtüyor ve bile bile gerçeği saklıyorsunuz?"},{"n":72,"t":"Kitap ehlinden bir grup dedi ki; ’müminlere indirilen mesaja günün başlangıcında inanınız, fakat günün sonunda onu reddediniz, böylece belki onlar da inançlarından dönerler."},{"n":73,"t":"Onlar birbirlerine ’Size verilen mesajın benzeri bir başkasına (peygambere) verildiği için ya da söyleyeceklerinizi, Rabbiniz katında size karşı delil olarak kullanırlar diye müslümanların dinlerine inanmayın’ derler. De ki; ’Lütuf, Allah’ın elindedir, onu dilediğine verir. Allah’ın lütfu geniştir ve O her şeyi bilir.’"},{"n":74,"t":"Dilediğine rahmetini bağışlar. Dünyada ve ahirette en büyük nimetler de O’nundur."},{"n":75,"t":"Kitap ehlinden öylesi var ki, yanına yüklü bir emanet bıraksan onu sana geri verir, buna karşılık öylesi var ki, eğer ona bir dinarcık emanet versen, sürekli tepesinde dikilmedikçe onu sana geri vermez. ’Ümmilere (kendi dinimizden olmayanlara) karşı hiçbir sorumluluğumuz yoktur’ dedikleri için böyle davrananlar, böyle bile bile Allah adına yalan söylerler."},{"n":76,"t":"Hayır, öyle değil. Kim sözünü yerine getirir ve günahtan sakınırsa bilsin ki Allah kesinlikle takva sahiplerini sever."},{"n":77,"t":"Allah’a verdikleri sözü ve yeminleri birkaç para karşılığında satanlar var ya, onların ahirette hiçbir payları olmaz. Kıyamet günü Allah onlarla konuşmaz, taraflarına bakmaz ve kendilerini günahlardan arındırmaz; onları acıklı bir azap beklemektedir."},{"n":78,"t":"Onlardan öyleleri var ki, kutsal kitabı dik durarak okurlar, böylece okuduklarını Allah kitabından sanmanızı sağlamaya çalışırlar. Oysa bu okudukları şeyler kitaptan değildir. ’Bu Allah katındandır’ derler. Oysa Allah katından değildir. Böylece bile bile Allah adına yalan söylerler."},{"n":79,"t":"Hiçbir insana yakışmaz ki kendisine kitap, yetki ve peygamberlik verildikten sonra insanlara dönsün de Allah’ı bırakarak bana kul olunuz’ desin; tersine ona yakışan söz; ’Okuyup öğrendiğiniz bu kitap gereğince Allah ’a kul olmayı benimseyiniz’ demektir."},{"n":80,"t":"Onun size, melekleri ve peygamberleri ilâh edinmenizi emretmesi de düşünülemez. O size, müslüman olduktan sonra, kâfir olmayı emreder mi hiç?"},{"n":81,"t":"Hani Allah, peygamberlerden ’Bakınız, size kitap ve hikmet verdim, ilerde yanınızdaki kitabı onaylayan bir peygamber gelince ona kesinlikle inanacak, kendisini destekleyeceksiniz’ diye söz aldı; ’Bu direktifimi kabul ettiniz, omuzlarınıza yüklediğim bu görevi üstlendiniz mi?’ dedi. ’Kabul ettik’ dediler, Allah da ’Birbirinize şahid olunuz, ben de sizinle birlikte şahidlerdenim’ dedi."},{"n":82,"t":"O halde bundan sonra kim sözünden dönerse onlar fasıkların ta kendileridir."},{"n":83,"t":"Yoksa onlar Allah’ın dininden başka bir din mi arıyorlar? Oysa göklerde ve yerde bulunanların tümü ister- istemez O’na teslim olmuşlardır ve O’nun huzuruna döndürüleceklerdir."},{"n":84,"t":"De ki; Allah ’a, bize indirilen kitaba; İbrahim’e, İsmail’e, İshak’a, Yakub’a ve torunlarına indirilen ilahi mesajlara; Musa’ya, İsa’ya ve diğer peygamberlere Rabbleri tarafından verilenlere inandık; onlar arasında ayırım yapmayız, biz O’na teslim olmuşuz;"},{"n":85,"t":"Kim İslâm’dan başka bir din ararsa, o din ondan kabul edilmez ve ahirette hüsrana uğrayanlardan olur."},{"n":86,"t":"Peygamberin haklı olduğunu gördükleri, kendilerine açık belgeler geldiği halde iman ettikten sonra kafir olanları Allah doğru yola nasıl iletir? Allah zalimleri doğru yola iletmez."},{"n":87,"t":"Böylelerinin cezası; Allah’ın, meleklerin ve tüm insanların lanetine uğramalarıdır."},{"n":88,"t":"Onların bu cezaları süreklidir. Ne azapları hafifletilir ve ne de yüzlerine bakılır."},{"n":89,"t":"Ancak bu sapıtmanın ardından tevbe ederek durumlarını düzeltenler hariç. Çünkü Allah affedici ve merhametlidir."},{"n":90,"t":"İman ettikten sonra kâfir olanlar sonra da kâfirliklerini koyulaştıranlar; bunların tevbeleri kesinlikle kabul edilmez, bunlar sapıkların ta kendileridir."},{"n":91,"t":"Küfredip kâfir olarak ölenlere gelince, bunların hiç birinden yeryüzü dolusu kadar altını fidye olarak verse bile kabul edilmez. Onları acıklı bir azap beklemektedir, hiçbir yardımcı bulamazlar."},{"n":92,"t":"Sevdiğiniz şeylerden infak etmedikçe iyilik mertebesine eremezsiniz. Her ne infak ederseniz, hiç şüphesiz Allah onu bilir."},{"n":93,"t":"İsrail’in (Yakub’un), Tevrat’ın indirilişinden önce kendine yasakladıkları dışında kalan tüm yiyecekler İsrailoğulları’na helâl idi. De ki; ’Eğer doğru söylüyorsanız, Tevrat’ı getirip okuyunuz.’"},{"n":94,"t":"Kim bundan sonra Allah adına yalan uydurursa, bunlar zalimlerin ta kendileridirler."},{"n":95,"t":"De ki; Allah doğru söyledi. Buna göre İbrahim’in dosdoğru dinine uyunuz. O, müşriklerden değildi.’"},{"n":96,"t":"İnsanlar için kurulan ilk ev Mekke’deki bütün canlılar için bereket ve hidayet kaynağı olan (Kâbe)dir."},{"n":97,"t":"Orada apaçık deliller ve İbrahim’in makamı vardır. Kim oraya girerse güvenliğe erer. Ona yol bulabilenlerin Kâbe’ye haccetmesi Allah’ın, insanlar üzerinde hakkıdır. Kim küfrederse bilsin ki Allah alemlerden müstağnidir."},{"n":98,"t":"De ki; ’Ey ehl-i kitap, Allah yaptıklarınızı görüp dururken niye O’nun ayetlerini inkar ediyorsunuz?’"},{"n":99,"t":"De ki; ’Ey ehl-i kitap, niçin Allah’ın yolunu eğri göstermeye yeltenerek inananları o yoldan döndürmeye çalışıyorsunuz? Oysa onun doğru olduğunu biliyorsunuz. Allah yaptıklarınızdan kesinlikle habersiz değildir:"},{"n":100,"t":"Ey müminler, kendilerine kitap verilenlerin bir grubuna uyarsanız bunlar sizi iman ettikten sonra döndürüp kafir yaparlar."},{"n":101,"t":"Allah’ın ayetleri size okunuyorken ve O’nun Peygamberi aranızdayken nasıl kafir olabilirsiniz? Kim Allah’a sımsıkı sarılırsa doğru yola iletilmiş olur."},{"n":102,"t":"Ey müminler, Allah’tan gerektiği gibi korkunuz ve mutlaka müslüman olarak ölünüz."},{"n":103,"t":"Hep birlikte Allah’ın ipine sımsıkı sarılınız sakın ayrılığa düşmeyiniz, Allah’ın size bağışladığı nimeti hatırlayınız. Hani bir zamanlar düşman olduğunuz halde O, kalplerinizi uzlaştırdı da O’nun bu nimeti sayesinde kardeş oldunuz. Hani siz bir ateş kuyusunun tam kenarındayken O sizi oraya düşmekten kurtardı. Allah size ayetlerini işte böyle açık açık anlatır ki, doğru yolu bulasınız."},{"n":104,"t":"Sizden hayra çağıran, iyiliği emredip kötülükten sakındıran bir ümmet olsun. İşte kurtuluşa erenler bunlardır."},{"n":105,"t":"Sakın kendilerine apaçık ayetler geldikten sonra parçalanıp çatışmaya düşenler gibi olmayınız. Böyleleri için büyük bir azap vardır."},{"n":106,"t":"O gün kimi yüzler ağarır, kimi yüzler kararır. Yüzleri kararanlara ’Siz iman ettikten sonra tekrar kâfir mi oldunuz? O halde kafir olmanızın karşılığı olarak bu azabı tadın’ denir."},{"n":107,"t":"Yüzleri ağaranlara gelince, onlar Allah’ın rahmeti içindedirler ve orada sürekli olarak kalacaklardır."},{"n":108,"t":"Bunlar Allah’ın ayetleridir. Onları sana hakk içerikli olarak okuyoruz. Allah kesinlikle alemlere zulmetmek istemez."},{"n":109,"t":"Göklerde ve yerde olanların tümü Allah’ındır. Her işin mercii Allah’tır."},{"n":110,"t":"Siz insanlığın iyiliği için yetiştirilmiş hayırlı bir topluluksunuz. İyiliği emreder, kötülükten sakındırırsınız ve Allah’a inanırsınız. Eğer kitap ehli de inansaydı, elbette bu, kendileri için çok iyi olurdu. İçlerinden iman edenler var, fakat çoğu yoldan çıkmışlardır."},{"n":111,"t":"Onlar size eziyetten başka bir zarar veremezler. Eğer sizinle savaşa girişirlerse arkaya dönüp kaçarlar, sonra onlara yardım eden de bulunmaz."},{"n":112,"t":"Nerede olsalar, onlara aşağılık damgası vurulmuştur. Yalnız, Allah’ın ipine ve insanlar ile yaptıkları antlaşmalara bağlı kalanlar müstesna. Onlar Allah’ın gazabına uğradılar, alınlarına perişanlık damgası vuruldu. Bu, onların Allah’ın ayetlerini inkâr etmeleri ve sebepsiz yere peygamberleri öldürmeleri yüzündendir. Çünkü onlar Allah ’a başkaldırmış ve ölçüleri çiğnemişlerdir."},{"n":113,"t":"Ama onların hepsi bir değildir. Kitap ehlinin içinde geceleri ayakta durup Allah’ın ayetlerini okuyan ve secdeye kapanan bir kesim vardır."},{"n":114,"t":"Bunlar Allah’a ve ahiret gününe inanırlar, iyiliği emrederek kötülükten sakındırırlar, hayırlı işlere koşarlar. Onlar iyi kullardandırlar."},{"n":115,"t":"Onların yaptıkları hiçbir iyilik karşılıksız kalmayacaktır. Hiç kuşkusuz Allah takvalıların kimler olduğunu bilir."},{"n":116,"t":"Kafirlere gelince, ne malları ve ne de evlatları kendilerine Allah’a karşı hiçbir fayda sağlamayacaktır. Onlar Cehennemliktirler, orada sürekli olarak kalacaklardır."},{"n":117,"t":"Onların bu dünya hayatındaki maddi harcamaları, kendilerine zulmetmiş kimselerin tarlası üzerinden eserek bu tarlanın ekinini mahveden dondurucu rüzgara benzer. Allah onlara zulmetmiş değildir, tersine onlar kendi kendilerine zulmetmişlerdir."},{"n":118,"t":"Ey müminler, kendinizden başkasını sırdaş ve dost edinmeyiniz. Olanca güçleri ile size zarar dokundurmaya, dirliğinizi bozmaya çalışırlar, karşılaştığınız her sıkıntı onları sevindirir. Gerçi kinleri ağızlarından taşmıştır ama kalplerinde saklı tuttukları kin daha büyüktür. Eğer düşünecek olursanız size ayetlerimizi açık açık anlattık."},{"n":119,"t":"İşte siz öyle kimselersiniz ki, onları seversiniz, oysa onlar sizi sevmezler; bir de kitabın tümüne inanırsınız. Onlar sizinle karşılaştıklarında ’inandık’ derler fakat kendi başlarına kaldıkları zaman size duydukları öfke yüzünden parmak uçlarını ısırırlar. De ki; ’Öfkenizden ölün (çatlayın). Hiç şüphesiz Allah kalplerin içini dışını bilir.’"},{"n":120,"t":"Size bir iyilik ulaşırsa onları huzursuz eder. Ama size bir kötülük dokunduğunda bundan dolayı rahatlarlar. Eğer sabreder ve sakınırsanız onların oyunlarının size bir zararı dokunmaz. Allah onların yapmakta olduklarını (ilmiyle) kuşatmıştır."},{"n":121,"t":"Hani sen müminleri (Uhud’da) savaşacakları elverişli yerlere mevzilendirmek üzere evinden sabahleyin erken çıkmıştın. Hiç kuşkusuz Allah herşeyi işiten ve bilendir."},{"n":122,"t":"Hani sizden iki grupta yılgınlık ve çözülme emareleri belirmişti. Oysa onların dostu Allah’tı. Müminler, sırf Allah’a dayanmalıdırlar."},{"n":123,"t":"Nitekim Bedir’de Allah sizi zafere ulaştırdı, oysa siz zayıftınız. O halde Allah’tan korkunuz, O’na şükretmiş olasınız."},{"n":124,"t":"Hani sen müminlere ’Allah’ın gökten indirilmiş üç bin melekle yardım etmesi size yetmez mi?’ diyordun."},{"n":125,"t":"Evet, eğer siz sabreder ve Allah’tan korkarsanız, bu arada onlar şimdi, şu taraftan üzerinize saldırırlarsa Allah size beşbin nişanlı melekle yardım eder."},{"n":126,"t":"Allah size bu yardımı sırf size müjde olsun ve bu sayede kalpleriniz rahatlasın diye yaptı. Yoksa zafer, sadece üstün iradeli ve hikmet sahibi olan Allah’tan kaynaklanır."},{"n":127,"t":"Allah kafirlerin bir bölümünü kırıma uğratmak ya da bozguna düşürüp umutsuz biçimde geri dönmelerini sağlamak için size zafer kazandırdı."},{"n":128,"t":"Bu konuda senin yapabileceğin birşey yok. Allah ya onların tevbelerini kabul eder ya da zalimlikleri yüzünden onları azaba çarptırır."},{"n":129,"t":"Göklerde ve yerde ne varsa hepsi Allah’ındır. O dilediğini affeder, dilediğini de azaba çarptırır. Hiç kuşkusuz Allah affedici ve merhametlidir."},{"n":130,"t":"Ey müminler, sakın sürekli katlanan faizi yemeyiniz. Allah’tan korkunuz ki, kurtuluşa erebilesiniz."},{"n":131,"t":"Kafirler için hazırlanmış olan cehennem ateşinden sakınınız."},{"n":132,"t":"Allah’a ve Peygamber’e itaat ediniz ki rahmete kavuşabilesiniz."},{"n":133,"t":"Rabbinizin affediciliğine ve genişliği gökler ile yer arası kadar olan Cennete koşunuz. Burası takvalılar için hazırlanmıştır."},{"n":134,"t":"Onlar bollukta ve darlıkta Allah için mal harcarlar, öfkelerini yenerler ve insanların kusurlarını bağışlarlar. Hiç kuşkusuz Allah iyilikseverleri sever."},{"n":135,"t":"Yine onlar bir kötülük işlediklerinde ya da kendilerine zulmettiklerinde Allah’ı hatırlayarak hemen günahlarının affedilmesini dilerler. Günahları Allah’tan başka kim affedebilir? Onlar işledikleri günahlarda bile bile ısrar etmezler."},{"n":136,"t":"İşte onların mükafatı, Allah tarafından affedilmek ve altından ırmaklar akan, içinde sürekli kalacakları Cennetlerdir. İyi işler yapanları bekleyen mükafat ne kadar güzeldir!"},{"n":137,"t":"Sizden önce ilahi yasaların değişmezliğini kanıtlayan birçok olaylar gelip geçti. Yeryüzünü geziniz ve Allah’ın ayetlerini yalan sayanların akıbetini görünüz."},{"n":138,"t":"Bu Kur’an, insanlara yönelik bir açıklama, takvalılar için bir doğru yol kılavuzu, bir öğüttür."},{"n":139,"t":"Sakın gevşemeyiniz, karamsarlığa kapılmayınız. Eğer mümin iseniz üstün gelecek olan taraf sizlersiniz."},{"n":140,"t":"Eğer siz (Uhud’da) yara aldınız ise karşınızdakiler de benzeri bir yara almışlardır. Biz bu tür acı günleri insanlar arasında dolaştırırız. Allah’ın kimlerin mümin olduklarını belirlemesi ve aranızdan bazı şahitler seçmesi içindir bu. Hiç kuşkusuz Allah zalimleri sevmez."},{"n":141,"t":"Bunun bir başka sebebi Allah’ın, müminleri arındırması ve kâfirleri yok etmesidir."},{"n":142,"t":"Yoksa siz, Allah içinizdeki cihad edenleri ayırd etmeden ve sabırlıları belirlemeden Cennete girebileceğinizi mi sandınız?"},{"n":143,"t":"Sizler ölümle karşılaşmadan önce onu arzuluyordunuz. Oysa onu görünce bakıp duruyorsunuz."},{"n":144,"t":"Muhammed sadece bir peygamberdir. Ondan önce daha nice peygamberler gelip geçmiştir. Şimdi eğer o ölür ya da öldürülürse topuklarınız üzerinde geri mi döneceksiniz? Kim iki topuğu üzerinde geri dönerse bilsin ki, Allah’a hiçbir zarar vermez. Allah şükredenleri ödüllendirecektir."},{"n":145,"t":"Allah’ın izni olmaksızın hiç kimsenin ölmesi söz konusu değildir. O süresi belirli bir yazıya bağlıdır. Kim dünya kazancını isterse ona ondan veririz. Kim ahiret sevabını isterse ona da ondan veririz. Biz şükredenleri ödüllendireceğiz."},{"n":146,"t":"Nice peygamber var ki, çok sayıda taraftarı kendisi ile birlikte savaştı. Bunlar Allah yolunda başlarına gelenlerden dolayı gevşemediler, yılmadılar ve boyun eğmediler. Allah sabırlıları sever."},{"n":147,"t":"Onlar sadece «Ey Rabbimiz, günahlarımızı ve davranışlarımızdaki aşırılıklarımızı affeyle, ayaklarımızı kaydırma ve kâfirler karşısında bize yardım et» demişlerdir."},{"n":148,"t":"Allah da onlara hem dünya kazancını ve hem de ahiret mükâfatının en güzelini verdi. Allah iyi işler yapanları sever."},{"n":149,"t":"Ey müminler, eğer kâfirlere itaat ederseniz sizleri topuklarınız üzerinde geriye döndürürler de hüsrana uğrarsınız."},{"n":150,"t":"Oysa Allah’tır sizin mevlânız. O yardım edenlerin en hayırlısıdır."},{"n":151,"t":"Biz kâfirlerin kalplerine korku salacağız. Çünkü onlar kendilerine hiçbir güç verilmemiş olan nesneleri Allah ’a ortak koşmuşlardır. Onların gidecekleri yer Cehennem’dir. Zalimlerin varacağı yer ne fenadır!"},{"n":152,"t":"Allah size verdiği sözü yerine getirdi. Hani size sevdiğinizi (zaferi) gösterdikten sonra bozuluncaya, savaş konusunda görüş ayrılığına düşünceye ve itaatsizlik edinceye kadar müşrikleri kırıp geçiriyordunuz. Kiminiz dünyayı istiyordu, kiminiz de ahireti istiyordu. Sonra sizi deneyden geçirmek için onların başından savdı. Ama yine de sizi affetti. Allah müminlere karşı gerçekten lütuf sahibidir."},{"n":153,"t":"Hani Peygamber arkanızdan sizi çağırırken, hiç kimseye bakmadan kaçıyordunuz; ne kaybettiğinize ve ne de başınıza gelene üzülmeyesiniz diye Allah sizi kederden kedere uğrattı. Hiç kuşkusuz Allah yaptıklarınızdan haberdardır."},{"n":154,"t":"\"Evlerinizde olsaydınız üzerlerine ölüm yazılmış olanlar; yine muhakkak devrilecekleri yerlere çıkıp gidecektiler.\" Bu, göğüslerinizin içindekini yoklamak, kalplerinizdekini temizlemek içindir. Ve Allah, sinelerdekini hakkıyla bilir."},{"n":155,"t":"İki topluluğun karşılaştığı gün savaştan geri dönenlerinizi şeytan bazı günahkar duyguları yüzünden ayartmaya girişmişti. Ama Allah onları yine de affetti. Hiç kuşkusuz Allah affedici ve halimdir."},{"n":156,"t":"Ey müminler, yolculuğa çıkan ya da savaşa katılan kardeşleri hakkında «Eğer onlar yanımızda olsalardı ölmezler ya da öldürülmezlerdi» diyen kâfirler gibi olmayınız. Allah bu asılsız saplantıyı onların kalplerine çöreklenen acı bir hayıflanmaya dönüştürdü. Oysa can veren de öldüren de Allah’tır. Hiç kuşkusuz Allah yaptıklarınızı görür."},{"n":157,"t":"Eğer Allah yolunda öldürülür ya da ölürseniz, Allah’tan gelecek olan bağışlama ve rahmet, onların biriktirecekleri dünya nimetlerinden daha hayırlıdır."},{"n":158,"t":"Kuşku yok ki, ölseniz de öldürülseniz de Allah katında toplanacaksınız."},{"n":159,"t":"Allah’tan gelen merhamet sayesinde onlara yumuşak davrandın. Eğer sert, katı kalpli biri olsaydın, kuşkusuz çevrenden uzaklaşırlardı. Onları bağışla, kendileri için Allah’tan af dile, yapacağın işler hakkında onların görüşlerini al, ama karar verince artık Allah’a dayan. Hiç kuşkusuz Allah kendisine dayananları sever."},{"n":160,"t":"Eğer Allah size yardım ederse sizi hiç kimse yenemez. Fakat eğer sizi yüzüstü bırakırsa O’ndan başka size kim yardım edebilir? Müminler sadece Allah’a dayansınlar."},{"n":161,"t":"Bir peygamber için emanete hıyanet etmek olur şey değildir. Kim, böyle hainlik ederse, kıyamet günü bu hainlik ettiği şey ile gelir. Sonra herkese kazanmış olduğu şey ödenir. Ve onlara zulmedilmez."},{"n":162,"t":"Allah’ın rızasına uyan kimse, Allah’ın gazabına uğrayan kimse gibi olur mu? Onun varacağı yer Cehennem’dir. Orası ne kötü bir varış yeridir!"},{"n":163,"t":"Onların Allah katındaki dereceleri farklıdır. Allah onların neler yaptıklarını görmektedir."},{"n":164,"t":"Allah, müminlere kendi özlerinden bir peygamber göndermekle onlara karşı lütufta bulundu. Bu peygamber onlara Allah’ın ayetlerini okuyor, onları arındırıyor, kendilerine kitabı ve hikmeti öğretiyor. Oysa onlar daha önce açık bir sapıklık içinde idiler."},{"n":165,"t":"Karşı tarafa iki katını tattırdığımız musibet, bu kez sizin başınıza gelince «Bu nereden geldi?» demediniz mi? De ki; «O musibet kendinizden kaynaklandı.» Hiç şüphesiz Allah’ın gücü herşeye yeter."},{"n":166,"t":"İki topluluğun karşılaştığı gün başınıza gelen musibet, Allah’ın izni ile gerçekleşti. Bu musibet, Allah’ın müminleri belirlemesi için meydana geldi."},{"n":167,"t":"Bir de münafıkları ayırd etmesi içindi. Onlara «Geliniz, Allah yolunda savaşınız, ya da savunma yapınız» denince «Eğer savaşmayı bilseydik, mutlaka peşinizden gelirdik» dediler. O gün onlar imandan çok küfre yakındılar. Kalplerinde olmayan şeyi ağızları ile söylüyorlardı. Hiç kuşkusuz Allah, onların gizli tuttukları duyguları çok iyi bilir."},{"n":168,"t":"Onlar, evlerinde oturup savaşa katılan kardeşleri için «Eğer bizim sözümüzü dinleselerdi, öldürülmezlerdi» diyenlerdir. De ki; «Eğer doğru söylüyorsanız, ölümü kendi başınızdan savın bakalım.»"},{"n":169,"t":"Sakın Allah yolunda öldürülenleri ölü sanmayınız, tersine onlar yaşıyor ve Allah katında besleniyorlar."},{"n":170,"t":"Allah’ın, keremiyle kendilerine sunduğu nimetlerden dolayı sevinç içindedirler. Arkadaki henüz kendilerine katılmamış olanlar için korku ve üzüntü söz konusu değil diye onlar adına sevinçlidirler."},{"n":171,"t":"Onların sevinci Allah’tan gelen nimet ve lütuf ile O’nun müminlerin mükâfatını kayba uğratmayacağı müjdesinden kaynaklanıyor."},{"n":172,"t":"O müminler ki, yaralandıktan sonra Allah’ın ve peygamberin savaşma çağrısına uydular, onlardan «İhsan» (Allah’ı görüyormuş gibi ibadet etmek - Mütercim-) ilkesine uyanlar ile takva sahiplerini büyük bir ödül beklemektedir."},{"n":173,"t":"O kimseler ki, insanlar kendilerine «Düşmanlarınız size saldırmak için yığınak yaptılar, onlardan korkmalısınız» dediklerinde, bu sözden imanları daha güçlenerek ’Allah bize yeter, O ne güzel bir vekildir» dediler."},{"n":174,"t":"Bundan dolayı Allah’tan gelen nimet ve lütufla geri döndüler, kendilerine hiçbir zarar dokunmadı, Allah’ın rızasına uydular. Hiç kuşkusuz Allah büyük lütuf sahibidir."},{"n":175,"t":"O şeytan sizi yardakçıları ile korkutur, o halde eğer gerçekten mümin iseniz onlardan değil, benden korkunuz."},{"n":176,"t":"Doludizgin küfre koşanlar seni üzmesin. Onlar Allah’a hiçbir zarar veremezler. Allah onlara hiçbir pay bırakmamayı diliyor. Onları büyük bir azap bekliyor."},{"n":177,"t":"İman karşılığında kâfirliği satın alanlar Allah’a hiçbir zarar veremezler. Onları acıklı bir azap bekliyor."},{"n":178,"t":"Kulluk sözleşmesindeki ortak taahhütlerini, Allah’a iman, kulluk ve sorumluluk bilincini şuur altına iterek örtbas edip inkârda ısrar edenler, kâfirler, kendilerine vereceğimiz mühletin, haklarında hayırlı olduğunu sanmasınlar. Bilerek işledikleri günahlarını, zararlarını artırsınlar diye, biz onlara mühlet veriyoruz. Onlara, alçaltıcı, zillete düşürücü bir azap vardır."},{"n":179,"t":"Allah müminleri, şimdi içinde bulunduğunuz durumda bırakacak değildir, pis olanı temiz olandan ayıracaktır. Ayrıca Allah sizi, gaybın bilgisine de erdirecek değildir. Fakat Allah bunun için peygamberlerinden dilediğini seçer. O halde Allah’a ve O’nun peygamberlerine inanınız. Eğer iman eder ve günahlardan sakınırsanız size büyük bir ödül vardır."},{"n":180,"t":"Allah’ın lütuf olarak bağışladığı şeylerde cimrice davrananlar sakın bu tutumlarının kendileri hesabına hayırlı olduğunu sanmasınlar. Tersine bu, onlar hesabına kötüdür. Cimrilikle yanlarında tuttukları mal kıyamet günü boyunlarına dolanacaktır. Göklerin ve yeryüzünün mirası Allah’a aittir. Hiç kuşkusuz Allah yaptıklarınızdan haberdardır."},{"n":181,"t":"Allah fakir, biz ise zenginiz diyenlerin sözünü Allah işitti. Gerek bu sözlerini ve gerekse sebepsiz yere peygamberleri öldürmelerini hesaplarına yazacak ve onlara «Kavurucu azabı tadın bakalım» diyeceğiz."},{"n":182,"t":"Bu kendi elleriniz ile yaptıklarınız yüzündendir. Yoksa Allah’ın, kullara haksızlık etmesi kesinlikle söz konusu değildir."},{"n":183,"t":"Ateşin yakıp yiyeceği bir kurban mucizesi göstermedikçe hiçbir peygambere inanmayalım diye Allah bize kesin direktif verdi diyenlere de ki; «Benden önce size açık belgeler getiren ve sözünü ettiğiniz mucizeyi gösteren peygamberler geldi. Eğer doğru söylüyorsanız, onları niçin öldürdünüz?»"},{"n":184,"t":"Bunlar eğer seni yalanlıyorlarsa (bilesin ki) senden önce açık mucizeler, sayfalar ve aydınlatıcı kitap getiren birçok peygamberi de yalanlamışlardı."},{"n":185,"t":"Herkes kesinlikle ölümü tadacaktır. Yaptıklarınızın karşılıkları, kıyamet günü, size eksiksiz olarak verilecektir. O zaman kim Cehennem ateşinden uzak tutulur da Cennet’e konursa gerçekten başarıya ulaşmıştır. Dünya hayatı aldatıcı bir hazdan başka birşey değildir."},{"n":186,"t":"Mallarınız ve canlarınız konusunda kesinlikle deneyden geçirileceksiniz, gerek kitap ehlinden ve gerekse müşriklerden birçok incitici söz işiteceksiniz. Eğer (bunlara karşı) sabreder ve Allah’tan korkarsanız, bu tutum azimliliğinizin, kesin kararlılığınızın bir belirtisidir."},{"n":187,"t":"Hani Allah, kendilerine kitap verilenlerden «Bu kitabı insanlara mutlaka açıklayacaksınız, onu asla saklamayacaksınız» diye söz almıştı. Fakat onlar bu sözlerine sırt çevirerek o kitabı birkaç paraya sattılar. Almış oldukları o karşılık ne kötü bir şeydir!"},{"n":188,"t":"Yaptıklarına sevinen ve yapmadıklarına karşılık övülmekten hoşlananlar var ya, sakın onların azaptan kurtulabileceklerini sanma, onları acıklı bir azap beklemektedir,"},{"n":189,"t":"Göklerin ve yeryüzünün egemenliği Allah’ın tekelindedir. Hiç kuşkusuz Allah’ın gücü herşeye yeter."},{"n":190,"t":"Göklerin ve yeryüzünün yaratılışında, gece ile gündüzün birbirini kovalayışında derin düşünceliler için birçok ibret dersi vardır."},{"n":191,"t":"Onlar ayakta, otururken ve yatarken Allah’ı anarlar; göklerin ve yeryüzünün yaratılışı hakkında kafa yorarlar ve derler ki; «Ey Rabbimiz, sen bu evreni boşuna yaratmadın, sen (böyle bir anlamsızlıktan) münezzehsin, bizi Cehennem azabından koru!"},{"n":192,"t":"Ey Rabbimiz, sen birini Cehennem’e atınca onu perişan edersin. Zalimlerin hiçbir yardım edeni yoktur."},{"n":193,"t":"\"Rabbinize iman edin\" diye imana çağrıda bulunan bir çağırıcıyı işittik, hemen iman ettik. Rabbimiz, bizim günahlarımızı bağışla, kötülüklerimizi ört ve bizi de iyilik yapanlarla birlikte öldür.\""},{"n":194,"t":"Ey Rabbimiz, peygamberlerinin ağzından vaad ettiklerini bize ver, kıyamet günü bizi perişan etme, kuşku yok ki sen sözünden caymazsın.»"},{"n":195,"t":"Rabbleri onlara cevap verdi ki; «Ben birbirinizden meydana gelmiş bir bütün oluşturan sizlerden, erkek- kadın, hiçbir iyi amel işleyenin emeğini boşa çıkarmam. Buna göre göç edenlerin, yurtlarından sürülenlerin, benim yolumda eziyet çekenlerin, savaşanların ve öldürülenlerin kusurlarını örtecek ve kendilerini Allah tarafından verilmiş bir ödül olarak altlarından ırmaklar akan Cennetlere koyacağım. Ödüllerin güzeli yalnız Allah katındadır."},{"n":196,"t":"Kafirlerin (zevk içinde) diyar diyar gezinmeleri sakın seni aldatmasın."},{"n":197,"t":"Sadece az bir hazdır bu. Sonra varacakları yer Cehennem’dir. Orası ne kötü bir barınaktır!"},{"n":198,"t":"Fakat Rabblerinden korkanlar için altlarından ırmaklar akan Cennetler vardır. Onlar Allah’ın konukları olarak orada süresiz kalacaklardır. Allah’ın iyi kullara yönelik mükafatı daha hayırlıdır."},{"n":199,"t":"Kuşkusuz kitap ehlinden Allah’a size indirilen ve kendilerine indirilmiş olan mesaja, Allah korkusu içinde, inananlar, Allah’ın ayetlerini birkaç paraya satmayanlar vardır. Bunlar Rabbleri katında ödüllerini alacaklardır. Hiç şüphesiz Allah’ın hesaplaşması pek çabuktur."},{"n":200,"t":"Ey müminler, sabırlı olunuz, sabır yarışında düşmanlarınızı geride bırakınız, sürekli savaşa hazırlıklı olunuz ve Allah’tan korkunuz ki, kurtuluşa eresiniz."}],[{"n":1,"t":"Ey insanlar, Rabbinizden korkunuz. Ki O sizi tek bir kişiden türetti, o tek kişinin eşini de kendi özünden yarattı, sonra bu çiftten çok sayıda erkek ve kadın meydana getirerek yeryüzüne yaydı. Karşılıklı dileklerinizi adına bağladığınız Allah’tan ve akrabalık bağlarını çiğnemekten sakınınız. Hiç kuşkusuz Allah sizi sürekli gözetmektedir."},{"n":2,"t":"Yetimlere mallarını veriniz, temiz malı murdarı ile değiştirmeyiniz, onların mallarını kendi mallarınıza katarak yemeyiniz, çünkü bu büyük bir vebaldir."},{"n":3,"t":"Eğer gözetiminiz altındaki yetim kızları ile evlendiğiniz takdirde onların haklarını gerektiği gibi gözetemeyeceğinizden korkarsanız size nikahı düşen kadınlardan ikisi, üçü ya da dördü ile evlenebilirsiniz. Ama eğer onlar arasında adil davranamayacağınızdan korkarsanız tek kadınla evleniniz, ya da eliniz altındaki cariye ile yetininiz. Haksızlığa düşmemeniz için en uygun hareket budur."},{"n":4,"t":"Kadınların mehirlerini gönül hoşnutluğu ile veriniz. Fakat eğer onlar mehirlerinin bir bölümünü gönüllü olarak size bağışlarlar ise bunu afiyetle yiyiniz."},{"n":5,"t":"Allah’ın, sizi başına diktiği malları aptalların (aklî dengesi yerinde olmayanların) ellerine vermeyiniz. Fakat onları bu mallardan besleyiniz, giydiriniz ve kendilerine güzel söz söyleyiniz."},{"n":6,"t":"Yetimleri evlenme çağına gelene kadar deneyiniz. Eğer olgunlaştıklarını görürseniz hemen mallarını kendilerine teslim ediniz. Yetimler büyüyecek endişesi ile bu malları savurganca yemeyiniz. Zengin veliler bu mallara hiç el sürmesin. Fakir veliler ise bu malların geleneklere uygun düşecek kadarını yesin. Yetimlere mallarını teslim ederken yanınızda şahit bulundurunuz. Gerçi hesap sorma merci olarak Allah yeterlidir."},{"n":7,"t":"Ana- babanın ve yakın akrabaların bıraktıkları mirasta erkeklerin payı olduğu gibi kadınların da payı vardır. Bu miras ister az, ister çok olsun, onda erkeğin ve kadının belirlenmiş payları vardır."},{"n":8,"t":"Eğer miras bölüşümü sırasında pay sahibi olmayan uzak akrabalar, yetimler ve yoksullar hazır bulunursa onlara da bir şeyler veriniz ve kendilerine gönül alıcı sözler söyleyiniz."},{"n":9,"t":"Arkalarında güçsüz çocuklar bırakıp ölecek olsalar çocuklarının hali nice olur diye kaygı duyanlar yetimlere haksızlık etmekten korksunlar, Allah’tan sakınsınlar ve doğru konuşsunlar."},{"n":10,"t":"Yetimlerin mallarını haksız biçimde yiyenler, midelerini ateşle doldurmaktan başka birşey yapmıyorlar. Zaten kudurmuş alevlerin içine atılacaklardır."},{"n":11,"t":"Erkeğe iki dişinin hissesi kadardır. Eğer kadınlar ikinin üstünde ise bırakılan malların üçte ikisi onlarındır. Şayet tek ise yarısı onundur. Ölenin çocuğu varsa, ana ve babadan her birine bırakılan malın altıda biri. Çocuğu olmayıp da ona ana ve babası mirasçı olduysa üçte biri anasınındır. Kardeşleri varsa o vakit altıda biri anasınındır. Bu hükümler, ölenin borcu ödenip, yaptığı vasiyetler yerine getirildikten sonradır. Siz, babalarınızdan ve oğullarınızdan hangisinin size fayda bakımından daha yakın olduğunu bilmezsiniz. Bunlar, Allah’tan birer farizadır. Doğrusu Allah; hakkıyla bilen ve Hakim olandır."},{"n":12,"t":"Karılarınızın çocukları yoksa geriye bıraktıklarının yarısı sizindir. Çocukları varsa bıraktıklarının dörtte biri sizindir. Bunlar yaptıkları vasiyet ve borç ödendikten sonradır. Sizin çocuğunuz yoksa bıraktıklarınızın dörtte biri karılarınızındır. Şayet çocuğunuz varsa bıraktıklarınızın sekizde biri onlarındır. Ancak bu, yaptığınızı vasiyet ve borç ödendikten sonradır. Eğer mirası aranan erkek veya kadın çocuğu ve babası olmayan bir kimse olur da onun erkek veya kız kardeşi bulunursa bunların her birine altıda bir düşer. Eğer onlar ikiden çoksalar zarara uğratılmaksızın üçte birine ortak olurlar. Bunlar yaptıkları vasiyet ve borcu ödendikten sonradır. Bunlar, Allah’tan bir vasiyet ve emirdir. Ve Allah, Alim’dir, Halim’dir."},{"n":13,"t":"Bunlar Allah’ın koyduğu sınırlardır. Kim Allah’a ve Peygamber’e itaat ederse Allah onları içinde ebedi olarak kalacakları, altlarından ırmaklar akan Cennetlere yerleştirir. İşte büyük kurtuluş, büyük başarı budur."},{"n":14,"t":"Buna karşılık kim Allah’a ve Peygamber’e karşı gelir, O’nun çizdiği sınırları aşarsa Allah onu, içinde ebedi olarak kalmak üzere Cehennem’e atar. Onun için onur kırıcı bir azap vardır."},{"n":15,"t":"Zina suçu işleyen kadınlarınızın aleyhinde dört kişinin şahitliklerine başvurunuz. Eğer dört kişi aleyhte şahitlik ederse o kadınları, ölünceye kadar ya da Allah kendileri hakkında başka bir yol gösterinceye kadar evlerinizden dışarı salmayınız."},{"n":16,"t":"Zina suçu işleyen çiftin her ikisini de eziyetli cezaya çarptırınız. Fakat eğer tevbe eder de uslanırlarsa artık yakalarını bırakınız. Çünkü Allah tevbeleri kabul eder ve merhametlidir."},{"n":17,"t":"Allah, kötülüğü bilmeyerek işleyip de fazla geç kalmaksızın tevbe edenlerin tevbelerini kabul edeceğini vaad etmiştir. Hiç kuşkusuz Allah herşeyi bilir ve hikmet sahibidir."},{"n":18,"t":"Yoksa sürekli kötülük yapıp dururken ölümün eşiğine gelince «Şimdi tevbe ettim» diyenler ile kâfir olarak ölenlerin tevbesi geçerli değildir. Biz böyleleri için acı bir azap hazırladık."},{"n":19,"t":"Ey müminler, akrabalarınızın dul eşlerini zorla nikahlamanız helal değildir. İspatlanmış bir edepsizlik işlemedikleri sürece kendilerine verdiğiniz mehrin bir kısmını geri almak amacı ile onlara baskı yapmayınız. Onlara karşı iyi davranınız. Eğer onlardan hoşlanmıyorsanız, biliniz ki; hoşlanmadığınız birşeyi Allah hakkınızda çok hayırlı kılmış olabilir."},{"n":20,"t":"Eğer eşinizi bırakıp başka bir kadınla evlenmek isterseniz önceki eşinize gayet yüklü miktarda bir mehir vermiş olsanız bile bundan hiçbir şey geri almayınız. Yoksa kadına iftira atarak ve apaçık bir günaha girerek mi verdiğinizi geri alacaksınız?"},{"n":21,"t":"Verdiğinizi nasıl geri alırsınız ki, sizler birbirinizle içli- dışlı olmuşsunuz ve onlar sizden güçlü bir güvence almışlardır."},{"n":22,"t":"Geçmiş uygulamalar bir yana, bundan böyle babalarınızın evlenmiş olduğu kadınlar ile evlenmeyiniz. Bu bir edepsizlik, iğrenç bir hareket ve son derece çirkin bir gelenektir."},{"n":23,"t":"Analarınız, kızlarınız, kızkardeşleriniz, halalarınız, teyzeleriniz, kardeş kızları, kızkardeş kızları, sizi emziren analarınız, süt bacılarınız, eşlerinizin anaları, kendileriyle birleştiğiniz eşlerinizden olup evlerinizde bulunan üvey kızlarınız size haram kılındı. Eğer onlarla (nikâhlanıp da) henüz birleşmemişseniz kızlarını almanızda size bir mahzur yoktur. Kendi sulbünüzden olan oğullarınızın eşleri ve iki kız kardeşi birden almak da size haram kılındı; ancak geçen geçmiştir. Allah çok bağışlayıcı ve esirgeyicidir."},{"n":24,"t":"Savaş tutsağı olarak elinize geçmiş cariyeler dışında evli kadınlar ile evlenmeniz haramdır. Bunlar Allah’ın üzerinize yazdığı yasaklardır. Bunların dışında kalan kadınları iffetli yaşamanız, zina işlememeniz şartı ile mehirlerini vererek nikahlamanız size helâl kılındı. Bu kadınlardan sağladığınız faydanın karşılığı olarak kendilerine aranızda kararlaştırdığınız mehirlerini hakları olarak veriniz. Daha önce belirlenen mehri eşinizle anlaşarak yeni bir miktara bağlamanızın sakıncası yoktur. Hiç kuşkusuz Allah herşeyi bilir ve hikmet sahibidir."},{"n":25,"t":"İçinizden mâli durumu mümin ve özgür kadınlarla evlenmeye elverişli olmayanlar, ellerininizde bulunan mümin cariyeler ile evlensinler. Hanginizin imanı olduğunu en iyi Allah bilir. Hepiniz aynı soydansınız. Onlarla; namuslu olmaları, zinadan uzak durmaları ve gizli dost tutmamış olmaları halinde velilerinden izin alarak evleniniz. Ve kendilerine geleneğe uyacak miktarda mehir veriniz. Eğer evli iken zina işlerlerse kendilerine özgür kadınlara verilecek cezanın yarısını uygulayınız. Bu, içinizden günaha gireceklerinden korkanlara tanınan bir imkândır. Yoksa eğer sabrederseniz sizin için daha iyi olur. Allah affedici ve merhametlidir."},{"n":26,"t":"Allah size, helâl ile haramı açıkça bildirmek, sizden öncekilerin yararlı geleneklerini tanıtmak ve günahlarınızı bağışlamak ister. Allah herşeyi bilir ve hikmet sahibidir."},{"n":27,"t":"Allah sizin tevbelerinizi kabuk etmek ister. Oysa nefislerinin arzuları peşinden koşanlar sizin büyük bir sapıklığa düşmenizi isterler.."},{"n":28,"t":"Allah yükümlülüklerinizi hafifletmek ister. Çünkü insan zayıf yaratılmıştır."},{"n":29,"t":"Ey müminler, birbirinizin mallarını gayrı meşru yollar kullanarak değil, karşılıklı anlaşmaya dayalı ticaret yolu ile yiyiniz, kendinizi öldürmeyiniz. Hiç şüphesiz Allah size karşı merhametlidir."},{"n":30,"t":"Kim zulüm ve saldırganlık yolu ile böyle yaparsa ilerde onu Cehennem ateşine atacağız. Bunu yapmak Allah için gayet kolaydır."},{"n":31,"t":"Eğer size yasaklanan büyük günahlardan kaçınırsanız, küçük günahlarınızı bağışlar ve sizi onurlu bir konuta yerleştiririz."},{"n":32,"t":"Aranızda derece farkı doğuran ilahi bağışlara özlem beslemeyiniz. Erkekler kazançlarından pay aldıkları gibi kadınlar da kazançlarından pay alırlar. İstediklerinizi Allah’ın kereminden isteyiniz. Hiç şüphesiz Allah her şeyi bilir."},{"n":33,"t":"Kadın erkek herkese ana babaların, akrabaların ve yeminli sözleşmeler yaptığınız kimselerin miraslarından pay ayırdık. Bu pay sahiplerine paylarını veriniz. Hiç şüphesiz Allah her şeyin şahididir."},{"n":34,"t":"Allah’ın kimini kimine üstün kılmasından ötürü ve erkeklerin, mallarından sarf etmelerinden dolayı erkekler kadınlar üzerine hakimdirler. İyi kadınlar; gönülden boyun eğerler ve Allah’ın korunmasını emrettiğini, kocasının bulunmadığı zaman da koruyanlardır. Serkeşlik etmelerinden endişelendiğiniz kadınlara önce öğüt verin. Uslanmazlarsa, kendilerini yataklarında yalnız bırakın. Yine dinlemezlerse dövün. Size itaat ettikleri takdirde incitmeye bir bahane aramayın. Çünkü Allah çok yücedir, çok büyüktür."},{"n":35,"t":"Eğer karı kocanın arasının açılmasından endişe ederseniz onlara biri erkeğin ve öbürü kadının akrabası olan iki arabulucu gönderiniz. Eğer bu arabulucular karı-kocayı barıştırmak isterlerse Allah onların arasını bulur. Hiç şüphesiz Allah herşeyi bilir ve herşeyden haberdardır."},{"n":36,"t":"Allah’a kulluk ediniz. O’na hiçbir şeyi ortak koşmayınız. Ana-babaya akrabalara, yetimlere, yoksullara, yakın komşulara, uzak komşulara, yakın arkadaşlara, yarı yolda kalanlara, elinizin altındakilere iyilik ediniz. Allah kendini beğenmiş kibirlileri kesinlikle sevmez."},{"n":37,"t":"Bunlar kendileri cimrice davrandıkları gibi başkalarına da cimri olmayı önerirler ve Allah’ın lütuf eseri olarak kendilerine verdiği imkânları gizlerler. Biz kâfirler için onur kırıcı bir azap hazırladık."},{"n":38,"t":"Yine bunlar başkalarına gösteriş olsun diye mal verirler, Allah’a ve ahiret gününe inanmazlar. Yoldaşı şeytan olanın ne kötü yoldaşı vardır!"},{"n":39,"t":"Eğer onlar Allah’a ve ahiret gününe inansalar ve Allah’ın kendilerine bağışladığı mallarının bir bölümünü hayr yolunda harcasalardı, ne olurdu? Hiç kuşkusuz Allah onların yaptıkları her şeyi bilir."},{"n":40,"t":"Hiç şüphesiz Allah zerre kadar haksızlık etmez. Eğer bu bir iyilik olursa onu bir kaç kat büyütür ve karşılığında kendi katından büyük bir mükâfat verir."},{"n":41,"t":"Her ümmete karşı birer şahid tutacağımız ve seni de kendilerine karşı birer şahid tutacağımız ve seni de kendilerine karşı şahit göstereceğimiz gün acaba onların halleri nasıl olacak?"},{"n":42,"t":"Kâfirler ve Peygamberlere karşı gelenler o gün yerle bir olmayı özlemle isterler. Onlar Allah’tan hiçbir söz saklayamazlar."},{"n":43,"t":"Ey iman edenler! Sarhoşken, ne söylediğinizi bilinceye kadar, bir de cünüpken -yolcu olmanız müstesna- gusül yapmadıkça namaza yaklaşmayın. Eğer hasta veya yolculukta iseniz, yahut herhangi biriniz ayak yolundan gelmişse veya kadınlara yaklaşmışsanız ve bu durumlarda su bulamamışsanız pak bir toprağa teyemmüm edin, yüzlerinize ve ellerinize sürün. Şüphesiz ki Allah, çok affedici, çok bağışlayıcıdır."},{"n":44,"t":"Şu kendilerine kitaptan bir pay verdiklerimizi görmüyor musun? Bunlar sapıklığı satın alıyorlar ve sizin de yoldan çıkmanızı istiyorlar."},{"n":45,"t":"Allah düşmanlarınızı çok iyi bilir. Size bir velî, bir koruyucu, emrinde olduğunuz bir otorite olarak Allah yeter. Size bir yardım eden olarak da Allah yeter."},{"n":46,"t":"Yahudiler içinde öyleleri var ki, bu dine hakaret etmek amacı ile Tevrat’taki kelimeleri değiştirerek ve dillerini ağız boşluklarında burarak «işittik ve karşı geldik», «Dinle sözü dinlenmez olasıca!» ve «Raina (Bizi gözet anlamına da gelen eş sesli bir hakaret deyimi)» derler. Oysa eğer (böyle diyecekleri yerde) «duyduk ve uyduk», «işit» ve «bize bak» deselerdi kendileri hesabına daha hayırlı ve tutarlı olurdu. Fakat Allah kâfirlikleri yüzünden kendilerine lânet ettiği için -pek azı dışında- onlar iman etmezler."},{"n":47,"t":"Ey kendilerine kitap verilenler, biz bazı yüzleri çarpıtıp ense taraflarına döndürmeden ya da Cumartesi yasağını çiğneyenleri lânetlediğimiz gibi lânetlemeden elinizdeki kitabı onaylayıcı olarak indirdiğimiz Kur’an’a iman ediniz. Yoksa Allah’ın emri her zaman kesinlikle yerine gelir."},{"n":48,"t":"Hiç kuşkusuz Allah, kendisine ortak koşma günahını bağışlamaz. Bunun dışında kalan günahları dilediğine bağışlar. Kim Allah’a ortak koşarsa son derece büyük bir iftira günahı işlemiş olur."},{"n":49,"t":"Şu kendilerini temize çıkaranları görmüyor musun? Oysa Allah dilediği kimseyi arındırır, fakat hiç kimseye kıl payı kadar haksızlık yapılmaz."},{"n":50,"t":"Baksana Allah’a karşı nasıl yalan uyduruyorlar? Bu tek başına yeterli bir apaçık günahtır."},{"n":51,"t":"Şu kendilerine kitaptan bir pay verdiklerimizi görmüyor musun? Bunlar puta ve tağut’a (şeytana) inanırlar ve kâfirler hakkında ’Bunların yolu müminlerin yolundan daha doğrudur’ derler."},{"n":52,"t":"Bunlar Allah’ın lânetine uğramış kimselerdir. Allah birine lânet ederse ona yardım edecek birini bulamazsın."},{"n":53,"t":"Yoksa onların Allah’ın mülkünde bir payları mı var? Eğer öyle olsaydı, insanlara bir çekirdek kırıntısı bile vermezlerdi."},{"n":54,"t":"Yoksa Allah’ın, lütfunun eseri olarak insanlara bağışlamış olduğu imtiyazı çekemiyorlar, bu yüzden onları kıskanıyorlar mı? Oysa biz İbrahim’in soyundan gelenlere de kitap ve hikmet vermiş, kendilerine büyük bir egemenlik bağışlamıştık."},{"n":55,"t":"Fakat İbrahim’in soyundan gelenlerin kimi O’na inandı, kimi de kendisine sırt çevirdi. Öylelerinin hakkından alevli cehennem gelir."},{"n":56,"t":"Hiç kuşkusuz ayetlerimizi inkâr edenleri ilerde ateşe atacağız. Derileri kavruldukça azabın acısını duysunlar diye kendilerine başka deriler giydireceğiz. Hiç şüphesiz Allah üstün iradelidir, hikmet sahibidir."},{"n":57,"t":"İman edip iyi ameller işleyenleri de ilerde içinde ebedi olarak kalacakları, altından ırmaklar akan cennetlere yerleştireceğiz. Onlara orada el değmemiş eşler verilecek, kendileri koyu gölgeler altına alınacaklardır."},{"n":58,"t":"Allah size emanetleri, onları taşıyabilecek olanlara yüklemenizi ve insanlar arasında hüküm verirken adalete uygun hüküm vermenizi emreder. Allah size ne güzel öğüt veriyor! Hiç kuşkusuz Allah işiten ve görendir."},{"n":59,"t":"Ey müminler, Allah’a itaat ediniz; Peygambere ve sizden olan devlet yetkililerine de itaat ediniz. Eğer gerçekten Allah’a ve ahiret gününe inanmışsanız herhangi bir konuda anlaşmazlığa düştüğünüzde o meselenin çözümünü Allah’a ve Peygamber’e havale ediniz. Bu sizin hesabınıza en hayırlı ve en iyi akıbet vaad eden bir tutumdur."},{"n":60,"t":"Gerek sana ve gerekse senden öncekilere indirilen kitaplara inandıklarını ileri sürenleri görmüyor musun? Bunlar karşı çıkmakla, tanımamakla emredildikleri Tağutun hakemliğine başvurmak istiyorlar. Şeytan onları koyu bir sapıklığa düşürmek istiyor."},{"n":61,"t":"Onlara ’Allah’ın indirdiğine ve Peygamber’e geliniz’ dendiğinde o münafıkların senden büsbütün uzaklaştıklarını görürsün."},{"n":62,"t":"Peki, nasıl oluyor da kendi elleri ile işledikleri kötülük yüzünden başlarına bir musibet gelince sana koşarak ’Biz sadece iyilik yapmak, uzlaşma sağlamak istemiştik’ diye Allah adına yemin ederler."},{"n":63,"t":"Allah onların kalplerindeki kötü duyguları iyi bilir. Onlara aldırış etme, öğüt ver, kendileri hakkında içlerine işleyecek etkili sözler söyle onlara."},{"n":64,"t":"Biz gönderdiğimiz her peygamberi, Allah’ın izni ile, mutlaka kendisine itaat edilsin diye gönderdik. Eğer onlar nefislerine zulmettiklerinde sana gelerek Allah’tan af dileselerdi ve Peygamber de onlar adına af dileseydi, Allah’ı tevbeleri kabul edici ve merhametli olarak bulacaklardı."},{"n":65,"t":"Hayır, hayır! Rabbine andolsun ki, onlar aralarında çıkan anlaşmazlıklarda senin hakemliğine başvurmadıkça sonra da vereceğin karara, gönüllerinde hiçbir burukluk duymaksızın, kesin bir teslimiyetle uymadıkça mümin olamazlar."},{"n":66,"t":"Eğer onlara «canlarınızı feda ediniz» ya da «yurtlarınızdan çıkınız» diye emretmiş olsaydık, pek azı dışında, bunları yapamazlardı. Oysa eğer onlar kendilerine verilen öğütleri tutsalardı, bu haklarında hayırlı ve güvenceli bir tutum olurdu."},{"n":67,"t":"O zaman onlara tarafımızdan büyük bir mükâfat verirdik."},{"n":68,"t":"Kendilerini kesinlikle doğru yola iletirdik."},{"n":69,"t":"Allah’a ve Peygamber’e itaat edenler var ya, bunlar Allah’ın nimetine eriştirdiği peygamberlerle, dosdoğru kullarla, şehidlerle ve iyilerle birlikte olurlar. Bunlar ne iyi arkadaşlardır!"},{"n":70,"t":"Bu Allah’ın bağışıdır. Allah herşeyi yeterince bilir."},{"n":71,"t":"Ey müminler savaş hazırlıklarınızı yapınız ve sonra da ya bölük bölük ya da hep birlikte savaşa çıkınız."},{"n":72,"t":"İçinizde bu görevi gayet ağırdan alanlar var. Eğer bir musibet (başarısızlık- yenilgi) ile karşılaşırsanız ’Allah bana lütfetti de onlarla birlikte bulunmadım’ der."},{"n":73,"t":"Buna karşılık Allah size bir zafer kazandıracak olursa sanki daha önce aranızda hiçbir tanışıklık, hiçbir dostluk yokmuş gibi ’keşki ben de onlarla birlikte olsaydım da ben de büyük başarıya erseydim’ der."},{"n":74,"t":"Öyleyse dünya hayatını ahiret karşılığında satanlar Allah yolunda savaşsınlar. Kim Allah yolunda öldürülür veya galip gelirse biz ona ilerde büyük bir ödül vereceğiz."},{"n":75,"t":"Niye Allah yolunda ve ’Ey rabbimiz, bizi şu zalimlerin yaşadığı beldeden çıkar, bize katından bir kurtarıcı, kendi katından bir destekçi gönder’ diye yalvaran ezilmiş erkekler, kadınlar ve çocuklar uğrunda savaşmıyorsunuz."},{"n":76,"t":"Müminler Allah yolunda, kafirlerse Tağut (şeytan) uğrunda savaşırlar. O halde şeytanın dostlarıyla savaşınız. Çünkü şeytanın hilesi düzeni zayıftır."},{"n":77,"t":"Daha önce kendilerine ’savaştan uzak durun, namazı kılın ve zekatı verin’ direktifi verilmiş olanları görmüyor musun? Şimdi üzerlerine farz kılınınca, onların; Allah’tan korkar gibi ya da bundan bile daha fazla, insanlardan korkan bir grubu «Ey Rabbimiz niye üzerimize savaşmayı farz kıldın, bize biraz daha mühlet tanısaydın olmaz mıydı?» dediler. Onlara de ki; «Dünya zevki kısa sürelidir. Ahiret ise sakınanlar için daha hayırlıdır. Orada kıl payı bile haksızlığa uğramazsınız.»"},{"n":78,"t":"Nerede olursanız olun, surlarla tahkim edilmiş kalelerin içinde bile olsanız, ölüm sizi bulur. Eğer onlar bir iyilikle karşılaşırlarsa ’bu Allah’tandır’ derler, ama başlarına bir kötülük gelirse ’bu senin yüzündendir’ derler. Onlara de ki; \"Hepsi Allah’tandır.\" Niye bu adamlar kendilerine söylenen sözü anlamaya yanaşmıyorlar?"},{"n":79,"t":"Karşına çıkan her iyilik Allah’tandır. Başına gelen her kötülük de kendindendir. Biz seni insanlara peygamber olarak gönderdik. Buna şahit olarak Allah yeter."},{"n":80,"t":"Kim peygambere itaat ederse Allah’a itaat etmiş olur. Kim ona sırt çevirirse bilsin ki biz seni onların başına korucu olarak göndermiş değiliz."},{"n":81,"t":"Yüzüne karşı ’peki’ derler. Fakat onların bir gurubu yanından ayrıldıktan sonra geceleyin aleyhinde sana verdikleri sözle bağdaşmayan komplolar kurarlar. Hiç şüphesiz Allah onların geceleri kurdukları komploları yazıyor. Sen onlara aldırış etme, Allah’a güven. Vekil olarak Allah sana yeter."},{"n":82,"t":"Bunlar Kur’an’ı hiç incelemiyorlar mı? Eğer o Allah’tan başkası tarafından gelmiş olsaydı, içinde mutlaka birçok çelişkiler bulurlardı."},{"n":83,"t":"Onlar güvene ya da korkuya ilişkin bir haber alınca onu hemen yayarlar. Oysa eğer o haberi peygambere ya da başlarındaki kendi yetkililerine götürseler, aralarındaki yorum yapmaya yetenekli olanlar onun mahiyetini anlarlardı. Eğer Allah’ın üzerinizdeki lütfu ve rahmeti olmasaydı, küçük bir azınlık dışında hepiniz şeytana uyardınız."},{"n":84,"t":"Allah yolunda savaş. Sen sadece kendinden sorumlusun. Müminleri de savaşmaya teşvik et de ola ki Allah kafirlerin ağır baskılarını geri püskürtür. Hiç kuşkusuz Allah’ın kahrı, öldürücü darbesi pek şiddetlidir."},{"n":85,"t":"Kim iyi bir işe aracı olursa kendisinin de o iyilikte bir payı olur. Kim bir kötülüğe aracı olursa onun da kötülükte bir sorumluluk payı olur. Allah herşeyin karşılığını verir."},{"n":86,"t":"Size bir selam verildiğinde ona daha güzeli ile ya da aynısı ile karşılık veriniz. Hiç kuşkusuz Allah her şeyi hesaba katar."},{"n":87,"t":"Kendisinden başka ilah olmayan Allah, sizleri geleceği kuşkusuz olan Kıyamet günü kesinlikle bir araya getirecektir. Allah’tan daha doğru sözlü kim olabilir?"},{"n":88,"t":"Size ne oldu da münafıklar hakkında iki gruba ayrıldınız? Oysa Allah onları işlediklerinden dolayı baş aşağı çevirmiştir. Siz Allah’ın saptırdıklarını mı doğru yola eriştirmek istiyorsunuz? Allah kimi saptırırsa, onun için bir yol bulamazsın."},{"n":89,"t":"Onlar kendileri gibi sizin de kâfir olmanızı arzu ederler. Bu yüzden Allah yolunda hicret etmedikleri sürece onlardan hiçbirini dost edinmeyiniz. Eğer yüz çevirirlerse onları yakalayınız, bulduğunuz yerde öldürünüz, hiç birini dost veya müttefik edinmeyiniz."},{"n":90,"t":"Ancak sizinle kendileri arasında anlaşma bulunan bir millete sığınanlar müstesna. Sizinle savaşmaktan veya kendi milletleriyle harp etmekten bunalarak size baş vuranlar da müstesnadır. Allah dileseydi onları size musallat ederdi de, sizinle savaşırlardı. Eğer sizden uzak durur, savaşmaz ve size barış teklif ederlerse, Allah onlara dokunmanıza izin vermez."},{"n":91,"t":"Bir de hem sizden ve hem de tuttukları gruptan yana güven içinde olmak isteyen başka birtakım kimselere rastlayacaksınız. Bunlar ne zaman fitneye, bozgunculuğa itilseler ona balıklama dalarlar. Eğer bunlar sizden uzak durmaz size barış teklifi getirerek savaştan el çekmezlerse onları yakalayınız ve nerede bulursanız öldürünüz. Onlara karşı size apaçık bir yetki verdik."},{"n":92,"t":"Bir müminin diğer bir mümini öldürmesi düşünülemez. Bu ancak yanlışlıkla olabilir. Kim yanlışlıkla bir mümini öldürürse mümin bir köle azad etmesi ve ölünün ailesine diyet ödemesi gerekir. Eğer ölenin ailesi diyeti bağışlarsa bu gereklilik ortadan kalkar. Eğer ölü size düşman bir kavme mensub bir mümin ise o zaman mümin bir köle azad etmek gerekir. Eğer anlaşmalı olduğunuz kavimden ise ailesine fidye ödemek ve mümin bir köle azad etmek gerekir. Bunları bulamayan kimse Allah’ın tevbesini kabul etmesi için aralıksız iki ay oruç tutar. Hiç şüphesiz Allah herşeyi bilir ve hikmet sahibidir."},{"n":93,"t":"Kim bir mümini bile bile öldürürse onun cezası içinde ebedi olarak kalmak üzere Cehennemdir. Allah ona gazap etmiş, lanet yağdırmış ve kendisi için büyük azap hazırlamıştır."},{"n":94,"t":"Ey müminler Allah yolunda savaşa çıktığınız zaman iyice emin olmadan silah çekmeyiniz. Size selam verene, dünya hayatının malına göz dikerek ’sen mü’min değilsin’ demeyiniz. Zira asıl bol ganimetler Allah katındadır. Bir zamanlar siz de öyle idiniz de Allah’ın lütfu ile mümin oldunuz. O halde silah çekmeden önce durumu iyice anlayınız. Hiç şüphesiz ne yaparsanız Allah ondan haberdardır."},{"n":95,"t":"Müminlerden özürsüz olarak yerlerinde oturanlar ile malları ve canlarıyla Allah yolunda cihad edenler bir değildir. Allah malları ve canları ile cihad edenleri derece bakımından oturanlardan üstün kıldı. Gerçi Allah her ikisine de cenneti vaad etmiştir, ama malları ve canları ile cihad edenleri oturanlara karşı büyük bir mükafatla üstün tutmuştur."},{"n":96,"t":"(Cihad edenlere) kendi katından dereceler, bağışlama ve rahmet sunmuştur. Hiç kuşkusuz Allah bağışlayıcıdır, merhametlidir."},{"n":97,"t":"Melekler, kendilerini zulme mahkum edenlerin canlarını alırken onlara «Dünyadaki durumunuz neydi?» diye sorarlar. Onlar da «Ezilmiş zavallılardık» derler. Melekler onlara «Peki Allah’ın toprağı göç etmenize yetecek kadar geniş değil miydi ki? derler. Bunların barınakları Cehennem olacaktır. Orası ne kötü bir varış yeridir."},{"n":98,"t":"Yalnız, çaresiz kalan, hiç bir çıkar yol bulamayan ezilmiş, erkekler, kadınlar ve çocuklar bu hükmün dışındadırlar."},{"n":99,"t":"Böylelerini umulur ki, Allah affeder. Hiç şüphesiz Allah bağışlayıcıdır, affedicidir."},{"n":100,"t":"Kim Allah yolunda göç ederse bir çok barınak ve elverişli geçim imkanları bulur. Kim Allah ve peygamber uğruna evini- barkını bırakıp göç ederse de sonra bu yolda ölüme yakalanırsa onun mükafatı Allah’ın güvencesi altındadır. Hiç şüphesiz Allah affedici ve merhametlidir."},{"n":101,"t":"Yeryüzünde herhangi bir yöresinde savaşa çıktığınız zaman eğer size tuzak kuracaklarından çekiniyorsanız namazı kısaltarak kılmanızın sakıncası yoktur. Şüphe yok ki, kafirler sizin açık düşmanlarınızdır."},{"n":102,"t":"Eğer sen mümin savaşçıların arasında bulunur da onlara namaz kıldırırsan onların bir grubu senin arkanda namaza dursun ve silahlarını yanlarına alsınlar. Bu grup secdeden kalkınca arkanıza (nöbet yerine) geçsin. Bu kez namaz kılmamış olan öteki grup gelerek arkanda namaz kılsın, bunlar da silahlarını ve teçhizatlarını yanlarına alsınlar. Çünkü kafirler isterler ki, silahlarınızı ve kumanyalarınızı aklınızdan çıkarasınız da ansızın üzerinize baskın düzenlesinler. Eğer yağmurdan zarar görecekseniz ya da hasta iseniz silahlarınızı yere bırakmanızın sakıncası yoktur. Bununla birlikte uyanık ve tedbirli olunuz. Hiç şüphesiz Allah kafirler için onur kırıcı bir azap hazırlamıştır."},{"n":103,"t":"Namazı bitirdikten sonra ayaktayken, otururken ve yere uzanmışken Allah’ın adını anınız. Tehlikeyi savuşturup güvene kavuştuğunuzda namazı tam olarak kılınız. Zira namaz müminlere, vakitleri belirli bir farzdır."},{"n":104,"t":"O düşmanlarınızın peşini bırakmayınız, onları ısrarla kovalamaktan geri durmayınız. Çünkü eğer siz acı çekiyorsanız bilin ki, onlar da sizin gibi acı çekiyorlar. Oysa siz Allah’tan onların beklemediğini bekliyorsunuz. Hiç kuşkusuz Allah her şeyi bilir ve hikmet sahibidir."},{"n":105,"t":"Biz sana bu hak içerikli kitabı indirdik ki, insanlar arasında Allah’ın gösterdiği gibi hüküm veresin. Sakın hainlerin savunucusu olma."},{"n":106,"t":"Allah’tan af dile, hiç kuşkusuz Allah bağışlayıcıdır, merhametlidir."},{"n":107,"t":"Kendilerine hıyanet edenleri temize çıkarmaya çalışma. Hiç şüphesiz Allah hıyanete dalmış günahkarları sevmez."},{"n":108,"t":"Bu kimseler Allah’ın razı olmadığı sözü geceleyin buluşarak karara bağlarken insanlardan saklı tutuyorlar, ama yanı başlarında olan Allah’tan saklayamazlar. Hiç şüphesiz Allah onların yaptıklarını bilgisi ile kuşatacak güçtedir."},{"n":109,"t":"Diyelim ki, siz onları dünya hayatında savundunuz. Peki kıyamet günü onları Allah’a karşı kim savunacak ya da kim onların vekilliğini üzerine alacak."},{"n":110,"t":"Kim bir kötülük işler ya da kendine zulmeder de Allah’tan af dilerse Allah’ı bağışlayıcı ve esirgeyici olarak karşısında bulur."},{"n":111,"t":"Kim bir suç işlerse onu kendi aleyhine işlemiş olur. Kuşkusuz Allah bilir ve hakimdir."},{"n":112,"t":"Kim bir kusur ya da bir suç işler de onu bir masumun üzerine atarsa açık bir iftira, bir günah yükünün altına girmiş olur."},{"n":113,"t":"Eğer Allah’ın sana yönelik lütfu ve esirgemesi olmasaydı, onların bir takımı seni yanıltmaya yeltenmişlerdi. Oysa onlar sadece kendilerini yanıltırlar, sana hiçbir zarar dokunduramazlar. Çünkü Allah, kitabı ve hikmeti indirerek sana, daha önce bilmediğin gerçekleri öğretmiştir. Hiç şüphesiz Allah’ın sana yönelik lütfu son derece büyüktür."},{"n":114,"t":"Onların aralarında yaptıkları çoğu gizli konuşmalarda hayır yoktur. Meğer ki, bu fısıltılı toplantılarının amacı sadaka vermeyi, iyiliği ve insanlar arasında dirliği emretmek olsun. Kim bunları Allah’ın rızasını kazanmak amacıyla yaparsa ilerde kendisine büyük bir mükafat vereceğiz."},{"n":115,"t":"Kim bu yolu iyice tanıdıktan sonra, peygambere zıt düşer de müminlerin yolundan başka bir yola koyulursa, kendisini koyulduğu yolla baş başa bırakır, sonra da cehenneme atarız. Orası ne kötü bir dönüş yeridir."},{"n":116,"t":"Allah kendisine ortak koşma suçunu bağışlamaz. Bunun dışındaki suçları dilediğine bağışlar. Kim Allah’a ortak koşarsa gerçekten koyu bir sapıklığa düşmüş olur."},{"n":117,"t":"Onlar Allah’ı bırakıp dişi putlara (tanrıçalara) yalvarıyorlar. Aslında onların yalvardıkları şirret şeytandan başkası değildir."},{"n":118,"t":"O şeytan ki, Allah’ın lanetine uğrayınca «Kesinlikle kullarının belirli bir bölümünü kendi tarafıma alacağım.»"},{"n":119,"t":"Onları yoldan çıkaracağım, asılsız kuruntulara daldıracağım, kendilerine davarların kulaklarını yarmalarını emredeceğim, Allah’ın yaratıklarını değişikliğe uğratmalarını emredeceğim» demiştir. Kim Allah’ı bırakıp şeytanı dost edinirse apaçık bir hüsrana uğramış olur."},{"n":120,"t":"Şeytan onlara vaadler yapar, kendilerini kuruntulara daldırır. Fakat şeytanın onlara yaptığı vaadler aldatmacadan başka bir şey değildir."},{"n":121,"t":"İşte bunların varacakları yer cehennemdir. Ondan kurtulma imkanı bulamazlar."},{"n":122,"t":"İman edip iyi ameller işleyenleri ise altından ırmaklar akan, içinde ebedi olarak kalacakları cennetlere yerleştireceğiz. Bu Allah’ın vaadidir. Kim Allah’tan daha doğru sözlü olabilir."},{"n":123,"t":"Allah’ın vereceği mükafatı elde etmek ne sizin ne Kitap Ehli’nin kuruntularına göre olmaz. Kim kötülük işlerse cezasına çarpılır ve Allah’tan başka hiçbir dost, hiçbir yardım edici bulamaz."},{"n":124,"t":"Buna karşılık erkek yada kadın kim inanarak iyi bir amel işlerse, böyleleri de zerre kadar haksızlığa uğramaksızın cennete girerler."},{"n":125,"t":"Hem iyi ameller yapıp hem de tüm varlığı ile Allah’a teslim olandan ve İbrahim’den tek ilahlı dine uyandan daha iyi bir dindar kim olabilir? Allah, İbrahim’i dost edinmişti."},{"n":126,"t":"Gerek göklerde ve gerekse yeryüzünde bulunan tüm varlıklar Allah’a aittir. Allah herşeyi kuşatmıştır."},{"n":127,"t":"Bu fetva, paylarına düşen mirası vermediğiniz, yada nikahlamak istemediğiniz yetim kadınlar, mağdur çocuklar ve yetimlere karşı adil davranmanız konusunda, size okunan Kur’an ayetleridir. Ne iyilik yaparsanız, kuşkusuz Allah onu bilir."},{"n":128,"t":"Eğer kadın, kocasının geçimsizlik çıkaracağından veya kendisini ihmal edeceğinden endişe ederse bu çiftin anlaşma yolu ile ilişkilerini yeniden düzene koymalarının bir sakıncası yoktur. Anlaşma her zaman hayırlıdır. Nefisler cimriliğe, bencilliğe eğilimlidirler. Eğer iyi davranır, Allah’tan korkarsanız, hiç şüphesiz Allah yaptıklarınızdan haberdardır."},{"n":129,"t":"Ne kadar özen gösterseniz de eşleriniz arasında adaleti sağlayamayacaksınız. O halde birine iyice tutulup öbürünü ortada bırakmayınız. Eğer barışır Allah’tan korkarsanız, hiç kuşkusuz Allah affedicidir ve merhametlidir."},{"n":130,"t":"Eğer eşler birbirinden ayrılırlarsa Allah bol nimetleri ile her ikisini de muhtaç duruma düşmekten korur. Allah’ın nimetleri boldur ve O hikmet sahibidir."},{"n":131,"t":"Gerek göklerde gerekse yeryüzünde ne varsa hepsi Allah’a aittir. Size ve sizden önce kendilerine kitap verilmişlere Allah’tan korkmayı emrettik. Eğer kafir olursanız, biliniz ki, göklerde ve yeryüzünde bulunan herşey Allah’ındır. Onun hiçbir şeye ihtiyacı yoktur ve övgüye layıktır."},{"n":132,"t":"Gerek göklerde gerekse yeryüzünde ne varsa hepsi Allah’a aittir. Allah vekil olarak yeterlidir."},{"n":133,"t":"Ey insanlar, eğer O dilerse sizi ortadan kaldırır da yerinize başkalarını getirir. Hiç şüphesiz Allah’ın gücü bunu yapmaya yeter."},{"n":134,"t":"Kim dünyada mükafatını elde etmek isterse bilsin ki, dünyanın da ahiretin de mükafatı Allah’ın katındadır. Hiç kuşkusuz Allah herşeyi işiten ve görendir."},{"n":135,"t":"Ey müminler, kendinizin, ana-babanızın ve akrabalarınızın aleyhinde bile olsa, adalete sıkı sıkıya bağlı kalınız ve Allah için şahitlik ediniz. Haklarında şahitlik ettiğiniz kimseler ister zengin, ister fakir olsunlar, Allah kendilerine herkesten daha yakındır. O halde nefsinizin arzusuna uyarak doğruluktan sapmayınız. Eğer kaypaklık eder, ya da şahitlik yapmaktan kaçınırsanız, kuşku yok ki, Allah yaptıklarınızdan haberdardır."},{"n":136,"t":"Ey müminler, Allah’a, peygamberine, peygamberine indirmiş olduğu kitaba ve daha önce indirilmiş kitaba inanmaya devam ediniz. Kim Allah’ı, meleklerini, kitaplarını, peygamberlerini ve ahiret gününü inkar ederse koyu bir sapıklığa düşmüş olur."},{"n":137,"t":"Allah, önce iman edip arkasından küfredenleri, sonra yine iman edip arkasından küfredenleri, sonra da kafirliklerini koyulaştıranları asla affetmeyecek, kendilerini doğru yola iletmeyecektir."},{"n":138,"t":"Münafıklara acı bir azabın kendilerini beklediğini müjdele."},{"n":139,"t":"Onlar müminleri bırakıp kafirleri dost ediniyorlar. Acaba onların yanında şeref mi arıyorlar? Oysa şeref bütünüyle Allah’ındır."},{"n":140,"t":"Allah size indirdiği kitapta onun ayetlerinin inkar edildiğini ya da alaya alındığını işittiğinizde başka bir konuya geçmedikleri sürece onlarla bir arada oturmamanızı, yoksa sizin de onlar gibi olacağınızı bildirdi. Hiç kuşkusuz Allah münafıklar ile kafirleri cehennemde bir araya getirecektir."},{"n":141,"t":"Onların gözleri hep sizin üzerinizdedir. Eğer Allah size zafer nasip ederse, «Biz sizinle beraber değil miydik?» derler. Ama eğer kafirler üstünlük sağlarsa, (bu kez de onlara) «Sizin tarafınızı tutmadık mı, müminlere karşı size destek vermedik mi?» derler. Allah kıyamet günü arınızdaki hükmünü verecektir. Hiç kuşkusuz Allah kafirlere, müminler karşısında üstün gelme fırsatı vermez."},{"n":142,"t":"Münafıklar, Allah’ı aldatmaya yeltenirler, ama asıl Allah onları aldatır. Namaz kılarken isteksiz ve ciddiyetsiz biçimde ayakta dikilirler. Amaçları insanlara gösteriş yapmaktır, Allah’ın adını pek az anarlar."},{"n":143,"t":"İki taraf arasında yalpalarlar. Ne bu tarafa ve ne de o tarafa yar olurlar. Allah’ın şaşırttığı kimseye sen çıkış yolu bulamazsın."},{"n":144,"t":"Ey müminler, sakın müminleri bırakıp kafirleri dost edinmeyiniz. Yoksa Allah’a, aleyhinize işleyecek açık bir delil mi vermek istiyorsunuz?"},{"n":145,"t":"Hiç şüphesiz münafıkların yeri cehennemin en alt katıdır. Onlara yardım edecek hiç birini bulamazsınız."},{"n":146,"t":"Ancak tevbe edenler, durumlarını düzeltenler, Allah’ın ipine sarılanlar, sırf Allah’a bağlananlar bir dindarlığı benimseyenler işte bunlar, müminlerle beraberdirler. Allah ilerde müminlere büyük bir mükafat verecektir."},{"n":147,"t":"Eğer Allah’a şükreder, inanırsanız, O sizi niye azaba çarptırsın ki? Hiç şüphesiz Allah, şükre karşılık verir ve her şeyi bilir."},{"n":148,"t":"Allah zulme uğrayanların dışında hiç kimsenin açıkça kötü söz söylemesini sevmez. Hiç kuşkusuz Allah herşeyi işiten ve görendir."},{"n":149,"t":"Bir iyiliği açığa vursanız da gizli tutsanız da veya bir kötülüğü bağışlasanız da biliniz ki, Allah bağışlayıcıdır ve gücü her şeye yetendir."},{"n":150,"t":"Allah’ı ve peygamberlerini inkar edenler, Allah ile peygamberleri arasında ayırım yaparak; ’Buna inanır, fakat şuna inanmayız’ diyenler böylece, iman ile küfür arası bir yol tutturmak isteyenler var ya,"},{"n":151,"t":"onlar gerçek anlamı ile kafirdirler. Biz kafirler için onur kırıcı bir azap hazırladık."},{"n":152,"t":"Buna karşılık Allah’a ve peygamberlerine inananlara ve peygamberler arasında ayırım yapmayanlara gelince, Allah onların mükafatını ilerde verecektir. Hiç kuşkusuz Allah affedicidir, merhametlidir."},{"n":153,"t":"Ehl-i Kitap senden kendilerine gökten kitap indirmeni isterler. Onlar vaktiyle Musa’dan bundan daha büyüğünü isteyerek, ’Bize Allah’ı açıkça göster’ demişlerdi. Bu zalimce tutumları yüzünden kendilerini yıldırım çarpmıştı. Arkasından kendilerine açık belgeler geldikten sonra buzağıya taptılar. Bunu da bağışladık ve Musa’ya açık bir mesaj verdik."},{"n":154,"t":"Kesin söz vermeleri üzerine, başları üzerinde asılı duran kayayı yukarı çektik. Kendilerine, o kasabanın kapısından secde ederek içeri giriniz ve ’Cumartesi yasağını çiğnemeyiniz’ dedik, bu konularda onlardan sağlam bir söz aldık."},{"n":155,"t":"Yahudiler verdikleri sözlerinden caydılar. Allah’ın ayetlerini inkar ettiler, Peygamberlerini, sebepsiz yere öldürdüler ve ’Bizim kalplerimiz kılıçla kaplıdır’ dediler. Oysa Allah kafirlikleri sebebiyle kalplerini mühürlemiştir. Bundan dolayı onlar, pek azı dışında iman etmezler."},{"n":156,"t":"Kafirliklerinden dolayı ve Meryem’e büyük iftira atmalarından dolayı."},{"n":157,"t":"ve \"Allah’ın elçisi (olduğunu söyleyen) Meryem’ın oğlu İsa Mesih’i işte biz öldürdük!\" demeleri nedeniyle... Aslında onu ne öldürdüler ne de çarmıha gerdiler, fakat (kafa karışıklığıyla) onlara öyle olmuş gibi geldi. Bu konuda farklı görüşler ileri sürenler ise, ondan dolayı gerçekten şaşkınlık içerisindedirler; onunla ilgili bir bilgileri yoktu ve yalnızca zanna dayanıyorlardı. Sonuç olarak kesinlikle onu öldürmediler:"},{"n":158,"t":"Tersine Allah, O’nu kendi katına çıkardı. Hiç şüphesiz Allah üstün iradeli ve hikmet sahibidir."},{"n":159,"t":"Kitap Ehli’nden hiç kimse yoktur ki, ölümünün eşiğinde İsa’ya iman etmemiş olsun. Fakat kıyamet günü İsa, onların aleyhinde şahitlik edecektir."},{"n":"160-161","t":"İşte yaptıkları bunca zulümlerden, bir çok kimsenin Allah yoluna girmesini engellemelerinden, men edilmiş olan faizi almalarından ve insanların mallarını haksız yollara başvurarak yemelerinden dolayı, daha önce helal olan bazı temiz maddeler Yahudilere haram kılındı. Ayrıca onların arasındaki kafirlere acı bir azap hazırladık."},{"n":162,"t":"Fakat onlardan bilim alanında derinleşenlere, hem sana ve hem de senden öncekilere indirilen kitaba inanan müminlere, namaz kılanlara, zekat verenlere, Allah’a ve ahiret gününe inananlara büyük bir mükafat vereceğiz."},{"n":163,"t":"Nuh’a ve ondan önce gelen peygamberlere indirdiğimiz gibi sana da vahiy indirdik. Nitekim İbrahim’e, İsmail’e, İshak’a, Yakub’a, Yakub’un torunlarına, İsa’ya, Eyyub’a, Harun’a, Süleyman’a vahiy indirmiş, Davud’a da Zebur’u vermiştik."},{"n":164,"t":"Daha önce bazılarını sana anlattığımız, bazılarını da anlatmadığımız peygamberler gönderdik. Allah, Musa ile de bizzat konuştu."},{"n":165,"t":"Bu peygamberleri müjdeleyici ve uyarıcı olarak gönderdik ki, bu peygamberlerden sonra insanların Allah’a karşı ileri sürebilecekleri hiçbir bahaneleri kalmasın. Hiç kuşkusuz Allah güçlüdür ve hikmet sahibidir."},{"n":166,"t":"Fakat Allah sana indirdiği kitabın kendi bilgisi altında indirilmiş olduğuna şehadet eder. Melekler de buna şahitlik ederler. Aslında Allah’ın şahitliği yeterlidir."},{"n":167,"t":"Kafir olup başkalarını da Allah yolundan alıkoyanlar, hiç kuşkusuz koyu bir sapıklığa düşmüşlerdir."},{"n":168,"t":"Allah kafirleri ve zalimleri ne bağışlayacak ne de doğru yola iletecektir."},{"n":169,"t":"Onların iletilecekleri tek yol cehennem yoludur. Orada ebedi olarak kalacaklardır. Bunu yapmak Allah için pek kolaydır."},{"n":170,"t":"Ey insanlar, peygamber size Rabbinizden gerçeği getirdi. Buna inanınız, yararınıza olan budur. Ama eğer inkar ederseniz, biliniz ki, göklerde ve yeryüzünde ne varsa hepsi Allah’ındır. Hiç kuşkusuz Allah her şeyi bilir ve hikmet sahibidir."},{"n":171,"t":"Ey Kitap Ehli, dininiz konusunda aşırılığa sapmayınız, Allah hakkında gerçek olmayan sözler söylemeyiniz. Meryem oğlu İsa Mesih, Allah’ın sadece bir peygamberi, Meryem’e sunduğu bir kelimesi ve ondan gelen bir ruhtur. Allah’a ve peygamberine inanınız. Allah «üçtür» demeyiniz. Bundan vazgeçiniz, hayrınıza olan budur. Allah ancak tek bir ilahtır, çocuğu olmaktan münezzehtir, göklerde ve yeryüzünde bulunan herşey onundur. Allah insan için yeterli bir vekildir."},{"n":172,"t":"Ne Mesih Allah’a kul olmaktan kaçınır ve nede Allah’a yakın melekler. Kim ona kul olmaktan kaçınır, büyüklük taslarsa, bilsin ki, Allah hepsini huzurunda bir araya getirecektir."},{"n":173,"t":"İman edip iyi ameller işleyenlere mükafatlarını eksiksiz ödeyecek, hatta lütfundan onlara daha fazlasını verecektir. Kul olmayı kendisine yedirmeyip büyüklük taslayanları da acı bir azaba çarptıracaktır. Bunlar Allah’tan başka hiçbir dost, hiçbir yardım edici bulamazlar."},{"n":174,"t":"Ey insanlar size Rabbinizden kesin kanıt geldi ve size apaçık bir ışık indirdik."},{"n":175,"t":"Allah kendisine inanıp sarılanları rahmetine, bol bağışına kavuşturacak, onları doğru yola iletecektir."},{"n":176,"t":"Çocuğu olmayıp bir kız kardeşi bulunan kimse ölürse, bıraktığının yarısı kız kardeşe kalır. Fakat kız kardeşinin çocuğu yoksa, kendisi ona tamamen varis olur. Eğer kız kardeş kalmışsa, bıraktığının üçte ikisi onlaradır. Erkek, kadın, karışık kardeşlerse, erkeğe iki dişinin hissesi kadar pay vardır. Doğru yoldan saparsınız diye Allah size açıklıyor.\" Allah her şeyi hakkıyla bilendir."}],[{"n":1,"t":"İhramlı iken avlanmayı helal saymamanız şartı ile ilerde sayılacak olanlar dışında kalan bütün hayvanlar size helal kılındı, Allah dilediği hükmü verir."},{"n":2,"t":"Ey iman edenler, Allah’ın nişanelerine, (kıtal) haram olan aya, (Kabe’ye) hediye olan kurbanlığa, gerdanlıklar takılan hayvanlara, Rablerinden bol nimet ve rıza talep ederek Beyt-i Haram’a gelenlere sakın hürmetsizlik etmeyin. İhramdan çıktığınız zaman avlanabilirsiniz. Sizi Mescid-i Haram’dan men ettiği için bir kavme olan kininiz, aşırı gitmenize sebep olmasın; iyilikte ve fenalıktan sakınmakta yardımlaşın, günah işlemek ve aşırı gitmekte yardımlaşmayın. Allah’tan korkun. Allah’ın cezası şiddetlidir."},{"n":3,"t":"Ölü, kan, domuz eti, Allah’tan başkası adına boğazlananlar, -boğulmuş, bir yerine vurularak öldürülmüş, düşüp yuvarlanmış, başka bir hayvan tarafından süsülmüş, yırtıcı hayvan tarafından yenmiş olanları canları çıkmadan önce kesmemişseniz-, dikili taşlar üzerine boğazlananlar ve fal oklarıyla kısmet aramanız size haram kılındı; bunlar fasıklıktır. Bugün, kafirler dininizden çıkmanızdan ümitlerini kesmişlerdir, onlardan korkmayın, benden korkun. Bugün sizin dininizi kemale erdirdim, üzerinizdeki nimetimi tamamladım ve size din olarak İslamiyet’i beğendim. Açlıktan darda kalan, günaha kaymaksızın yiyebilir. Doğrusu Allah, Gafur’dur, Rahim’dir."},{"n":4,"t":"Sana kendilerine nelerin helal kılındığını soruyorlar. onlara de ki «Size temiz yiyecekler helal kılındı. Allah’ın size sağladığı bilgileri öğreterek yetiştirdiğiniz eğitimli ev hayvanları sizin için avladıkları hayvanları da yiyiniz ve üzerlerine Allah’ın adını anınız. Allah’tan korkunuz. Hiç kuşkusuz Allah’ın hesaplaşması çok çabuktur.»"},{"n":5,"t":"Bugün size temiz olan yiyecekler helal kılındı. Kendilerine kitap verilenlerin yiyecekleri size ve sizin yiyecekleriniz de onlara helâldir. İffetli ve hür mümin kadınları - zinaya ve metreslik ilişkisine başvurmaksızın- namuslu biçimde mehirlerini verdiğiniz takdirde size helâldir. Kim iman etmeyi reddederse yaptığı ameller boşa gitmiştir, o kimse ahirette hüsrana uğrayanlardan olur."},{"n":6,"t":"Ey iman edenler, namaza kalktığınızda yüzlerinizi, dirseklere kadar ellerinizi, -başlarınızı meshedip– topuk kemiklerine kadar ayaklarınızı yıkayın. Eğer cünüpseniz temizlenin; şayet hasta veya yolculukta iseniz ya da ayak yolundan gelmişseniz yahut kadınlara yaklaşmışsanız ve su bulamamışsanız temiz bir toprağa teyemmüm edin, yüzlerinizi, ellerinizi onunla meshedin. Allah sizi zorlamak istemez, Allah sizi arıtıp üzerinize olan nimetini tamamlamak ister ki şükredesiniz."},{"n":7,"t":"Allah’ın size yönelik nimeti ile «Duyduk ve uyduk» dediğiniz zaman, O’na verdiğiniz bağlayıcı sözü hatırlayınız. Allah’tan korkunuz. Hiç kuşkusuz Allah, kalplerinizin özünü bilir."},{"n":8,"t":"Ey müminler, her davranışınızda Allah’ı sıkı sıkıya gözeten ve adalete bağlı şahitlik eden kimseler olunuz. Sakın herhangi bir gruba karşı duyduğunuz kin, sizi adaletsiz davranmaya sevk etmesin. Adil olunuz, takvaya en yakın tutum budur. Allah’tan korkunuz. Hiç kuşkusuz Allah, bütün yaptıklarınızdan haberdardır."},{"n":9,"t":"Allah, iman edip iyi ameller işleyenleri bağışlayacağını ve kendilerine büyük mükafat vereceğini vaad etmiştir."},{"n":10,"t":"Küfre sapıp ayetlerimizi yalanlayanlar ise cehennemliktirler."},{"n":11,"t":"Ey müminler, Allah’ın size yönelik nimetini hatırlayınız. Hani bir grup size el uzatmaya yeltenmişti de Allah onların size el uzatmalarına engel olmuştu. Allah’tan korkunuz. Müminler Allah’a dayansınlar."},{"n":12,"t":"Allah, İsrailoğullarından kesin söz almış başlarına kendi aralarından on iki önder göndermiştik. Allah onlara demişti ki; «Ben sizinle beraberim. Eğer namazı kılar, zekatı verir, peygamberime inanır, onların tarafını tutar ve dünyada karşılığını beklemeksizin Allah’a borç verirseniz, kesinlikle kötülüklerinizi siler, sizleri altlarından ırmaklar akan cennetlere yerleştiririm. Bu sözleşmeden sonra içinizden kim kâfir olursa doğru yoldan sapmış olur."},{"n":13,"t":"Verdikleri sözlerden caydıkları için onları lanetledik ve kalplerini katılaştırdık. Onlar kelimelerin anlamlarını değiştirirler, kendilerine verilen öğütlerin başlıcalarını unuturlar. Pek azı dışında, onlardan sürekli ihanet görürsün. Yine de onları bağışla, yaptıklarına aldırış etme. Hiç şüphesiz Allah iyi davrananları sever."},{"n":14,"t":"Biz hristiyanız diyenlerden de kesin söz almıştık. Fakat onlar da kendilerine verilen öğütlerin başlıcalarını unuttular. Bu yüzden kıyamet gününe kadar aralarına düşmanlık ve kin saldık. Allah şimdi yaptıklarını ilerde onlara tek tek bildirecektir."},{"n":15,"t":"Ey Kitap Ehli, size bizim peygamberimiz geldi. Bu peygamber, elinizdeki kitabın öteden beri gizli tuttuğunuz bir hükmünü açıklıyor, bir çoğuna da değinmiyor. Gerçekten size Allah tarafından bir ışık, bir açıklayıcı kitap geldi."},{"n":16,"t":"Allah, rızası peşinde koşanları, bu kitap sayesinde selamet yollarına erdirir, onları, kendi izni ile, karanlıklardan aydınlığa çıkarır, doğru yola iletir."},{"n":17,"t":"Allah Meryemoğlu Mesih’dir diyenler kesinlikle kafir olmuşlardır. Onlara de ki; Eğer Meryemoğlu İsa’yı annesini ve yeryüzünde bulunan varlıkların tümünü yok etmek istese O’na kim engel olabilir? Göklerde, yeryüzünde ve ikisi arasında bulunan tüm varlıklar Allah’ın egemenlik tekelindedir. O dilediğini yaratır. Allah’ın gücü herşeye yeter."},{"n":18,"t":"Yahudiler ve hristiyanlar «Biz Allah’ın evladları ve sevdikleriyiz» dediler. Onlara de ki; o halde O, niçin günahlarınızın yüzünden azaba çarptırıyor. Aslında O’nun yarattığı birer insansınız. O dilediğini affeder, dilediğini azaba çarptırır. Gökler, yeryüzünün ve ikisi arasında bulunan tüm varlıklar Allah’ın egemenlik tekelindedir. Dönüş O’nadır."},{"n":19,"t":"Ey Kitap Ehli, «Bize bir müjdeci, bir uyarıcı gelmedi» demeyesiniz diye peygambersiz geçen bir ara dönemin arkasından size gerçekleri açıklayan peygamberimiz geldi. İşte size müjdeleyici, uyarıcı geldi. Allah’ın gücü her şeye yeter."},{"n":20,"t":"Hani Musa kavmine demişti ki, ey kavmim, Allah’ın size verdiği nimetleri hatırlayınız. Hani içinizden peygamberler çıkardı, sizleri hükümdar yaptı, size dünyada hiç kimseye vermediğini verdi."},{"n":21,"t":"Ey kavmim, Allah’ın sizin için yurt olarak belirlediği kutsal topraklara giriniz, sakın geri dönmeyiniz, yoksa hüsrana uğrayanlardan olursunuz."},{"n":22,"t":"Dediler ki, «Ya Musa, orada zorba bir kavim var. Onlar oradan çıkmadıkça biz oraya kesinlikle girmeyiz. Eğer çıkarlarsa o zaman oraya gireriz.»"},{"n":23,"t":"Allah’tan korkan ve O’nun nimetine ermiş iki kişi dedi ki; «Onların üzerine şehrin kapısından yürüyünüz. Kapıdan içeri girince onları yendiniz demektir. Eğer müminseniz sırf Allah’a dayanınız.»"},{"n":24,"t":"Dediler ki, «Ey Musa, onlar orada olduğu sürece biz oraya kesinlikle girmeyiz. Git sen Rabbin ile birlikte savaş, biz burada kalıyoruz.»"},{"n":25,"t":"Musa dedi ki; «Ya Rabbi, kendimden ve kardeşimden başka hiç kimseye söz geçiremiyorum. Bizi bu yoldan çıkmış kavimden ayır.»"},{"n":26,"t":"Allah dedi ki; «Kırk yıl boyunca orası onlara yasaklandı. Bu süre içinde orada burada şaşkın şaşkın dolaşacaklardır. Yoldan çıkmış bu kavim için sakın üzülme."},{"n":27,"t":"Ey Muhammed, onlara Adem’in iki oğlunun gerçeğe dayalı hikayesini anlat. Hani ikisi birer kurban sunmuşlardı da birinin kurbanı kabul edilmiş öbürününki kabul edilmemişti. Kurbanı kabul edilmeyen kardeşine «yemin ederim ki seni öldüreceğim» deyince öbür kardeş şöyle dedi; «Allah sadece takva sahiplerinin ibadetlerini kabul eder.»"},{"n":28,"t":"Eğer sen öldürmek amacı ile elini bana doğru uzatacak olursan ben öldürmek amacı ile elimi sana doğru uzatacak değilim. Çünkü ben alemlerin Rabbi olan Allah’tan korkarım."},{"n":29,"t":"İstiyorum ki, hem kendi günahını hem de benim günahımı yüklenerek cehennemliklerden olasın. Zalimlerin cezası budur."},{"n":30,"t":"Buna rağmen öbür kardeş ihtiraslarına boyun eğerek kardeşini öldürdü ve böylece hüsrana uğrayanlardan oldu."},{"n":31,"t":"Bunun üzerine Allah, kardeşinin ölüsünü nasıl gözlerden saklayacağını göstermek üzere ona toprağı eşeleyen bir karga gönderdi. «Kardeş katili, eşinen kargayı görünce «Yazık bana, şu karga kadar olup kardeşimin cesedini gömemiyor muyum?» dedi ve arkasından ettiğine pişman olanlardan oldu."},{"n":32,"t":"Kim kısas gerekmeksizin veya yeryüzünde fesad işlemeksizin bir kimseyi öldürürse, bütün insanları öldürmüş gibi olur. Kim de onu kurtarırsa, bütün insanları kurtarmış gibi olur. Andolsun ki onlara Peygamberlerimiz mucizeler getirdiler, sonra buna rağmen, onların çoğu yeryüzünde taşkınlık edenler oldu."},{"n":33,"t":"Allah’a ve peygambere savaş açanların ve yeryüzünde kargaşa çıkaranların cezaları ya öldürmeleri ya idam etmeleri ya sağlı-sollu birer el ve ayaklarının kesilmesi ya da yaşadıkları yerlerden sürülmeleridir. Bu onların dünyadaki perişanlıklarıdır. Ahirette ise, kendilerini ağır bir azap beklemektedir."},{"n":34,"t":"Yalnız bunların içinde tarafınızdan yakalanmadan önce tevbe edenler olursa biliniz ki Allah affedicidir ve merhametlidir."},{"n":35,"t":"Ey müminler, Allah’tan korkunuz, sizi ona yakınlaştırabilecek her yolu arayınız, onun yolunda cihad ediniz ki, kurtuluşa eresiniz."},{"n":36,"t":"Kafirlere gelince eğer yeryüzünün tüm varlıkları bir kat fazlası ile birlikte kendilerinin olsa da bu servetlerini kıyamet gününün azabından kurtulmak için fidye olarak verseler bu fidyeleri kabul edilmez. Onları acıklı bir azap beklemektedir."},{"n":37,"t":"Onlar cehennemden çıkmak isteyecekler, fakat kesinlikle dışarı çıkamayacaklardır. Onlar için sürekli azap vardır."},{"n":38,"t":"Erkek ve kadın hırsızların ellerini kesiniz. Bu onların suçlarına karşılık Allah tarafından belirlenmiş caydırıcı bir cezadır. Hiç kuşkusuz Allah üstün iradeli ve hikmet sahibidir."},{"n":39,"t":"Fakat işlediği zulümden sonra tevbe edip islah olan kimse bilsin ki, Allah onun tevbesini kabul eder. Hiç şüphesiz Allah affedicidir ve merhametlidir."},{"n":40,"t":"Göklerin ve yeryüzünün egemenliğinin Allah’ın tekelinde olduğunu bilmiyor musun? O dilediğini azaba çarptırır ve dilediğini affeder. Hiç şüphesiz Allah’ın gücü herşeye yeter."},{"n":41,"t":"Ey peygamber, kalpleri iman etmediği halde ağızdan «inandık» diyenler ile yahudilerden oluşmuş küfür yarışçılarının tutumu seni üzmesin. Bunlar körü körüne yalana kanarlar ve senin karşına çıkmayan bir grubun sözlerini tutarlar. Onlar da kelimelerin anlamlarını çarpıtan ve «size şöyle bir fetva verilerse ona uyun, eğer başka bir fetva verilirse ona kulak asmayın» diyen kimselerdir. Eğer Allah birini saptırmayı dilerse sen Allah’a karşı onun için hiç bir şey yapamazsın. İşte bunlar, Allah kalplerini arıtmayı dilememiştir. Onlar için dünyada perişanlık vardır, ahirette de onları ağır bir azap beklemektedir."},{"n":42,"t":"Onlar körü körüne yalana kanarlar ve ısrarla haram yerler. Eğer sana gelirlerse istersen aralarında hüküm ver, istersen kendilerine yüz çevir. Eğer onlara yüz çevirirsen sana hiç bir zarar dokunduramazlar. Eğer aralarında hüküm verirsen adalet uyarınca hüküm ver. Çünkü Allah adalete bağlı olanları sever."},{"n":43,"t":"Onlar Allah’ın hükmünü içeren Tevrat ellerindeyken niçin senin hakemliğine başvuruyorlar ve sonra da verdiğin hükme yan çiziyorlar? Onlar kesinlikle imansızdırlar."},{"n":44,"t":"Doğrusu biz yol gösterici ve nurlandırıcı olarak Tevrat’ı indirdik. Kendisini Allah’a teslim etmiş Peygamberler, yahudilere onunla hükmederlerdi. Alimler ve fakihler de Allah’ın kitabını hıfza memur oldukları için yine hükümlerini onunla verirlerdi. Hepsi de Tevrat’a şahittiler. İnsanlardan korkmayın, benden korkun, ayetlerimi hiç bir değerle değiştirmeyin; Allah’ın indirdiği ile hükmetmeyenler, işte onlar kafirlerdir."},{"n":45,"t":"Tevrat’ta, yahudilere yazılı olarak bildirdik ki, canın karşılığı can, gözün karşılığı göz, burnun karşılığı burun, kulağın karşılığı kulak, dişin karşılığı diştir ve yaralamalarda da karşılıklılık (kısas) ilkesi geçerlidir. Kim kısas hakkını bağışlarsa bu onun günahlarına kefaret olur. Allah’ın indirdiği ayetlere göre hüküm vermeyenler ise zalimlerin ta kendileridirler."},{"n":46,"t":"Bu peygamberlerin ardından kendisinden önce gelen Tevrat’ı onaylayıcı olarak Meryemoğlu İsa’yı gönderdik; O’na doğru yol bilgisi ile ışık içeren, önündeki Tevrat’ı onaylayan, takvalılar için yol gösterici ve öğüt olan İncil’i verdik."},{"n":47,"t":"İncil ümmeti, Allah’ın bu kitapta indirdiklerine göre hüküm versin. Kim Allah’ın indirdiği ayetlere göre hüküm vermez ise onlar fasıkların, doğru yoldan çıkmışların ta kendileridir."},{"n":48,"t":"Sana da kendinden önceki kitabları tasdik edici ve onlara şahit olan Hak Kur’an’ı indirdik. Allah’ın indirdiği ile aralarında hükmet; gerçek olan sana gelmiş bulunduğuna göre onların heveslerine uyma! Her biriniz için bir şeriat, bir yol tayin ettik; eğer Allah dileseydi sizi bir tek ümmet yapardı, fakat bu, verdikleriyle sizi denemesi içindir; o halde iyiliklere koşun, hepinizin dönüşü Allah’adır. O ayrılığa düştüğünüz şeyleri size bildirecektir."},{"n":49,"t":"O halde onların arasında Allah’ın indirdiği ayetlere göre hüküm ver, onların keyfi arzularına uyma, onların seni Allah’ın indirdiği hükümlerin bir kısmından bile şaşırtmalarından sakın, eğer sana sırt çevirirlerse bil ki, Allah, günahlarının bazısı yüzünden onları cezalandırmak istiyor. Kuşku yok ki, insanların çoğu fasıktır."},{"n":50,"t":"Yoksa istedikleri cahiliye düzeni midir? Kesin inançlılara göre Allah’ın düzeninden, Allah’ın verdiği hükümden daha iyisi düşünülebilir mi hiç?"},{"n":51,"t":"Ey müminler yahudileri ve hristiyanları dost edinmeyiniz. Onlar birbirlerinin dostlarıdırlar. Sizden kim onları dost edinirse o onlardan olur. Hiç kuşkusuz Allah, zalimleri doğru yola iletmez."},{"n":52,"t":"Kalpleri hasta olanların «Başımıza bela gelir diye korkuyoruz» diyerek onlara koştuklarını görürsün. Olur ki Allah yakında size fetih nasib eder ya da kendi tarafından süpriz bir gelişme gösterir de o zaman bu kimseler kalplerinde gizli tuttukları duygulardan pişman olurlar."},{"n":53,"t":"O zaman müminler onlara «Bütün güçleri ile sizin yanınızda olacaklarına Allah adına yemin edenler bunlar mı?» derler. Onların bütün çabaları boşa gitmiş ve hüsrana uğrayanlardan olmuşlardır."},{"n":54,"t":"Ey müminler, içinizden kim dininden dönerse bilsin ki, yakında Allah öyle bir grup ortaya çıkaracak ki, Allah onları sevdiği gibi onlar da O’nu severler, bunlar müminlere karşı alçak gönüllü, kafirlere karşı onurlu davranırlar, Allah yolunda cihad ederler, hiç kimsenin yergisinden ve kınamasından çekinmezler. Bu Allah’ın bağışıdır, onu dilediğine verir. Allah’ın lütfu geniştir, O herşeyi bilir."},{"n":55,"t":"Sizin dostunuz ancak Allah, O’nun peygamberi ve namaz kılan, zekat veren rükua varan müminlerdir."},{"n":56,"t":"kim Allah’ı, Peygamberi ve müminleri dost edinirse bilsin ki, galip gelecek olanlar, yalnız Allah’ın tarafını tutanların grubudur."},{"n":57,"t":"Ey müminler, sakın sizden önce kendilerine kitap verilmiş olanlardan ve kafirlerden dininizi alaya alanları, eğlence konusu yapanları dost edinmeyiniz. Eğer gerçekten mümin iseniz, Allah’tan korkunuz."},{"n":58,"t":"Birbirinizi namaza çağırmak için ezan okuduğunuz zaman, onlar bu çağrınızı alaya alırlar, eğlence konusu yaparlar. Bu davranış onların aklı başında olmayan kimseler olmalarından kaynaklanıyor."},{"n":59,"t":"De ki; «Ey Kitap Ehli, bizden hoşlanmamanızın sebebi Allah’a, bize indirilen kitaba ve daha önce indirilmiş olan kitaplara inanmamız ve de çoğunuzun fasık, yoldan çıkmış kimseler olmanız değil midir?"},{"n":60,"t":"De ki; «Allah katında bundan daha kötü konumda olanları size bildireyim mi? Allah’ın lanet ettiği, gazabına uğrattığı, aralarından bir bölümünü çarpıtarak maymuna ve domuza dönüştürdüğü kimseler ile tağuta (şeytan) tapan kimselerdir. Bunlar konumları en kötü ve doğru yoldan en sapmış olanlardır."},{"n":61,"t":"Bunlar yanınıza geldiklerinde, «inandık» dediler. Oysa yanınıza, kafir olarak girmiş ve yine kafir olarak çıkmışlardır. Allah onların gizli tuttukları duyguları herkesten iyi bilir."},{"n":62,"t":"Onlardan çoğunun günahta, ölçüleri aşmakta ve haram yemekte birbirleriyle yarıştıklarını görürsün. Yaptıkları şey ne kadar kötüdür."},{"n":63,"t":"Allah’a bağlı bilginler ile din adamları bunları günah söz söylemekten ve haram mal yemekten sakındırsalar ya! Yaptıkları şey ne kadar kötüdür."},{"n":64,"t":"Yahudiler «Allah’ın eli sıkıdır» dediler. Bu sözlerinden ötürü elleri bağlansın. onlara lanet olsun! Tersine O’nun iki eli de açıktır, dilediği gibi verir. Rabbin tarafından sana indirilen ayetler onların çoğunun azgınlığını ve kafirliğini arttıracaktır. Onların arasına kıyamet gününe kadar sürecek bir düşmanlık ve kin saldık. Ne zaman savaş ateşini körüklediler ise, Allah onu söndürmüştür. Onlar yeryüzünde hep fesad, bozgunculuk peşinde koşarlar. Oysa Allah bozguncuları sevmez."},{"n":65,"t":"Eğer Kitap Ehli, iman edip kötülüklerden sakınsalar, günahlarını siler, onları nimetlerle dolu cennetlere koyardık."},{"n":66,"t":"Eğer onlar Tevrat’a, İncil’e ve Rableri tarafından kendilerine indirilen Kur’an’a uygun yaşasalardı, başları üzerinden ve ayakları altından kaynaklanan nimetler yerlerdi. Onların içinde ılımlı, aşırı davranışlardan sakınan bir kesim var. Fakat çoğu ne fena işler yapıyor!"},{"n":67,"t":"Ey Peygamber, Rabbin tarafından sana indirilen mesajı duyur. Eğer bunu yapmazsan O’nun elçisi olma görevini yerine getirmemiş olursun. Allah seni insanlardan korur. Allah kafirleri doğru yola iletmez."},{"n":68,"t":"De ki; «Ey Kitap Ehli, sizler Tevrat’a, İncil’e ve Rabbiniz tarafından size indirilen Kur’an’a gereği gibi uymadıkça boşluktasınız, hiçbir temele dayanmış değilsiniz.» Rabbin tarafından sana indirilen ayetler, onların çoğunun azgınlığını ve kâfirliğini arttıracaktır. O halde kâfirler için üzülme."},{"n":69,"t":"Yahudilerden sabiilerden (yıldızlara tapanlardan) ve hristiyanlardan Allah’a ve ahiret gününe inanarak iyi ameller işleyenler için korku söz konusu değildir, onlar hiç üzülmeyeceklerdir."},{"n":70,"t":"Biz İsrailoğullarından kesin söz aldık ve onlara çok sayıda peygamber gönderdik. Fakat peygamberler kendilerine nefislerinin hoşuna gitmeyen bir mesaj getirdikçe kimisini yalanlıyor, kimisini de öldürüyorlardı."},{"n":71,"t":"Bu cinayetleri hiçbir fitneye, hiçbir kargaşaya yol açmayacak sandılar. Gözleri kör ve kulakları sağır oldu. Sonra Allah tevbelerini kabul etti, fakat arkasından çoğu yine kör ve sağır oldu. Hiç şüphesiz Allah onların ne yaptıklarını görüyor."},{"n":72,"t":"Allah, Meryemoğlu Mesih’(İsa)dır diyenler kesinlikle kafir olmuşlardır. Oysa Mesih demişti ki; «Ey israiloğulları, benim ve sizin Rabbiniz olan Allah’a kulluk ediniz. Kim Allah’a ortak koşarsa Allah ona cenneti kesinlikle haram etmiştir, onun varacağı yer cehennemdir, zalimlerin hiçbir yardım edeni yoktur.»"},{"n":73,"t":"Allah üçün üçüncüsüdür diyenler de kesinlikle kâfir olmuşlardır. Tek Allah’tan başka hiçbir ilâh yoktur. Eğer onlar bu dediklerinden vazgeçmezler ise onların içinde kafirlerin başlarına acıklı bir azap gelecektir."},{"n":74,"t":"Onlar Allah’a tevbe etseler, O’ndan af dileseler olmaz mı? Hiç kuşkusuz Allah affedicidir, merhametlidir."},{"n":75,"t":"Meryemoğlu Mesih sadece bir peygamberdir. Ondan önce de birçok peygamber gelip geçmiştir. Annesi de özü- sözü doğru bir kadındı. Her ikisi de (öbür insanlar gibi) yemek yerlerdi. Bak biz onlara ayetlerimizi nasıl açık açık anlatıyoruz ve sonra bak onlar bu ayetleri nerelerinden çarpıtıyorlar!"},{"n":76,"t":"De ki; «Allah’ı bırakıp size ne zarar ve ne de yarar dokundurmaya gücü yetmeyen nesnelere mi tapıyorsunuz? Oysa Allah herşeyi işitir ve herşeyi bilir."},{"n":77,"t":"De ki; Ey Kitap Ehli, dininiz konusunda gerçeğe aykırı aşırılıklara kapılmayınız, sizden önceki dönemlerde sapıtmış, bir çoklarını saptırmış ve düz yolu şaşırmış kimselerin keyfi arzularına uymayınız."},{"n":78,"t":"İsrailoğullarının kafirleri, Davud’un ve Meryemoğlu İsa’nın dilinden lanetlenmiştir. Bu lânetlenmelerinin sebebi, onların Allah’a karşı gelmeleri ve O’nun sınırlarını çiğnemeleri idi."},{"n":79,"t":"Onlar işledikleri kötülüklerden birbirlerini sakındırmazlardı. Ne kadar kötü şeydi yaptıkları!"},{"n":80,"t":"Onların çoğunun kâfirleri dost edindiklerini görürsün. Bu davranışları kendilerine, Allah’ın gazabına uğramalarından ve sürekli azaba çarpılmalarından ibaret ne kadar kötü bir gelecek hazırlanmıştır."},{"n":81,"t":"Eğer onlar Allah’a, peygambere ve O’na indirilen Kur’an’a inansalardı, kâfirleri dost edinmezlerdi. Onların çoğu fasık, yoldan çıkmış kimselerdir."},{"n":82,"t":"İnsanlar arasında müminlere en amansız düşman olanların yahudiler ve Allah’a ortak koşanlar olduğunu göreceksin. Buna karşılık müminlere en çok sempati duyanların «Biz hırıstiyanız» diyenler olduğunu göreceksin. Çünkü hristiyanlar arasında Allah’a bağlı bilginler ve din adamları vardır ve onlar büyüklük taslamazlar."},{"n":83,"t":"«Ey Rabbimiz, inandık, bizi de gerçeğe şahit olanlar arasında yaz.»"},{"n":84,"t":"Rabbimizin bizi iyi kulları arasına katacağını umarken neden Allah’a ve bize gelen gerçeğe inanmayalım?"},{"n":85,"t":"Allah, onları bu sözlerinden dolayı, altlarından ırmaklar akan ve içlerinde ebedi olarak kalacakları cennetler ile ödüllendirdi. Bu iyi kulların mükafatıdır."},{"n":86,"t":"Kafirlere, ayetlerimizi yalan sayanlara gelince, onlar temelli cehennemliktir."},{"n":87,"t":"Ey müminler, Allah’ın size helal kıldığı tertemiz nimetleri haram saymayın, sınırları aşmayın. Hiç kuşkusuz Allah sınırları aşanları sevmez."},{"n":88,"t":"Allah’ın size verdiği rızıklardan helâl ve temiz olarak yiyiniz ve inandığınız Allah’tan sakınınız."},{"n":89,"t":"Allah size ağız alışkanlığı ile yaptığınız yeminlerden dolayı değil, bilerek yaptığınız yeminlerden dolayı sorumlu tutar. Böyle bir yemini bozmanın cezası, kefareti ya ailenize yedirdiğiniz yemeğin ortalaması üzerinden on yoksulu doyurmak ya yine on yoksulu giydirmek ya da bir köle azad etmektir. Bunların hiçbirini bulamayan (yapamayan) kimse, üç gün oruç tutar. İşte bozduğunuz yeminlerin cezası, kefareti budur. Yeminlerinizi tutun Allah, şükredesiniz diye, size ayetlerini böyle açık açık anlatıyor."},{"n":90,"t":"Ey müminler, içki, kumar, anıt taşları, fal okları şeytan işi iğrençliklerdendir, bunlardan uzak durun ki, kurtuluşa eresiniz."},{"n":91,"t":"Şeytan içki ve kumar yolu ile aranıza kin ve düşmanlık tohumları ekmek, sizi Allah’ı anmaktan ve namazdan alıkoymak ister. Artık bunlara son veriyorsunuz değil mi?"},{"n":92,"t":"Allah’a ve peygambere itaat ediniz, onlara karşı gelmekten sakının. Eğer bu direktife sırt çevirirseniz, biliniz ki, Peygamberimizin görevi sadece açıkça duyurmaktır."},{"n":93,"t":"İman edip iyi ameller işleyenler, Allah’tan korkup iman ettikleri, arkasından yine Allah’tan korkup müminliklerini devam ettirdikleri ve sonra yine Allah’tan korkup iyilik yaptıkları takdirde vaktiyle tattıkları haram yiyecek ve içeceklerden dolayı sorumlu tutulmazlar. Hiç kuşkusuz Allah, iyilik yapanları sever."},{"n":94,"t":"Ey müminler, Allah’ kendisini görmeksizin O’ndan kimlerin korktuğunu belirlemek için sizleri, ihramlı iken ellerinizin ve mızraklarınızın erişebileceği av hayvanları aracılığı ile dener. Kim bu denemeden sonra yasakları çiğnerse, kendisini acıklı bir azap beklemektedir."},{"n":95,"t":"Ey müminler, ihramlı iken av hayvanı vurmayınız. Kim bu durumdayken bilerek bir av hayvanı vurursa, işlediği suçun vebalini tadması için, içinizden iki adil kişinin vurulan av hayvanının dengi olduğuna karar verecekleri bir kurbanlığı, ceza olarak, Kabe ye ulaştırıp kesmesi ya kefaret olarak yoksullara yemek yedirmesi yada bunun dengi kadar gün oruç tutması gerekir. Allah geçmiştekileri affetmiştir. Fakat kim bir daha aynı suçu işlerse Allah ondan öç alır. Hiç kuşkusuz Allah üstün iradeli ve öç alıcıdır."},{"n":96,"t":"Deniz hayvanlarını avlamak ve hem kendiniz hem de yoksullar için besin maddesi olarak yemek size helâl kılındı. Huzurunda bir araya getirileceğiniz Allah’tan korkunuz."},{"n":97,"t":"Allah, Kabe’yi, o dokunulmaz evi, insanlar için güvenli bir barınak kıldı. Savaşılması yasak ayları, kurbanlıkları ve (bu bölgeye sığınma göstergesi olarak takılan) gerdanlıkları da bu dokunulmazlığın kapsamına aldı. Allah’ın göklerde ve yeryüzünde olan her şeyi bildiğini, O’nun bilgisinin her şeyi kapsamına aldığını bilesiniz diye bunu böyle yaptı."},{"n":98,"t":"Biliniz ki, Allah, azabı ağır olan, bunun yanında da affedici ve merhametli olandır."},{"n":99,"t":"Peygamberin görevi sadece duyurmaktır. Allah gerek açığa vurduğunuz ve gerekse gizlediğiniz duyguları iyi bilir."},{"n":100,"t":"De ki; «Murdar’ın çokluğu (yaygınlığı) senin beğenini kazanmış olsa da, murdar ile temiz (aslında) bir değildir. Buna göre ey sağduyulu kimseler, Allah’tan korkunuz ki, kurtuluşa eresiniz.»"},{"n":101,"t":"Ey müminler, açıklandıkları takdirde zorunuza gidecek konuları sormayın, eğer Kur’an inerken bu konuları sorarsanız onlar size açıklanır. Oysa Allah onlara değinmemiştir. Hiç şüphesiz Allah affedicidir, yumuşaktır. (halimdir)."},{"n":102,"t":"Sizden önceki bir ümmet böyle konuları sordu, fakat sonra bunlar yüzünden kafir oldular."},{"n":103,"t":"Allah, Bahire, Saibe, Vesile ve Hami diye bir şey koymamıştır. Fakat kâfirler Allah adına yalan uydururlar. Onların çoğu düşünme yeteneğinden yoksundur."},{"n":104,"t":"Onlara Allah’ın indirdiği Kur’an’a ve Peygambere uyunuz denildiğinde, «Atalarımızın miras bıraktığı düzen bize yeter» derler. Peki ya, ataları hiçbir şey bilmeyen, doğru yoldan uzak kimseler idiyse?"},{"n":105,"t":"Ey müminler, siz kendinizden sorumlusunuz, eğer siz doğru yolda olursanız sapıklar size zarar veremez. Hepinizin dönüşü Allah’adır. O size yapmış olduklarınızın iç yüzünü bildirecektir."},{"n":106,"t":"\"Billahi, akrabamız da olsa yeminimizi hiçbir karşılıkla değişmeyiz, Allah’ın emri olan şahidliği gizlemeyiz. Eğer gizlersek şüphesiz ki günahkarlardan oluruz.\""},{"n":107,"t":"Eğer daha sonra bu şahitlerin günaha girdiği ortaya çıkarsa, şahitlikleri yüzünden hakları çiğnenen iki kişi onların yerine geçerek «bizim şahitliğimiz onlarınkinden daha doğrudur, biz hiçbir hakkı çiğnemiyoruz, yoksa zalimlerden oluruz» diye yemin ederler."},{"n":108,"t":"Bu, şahidliği gerektiği gibi yapmalarını veya yeminlerinden sonra yeminlerin kabul edilmemesinden korkmalarını daha iyi sağlar. Allah’dan korkun ve iyi dinleyin. Allah fasık kimselere yol göstermez."},{"n":109,"t":"Allah, bütün peygamberleri bir araya getireceği gün insanlar çağrılarınıza ne cevap verdi? diye sorar, Peygamberler de; bizim birşey bildiğimiz yok. Hiç şüphesiz sen gaybleri bilensin derler."},{"n":110,"t":"‘Bu apaçık bir büyüdür’ demişlerdi de ben onların sana zarar vermelerini önlemiştim.\""},{"n":111,"t":"Hani havarilere vahiy yolu ile, «Bana ve peygamberime inanınız, diye direktif vermiştim de bunun üzerine onlar da, «inandık, şahid ol ki bizler müslümanız» dediler."},{"n":112,"t":"Hani havariler Ey Meryemoğlu İsa, senin Allah’ın bize gökten bir sofra indirebilir mi?» diye sordular da İsa onlara «Eğer mümin iseniz Allah’tan korkunuz» demişti."},{"n":113,"t":"Havariler O’na dediler ki, «İstiyoruz ki, o sofranın yemeklerinden yiyelim, kalplerimiz güven bulsun, bize doğru söylediğini kesinlikle bilelim ve olayın tanıklarından olalım."},{"n":114,"t":"Bunun üzerine Meryemoğlu İsa şöyle dedi; «Allah’ım, ey Rabbimiz, bize gökten bir sofra indir ki bu gün hem öncekilerimiz hem de sonrakilerimiz için bir bayram ve senin bize gösterdiğin bir mucize olsun. Bize rızık ver. Sen rızık verenlerin en hayırlısısın.»"},{"n":115,"t":"Allah dedi ki; Ben o sofrayı size indireceğim, ama ondan sonra kim kafir olursa onu hiç kimseyi çarptırmadığım bir azaba çarptırırım."},{"n":116,"t":"Hani Allah «Ey Meryemoğlu İsa sen mi, Allah dışında beni ve annemi ilah edinin dedin?» İsa şöyle dedi; «Haşa seni her türlü noksanlıktan tenzih ederim, gerçek olmadığını bildiğim bir sözü söylemek bana yakışmaz, eğer böyle birşey söyleseydim sen bunu bilirdin, Sen benim içimdekini bilirsin, fakat ben Senin özündekini bilemem. Hiç kuşkusuz Sen gaybleri bilensin."},{"n":117,"t":"Ben onlara sadece bana emrettiğini yani «Benim ve sizin Rabbiniz olan Allah’a kulluk ediniz dedim. Aralarında bulunduğum sürece onların üzerinde gözetleyici oldum. Fakat sen canımı alınca onların tek gözetleyicisi Sen oldun. Her şeyin şahidi Sensin."},{"n":118,"t":"Eğer onları azaba çarptırırsan, onlar senin kullarındır, eğer günahlarını affedersen kuşku yok ki Sen üstün iradeli ve hikmet sahibisin."},{"n":119,"t":"Allah dedi ki; Bugün, doğruların doğruluklarının yararını görecekleri gündür, onlar için altından nehirler akan ve içlerinde ebedi kalacakları cennetler vardır. Allah onlardan razıdır, onlar da ondan razıdırlar. İşte o büyük kurtuluş, o büyük başarı budur."},{"n":120,"t":"Göklerin, yeryüzünün ve her ikisinde bulunan tüm varlıkların egemenliği Allah’ın tekelindedir. O’nun herşeye gücü yeter."}],[{"n":1,"t":"Hamd, gökleri ve yeri yaratan, karanlıkları ve aydınlığı yoktan var eden Allah’a mahsustur. Durum böyleyken kafirler, bu yaratıkları Rabblerine denk tutuyorlar."},{"n":2,"t":"O sizi çamurdan yaratan, sonra da ecelinizi belirleyendir. Ayrıca O’nun katında tasarıya bağlanan bir vade daha vardır. Gerçek böyleyken sizler kuşkuya kapılıyorsunuz."},{"n":3,"t":"O göklerin de Allah’ıdır, yeryüzünün de Allah’ıdır. Sizin gizlinizi, açığınızı ve yaptığınız her şeyi bilir."},{"n":4,"t":"Oysa kâfirler kendilerine Rabblerinden gelen her ayete yüz çevirirler."},{"n":5,"t":"Nitekim onlar kendilerine gelen gerçeği, Kur’an’ı derhal yalanladılar. Fakat alay konusu ettikleri gerçeklerin haberleri ilerde kendilerine gelecektir."},{"n":6,"t":"Onlardan önceki nice kuşakları yok ettiğimizi görmediler mi? Oysa o kuşaklara size vermemiş olduğumuz derecede geniş yerleşme ve yaşama imkânları vermiş, yurtlarına gökten bol yağmurlar yağdırmış, ayakları altından nehirler akıtmıştık. Fakat işledikleri günahlar yüzünden onları yok ederek arkalarından başka kuşaklar yarattık."},{"n":7,"t":"Eğer sana kağıda yazılmış, somut bir kitap indirmiş olsaydık da onu kâfirler elleri ile tutsalardı, «Bu apaçık bir büyüden başka bir şey değil» diyeceklerdi."},{"n":8,"t":"Onlar «Muhammed’e bir melek indirilseydi ya» dediler. Eğer melek indirseydik, onların işleri bitirilir, kendilerine hiç mühlet tanınmazdı."},{"n":9,"t":"Eğer meleklerden bir peygamber gönderseydik onu insan kılığında gönderecektik. O zaman da kâfirleri şimdiki yanılgılarının aynısına düşürmüş olurduk."},{"n":10,"t":"Senden önceki birçok peygamberler de alaya alınmıştı. Fakat bu alaycılar, alay konusu yaptıkları gerçek tarafından kıskıvrak kuşatılıverdiler."},{"n":11,"t":"Onlara de ki; ’’Dünyayı geziniz de peygamberleri yalanlayanların sonu nice oldu, görünüz?»"},{"n":12,"t":"De ki; «Göklerde ve yerde olanlar kimindir?» De ki; «Allah’ındır.» O merhametliliği üzerine görev yazdı. Sizleri geleceği kuşkusuz olan Kıyamet günü kesinlikle biraraya getirecektir. Kendilerine kıyanlar var ya, buna sadece onlar inanmazlar."},{"n":13,"t":"Gecenin ve gündüzün barındırdığı her şey O’nundur. O her şeyi işiten ve bilendir."},{"n":14,"t":"De ki; «Allah’dan başkasını mı dost edineyim ki, O göklerin ve yerin yoktan var edicisidir, yedirir, fakat yedireni yoktur.» De ki; «Müslümanların ilki olmam emredildi, bana ’sakın Allah’a ortak koşanlardan olma’ denildi.»"},{"n":15,"t":"De ki; «Eğer Rabbimin buyruklarına karşı gelirsem büyük günün azabından korkarım.»"},{"n":16,"t":"O gün kim azaptan uzak tutulursa Allah onu kayırmış olur. İşte kesin kurtuluş budur."},{"n":17,"t":"Ve eğer Allah senin zarara uğramanı isterse, Zatından başka kimse ona engel olamaz; yok eğer senin için bir hayır dilerse, unutma ki O her şeyi yapmaya kadirdir."},{"n":18,"t":"Kulları üzerinde kesin egemendir. O’nun yaptığı her şey yerindedir, O her şeyden haberdardır."},{"n":19,"t":"De ki; «En büyük şahitlik kiminkidir?» De ki; «Benimle sizin aranızda Allah şahittir. Bu Kur’an, gerek sizi gerekse ulaştığı herkesi uyarayım diye bana vahyedildi, sizler Allah ile birlikte başka ilâhlar olduğuna mı şahadet ediyorsunuz?» De ki; «Ben buna şahadet etmem; ’De ki; «O tek bir ilahtır ve ben sizin O’na koştuğunuz ortaklardan uzağım»"},{"n":20,"t":"Kendilerine kitap verdiklerimiz, Peygamberi ve Kur’an’ı tıpkı çocuklarını tanıdıkları gibi tanırlar. Fakat kendilerine kıyanlar var ya, onlar asla inanmazlar."},{"n":21,"t":"Allah hakkında yalan uydurarak O’na iftira edenden ya da O’nun ayetlerini yalanlayandan daha zalim kim olabilir? Hiç kuşkusuz zalimler kurtuluşa eremezler."},{"n":22,"t":"O gün onların tümünü bir yere toplarız da sonra Allah’a ortak koşanlara «Hani, nerede Allah’ın ortakları olduklarını sandıklarınız?» diye sorarız."},{"n":23,"t":"Sonra bu müşrikliklerinin «Vallahi, ey Rabbimiz, biz müşrik değildik» demelerinden başka bir akıbetleri olmaz."},{"n":24,"t":"Kendileri aleyhinde nasıl yalan söylediklerini ve uydurma ilâhları tarafından nasıl yüzüstü bırakıldıklarını görüyor musun?"},{"n":25,"t":"Onların içinde seni dinleyenler vardır, biz onların kalblerini, Kur’an’ı anlamalarına engel oluşturacak biçimde, perdeledik, kulaklarını da sağırlaştırdık. Bu yüzden her türlü mucizeyi görseler bile ona inanmazlar. Nitekim bu kâfirler tartışmak için yanına geldiklerinde sana «Bu Kur’an, eskilerin masallarından başka bir şey değildir» derler."},{"n":26,"t":"Hem başkalarını Kur’an’dan uzak tutuyorlar, hem de kendileri ondan uzak duruyorlar. Böylece aslında kendilerini mahvediyorlar, ama bunun farkında değildirler."},{"n":27,"t":"Cehennemin başında durdurulduklarında onların «Ah ne olaydı, dünyaya geri gönderilsek de bir daha Rabbimizin ayetlerini yalanlamasak ve müminlerden olsak» dediklerini keşki görseydin!"},{"n":28,"t":"Hayır, sadece daha önce içlerinde sakladıklarının akıbeti önlerinde belirdi (diye böyle hayıflanıyorlar. Yoksa) eğer dünyaya geri gönderilseler yine sakındırıldıkları yola dönerler. Onlar gerçekten yalancıdırlar."},{"n":29,"t":"Onlar «Hayat, sadece dünyadaki hayatımızdan ibarettir, bir daha diriltilecek değiliz» dediler."},{"n":30,"t":"Onları Rabblerinin huzuruna çıkarıldıkları zaman keşki görsen! Allah, onlara «yeniden dirilmek gerçek değil miymiş?» der. Onlar «Rabbimiz hakkı için, evet» derler. Allah da onlara «O halde inkârcılığınızdan dolayı azabı çekiniz» der."},{"n":31,"t":"Allah’ın huzuruna çıkmayı yalanlayanlar gerçekten mahvolmuşlardır. Sonunda Kıyamet günü ansızın gelip çatınca sırtlarında taşıdıkları günah yükü altında «Eyvah, dünyada kaçırdığımız fırsatlara!» derler. Hey, sırtlarında taşıdıkları o yük, ne kötü bir yüktür!"},{"n":32,"t":"Dünya hayatı, oyundan ve eğlenceden başka bir şey değildir. Oysa günahlardan sakınanlar için Ahiret yurdu daha hayırlıdır. Buna aklınız ermiyor mu?"},{"n":33,"t":"Onların sözlerinin seni üzdüğünü biliyoruz. Aslında onlar seni yalanlamıyorlar, fakat o zalimler Allah’ın ayetlerini inkâr ediyorlar."},{"n":34,"t":"Peygamberlerin haberi sana da geldi."},{"n":35,"t":"Eğer onların sırt çevirmeleri ağırına gitti ise elinden geliyorsa yerkürenin derinliklerine inen bir yarık ya da göğe çıkaracak bir merdiven bul da onlara bir delil getir. Eğer Allah dileseydi, onları doğru yolda biraraya getirirdi. O halde sakın cahillerden olma."},{"n":36,"t":"Ancak işitebilenler çağrıya karşılık verebilirler. Ölülere gelince onları Allah diriltebilir, sonra hepsi O’nun huzuruna çıkarılırlar."},{"n":37,"t":"Muhammed’e, Rabbinden bir mucize indirilseydi ya dediler. De ki; «Allah’ın böyle bir mucize indirmeye gücü yeterlidir, fakat onların çoğu bilgiden yoksundur."},{"n":38,"t":"Yerde kımıldayan bütün hayvan türleri ve kanatları ile uçan bütün kuş çeşitleri sizler gibi birer canlılar topluluğudurlar. Biz hiçbir şeyi o kitabın dışında bırakmadık. Sonra bunlar, Rabblerinin huzurunda biraraya getirirler."},{"n":39,"t":"Bizim ayetlerimizi yalanlayanlar karanlıklar içinde bocalayan sağırlar ve dilsizlerdir. Allah dilediği kimseyi şaşırtır, dilediği kimseyi de doğru yola iletir."},{"n":40,"t":"De ki; «Eğer başınıza Allah’ın azabı kıyamet ile yüzyüze gelseniz, doğru konuşacaksanız söyleyin bakalım acaba (bu durumda) Allah’dan başkasına mı yalvarırsınız?"},{"n":41,"t":"Hayır, sırf O’na yalvarırsınız, O da dilerse feryadınıza konu olan belayı başınızdan aldırır, o zaman O’na koştuğunuz ortakları unutuverirsiniz."},{"n":42,"t":"Senden önceki birçok ümmetlere peygamberler gönderdik, dinlemediler. Bunun üzerine ola ki, bize yalvarırlar diye kendilerini sıkıntılara ve belâlara çarptırdık."},{"n":43,"t":"Bari sıkıntılarımız başlarına gelince bize yalvarsalardı ya! Fakat kalbleri katılaştı ve şeytan yaptıkları her şeyi onlara cazip gösterdi."},{"n":44,"t":"Onlar kendilerine yapılan uyarıları unutunca bütün nimetlerin kapılarını yüzlerine açtık, nihayet sahip oldukları nimetler yüzünden şımarıklığa kapıldıklarında kendilerini ansızın, kıskıvrak yakalayıverdik de bütün ümitleri suya düştü!"},{"n":45,"t":"Böylece, alemlerin Rabbi olan Allah’a hamdolsun ki, zalimler güruhunun arkası kesildi, soyu kurudu."},{"n":46,"t":"De ki, ’Eğer Allah kulaklarını sağır, gözlerini kör etse ve kalplerinize mühür vursa, acaba Allah’dan başka hangi ilâh bunları size geri verebilir?’ Nasıl ayetlerimizi çeşitli açılardan açıkladığımızı ve sonradan onların nasıl yüz çevirdiklerini görüyor musun?"},{"n":47,"t":"De ki, ’Ne sanıyorsunuz, eğer ansızın ya da açık bir şekilde size Allah’ın azabı gelse, zalimler güruhundan başkası mı helâk olur?’"},{"n":48,"t":"Biz peygamberleri müjdeleyici ve uyarıcı olarak göndeririz. Kim iman eder ve kendini ıslah ederse onlar için korku söz konusu değildir, onlar hiç üzülmezler de."},{"n":49,"t":"Ayetlerimizi yalanlayanlar ise fasıklıklarından, yoldan çıkmalarından ötürü azaba çarpılırlar."},{"n":50,"t":"De ki; «Ben size Allah’ın hazineleri elimin altındadır» demiyorum. Size meleğim de demiyorum. Sadece bana indirilen vahye uyuyorum. Hiç kör ile gören bir olur mu? Düşünmüyor musunuz?»"},{"n":51,"t":"Rabblerin huzurunda toplanacaklarından korkanları Kur’an aracılığı ile uyar. Onlar için Allah dışında bir dost ya da aracı yoktur. Ola ki, günahlardan sakınırlar."},{"n":52,"t":"Sırf Rabblerinin rızasını dileyerek sabah, akşam O’na yalvaranları yanından kovma, onların hesabından sana ve senin hesabından onlara bir şey düşmez ki, bu yüzden onları kovarak zalimlerden olasın."},{"n":53,"t":"Kendini beğenmişler «Allah’ın aramızdan seçerek lütfuna lâyık gördükleri bunlar mıdır?» desinler diye biz onları işte böylece sınavdan geçirdik. Allah şükredenleri herkesten iyi bilen değil mi?"},{"n":54,"t":"«Selâm size, Rabbiniz merhametliliği üzerine görev yazdı, buna göre içinizden kim bilmeyerek bir kötülük işler de arkasından tevbe edip kendini ıslâh ederse, hiç kuşkusuz, Allah bağışlayıcıdır, merhametlidir.»"},{"n":55,"t":"Günahkârların yolu açıkça belli olsun diye ayetlerimizi, işte böyle, ayrıntılı biçimde anlatıyoruz."},{"n":56,"t":"De ki; «Sizin Allah dışında yalvardığınız ilâhlara tapmak bana yasaklandı.» De ki; «Ben sizin keyfi arzularınıza uymam; uyarsam sapıtmış, doğru yolda gidenlerden olmamış olurum.»"},{"n":57,"t":"De ki; «Ben Rabbimden gelen kesin bir delile dayanıyorum, siz ise onu yalanladınız. Bir an önce gerçekleşmesini istediğiniz azap da benim yetkimde değildir. Egemenlik, Allah’ın tekelindedir. O gerçeği açıklar ve O ayırd edici hükmü verenlerin en hayırlısıdır.»"},{"n":58,"t":"De ki; «Eğer bir an önce gerçekleşmesini istediğiniz azap benim yetkimde olsaydı, aramızdaki mesele çoktan çözümlenmiş olurdu.» Allah, zalimleri herkesten iyi bilir."},{"n":59,"t":"Gayb’ın anahtarları Allah’ın katındadır, onu yalnız O bilir. Mutlaka O’nun bilgisi altında dalından düşen her yaprak, yerin karanlık derinliklerindeki her tane, yaş- kuru ne varsa hepsi apaçık bir kitaptadır."},{"n":60,"t":"Sizi geceleyin öldüren ve gündüzleyin neler yaptığını bilen O’dur. Sonra O sizi gündüzleyin diriltir, belirli hayat süreniz dolsun diye, sonra O’nun huzuruna döneceksiniz de O yapmış olduklarınızı size haber verecektir."},{"n":61,"t":"O, kulları üzerinde kesin egemendir. Size koruyucu melekler gönderir. Sonunda birinize ölüm gelince, elçilerimiz hiçbir görev kusuru yapmaksızın onun canını alırlar."},{"n":62,"t":"Sonra o canlar gerçek sahipleri olan Allah’a götürülürler. İyi biliniz ki, egemenlik yalnız O’nun tekelindedir ve hesap görenlerin en çabuğudur."},{"n":63,"t":"De ki; «Sizi karanın ve denizin karanlıklarından kurtaran kimdir? Ki O’na -Eğer bizi bu zor durumdan kurtarırsa kesinlikle şükredenlerden olacağız- diye açıktan ya da gizlice yalvarırsınız."},{"n":64,"t":"De ki; «Sizi bu zor durumdan ve bütün sıkıntılardan kurtaran Allah’dır. Sonra da O’na ortak koşuyorsunuz!»"},{"n":65,"t":"De ki; «O, size üstünüzden ya da ayaklarınızın altından azap göndermeye veya düşman gruplara ayırarak size birbirinizin hıncını, birbirinizin terörünü, acısını tattırmaya kadirdir.» Ola ki, anlarlar diye, ayetlerimizi çeşitli açılardan nasıl açıkladığımızı görüyor musun?"},{"n":66,"t":"Kur’an gerçek olduğu halde, senin kavmin onu yalanladı. Onlara de ki; «Ben sizin (akıbetinizi yönlendirmekle yükümlü) vekiliniz değilim.»"},{"n":67,"t":"Her haberin bir gerçekleşme zamanı vardır. İlerde anlayacaksınız."},{"n":68,"t":"Ayetlerimiz hakkında asılsız lâf ebeliğine dalanları gördüğünde (bu adamlar) başka bir söze geçinceye kadar yanlarından uzaklaş. Eğer şeytan sana yanlarından kalkmayı unutturursa, hatırladıktan sonra sakın o zalimler ile birlikte oturma."},{"n":69,"t":"Gerçi günahlardan sakınanlara onların hesabından hiçbir sorumluluk düşmez. Fakat söz konusu olan hatırlatmadır... Ola ki, sakınırlar."},{"n":70,"t":"Dinlerini oyun- eğlence konusu yapan ve dünya hayatına aldanan kimseleri bırak da Kur’an aracılığı ile şunu hatırlat ki, eğri davranışlarının, günahlarının tutsağı olan kimse ne Allah dışında bir yardım edici ve ne de bir aracı bulabilir. Eğer o bütün varını fidye olarak ortaya koysa kabul edilmez."},{"n":71,"t":"De ki; «Allah’ı bırakıp bize ne yarar ve ne de zarar dokunduramayan putlara mı yalvarırım? Allah bizi doğru yola ilettikten sonra tekrar geriye mi dönelim? Tıpkı arkadaşları tarafından ’bize gel’ diye doğru yola çağrıldığı halde, şeytanlar tarafından ayartılıp çöl ortasında şaşkın bırakılan kimse gibi mi olalım? De ki; «Doğru kılavuzluk, Allah’ın kılavuzluğudur, bize alemlerin Rabbine teslim olmamız emredildi.»"},{"n":72,"t":"Ayrıca bize «namazı kılınız ve Allah’dan korkunuz» diye emredildi. Huzurunda toplanacağınız O’dur."},{"n":73,"t":"Gökleri ve yeri gerçeğe dayalı olarak yaratan O’dur. Her şey «Ol» dediği gün oluverir. Sözü gerçektir. Sur’a üflendiği gün, egemenlik O’nun tekelindedir. O gizli- açık her şeyi bilir, O hikmet sahibidir ve her şeyden haberdardır."},{"n":74,"t":"Hani İbrahim, babası Azer’e dedi ki; «Sen putları ilâh mı ediniyorsun? Ben gerçekten gerek senin ve gerekse kavminin açık bir sapıklık içinde olduğunuzu görüyorum.»"},{"n":75,"t":"Biz İbrahim’e göklerin ve yerin görkemli egemenlik mekanizmasını böylece gösteriyorduk ki, o kesin inançlılardan olsun."},{"n":76,"t":"\"Ben batanları sevmem\"."},{"n":77,"t":"Arkasından ayı doğarken görünce «Rabbim budur» dedi. Fakat o da batınca «Eğer Rabbim beni doğru yola iletmeseydi, kuşkusuz sapıklardan biri olurdum» dedi."},{"n":78,"t":"Daha sonra güneşi doğarken görünce «Rabbim budur, bu daha büyüktür» dedi. Fakat o da batınca «Ey kavmim, ben sizin Allah’a ortak koştuğunuz putlardan uzağım.»"},{"n":79,"t":"Ben yüzümü, dosdoğru bir şekilde, gökleri ve yeri yoktan var edene yönelttim, ben O’na ortak koşanlardan değilim."},{"n":80,"t":"Kavmi onunla tartışmaya girişti, bunun üzerine onlara dedi ki; «Allah beni doğru yola iletmişken sizler, O’nun hakkında benimle tartışmaya mı kalkışıyorsunuz? Ben O’na koştuğunuz ortaklardan korkmam. Meğer ki, Rabbim hakkımda bir şey dilemiş olsun. Rabbimin bilgisi her şeyi kuşatmıştır. Halâ düşünmüyor musunuz?»"},{"n":81,"t":"Sizler Allah’ın haklarında size hiçbir kanıt indirmemiş olduğu putları O’na ortak koşmaktan korkmazken, ben sizin O’na koştuğunuz ortaklardan nasıl olur da korkarım? Eğer biliyorsanız, söyleyin bakayım, bu iki gruptan hangisi güvenli olmaya daha lâyıktır?"},{"n":82,"t":"İman edenler ve bu imanlarına zulüm karıştırmayanlar var ya, güven işte onlar içindir, doğru yolda olanlar onlardır."},{"n":83,"t":"Bu bizim kesin kanıtımızdır, onu kavmine karşı İbrahim’e verdik. Biz dilediğimizin derecesini kat kat yükseltiriz. Hiç kuşkusuz Rabbin hikmet sahibi ve her şeyi bilendir."},{"n":84,"t":"Biz O’na İshak’ı ve Yakub’u armağan ettik. Hepsini doğru yola ilettik. Daha önce de Nuh’u ve O’nun soyundan gelen Davud’u, Süleyman’ı, Eyyub’u, Yusuf’u, Musa’yı ve Harun’u doğru yola iletmiştik. Biz iyileri işte böyle mükâfatlandırırız."},{"n":85,"t":"Zekeriyya’yı, Yahya’yı, İsa’yı ve İlyas’ı da doğru yola ilettik. Hepsi de iyilerdendi."},{"n":86,"t":"İsmail’i, el-Yesa’yı, Yunus’u ve Lût’u da doğru yola ilettik. Hepsini de alemlere üstün kıldık."},{"n":87,"t":"Bunlardan bazılarının babalarını, soylarından gelenleri ve kardeşlerini de seçip doğru yola ilettik."},{"n":88,"t":"İşte bu Allah’ın doğru yoludur, dilediği kullarını ona iletir. Eğer onlar da Allah’a ortak koşsalardı, yapmış oldukları bütün iyilikler boşa giderdi."},{"n":89,"t":"onlar asla bu hakikatlerin inkarcısı olmazlar;"},{"n":90,"t":"İşte onlar Allah’ın doğru yola ilettiği kimselerdir. Sen de onların yolunu izle ve de ki; «Ben bu Kur’an’a karşılık sizden hiçbir ücret istemiyorum, o bütün alemlere yönelik bir hatırlatmadan başka bir şey değildir.»"},{"n":91,"t":"\"Musa’nın insanlara nur ve yol gösterici olarak getirdiği Kitab’ı kim indirdi? Ki siz onu parça parça kağıtlar haline getirip işinize geleni açıklandınız ve çoğunu gizlediniz. Atalarınızın da, sizin de bilmediğiniz şeyler size onunla öğretilmiştir.\" (Habibim) sen \"Allah\" de, sonra da onları daldıkları sapıklıkta bırak, oyalana dursunlar."},{"n":92,"t":"Bu Kur’an, anakent Mekke ile bu kentin çevresinde yaşayanları uyarasın diye sana indirdiğimiz, kendinden önceki kutsal kitapları onaylayan mübarek bir kitaptır. Ahirete inananlar bu kitaba da inanırlar. Onlar namazlarını devamlı olarak ve özenerek kılarlar."},{"n":93,"t":"\"Can verin, bugün Allah’a karşı haksız yere söylediklerinizden, O’nun ayetlerine büyüklük taslamanızdan ötürü alçaltıcı bir azab ile cezalandırılacaksınız\" derken bir görsen!.."},{"n":94,"t":"Tıpkı ilk yarattığımızda olduğu gibi, bize yine yalnız başınıza geldiniz, size vermiş olduğumuz her şeyi arkanızda bıraktınız, üzerinde etkili ortaklarımız olduklarını sandığınız aracılarınızı yanınızda görmüyoruz, aranızdaki bütün bağlar kopuverdi, ortağımız sandığınız ilâhlar sizden uzaklaşıp kayıplara karıştı."},{"n":95,"t":"Tohumu ve çekirdeği çatlatan Allah’tır. O ölüden diriyi ve diriden ölüyü çıkarır. İşte Allah budur. Nasıl olur da bu gerçeği görmezlikten geliyorsunuz?"},{"n":96,"t":"Sabahı açtıran O’dur. O geceyi dinlenme zamanı, güneş ile ayı zaman ölçme birimi yaptı. Bu, üstün iradeli ve her şeyi bilen Allah’ın düzenlemesidir."},{"n":97,"t":"O ki, karanın ve denizin karanlıklarında yolunuzu şaşırmayasınız diye size yıldızları kılavuz yaptı. Biz bilenler için ayetleri ayrıntılı biçimde açıkladık."},{"n":98,"t":"O ki, sizi bir tek nefisten oluşturdu. Arkasından sizin için bir barınma ve bir geçiş yeri belirledi. Biz anlayanlar için ayetleri ayrıntılı biçimde açıkladık."},{"n":99,"t":"O ki, gökten suyu indirdi. Her çeşit bitkiyi bu su aracılığı ile ortaya çıkardık, her bitkiden yeşil sürgün çıkardık, bu yeşil sürgünden taneleri üst üste binmiş başaklar, hurma tomurcuğundan yere sarkan salkımlar, üzüm bağları, zeytin ve nar çıkarırız. Bu meyvaların kimi birbirine benzer, kimi de benzemez. Bunların meyvalarına bir hamken ve bir de olgunlaşınca bakınız. Hiç kuşkusuz müminlerin bunlardan alacakları birçok ibret dersi vardır."},{"n":100,"t":"Müşrikler cinleri Allah’a ortak koştular. Oysa cinleri yaratan O’dur. Körükörüne, hiç yoktan O’na oğullar ve kızlar yakıştırdılar. Haşa O, onların uydurdukları sıfatlardan uzak ve yücedir."},{"n":101,"t":"O göklerin ve yerin yoktan var edicisidir. Eşi olmadığına göre, çocuğu nasıl olabilsin ki? Her şeyi O yarattı ve O her şeyi bilendir."},{"n":102,"t":"İşte Rabbimiz olan Allah budur. O’ndan başka ilâh yoktur, her şeyin yaratıcısı O’dur, o halde sırf O’na kulluk ediniz, her konuda dayanılacak tek merci O’dur."},{"n":103,"t":"Gözler O’nu görmez, fakat O gözleri görür. O latiftir (algılanamaz) ve her şeyden haberdardır."},{"n":104,"t":"Hiç kuşkusuz size Rabbinizden birçok uyarıcı kanıtlar, açık belgeler geldi. Kim bunları görürse, kendi lehine ve kim bunlara karşı göz yumarsa kendi aleyhine davranmış olur. Ben sizin başınızda korucu, bekçi değilim."},{"n":105,"t":"Kimileri sana «Sen bir yerden ders almışsın» desinler ve bilenlere de iyice anlatalım diye ayetlerimizi çeşitli açılardan açıklıyoruz."},{"n":106,"t":"Rabbinden sana gelen vahye uy, O’ndan başka ilâh yoktur, O’na ortak koşanlardan yüz çevir."},{"n":107,"t":"Allah dileseydi, onlar O’na ortak koşmazlardı. Biz seni onların başına korucu, bekçi dikmedik; sen onların vekili, davranışlarının sorumlusu da değilsin."},{"n":108,"t":"Onların Allah dışında yalvardıkları putlara sövmeyiniz ki, şaşkınlığa kapılarak körükörüne Allah’a sövmesinler. Böylece her ümmete davranış ve tutumlarını cazip gösterdik. Sonunda dönüşleri Rabblerinedir, O onlara yaptıklarının içyüzünü bildirir."},{"n":109,"t":"Onlar kesin bir dille Allah adına yemin ederek, eğer kendilerine bir mucize gelirse O’na mutlaka inanacaklarını söylediler. De ki; «Mucizeler sırf Allah’ın tekelindedir.» Hem bilmiyor musunuz ki, eğer o mucize gelse, onlar yine inanmazlar."},{"n":110,"t":"Onların gönüllerini ve gözlerini ters çevirerek kendilerini iman etmekten kaçındıkları ilk durumlarına döndürür ve azgınlıkları içinde debelenmeye bırakırız."},{"n":111,"t":"Eğer biz onlara melekler indirsek, ölüler kendileri ile konuşsa ve her şeyi biraraya getirip karşılarına koysaydık, Allah dilemedikçe yine inanmazlardı. Fakat çoğu bunu bilmez."},{"n":112,"t":"Böylece biz insandan ve cinden şeytanları her peygambere düşman kıldık. Bunlar birbirlerini aldatmak için yaldızlı sözler söylerler. Eğer Rabbin dileseydi, bunu yapamazlardı. Onları asılsız uydurmalarıyla başbaşa bırak."},{"n":113,"t":"Ahirete inanmayanların kalpleri bu yaldızlı uydurmalara kansın, onlardan hoşlansın ve işledikleri kötülükleri işlemeye devam etsinler diye."},{"n":114,"t":"Allah size ayrıntılı açıklamalar içeren kitabı indirmişken ben O’nun dışında bir hakeme mi başvurayım? Kendilerine kitap verdiklerimiz, Kur’an’ın gerçeğe dayalı olarak Allah tarafından indirildiğini bilirler. O halde sakın kuşkuya kapılanlardan olma."},{"n":115,"t":"Rabbinin sözü doğruluğun ve adaletin doruğuna erdi. O’nun sözlerini hiçbir güç değiştiremez. O her şeyi işitir ve bilir."},{"n":116,"t":"Eğer sen yeryüzünde yaşayan insanların çoğuna uyacak olursan, bunlar seni Allah’ın yolundan saptırırlar. Onlar sadece zanların, sanıların peşinde giderler, sırf tahmin yürütürler."},{"n":117,"t":"Hiç kuşkusuz Rabbin kimin kendi yolundan saptığını ve kimin doğru yolda olduğunu herkesten iyi bilir."},{"n":118,"t":"Eğer Allah’ın ayetlerine inanıyorsanız, O’nun adı anılarak kesilen hayvanların etlerinden yiyiniz."},{"n":119,"t":"Niçin Allah’ın adı anılarak kesilen hayvanların etlerinden yemiyorsunuz? Oysa Allah çaresizlik sonucu yemek zorunda kaldıklarınız dışında, size haram kıldığı etleri ayrıntılı biçimde açıkladı. Birçokları bilmeden keyfi arzularına uyarak insanları yoldan çıkarırlar. Hiç kuşkusuz Rabbin sınırı aşanları herkesten iyi bilir."},{"n":120,"t":"Ve günahın açığını da gizlisini de bırakın! Unutmayın ki, günahkar kimseler işledikleri yüzünden cezalandırılacaktır."},{"n":121,"t":"Allah’ın adı anılarak kesilmeyen hayvanların etlerinden yemeyiniz. Çünkü bu, Allah’ın yolundan sapmaktır. Şeytanlar dostlarına sizinle tartışmalarını telkin ederler. Eğer onlara uyarsanız, şüphesiz siz de müşrik olursunuz."},{"n":122,"t":"Ölü iken dirilttiğimiz ve kendisine insanlar arasında yürürken yararlandığı bir ışık verdiğimiz kimse, karanlıklar içinde bocalayıp oradan bir türlü dışarı çıkamayan kimse gibi midir? İşte böylece kâfirlere yaptıkları kötülükler çekici göründü."},{"n":123,"t":"Tıpkı bunun gibi her kentin kimi ileri gelenlerini o kentin hakka karşı komplo düzenleyen azılı günahkârları yaptık. Aslında onlar kendilerine karşı komplo düzenlerler, ama bunun farkında değildirler."},{"n":124,"t":"Onlara bir ayet gelince, «Allah’ın peygamberlerine verilen vahiy aynen bize de verilmedikçe asla inanmayız» derler. Oysa Allah peygamberlik görevini kime vereceğini herkesten iyi bilir. Bu azılı günahkârlar düzenledikleri komplolardan ötürü Allah katında aşağılanmaya ve ağır azaba çarpılacaklardır."},{"n":125,"t":"Allah kimi doğru yola iletmek isterse göğsünü İslâm’a açar. Kimi de saptırmak isterse göğsünü, sanki göğe çıkıyormuş gibi, dar ve tıkanık yapar. Bunun yanısıra Allah, inanmayanları iğrençliğe mahkum eder."},{"n":126,"t":"Bu, Rabbinin doğru yoludur. Biz öğüt almaya açık kimselere ayetlerimizi ayrıntılı biçimde anlattık."},{"n":127,"t":"Onlar için, Rabbleri katında, esenlik yurdu vardır. İşledikleri iyi amellerden ötürü O, onların dostudur."},{"n":128,"t":"Allah, insanlar ile cinleri biraraya topladığı gün, «Ey cinler, çok sayıda insanı ayarttınız» der. Cinlerin insandan yardakçıları da, «Ey Rabbimiz birbirimizi kullanarak bizim için belirlemiş olduğun süreyi doldurduk» derler. O da «Barınağınız, orada sürekli kalmak üzere cehennem ateşidir. Yalnız Allah’ın affetmeyi diledikleri müstesna» der. Hiç kuşkusuz Rabbin hikmet sahibidir ve her şeyi bilir."},{"n":129,"t":"İşte böylece biz, işledikleri kötülüklerden ötürü kimi zalimleri diğerlerinin peşine takarız."},{"n":130,"t":"Ey insanlar ve cinler, size ayetlerimi anlatan ve bu günle karşılaşacağınıza ilişkin sizi uyaran içinizden peygamberler gelmedi mi? Onlar da «Kendi aleyhimize şahitlik ederiz» derler. Dünya hayatı onları aldattı da kâfir olduklarına kendi aleyhlerine şahitlik ettiler."},{"n":131,"t":"Bu, şunu kanıtlar ki, Rabbin, gerçeklerden habersiz olan bir kentin halkını haksız yere asla helâk etmez."},{"n":132,"t":"Herkesin, yaptığı işlere göre birbirinden farklı derecesi vardır. Rabbin onların yaptıklarından habersiz değildir."},{"n":133,"t":"Rabbin hiçbir şeye muhtaç değildir ve merhamet sahibidir. O eğer dilerse sizi yok edip arkanızdan yerinize istediği başkalarını geçirebilir. Tıpkı sizi başka bir kavmin soyundan türettiği gibi."},{"n":134,"t":"Size va’dedilen akıbet kesinlikle yerine gelecektir. Siz onun önüne geçemezsiniz."},{"n":135,"t":"\"Ey kavmim! Elinizden geleni yapınız! Ben de yapacağım! Yurdun sonunun kimin lehine olduğunu yakında bileceksiniz. Gerçek şu ki, zâlimler iflâh olmazlar.\""},{"n":136,"t":"Onlar Allah’a, O’nun yarattığı ekinlerden ve hayvanlardan sınırlı bir pay ayırdılar. Asılsız saplantıları uyarınca «Bu Allah’ın bu da O’na koştuğumuz ortakların payıdır» derler. Fakat koştukları ortakların payı Allah’a geçmezken, Allah’ın payı bu ortaklara geçebiliyor. Ne kötü hüküm veriyorlar."},{"n":137,"t":"Tıpkı bunun gibi, bu düzmece ortaklar çoğu müşriklere öz evlatlarını öldürmeyi çekici göstermişlerdir ki, böylece hem fıtratlarını yozlaştırsınlar ve hem de dinlerini bozsunlar. Eğer Allah dileseydi bunu yapamazlardı. O halde onları asılsız uydurmaları ile başbaşa bırak."},{"n":138,"t":"Onlar saçma inançları uyarınca ’Bu hayvanlar ve ekinler dokunulmazdır. Bizim istediklerimizden başka hiç kimse onları yiyemez, bunlar da sırtlarına yük vurulması ve binilmesi yasak hayvanlardır’, dediler. Bazı hayvanları keserken de Allah’ın adını anmazlar, bunu yaparken ’Allah’ın emri böyledir’ diye O’na iftira ederler. Allah onları yaptıkları bu iftiralardan ötürü cezalandıracaktır."},{"n":139,"t":"Yine onlar ’Bu hayvanların karınlarındaki yavrular sadece erkeklerimize aittir, kadınlarımıza ise yasaktır. Eğer hayvanın yavrusu ölü doğarsa her ikisi de O’na ortak olur, dediler. Allah bu yakıştırmalarının cezasını verecektir. Hiç kuşkusuz Allah hikmet sahibidir ve her şeyi bilir."},{"n":140,"t":"Hiçbir bilgiye dayanmaksızın, aptalca evlatlarını öldürenler ve Allah’a iftira atarak O’nun verdiği rızıkları kendilerine yasaklayanlar, gerçekten hüsrana uğramışlardır. Onlar kesinlikle sapıtmışlardır, doğru yola gelecekleri yoktur."},{"n":141,"t":"O ki, çardaklı ve çardaksız bahçeleri, ürünleri değişik hurmaları ve ekinleri, yaprakları benzer ve meyvaları benzemez zeytin ve nar ağaçlarını yarattı. Bu ağaçlar ürün verdiklerinde meyvalarından yiyiniz ve hasat günü haklarını veriniz, fakat israf etmeyiniz, çünkü Allah israf edenleri sevmez."},{"n":142,"t":"Kimi yük taşıyan ve kiminin yününden yaygı yapılan hayvanları yaratan da O’dur. Allah’ın size verdiği rızıklardan yiyiniz ve şeytanın izinden gitmeyiniz. Çünkü o sizin açık düşmanınızdır."},{"n":143,"t":"(Erkekli dişili olmak üzere) sekiz baş olan bu hayvanların ikisi koyun, ikisi keçidir. De ki; «Allah bu hayvanların erkeklerini mi, dişilerini mi, yoksa dişilerin rahimlerinin içerdiği yavruları mı haram kıldı? Eğer doğru söylüyorsanız, bana bilimsel bir açıklama yapınız?»"},{"n":144,"t":"Geride kalanların ikisi deve, ikisi sığırdır. De ki; «Allah bunların erkeklerini mi, dişilerini mi, yoksa dişilerin rahimlerinin içerdiği yavruları mı haram kıldı? Yoksa Allah’ın size bu direktifi verdiğinin somut tanıkları mısınız? Körü körüne insanları yoldan çıkarmak amacı ile Allah’a iftira eden, Allah adına yalan uyduran kimseden daha zalim kim olabilir? Hiç kuşkusuz Allah zalimleri doğru yola iletmez.»"},{"n":145,"t":"\"Bana vahyolunanda, ölü, akıtılmış kan, domuz eti –ki pistir- ve yoldan çıkararak Allah’dan başkası adına kesilen hayvandan gayrisini yemenin haram olduğuna dair bir emir bulamıyorum; fakat darda kalan başkasının payına el uzatmamak ve zaruret miktarını aşmamak üzere bunlardan da yiyebilir.\" Şüphesiz ki Rabb’in, Gafur’dur, Rahim’dir."},{"n":146,"t":"Yahudilere bütün tek tırnaklı hayvanları yasakladık. Onlara sığırların ve koyunların sırt, bağırsak ve kemik yağları dışında kalan içyağlarını da haram kıldık. Allah’ın ölçülerini çiğnedikleri için onları bu şekilde cezalandırdık. Söylediklerimiz kesinlikle doğrudur."},{"n":147,"t":"Eğer onlar seni yalanlarlarsa de ki; «Rabbim, yaygın rahmet sahibidir. Ama O’nun günahkârlara yönelik azabını hiç kimse geri savamaz.»"},{"n":148,"t":"Müşrikler diyecekler ki; «Eğer Allah dileseydi, ne biz ve atalarımız O’na ortak koşar ve ne de bu şeyi yasaklardık.» Onlardan öncekilerde bu şekilde peygamberlerini yalanladılar da azabımızın acısını tattılar. Onlara de ki; «Önümüze koyacağınız bir bildiğiniz var mı? Siz sadece sanının, yakıştırmaların peşinden gidiyorsunuz, sırf tahminlere dayanıyorsunuz.»"},{"n":149,"t":"De ki; «Yetkin delil, Allah’ın tekelindedir. Eğer O dileseydi, hepinizi doğru yola iletirdi.»"},{"n":150,"t":"De ki; Allah’ın bu yasakları koyduğuna şahitlik edecek tanıklarınızı getiriniz bakalım. Eğer onlar bu yolda şahitlik ederlerse, sakın şahitliklerini onaylama. Ayetlerimizi yalanlayanların, ahirete inanmayanların ve Rabblerine eş koşanların keyfi arzularına uyma."},{"n":151,"t":"O’na hiçbir şeyi ortak koşmayın. Ana- babaya karşı iyi davranınız. Yoksulluk kaygısı ile evlâtlarınızı öldürmeyiniz. Sizin de onların da rızkını biz veririz. Kötülüklerin açığına da gizlisine de yaklaşmayınız. Haklı bir gerekçe yokken Allah’ın dokunulmaz saydığı cana kıymayınız. İşte Allah, ola ki düşünürsünüz diye size bu direktifleri veriyor."},{"n":152,"t":"Erginlik çağına erinceye kadar yetimin malına sadece niyetlerin en iyisi ile yaklaşınız. Ölçüde ve tartıda dürüst olunuz. Biz hiç kimseye kapasitesini aşan bir yük yüklemeyiz. Bir söz söylerken, söz konusu olan akrabanız bile olsa, doğru konuşunuz. Allah’a verdiğiniz sözü tutunuz. İşte Allah, ola ki düşünüp öğüt alırsınız diye size bu direktifleri veriyor."},{"n":153,"t":"İşte benim dosdoğru yolum budur, bu yola uyunuz. Sakın sizi Allah’ın yolundan ayrı düşürecek yollara girmeyiniz. İşte Allah, kötülüklerden sakınasınız diye size bu direktifi veriyor."},{"n":154,"t":"Sonra iyilik edenlere yönelik nimetimiz tamama ersin, her şey ayrıntılı biçimde açıklansın, doğru yol kılavuzu ve rahmet olsun diye Musa’ya tevratı verdik. Ola ki, Rabblerinin huzuruna çıkacaklarına inanırlar."},{"n":155,"t":"Bu Kur’an bizim indirdiğimiz kutsal bir kitaptır. Ona uyunuz ve kötülüklerden sakınınız, ki, size merhamet edilsin."},{"n":156,"t":"Onu size indirdi ki, «Bizden önceki iki ümmete (yahudiler ile hristiyanlara) kitap indirildi ve biz onların okuduklarından habersiz kaldık» diyemeyesiniz."},{"n":157,"t":"Yine diyemeyesiniz ki, «Eğer bize de kitap indirilseydi, doğru yola onlardan daha sıkı sarılırdık.» Çünkü size de Rabbinizden açık belge, doğru yol kılavuzu ve rahmet geldi. Allah’ın ayetlerini yalanlayıp onlara yüz çevirenlerden daha zalim kim olabilir? Ayetlerimize yüz çevirenleri, bu yüz çevirmelerinden ötürü azapların en kötüsüne çarptıracağız."},{"n":158,"t":"«Bekleyin bakalım, biz de bekliyoruz.»"},{"n":159,"t":"Dinlerinin öngördüğü inanç ve ümmet birliğini parçalayarak çeşitli akımlara bölünenler ile, senin hiçbir ilişkin yoktur. Onların işi Allah’a kalmıştır. Allah onlara ilerde yaptıklarının akıbetini bildirecektir."},{"n":160,"t":"Kim Allah’ın huzuruna bir iyilikle varırsa kendisine on katı verilir. Kim Allah’ın huzuruna bir kötülük ile varırsa sadece onun dengi olan cezaya çarptırılır. Ne iyilik edenlere, ne kötülük işleyenlere haksızlık edilmez."},{"n":161,"t":"De ki; «Rabbim beni doğru yola, insanların tüm ihtiyaçlarına cevap veren dine, Allah’ın birliğine inanan ve O’na ortak koşanlardan olmayan İbrahim’in inanç sistemine iletti.»"},{"n":162,"t":"De ki; «benim namazım, ibadetlerim, hayatım ve ölümüm tüm varlıkların Rabbi olan Allah içindir.»"},{"n":163,"t":"O’nun ortağı yoktur. Bana böyle emredildi. Ben müslümanların ilkiyim."},{"n":164,"t":"De ki; «Allah her şeyin Rabbi iken, ben O’ndan başka bir ilâh mı arayayım? Herkesin işlediği kötülüğün sorumluluğu kendisine aittir. Hiç kimse başkasının kötülüğünün sorumluluğunu taşımaz. Sonunda Rabbinize döneceksiniz. O size anlaşmazlığa düştüğünüz meselelerin içyüzünü bildirecektir."},{"n":165,"t":"Sizi yeryüzünde halife yapan ve verdiği nimetler hakkında sınavdan geçirmek için bazılarınızın derecesini diğer bazılarınızdan üstün kılan O’dur. Hiç şüphesiz Rabbinin cezalandırması gecikmesizdir, aynı zamanda O, bağışlayıcı ve merhametlidir."}],[{"n":1,"t":"Elif, Lâm, Mim, Sad"},{"n":2,"t":"Bu Kur’an, kendisi ile insanları uyarasın ve müminlere öğüt veresin diye sana indirilen bir kitaptır. O halde bu görevi yaparken sakın ruhun sıkılmasın."},{"n":3,"t":"Rabbiniz tarafından size indirilen mesaja uyunuz, O’nun dışında başka dostlar edinip peşlerinden gitmeyiniz. Ne kadar kıt düşüncelisiniz!"},{"n":4,"t":"Biz nice kentleri yokettik. Azabımız, onları, ya geceleyin ya da öğle uykuları sırasında yakalayıverdi."},{"n":5,"t":"Azabımıza uğradıkları andaki tek feryadları «Biz gerçekten zalimdik» demekten ibaret oldu."},{"n":6,"t":"Kendilerine peygamber gönderilenleri de peygamberleri de sorguya çekeceğiz."},{"n":7,"t":"Onlara olup bitenleri bilgimize dayanarak kesinlikle bir bir anlatacağız. Zira onlar hiçbir zaman bilgi alanımız dışında kalmamışlardı."},{"n":8,"t":"O gün tam doğru tartı vardır. Kimlerin tartıları ağır çekerse, onlar kurtuluşa ermişlerdir."},{"n":9,"t":"Kimlerin tartıları hafif kalırsa, onlar ayetlerimiz karşısında takındıkları zalimce tutumları yüzünden kendilerini mahvetmiş olurlar."},{"n":10,"t":"Size yeryüzünde yurt sağladık, orada size çeşitli geçim kaynakları bağışladık. Ne kadar az şükrediyorsunuz!"},{"n":11,"t":"Sizi yarattık, arkasından belirli bir biçime soktuk, sonra meleklere «Ademe secde edin!» dedik. İblis dışında hepsi secde etti. Sadece o secde edenlerden olmadı."},{"n":12,"t":"Allah İblis’e Secde etmeni emrettiğimde seni secde etmekten alıkoyan ne oldu? dedi. O da «Ben ondan üstünüm, beni ateşten, onu ise çamurdan yarattın» dedi."},{"n":13,"t":"Allah ona o halde in oradan, orada büyüklük taslamak haddine düşmedi. Çık dışarı, sen alçağın birisin, dedi."},{"n":14,"t":"İblis, «Bana insanların tekrar dirilecekleri güne kadar mühlet ver» dedi."},{"n":15,"t":"Allah «Sen mühlet verilenlerden birisin» dedi."},{"n":16,"t":"İblis dedi ki; «Beni kışkırtıp sapıklığa düşürdüğün için, andolsun ki, doğru yolun üzerinde pusu kurup insanların yolunu keseceğim."},{"n":17,"t":"Sonra önlerinden, arkalarından, sağlarından, sollarından onlara sokulacağım da çoğunluğunu şükreder bulamayacaksın.»"},{"n":18,"t":"Allah dedi ki; «Çık oradan yerilmiş ve kovulmuş olarak! Andolsun ki, insanlardan kim sana uyarsa, onları ve sizi birlikte cehenneme dolduracağım.»"},{"n":19,"t":"Ey Adem, sen ve eşin cennette oturunuz, istediğinizi nerede bulursanız yiyiniz. Yalnız şu ağaca yaklaşmayın. yoksa zalimlerden olursunuz."},{"n":20,"t":"Fakat şeytan, gözlerinden saklı tutulan ayıp yerlerini meydana çıkarmak amacı ile onlara şu sözleri fısıldadı. Rabbiniz, ya melek olmayasınız ya da burada sürekli kalacakların arasına katılmayasınız diye size bu ağacı yasakladı."},{"n":21,"t":"Onlara ’Ben gerçekten sizin iyiliğinizi istiyorum’ diye yemin etti."},{"n":22,"t":"Ben size o ağacı yasaklamamışmıydım, şeytanın açık düşmanınız olduğunu size söylememiş miydim?"},{"n":23,"t":"Adem ile eşi dedi ki; «Ey Rabbimiz, biz kendimize zulmettik, eğer bizi bağışlamaz, bize acımazsan kesinlikle hüsrana uğrayanlardan oluruz.»"},{"n":24,"t":"Allah dedi ki, «Oradan aşağıya ininiz, şeytan ile siz birbirinizin düşmanısınız, sizler belirli bir süre yeryüzünde barınacak geçineceksiniz.»"},{"n":25,"t":"Orada yaşayacak, orada ölecek ve tekrar diriltilerek oradan çıkarılacaksınız."},{"n":26,"t":"Ey insanoğulları, size ayıp yerlerinizi örtecek ve süslenmenizi sağlayacak elbiseler gönderdik. Takva elbisesi bunlardan daha hayırlıdır. Bu Allah’ın ayetlerinden biridir. Ola ki, düşünüp ders alırlar."},{"n":27,"t":"Ey insanoğulları, şeytan ana-babanızı elbiselerinden soyundurup ayıp yerlerini meydana çıkararak cennetten çıkardığı gibi sizleri de ayartıp tuzağa düşürmesin. Sizin şeytanı ve adamlarını göremeyeceğiniz yerlerden onlar sizi görürler. Biz şeytanları inanmayanlara dost yaptık."},{"n":28,"t":"Onlar bir kötülük işlediklerinde ’Biz atalarımızdan böyle gördük, böyle yapmamızı emreden Allah’dır’ derler. Onlara de ki; Allah kötülük işlemeyi emretmez. Allah adına bilmediğiniz bir şeyi mi söylüyorsunuz?"},{"n":29,"t":"De ki; «Rabbim bana ölçülü ve dengeli olmayı emretti. Her secde yerinde ve anında tüm varlığınızla O’na yönelerek müşriklikten tamamen arınmış bir bağlılıkla O’na dua ediniz. Sizi ilkin yarattığı gibi yine O’na döneceksiniz.»"},{"n":30,"t":"Allah, insanların bir kesimini doğru yola iletti, bir kesimi de sapıklığı haketti. Çünkü onlar Allah’ı bir yana bırakarak şeytanları dost edindiler ve (buna rağmen) doğru yolda olduklarını sanıyorlar."},{"n":31,"t":"Ey insanoğulları, her mescide girişinizde güzel elbiseler giyiniz. Yiyiniz, içiniz, fakat israf etmeyiniz. Çünkü Allah israf edenleri sevmez."},{"n":32,"t":"De ki; «Allah’ın kullarının yararına sunduğu güzellikleri ve temiz yiyecekleri kim haram etti? De ki; Bunlar, dünya hayatında müminler içindir kıyamet günü ise sadece onlarındır, biz ayetlerimizi bilenlere böyle ayrıntılı biçimde açıklıyoruz.»"},{"n":33,"t":"De ki; «Allah sadece açık gizli bütün kötülükleri, günahı, haksız saldırıyı, Allah’ın hakkında hiçbir delil indirmediği şeyleri O’na ortak koşmanızı ve Allah hakkında bilmediklerinizi söylemeyi haram kıldı."},{"n":34,"t":"Her toplumun belirlenmiş bir eceli vardır. Ecelleri geldiğinde onu ne bir an erteleyebilirler ve ne de bir an öne alabilirler."},{"n":35,"t":"Ey insanoğulları, size sizden olan peygamberler gelerek, ayetlerimi açıkladıkları zaman kimler kötülüklerden sakınıp kendilerini düzeltirlerse, onlar için artık korku sözkonusu değildir ve onlar üzülmezler de."},{"n":36,"t":"Ayetlerimizi yalanlayanlar, onlara burun kıvıranlar ise, orada ebedi kalmak üzere cehennemliktirler."},{"n":37,"t":"Allah adına yalan uydurandan ya da O’nun ayetlerini yalanlayanlardan daha zalim kim olabilir? Onlara kitaptaki payları erişir. Sonunda canlarını almak üzere elçilerimiz yanlarına geldiklerinde kendilerine ’Allah’ın dışında taptığınız putlar hani nerede? deyince, Koyup gittiler bizi’ derler. Böylece kâfir olduklarına dair kendileri şahitlik ederler."},{"n":38,"t":"Allah onlara «Sizden önce gelip göçen cin ve insan toplulukları yanında cehenneme giriniz» der. Her cehenneme giren topluluk yoldaşına lânet okur. Sonunda hepsi biraraya gelince sonrakiler, kendilerinden öncekiler için «Ey Rabbimiz, bizi bunlar yoldan çıkardı, onun için bunlara bir kat daha fazla cehennem azabı çektir» derler. Allah da onlara «Herbirinizin azabı ikiye katlanmıştır, ama bilmiyorsunuz.»"},{"n":39,"t":"Öncekiler de, kendilerinden sonrakilere, «Sizin de bizden bir farkınız yoktu. O halde siz de işlediğiniz kötülüklerin karşılığı olan azabı çekiniz» derler."},{"n":40,"t":"Ayetlerimizi yalanlayanlar ve onlara burun kıvıranlar var ya, gökyüzü kapıları yüzlerine açılmaz ve deve, iğne deliğinden geçmedikçe cennete giremezler. Biz ağır suçluları işte böyle cezalandırırız."},{"n":41,"t":"Onlara bir cehennem döşeği ile üzerlerini örtecek bir cehennem yorganı verilir. Biz zalimleri işte böyle cezalandırırız."},{"n":42,"t":"İman edip iyi ameller işleyenlere gelince biz hiç kimseye gücünün yeteceğinden fazla yük yüklemeyiz. Onlar orada ebedi olarak kalmak üzere cennetliktirler."},{"n":43,"t":"Kalplerindeki kin, kıskançlık kalıntılarını söküp atmışlardır. Ayaklarının altında ırmaklar akar. Onlar şöyle derler; Bizi bu derece erdiren Allah’a hamdolsun. Eğer Allah bize yol göstermeseydi, biz kendiliğimizden bu dereceye eremezdik. Belli ki, Rabbimizin peygamberleri bize gerçeği getirmişlerdi, onlara şöyle seslenilir; İşte size cennet, işlediğiniz iyi amellerin karşılığı olarak onu hakettiniz."},{"n":44,"t":"Cennetlikler, cehennemliklere seslenerek, «Biz Rabbimizin bize vadettiklerini gerçekleşmiş bulduk, siz de Rabbinizin size yönelik vaadlerini gerçekleşmiş buldunuz mu?» derler. Cehennemlikler «evet» derler. Bu sırada aralarından biri yüksek sesle şöyle bağırır, «Allah’ın lâneti zalimlerin üzerine olsun.»"},{"n":45,"t":"Onlar insanları Allah yolundan alıkoyarlar, onu eğri göstermeye yeltenirler ve ahirete de inanmazlar."},{"n":46,"t":"İki taraf arasında bir set ve bu setin tepelerinde her iki grubu simalarından tanıyan kimseler vardır. Cennete girememiş, fakat gireceklerini uman bu kimseler cennetliklere «selâmun aleyküm» diye seslenirler."},{"n":47,"t":"Bunların bakışları, cehennemliklere doğru kaydırılınca da «Ey Rabbimiz, bizi zalimler ile biraraya getirme!» derler."},{"n":48,"t":"Bu tepelerdekiler, simalarından tanıdıkları bazı azılı kâfirlere de şöyle seslenirler. «Ne kalabalığınız ve ne de şımarmanıza yolaçan güçleriniz size yarar sağlamadı.»"},{"n":49,"t":"Allah onları hiçbir rahmete erdirmez diye haklarında yemin ederek küçümsediğiniz kimseler bunlar mıydı? Bu arada Allah onlara «Giriniz cennete, sizin için hiçbir korku sözkonusu değil artık, hiç üzülmeyeceksiniz» der."},{"n":50,"t":"Cehennemlikler cennetliklere Bize biraz su ya da Allah’ın size sunduğu yiyeceklerden biraz bir şeyler ikram ediniz? diye seslenirler. Cennetlikler ise «Allah her ikisini de kâfirlere haram kıldı» derler."},{"n":51,"t":"Onlar dinlerini oyun ve eğlence yerine koydular, dünya hayatı kendilerini baştan çıkardı. Onlar nasıl bu günler ile karşılaşacaklarını unuttular ve ayetlerimizi ısrarla yalanladılarsa, bugün de biz onları unutuyoruz."},{"n":52,"t":"Biz onlara, ilme dayalı ayrıntılı açıklamalarla donattığımız, müminlere doğru yol kılavuzu ve rahmet olan bir kitap (Kur’an) gönderdik."},{"n":53,"t":"Onlar ille de onun somut yorumunu mu bekliyorlar? Somut yorumu ortaya çıktığı gün onu vaktiyle unutmuş olanlar Rabbimizin peygamberleri gerçeği getirmişlerdi. Şimdi bize şefaat edecek aracılarımız var mı ya da işlemiş olduğumuz kötülüklerden farklı işler yapmak üzere tekrar geri döndürülür müyüz derler. Onlar kendilerini hüsrana düşürmüşler ve uydurdukları ilâhlar ortalıkta görünmez olmuştur."},{"n":54,"t":"Rabbiniz Allah’dır, o gökleri ve yeri altı günde yarattı, sonra Arş’a kuruldu. O gündüzü sürekli kovalayan geceyi gündüzün üzerine örter. Güneş, ay ve yıldızlar O’nun buyruğuna başeğmişlerdir. İyi bilin ki, yaratma ve yönlendirme O’nun tekelindedir. Alemlerin Rabbi olan Allah yücelerin yücesidir."},{"n":55,"t":"Rabbinize yalvararak ve gizlice dua ediniz. Çünkü O haddi aşanları sevmez."},{"n":56,"t":"Yeryüzünde dirlik, düzen sağlandıktan sonra bozgunculuk çıkarmayınız. Allah’a korku ve umut içinde dua ediniz. Hiç kuşkusuz Allah’ın rahmeti iyi işler yapanlara yakındır."},{"n":57,"t":"O ki, rüzgârları rahmetinin önünde müjdeleyici olarak gönderir. Bu rüzgârlar yüklü bulutu havada yükseltince onu ölü bir yöreye gönderir, onun aracılığı ile oraya su indiririz, arkasından bunun aracılığı ile her türlü yerden bitiririz. İşte ölüleri de böyle yerden çıkarırız. Ola ki düşünür, ders alırsınız."},{"n":58,"t":"Verimli yöre, Allah’ın izni ile, ürünü cömertçe verir. Kıraç yöre ise cılız ürün verir. Biz şükredenler için ayetlerimizi böyle farklı açılardan açıklarız."},{"n":59,"t":"«Ey soydaşlarım, Allah’a kulluk ediniz, O’ndan başka bir ilâhınız yoktur, sizin hesabınıza büyük günün azabından korkuyorum.»"},{"n":60,"t":"Soydaşlarının ileri gelenleri ona ’senin açık bir sapıklık içinde olduğunu görüyoruz’ dediler."},{"n":61,"t":"Nuh onlara dedi ki, «Ey soydaşlarım, bende bir sapıklık yoktur. Tersine tüm varlıkların Rabbi tarafından gönderilen bir peygamberim."},{"n":62,"t":"Size Rabbimin mesajlarını iletiyorum, size öğüt veriyorum ve Allah’dan gelen vahiy sayesinde sizin bilmediğinizi biliyorum.»"},{"n":63,"t":"Kötülüklerden sakınasınız ve bu sayede merhamete eresiniz diye sizi uyarmak için içinizden biri aracılığı ile Rabbinizden size mesaj gelmiş olması tuhafınıza mı gitti?"},{"n":64,"t":"Onu yalanladılar. Bunun üzerine onu ve gemide onunla birlikte olanları kurtardık. Ayetlerimizi yalanlayanları ise boğduk. Kuşkusuz onlar kör bir kavim idiler."},{"n":65,"t":"Ad kavminde de kardeşleri Hud’u peygamber olarak gönderdik. Hud onlara ’Ey soydaşlarım, Allah’a kulluk ediniz, O’ndan başka bir ilâhınız yoktur. O’ndan korkmuyor musunuz?’ dedi."},{"n":66,"t":"Soydaşlarının ileri gelen kâfirleri O’na ’Biz seni aptal olarak görüyoruz ve bir yalancı olduğunu sanıyoruz’ dediler."},{"n":67,"t":"Bende bir aptallık yoktur, tersine tüm varlıkların Rabbi tarafından gönderilen bir peygamberim."},{"n":68,"t":"Size Rabbimin mesajlarını iletiyorum, sizin için güvenilir bir öğüt vericiyim."},{"n":69,"t":"Sizi uyarmak üzere içinizden biri aracılığı ile Rabbiniz tarafından size mesaj olması tuhafınıza mı gidiyor? Allah’ın sizi Nuh kavminin yerine geçirdiğini, sizi vücud yapısı bakımından onlardan daha güçlü yarattığını hatırlayınız. Allah’ın nimetlerini hatırlayınız ki kurtuluşa eresiniz."},{"n":70,"t":"Sen bize tek Allah’a kulluk edelim, atalarımızın taptıkları ilâhları bırakalım diye mi geldin. Eğer söylediklerin doğru ise ilerde çarpılacağımızı söylediğin azabı şimdi başımıza getir, bakalım."},{"n":71,"t":"Rabbinizin azabı ve öfkesi hakkınızda kesinleşti. Allah’ın haklarında hiçbir kanıt indirmediği, kendiniz ve atalarınız tarafından takılmış birtakım adlar üzerine benimle tartışmaya mı girişiyorsunuz? O halde bekleyin bakalım, ben de sizin ile birlikte bekliyorum."},{"n":72,"t":"Hud’u ve beraberindekileri rahmetimizin sonucu olarak kurtardık. Ayetlerimizi yalanlayarak inanmamış olanların ise kökünü kuruttuk."},{"n":73,"t":"’Ey soydaşlarım, Allah’a kulluk ediniz, O’ndan başka bir ilâhımız yoktur. Rabbinizden size bir belge geldi. Şu Allah’ın dişi devesi size bir delildir. Bırakın onu, Allah’ın çayırında otlasın, sakın ona bir kötülük etmeyin, yoksa acı bir azaba çarptırılırsınız.’"},{"n":74,"t":"Allah’ın sizi Ad kavminin yerine geçirdiğini ve ovalarında köşkler edinip dağlarında yontma evler yaptığınız bir bölgeye yerleştirdiğini hatırlayınız. Allah’ın nimetlerini hatırlayınız da yeryüzünde bozgunculuk yapmaktan kesinlikle kaçınınız."},{"n":75,"t":"Salih’in kendini beğenmiş soydaşları, içlerinden iman etmiş horlanmışlara, ezilenlere ’Salih’in Rabbi tarafından gönderildiğini biliyor musunuz?’ dediler. Onlar da ’Evet, biz onun aracılığı ile gönderilen mesaja inanıyoruz’ dediler."},{"n":76,"t":"Kendini beğenmişler de onlara ’Biz sizin inandığınızı inkâr ediyor, reddediyoruz’ dediler."},{"n":77,"t":"Arkasından Rabblerinin emrine başkaldırarak dişi deveyi boğazladılar ve ’Ey Salih, eğer gerçekten peygambersen, ilerde çarpılacağımızı söylediğin azabı şimdi başımıza getir, bakalım’ dediler."},{"n":78,"t":"Bu arada ani bir yer sarsıntısına tutuldular da oldukları yerde yığılıp kalıverdiler."},{"n":79,"t":"Bunun üzerine Salih, onlara sırt çevirdi ve ’Ey soydaşlarım, size Rabbimin mesajını ilettim, size öğüt verdim, fakat siz öğüt verenlerden hoşlanmıyorsunuz’ dedi."},{"n":80,"t":"«Sizler daha önce dünyada hiç kimsenin işlemediği bir fuhuş türünü mü işliyorsunuz?"},{"n":81,"t":"Sizler kadınları bırakıp, erkeklere şehvetle yaklaşıyorsunuz. Kuşkusuz siz her türlü ölçüyü çiğneyen, azgın bir toplumsunuz."},{"n":82,"t":"Soydaşlarının verdikleri tek cevap şu oldu; ’Lût’u ve arkadaşlarını kentinizden sürünüz, çünkü onlar temizliğe pek meraklı kimselermiş’ dediler."},{"n":83,"t":"Lût’u ve eşi dışındaki yakınlarını kurtardık. Eşi ise geride kalıp helak olanlardan oldu."},{"n":84,"t":"Onların üzerine müthiş bir yağmur yağdırdık. Gör bakalım, günahkârların sonu nasıl oldu?"},{"n":85,"t":"Medyen halkına da kardeşleri Şuayb’ı peygamber olarak gönderdik. Şuayb onlara dedi ki; ’Ey soydaşlarım, Allah’a kulluk ediniz, O’ndan başka bir ilâhınız yoktur. Rabbinizden size bir belge geldi. Ölçüde ve tartıda dürüst olunuz, insanların eşyalarını eksik vermeyiniz, yeryüzünde dirlik- düzen sağlandıktan sonra bozgunculuk çıkarmayınız. Eğer mümin iseniz, sizin için hayırlı olan tutum budur."},{"n":86,"t":"Bütün yol başlarında pusu kurup inananları tehditle Allah yolundan alıkoymayınız, bu yolu eğri göstermeye yeltenmeyiniz. Sayıca azken, Allah’ın sizi çoğalttığını hatırlayınız. Görünüz, bozguncuların sonu nasıl oldu?"},{"n":87,"t":"Eğer içinizden bir grup benim aracılığım ile gönderilen mesaja inanırken diğer bir grup buna inanmamış ise, Allah’ın aramızda hüküm vereceği güne kadar sabrediniz, o hüküm verenlerin en iyisidir."},{"n":88,"t":"O’nun kendini beğenmiş soydaşları dediler ki, ’Ya seni ve seninle birlikte inananları kentimizden süreriz, ya da dinimize dönersiniz Şuayb onlara dedi ki; ’İstemesek de mi?’"},{"n":89,"t":"Allah bizi sizin dininizden kurtardıktan sonra tekrar ona dönersek Allah’a yalan yere iftira atmış oluruz. Rabbimiz Allah dilemedikçe bir daha sizin dininize dönmemiz sözkonusu değildir. Rabbimizin bilgisi her şeyi kapsamına almıştır. Sırf Allah’a dayanırız biz. Ey Rabbimiz, soydaşlarımız ile aramızdaki anlaşmazlığı sen hak uyarınca çözüme bağla. Çünkü anlaşmazlıkları en iyi çözüme bağlayan sensin!’"},{"n":90,"t":"Soydaşlarının ileri gelenleri ’eğer Şuayb’a uyarsanız, kesinlikle hüsrana uğrar, mahvolursunuz’ dediler."},{"n":91,"t":"Bu arada ani bir yersarsıntısına tutuldular da oldukları yerde yığılıp kalıverdiler."},{"n":92,"t":"Şuayb’ı yalanlayanlar, sanki yurtlarında hiç oturmamış gibi oldular. Şuayb’ı yalanlayanlar, asıl hüsrana uğrayanlar, asıl mahvolanlar oldular."},{"n":93,"t":"Bunun üzerine Şuayb onlara sırt çevirdi ve ’Ey soydaşlarım, size Rabbimin mesajlarını ilettim, öğüt verdim, şimdi kâfir bir topluma nasıl acıyabilirim?’ dedi."},{"n":94,"t":"Peygamber gönderdiğimiz her ülkenin halkını, ola ki, bize yalvarırlar diye, mutlaka sıkıntılara ve belalara uğrattık."},{"n":95,"t":"«Atalarımız da hem sıkıntılı hem de sevinçli günler geçirmişlerdi» dediler. Bunun üzerine onları hiç ummadıkları bir sırada ansızın yakalayıverdik.»"},{"n":96,"t":"Eğer o ülkelerin halkları iman edip kötülüklerden sakınsalardı, göğün ve yerin bereket kapılarını yüzlerine açardık. Fakat yalanladılar, biz de onları işlediklerinin cezasına çarptırdık."},{"n":97,"t":"Acaba o ülkelerin halkları geceleyin uyurlarken başlarına azabımızın gelmeyeceğinden emin midirler?"},{"n":98,"t":"Acaba o ülkelerin halkları, kuşluk vakti eğlenirlerken, azabımızın gelmeyeceğinden emin midirler?"},{"n":99,"t":"Onlar Allah’ın tuzağına yakalanmayacaklarından emin midirler? Oysa hüsrana uğrayan toplum dışında hiç kimse kendini Allah’ın tuzağından emin sayamaz."},{"n":100,"t":"Üzerinde yaşadıkları toprakları eski yerlilerinden miras alanlar, istesek kendilerini günahları yüzünden musibetlere çarptırabileceğimizi, kalplerini mühürleyebileceğimizi ve kulaklarının işitemez olabileceğini, bu tarihi sürecin ışığında halâ kavrayamadılar mı?"},{"n":101,"t":"İşte şu ülkeler var ya, hani sana onlara ilişkin bazı tarihi olayları anlatıyoruz. Bunlara peygamberleri açık belgeler, mucizeler getirmişlerdi. Fakat mucizelerden önce yalanladılar! Mesajlara inanmaları sözkonusu olmadı. İşte Allah kafirlerin kalplerini böyle mühürler."},{"n":102,"t":"Onların çoğunda söze bağlılık diye bir şey bulamadık, tersine çoğunu yoldan çıkmış bulduk."},{"n":103,"t":"Sonra bu peygamberlerin arkasından Musa’yı ayetlerimiz ile Firavun’a ve yakın adamlarına gönderdik, fakat onlar ayetlerimize karşı zalimce bir tutum takındılar. Gör bakalım, bozguncuların sonu nice oldu?"},{"n":104,"t":"Musa dedi ki; «Ey Firavun, ben tüm varlıkların Rabbi tarafından gönderilmiş bir peygamberim.»"},{"n":105,"t":"bana Allah hakkında sadece doğruyu söylemek yaraşır. Size Rabbinizden açık bir belge, bir mucize getirdim, İsrailoğulları’nı benimle gönder. (Serbest bırak.)"},{"n":106,"t":"Eğer doğru söylüyorsan ve getirdiğin bir mucize varsa onu göster bakalım, dedi."},{"n":107,"t":"bunun üzerine Musa, elindeki değneği yere attı, değnek o anda sahici bir yılan oluverdi."},{"n":108,"t":"Ve elini yeninin altından çıkardı, bakanlar onun ak bir parıltı saçtığını gördüler."},{"n":109,"t":"\"Anlaşıldı ki bu kişi, bu işleri iyi bilen bir sihirbazmış,"},{"n":110,"t":"Sizi yurdunuzdan çıkarmak istiyor. Peki ne buyurursunuz?"},{"n":111,"t":"Onu kardeşi ile birlikte oyala ve bütün kentlere adam toplayacak elçiler gönder."},{"n":112,"t":"Bütün bilgili büyücüleri sana getirsinler."},{"n":113,"t":"Firavun’un büyücüleri geldiler. «Eğer biz yenecek olursak, bize bir ödül verilecek, değil mi?» dediler."},{"n":114,"t":"«Evet, yakın adamlarım arasına gireceksiniz» dedi."},{"n":115,"t":"Ya Musa, önce sen mi hünerini ortaya koyacaksın, yoksa biz mi önce hünerimizi ortaya atalım» dediler."},{"n":116,"t":"Musa, ’Önce siz atın’ dedi. Büyücüler hünerlerini ortaya atınca, insanların gözlerini büyülediler, onları ürküttüler ve müthiş bir büyü gösterisi gerçekleştirdiler."},{"n":117,"t":"Biz de Musa’ya ’Elindeki değneği yere at’ diye vahyettik, değnek onların bütün göz boyayıcılıklarını yutuverdi."},{"n":118,"t":"Böylece gerçek ortaya çıktı ve onların bütün marifetleri boşa çıktı."},{"n":119,"t":"Orada yenilgiye uğradılar ve burunları (onurları) kırılıverdi."},{"n":120,"t":"Bütün büyücüler secdeye kapandılar."},{"n":121,"t":"Tüm varlıkların Rabbine inandık dediler."},{"n":122,"t":"Musa ile Harun’un Rabbine."},{"n":123,"t":"Firavun onlara dedi ki; «Ben izin vermeden O’na inandınız, öyle mi? Bu, bu kentin halkını buradan çıkarabilmek için daha önceden burada tekrarladığınız bir komplodur, ama yakında başınıza neler geleceğini öğreneceksiniz!»"},{"n":124,"t":"Andolsun ki, sağlı-sollu birer el ve ayağınızı kesecek ve arkasından tümünüzü asacağım."},{"n":125,"t":"Büyücüler de dediler ki, «Biz zaten Rabbimize döneceğiz."},{"n":126,"t":"Sen ancak Rabbimizin ayetleri bize gelince onlara inandık diye bizden öç alıyorsun. ’Ey Rabbimiz, üzerimize sabır yağdır ve müslüman olarak al canımızı.’»"},{"n":127,"t":"Soydaşlarının ileri gelenleri Firavun’a dediler ki, Musa ile soydaşlarını toplumda kargaşalık çıkarsınlar, seni ve ilâhlarını boşlukta bıraksınlar diye mi bırakacaksın? Firavun dedi ki; Hayır onların erkeklerini öldürecek, kadınlarını sağ bırakacağız. Onları ezici baskımız altında tutacağız.»"},{"n":128,"t":"Musa soydaşlarına dedi ki; Allah’tan yardım isteyiniz ve sabrediniz. Yeryüzü Allah’ındır. Orayı dilediği kullarına miras kılar. Mutlu sonuç, günahlardan sakınanlarındır.»"},{"n":129,"t":"Soydaşları dediler ki; Sen gelmezden önce de geldikten sonra da işkence çektik. Musa dedi ki, «Umulur ki, Allah düşmanınızı yok eder ve sizleri onların yerine geçirir de nasıl hareket edeceğinize bakar.»"},{"n":130,"t":"Andolsun ki, biz Firavunoğulları’nı ola ki, akılları başlarına gelir diye yıllarca süren kuraklığa ve ürün kıtlığına uğrattık."},{"n":131,"t":"Onlar bir iyilikle karşılaşınca «bu kendimizden kaynaklanıyor» derler. Fakat eğer başlarına bir kötülük gelecek olursa, bunu Musa ile arkadaşlarının uğursuzluğuna yorarlar. Oysa onların kaderlerini belirleme yetkisi sırf Allah’ın tekelindedir, fakat çoğu bunu bilmiyor."},{"n":132,"t":"Musa’ya bizi büyülemek üzere ne kadar mucize gösterirsen göster, sana kesinlikle inanmayacağız dediler."},{"n":133,"t":"Biz de onlara, ayrı ayrı birer mucize olarak su baskını, çekirge sürüsü, zararlı böcek salgını, kurbağalar ve kan gönderdik. Yine de burun kıvırarak günahkâr bir toplum oldular."},{"n":134,"t":"Azap başlarına çökünce; «Ey Musa sana verdiği peygamberlik payesine dayanârak, bizim için Rabbine dua et. Eğer bu azabı başımızdan savarsan, andolsun ki, sana inanacak ve İsrailoğulları’nı seninle birlikte göndereceğiz» dediler."},{"n":135,"t":"Fakat o azabı günün birinde dolduracakları belirli bir sürenin sonuna kadar başlarından savar- savmaz hemen sözlerinden dönüverdiler."},{"n":136,"t":"Sonunda onlardan öç aldık. Ayetlerimizi yalanladıkları, onları umursamadıkları için kendilerini denizde boğduk."},{"n":137,"t":"O güne kadar horlanan, ezilen toplumu (yahudileri) bereketlerle donattığımız toprakların doğusuna ve batısına mirasçı kıldık. İsrailoğulları’nın sabırlarına karşılık, Rabbinin onlara verdiği güzel söz gerçekleşti. Firavun’un ve soydaşlarının ortaya koydukları eserleri ve yükselttikleri yapıları yıkıp yok ettik."},{"n":138,"t":"İsrailoğulları’nı denizden karşıya geçirdik. Yolda putlarına tapan bir topluma rastladılar, bunun üzerine «Ey Musa, bu adamların nasıl ilâhları varsa bize de öyle ilâhlar yap» dediler. Musa da onlara «Siz gerçekten cahil bir toplumsunuz.»"},{"n":139,"t":"Bunların uydukları sapık din yokolmaya mahkûmdur, işledikleri ameller de geçersizdir."},{"n":140,"t":"Dedi ki; «Allah sizi bütün varlıklara üstün kılmışken ben size Allah dışında bir ilâh mı arayayım?»"},{"n":141,"t":"Hani sizi firavun hanedanından kurtardık. Onlar size ağır eziyetler çektiriyor, erkeklerinizi öldürüp kadınlarınızı sağ bırakıyorlardı. Bu olaylar Rabbinizin size yönelik büyük bir sınavıdır."},{"n":142,"t":"Musa ile otuz geceliğine sözleştik, buna on gece daha ekledik, böylece Rabbinin belirlediği buluşma süresi kırk geceye ulaştı. Musa kardeşi Harun’a dedi ki; «Soydaşlarım arasında benim yerimi tut, kötülükleri düzelt, bozguncuların yoluna girme.»"},{"n":143,"t":"\"Ya Rabbi, münezzehsin, sana tevbe ettim, ben iman edenlerin ilkiyim\" dedi."},{"n":144,"t":"Allah dedi ki; «Ey Musa, mesajlarımla ve aracısız konuşmamla sana diğer insanlar üzerinde seçkin bir konum bağışladım. Sana verdiklerimi al ve şükredenlerden ol.»"},{"n":145,"t":"Onun için levhalarda her şeyle ilgili bir öğüt ve her şey hakkında bir açıklama yazdık. ’Bunlara sıkıca sarıl ve kavmine de bunlara en güzel şekilde uymalarını emret. Size fasıkların yurdunu göstereceğim.’"},{"n":146,"t":"Dünyadaki haksız yere büyüklük taslayanları ayetlerimden uzak düşüreceğim. Onlar görecekleri hiçbir ayete inanmazlar, eğer doğru yolu görseler de o yola girmezler, fakat sapık yolu görünce hemen ona koyulurlar. Bunun sebebi onların ayetlerimizi yalanlamaları, umursamamalarıdır."},{"n":147,"t":"Ayetlerimizi ve ahiret karşılaşmasını, hesaplaşmasını yalanlayanların tüm amelleri boşa gitmiştir. Görecekleri ceza işlediklerinin karşılığından başka bir şey mi olacak ki."},{"n":148,"t":"Soydaşları, Musa’nın ardından, ziynet eşyalarından yapılmış, böğürme sesi verebilen bir buzağı heykelini ilâh edindiler. Oysa görmüyorlar mıydı ki, O onlarla ne konuşabiliyor ve ne de kendilerine bir yol gösterebiliyor? Onlar bu heykeli ilâh edinerek, zalimlerden oldular."},{"n":149,"t":"Fakat başları ellerinin arasına düştüğünde (yaptıklarına pişman olduklarında), sapıtmış olduklarını gördüklerinde «Eğer Rabbimiz bize acımaz, bizi bağışlamaz ise, kesinlikle hüsrana uğrayanlardan, mahvolanlardan oluruz» dediler."},{"n":150,"t":"Musa kızgın ve üzgün olarak soydaşlarının yanına dönünce «Benim arkamdan yokluğumda ne kötü işler yapmışsınız? Yoksa Rabbinizin hükmünü öne almaya mı kalkıştınız?» dedi, levhaları yere attı ve kardeşinin başını tutup kendine doğru çekti. Kardeşi ise, «Ey anamoğlu, soydaşlarım beni saymadılar, horladılar, neredeyse beni öldüreceklerdi, beni düşmanları güldürecek biçimde hırpalama, zalimlerle bir tutma» dedi."},{"n":151,"t":"Musa dedi ki; «Ey Rabbim, beni ve kardeşimi bağışla, bizi rahmetinin kapsamına al, sen merhametlilerin en merhametlisisin.»"},{"n":152,"t":"Buzağıyı ilâh edinenler ise kesinlikle Rabblerinin öfkesine ve dünya hayatında alçaklığa uğrayacaklardır. Biz Allah hakkında asılsız iddialar ileri sürenleri, işte böyle cezalandırırız."},{"n":153,"t":"Çeşitli kötülükler işledikten sonra, arkasından tevbe edip, iman edenlere gelince, kuşku yok ki, Rabbi o aşamadan sonra bağışlayıcı ve merhametlidir."},{"n":154,"t":"Musa’nın öfkesi yatışınca attığı levhaları yerden aldı. Bu levhalarda Rabblerinden korkanlar için doğru yolu gösteren, rahmet niteliğinde yazılar vardı."},{"n":155,"t":"Musa belirlediğimiz buluşma için soydaşlarından yetmiş kişi seçti. Bunlar bir sarsıntıya tutulunca Musa dedi ki; «Ey Rabbim, eğer dileseydin onları da beni de daha önce yokederdin. Aramızdaki beyinsizlerin yaptıklarından dolayı bizi yok eder misin? Bu senin bir sınavından başka bir şey değildir. Bu sınav aracılığı ile dilediğini saptırır, dilediğini de doğru yola iletirsin. Sen bizim dostumuz, efendimizsin. O halde bizi bağışla, bize merhamet et, sen bağışlayıcıların en hayırlısısın.»"},{"n":156,"t":"Bize bu dünyada da ahirette de iyi olanı yaz. Biz sana yöneldik.» Allah dedi ki, «Azabıma dilediğimi çarptırırım. Fakat rahmetim her şeyi kapsamına almıştır. Onu günahlardan sakınanlara, zekâtı verenlere ve ayetlerimize inananlara yazacağım.»"},{"n":157,"t":"\"Onlar ki yanlarındaki Tevrat’ta ve İncil’de yazılı gördükleri, okuma yazması olmayan peygambere tabi olurlar, o peygamber onlara iyiliği emreder, onları kötülükten nehyeder, tertemiz ve iyi olan şeyleri helal, kötü ve zararlı şeyleri haram eder, onların sırtlarındaki ağır yükü kaldırır, onların zincirlerini kırar; o peygambere inanıp ona saygı gösteren, yardım eden, onunla birlikte gönderilen ışığa uyanlar yok mu, murada erenler işte onlardır\" buyurdu."},{"n":158,"t":"De ki; «Ey insanlar, ben Allah’ın hepinize gönderilmiş elçisiyim. O ki, göklerin ve yerin egemenliği tekelindedir, O kendisinden başka ilâh yoktur, diriltir ve öldürür. Geliniz Allah’a ve O’nun o okuma yazması olmayan (ümmi) peygamberine, Allah’a ve O’nun sözlerine inanan Peygamberine inanınız, O’na uyunuz ki, doğru yolu bulasınız.»"},{"n":159,"t":"Musa’nın soydaşlarından insanları hakka ileten ve hakka uygun, adil hükümler veren bir grup vardı."},{"n":160,"t":"\"Asanla taşa vur\" diye vahyettik; taştan on iki pınar fışkırdı, herkes içeceği yeri öğrendi. Bulutla üzerlerine gölge yaptık. Onlara kudret helvası ve bıldırcın indirdik. \"Size verdiğimiz rızıkların temiz olanlarından yiyin\" dedik. Onlar, karşı gelmekle bize değil kendilerine zulmediyorlardı."},{"n":161,"t":"Hani onlara denmişti ki; «Şu kasabada oturunuz, orada ne isterseniz yiyiniz, kasabanın kapısından girerken, başlarınızı eğerek ’Bağışla bizi’ deyiniz ki, günahlarınızı affedelim ve iyilik edenlerin mükâfatını arttıralım.»"},{"n":162,"t":"Fakat yahudilerin zalimleri o sözü kendilerine söylenmeyen başka bir sözle değiştirdiler. Biz de zalimliklerinden ötürü o zalimlere gökten ağır bir azap indirdik."},{"n":163,"t":"Onlara deniz kıyısındaki kasabanın halkının yaptığını sor. Hani onlar cumartesi yasağını çiğniyorlardı. Çünkü cumartesi yasağına uydukları gün onlara akın akın balık geliyordu, fakat cumartesi yasağını çiğnedikleri gün onlara hiç balık gelmiyordu. Öteden beri fasık oldukları için, biz onları böylece sınavdan geçiriyorduk."},{"n":164,"t":"Hani o kasabalılardan bir grup «Allah’a yokedeceği ya da ağır bir azaba çarptıracağı bir topluma ne diye öğüt veriyorsunuz» dedi de öğüt verenler «Rabbinize karşı haklı bir mazeretimiz olsun ve ola ki kötülükten sakınırlar» dediler."},{"n":165,"t":"Onlar kendilerine yapılan hatırlatmaları unutunca kötülükten sakındıranları kurtardık ve zalimleri, yoldan çıkmışlıkları yüzünden ağır bir azaba uğrattık."},{"n":166,"t":"Sakındırıldıkları kötülüğü ısrarla ve küstahça işlemeye devam edince kendilerine «birer aşağılık maymun olunuz» dedik."},{"n":167,"t":"Hani Rabbin açıkça bildirdi ki, işkencelerin en ağırını tattıracak zorbaları kıyamet gününe kadar yahudilerin başlarına musallat edecektir. Hiç kuşkusuz Rabbi çabuk cezalandırandır ve yine O, hiç kuşkusuz bağışlayıcı ve merhametlidir."},{"n":168,"t":"Biz yahudileri yeryüzünde çeşitli gruplara ayırdık. Kimileri iyi kimselerdir, kimileri öyle değildir. Ola ki doğru yola dönerler diye onları iyilikler ile ve kötülükler ile sınavdan geçirdik."},{"n":169,"t":"Onlardan sonra gelen kötü bir nesil Kitab’a mirasçı oldu. \"Biz nasıl olsa affedileceğiz\" diyerek Kitab’ın hükümlerini değiştirme karşılığı bu değersiz dünyanın mallarını alırlar. Yine ona benzer geçici bir şey kendilerine gelince onu da alırlar. Onlardan, Allah’a karşı ancak gerçeği söyleyeceklerine dair Kitab üzerine ahd alınmamış mıydı? Kitab’da onları okumamışlar mıydı? Allah’a karşı gelmekten sakınanlar için ahiret yurdu daha hayırlıdır. Daha aklınızı başınıza almayacak mısınız?"},{"n":170,"t":"Onlar ki, Kitab’a sımsıkı sarılırlar ve namazı kılarlar! Hiç kuşkusuz biz iyi amel işleyenlerin mükâfatını kayba uğratmaksızın tam olarak veririz."},{"n":171,"t":"Hani o dağı (Tur Dağı’nı) başları üzerine çıkarmıştık, onlar dağın üzerlerine düşeceğini sanmışlardı. Bu durumda kendilerine «Size verdiğimiz Kitab’a sımsıkı sarılınız ve içindeki mesajları sürekli aklınızda tutunuz."},{"n":172,"t":"Hani Rabbin, Ademoğulları’ndan onların bellerinden soylarını dışarı aldı ve Ben sizin Rabbiniz değil miyim? diyerek kendilerini birbirine şahit tutmuştu da onlar da «Evet şahidiz» demişlerdi. Allah kıyamet günü şöyle diyemeyesiniz diye bunu böyle yaptı; «bizim bundan haberimiz yoktu.»"},{"n":173,"t":"’Ya da şöyle diyemeyesiniz diye; «Vaktiyle atalarımız müşrik olmuşlardı, biz onlardan sonra gelen kuşaklardık, bizi eğri yola sapanların yaptıklarından dolayı mı mahvedeceksin?»"},{"n":174,"t":"İşte ayetlerimizi böyle ayrıntılı biçimde anlatıyoruz, ola ki, doğru yola dönerler."},{"n":175,"t":"Adama ayetlerimizi sunduk, fakat o onların içinden sıyrılıp çıktı. Arkasından onu şeytan peşine taktı da azgınlardan oldu."},{"n":176,"t":"Eğer dileseydik bu ayetler aracılığı ile onun düzeyini yükseltirdik, fakat o yere saplandı kaldı. Onun durumu üstüne varsan da, kendi haline bıraksan da dilini sarkıtıp hırlayarak soluyan köpeğin durumu gibidir. İşte ayetlerimizi yalanlayanların durumu budur. Bu hikâyeyi onlara anlat, ola ki, üzerinde düşünürler."},{"n":177,"t":"Ayetlerimizi yalanlayan ve kendilerine zulmeden toplumun durumu ne kötü bir örnektir."},{"n":178,"t":"Allah kimi doğru yola iletirse o doğru yolda olur, kimleri saptırırsa işte onlar, hüsrana uğrayanlardır."},{"n":179,"t":"Andolsun ki, birçok cini ve insanı cehennemlik olarak yarattık. Onların kalpleri var. Fakat anlamazlar, gözleri var, fakat görmezler, kulakları var, fakat işitmezler. Onlar hayvanlar gibidirler. Hatta hayvanlardan da sapıktırlar. Onlar gaflet içindedirler."},{"n":180,"t":"En güzel isimler Allah’ınkilerdir. O’na o isimler ile dua ediniz. O’nun isimleri konusunda eğriliğe sapanları sapıklıkları ile başbaşa bırakınız. Onlar yaptıklarının cezasını ilerde çekeceklerdir."},{"n":181,"t":"Yarattığımız insanlar içinde başkalarını hakka ileten ve hakka uygun, adil hükümler veren bir kesim varılır."},{"n":182,"t":"Ayetlerimizi yalanlayanları hiç farkına varmayacakları biçimde yavaş yavaş kötü akıbetlerine yaklaştıracağız."},{"n":183,"t":"Onlara mühlet veririm. Çünkü benim tuzağım sağlamdır."},{"n":184,"t":"Düşünmüyorlar mı ki, arkadaşları Muhammed’in deli olması sözkonusu değildir. O sadece açık bir uyarıcıdır."},{"n":185,"t":"Göklerin ve yerin görkemli mekanizmasını, Allah’ın yaşattığı her şeyi ve ecellerinin gerçekten yaklaşmış olabileceğini düşünmüyorlar mı? Kur’an’dan sonra hangi söze inanacaklar?"},{"n":186,"t":"Allah’ın saptırdığı kulu hiç kimse doğru yola iletmez. O sapıkları, azgınlıklar içinde debelenmeye bırakır."},{"n":187,"t":"Sana kıyamet anı hakkında sorarlar, ne zaman gelip çatacak diye. De ki, «onun bilgisi rabbimin tekelindedir. Vakti gelince, onu gerçekleştirip açığa çıkaracak olan O’dur.» Göklerin ve yerin ağırlığını kaldıramayacağı bu olay başınıza ansızın gelecektir. Sanki sen bu konuyu sürekli kurcalıyormuşsun gibi, sana onu soruyorlar. De ki; «onun bilgisi Allah’ın tekelindedir, fakat insanların çoğu bu gerçeği bilmezler.»"},{"n":188,"t":"De ki; ben kendime, Allah’ın dilediğinden başka bir yarar ya da zarar dokunduracak güçte değilim. Eğer görünmeyeni, gaybı bilseydim, daha çok iyilik elde ederdim. Ve başıma hiçbir kötülük gelmezdi. Ben sadece müminler toplumuna seslenen bir uyarıcı ve müjdeciyim."},{"n":189,"t":"O ki, sizi bir tek kişiden türetti, o tek kişinin beraberliğinde huzura ereceği eşini de kendi özünden yarattı, eşini kucaklayıp sarınca, hafif bir yük yüklendi. Onu bir süre taşıdı, sonra yükü ağırlaşınca, eşler birlikte «eğer bize sağlıklı bir çocuk verirsen, kesinlikle sana şükredenlerden oluruz» diye Allah’a dua ettiler."},{"n":190,"t":"Fakat Allah onlara sağlıklı bir çocuk verince, kendilerine Allah tarafından verilen bu çocuk üzerinde Allah’a ortak koştular. Oysa Allah onların koştuğu ortaklardan münezzehtir."},{"n":191,"t":"Hiçbir şey yaratmayan, kendileri birer yaratık olan varlıkları Allah’a ortak koşuyorlar?"},{"n":192,"t":"Oysa bu düzmece ortaklar, ne onlara yardım edebilirler, ne de kendilerine yardım edebilirler."},{"n":193,"t":"Eğer onları doğru yola çağırırsanız size uymazlar; onları çağırsanız da karşılarında suskun dursanız da sizin için birdir."},{"n":194,"t":"Allah’ın dışındaki yalvardıklarınız tıpkı sizin gibi birer kul, birer yaratıkdırlar. Eğer onlara ilişkin düşünceniz doğru ise, çağırın onları da, size karşılık versinler bakalım."},{"n":195,"t":"Onların yürüyecek ayakları mı var, tutacak elleri mi var, görecek gözleri mi var, yoksa işitecek kulakları mı var? De ki, Allah’a koştuğunuz ortakları çağırınız, sonra hiç göz açtırmaksızın bana karşı tuzak kurunuz."},{"n":196,"t":"Benim dostum, koruyucum Kitab’ı (Kur’an’ı) indiren Allah’tır. O iyileri dost edinir, koruması altında tutar."},{"n":197,"t":"O’nun dışındaki yalvardıklarınız ne size yardım edebilirler, ne de kendilerine yardım edebilirler."},{"n":198,"t":"Eğer onları doğru yola çağırırsanız işitmezler, onları sana bakar gibi görürsün, fakat görmezler."},{"n":199,"t":"Affı, kolaylaştırmayı prensip edin, iyi olanı emret ve cahillere aldırış etme!"},{"n":200,"t":"Eğer şeytandan gelen bir dürtmeye, bir kışkırtmaya uğrayacak olursan Allah’a sığın. Çünkü O, her şeyi işiten ve her şeyi bilendir."},{"n":201,"t":"Allah’tan korkanlar şeytandan gelen bir dürtmeye bir kışkırtmaya uğradıklarında, Allah’ın uyarılarını hatırlar ve hemen gerçeği görürler."},{"n":202,"t":"Şeytanın kardeşleri, dostları azgınlıkta şeytanlara yardakçılık ederler, sonra da ellerinden geleni yapmaya devam ederler."},{"n":203,"t":"Sen onlara bir ayet sunmadığın zaman «kendin bir ayet uydursaydın ya» derler. De ki; «Ben ancak Rabbim tarafından bana indirilen vahye uyuyorum. Bu Kur’an’daki ayetler müminler topluluğu için uyarıcı kanıtlar, doğru yol kılavuzu ve rahmettir.»"},{"n":204,"t":"Kur’an okunduğu zaman onu dikkatle ve sessizce dinleyiniz ki, size rahmet edilsin."},{"n":205,"t":"Rabbinin adını yalvararak korkarak ve yüksek olmayan bir sesle sabah akşam an ve gafillerden olma."},{"n":206,"t":"Rabbinin yanındakiler, burun kıvırıp O’na kulluk etmekten geri durmazlar, O’nu noksanlıklardan tenzih ederler ve O’na secde ederler."}],[{"n":1,"t":"Sana savaş ganimetlerinin bölüşümü hakkında soru sorarlar. De ki; ganimetler hakkında hüküm verme yetkisi Allah’a ve Peygamber’e aittir. Buna göre eğer mümin iseniz, Allah’dan korkunuz, ilişkilerinizi düzeltiniz, Allah’a ve Peygamber’e itaat ediniz."},{"n":2,"t":"Müminler ancak öyle kimselerdir ki, Allah anıldığında kalpleri ürperir, yanlarında Allah’ın ayetleri okunduğu zaman bu ayetler imanlarını arttırır, pekiştirir ve sadece Rabblerine dayanırlar."},{"n":3,"t":"Onlar namazı kılarlar ve kendilerine bağışladığımız rızıklardan başkalarına da verirler."},{"n":4,"t":"İşte gerçek mü’minler bunlardır. Onları Rabbleri katında yüksek dereceler, bağışlanma ve göz kamaştırıcı rızık beklemektedir."},{"n":5,"t":"(Ganimetlerin bölüşümü sırasında karşılaştığın bu hoşnutsuzluk) tıpkı mü’minlerin bir kesimi istemediği halde Rabbinin seni hak uğruna savaşmak için evinden çıkarmasına benzer."},{"n":6,"t":"Onlar sanki göz göre göre ölüme sürülüyorlarmış gibi, gerçek ortaya çıktıktan sonra seninle tartışıyorlar."},{"n":7,"t":"Allah, iki gruptan birinin hakkından geleceğinizi vadettiği zaman, siz güçsüz olan grubun size düşmesini istediniz. Oysa Allah sözleri aracılığı ile gerçeği yüceltmeyi ve kâfirlerin kökünü kazımayı, soylarını kurutmayı istiyordu."},{"n":8,"t":"Amaç, mücrimlerin hoşuna gitmese de gerçeği yüceltmek ve batılı ortadan kaldırmaktı."},{"n":9,"t":"Hani siz Rabbinizden yardım istediğinizde Allah bu çağrınıza ’Ben size ardarda gelecek bin kişilik bir melek ordusu ile yardım edeceğim’ diye cevap verdi."},{"n":10,"t":"Allah sadece müjde olsun ve kalpleriniz güven bulsun diye size bu yardımı yaptı. Zaten yardım, zafer doğrudan doğruya Allah katındandır. Hiç kuşkusuz Allah üstün iradeli ve hikmet sahibidir."},{"n":11,"t":"Hani Allah, korkunuzu gidermek için sizi hafif bir uykuya daldırmıştı. Ayrıca sizi temizlemek, şeytanın vesvesesinden arındırmak, kalplerinizi pekiştirip kaynaştırmak ve ayaklarınızın yere sağlam basmasını sağlamak için size gökten su indirdi."},{"n":12,"t":"Hani Rabbin meleklere «Ben sizinle beraberim, mü’minleri yüreklendirin, ben kafirlerin kalplerine korku salacağım, vurun boyunlarını, indirin darbelerinizi parmaklarına» diye vahyetti."},{"n":13,"t":"Şundan dolayı ki, onlar Allah’a ve Peygamber’e karşı çıktılar. Kim Allah’a ve Peygamber’e karşı çıkarsa bilsin ki, Allah’ın azabı ağırdır."},{"n":14,"t":"İşte size Allah’ın azabı, tadınız onu. Ayrıca kâfirler için cehennem azabı da vardır."},{"n":15,"t":"Ey mü’minler, kâfirlerin üzerinize doğru ilerleyen ordusu ile karşılaştığınız zaman sakın onlara arkanızı dönmeyiniz."},{"n":16,"t":"Savaş taktiği gereğince yer değiştirme ya da başka bir birliğe katılma amaçları dışında o gün kim kâfirlere arka dönerse, Allah’ın gazabına uğramış olarak döner. Onun varacağı yer cehennemdir. Orası ne fena bir dönüş yeridir."},{"n":17,"t":"Müşrikleri öldüren siz değildiniz, fakat Allah öldürdü onları. Onlara doğru toprak atarken, sen atmadın, fakat Allah attı. Allah kendi keremi ile mü’minleri güzel bir sınavdan geçirmek için bunu böyle yaptı. Hiç kuşkusuz Allah işitendir, bilendir."},{"n":18,"t":"Bunların yanısıra Allah kâfirlerin tuzaklarını boşa çıkarandır."},{"n":19,"t":"Ey müşrikler eğer zafer istiyorsanız, size zafer geldi (fakat aleyhinize çıktı). Eğer Peygamber’e karşı çıkmaktan vazgeçerseniz iyiliğinize olur. Yok eğer bir daha aynı şeyi yaparsanız biz de size yine aynı akibeti tattırırız. Topluluğunuz ne kadar kalabalık olursa olsun size hiçbir yarar sağlamayacaktır. Allah kesinlikle mü’minler ile beraberdir."},{"n":20,"t":"Ey iman edenler! Allah’a ve peygamberine itaat edin ve duyduğunuz halde ondan yüz çevirmeyin. [3]"},{"n":21,"t":"Onun söylediklerini işitmedikleri halde «işittik» diyenler gibi olmayınız."},{"n":22,"t":"Allah katında canlıların en kötüsü, düşünmeyen, gerçeği kavramayan sağır ve dilsizlerdir."},{"n":23,"t":"Eğer Allah onlarda hayır olduğunu bilseydi, kendilerine gerçeği işittirirdi. Oysa eğer gerçeği işittirse bile yine burun kıvırarak yüz çevirirlerdi."},{"n":24,"t":"Ey mü’minler, Allah ve Peygamberi sizi hayat bağışlayacak ilkelere çağırdıkları zaman bu çağrıya olumlu karşılık veriniz. Biliniz ki, Allah kişi ile kalbi arasına girer ve siz O’nun huzurunda biraraya geleceksiniz."},{"n":25,"t":"Sadece aranızdaki zalimlerin başlarına gelmekle yetinmeyecek olan belâdan sakınınız. Biliniz ki, Allah’ın’ azabı ağırdır."},{"n":26,"t":"Hatırlayınız ki, bir zamanlar siz yeryüzünde ezilen, sayıca az bir gruptunuz, insanlar sizi kapıp götürecekler diye korkuyordunuz. Fakat şükredesiniz diye Allah size sığınak sağladı, helâl besinler sundu, sizi yardımı ile destekledi."},{"n":27,"t":"Ey mü’minler Allah’a, Peygamber’e hıyanet etmeyiniz. Yoksa üstlendiğiniz emanetlere bile bile hıyanet etmiş olursunuz."},{"n":28,"t":"Biliniz ki, mallarınız ve evlatlarınız sizin için aslında birer sınav konusudur ve büyük ödül Allah katındadır."},{"n":29,"t":"Ey mü’minler, eğer Allah’dan korkarsanız, O size iyiyi kötüden ayırd edebilecek bir nosyon, bir kriter bağışlar, kötülüklerinizi örter ve sizi affeder. Allah büyük lütuf sahibidir."},{"n":30,"t":"Hani kâfirler seni tutuklamak, öldürmek ya da Mekke’den sürmek amacı ile aleyhinde tuzak kurmuşlardı. Onlar tuzak kurarken Allah da tuzak kuruyordu. Hiç kuşkusuz Allah en etkili tuzak kurucudur."},{"n":31,"t":"Onlara ayetlerimiz okununca «işittik, istesek biz de bunlar gibisini söyleyebiliriz, bunlar eskilerin masallarından başka bir şey değildirler» dediler."},{"n":32,"t":"Hani onlar «Allah’ımız, eğer bu Kur’an senin tarafından gönderilmiş gerçek bir kitap ise, başımıza gökten taş yağdır ya da bizi acıklı bir azaba çarptır» dediler."},{"n":33,"t":"Oysa sen aralarında bulundukça, Allah onları azaba çarptırmaz. Ayrıca bağışlanma dilerlerken de Allah onları azaba çarptırmaz."},{"n":34,"t":"Yoksa onlar insanların Mescid-i Haram’a girmelerine engel oldukları halde, Allah onları niye azaba çarptırmasın ki? Onlar oranın korucuları değildiler. Oranın korucuları ancak Allah’ın yasaklarından sakınanlardır. Fakat çokları bunu bilmezler."},{"n":35,"t":"Onların Kâbe karşısında tapınmaları naradan ve alkıştan ibaretti. Süregelen inkârcılığınızın karşılığı olarak şimdi azabı tadın bakalım."},{"n":36,"t":"Kâfirler insanları Allah yolundan alıkoymak için mallarını harcarlar. Onlar mallarını bu uğurda harcayacaklar, sonra da bu harcama onlar için yürek acısı olacak, arkasından da yenilgiye uğrayacaklardır. Kâfirler cehennemde biraraya getirileceklerdir."},{"n":37,"t":"Ta ki, Allah murdarı temizden ayırdetsin ve murdarları üstüste koyup hep biraraya yığarak cehenneme atsın. İşte bunlar hüsrana uğrayanlardır."},{"n":38,"t":"Kâfirlere dedi ki; «Eğer saldırganlıklarından vazgeçerlerse geçmişteki suçları bağışlanır. Yok eğer eski tutumlarına dönerlerse, daha öncekiler için geçerli olan kurallar onlar için de işler.»"},{"n":39,"t":"Fitnenin kökü kazınıp Allah’ın dini kesinlikle egemen oluncaya kadar onlarla savaşınız. Eğer yaptıklarından vazgeçerlerse, hiç şüphesiz Allah onların ne yaptıklarını görür."},{"n":40,"t":"Eğer yüz çevirirlerse biliniz ki, Allah sizin dostunuz ve dayanağınızdır. O ne güzel bir dost ve dayanak, ne güzel bir yardım edicidir."},{"n":41,"t":"Eğer Allah’a ve doğru ile eğrinin birbirinden ayrıldığı gün, yani iki ordunun Bedir’de karşılaştığı gün kulumuz Muhammed’e indirdiğimiz mesaja inanıyorsanız biliniz ki, ele geçirdiğiniz ganimet mallarının beşte biri Allah’a, Peygamber’e, Peygamber’in yakınlarına, yetimlere, yoksullara ve yarı yolda kalanlara aittir. Allah her şeye kadirdir."},{"n":42,"t":"Hani Bedir savaşında siz vadinin Medine’ye yakın yakasında, onlar Medine’ye uzak yakasında ve ticaret kervanı da vadi tabanına sizden daha yakın idi. Eğer bu şekilde buluşmak üzere sözleşseydiniz bile bu şekilde buluşamazdınız. Fakat Allah ortaya çıkması gereken bir sonucun gerçekleşmesi için bu buluşmayı böyle düzenledi. Böylece can veren bile bile can verecek, hayatta kalan da bile bile hayatta kalacaktı. Hiç kuşkusuz Allah Her şeyi işitir ve her şeyi bilir."},{"n":43,"t":"Hani Allah onları sana rüyanda az gösteriyordu. Eğer onları kalabalık gösterseydi moraliniz bozulur, bu konuda aranızda tartışmaya düşerdiniz. Fakat Allah, sizi bu tehlikeden korudu. Hiç şüphesiz O, kalplerin özünü bilir."},{"n":44,"t":"Allah, ortaya çıkması gereken sonucun gerçekleşmesi için savaş alanında karşılaştığınızda onları sizin gözlerinizde az gösteriyor, sizi de onların gözlerinde azaltıyordu. Her işin sonu Allah’a varır."},{"n":45,"t":"Ey mü’minler, bir savaş birliği ile karşılaştığınızda direniniz, Allah’ı çok anınız ki, başarıya eresiniz."},{"n":46,"t":"Allah’a ve Peygamberi’ne itaat ediniz. Aranızda tartışmaya, çekişmeye düşmeyiniz. Yoksa moraliniz bozulur, hızınız kaybolur. Sabrediniz. Çünkü Allah sabırlılar ile beraberdir."},{"n":47,"t":"Yurtlarından çalım satarak, halka gösteriş yaparak sefere çıkan ve insanları Allah yolundan alıkoyanlar gibi olmayınız. Şüphe yok ki, Allah onların bütün yaptıklarını bilgisi ile kuşatmıştır."},{"n":48,"t":"Hani şeytan onlara yaptıkları işleri güzel göstererek kendilerine «Bugün sizi hiçbir insan grubu yenemez, ben sizin arkanızdayım» dedi. Fakat iki ordu birbirini görünce, birdenbire geri dönerek, «Benim sizinle hiçbir ilgim yok, ben sizin görmediğinizi görüyorum, ben Allah’tan korkarım, çünkü Allah’ın azabı ağırdır» dedi."},{"n":49,"t":"Hani münafıklar ile kalplerinde hastalık bulunanlar «Bu müslümanları dinleri şımartıp yanılgıya düşürdü» dediler. Oysa kim Allah’a dayanırsa bilsin ki Allah, üstün iradeli ve hikmet sahibidir."},{"n":50,"t":"«Yakıcı azabı tadınız bakalım.»"},{"n":51,"t":"İşte bu vaktiyle kendi ellerinizle hazırladığınız bir sonuçtur. Yoksa Allah kesinlikle kullarına haksızlık etmez."},{"n":52,"t":"Bu kâfirlerin durumu tıpkı Firavunoğulları ile daha önceki kâfirlerin durumu gibidir. Onlar Allah’ın ayetlerini inkâr ettiler, Allah da günahları yüzünden yakalarına yapıştı. Hiç şüphesiz Allah güçlüdür ve azabı ağırdır."},{"n":53,"t":"Bu böyledir. Çünkü bir toplum, sahip olduğu iyi bir niteliği değiştirmedikçe, Allah da o topluma vermiş olduğu nimeti değiştirmez. Hiç şüphesiz Allah her şeyi işitir, her şeyi bilir."},{"n":54,"t":"Bu kâfirlerin durumu tıpkı Firavunoğulları ile daha önceki kâfirlerin durumu gibidir. Onlar Rabblerinin ayetlerini yalanladılar, biz de onları günahları yüzünden yokettik, Firavunoğulları’nı denizde boğduk. Bunların hepsi zalimdi."},{"n":55,"t":"Allah katında canlıların en kötüleri kâfirlerdir. Onlar artık inanmazlar."},{"n":56,"t":"Onlar kendileri ile antlaşma yaptığın her defasında hiç çekinmeden antlaşmalarını bozan kimselerdir."},{"n":57,"t":"Eğer savaşta, onları ele geçirirsen, onları geride kalanlara bir ibret olacak biçimde cezalandır."},{"n":58,"t":"Eğer antlaşmalı bir toplumun anlaşmasını bozacağından endişeli isen, aranızdaki antlaşmayı, karşılıklılık ilkesi uyarınca açıkça yüzlerine fırlat. Çünkü, Allah ihanet edenleri sevmez."},{"n":59,"t":"Kâfirler sakın yakayı kurtardıklarını sanmasınlar. Çünkü onlar bizi kesinlikle aciz bırakamazlar."},{"n":60,"t":"Ey iman edenler, onlara karşı gücünüzün yettiği kadar – Allah’ın düşmanı ve sizin düşmanlarınızı ve bunların dışında Allah’ın bilip sizin bilmediklerinizi yıldırmak üzere – kuvvet ve savaş atları hazırlayın. Allah yolunda sarf ettiğiniz her şey, size haksızlık yapılmadan tamamen ödenecektir."},{"n":61,"t":"Eğer onlar barışa yanaşırlarsa sen de ona yanaş ve Allah’a dayan. Çünkü O her şeyi işiten ve bilendir."},{"n":62,"t":"Eğer onlar seni aldatmak isterlerse kuşku yok ki, Allah sana yeter. O seni yardımı ile ve mü’minler aracılığı ile desteklemiştir."},{"n":63,"t":"Allah, mü’minlerin kalplerini uzlaştırdı. Eğer sen dünyadaki her şeyi harcasan yine onların kalplerini uzlaştıramazdın. Fakat Allah onları uzlaştırdı. Hiç kuşkusuz O, üstün iradeli ve hikmet sahibidir."},{"n":64,"t":"Ey peygamber, sana ve sana uyan mü’minlere Allah yeter."},{"n":65,"t":"Ey peygamber, mü’minleri savaşa teşvik et. Eğer sizden yirmi sabırlı kişi olursa bunlar iki yüz kâfiri yenerler. Eğer sizden yüz kişi olsa, bunlar bin kâfiri yenerler. Çünkü onlar anlayışsız, bilinçsiz bir güruhtur."},{"n":66,"t":"Allah, bundan böyle, bu konudaki yükünüzü hafifletti ve bünyenizde bir zaaf belirdiğini bildi. Buna göre eğer sizden yüz sabırlı kişi olursa, bunlar iki yüz kâfiri yenerler. Eğer sizden bin sabırlı kişi olursa, bunlar Allah’ın izni ile iki bin kâfiri yenerler. Allah sabırlılarla beraberdir. ’"},{"n":67,"t":"Yeryüzünde üstünlüğünü perçinlemedikçe hiçbir peygamberin esir alması yerinde değildir. Siz geçici dünya malını istiyorsunuz. Oysa Allah sizin hesabınıza ahireti istiyor. Allah üstün iradeli ve hikmet sahibidir."},{"n":68,"t":"Eğer Allah’ın daha önce kesinleşmiş (ve bu konuda lehinize işleyen) bir hükmü olmasaydı, esirlerin karşılığında aldığınız fidyeler yüzünden başınıza büyük bir azap gelirdi."},{"n":69,"t":"Artık elinize geçen ganimet mallarını helal olarak afiyetle yiyiniz, Allah’dan korkunuz. Hiç kuşkusuz Allah affedicidir ve merhametlidir."},{"n":70,"t":"Ey peygamber elinizdeki esirlere de ki; «Eğer Allah kalplerinizde hayırlı bir yaklaşım olduğunu görürse size elinizden alınandan daha iyisini verir ve sizi affeder. Hiç şüphesiz, Allah affedicidir ve merhametlidir."},{"n":71,"t":"Eğer bu esirler sana ihanet etmeyi düşünüyorlarsa bilsinler ki, daha önce Allah’a ihanet ettiler de bu yüzden O, seni onlara karşı üstün getirdi. Hiç kuşkusuz Allah her şeyi bilir ve her yaptığı yerindedir."},{"n":72,"t":"İman edip Medine’ye göçenler ve Allah yolunda canları ile malları ile cihad edenler ile bu göçmenlere barınak sağlayanlar ve yardım edenler birbirlerinin yandaşları, koruyucularıdırlar. İman edip Medine’ye göçetmeyenlere gelince, bunlar göçetmedikçe kendilerine karşı hiçbir yandaşlık, koruyuculuk yükümlülüğünüz yoktur. Eğer böyleleri sizden, aranızda saldırmazlık antlaşması bulunmayan bir topluma karşı din konusunda yardım isterlerse kendilerine yardım etmekte yükümlüsünüz. Allah yaptığınız her şeyi görür.»"},{"n":73,"t":"Kâfirler birbirlerinin yandaşları, koruyucularıdırlar. Eğer aranızda bu sıkı dayanışmayı gerçekleştirmezseniz, yeryüzünde fitne ve büyük bir kargaşa çıkar."},{"n":74,"t":"İman edip Medine’ye göçenler ve Allah yolunda malları ile, canları ile cihad edenler ile bu göçmenlere barınak sağlayanlar ve yardım edenler var ya, işte bunlar gerçek mü’minlerdir, onları bağışlanma ve bol rızık beklemektedir."},{"n":75,"t":"Sonradan iman edip Medine’ye göçenlere ve sizinle birlikte cihad edenlere gelince onlar sizdendirler. Allah’ın Kitabı’na göre yakın akrabaların birbirlerine mirasçı olma konusunda öncelik hakları vardır. Hiç kuşkusuz Allah her şeyi bilir."}],[{"n":1,"t":"Kendileri ile aranızda antlaşma bulunan müşriklere Allah ve Peygamber’i tarafından yöneltilen bir ilişki kesme ihtarıdır bu."},{"n":2,"t":"Dört ay daha yeryüzünde serbestçe dolaşınız. Allah’ın yapacaklarına engel olamayacağınızı ve Allah’ın kâfirleri perişan edeceğini biliniz."},{"n":3,"t":"Büyük hacc günü Allah ve Peygamber tarafından tüm insanlara duyurulur ki; «Allah ve Peygamber’i ile müşrikler arasında her türlü ilişki kesilmiştir. Eğer tevbe ederseniz bu sizin için daha yararlıdır. Eğer sırt çevirirseniz Allah’ın yapacaklarına engel olamayacağınızı biliniz. Ey Peygamber, kâfirleri acıklı bir azapla müjdele!»"},{"n":4,"t":"Yalnız antlaşma şartlarını eksiksiz biçimde yerine getiren ve size karşı hiç kimseyi desteklemeyen müşriklere gelince onlar ile aranızdaki anlaşmalara sürelerinin sonuna kadar uyunuz. Hiç şüphesiz Allah kötülükten sakınanları sever."},{"n":5,"t":"Haram aylar geçince müşrikleri bulduğunuz yerde öldürünüz, yakalayıp hapsediniz, bütün muhtemel geçitleri tutup onları gözetleyiniz. Eğer tevbe eder de namaz kılar ve zekât verirlerse onları salıveriniz. Hiç şüphesiz Allah affedici ve merhametlidir."},{"n":6,"t":"Eğer puta tapanlardan biri senden can güvenliği isterse kendisine can güvenliği sağla ki, Allah’ın sözünü, Kur’ân’ı işitebilsin, sonra da onu güven içinde olacağı bir yere ulaştır. Çünkü onlar gerçekleri bilmeyen bir güruhtur."},{"n":7,"t":"Mescid i Haram’ın, Kabe’nin yanında antlaşma yaptıklarınız dışındaki müşriklere karşı Allah’ın ve Peygamber’in nasıl taahhüdü olabilir? Onlar size karşı dürüst davrandıkça siz de onlara karşı dürüst davranınız. Hiç şüphesiz Allah kötülükten sakınanları sever."},{"n":8,"t":"Allah’ın ve Peygamber’in onlara karşı nasıl taahhüdü olabilir ki, eğer size karşı üstün gelseler ne and ve ne de yükümlülük gözetirler. Dilleri ile sizi hoşnut etmeye çalışırlar, ama kalbleri sözleri ile çelişiktir. Onların çoğunun karakteri bozuktur."},{"n":9,"t":"Allah’ın ayetlerini birkaç paraya sattılar ve insanları O’nun yolundan alıkoydular. Onların yaptıkları ne kadar kötüdür!"},{"n":10,"t":"Onlar bir mümine karşı ne and ve ne de yükümlülük gözetirler. Onlar saldırganların ta kendileridirler."},{"n":11,"t":"Eğer tevbe edip namazı kılar ve zekatı verirlerse sizin din kardeşleriniz olurlar. Biz bilgili kimselere ayetlerimizi ayrıntılı biçimde açıklarız."},{"n":12,"t":"Eğer onlarla antlaşma yaptıktan sonra antlarını bozarlar da dininize dil uzatırlarsa kafirlerin elebaşları ile savaşınız. Çünkü onlar için yeminin bir anlamı yoktur. Belki can korkusu ile saldırılarına son verirler."},{"n":13,"t":"Yeminlerini bozan ve Peygamber’i Mekke’den çıkarmaya yeltenen kimseler ile, üstelik size karşı savaşı başlatan taraf oldukları halde, savaşmayacak mısınız? Yoksa onlardan korkuyor musunuz? Oysa eğer mümin iseniz asıl Allah’dan korkmalısınız."},{"n":14,"t":"Onlarla savaşınız ki, Allah sizin elinizle onları azaba çarptırsın, kendilerini perişan etsin, sizi onlara karşı üstün getirsin de müminlerin kalb yaralarını iyileştirsin, su serpsin."},{"n":15,"t":"Kalblerindeki kini gidersin. Allah dilediği kimselerin tevbesini kabul eder. Allah üstün iradelidir ve ne yaparsa yerindedir."},{"n":16,"t":"Yoksa Allah içinizdeki cihad edenleri ve Allah’dan, Peygamber’den, müminlerden başka hiç kimseyi sırdaş edinmeyenleri belirlemeden sizi kendi halinize bırakacak mı sandınız? Allah yaptığınız her işten haberdardır."},{"n":17,"t":"Müşriklere, kâfir olduklarına bizzat kendileri tanıklık ettikleri halde Allah’ın mescidlerini onarıp şenlendirmek düşmez. Onların bütün yaptıkları boşunadır. Onlar ebedi olarak cehennemde kalacaklardır."},{"n":18,"t":"Allah’ın mescidlerini ancak Allah’a ve ahiret gününe iman eden, namazı kılan, zekatı veren ve Allah’tan başkasından korkmayan kimseler onarabilir. İşte bunlar doğru yola erenlerden olabilirler."},{"n":19,"t":"Hacılara su sağlamayı ve Kâbe’yi onarıp şenlendirmeyi, ahiret gününe inanmakla ve Allah yolunda cihad etmekle bir mi tutuyorsunuz? Bunlar Allah katında bir değildirler. Allah zalimler güruhunu doğru yola iletmez."},{"n":20,"t":"İman edip Medine’ye hicret edenlerin ve malları, canları ile Allah yolunda cihad edenlerin Allah katındaki dereceleri en üstündür. İşte kurtuluşa erenler onlardır."},{"n":21,"t":"Rabb’leri onları kendi öz bağışı olan bir rahmetle, hoşnutluk ve bitmez tükenmez nimetlerle dolu cennetler ile müjdeler."},{"n":22,"t":"Onlar orada ebedi olarak kalacaklardır. Hiç şüphesiz büyük ödül Allah katındadır."},{"n":23,"t":"Ey müminler, eğer babalarınız ve kardeşleriniz kâfirliği, müminliğe tercih ediyorlarsa sakın onları dost, yandaş edinmeyiniz. Kimler böylelerini dost edinirlerse onlar zalimlerin ta kendileridirler."},{"n":24,"t":"De ki; «Eğer babalarınızı, evlâtlarınızı, kardeşlerinizi, eşlerinizi, hısım akrabanızı, kazandığınız malları, bozulmasından korktuğunuz ticareti ve hoşunuza giden evleri, konakları Allah’dan, Peygamber’den ve Allah yolunda cihad etmekten daha çok seviyorsanız Allah emrini gerçekleştirinceye, yapacağını yapıncaya kadar bekleyiniz. Allah yoldan çıkmışlar güruhunu doğru yola iletmez.»"},{"n":25,"t":"Gerçekten Allah size birçok yerde, birçok olayda olduğu gibi Huneyn savaşı günü de yardım etti. Hani o gün sayıca çok oluşunuz hoşunuza gitmiş, böbürlenmenize yolaçmıştı da bu kalabalıklık size hiçbir yarar sağlamamıştı; yeryüzü, onca genişliğine rağmen size dar gelmişti de sonra arkanızı dönüp kaçmıştınız."},{"n":26,"t":"Bu bozgunun arkasından Allah, Peygamberinin ve müminlerin kalblerine güven duygusu indirdi ve görmediğiniz ordular göndererek kâfirleri azaba çarptırdı. Kâfirlerin görecekleri karşılık budur."},{"n":27,"t":"Ama bütün bunlara rağmen, Allah tevbe isteyen kimsenin tevbesini dilediği şekilde kabul eder. Allah çok bağışlayan ve çok acıyandır."},{"n":28,"t":"Ey müminler! Allah’a ortak koşanlar birer somut pisliktirler. Bundan dolayı bu yıldan sonra bir daha Mescid- i Haram’a yaklaşmasınlar. Eğer (ziyaretçi sayısının azalması yüzünden) yoksul düşeceğinizden korkuyorsanız, biliniz ki, Allah eğer dilerse yakında kendi lûtfu ile sizi zengin edecektir. Hiç şüphesiz Allah her şeyi bilir ve her yaptığı yerindedir."},{"n":29,"t":"Allah’a ve Ahiret gününe inanmayan, Allah’ın ve Peygamber’in haram kıldığı şeyleri haram saymayan ve gerçek dinî benimsemeyen yahudi ve hıristiyanlar ile, bunlar size boyun eğip kendi elleri ile cizye verene dek savaşınız."},{"n":30,"t":"Yahudiler «Uzeyr, Allah’ın oğludur» dediler. Hıristiyanlar da «Mesih (İsa) Allah’ın oğludur» dediler. Bunlar, onların ağızları ile geveledikleri dayanaksız sözlerdir. Böyle demekle daha önceki kâfirlerin sözlerine özeniyorlar. Allah kahretsin onları. Nasıl gerçeklerden sapıyorlar?"},{"n":31,"t":"Onlar Allah dışında hahamlarını, rahiplerini ve Meryemoğlu İsa’yı ilah edindiler. Oysa onlara sadece tek ilaha, kendisinden başka ilah olmayan ve onların yakıştırma ortaklarından uzak olan Allah’a kulluk etmeleri emredilmişti."},{"n":32,"t":"Onlar Allah’ın nurunu ağızları ile söndürmek istiyorlar. Oysa Allah, kâfirlerin hoşuna gitmese de, nurunu kesinlikle tamama erdirmekte kararlıdır."},{"n":33,"t":"Müşriklerin hoşuna gitmese de kendi dinini diğer bütün dinlere karşı üstün getirmek üzere peygamberini doğru yol ve gerçek din ile gönderen O’dur."},{"n":34,"t":"Ey müminler, birçok hahamlar ve rahipler insanların mallarını eğri yöntemlerle yerler ve halkı Allah’ın yolundan alıkoyarlar. Altın ve gümüşü biriktirip de bunları Allah yolunda harcamayanları acıklı bir azapla müjdele!"},{"n":35,"t":"Bu toplanıp saklanan altının, gümüşün cehennem ateşinde kızdırılıp, onların alınlarının, böğürlerinin ve sırtlarının damgalanacağı gün, bu günahkarlara \"İşte kendiniz için topladığınız hazineler\" denecek. \"Şimdi tadın bakalım, sarılıp sakladığınız hazinelerin başınıza açtığı belanın tadını!\""},{"n":36,"t":"Allah’ın gökleri ve yeri yarattığı günden beri geçerli olan evrensel yasasına göre O’nun katında ayların sayısı onikidir. Bunlardan dördü haram aylardır. Bu dosdoğru dindir. Sakın bu aylarda konmuş yasakları çiğneyerek kendinize zulmetmeyiniz. Allah’a ortak koşanlar nasıl size karşı topyekün savaşıyorlarsa, siz de onlarla topyekün savaşınız ve biliniz ki, Allah kötülüklerden sakınanlarla beraberdir."},{"n":37,"t":"Haram aylardaki savaş yasağını başka aylara aktarmak, ertelemek kâfirlikte daha ileri gitmektir. Kâfirler bu yolla sapıklığa sürüklenirler. Onlar Allah’ın haram kıldığı ayları sayıca denk getirmek için bu ertelemeyi bir yıl helâl sayarlarken, bir sonraki yıl haram kabul ederler. Böylece Allah’ın haram kıldığını helâl saymış olurlar. Yaptıkları çirkin işler kendilerine güzel gösterildi. Allah kâfirler güruhunu kesinlikle doğru yola iletmez."},{"n":38,"t":"Ey mü’minler, size ne oldu da «Allah yolunda savaşa çıkınız» dendiğinde yere çakıldınız. Yoksa dünya hayatını ahirete tercih mi ettiniz? Oysa dünya hayatının hazzı, ahiretin hazzı yanında pek azdır."},{"n":39,"t":"Eğer savaşa çıkmazsanız Allah sizi acıklı bir azaba uğratarak yerinize başka bir toplum getirir. Siz Allah’a hiç bir zarar dokunduramazsınız. Çünkü Allah’ın gücü her şeyi yapmaya yeter."},{"n":40,"t":"Peygamber’e yardım etmezseniz, biliniz ki, kâfirler O’nu Mekke’den çıkardıklarında iki kişiden biri olarak mağaradayken Allah O’na yardım etmişti. Hani O arkadaşına «Üzülme, Allah bizimle beraberdir» diyordu. Allah O’nun kalbine güven duygusu indirmiş, kendisini göremediğiniz askerler ile desteklemiş, böylece kâfirlerin sözünü alçaltmıştı. Yüce olan Allah’ın sözüdür. Allah üstün iradelidir ve her yaptığı yerindedir."},{"n":41,"t":"Kolayınıza da gelse zorunuza da gitse mutlaka sefere çıkınız, Allah yolunda mallarınızla ve canlarınızla cihad ediniz. Eğer bilirseniz bu sizin için daha hayırlıdır."},{"n":42,"t":"Eğer yakın vadeli bir kazanç ve kısa bir yolculuk sözkonusu olsaydı, mutlaka peşinden gelirlerdi. Fakat bu sıkıntılı yolculuk onlara uzun geldi. Allah adına yemin ederek, «Eğer gücümüz yetseydi, kesinlikle sizinle birlikte sefere çıkardık» diyerek kendilerini mahvedecekler. Oysa Allah biliyor ki, onlar yalan söylüyorlar."},{"n":43,"t":"Allah affetsin seni. Kimlerin doğru söylediği belli oluncaya ve kimlerin yalancı olduğunu belirleyinceye kadar onlara niçin izin verdin?"},{"n":44,"t":"Allah’a ve ahiret gününe inananlar, malları ile ve canları ile cihad etmekten geri kalmak için senden izin istemezler. Allah kötülükten sakınanları bilir."},{"n":45,"t":"Senden savaştan muaf tutulmaları yolunda izin isteyenler, Allah’a ve ahiret gününe inanmayanlar, kalpleri kuşkuya kapılıp bu kuşkuları içinde bocalayanlardır."},{"n":46,"t":"Eğer onlar sefere çıkmak isteselerdi, bunun için hazırlık yaparlardı. Fakat Allah, sefere çıkmaya kalkışmalarını istemediği için onları böyle bir girişimden alıkoydu. Kendilerine «(Kadın, çocuk, yaşlı, hasta gibi) savaşma gücünden yoksun kimselerle birlikte siz de evlerinizde oturunuz» dendi."},{"n":47,"t":"Eğer sizinle birlikte sefere çıksalardı, size bozgunculuktan başka bir katkıları olmazdı, sizi birbirinize düşürmek için aranıza atılacaklar, balıklama dalacaklardı. Aranızda onların sözlerine kulak verecekler de vardı. Allah zalimlerin kimler olduğunu bilir."},{"n":48,"t":"Onlar daha önce de fitne çıkarmak istemişler, sana karşı çeşitli entrikalar çevirmişlerdi. Sonunda gerçek geldi ve onların istememesine rağmen, Allah’ın emri üstün çıktı."},{"n":49,"t":"Onlardan bazıları, «Bana savaşa katılmama izni ver de beni fitneye düşürme» derler. Haberiniz olsun ki, onlar fitnenin içine düşmüşlerdir ve cehennem kâfirleri kuşatacaktır."},{"n":50,"t":"Eğer karşına bir iyilik çıkarsa fenalarına gider. Eğer başına bir musibet gelirse, «Biz savaşa katılmayarak önceden tedbirimizi aldık» diyerek sevinç içinde dönüp giderler."},{"n":51,"t":"Onlara de ki; «Başımıza gelenler, sadece Allah’ın alnımıza yazdıklarıdır. Bizim mevlamız, sahibimiz O’dur. Mü’minler sadece Allah’a dayansınlar.»"},{"n":52,"t":"De ki; «Bizim için beklediğiniz sonuç iki iyiden, yani zaferden veya şehit düşmekten biri değil mi? Biz ise Allah’ın sizi ya doğrudan doğruya kendi tarafından ya da bizim elimizle azaba uğratmasını bekliyoruz. Bekleyiniz bakalım, biz de sizinle birlikte bekliyoruz.»"},{"n":53,"t":"Onlara de ki, «İster gönüllü, ister gönülsüz olarak sadaka veriniz, verdiğiniz sadakalar kabul edilmeyecektir, sizler yoldan çıkmışlar güruhusunuz.»"},{"n":54,"t":"Verdikleri sadakaların kabul edilmesini engelleyen tek sebep şudur; Onlar Allah’a ve Peygamber’e inanmadılar, namaza ancak uyuşuk uyuşuk dururlar ve verdikleri sadakaları istemeyerek verirler."},{"n":55,"t":"Artık onların malları ve çocukları seni imrendirmesin. Allah bunlarla onlara dünya hayatında azâp etmek ve canlarının kâfir olarak çıkmasını ister."},{"n":56,"t":"Onlar sizden olduklarına dair Allah adına yemin ederler, oysa sizden değildirler, fakat ödlek bir güruhturlar."},{"n":57,"t":"Eğer bir sığınak, bir mağara ya da geçilecek bir yeraltı deliği bulsalar, dolu dizgin buralara koşarlardı."},{"n":58,"t":"Onların bazıları sadakaların (zekât gelirlerinin) bölüştürülmesi konusunda sana dil uzatırlar. Eğer zekât gelirlerinden kendilerine bir pay verilirse memnun olurlar, eğer bu gelirlerden kendilerine bir pay verilmez ise hemen öfkeleniverirler."},{"n":59,"t":"Oysa eğer onlar Allah’ın ve Peygamber’in kendilerine ayırdığı payı sevinçle karşılayarak, «Allah bize yeter, yakında Allah da bize lütfundan verecek, Peygamber de. Biz umudumuzu yalnız Allah’a bağlamışız» deselerdi, kendileri hakkında daha iyi olurdu."},{"n":60,"t":"Sadakalar (zekât gelirleri) sadece yoksullara, düşkünlere, zekât toplamakla görevli memurlara, kalpleri islâma ısındırılmak istenenlere, sözleşmeli kölelere, borçlulara, Allah yolunda çalışanlara ve yarı yolda kalanlara verilir. Bu paylaştırma sırası Allah tarafından belirlenmiştir. Allah her şeyi bilir ve her yaptığı yerindedir."},{"n":61,"t":"Onlardan bazıları da, «Peygamber herkesi dinleyen bir kulaktan ibarettir» diyerek, onu üzerler. Onlara de ki; «O sizin için yararlı bir kulaktır; Allah’a inanır, mü’minlere güvenir, içinizdeki mü’minler için rahmettir. Allah’ın elçisini üzenleri acıklı bir azap beklemektedir."},{"n":62,"t":"Sizin hoşnutluğunuzu kazanmak için Allah’a yemin ederler. Oysa eğer mü’min olsalardı, Allah’ın ve peygamberin hoşnutluğunu kazanmayı daha gerekli görürlerdi."},{"n":63,"t":"Onlar halâ öğrenemediler mi ki, Allah’a ve Peygamber’e zıt düşeni, düşman olanı cehennem ateşi bekliyor; o, orada ebedi olarak kalacaktır. Bu büyük perişanlıktır."},{"n":64,"t":"Münafıklar kalplerinde sakladıkları kâfirliği açığa vuracak bir surenin inmesinden korkuyorlar. Onlara de ki; «Siz alay edin bakalım, Allah kesinlikle korktuğunuzu meydana çıkaracaktır.»"},{"n":65,"t":"Eğer onlara soracak olursan, ’Biz lafa daldık aramızda eğleniyorduk derler.’ De ki; «Allah ile, Allah’ın ayetleri ile ve Peygamber ile mi alay ediyordunuz?»"},{"n":66,"t":"Uydurma bahaneler ileri sürmeyiniz. İman ettikten sonra tekrar kâfir oldunuz. Bir kısmınızı affetsek bile, ağır suçlu olduklarından dolayı diğer kısmınızı azaba çarptıracağız."},{"n":67,"t":"Erkek kadın bütün münafıklar hep birdirler. Kötülüğü emrederler, iyiliği yasaklarlar, elleri sıkıdır, onlar Allah’ı unuttukları için Allah da onları unuttu. Münafıklar yoldan çıkmışların ta kendileridirler."},{"n":68,"t":"Allah erkek kadın münafıklar ile kâfirleri cehennem ateşi ile cezalandıracağına söz vermiştir. Onlar orada ebedi olarak kalacaklardır. Orası onlara yeter. Allah onları lanetlemiştir. Onları sürekli bir azap beklemektedir."},{"n":69,"t":"Ey münafıklar, siz de sizden önce yaşamış ve sizden daha güçlü, daha zengin ve daha çok sayıda çocuklu olup paylarına düşen dünya nimetlerinin cazibesine kapılan kimseler gibi davrandınız, bu kimseler nasıl paylarına düşen dünya nimetlerinin cazibesine kapıldılar ise, siz de öylece payınıza düşen dünya nimetlerinin cazibesine kapıldınız, vaktiyle eğriliğe dalanlar gibi siz de eğriliğe daldınız. Onlar, yaptıkları dünyada ve ahirette boşa gitmiş kimselerdir. Onlar hüsrana uğramışların ta kendileridir."},{"n":70,"t":"Onlara kendilerinden önceki toplumlara, yani Nuh, Ad, Semud kavmine, İbrahim kavmine, Medyen halkına ve yurtları altüst edilenlere ilişkin bilgiler gelmedi mi? Bu toplumlara, peygamberleri açık anlamlı mesajlar getirmişlerdi. Allah’ın onlara zulmetmesi sözkonusu değildi; fakat onlar kendi kendilerine zulmettiler."},{"n":71,"t":"Erkek kadın bütün mü’minler birbirlerinin dostu, dayanağıdırlar. Bunlar iyiliği emrederek kötülükten sakındırırlar, namazı kılarlar, zekâtı verirler, Allah’a ve peygamberine itaat ederler. Allah işte onlara rahmet edecektir. Hiç şüphesiz Allah, güçlü iradelidir ve her yaptığı yerindedir."},{"n":72,"t":"Allah, erkek kadın bütün müminleri altlarından nehirler akan ve içlerinde sürekli kalacakları cennetlere, Adn cennetlerinde konforlu konutlara yerleştireceğine söz vermiştir. Allah’ın hoşnutluğu ise, bunlardan daha büyük bir ödüldür. İşte büyük kurtuluş, büyük başarı budur."},{"n":73,"t":"Ey peygamber, kâfirlerle ve münafıklarla savaş, onlara karşı sert ol, onların varacakları yer cehennemdir, orası ne kötü bir varılacak yerdir."},{"n":74,"t":"Onlar söylemediler diye Allah adına yemin ederler, ama o küfür sözünü söylediler. Müslüman olduktan sonra kâfir oldular. Yapamadıkları bir işe yeltendiler. Bu yolla öç almaya kalkışmalarının tek sebebi Allah’ın lütfu ile Allah’ın ve Peygamber’in kendilerini zengin etmiş olmalarıdır. Eğer tevbe ederlerse kendileri için iyi olur, Eğer sırt çevirirlerse, Allah onları hem dünyada, hem de ahirette acıklı bir azaba uğratır. Dünyada onlara ne bir dost ve ne de bir yardım edici bulunur."},{"n":75,"t":"Onlardan bazıları «eğer Allah bize lütfundan bol mal verirse, sadaka verenlerden ve iyi amel işleyenlerden olacağımıza yemin ederiz» diye Allah’a kesin söz verirler."},{"n":76,"t":"Fakat Allah onlara lütfundan bol mal verince, cimrice davranarak sırt çevirdiler, sözlerinden döndüler."},{"n":77,"t":"Allah’a verdikleri sözden caydıkları ve yalan söyledikler gerekçesiyle Allah, karşısına çıkacakları güne kadar kalplerine münafıklığı yerleştirdi."},{"n":78,"t":"Allah’ın onların sırlarını ve fısıltılarını bildiği, O’nun «gayb «leri çok iyi bildiğini halâ öğrenemediler mi?"},{"n":79,"t":"Sadaka vermekte gönülden davranan müminlere dil uzatan ve ancak ellerinden geldiği kadar verebilenlerle alay eden kimselere davranışlarının cezasını Allah verir. Onlara can yakıcı azab vardır."},{"n":80,"t":"Onlar için ister af dile, ister dileme, onlar adına yetmiş kere (istediğin kadar çok) af dilesen de Allah onları kesinlikle affetmez. Sebebine gelince, onlar Allah’ı ve peygamberini tanımadılar, Allah yoldan çıkmışlar güruhunu doğru yola iletmez."},{"n":81,"t":"Sefere katılmayanlar Allah’ın Rasulüne ters düşerek geride kaldıklarına sevindiler. Allah yolunda malları ve canları ile cihad etmeyi istemediler, «Sıcakta sefere çıkmayın» dediler. Onlara «Cehennem ateşi bundan daha sıcaktır» deyiniz. Keşke bunu kavrayabilselerdi."},{"n":82,"t":"Yaptıklarının karşılığı olarak bundan böyle az gülüp çok ağlasınlar."},{"n":83,"t":"Eğer Allah sana onlardan bir grubun yanına dönmeyi nasip eder de onlar senden sefere çıkmak üzere izin isterlerse de ki; hiçbir zaman benimle beraber düşmanla savaşmayacaksınız. Çünkü siz ilk keresinde geride kalmaktan hoşlandınız. O halde şimdi de (kadın çocuk, yaşlı ve hasta gibi) savaşma gücünden yoksun kimseler ile birlikte evlerinizde oturunuz."},{"n":84,"t":"Onlardan biri ölünce asla namazı kılma ve sakın mezarı başında dikilme. Çünkü onlar Allah’ı ve Peygamber’i tanımadılar ve yoldân çıkmış olarak öldüler."},{"n":85,"t":"Onların malları ve evlatları sakın seni imrendirmesin. Allah bunlar aracılığı ile onların dünya hayatında azaba uğramasını ve canlarını kâfir olarak vermelerini ister."},{"n":86,"t":"Allah’a inanınız ve peygamberi ile birlikte cihad ediniz direktifini içeren bir sure indiğinde onların içindeki zenginler senden izin isteyerek «Bizi bırak evlerinde oturanlarla birlikte olalım» derler."},{"n":87,"t":"Onlar evlerinde oturan güçsüzlerle birlikte kalmaya razı oldular, kalplerine mühür vuruldu; artık onlar anlayamazlar."},{"n":88,"t":"Fakat Peygamber’e ve onunla birlikte canları malları ile savaşanlara gelince, işte bütün hayırlar onları bekliyor ve onlar başarıya erenlerin, kurtuluşa kavuşanların ta kendileridirler."},{"n":89,"t":"Allah onlara altlarından nehirler akan ve içlerinde sürekli kalacakları cennetler hazırlamıştır. İşte büyük kurtuluş budur."},{"n":90,"t":"Bedevilerin mazeret uyduranları sefere çıkmamak için izin almaya geldiler. Allah’a ve peygamberine yalan söyleyenler ise, mazeret bile ileri sürmeden geri kaldılar. Onların içindeki kâfirler acıklı bir azaba çarpılacaklardır."},{"n":91,"t":"Savaşma gücünden yoksun olanlar, hastalık ve savaş masraflarını karşılayacak imkânı olmayanlar için Allah’ın ve peygamberinin tarafını tuttukları takdirde savaştan geri kalmanın sakıncası yoktur. İyi niyetlilere karşı kınama ve suçlama yolu kapalıdır. Allah bağışlayıcı ve merhametlidir."},{"n":92,"t":"Bir de kendilerine binek hayvanı sağlayasın diye sana başvurduklarında «Size binek hayvanı bulamıyorum» deyince, bu yolda harcama yapacak imkânları olmadığı için üzüntüden gözlerinde yaş olarak dönenlere karşı da bir kınama ve suçlama yolu kapalıdır."},{"n":93,"t":"Ancak zengin oldukları halde savaşa katılmamak üzere senden izin isteyenler, böylece savaşma gücünden yoksun olanlarla birlikte evlerinde oturmayı içlerine sindirenler kınanabilir suçlanabilirler. Allah onların kalplerini mühürlediği için neyin yararlı olduğunu bilmezler."},{"n":94,"t":"\"Özür beyan etmeyin. Size asla inanmayacağız. Allah haberlerinizi bize bildirmiştir. Allah da, Peygamberi de işleyeceklerinizi görecektir. Sonunda, görülmeyeni ve görüneni bilen Allah’a geri çevrileceksiniz. O, işlediklerinizi size haber verecektir.\""},{"n":95,"t":"Savaştan döndüğünüzde kendilerini azarlamayasınız diye size Allah adına yemin edeceklerdir. Onları azarlamayınız, bir şey olmamış gibi davranınız. Çünkü onlar soyut pisliktirler. İşledikleri kötülüklerin karşılığı olarak varacakları yer, cehennemdir."},{"n":96,"t":"Kendilerinden hoşnut olasınız diye size yemin ederler. Oysa siz onlardan hoşnut olsanız bile Allah yoldan çıkmışlar güruhundan kesinlikle hoşnut olmaz."},{"n":97,"t":"Bedevi Araplar kâfirlikte ve münafıklıkta daha aşırı; Allah’ın peygamberine indirdiği hükümlerin sınırlarını bilmemeye daha yatkın kimselerdir. Allah her şeyi bilir ve her yaptığı yerindedir."},{"n":98,"t":"Kimi Bedeviler Allah’ın emri uyarınca yaptıkları harcamaları cerime, angarya sayarlar. Ve başınıza belaların geleceği günü gözlerler. Gözledikleri o bela kendi başlarına gelesiceler! Allah herşeyi işitir, herşeyi bilir."},{"n":99,"t":"Kimi Bedeviler de Allah’a ve ahiret gününe inanırlar; yaptıkları maddi bağışları Allah’ın yakınlığını ve peygamberin dualarını kazanma aracı, sebebi sayarlar. Haberiniz olsun ki, yaptıkları bu bağışlar, gerçekten onları Allah’a yaklaştıran bir sebeptir. İlerde Allah onları rahmetinin kapsamı içerisine alacaktır. Hiç şüphesiz Allah affedici ve merhametlidir."},{"n":100,"t":"Muhacirlerin ve Ensar’ın ilk öncüleri ile iyilikte onlara tam uyanlardan Allah hoşnut olduğu gibi onlar da Allah’dan hoşnut olmuşlardır. Allah onlara altlarından nehirler akan ve içlerinde ebedi olarak kalacakları cennetler hazırlamıştır. İşte büyük kurtuluş, büyük başarı budur."},{"n":101,"t":"Gerek çevrenizdeki bedeviler içinde ve gerekse Medine halkı arasında ikiyüzlülükte uzmanlaşmış, kaşarlanmış münafıklar vardır. Sen onları bilmezsin, ancak biz biliriz. Onları iki kez azaba çarptıracağız, sonra da büyük azaba uğratılacaklardır."},{"n":102,"t":"Savaşa katılmayanların bir bölümü de suçlarını itiraf ettiler ve iyiliği kötülüğe eklediler. Belki Allah onların tevbesini kabul eder. Hiç kuşkusuz Allah affedicidir, merhametlidir."},{"n":103,"t":"Mallarının bir bölümünü sadaka olarak al ve bu yolla onları temizle, günahlardan arındır. Onlara dua et, çünkü senin duan onlara gönül huzuru sağlar. Allah her şeyi işitir ve bilir."},{"n":104,"t":"Onlar Allah’ın kullarının tevbelerini kabul ettiğini ve sadakaları aldığını, zaten tevbelerin kabul edicisi ve merhamet edici olduğunu bilmiyorlar mı?"},{"n":105,"t":"«İstediğiniz gibi davranınız, yaptığınız işleri hem Allah, hem Peygamber, hem de mü’minler göreceklerdir. Sonra görünür, görünmez her şeyi bilen Allah’ın huzuruna çıkarılacaksınız da, O size neler yaptığınızı haber verecektir."},{"n":106,"t":"Savaşa katılmayanların bir başka bölümü daha var ki, onların işleri doğrudan doğruya Allah’ın iradesine kalmıştır. O, onları ya azaba çarptırır ya da tevbelerini kabul eder. Allah her şeyi bilir ve her yaptığı yerindedir."},{"n":107,"t":"Savaşa katılmayanların bir başka grubu da islâma zarar vermek, kâfirliği pekiştirmek, mü’minler arasında ayrılık tohumu ekmek, daha önce Allah’a ve Peygamber’e karşı savaşmış birine gözetleme yeri hazırlamak amacı ile bir mescid yaptılar. Onlar, «iyilikten başka bir amacımız yoktu» diye yemin edeceklerdir. Oysa Allah şahittir ki, onlar yalan söylüyorlar."},{"n":108,"t":"Orada asla namaza durma. İlk gününden itibaren Allah korkusu temeli üzerine kurulan mescid, içinde namaz kılmana daha lâyık bir yerdir. Orada günahlardan arınmayı özleyen kimseler vardır. Allah günahlardan arınanları sever."},{"n":109,"t":"Yapısını Allah korkusu ve hoşnutluğu temeli üzerine kuran mı hayırlıdır, yoksa yapısını kaymak üzere olan bir yarın üzerine kurup da o yarla birlikte cehenneme kayan kimse mi hayırlıdır? Allah zalimler güruhunu doğru yola iletmez."},{"n":110,"t":"Yaptıkları o yapı kalpleri paralanana kadar, yüreklerinde bir kuşku kaynağı olmaya devam edecektir. Allah her şeyi bilir ve her yaptığı yerindedir."},{"n":111,"t":"Allah mü’minlerin mallarını ve canlarını karşılığında kendilerine cenneti vermek üzere satın aldı. Onlar Allah yolunda savaşırlar, bu yolda kimi zaman öldürürler ve kimi zaman da öldürülürler. Bu Allah’ın üzerine borç aldığı ve hem Tevrat’ta, hem İncil’de, hem de Kur’an’da yer verdiği bir sözdür. Allah’dan daha çok sözünde duran kim olabilir ki? O halde yaptığınız bu alışverişe sevininiz. İşte büyük kurtuluş, büyük başarı budur."},{"n":112,"t":"Allah ile bu alışverişi yapanlar, tevbe edenler, sırf Allah’a kulluk edenler, hamd edenler, Allah yolunda geziye çıkanlar, rükua varanlar, secde edenler, iyiyi emrederek kötülükten sakındıranlar, Allah’ın koyduğu sınırları gözetenlerdir. Mü’minleri müjdele!"},{"n":113,"t":"Akraba bile olsalar, cehennemlik oldukları belli olduktan sonra puta tapanlar için Allah’dan af dilemek, ne peygambere ve ne de mü’minlere yakışmaz."},{"n":114,"t":"İbrahim’in babası için af dilemesi, ona bu yolda söz verdiği içindi. Fakat babasının bir Allah düşmanı olduğunu kesinlikle anlayınca, onunla ilişkisini kesti. İbrahim gerçekten çok duygulu ve yumuşak kalpli idi."},{"n":115,"t":"Allah bir toplumu doğru yola ilettikten sonra, nelerden sakınacaklarını açıkça belirtmedikçe kendilerini sapıklığa düşürmez. Hiç kuşkusuz Allah her şeyi bilir."},{"n":116,"t":"Göklerin ve yerin egemenliği Allah’ın tekelindedir. Can veren de öldüren de O’dur. Sizin Allah’dan başka bir dostunuz, dayanağınız ve yardım edeniniz yoktur."},{"n":117,"t":"Allah, Peygamber’in ve o zor anda onun peşinden giden muhacirler ile Ensar’ın tevbelerini kabul etti. O sırada onlardan bir grubun kalpleri kaymanın eşiğine gelmişti. Arkasından O, onların tevbelerini kabul etti. Çünkü O, onlara karşı son derece şefkatli ve merhametlidir."},{"n":118,"t":"Allah, hükümleri ertelenen o üç kişinin de tevbelerini kabul etti. Sonunda yeryüzü bütün genişliğine rağmen onlara dar geldi, can sıkıntısından patlayacak gibi oldular, Allah’dan kaçmanın yine O’na sığınmaktan başka bir çıkar yolu olmadığını anladılar. Bunun üzerine Allah onların tevbelerini kabul etti ki, tevbe etsinler. Hiç kuşkusuz Allah, tevbelerin kabul edicisidir, merhametlidir."},{"n":119,"t":"Ey mü’minler Allah’dan korkunuz ve dosdoğrularla, gerçekten hiç ayrılmamış olanlarla beraber olunuz."},{"n":120,"t":"Gerek Medineliler’e ve gerekse çevrelerinde yaşayan Bedeviler’e savaşta peygamberden geri kalmak ve kendi canlarının kaygısını onun canının kaygısının önüne geçirmek yakışmaz. Çünkü Allah yolunda çekecekleri her susuzluk, katlanacakları her yorgunluk, karşılaşacakları her açlık, kâfirleri öfkelendirecek her bir karış toprağa ayak basmaları; düşmanın zararına kazanacakları her tür başarı karşılığında mutlaka hesaplarına iyi amel yazılır. Hiç şüphesiz Allah, iyi işler yapanları ödülsüz bırakmaz."},{"n":121,"t":"Yaptıkları küçük büyük bütün maddi harcamalar ve aştıkları her vadi, mutlaka hesaplarına yazılır ki, Allah işledikleri iyilikleri en güzel karşılıklarla ödüllendirsin."},{"n":122,"t":"Mü’minlerin topyekün sefere çıkmaları gerekmez. Bunun yerine her kabileden bir grup, dinin özünü öğrenmek ve kötülüklerden kaçınırlar umudu ile soydaşlarını uyarmak için sefere çıkmalıdır."},{"n":123,"t":"Ey mü’minler en yakınınızdaki kâfirler ile savaşınız, bunlar sizde sertlik bulsunlar ve biliniz ki, Allah kendisinden korkanlar ile beraberdir."},{"n":124,"t":"Her yeni sure indirilişinde kimi münafıklar, «Bu sure hanginizin imanını arttırdı?» diye sorarlar. Gerçek şu ki, o sure mü’minlerin imanını arttırmıştır, onlar bu yüzden sevinç duyarlar."},{"n":125,"t":"Fâkat kalplerinde hastalık olanlara gelince, bu sure pisliklerine pislik ekler de onlar kâfir olarak ölürler."},{"n":126,"t":"Buna rağmen ne tevbe ediyorlar ve ne de olup bitenlerden ders alıyorlar."},{"n":127,"t":"Yeni bir sure indirilince birbirlerine, «Acaba sizi bir gören var mı?» diye sorarlar, sonra sıvışırlar. Anlayışsız, duyarsız bir güruh olduklar gerekçesi ile Allah onların kalplerini gerçeklerden uzaklaştırmıştır."},{"n":128,"t":"Size kendinizden öyle bir peygamber geldi ki, sıkıntıya düşmeniz ağırına gider, size son derece düşkün, mü’minlere karşı şefkatli ve merhametlidir."},{"n":129,"t":"Eğer sana sırt çevirirlerse de ki, Allah bana yeter, O’ndan başka ilah yoktur ben sırf O’na dayandım, O, yüce Arş’ın sahibidir."}],[{"n":1,"t":"Elif, Lam, Ra. İşte bunlar o hikmet dolu Kitab’ın ayetleridir."},{"n":2,"t":"Bizim aralarında bir kişiye, ’insanları uyar’ ve ’mü’minlere, Rabbleri katında sarsılmaz bir derecenin sahibi oldukları müjdesini ver’ diye vahyetmemiz insanların tuhafına mı gitti ki, kâfirler, ’Bu adam açık bir büyücüdür’ dediler."},{"n":3,"t":"Rabbiniz Allah, gökleri ve yeri altı günde yarattı; sonra Arş’a kuruldu, her işi tasarlıyor ve çekip çeviriyor. O, izin vermedikçe hiç kimse aracılık (şefaat) edemez. İşte budur Rabbiniz olan Allah; o halde O’na kulluk ediniz; bunlar üzerine düşünüp ders almaz mısınız?"},{"n":4,"t":"Sonunda hepiniz O’na döneceksiniz. Bu Allah’ın kesinlikle gerçekleşecek bir vaadidir. O, iman edip iyi ameller işleyenleri adalet uyarınca ödüllendirmek için insanları önce hiç yoktan yaratır, sonra da onları yeniden diriltir. Kâfirlere gelince, gerçekleri inkâr ettiklerinden dolayı onları kaynar sıvıdan oluşmuş bir içki ile acıklı bir azap beklemektedir."},{"n":5,"t":"O, güneşi ışık kaynağı ve ayı aydınlık yaptı; yılların sayısını ve vakitlerin hesabını bilesiniz diye, ay için farklı doğuş noktaları belirledi. Allah bunları mutlaka bir gerçeğe, bir sebebe dayalı olarak yarattı. O bilen kimselere ayetlerini ayrıntılı biçimde anlatır."},{"n":6,"t":"Gece ile gündüzün birbirini kovalamasında ve Allah’ın gökler ile yerde yarattığı varlıklarda, O’ndan korkan kimseler için birçok ibret dersleri vardır."},{"n":7,"t":"Bizimle karşılaşacaklarını beklemeyenler, dünya hayatından hoşnut olup bu hayatla yetinenler ve ayetlerimizin farkında olmayanlar var ya;"},{"n":8,"t":"İşte bunların varacakları yer, işlediklerinin karşılığı olarak cehennemdir."},{"n":9,"t":"İman edip iyi ameller işleyenlere gelince, Rabbleri onları imanları sayesinde doğru yola iletir, nimet cennetlerinde onların altlarından nehirler akar."},{"n":10,"t":"Onların oradaki çağrıları, «Allah’ım, sen noksan sıfatlardan uzaksın» birbirlerine yönelik iyilik dilekleri, «selâm» ve son çağrıları da, «Alemlerin Rabbi olan Allah’a hamdolsun» sözleridir."},{"n":11,"t":"Allah, insanlara iyiliği istedikleri çabuklukta kötülüğü verseydi, süreleri hemen bitirilirdi. Oysa biz, bizimle karşılaşacaklarını beklemeyenleri azgınlıkları içinde debelenmeye bırakırız."},{"n":12,"t":"İnsanın başına bir sıkıntı gelince yatarken, otururken ve ayaktayken bize yalvarır. Fakat sıkıntısını giderdiğimizde başına gelen sıkıntıdan dolayı bize hiç yalvarmamış gibi olur. İşte ölçüyü aşanlara, işledikleri kötülükler böylesine güzel gösterildi."},{"n":13,"t":"Sizden önceki nice kuşakları, peygamberleri kendilerine açık gerçekler getirmişlerken, zalimce davranarak iman etmeye yanaşmadıkları için yokettik. İşte biz ağır suçlu toplumları böyle cezalandırırız."},{"n":14,"t":"Sonra nasıl davranacağınızı görelim diye sizi onların yerine geçirerek yeryüzünde egemen kıldık."},{"n":15,"t":"Onlara açık anlamlı ayetlerimiz okunduğunda, bizimle karşılaşacaklarını beklemeyenler sana, «bundan başka bir Kur’an getir ya da onu değiştir» dediler. Onlara de ki; «Onu kendiliğimden değiştirmem sözkonusu değildir. Ben sadece bana vahyolunan mesaja uyarım. Eğer Rabbime karşı gelirsem büyük günün azabından korkarım.»"},{"n":16,"t":"De ki; «Eğer Allah’ın dileği bu yolda olmasaydı, bu Kur’an’ı size okumazdım, hatta Allah sizi ondan hiç haberdar etmezdi, bundan önce aranızda bir ömür yaşadım, hiç düşünmüyor musunuz?»"},{"n":17,"t":"Allah’a yalan yakıştırmalar yapandan ya da O’nun ayetlerini yalanlayanlardan daha zalim kim olabilir? Hiç kuşkusuz ağır suçlular iflah olmazlar."},{"n":18,"t":"Onlar Allah’ı bırakarak kendilerine ne zarar ve ne de yarar dokunduramayan putlara tapıyorlar ve «Bunlar Allah katında bizim aracılarımızdır» diyorlar. Onlara de ki; «Göklerde ve yerde Allah’ın bilmediği bir şeyi mi O’na haber veriyorsunuz? Allah onların koştukları ortaklardan uzak ve yücedir."},{"n":19,"t":"Tüm insanlar tek bir ümmetten ibaretti, sonra görüş ayrılığına düştüler. Eğer Rabbinin daha önce kesinleşmiş bir kararı olmasaydı, anlaşmazlığa düştükleri konularda aralarında hemen hüküm verilirdi."},{"n":20,"t":"«Gaybı bilmek ancak Allah’a mahsustur, bekleyiniz bakalım, ben de sizinle beraber bekleyeceğim şüphesiz.»"},{"n":21,"t":"İnsanların başlarına gelen sıkıntılardan sonra kendilerine bir rahmet, bir rahatlık tattırdığımızda bakarsın ki, ayetlerimize karşı hemen tuzak kurarlar. Onlara de ki; «Allah sizden daha çabuk tuzak kurar, güvenlik elçilerimiz kurduğunuz tuzakları yazıyorlar.»"},{"n":22,"t":"Sizi karada yürüten ve denizde yüzdüren Allah’tır. Bir gemide olduğunuzu, hoş bir meltemin yolcuları götürdüğünü ve herkesin bunun hazzını yaşadığını düşününüz. Tam o sırada geminin bir kasırga ile karşılaştığını yolcuların her taraftan dalgalarla sarıldıklarını ve çepeçevre kuşatıldıklarını sandıkları zaman, sırf Allah’ın dinine inanan samimi bir bağlılıkla O’na şöyle yalvarırlar; «Eğer bizi bu tehlikeden kurtarırsan kesinlikle şükredenlerden olacağız.»"},{"n":23,"t":"Fakat Allah kendilerini bu zor durumdan kurtarır kurtarmaz hemen yeryüzünde haksız yere taşkınlıklara dalarlar. Ey insanlar, yapacağınız taşkınlıklar aslında kendi aleyhinizedir, bu yolla geçici dünyanın yararını elde edersiniz, ancak sonra bize dönersiniz, biz de yaptıklarınızı size bir bir haber veririz."},{"n":24,"t":"Dünya hayatı gökten indirdiğimiz su gibidir. Onunla, insan ve hayvanların yiyerek beslendikleri nebatlar bol bol yetişir; yeryüzü renk renk, çeşit çeşit mahsullerle süslenir ve yerin sahipleri bütün bunlara malik olduklarını sandıkları sırada, geceleyin veya gündüzün emrimiz geliverir de, orayı hiçbir şey bitirmemişe çeviririz. İşte Biz böylece ayetlerimizi, düşünen insanlar için, apaçık beyan ederiz."},{"n":25,"t":"Allah insanları esenlik, barış yurduna çağırır ve dilediği kimseleri doğru yola iletir."},{"n":26,"t":"Dünyada iyi işler yapanlara daha iyi bir karşılık ve fazlası vardır. Onların yüzlerini ne kara leke ve ne de horlanmışlık kaplar. Onlar cennetliklerdir, orada ebedi olarak kalacaklardır."},{"n":27,"t":"Dünyada kötülük işleyenlere gelince, her kötülüklerine karşılığı kadar ceza verilir. Yüzlerini horlanmışlık kaplar. Onları Allah’dan kurtaracak hiç kimseleri yoktur. Yüzleri sanki gecenin kesitleri ile kaplıdır. Onlar cehennemliklerdir, orada ebedi olarak kalacaklardır."},{"n":28,"t":"«Siz bize tapmıyordunuz.»"},{"n":29,"t":"Aramızda şahit olarak Allah yeterlidir. Gerçekten sizin bize taptığınızdan haberimiz yoktu."},{"n":30,"t":"İşte orada herkes geçmişteki her davranışının yararını ve zararını somut olarak görür, insanların tümü gerçek sahipleri olan Allah’a döndürülürler ve yakıştırdıkları düzmece ilahlar yanlarından kayboluverir."},{"n":31,"t":"Onlara de ki; «Gökten ve yerden size rızık veren kimdir? Kulaklara ve gözlere işlerini görme yeteneğini kim verdi? Ölüden diriyi ve diriden ölüyü çıkaran kimdir? Evrenin işlerini kim çekip çeviriyor? Sana, «Allah» diyeceklerdir. O zaman onlara, «Allah’dan korkmuyor musunuz?» de."},{"n":32,"t":"İşte gerçek Rabbiniz Allah budur. Gerçekten sonra sapıklıktan başka ne var ki? O halde nasıl gerçekten saptırılıyorsunuz?"},{"n":33,"t":"Böylece Rabbinin yoldan çıkmışlara ilişkin, onların iman etmeyecekleri şeklindeki sözü gerçekleşmiş oldu."},{"n":34,"t":"Onlara de ki; «Allah’a ortak koştuğunuz putlar içinde, yaratma olayını ilk başta gerçekleştiren ve sonra tekrarlayan var mı?» De ki; «Allah yaratma olayını ilk başta gerçekleştirir, sonra da onu tekrarlar. Doğrudan nasıl saptırılıyorsunuz?»"},{"n":35,"t":"Onlara de ki; «Allah’a ortak koştuğunuz putlar arasında gerçeğe ileten var mı?» De ki; «Allah, insanları gerçeğe iletir.» Acaba insanları gerçeğe ileten mi uyulmaya daha layıktır, yoksa başkasının kılavuzluğundan yararlanmadıkça doğru yolu kendi kendine bulamayan mı? O halde size ne oluyor da böyle yanlış hüküm veriyorsunuz?"},{"n":36,"t":"Onların çoğu sadece zayıf bilgiye, zanna dayanıyor. Oysa zan, zayıf bilgi, gerçeğin bir noktasının bile yerini tutamaz. Hiç şüphesiz Allah onların ne yaptıklarını bilir."},{"n":37,"t":"Bu Kur’an Allah’dan geldi, başkası tarafından uydurulmuş değildir. O, kendisinden önceki semavi kitapları onaylar ve ilahi kitabı ayrıntılı biçimde açıklar. Onun alemlerin Rabbi tarafından gönderildiği kuşkusuzdur."},{"n":38,"t":"Yoksa, ’Onu Muhammed uydurdu’ mu diyorlar? Onlara de ki; ’Eğer doğru söylüyorsanız, Kur’an’a benzer bir sure ortaya getiriniz, bu konuda Allah dışında kimleri yardıma çağırabilecekseniz, çağırınız."},{"n":39,"t":"Tersine onlar bilgisini kavrayamadıkları ve henüz açıklamasına da muhatap olmadıkları bir mesajı yalanladılar. Onlardan öncekiler de böyle yalanlanmışlardı. Gör bakalım, o zalimlerin sonu nice oldu?"},{"n":40,"t":"Onlardan kimi bu Kur’an’a inanır, kimi de inanmaz. Rabbin, kimlerin bozguncu olduğunu herkesten iyi bilir."},{"n":41,"t":"Eğer onlar seni yalanlarsa de ki; «Benim işlediklerim bana, sizin işledikleriniz de sizedir. Benim işlediklerim ile sizin bir ilginiz olmadığı gibi, sizin işlediklerinizle de benim bir ilgim yoktur.»"},{"n":42,"t":"Onların arasında Kur’an okurken sana kulak verenler de vardır. Fakat üstelik düşünme yeteneğinden de yoksun sağırlara, sen söz işittirebilir misin?"},{"n":43,"t":"Onların arasında sana bakanlar da vardır. Fakat görme yeteneğinden bütünü ile yoksun körleri, sen doğru yola iletebilir misin?"},{"n":44,"t":"Allah insanlara hiç zulmetmez, fakat insanlar kendi kendilerine zulmederler."},{"n":45,"t":"Allah insanları biraraya topladığı gün, sanki dünyada sadece gündüzün bir saati kadar kalmışlar ve bu süreyi birbirleri ile tanışmak için harcamışlar gibidirler. Allah ile karşılaşacaklarını yalanlayanlar gerçekten hüsrana uğramışlardır, onlar doğru yolu bulamamışlardır."},{"n":46,"t":"Kâfirleri çarptıracağımızı söz verdiğimiz cezanın bir bölümünü sana göstersek de ya da daha önce senin canını alsak da, onların dönüşü bizedir. Sonra Allah onların neler yaptıklarına tanıktır."},{"n":47,"t":"Her ümmete bir peygamber gönderilmiştir. Peygamberler gelip de mesajlarını duyurduktan sonra ümmetler hakkında adalet uyarınca hüküm verilir, onlara haksızlık edilmez."},{"n":48,"t":"Onlar, «Eğer doğru söylüyorsanız vadettiğiniz bu ceza ne zaman gerçekleşecek?» derler."},{"n":49,"t":"Onlara de ki; «Allah’ın dileği dışında benim kendime bile zarar ya da yarar dokundurmaya gücüm yetmez. Her ümmetin belirli bir yaşama süresi vardır. O süre dolunca, ne bir an geri bırakılırlar ve ne de bir an önceye alınırlar.»"},{"n":50,"t":"De ki; «Allah’ın azabı diyelim ki; gündüz ya da gece başınıza geldi. Suçlular bunun bir an önce gerçekleşmesini niye isterler ki?"},{"n":51,"t":"Yoksa azap başlarına geldikten sonra kendilerine, ’Şimdi ona inandınız mı? Hani onun bir an önce gerçekleşmesini istiyordunuz’ densin diye mi?"},{"n":52,"t":"Sonra zulmedenlere denir ki; «Sürekli azabı tadınız bakalım, sadece dünyada işlediklerinizin karşılıkları ile cezalandırılmıyor musunuz?"},{"n":53,"t":"Sana, «O ceza gerçek midir?» diye soruyorlar. Onlara de ki; «Rabbim hakkı için, evet. O, gerçektir, siz Allah’ın yapacağını engelleyemezsiniz.»"},{"n":54,"t":"Kendisine zulmetmiş olan herkes, o gün yeryüzünün bütün servetine sahip olsa bunu (azaptan kurtulmak için) fidye olarak verirdi. Onlar azabı gördükleri zaman pişmanlıktan donakalırlar. Haklarında adalet uyarınca hüküm verilir, kendilerine haksızlık edilmez."},{"n":55,"t":"Haberiniz olsun ki, göklerde ve yerde ne varsa hepsi Allah’ındır. Haberiniz olsun ki, Allah’ın vaadi gerçektir, fakat onların çoğu bunu bilmez."},{"n":56,"t":"Dirilten de öldüren de O’dur. O’nun huzuruna döndürüleceksiniz."},{"n":57,"t":"Ey insanlar, size Rabbinizden bir öğüt, kalplerdeki hastalıklara bir şifa, inananlara yol gösterici ve rahmet gelmiştir."},{"n":58,"t":"De ki; «Allah’ın lütfu ile, rahmeti ile, sadece bunlarla sevinsinler. Bunlar onların biriktirdikleri dünya malından daha hayırlıdır."},{"n":59,"t":"De ki; «Baksanıza Allah’ın size gönderdiği rızıklara? Bunların bir bölümünü haram ve bir bölümünü de helâl saydınız.» De ki; «Bu konuda Allah mı size izin verdi, yoksa O’na iftira mı ediyorsunuz?»"},{"n":60,"t":"Allah’a iftira edenlerin kıyamet günü görecekleri işleme ilişkin görüşleri nedir acaba? Hiç kuşkusuz Allah, insanlara karşı lütufkârdır, fakat onların çoğu şükretmezler."},{"n":61,"t":"Ne ile uğraşırsan uğraş. Kur’an’dan hangi parçayı okursan oku, hangi işi yaparsanız yapınız, işinize daldığınızda mutlaka davranışlarınızın tanığı, gözeticisiyiz. Ne yerde ve ne de gökte bulunan zerre ağırlığınca bir şey Rabbinizden saklı kalmaz. Gerek bundan daha küçüğü ve gerekse daha büyüğü mutlaka apaçık bir Kitap’ta yeralır."},{"n":62,"t":"Haberiniz olsun ki, Allah’ın dostlarına korku yoktur, onlar hiç üzülmeyeceklerdir de."},{"n":63,"t":"Onlar Allah’a inanmış ve kötülüklerden sakınmışlardır."},{"n":64,"t":"Onlar için dünya hayatında da ahirette de müjde vardır. Allah’ın verdiği sözlerin değişmesi sözkonusu değildir. Büyük kurtuluş, büyük başarı işte budur."},{"n":65,"t":"Kafirlerin sözleri sakın seni üzmesin. Çünkü üstünlük tümü ile, Allah’ın tekelindedir. O, her şeyi işiten ve her şeyi bilendir."},{"n":66,"t":"Haberiniz olsun ki, göklerde ve yerde kimler varsa hepsi Allah’ındır. Allah’ı bir yana bırakarak putlara tapanlar aslında bu düzmece ortaklara uymuyorlar; sadece sanıya, dayanaksız bilgiye uyuyorlar, sırf asılsız hayallerin peşinden gidiyorlar."},{"n":67,"t":"Geceyi dinlenmenize elverişli ve gündüzü aydınlık yapan O’dur. Hiç şüphesiz bu sözlerde, onlara kulak verenler için birçok ibret dersi vardır."},{"n":68,"t":"Müşrikler ’Allah evlât edindi’ dediler. Haşa! O’nun hiçbir şeye ihtiyacı yoktur. Göklerde ve yerde ne varsa O’nundur. Bu konuda elinizde hiçbir kanıt yoktur. Nasıl oluyor da Allah hakkında bilmediğiniz bir şeyi söyleyebiliyorsunuz!"},{"n":69,"t":"De ki; «Allah hakkında yalan uyduranlar kesinlikle iflah olmazlar.»"},{"n":70,"t":"Dünyada geçici bir yarar sağlarlar, arkasından dönüşleri bizedir, sonra gerçekleri inkâr etmelerinin karşılığı olarak onlara ağır bir azap tattırırız."},{"n":71,"t":"Hani o soydaşlarına demişti ki; «Ey soydaşlarım, eğer karşınıza çıkıp Allah’ın ayetlerini hatırlatmam ağırınıza gidiyorsa ben Allah’a dayandım; siz de Allah’a ortak koştuğunuz putlarla birlikte ne yapacağınızı kararlaştırınız, sonra vardığınız karardan dolayı başınız ağrımasın; arkasından şahsıma ilişkin kararınızı, bana hiçbir mühlet tanımaksızın uygulayınız."},{"n":72,"t":"Eğer çağrıma sırt dönüyorsanız, ben sizden herhangi bir ücret istemiş değilim, benim çabamın karşılığını verecek olan sadece Allah’dır; bana müslümanların, Allah’ın buyruklarına teslim olanların ilki olmam emredildi."},{"n":73,"t":"Yine de onu yalanladılar. Biz de onu ve gemideki arkadaşlarını boğulmaktan kurtararak, boğulanların yerine geçirdik ve ayetlerimizi yalanlayanları boğduk. Gör bakalım, uyarılıp da yola gelmeyenlerin sonu nice oldu?"},{"n":74,"t":"Sonra Nuh’un ardından birçok peygamberi soydaşlarına gönderdik. Peygamberler soydaşlarına açık mesajlar getirdiler. Fakat soydaşları daha önce yalanladıkları gerçeklere inanmaya yanaşmadılar. Biz de, ölçüyü aşanların kalplerini böyle mühürleriz."},{"n":75,"t":"Bu peygamberlerin ardından Musa ile Harun’u ayetlerimiz ile Firavun’a ve seçkin yakınlarına gönderdik, ama burun kıvırdılar ve ağır suçlu bir toplum oldular."},{"n":76,"t":"Bizim tarafımızdan gönderilen gerçek onlara ulaşınca, «Bu apaçık bir büyüdür» dediler."},{"n":77,"t":"Musa, onlara; «Size gelen gerçek için böyle mi diyorsunuz? Bu bir büyü müdür? Oysa büyücüler iflah olmazlar, kurtuluşa eremezler.»"},{"n":78,"t":"Musa’nın soydaşları dediler ki; «Siz ikiniz, bizi atalarımızdan miras aldığımız inanç ve geleneklerden vazgeçiresiniz ve bu yörede egemenliği ele geçiresiniz diye mi bize geldiniz? Biz size kesinlikle inanmayacağız.»"},{"n":79,"t":"Firavun, Bana bütün bilgili büyücüleri getiriniz» dedi."},{"n":80,"t":"Büyücüler gelince Musa onlara, ’Atacağınızı atınız, hünerinizi gösteriniz’ dedi."},{"n":81,"t":"Onlar atacaklarını atıp, hünerlerini gösterince Musa, «Sizin gösterdiğiniz hüner büyüdür; ama Allah onu kesinlikle boşa çıkaracaktır. Çünkü Allah bozguncuların işini amacına vardırmaz."},{"n":82,"t":"Suçluların hoşuna gitmese de, Allah sözleri ile direktifleri ile gerçeği üstün getirir."},{"n":83,"t":"Musa’ya soydaşlarının sadece bir bölüm gençleri inanmıştı. Bunlar da hem Firavun’dan ve hem de ileri gelen soydaşlarından kaynaklanan işkence korkularına rağmen inanmışlardı. Çünkü Firavun yeryüzünde koyu bir diktatörlük kurmuş, iyice azıtmıştı."},{"n":84,"t":"Musa dedi ki; «Ey soydaşlarım eğer Allah’a inandıysanız, eğer O’na teslim olmuşsanız, O’na dayanınız."},{"n":85,"t":"Onlar da dediler ki; «Biz Allah’a dayandık ey Rabbimiz, zalimler güruhunun bizi sapıklıklarına gerekçe göstermelerine meydan verme."},{"n":86,"t":"Rahmetinle bizi kâfirler güruhundan kurtar."},{"n":87,"t":"Biz Musa ile kardeşine vahyettik ki; «Soydaşlarınıza Mısır’da evler hazırlayınız, evlerinizi namazgâh haline getiriniz, namaz kılınız ve mü’minleri müjdeleyiniz.»"},{"n":88,"t":"Musa dedi ki; «Ey Rabbimiz, sen dünya hayatında Firavun’a ve yakın adamlarına debdebe ve bol servet verdin. Ey Rabbimiz, bunlar insanları senin yolundan saptırmak için kullanılıyor. Ey Rabbimiz, onların servetlerini mahvet ve kalplerini sıkıca mühürle ki, acıklı azabı görmedikçe iman etmesinler.»"},{"n":89,"t":"Allah dedi ki; «İkinizin duası kabul edildi, doğrultunuzdan şaşmayınız, bilmezlerin yoluna girmeyiniz.»"},{"n":90,"t":"İsrailoğulları’nı denizden geçirdik. Firavun ve askerleri saldırı ve düşmanlık amacı ile peşlerine düştüler. Sonunda Firavun boğulmanın eğişine geldiğinde, «İsrailoğulları’nın inandıkları ilahtan başka ilah olmadığına inandım, ben de O’na teslim olanlardan (müslümanlardan) biriyim» dedi."},{"n":91,"t":"«Şimdi mi aklın başına geldi? Daha önce Allah’a hep karşı gelmiş ve bozgunculardan biri olmuştun.»"},{"n":92,"t":"Bugün senden sonra geleceklere ibret osun diye cansız vücudunu bozulmaktan kurtaracak, onu sahilde bir tümseğe atacağız. Gerçi insanların çoğu bizim ibret verici belgelerimizin farkına varmazlar."},{"n":93,"t":"Gerçekten biz İsrailoğulları’nı güvenli bir yurda yerleştirdik, onlara temiz rızıklar sunduk. Kendilerine bilgi gelinceye kadar anlaşmazlığa düşmemişlerdi. Şüphe yok ki, Rabbin kıyamet günü anlaşmazlığa düştükleri konularda haklarında hüküm verecektir."},{"n":94,"t":"Eğer sana indirdiğimiz bilgilerden kuşku duyuyorsan, senden önceki kutsal kitap okurlarına sor. Sana Rabbinden kesinlikle gerçek geldi, sakın kuşkulananlardan olma."},{"n":95,"t":"Sakın Allah’ın ayetlerini yalanlayanlardan olma, yoksa hüsrana uğrayanlardan olursun."},{"n":96,"t":"Haklarında Rabbinin hükmü kesinleşenler asla iman etmezler."},{"n":97,"t":"Onlara bütün uyarıcı mesajlar gelse bile. Ancak acıklı azabı görünce iman ederler."},{"n":98,"t":"Keşke sözkonusu yıkıma uğramış şehirlerden herhangi biri iman etseydi de, imanının yararını görseydi! Yalnız Yunus’un soydaşları hariç. Onlar iman edince, dünya hayatında burun buruna geldikleri perişan edici azabı başlarından kaldırdık ve kendilerine belirli bir süre daha yaşama fırsatı tanıdık."},{"n":99,"t":"Eğer Rabbin dileseydi, yeryüzünde yaşayanların hepsi tümü ile iman ederdi. O halde insanları sen mi zorlayacaksın da iman edecekler?"},{"n":100,"t":"Allah’ın izni olmadıkça hiç kimsenin inanması sözkonusu değildir. Allah, aklını kullanmayanları en yüz kızartıcı iğrençliğin kucağına atar."},{"n":101,"t":"Onlara de ki; «Göklerde ve yerde neler olduğuna bakınız.» Fakat ibret verici belgelerin ve uyarıların iman etmeyenlere hiçbir yararı olmaz."},{"n":102,"t":"Onlar kendilerinden önce gelip geçen toplumların yaşadıkları acı günlerden başka bir sonuç mu bekliyorlar? Onlara de ki; «Bekleyiniz bakalım, ben de sizinle birlikte bekleyenlerdenim.»"},{"n":103,"t":"Sözkonusu toplu afetlerden sonra peygamberlerimizi ve iman edenleri kurtarırız. Mü’minleri kurtarmak böylece üzerimize borçtur."},{"n":104,"t":"De ki «Ey insanlar, benim dinimden şüphede iseniz, bilin ki ben Allah’tan başka taptıklarınıza tapmam. Ancak bizi öldürecek olan Allah’a kulluk ederim. Ben, mü’minlerden olmakla emrolundum.»"},{"n":105,"t":"«Yüzünü tevhit dinine döndür, sakın müşriklerden olma»"},{"n":106,"t":"«Allah’ı bırakıp ta sana ne fayda ne de zarar getirecek olan nesnelere tapma. Eğer öyle yapacak olursan şüphesiz zâlimlerden olursun denildi» de."},{"n":107,"t":"Allah sana bir sıkıntı verirse onu yine ancak Allah giderir. Sana bir iyilik dilediği takdirde O’nun nimetini engelleyecek bir kuvvet de yoktur. O, bunu kullarından dilediğine eriştirir. O, Gafûr dur, Rahîm dir."},{"n":108,"t":"«Ey insanlar, size Rabbinizden hak gelmiştir. Artık kim hidayeti kabul ederse o, ancak kendi faydası için hidayete ermiş, kim de saparsa, kendi zararına sapmış olur. Ben sizin başınızda bir bekçi de değilim.»"},{"n":109,"t":"Sana her ne vahy ediliyorsa ona tabi ol. Allah hükmünü verinceye kadar sabret. O, hüküm verenlerin en hayırlısıdır."}],[{"n":1,"t":"Elif, Lâm, Ra. Bu Kur’an, her işi yerinde ve her şeyden haberdar olan Allah tarafından muhkem, uyumlu cümlelerle örülen, sonra ayrıntılı biçimde açıklanan ayetlerden oluşmuş bir kitaptır."},{"n":2,"t":"Allah’dan başkasına kulluk sunmayınız. Ben, O’nun size gönderdiği bir uyarıcı ve müjdeleyiciyim."},{"n":3,"t":"Rabbinizden af dileyiniz, pişmanlık duygusu ile O’na yöneliniz ki, belirli bir sürenin sonuna kadar sizi mutlu yaşatsın ve her erdemli kişiye erdemli davranışlarının ödülünü versin. Eğer O’na sırt dönerseniz, sizin hesabınıza büyük günün azabından korkarım."},{"n":4,"t":"Dönüş yeriniz Allah’ın huzurudur. O’nun gücü her şeye yeter."},{"n":5,"t":"Haberiniz olsun ki, müşrikler kendilerine Kur’an okunurken Allah’dan gizlenmek için başlarını göğüslerine yapıştırarak iki büklüm olurlar. Haberiniz olsun ki, Allah başlarını elbiselerinin altında sakladıklarında gerek gizli tuttukları ve gerekse açığa vurdukları tüm duygularını bilir. O kalplerin özünü bilir."},{"n":6,"t":"Yeryüzündeki bütün canlı türlerinin beslenmelerini ve geçinmelerini sağlamak Allah’ın garantisi altındadır. O, onların ilk barınma yerleri ile geçiş yerlerini bilir. Bütün bunlar açık bir kitapta yazılıdır."},{"n":7,"t":"Sizi sınavdan geçirerek hanginizin daha iyi işler yapacağınızı belirlemek için gökleri ve yeri altı günde yaratan O’dur. Bu yaratılış süreci sırasında O’nun Arş’ı su üzerinde idi. Böyleyken eğer kâfirlere «Öldükten sonra dirileceksiniz» diyecek olsan, «Bu iddia, apaçık bir büyüden başka bir şey değildir» diyeceklerdir."},{"n":8,"t":"Eğer onların azabını belirli bir sürenin sonuna ertelersek, ’Bu azabı bizden alıkoyan nedir?’ derler. Haberleri olsun ki, azabımızla yüzyüze geldiklerinde onu hiç kimse başlarından savamaz, böylece alay konusu ettikleri akıbetin pençesine düşerler."},{"n":9,"t":"Eğer insana önce rahmetlerimizi tattırıp sonra onu elinden alsak, o mutsuz bir nanköre dönüşür."},{"n":10,"t":"Eğer insanın başına gelen bir sıkıntının ardından kendisine mutluluk tattıracak olursak, kesinlikle «Kötü günler artık geride kaldı» diyecektir. İnsan gerçekten kendini beğenmiş bir şımarıktır."},{"n":11,"t":"Yalnız sıkıntılı günlerde sabreden ve iyi ameller işleyenler bu iki kategorinin dışındadırlar; onları bağışlanma ve büyük ödül bekliyor."},{"n":12,"t":"Müşriklerin «Muhammed’e gökten bir hazine inseydi ya, ya da kendisi ile birlikte bir melek gelseydi ya» şeklindeki sözleri canını sıkabilir ve bu yüzden sana indirdiğimiz vahyin bir bölümünü onlara duyurmaktan vazgeçebilirsin. Oysa sen sadece bir uyarıcısın. Her şeyin yönlendiricisi Allah’dır."},{"n":13,"t":"Yoksa onlar «Muhammed, bu Kur’an’ı kendi uydurdu» mu diyorlar. Onlara de ki, «Öyleyse Kur’an’ın surelerine benzeyen on sure de siz uydurun bakalım. Eğer söylediğiniz doğru ise, bu konuda Allah dışında yardıma çağırabileceklerinizi de yardıma çağırın.»"},{"n":14,"t":"Eğer bu çağrına karşılık vermezlerse anlayınız ki, bu Kur’an Allah’ın bilgisi altında indirilmiştir ve O’ndan başka ilah yoktur. Nasıl, artık müslüman oldunuz mu?"},{"n":15,"t":"Sadece dünya hayatını ve bu hayatın çekici güzelliklerini isteyenlere çalışmalarının karşılığını orada tam olarak veririz, onlar orada hiçbir ödül kısıntısına uğratılmazlar."},{"n":16,"t":"Ama ahirette onlar için sadece cehennem ateşi vardır, dünyada yaptıkları iyi işler boşa gider, işledikleri yararlı ameller geçersiz olur."},{"n":17,"t":"Bir de Rabbinden kaynaklanan açık belgelere dayanan kimseleri düşünelim. Bu belgeleri yine Allah katından gelen bir tanık izliyor. Bu kimseler onun da öncesinde Musa’nın önder ve rahmet nitelikli kitabının onayı ile desteklenmişlerdir. (Böyleleri sırf dünya hayatı peşinde koşanlarla hiç bir olur mu?)"},{"n":18,"t":"Allah’a yalan yakıştırmalar yapanlardan daha zalim kim olabilir? Onlar Rabblerinin huzuruna çıkarıldıklarında, tanıklar «Bunlar Rabbleri hakkında yalan yakıştırmalar düzmüşlerdir» derler. Haberiniz olsun ki, Allah’ın lâneti zalimlerin üzerinedir."},{"n":19,"t":"Onlar insanları Allah yolundan alıkoyarlar. O yolu eğri göstermeye yeltenirler ve ahireti de inkâr ederler."},{"n":20,"t":"Bunların, Allah’ın yapacaklarına engel olmaları sözkonusu değildir. Allah dışında dayanakları, destekçileri de yoktur. Azapları katlanır. Ne işitebilirler ve ne de görebilirler."},{"n":21,"t":"Bunlar kendilerini hüsrana düşürmüşler ve uydurdukları ilahlar ortalıkta görünmez olmuşlardır."},{"n":22,"t":"Onlar, hiç kuşkusuz, ahirette en ağır hüsrana uğrayacak kimseler olacaklardır."},{"n":23,"t":"İman edip iyi ameller işleyenlere ve Allah’a gönülden saygı besleyenlere gelince, onlar cennetliklerdir ve orada ebedi olarak kalacaklardır."},{"n":24,"t":"Bu iki grup kör ve sağır ile görebilen ve işitebilen kimselere benzer. Hiç bu iki grubun durumu bir olur mu? Acaba ibret dersi almaz mısınız?"},{"n":25,"t":"Biz Nuh’u soydaşlarına peygamber olarak gönderdik. (O onlara dedi ki); «Ben sizin için açık bir uyarıcıyım.»"},{"n":26,"t":"Sırf Allah’a kulluk sununuz. Yoksa sizin hesabınıza acıklı bir günün azabından korkarım."},{"n":27,"t":"Soydaşlarının ileri gelen kâfirleri O’na dediler ki, «Biz senin sadece bizim gibi bir insan olduğunu görüyoruz. Sana uyanların da aramızdaki ilkel düşünceli, ayak takımı olduğunu görüyoruz. Sizin bize karşı herhangi bir üstünlük taşıdığınız görüşünde değiliz. Tersine sizlerin yalan söylediğiniz kanısındayız."},{"n":28,"t":"Nuh dedi ki; «Ey soydaşlarım, baksanıza, eğer ben Rabbimden gelen açık belgelere dayanıyorsam, eğer O bana kendi katından bir rahmet verdi ise de siz bunu görmekten yoksun bırakıldı iseniz, istemediğiniz halde sizi bu açık belgeleri ve bu rahmeti kabul etmeye mi zorlayacağız?»"},{"n":29,"t":"Ey soydaşlarım, bu uyarı çabalarıma karşılık sizden maddi bir karşılık istemiyorum, benim ücretimi verecek olan Allah’dır, mü’minleri yanımdan kovacak değilim, çünkü onlar Rabblerine kavuşacaklardır. Fakat sizin gerçeklerden habersiz bir toplum olduğunuzu görüyorum."},{"n":30,"t":"Ey soydaşlarım, eğer o mü’minleri yanımdan kovacak olursam, Allah’a karşı beni kim savunabilir? Bunu hiç düşünmüyor musunuz?"},{"n":31,"t":"Size ’Allah’ın hazineleri benim elimin altında da’ demiyorum, gayp alemini de bilemem, ’Ben bir meleğim’ de demiyorum. Sizin gözlerinize hor görünen kimselere Allah’ın hiçbir hayır vermediğini de söyleyemem, kalplerinde neler olduğunu herkesten iyi bilen Allah’dır. Yoksa zalimlerden biri olurum."},{"n":32,"t":"Soydaşları dediler ki; «Bizimle tartıştın, üstelik bu tartışmayı çok uzattın, eğer söylediklerin doğru ise, ileride karşımıza çıkacak diye bizi korkuttuğun azabı şimdi başımıza getir de görelim.»"},{"n":33,"t":"Nuh dedi ki; «O azabı eğer dilerse yalnız Allah başınıza getirebilir. Siz O’nun yapacaklarına engel olamazsınız.»"},{"n":34,"t":"Eğer Allah, sizin azmanızı istiyorsa, size nasihat etmek istesem de benim nasihatim size yararlı olmaz. O’dur sizin Rabbiniz ve O’nun huzuruna döneceksiniz."},{"n":35,"t":"Ey Muhammed -salât ve selâm üzerine olsun- yoksa sana «Bu Kur’an’ı sen uydurdun mu?» diyorlar. Onlara de ki; «Eğer onu ben uydurdumsa, suçu bana aittir. Ben sizin suçlarınızın sorumluluğundan uzağım.»"},{"n":36,"t":"Nuh’a vahiy yolu ile bildirildi ki; «Daha önce inananlar dışında soydaşlarından başka inanan olmayacaktır. Onların yaptıklarından dolayı üzülme.»"},{"n":37,"t":"Bizim gözlerimiz önünde ve vahyimiz uyarınca gemiyi yap, zalimler konusunda bana başvurma, çünkü onlar kesinlikle boğulacaklardır."},{"n":38,"t":"Nuh, gemiyi yapar. İleri gelen soydaşlarının yanından geçen her grubu kendisini alaya alır. Nuh da onlara dedi ki; «Siz bizimle alay ediyorsunuz, ama şimdi siz bizimle nasıl alay ediyorsanız. İlerde biz sizinle alay edeceğiz.»"},{"n":39,"t":"Perişan edici azabın hangimizin başına geleceğini, hangimizin sürekli azaba uğrayacağını yakında öğreneceksiniz."},{"n":40,"t":"Nihayet emrimiz gelip tandır kaynamaya (her taraftan sular fışkırmaya) başlayınca Nuh’a «Her canlı türünün birer çiftini, boğulacağına ilişkin hükmümüzün kesinleştiği kimse dışında kalan aile bireylerini ve mü’minleri gemiye bindir» dedik. Zaten O’na az sayıda kişi inanmıştı."},{"n":41,"t":"Nuh dedi ki; «Haydi gemiye bininiz. Onun sular içinde yol alması da, bir yerde durması da Allah’ın adı ile gerçekleşecektir. Hiç şüphesiz Rabbim affedicidir, merhametlidir.»"},{"n":42,"t":"\"Yavrucuğum! Gel, bizimle birlikte bin gemiye; inkara gömülüp gidenlerle birlikte olma!\""},{"n":43,"t":"Oğlu «Beni sulardan koruyacak bir dağa sığınacağım» dedi. Nuh, ona «Bugün Allah’ın emrinden kurtaracak hiçbir güç yoktur, sadece O’nun esirgedikleri kurtulabilir» dedi. Tam bu sırada aralarına bir dalga girdi de Nuh’un oğlu boğulanların arasına katıldı."},{"n":44,"t":"Bir süre sonra yere «Ey yer, suyunu yut» ve göğe «Ey gök, yağmurunu tut» dendi. Bunun üzerine sular çekildi, Allah’ın emri gerçekleşti ve gemi Cudi’ye oturdu. Bu sırada «Kahrolsun zalimler güruhu» diyen bir ses duyuldu."},{"n":45,"t":"Nuh, Rabbine seslenerek dedi ki; «Ey Rabbim, oğlum ailemin bir bireyi idi, senin vaadin de gerçektir ve sen kesinlikle hüküm verenlerin en yerinde hüküm verenisin.»"},{"n":46,"t":"Allah dedi ki; «Ey Nuh, o oğlun senin ailenden değildi. Çünkü o kötü işler yaptı. İçyüzünü bilmediğin bir şeyi yapmamı benden isteme. Sana cahillerden olmamanı öğütlerim.»"},{"n":47,"t":"Nuh dedi ki; «İçyüzünü bilmediğim bir şeyi yapmanı istemekten sana sığınırım. Eğer sen beni affetmez, bana merhamet etmezsen hüsrana uğrayanlardan olurum.»"},{"n":48,"t":"Bu sırada şöyle bir ses duyuldu; «Ey Nuh, sana ve yanındakilerden meydana gelecek ümmetlere sunacağımız esenliğin ve bereketlerin eşliğinde gemiden in. Yanındakilerin soyundan başka ümmetler de gelecektir. Bunlara bir süreye kadar dünya nimetlerini tattırdıktan sonra kendilerini acıklı azabımıza çarptıracağız.»"},{"n":49,"t":"Ey Muhammed, bu anlatılanlar sana vahiy yolu ile bildirdiğimiz gaybe ilişkin haberlerdir. Bundan önce ne sen ve ne de soydaşların bu olayları bilmiyordunuz. Müşriklerin olumsuz tepkilerine karşı sabret; sonuç, kötülüklerden sakınanlarındır."},{"n":50,"t":"Adoğullarına da kardeşleri Hud’u peygamber olarak gönderdik. Hud dedi ki; «Ey soydaşlarım, sadece Allah’a kulluk sununuz, O’ndan başka ilahınız yoktur. Başka ilahlara taptığınız için sizler birer iftiracısınız, uydurmaların peşinden gidiyorsunuz.»"},{"n":51,"t":"Ey soydaşlarım, bu uyarı çabalarıma karşılık sizden herhangi bir ücret istemiyorum. Benim ücretimi, beni yoktan vareden Allah verecektir. Acaba aklınızı başınıza toplamayacak mısınız?"},{"n":52,"t":"Soydaşlarım, Rabbinizden af dileyiniz, arkasından O’na yöneliniz ki, size gökten bol yağmur göndersin, gücünüze güç katsın, suç işlemekte ısrar ederek çağrıma sırt çevirmeyiniz."},{"n":53,"t":"Soydaşları dediler ki; «Ey Hud, bize somut bir mucize getirmiş değilsin. Sırf öyle diyorsun diye ilahlarımızı bırakmayız, sana kesinlikle inanmıyoruz.»"},{"n":54,"t":"«Seni ilahlarımızdan biri çarpmış olmalı.» Hud dedi ki; «Ben Allah’ı şahit tutuyorum, ayrıca siz de şahit olunuz ki, ben O’na koştuğunuz ortaklardan uzağım.»"},{"n":55,"t":"Siz ve Allah dışında O’na ortak koştuğunuz ilahlar hep birlikte bana istediğiniz tuzağı kurunuz, sonra da bana hiç mühlet vermeyiniz."},{"n":56,"t":"Ben, benim ve sizin Rabbiniz olan Allah’a dayandım. Hiçbir canlı yoktur ki, perçemi O’nun avucu içinde olmasın. Hiç kuşkusuz benim Rabbim, doğru yoldadır."},{"n":57,"t":"Eğer benim çağrıma sırt dönecek olursanız, ben size gönderilen mesajı duyurdum. Rabbim, sizin yerinize başka bir toplum getirir. Siz O’na hiçbir zarar dokunduramazsınız. Hiç kuşkusuz, her şey Rabbimin gözetimi ve denetimi altındadır."},{"n":58,"t":"Azaba ilişkin emrimiz geldiğinde Hud’u ve beraberindeki mü’minleri, rahmetimizin sonucu olarak, kurtardık; onları ağır azaptan koruduk."},{"n":59,"t":"İşte sana o Adoğulları; onlar Rabblerinin ayetlerini yalanladılar, O’nun peygamberlerine karşı geldiler ve ne kadar küstah zorba varsa hepsinin emirlerine uydular."},{"n":60,"t":"Gerek bu dünyada gerek kıyamet gününde Allah’ın lânetine uğradılar. Haberiniz olsun, Adoğulları Rabblerini inkâr ettiler. Hey, kahrolsun Hud’un soydaşları olan Adoğulları!"},{"n":61,"t":"Semudoğulları’na da kardeşleri Salih’i peygamber olarak gönderdik. Salih dedi ki; ’’Soydaşlarım, sadece Allah’a kulluk sununuz, O’ndan başka bir ilahınız yoktur. Sizi topraktan yaratan ve yeryüzüne yerleştirerek burayı kalkındırmakla görevlendiren O’dur. O’ndan af dileyiniz, O’na yöneliniz. Çünkü Allah, kullarına yakındır ve dileklerin kabul edicisidir."},{"n":62,"t":"Soydaşları dediler ki; «Ya Salih, bundan önce sen kendisine umut bağladığımız bir kişi idin. Şimdi bize atalarımızın taptıkları ilahlara tapmayı mı yasaklıyorsun? Bizi benimsemeye çağırdığın ilkeler konusunda koyu bir kuşku içindeyiz.»"},{"n":63,"t":"Ey soydaşlarım, baksanıza, eğer ben Rabbimden gelen açık bir belgeye dayanıyorsam, O bana kendi katından bir rahmet bağışladı ise, emrine karşı geldiğim taktirde beni O’ndan kim kurtaracak? Sizin bana zararımı arttırmaktan başka hiç bir katkınız olamaz."},{"n":64,"t":"Ey soydaşlarım, bu Allah’ın devesidir, size bir mucize olarak gönderildi; bırakın onu Allah’ın toprağında dolaşıp yesin içsin; ona bir kötülük dokundurmayın, yoksa yakın vadeli bir azaba çarpılırsınız."},{"n":65,"t":"\"Yurdunuzda üç gün daha kalın, bu yalanlanmayacak sözdür.\" ..."},{"n":66,"t":"Azaba ilişkin emrimiz geldiğinde Salih ile beraberindeki mü’minleri helak olmaktan ve o günkü onur kırıcı perişanlıktan, rahmetimizin sonucu olarak, kurtardık. Hiç şüphesiz senin Rabbin güçlüdür, üstün iradelidir."},{"n":67,"t":"O zalimleri müthiş bir gürültü yakaladı da evlerinde, oldukları yerde yığılıp kalıverdiler."},{"n":68,"t":"Sanki az önce o evlerde yaşayanlar onlar değildi. Haberiniz olsun ki, Semudoğulları Rabblerini inkâr ettiler. Hey, kahrolsun Semudoğulları!"},{"n":69,"t":"Hani elçilerimiz İbrahim’e müjdeli haberi getirdiklerinde ona, «Selâm sana» dediler. O da onlara «Selâm size» dedi. Az sonra önlerine kızarmış bir buzağı getirdi."},{"n":70,"t":"İbrahim, elçilerin kızarmış buzağıya doğru el uzatmadıklarını görünce, konukları tuhafına gitti, içine onlardan kaynaklanan bir korku düştü. Bu sırada konukları «Korkma, biz Lût’un soydaşlarına gönderildik» dediler."},{"n":71,"t":"O sırada ayakta duran İbrahim’in karısı bu haberi duyunca güldü. Biz de ona o elçiler aracılığı ile oğlu İshak’ın ve İshak’ın arkasından da torunu Yakub’un müjdesini ilettik."},{"n":72,"t":"Aman Allah’ım! Doğum mu yapacağım? Oysa ben yaşlı bir kadınım, şu eşim de ihtiyar bir adamdır. Bu şaşılacak bir şey!"},{"n":73,"t":"Konuklar, kadına «Allah’ın işine mi şaşıyorsun? Ey hane halkı, Allah’ın rahmeti ve bereketi üzerinizdedir. Hiç kuşkusuz O, övgüye ve yüceltilmeye lâyıktır» dediler."},{"n":74,"t":"İbrahim’in korkusu geçip de müjdeli haberi alınca, Lût’un soydaşları hakkında elçilerimiz ile tartışmaya girişti."},{"n":75,"t":"İbrahim, gerçekten hoşgörülü, yumuşak kalpli ve kendini Allah’a adamış bir kimse idi."},{"n":76,"t":"Konuk melekler ona dediler ki; «Ey İbrahim, bu işten vazgeç; çünkü Rabbinin emri gelmiştir. Onların başlarına geri çevrilmesi mümkün olmayan bir azap gelecektir.»"},{"n":77,"t":"Elçilerimiz Lût’un yanına vardıklarında kaygıya kapıldı, canı sıkıldı ve «bugün, zor bir gündür» dedi."},{"n":78,"t":"Soydaşları apar topar evine koştular. Daha önce pis işler yapıyorlar, iğrenç ilişkilerde bulunuyorlardı. Lût onlara dedi ki; «Soydaşlarım, işte kızlarım, onlarla eşleşmek sizin için daha temiz bir iştir. Allah’dan korkun da beni konuklarım önünde rezil etmeyin. İçinizde aklı başında biri yok mu?»"},{"n":79,"t":"Soydaşları «Biliyorsun ki, bizim kızlarınla bir işimiz, onlara yönelik bir amacımız yok. Sen bizim ne istediğimizi iyi bilirsin» dediler."},{"n":80,"t":"Lût, melek konuklarına dönerek dedi ki, «Keşki siz bana dayanak olacak güçte olsaydınız, ya da himayelerine sığınabileceğim gözüpek adamlarım olsaydı!»"},{"n":81,"t":"Konukları dediler ki; «Ey Lût, biz Rabbinin elçileriyiz; onlar sana ilişemeyecekler. Geceleyin bir ara aileni yanına alarak yola çık, hiçbiriniz geride kalmasın. Yalnız eşini yanına alma. Çünkü soydaşlarının başına ne gelecekse onun da başına gelecektir. Vadeleri tanyeri ağarınca dolacaktır. Tan yerinin ağarması yakın değil mi?»"},{"n":82,"t":"Azaba ilişkin emrimiz geldiğinde orayı altüst ettik, oranın halkı üzerine, sağanak halinde balçıkla kaplanmış taşlar yağdırdık."},{"n":83,"t":"Bunlar Rabbinin katında dökülüp damgalanmış taşlardı. Bu tür bir azap, zalimlerin uzağında değildir."},{"n":84,"t":"Medyenoğulları’na da kardeşleri Şuayb’ı peygamber olarak gönderdik. Şuayb dedi ki; «Ey soydaşlarım, sadece Allah’a kulluk sununuz, O’ndan başka ilahınız yoktur. Birşey ölçer ya da tartarken eksik ölçüp tartmayınız. Bolluk içinde olduğunuzu görüyorum, ama sizin hesabınıza kıyamet gününün geniş kapsamlı azabından korkuyorum.»"},{"n":85,"t":"«Ey soydaşlarım, bir şey ölçer ya da tartarken adalete uyarak ölçüyü ve tartıyı tam tutunuz. Halkın mallarına düşük değer biçmeyiniz. Yeryüzünde kargaşa çıkarıp dirliği bozmayınız."},{"n":86,"t":"Eğer mü’min kimseler iseniz, Allah’ın size bıraktığı pay, hakkınızda daha hayırlıdır. Ben sizi gözetlemekle, korumakla görevli değilim.»"},{"n":87,"t":"Soydaşları dedi ki; «Ey Şuayb, atalarımızın taptıkları ilahlara tapmayı bırakmamızı ve mallarımız konusunda dilediğimiz tasarrufları yapmaktan kaçınmamızı emreden, empoze eden faktör, şu kıldığın namaz mıdır? Aslında sen yumuşak huylu, uslu ve aklı başında bir adamsın.»"},{"n":88,"t":"Şuayb dedi ki; «Soydaşlarım, baksanıza, ya ben Rabbimden gelen açık bir belgeye dayanıyorsam ve O bana kendi rahmetinin sonucu olarak temiz bir geçim kaynağı vermiş ise? Yasakladığım hareketleri kendim yaparak size ters düşmek istemiyorum. Tek isteğim, gücümün yettiği oranda bozuklukları düzeltmektir. Başarım Allah’ın yardımına bağlıdır. Yalnız O’na dayanıyor ve sadece O’na yöneliyorum.»"},{"n":89,"t":"Soydaşlarım, içinizdeki bana ters düşme, zıt çıkma tutkusu, Nuh’un, Hud’un ya da Salih’in soydaşlarının başına gelen felâketler gibi bir felâketin sizin de başınıza gelmesine sakın yolaçmasın. Üstelik Lût kavmi size pek uzak değil."},{"n":90,"t":"Soydaşlarım, Rabbinizden af dileyiniz, sonra O’na yöneliniz. Hiç şüphesiz Rabbim kullarına karşı merhametlidir, sevecendir."},{"n":91,"t":"eğer ailen(den hatırını saydıklarımız) olmasaydı, seni mutlaka taşa tutardık; zira sen bizden hiç de güçlü ve üstün değilsin.\""},{"n":92,"t":"Ey soydaşlarım, aşiretim sizin gözünüzde Allah’dan daha mı üstün, daha mı önemlidir ki, O’na sırt döndünüz, O’nu yabana attınız? Hiç kuşkusuz, yaptığınız her hareket Rabbimin bilgisinin kapsamı içindedir."},{"n":93,"t":"Soydaşlarım, siz bildiğiniz gibi hareket ediniz, ben de bildiğim gibi hareket edeyim. Hangimizin perişan edici bir azaba uğrayacağını, hangimizin yalancı olduğunu yakında göreceksiniz. Bekleyiniz; ben de sizinle birlikte bekliyorum."},{"n":94,"t":"Azaba ilişkin emrimiz geldiğinde Şuayb ile beraberindeki mü’minleri, rahmetimizin sonucu olarak kurtardık. O zalimler müthiş bir gürültüye tutuldular da evlerinde, oldukları yerde yığılıp kalıverdiler."},{"n":95,"t":"Sanki az önce o evlerde yaşayanlar onlar değildi. Hey, Semudoğulları nasıl kahroldularsa, Medyenoğulları da öyle kahrolsunlar!"},{"n":96,"t":"Musa’yı da ayetlerimizle ve somut mucizeler ile peygamber olarak gönderdik."},{"n":97,"t":"Onu Firavun’a ve yandaşlarına gönderdik. Yândaşları Firavun’un emrine uydular. Oysa Firavun’un emri doğruya iletici değildir."},{"n":98,"t":"Kıyamet günü, Firavun soydaşlarının önüne düşerek onları cehenneme götürdü. Vardıkları yer ne fena bir yerdir!"},{"n":99,"t":"Çarpıldıkları azaba ek olarak hem dünyada hem de ahirette lânete uğramışlardır. Paylarına düşen bu armağan ne fena bir armağandır."},{"n":100,"t":"Ya Muhammed, sana anlattığımız bu olaylar, bu şehirlerin hikâyeleridir. Bu şehirlerin kimisi halâ duruyor, kimisi de biçilmiş ekin tarlasına dönüşmüştür."},{"n":101,"t":"O şehirlerin halklarına biz zulmetmedik, tersine onlar kendilerine zalimlik ettiler. Allah’ın azaba ilişkin emri geldiğinde Allah dışında imdada çağırdıkları düzmece ilahları, hiçbir dertlerine deva olmadılar, yıkımlarını arttırmaktan başka hiçbir işlerine yaramadılar."},{"n":102,"t":"İşte Rabbin, zalim halkların şehirlerinin yakasından tutunca böyle tutar. Hiç kuşkusuz O’nun yakaya yapışması pek sert ve acıklıdır."},{"n":103,"t":"Ahiret azabından korkanlar için bu olaylardan çıkarılacak dersler vardır. O gün tüm insanların toplantı günüdür, herkes o günün canlı tanığı olacaktır."},{"n":104,"t":"Biz o günü, sadece sayılı günlerin sonuna kadar erteliyoruz."},{"n":105,"t":"O gün geldiğinde Allah’ın izni olmadıkça hiç kimse konuşamaz. O gün kimi insanlar mutlu, kimisi ise bedbahttır."},{"n":106,"t":"Bedbahtların varacakları yer cehennem ateşidir. Onların orada ahlandıkları, vahlandıkları, hırıltılı seslerle inledikleri duyulur."},{"n":107,"t":"Gökler ile yer durdukça, Rabbinin dileği uyarınca cehennemlikler orada sürekli kalacaklardır. Hiç kuşkusuz Rabbin neyi isterse onu yapar."},{"n":108,"t":"Mutluların varacakları yer ise cennettir. Gökler ile yer durdukça Rabbinin dileği uyarınca cennetlikler kesintisiz bir bağış olarak orada sürekli kalacaklardır."},{"n":109,"t":"Ey Muhammed, şu müşriklerin taptıkları ilahların düzmece oldukları konusunda sakın kuşkun olmasın. Onlar vaktiyle atalarının yaptıkları gibi asılsız ilahlara tapıyorlar. Onlara hakettikleri karşılığı eksiksiz olarak vereceğiz."},{"n":110,"t":"Musa’ya kitap verdik, fakat bu kitap (Tevrat) hakkında insanlar görüş ayrılığına düştüler. Eğer Rabbinin daha önce verilmiş kesin hükmü olmasaydı, o anlaşmazlığa düşenler hakkında çoktan hüküm verilirdi. Onlar Tevrat konusunda koyu bir kuşku içindedirler."},{"n":111,"t":"Kuşku yok ki, Rabbin onların tümüne davranışlarının karşılığını tam olarak verecektir. Hiç şüphesiz, O, onların neler yaptıklarından haberdardır."},{"n":112,"t":"Ey Muhammed, sana emredildiği gibi dosdoğru ol; yanındaki eski sapıklıklarından tevbe edenler de öyle olsunlar. Sakın ölçüleri aşmayınız. Hiç kuşkusuz Allah bütün yaptıklarınızı görür,"},{"n":113,"t":"Sakın zalimlere eğilim, yakınlık göstermeyiniz. Yoksa cehennem ateşi yakalar sizi; Allah’dan başka bir dostunuz, bir dayanağınız yoktur. O zaman O’nun yardımını göremezsiniz."},{"n":114,"t":"Gündüzün iki ucunda ve gecenin ilk saatlerinde namaz kıl; iyi ameller kötülükleri giderirler. Bu hatırlatmalar öğüt alacak yetenekte olanlar için birer öğüttür."},{"n":115,"t":"Müşriklerin sana çektirdikleri sıkıntılara karşı sabret; çünkü Allah, iyi davranışları ödülsüz bırakmaz."},{"n":116,"t":"Sizden önceki kuşaklardan, yeryüzünde bozgunculuktan sakındıran birtakım akıllı ve erdemli kimseler çıksaydı ya! Sadece toplu felaketlerden kurtardığımız az sayıda kimse bu görevi yerine getirdi. Zalimler ise kendilerini şımartan ihtiraslarına kapılarak ağır suçlara daldılar."},{"n":117,"t":"Sözkonusu şehirlerin halkları doğru yoldayken, Rabbin oraları haksızlıkla helak etmiş değildir."},{"n":118,"t":"Eğer Rabbin dileseydi, tüm insanları tek bir ümmet yapardı. Oysa insanlar sürekli görüş ve inanç ayrılığı içindedirler."},{"n":119,"t":"Yalnız Rabbinin merhametine mazhar olabilenler doğru yolda görüş ve inanç birliği sağlayabiliyorlar. Zaten Allah insanları bunun için yarattı. Rabbinin «cehennemi, mutlaka insanlarla ve cinlerle dolduracağım» şeklindeki sözü çoktan kesinleşti."},{"n":120,"t":"Sana anlattığımız, önceki peygamberlerin hayatına ilişkin her olay, gönlünü ferahlatmayı ve azmini pekiştirmeyi amaçlıyor. Bu hikâyeler sana gerçeği ilettikleri gibi mü’minler için de öğüt ve hatırlatma niteliğindedirler."},{"n":121,"t":"İnanmayanlara de ki; ’Siz bildiğiniz gibi hareket ediniz, biz de bildiğimiz gibi hareket edelim. ’"},{"n":122,"t":"Bekleyiniz bakalım, biz de bekliyoruz."},{"n":123,"t":"Göklere ve yere ilişkin bilinmezliklerin (gaybın) bilgisi Allah’ın tekelindedir. Her işin kesin çözüm mercii O’dur. Öyleyse sırf O’na kulluk sun, yalnız O’na dayan; Rabbın onların neler yaptıklarından habersiz değildir."}],[{"n":1,"t":"Elif, Lâm Râ; bunlar, gerçeği açık açık anlatan kitabın ayetleridir."},{"n":2,"t":"Biz o kitabı Arapça bir Kur’an olarak indirdik ki anlayabilesiniz."},{"n":3,"t":"Biz bu Kur’an’ı vahyetmekle sana kıssaların, eski milletler ile ilgili hikâyelerin en güzelini anlatıyoruz. Oysa daha önce bu hikâyeleri hiç bilmiyordun."},{"n":4,"t":"Hani Yusuf babasına «Babacığım; ben rüyamda onbir yıldızın, güneşin ve ayın önümde secde ettiklerini gördüm» dedi."},{"n":5,"t":"Babası ona dedi ki; «Yavrum bu rüyanı kardeşlerine anlatma; sonra sana tuzak kurarlar. Çünkü şeytan insanın açık bir düşmanıdır."},{"n":6,"t":"Tıpkı rüyanda gördüğün gibi Rabbin seni peygamber olarak seçecek, sana olayları (ya da rüyaları) yorumlamaya ilişkin bazı bilgiler öğretecek ve daha önce ataların İbrahim ile İshak’a yönelik nimetini nasıl tamama erdirdi ise, sana ve Yakub’un soyuna yönelik nimetini de tamama erdirecektir. Hiç kuşkusuz Rabbin herşeyi bilir ve her işi yerinde yapar."},{"n":7,"t":"Yusuf ile kardeşleri olayında, bu olayın içyüzünü irdeleyenlerin alacağı birçok ibret dersleri vardır."},{"n":8,"t":"Hani Yusuf’un üvey kardeşleri dediler ki; «Babamız, Yusuf ile öz kardeşini bizden daha çok seviyor. Oysa biz sayıca çok ve güçlü bir grubuz. Kuşku yok ki, babamız açık biçimde hatalıdır.»"},{"n":9,"t":"Yusuf’u ya öldürünüz, ya da ıssız bir yere bırakınız; o zaman babanızın rakipsiz sevgilileri olursunuz, arkasından da tevbe eder iyi kimseler olursunuz."},{"n":10,"t":"Üvey kardeşlerden biri dedi ki; «Yusuf’u öldürmeyiniz; eğer mutlaka bir şey yapmak istiyorsanız, onu bir kuyunun dibine atınız da yoldan geçecek kervanlardan biri onu çıkarıp alsın.»"},{"n":11,"t":"Bunun üzerine üvey kardeşler, babalarına dediler ki; «Ey babamız, niçin Yusuf konusunda bize güvenmiyorsun? Oysa biz onun sadece iyiliğini isteriz."},{"n":12,"t":"Yarın onu bizimle birlikte kıra gönder; yesin, içsin, eğlensin, biz ona kesinlikle göz kulak oluruz."},{"n":13,"t":"Babaları dedi ki; «Onu götürmeniz beni üzer, ayrılığına dayanamam; ayrıca korkarım ki, siz farkında olmadan onu kurt kapar.»"},{"n":14,"t":"Üvey kardeşler dediler ki; «Bu kadar çok kişi olmamıza rağmen eğer onu kurt kaparsa yandık demektir.»"},{"n":15,"t":"Kardeşleri Yusuf’u kıra götürüp onu bir kuyunun dibine atmayı kararlaştırdıklarında, kendisine «İlerde, hiç beklemedikleri bir sırada, sana yaptıkları bu işi kardeşlerine hatırlatacaksın» diye vahyettik."},{"n":16,"t":"Akşam olunca ağlayarak babalarına geldiler."},{"n":17,"t":"Dediler ki; «Ey babamız, Yusuf’u eşyalarımızın yanında bırakarak yarış yapmaya gitmiştik, o sırada onu kurt kapıverdi; her ne kadar söylediğimiz doğru ise de, bize inanmayacaksın.»"},{"n":18,"t":"Yusuf’un yalandan kana bulanmış gömleğini getirdiler. Babaları Yakub dedi ki; «Anlaşılan nefsiniz sizi kötü bir işe sürükledi, bana düşen yaman bir sabırdır, anlattıklarınız karşısında Allah’ın yardımına sığınıyorum.»"},{"n":19,"t":"Bir kervan geldi, sucularını su almaya gönderdiler. Adam kovasını kuyuya sarkıtınca «Müjde, işte size bir oğlan çocuğu» dedi. Kervandakiler onu satmak üzere sakladılar. Oysa Allah ne yaptıklarını biliyordu."},{"n":20,"t":"Yusuf’u ucuz bir fiyatla, birkaç paraya sattılar. Çünkü onu bir an önce ellerinden çıkarmak istiyorlardı."},{"n":21,"t":"Onu satın alan Mısırlı, karısına «Bu çocuğa iyi bak, ilerde işimize yarayabilir, belki de onu evlâd ediniriz» dedi. Böylece Yusuf’a güvenli bir barınak sağladık, ona olayların (ya da rüyaların) yorumuna ilişkin bazı bilgiler öğrettik. Allah, meramını kesinlikle yürütür. Fakat insanların çoğu bunu bilmezler."},{"n":22,"t":"Yusuf ergenlik çağına erince kendisine hikmet ve bilgi bağışladık. Biz iyi davranışlıları işte böyle ödüllendiririz."},{"n":23,"t":"Kaldığı evin hanımı onu yatağına çağırdı, kapıları kilitledikten sonra ona «Haydi, gelsene!» dedi. Fakat Yusuf, «Allah korusun! Rabbim bana güvenli bir barınak sağladı; hiç kuşkusuz zalimler iflah olmazlar, kurtuluşa eremezler» dedi."},{"n":24,"t":"Kadının canı Yusuf’u istedi, Yusuf da ona karşı ilgi duydu. Eğer Rabbinin caydırıcı direktifi, gözlerinin önünde somutlaşmasaydı, kendini tutamazdı. Böylece biz Yusuf u kötülükten ve fuhuştan uzak tuttuk. O, hiç kuşkusuz, bize içten bağlı, seçkin bir kulumuzdu."},{"n":25,"t":"Her ikisi de -Yusuf önde, kadın peşinde olmak üzere- kapıya koştular. Kadın, Yusuf’un gömleğini arkasından yırttı; kapıda kadının kocası ile karşılaştılar. O sırada kadın, kocasına «Eşine kötülük etmek isteyenin cezası herhalde hâpsedilmekten ya da ağır işkenceye çarpılmaktan başka bir şey olamaz» dedi."},{"n":26,"t":"Yusuf «Beni yatağına çağıran odur» dedi. Kadının akrabalarından biri olaya ilişkin şöyle bir çözüm önerdi, «Eğer Yusuf’un gömleği ön tarafından yırtılmış ise, kadın doğru söylüyor, Yusuf ise bir yalancıdır.»"},{"n":27,"t":"Yok, eğer Yusuf’un gömleği arka tarafından yırtılmış ise, kadın yalan söylüyor ve Yusuf’un dediği doğrudur."},{"n":28,"t":"Adam, gömleğin arka tarafından yırtılmış olduğunu görünce karısına «Bu iş, siz kadınlara özgü bir komplodur, sizin komplolarınız yamandır» dedi."},{"n":29,"t":"Adam, Yusuf’a «Sen ona bakma, kapat bu olayı» dedikten sonra karısına dönerek «Sen de günahından ötürü af dile, çünkü sen bir günahkârsın» dedi."},{"n":30,"t":"Şehirdeki birtakım kadınlar «Başbakanın karısı, kölesini yatağına çağırmış; delikanlının aşkı iliklerine işlemiş; anlaşılan (gördüğümüz o ki), iyice sapıtmış» dediler."},{"n":31,"t":"Kadın, hemcinslerinin bu kınayıcı dedikodularını duyunca haber salarak onları evine çağırdı, onlar için konforlu sedirler hazırladı, herbirinin eline birer yemek bıçağı verdi ve Yusuf’a «Çık şunların önüne» dedi. Kadınlar Yusuf’u görünce güzelliği karşısında büyülendiler ve «Allah’ım, sen ne büyüksün! Bu bir insan değil, olsa olsa saygın bir melektir» dediler."},{"n":32,"t":"Kadın dedi ki; «İşte siz beni bu delikanlı yüzünden kınadınız. Ben onu yatağıma çağırdım, fakat aşırı bir namusluluk tepkisi ile isteğimi reddetti. Ama kendisine emrettiğim işi yapmaz ise, kesinlikle hapse atılarak burnu yere sürtülecektir.»"},{"n":33,"t":"Yusuf dedi ki; «Ya Rabbi bana göre hapse girmek bunların benden istediklerini yapmamdan daha iyidir. Eğer beni onların komplolarından uzak tutmazsan ağlarına düşer, böylece cahillerden biri olurum.’’"},{"n":34,"t":"Allah, onun bu duasını kabul ederek kendisini kadınlardan uzak tuttu. Hiç kuşkusuz O her şeyi işitir, her şeyi bilir."},{"n":35,"t":"Sonra adamlar, Yusuf’u belirli bir süre için hapse atmayı gerekli gördüler. Oysa onun masum olduğunu kanıtlayan bunca delil gözleri önünde duruyordu."},{"n":36,"t":"İki genç, onunla birlikte hapse girmişlerdi. Bunlardan biri «Ben rüyamda şaraplık üzüm sıktığımı gördüm» dedi. Öbürü de dedi ki; «Rüyamda başımın üzerinde bir somun ekmek taşıdığımı gördüm, onu kuşlar yiyorlardı. Bu rüyalarımızın ne anlama geldiklerini bize anlat. Çünkü biz senin iyiliksever bir adam olduğunu görüyoruz.»"},{"n":37,"t":"Yusuf dedi ki; «Payınıza ayrılan yemek, henüz önünüze gelmeden önce onun ne olduğunu size bildirebilirim. Bu önsezi bana Allah’ın öğrettiği bilgilerdendir. Ben Allah’a inanmayan ve ahireti inkâr eden milletin dininden çıktım.»"},{"n":38,"t":"Onun yerine atalarım İbrahim’in, İshak’ın ve Yakub’un dinlerine bağlandım. Allah’a herhangi bir şeyi ortak koşmak bize yakışmaz. Bu inanç Allah’ın, gerek bize ve gerekse tüm insanlara yönelik bir lütfudur. Fakat insanların çoğu Allah’a şükretmezler."},{"n":39,"t":"Ey hapishane arkadaşlarım, çok sayıda ilaha inanmak mı, yoksa ezici iradeli tek Allah’a inanmak mı daha iyidir?"},{"n":40,"t":"Allah’ı bir yana bırakarak taptığınız düzmece ilahlar, ya sizin ya da atalarınızın taktığı birtakım boş, içeriksiz adlardan başka bir şey değildirler. Allah onlara hiçbir güç vermiş değildir. Egemenlik sadece Allah’ın tekelindedir. O yalnız kendisine kulluk sunmanızı emretmiştir. Dosdoğru din, işte budur. Fakat insanların çoğu bu gerçeği bilmiyor."},{"n":41,"t":"Ey hapishane arkadaşlarım, rüyalarınızın yorumuna gelince biriniz eskisi gibi efendisine içki sunacak, öbürünüz ise idam edilecek ve başını kuşlar kemirecek. Benden yorumlamamı istediğiniz rüyalara ilişkin hüküm bu şekilde kesinleşti."},{"n":42,"t":"Yusuf, kurtulacağını tahmin ettiği arkadaşına «Efendinin yanında benden söz et» dedi. Fakat şeytan, efendisine Yusuf’tan sözetmeyi adama unutturdu; bu yüzden Yusuf, daha birkaç yıl hapiste kaldı."},{"n":43,"t":"Bir gün kral dedi ki; «Ben rüyamda yedi zayıf ineğin yedi semiz ineği yediğini, ayrıca yedi yeşil ve bir o kadar da kuru başak gördüm. Efendiler, eğer rüya yorumlamayı biliyorsanız, bu rüyamın ne anlama geldiğini bana söyleyiniz.»"},{"n":44,"t":"Kralın adamları dediler ki; «Bu gördükleriniz birtakım karmaşık, birbirinden kopuk hayallerdir. Biz karmaşık hayallerin yorumunu bilemeyiz.»"},{"n":45,"t":"Yusuf’un hapishaneden kurtulan ve kendisini ancak uzun bir süre sonra hatırlayan arkadaşı krala «Ben bu rüyanın ne anlama geldiğini sizin için öğrenirim, yalnız bana izin verin de bir yere kadar gideyim» dedi."},{"n":46,"t":"Hapishaneye varınca dedi ki; «Ey özü sözü dosdoğru Yusuf, yedi zayıf ineğin yediği yedi semiz ineğe ve yedi yeşil başak ile bir o kadar sayıdaki kuru başağa ilişkin ne anlama geldiğini bize anlat ki, ben de adamların yanına döneyim de öğrensinler.»"},{"n":47,"t":"Yusuf dedi ki; «Yedi yıl boyunca topraklarınızı nadasa bırakmaksızın ekip biçersiniz. Elde edeceğiniz ürünü, yiyecek olarak ayıracağınız az bir bölümü dışında başak halinde saklayınız."},{"n":48,"t":"Bunun arkasından yedi kurak ve sıkıntılı yıl gelir. Bu süre içinde, ayıracağınız az miktardaki tohumluklar dışında, bu yıllar için stok ettiğiniz ürünü yersiniz."},{"n":49,"t":"Bunun arkasından da halkın bol yağmura kavuşacağı, üzümlerini ve zeytinlerini sıkıp şıra ve yağ elde edebilecekleri bereketli bir yıl gelir.»"},{"n":50,"t":"Kral «O adamı bana getiriniz» dedi. Yusuf, yanına gelen kralın elçisine dedi ki; «Efendinin yanına dön ve ellerini yemek bıçakları ile kesen kadınlara ilişkin olayın içyüzünü kendisine sor. Gerçi Rabbim, o kadınların bana kurdukları tuzağı iyi bilir.»"},{"n":51,"t":"Kral, kadınlara «Yusuf’tan yatak yoldaşınız olmasını istediğinizde neler oldu?» dedi. Kadınlar «Haşa Allah’a! O’nun hiçbir kötü davranışını görmedik» dediler. Bunun üzerine başbakanın eşi dedi ki; «Şimdi gerçek meydana çıktı, Yusuf’u yatağıma ben çağırmıştım, onun söylediği doğrudur.»"},{"n":52,"t":"Böylece Yusuf bilsin ki, ona yokluğunda kalleşlik etmedim ve Allah, kalleşlerin kurdukları tuzakları başarıya erdirmez."},{"n":53,"t":"Bununla birlikte nefsimi aklamak, onu masum göstermek istemiyorum. Çünkü Rabbimin rahmeti ile korudukları dışındaki tüm nefisler, insanı ısrarla kötülüğe kışkırtırlar. Hiç şüphesiz Rabbim affedicidir, merhametlidir."},{"n":54,"t":"Kral «Getirin o adamı bana, onu yakın çevreme alayım» dedi. Yusuf ile konuşunca da ona «Bugün sen artık bizim yüksek mevkili ve güvenilir bir adamımızsın» dedi."},{"n":55,"t":"Yusuf, krala «Beni ülkenin hazinelerini yönetmekle görevlendir. Çünkü ben hazinelerinizi titizlikle korurum ve onların nasıl yönetileceğini iyi bilirim."},{"n":56,"t":"Böylece Yusuf’un o ülkedeki konumunu sağlamlaştırdık, artık o ülkenin dilediği yerinde oturabilirdi. Biz rahmetimizi dilediğimiz kimselere sunarız ve iyi davranışlıları ödülsüz bırakmayız."},{"n":57,"t":"Ama iman edip kötülükten sakınanlar için ahiret ödülü daha hayırlıdır."},{"n":58,"t":"Bir gün Yusuf’un kardeşleri gelip yanına girdiler. Yusuf onları hemen tanıdı, fakat onlar onu tanımamışlardı."},{"n":59,"t":"Yusuf, kardeşlerinin zahire yüklerini hazırlatınca onlara dedi ki; «Babadan kardeşinizi bana getiriniz. Görüyorsunuz ya, zahirenizi tastamam ölçerek veriyorum ve konukseverlerin de en iyisiyim.»"},{"n":60,"t":"Ama eğer babadan kardeşinizi bana getirmezseniz, artık size erzak yok, bir daha semtime yaklaşmayınız."},{"n":61,"t":"Yusuf’un kardeşleri «Babasından onun için izin koparmaya çalışacağız, herhalde bunu başarırız» dediler."},{"n":62,"t":"Yusuf yanında çalışan işçilere dedi ki; «Bunların verdikleri zahire bedelini yüklerine koyunuz, evlerine varınca herhalde onu farkederler de bir daha gelirler.»"},{"n":63,"t":"Yusuf’un kardeşleri babalarının yanına dönünce dediler ki; «Ey babamız, erzak almamız yasaklandı, kardeşimizi bizimle birlikte gönder ki, erzak alabilelim, biz onu kesinlikle koruruz.»"},{"n":64,"t":"Babaları Yakub dedi ki; «Daha önce kardeşi konusunda size duyduğum güvenin aynısını şimdi de onun hakkında mı size duyayım? En iyi koruyucu Allah’dır. O merhametlilerin merhametlisidir.»"},{"n":65,"t":"Zahire yüklerini açıp da ödemiş oldukları bedelin kendilerine geri verildiğini gördüklerinde dediler ki; «Ey babamız, senden yanlış birşey istemiyoruz. İşte ödemiş olduğumuz bedel bize geri verilmiş. Ailemize erzak getiririz, kardeşimizi koruruz, böylece bir deve yükü daha fazla zahiremiz olur. Bunu sağlamak kolay bir iştir artık.»"},{"n":66,"t":"Babaları «Hep birlikte ölüm çemberine düşmeniz ihtimali dışında, onu kesinlikle geri getireceğinize ilişkin bana Allah adına sağlam bir güvence, bağlayıcı bir söz vermedikçe onu sizinle birlikte göndermem» dedi. Oğullarının istediği güvenceyi vermeleri üzerine dedi ki; «Bu söylediklerimize Allah vekildir.»"},{"n":67,"t":"Yavrularım, şehre aynı kapıdan girmeyiniz, değişik kapılardan giriniz. Gerçi ben Allah’ın size ilişkin hiçbir ön kararını başınızdan savamam. Egemenlik sadece Allah’ın tekelindedir. Ben yalnız O’na güveniyorum. Tüm dayanak arayanlar da yalnız O’na güvenmelidirler."},{"n":68,"t":"Yusuf’un kardeşleri babalarının direktifi uyarınca şehre girdiler. Gerçi bu önlem, Allah’ın onlara ilişkin hiçbir ön kararını başlarından savacak değildi. Sadece Yakub, içinden gelen bir görev duygusunun gereğini yerine getirmişti. Onun bu meseleye ilişkin, tarafımızdan kendisine öğretilmiş bilgisi vardı. Fakat insanların çoğu bu meseleye ilişkin gerçeği bilmezler."},{"n":69,"t":"Yakub’un oğulları, Yusuf’un yanına girdiklerinde o öz kardeşini bağrına basarak «Ben senin öz kardeşinim, onların yaptıkları kötülüklerden ötürü sakın tasalanma» dedi."},{"n":70,"t":"«Ey yolcular kafilesi, sizler hırsızsınız» diye seslendi."},{"n":71,"t":"Yusuf’un kardeşleri, görevlilere dönerek «Ne kaybettiniz?» dediler."},{"n":72,"t":"Görevlilerden biri dedi ki; «Ölçü kabı olarak kullanılan kralın su tasını kaybettik. Onu geri getirene ödül olarak bir deve yükü zahire verilecek buna ben kefilim.»"},{"n":73,"t":"Yusuf’un kardeşleri «Allah aşkına, siz de biliyorsunuz ki, biz bu ülkeye kargaşa çıkarmak için gelmedik, biz hırsız değiliz» dediler."},{"n":74,"t":"Görevliler; «Peki eğer yalan söylüyorsanız, size göre hırsızlığın cezası nedir?» dediler."},{"n":75,"t":"Yusuf’un kardeşleri «Hırsızlığın cezası, tası yükünde bulduğunuz kimsenin karşılık olarak tutulmasıdır. Biz zalimleri böyle cezalandırırız» dediler."},{"n":76,"t":"Yusuf, öz kardeşinin valizinden önce üvey kardeşlerinin valizlerini aradı, sonra tası öz kardeşinin valizinden çıkardı. Biz Yusuf’a böyle bir plana başvurmayı ilham ettik. Çünkü kralın yasalarına göre kardeşini alıkoyamazdı. Meğer ki, Allah bu alıkonmayı dilemiş olsun. Biz dilediğimiz kimsenin derecelerini yükseltiriz. Her bilenden daha üstün bir bilgin vardır."},{"n":77,"t":"Yakub’un oğulları; «Bu kardeşimiz hırsızlık yaptı ise daha önce de onun öz kardeşi hırsızlık yapmıştı» dediler. Yusuf kardeşlerinin bu iftirasını duymazlıktan geldi, onu yüzlerine vurmadı. İçinden «Asıl kötü durumda olan sizlersiniz, Allah sizin uydurma sözlerinizin içyüzünü herkesten iyi bilir» dedi."},{"n":78,"t":"Yakub’un oğulları dediler ki; «Ey vezir, bu kardeşimizin ileri derecede yaşlanmış, ihtiyar bir babası var. Onun yerine içimizden birini alıkoy. Görüyoruz ki, sen iyiliksever bir adamsın.»"},{"n":79,"t":"Yusuf «Çalınan eşyamızı valizinde bulduğumuz kimseden başkasını alıkoymaktan Allah’a sığınırız. Yoksa zalimlik etmiş oluruz» dedi."},{"n":80,"t":"Yakub’un oğulları Yusuf’tan umut kesince, aralarında konuşmak üzere bir kenara çekildiler. En büyükleri dedi ki; «Babanızın Allah adına sizden bağlayıcı bir güvence aldığını ve daha önceki Yusuf’a ilişkin ihmalinizi bilmiyor musunuz? Bu yüzden babam bana izin vermedikçe ya da hüküm verenlerin en hayırlısı olan Allah, hakkımda bir hüküm vermedikçe buradan ileriye adım atmam!»"},{"n":81,"t":"Varınız babanıza deyiniz ki; ’Ey babamız! Oğlun hırsızlık yaptı, biz sadece bildiklerimizi söylüyoruz, yoksa bilinmez sırlara ilişkin bir haberimiz yoktur!"},{"n":82,"t":"İçinde bulunduğumuz şehrin halkına ve birlikte yola çıktığımız kervana sor, söylediklerimiz kesinlikle doğrudur."},{"n":83,"t":"Hz. Yakub dedi ki; ’Herhalde nefsinizin kışkırtması ile bir komplo düzenlediniz. Bana yaman bir sabır düşüyor. Belki de Allah bana tüm oğullarımı birlikte kavuşturacaktır. Hiç şüphesiz O, her şeyi bilir ve her yaptığı yerindedir.»"},{"n":84,"t":"Hz. Yakub, yüzünü başka tarafa çevirerek; ’Vah Yusuf’um vah!’ diye inledi. Gözleri hüzünden ağarmıştı, buna rağmen acısını içine gömüyor, belli etmiyordu."},{"n":85,"t":"Oğulları; «Vallahi, Yusuf Yusuf diye diye ya yatağa düşeceksin, ya da helâk olacaksın» dediler..."},{"n":86,"t":"Hz. Yakub, oğullarına dedi ki; «Ben acımı ve ızdırabımı yalnız Allah’a şikayet ediyorum ve ben Allah hakkında sizin bilmediklerinizi biliyorum.»"},{"n":87,"t":"Ey yavrularım! Haydi gidin, Yusuf ile kardeşi hakkında haber elde etmeye çalışın! Allah’ın rahmetinden de umut kesmeyin! Şu bir gerçek ki, Allah’ın kuşatıcı ve kurtarıcı rahmetinden yalnızca kafirler güruhu umut keser."},{"n":88,"t":"Yakub’un oğulları, Yusuf’un yanına girdiklerinde dediler ki; ’Ey vezir, biz ve ailemiz sıkıntıya düştük, yanımızda düşük değerli bir bedel getirdik, fakat sen erzağımızı eksiltmeden ver, bize bağışta bulun. Çünkü Allah hayırseverleri ödüllendirir...»"},{"n":89,"t":"Hz. Yusuf kardeşlerine; «Cahillik döneminde Yusuf’a ve kardeşine neler yaptığınızı hatırlıyor musunuz?» dedi."},{"n":90,"t":"Kardeşleri «Yoksa sen Yusuf musun?» dediler. O da dedi ki; «Evet, ben Yusuf’um, bu da kardeşimdir. Allah bize lütufta bulundu. Kuşku yok ki, kim kötülükten sakınır ve sabrederse, Allah iyilik edenleri asla ödülsüz bırakmaz.»"},{"n":91,"t":"Kardeşleri; «Vallahi, Allah seni bize üstün kıldı, biz hep suçlu idik.» dediler..."},{"n":92,"t":"Yusuf dedi ki; «Bugün size kınama yok, Allah günahlarınızı bağışlar, O merhametlilerin en merhametlisidir.»"},{"n":93,"t":"Şimdi şu benim gömleğimi götürüp yüzüne sürün de gözleri açılsın. Sonra bütün ailenizle birlikte bana geliniz."},{"n":94,"t":"Kafile Mısır’dan henüz ayrılmıştı ki, babaları ’Yusuf’un kokusunu alıyorum,’ dedi. ’Tabii beni bunaklıkla suçlamazsanız.’"},{"n":95,"t":"Yanındakiler, Hz. Yakub’a; «Vallahi, sen halâ o eski şaşkınlığının pençesindesin» dediler.."},{"n":96,"t":"Hz. Yakub’un müjdeli haberi taşıyan oğlu gelip de gömleği babasının yüzüne sürünce, gözleri açılıverdi ve oğullarına «ben size Allah hakkında sizin bilmediklerinizi biliyorum demedim mi?» dedi."},{"n":97,"t":"Oğulları; «Ey babamız! Bizim adımıza Allah’tan günahlarımızı affetmesini dile, biz kesinlikle suçluyuz» dediler."},{"n":98,"t":"Hz. Yakub, oğullarına; «Sizin için daha sonra af dileyeceğim. Hiç kuşkusuz Allah affedicidir, merhametlidir» dedi."},{"n":99,"t":"Hz. Yakub ailesi, Hz. Yusuf’un yanına vardığında O, ana babasını bağrına bastı ve «Allah’ın izni ile Mısır’a güven içinde giriniz» dedi."},{"n":100,"t":"Ana babasını makam koltuğuna oturttu, bu arada hep birlikte önünde secdeye kapandılar. Bunun üzerine Hz. Yusuf, babasına dedi ki; «Babacığım, bu olay, bir zamanlar gördüğüm rüyanın somut yorumudur, Rabbim o rüyayı gerçeğe dönüştürdü. Ayrıca beni hapisten çıkararak ve şeytanın kışkırtması sonucunda kardeşlerimle aramın açılmasından sonra sizleri çöl ortasından kaldırıp yanıma getirerek bana lütufta bulundu. Hiç kuşkusuz Rabbim dilediklerine karşı lütufkâr davranır. O her şeyi bilen ve her yaptığını yerinde yapandır.»"},{"n":101,"t":"Rabbim, sen bana egemenlikten pay verdin, beni olayları (ya da rüyaları) yorumlamaya ilişkin bazı bilgiler ile donattın. Ey göklerin ve yerin yaradanı! Gerek dünyada, gerek ahirette tek dayanağım sensin; canımı müslüman olarak al ve beni iyi kulların arasına kat.»"},{"n":102,"t":"Ey Muhammed! Bu anlatılanlar, gayba ilişkin haberlerdir, onları sana vahiy yolu ile bildiriyoruz. Yoksa Hz. Yakub’un oğulları, biraraya gelerek kardeşlerinin tuzak kurmayı kararlaştırdıkları sırada sen yanlarında değildin."},{"n":103,"t":"Sen insanların iman etmesini ne kadar ısrarla istersen iste, onların çoğu iman etmeyecektir."},{"n":104,"t":"Oysa sen bu çabana karşılık onlardan herhangi bir ücret istemiyorsun. Kur’an, tüm insanlara seslenen bir hatırlatmadır sadece."},{"n":105,"t":"Göklerde ve yerde nice ayetler, nice ibret içerikli belgeler vardır, yanlarından geçtikleri halde onları umursamazlar."},{"n":106,"t":"Onların çoğu, Allah’a ortak koşmaksızın O’na inanmazlar."},{"n":107,"t":"Acaba onlar, hepsini birlikte çarpacak, yaygın bir ilahi azaba uğramayacaklarından ya da hiç farkında olmadıkları bir sırada ansızın kıyametin başlarına kopmayacağından emin midirler?"},{"n":108,"t":"Ey Muhammed, de ki; «İşte benim yolum budur, ben inandırıcı kanıtlar göstererek insanları Allah’a çağırırım. Bana uyanlar da öyle yaparlar. Allah’ı her türlü noksanlıktan uzak tutarım. Ben Allah’a ortak koşanlardan değilim.»"},{"n":109,"t":"Senden önce gönderdiğimiz tüm peygamberler de, çeşitli şehirlerin halklarından seçerek kendilerine vahiy indirdiğimiz erkekler idi. Onlar yeryüzünde gezerek; kendilerinden önceki inkârcı milletlerin sonunun nasıl olduğunu görmüyorlar mı? Kötülükten kaçınanlar için ahiret yurdu, dünyadan daha hayırlıdır. Bunu düşünemiyor musunuz?"},{"n":110,"t":"Gönderdiğimiz peygamberler, ümmetlerinden iyice ümit kestiklerinde ve kesinlikle yalancı sayıldıkları sonucuna vardıklarında, kendilerine yardımımız erişiverdi de dilediklerimiz ortak azaptan kurtarıldı, fakat hiç kimse ağır suçlulardan şiddetli azabımızı savamaz."},{"n":111,"t":"Sağduyuluların, peygamberlere ilişkin hikâyelerden alacakları ibret dersleri vardır. Bu Kur’an bir düzmece sözler dizisi değildir. Tersine O, kendisinden önceki kutsal kitapları onaylayan, her şeyi ayrıntılı biçimde anlatan, mü’minler için doğru yol kılavuzu ve rahmet olan gerçek bir ilahi kitaptır."}],[{"n":1,"t":"Elif Lâm Mîm Râ. Bunlar kitabın ayetleridir. Rabbinden sana indirilen mesaj gerçektir, fakat insanların çoğu buna inanmazlar."},{"n":2,"t":"Allah gökleri, gördüğünüz gibi, direksiz olarak yükseltti. Sonra Arş’a kuruldu, güneş ile ayı buyruğu altına aldı, her biri belli bir sürenin sonuna kadar yörüngesinde hareket eder, o bütün bu gelişmeleri düzenler. Rabbinizin karşısına çıkacağınıza kesinlikle inanasınız diye O, size ayetlerini ayrıntılı biçimde açıklar.."},{"n":3,"t":"O yerin alanını geniş yaptı; orada köklü dağlar ve nehirler varetti; bütün ürünleri, bütün bitkileri çift olarak yarattı; O geceyi gündüzün üzerine örter. Hiç kuşkusuz bunlar da düşünen kimseler için ibret dersleri vardır."},{"n":4,"t":"Yeryüzünde biribirine bitişik, farklı yapıda toprak parçaları; üzüm bağları, ekinler ve çatallı çatalsız hurma ağaçları vardır; hepsi aynı su ile sulanır, fakat ürünleri arasında fark gözetiriz. Hiç kuşkusuz bunlarda aklı erenler için birçok ibret dersleri vardır."},{"n":5,"t":"Eğer şaşacaksan, kâfirlerin ’Biz ölüp toprak olunca mı yeniden diriltileceğiz?’ demelerine şaşmak gerekir. Onlar Rabb’lerini inkâr edenlerdir, onların boyunlarına demir halkalar geçirilecektir; onlar, orada ebedi olarak kalmak üzere, cehennemliktirler."},{"n":6,"t":"Müşrikler senden iyilikten önce kötülük isterler, çarptırılacakları cezanın bir an önce başlarına gelmesini dilerler. Oysa onlardan önce nice ağır ceza örnekleri yaşanmıştır. Hiç kuşkusuz Rabb’in, insanların zalimliklerine rağmen onlara karşı bağışlayıcıdır ve yine hiç kuşkusuz Rabbinin cezası da pek ağırdır."},{"n":7,"t":"Kâfirler «Muhammed’e, Rabb’inden bir mucize indirilseydi ya» derler. Oysa sen sadece bir uyarıcısın ve her toplumun bir doğru yol göstericisi vardır."},{"n":8,"t":"Allah, her dişinin rahminde taşıdığını, bu rahimlerin erken doğurdukları ile fazla tuttuklarını bilir. Her şey O’nun katında belirli bir ölçüye bağlıdır."},{"n":9,"t":"O, görülür görülmez, her şeyi bilen, yüceler yücesidir."},{"n":10,"t":"İçinizden sözünü gizli tutanla açıkça söyleyen, geceye bürünüp saklanan ile gündüzleyin ortalıkta gezen arasında O’nun için hiçbir fark yoktur."},{"n":11,"t":"İnsanı önünden ve arkasından izleyen (melekler) vardır, onu Allah’ın emri ile gözetlerler. Herhangi bir toplum tutumunu değiştirmedikçe Allah onun konumunu değiştirmez. Allah, bir toplumun herhangi bir kötülüğe uğramasını dileyince, onu hiç kimse önleyemez. İnsanların Allah’dan başka hiçbir koruyucusu, kayırıcısı yoktur."},{"n":12,"t":"Şimşeği size hem korku ve hem de umut kaynağı olarak gösteren, yağmur yüklü bulutları oluşturan odur."},{"n":13,"t":"O’nu gök gürültüsü övgü ile ve melekler korku içinde tesbih ederler, noksanlıklardan uzak tutarlar. O yıldırımlar salarak bunlarla dilediklerini çarpar. Allah’ın sillesi son derece sert olduğu halde, onlar O’nun hakkında tartışıyorlar."},{"n":14,"t":"Gerçek dua, yalnız Allah’a yöneltilen çağrıdır. Müşriklerin Allah dışında çağrı yönelttikleri putlar, onların hiçbir dileklerine cevap veremezler. Böyleleri ağzına su gelsin diye avuçlarını ona doğru açan kimseye benzerler ki, asla bu yolla ağzına su gelmez. İşte kâfirlerin çağrısı böylesine boşunadır."},{"n":15,"t":"Göklerdeki ve yerdeki tüm varlıklar ile bu varlıkların gölgeleri gönüllü ya da zorunlu olarak sabah akşam Allah’a secde ederler."},{"n":16,"t":"\"Her şeyi yaratan Allah’tır. O, bir tektir, her şeye üstün gelir.\""},{"n":17,"t":"Allah, gökten su indirdi ve yataklarının kapasitesi ile ölçülü büyüklükte dereler akıttı. Akan sel, yüzeyinde köpük taşır. Süs ya da kullanım eşyası yapmak amacı ile ateşte erittiğiniz madenlerin de buna benzer köpükleri, cürufları vardır. Allah, hak ile batılı bu örnek aracılığı ile anlatır. Köpük, havaya uçup gider; fakat insanlara yarar sağlayan kısım yerde kalır. İşte Allah, böylesine örnekler verir."},{"n":18,"t":"Rabblerinin çağrısına olumlu cevap verenlere karşılıkların en güzeli verilir. O’nun çağrısına olumlu karşılık vermeyenlere gelince, eğer dünyada bulunan her şey, bir kat fazlası ile ellerinde olsa, bütün bunları kurtuluş fidyesi olarak verirlerdi. Böylelerini kötü bir hesaplaşma işlemi bekliyor, varacakları yer cehennemdir; orası ne fena bir barınaktır!"},{"n":19,"t":"Rabbin tarafından sana indirilen mesajın gerçek olduğunu bilen kimse hiç kör ile bir olur mu? Ancak sağduyu sahipleri öğüt alırlar."},{"n":20,"t":"Onlar Allah’a verdikleri sözü tutarlar, anlaşmalarını bozmazlar."},{"n":21,"t":"Yine onlar, Allah’ın sürdürülmesini emrettiği ilişkileri sürdürürler. Rabblerinden korkarlar ve kötü hesaplaşmadan ürkerler."},{"n":22,"t":"Yine onlar, Allah’ın hoşnutluğunu kazanmak amacı ile sabrederler, namazı kılarlar, kendilerine verdiğimiz rızıktan gizlice ve açıkça hayır yolunda harcarlar, kötülüğü iyilikle savarlar. İşte geçici dünyanın ardından gelecek olan mutlu akıbet onları bekliyor."},{"n":23,"t":"Bu mutlu akıbet, Adn cennetleridir. Kendileri ile birlikte iyi davranışlı ana babaları, eşleri ve çocukları bu cennetlere girerler. Melekler her kapıdan yanlarına girerek;"},{"n":24,"t":"Sabrettiğinizden dolayı selâm size. Dünyayı izleyen bu mutlu akıbet ne kadar güzel! derler."},{"n":25,"t":"Allah’a vermiş oldukları sözü kesin bir taahhüt haline getirdikten sonra bozanlara, Allah’ın sürdürülmesini emrettiği ilişkileri kesenlere ve yeryüzünde bozgunculuk çıkaranlara gelince onlara lânet vardır ve dünyayı izleyecek olan kötü akıbet kendilerini beklemektedir."},{"n":26,"t":"Allah dilediğine bol rızık verir ve dilediğinin rızkını kısıtlar. Onlar dünya hayatı ile böbürlendiler. Oysa dünya hayatı, ahiretin yanında basit bir metadan başka bir şey değildir."},{"n":27,"t":"Kâfirler «Muhammed’e, Rabbi tarafından somut bir mucize, indirilseydi ya» derler. Onlara de ki; «Allah, dilediğini saptırır ve kendisine yöneleni doğru yola iletir.»"},{"n":28,"t":"Onlar iman etmişlerdir ve kalpleri Allah’ı anmakla huzura kavuşur. Haberiniz olsun ki, kalpler ancak Allah’ı anmakla huzura erebilirler."},{"n":29,"t":"İman edip iyi ameller işleyenlere ne mutlu, onları güzel bir gelecek beklemektedir."},{"n":30,"t":"Ey Muhammed sana vahyettiğimiz mesajı kendilerine okuyasın diye seni öyle bir ümmete gönderdik ki, onlardan önce birçok ümmetler gelip geçmiştir. Onlar rahmeti bol olan Allah’ı tanımıyorlar. Onlara de ki; «Benim Rabbim O’dur, O’ndan başka ilah yoktur, ben yalnız O’na dayandım, dönüş O’nadır.»"},{"n":31,"t":"Eğer dağların yürümesini, yeryüzünün parçalanmasını ve ölüler ile konuşabilmeyi sağlayan bir kitap olsaydı, o bu Kur’an olurdu. Fakat tüm yetki Allah’ın tekelindedir. Dilese, Allah’ın bütün insanları doğru yola ileteceğini, mü’minler halâ kesinlikle anlamadılar mı? İşledikleri kötülükler yüzünden kâfirlerin başlarına sürekli olarak belâlar gelir, ya da bu belâlar yurtlarının yakınına iner. Sonunda Allah’ın verdiği söz gerçekleşir. Kuşku yok ki, Allah sözünden caymaz."},{"n":32,"t":"Senden önceki birçok peygamber ile de alay etmişlerdi. Ben o kâfirlere bir süre meydan verdim, fakat sonra yakalarına yapıştım. O zaman azabım nice oldu?"},{"n":33,"t":"Herkesin ne yaptığını gözeten Allah, böyle bir gücü olmayan düzmece ilâhlar ile bir olur mu? Müşrikler, Allah’a birtakım ortaklar koştular. Onlara de ki; «bunların adlarını söyleyiniz, niteliklerini belirtiniz. Yoksa Allah’a, O’nun yeryüzünde bilmediği bir şeyin haberini mi veriyorsunuz? Yoksa kuru sözler ile mi oyalanıyorsunuz? Aslında kâfirlere entrikaları, düzenbazlıkları çekici göründü de doğru yoldan saptırıldılar. Allah’ın saptırdığını hiç kimse doğru yola iletemez."},{"n":34,"t":"Onlara dünya hayatında azap vardır. Fakat ahiret azabı daha ağırdır. Onları Allah’ın elinden hiç kimse kurtaramaz."},{"n":35,"t":"Kötülüklerden sakınanlara vadedilen cennet şöyledir. Oranın altından çeşitli ırmaklar akar, ağaçlarının meyvaları süreklidir, gölgeleri de. İşte kötülüklerden sakınanların sonu burasıdır. Kâfirlerin sonu ise cehennem ateşidir."},{"n":36,"t":"Kendilerine kitap gönderdiğimiz kimseler, sana indirilen mesajı sevinçle karşılarlar. Fakat karşıt gruplar içinde bu mesajın bir bölümünü inkâr edenler vardır. Onlara de ki; «Bana Allah’a kulluk etmem, O’na ortak koşmamam emredildi; O’na çağırırım insanları; O’nadır dönüşüm."},{"n":37,"t":"Bunun yanısıra biz onu Arapça bir hüküm sistemi olarak indirdik. Eğer sana gelen bu bilgiden sonra onların keyfi arzularına uyacak olursan, seni Allah’ın elinden kurtaracak bir destekçi, bir koruyucu bulamazsın."},{"n":38,"t":"Biz senden önce de nice peygamberler gönderdik, onlara da eşler ve çocuklar verdik. Allah’ın izni olmadıkça hiçbir peygamber mucize göstermeye yetkili değildir. Her belirli sürenin, her dönemin ayrı bir kitabı vardır."},{"n":39,"t":"Allah dilediği hükmü yürürlükten kaldırır, dilediğini de yürürlükte tutar. Ana kitap O’nun katındadır."},{"n":40,"t":"Kâfirlere yönelttiğimiz bazı tehditleri sana göstersek de ya da daha önce canını alsak da senin görevin mesajımızı duyurmaktır, insanları hesaba çekmek bize düşer."},{"n":41,"t":"Bizim kâfirlerin yurtlarını uçlarından kırptığımızı, müslümanlar lehine alanlarını daralttığımızı görmüyorlar mı? Hüküm veren Allah’tır, O’nun hükmünü gözden geçirecek hiç kimse yoktur. O’nun hesaplaşması pek çabuktur."},{"n":42,"t":"Onlardan öncekiler de peygamberlerine karşı tuzaklar kurdular. Fakat asıl tuzak kurma yetkisi Allah’ın tekelindedir. O herkesin ne yaptığını bilir. Kâfirler, kimin mutlu sona ereceğini ilerde öğreneceklerdir."},{"n":43,"t":"Kâfirler «Sen peygamber değilsin» derler. Onlara de ki; «Sizin ile benim aramda Allah’ın ve kutsal kitap kaynaklı bilginlerin tanıklığı yeterli bir kanıttır.»"}],[{"n":1,"t":"Elif, Lâm, Ra. Bu Kur’an, insanları Rabblerinin izni ile karanlıklardan aydınlığa çıkarasın, üstün iradeli ve övgüye lâyık Allah’ın yoluna iletesin diye sana indirilmiş bir kitaptır."},{"n":2,"t":"O Allah ki, göklerde ve yerde ne varsa hepsi O’nundur. Uğrayacakları ağır azaptan ötürü vaygele kâfirlerin başına!"},{"n":3,"t":"Onlar ki, dünya hayatını ahirete tercih ederler, insanları Allah yolundan alıkoyarlar ve bu yolu eğri göstermeye yeltenirler. İşte onlar koyu bir sapıklık içindedirler."},{"n":4,"t":"Biz bütün peygamberleri soydaşlarının dili ile gönderdik ki, onlara Allah’ın buyruğunu açıkça anlatabilsinler. Allah dilediğini saptırır, dilediğini de doğru yola iletir. O üstün iradelidir ve her işi yerindedir."},{"n":5,"t":"Biz Musa’yı «Soydaşlarını karanlıktan aydınlığa çıkar ve onlara Allah’ın (tarihlerinde iz bırakmış) günlerini hatırlat» direktifi ile somut mucizelerin desteğinde peygamber olarak gönderdik. Bu hatırlatmada sabırlı ve şükreden herkesin alacağı ibret dersleri vardır."},{"n":6,"t":"Hani Musa, soydaşlarına dedi ki; «Allah’ın size bağışladığı nimetleri hatırlayınız. Hani O oğullarınızı boğazlayıp kadınlarınızı erkeksiz bırakmak sureti ile size çok ağır bir işkence çektiren Firavun hanedanından sizi kurtarmıştı. Bu, Rabbinizin size yönelik büyük bir sınavı idi.»"},{"n":7,"t":"Hani Rabbiniz size şöyle bildirmişti; «Eğer şükrederseniz, size yönelik nimetlerimi kesinlikle arttırırım, eğer nankörlük ederseniz, hiç kuşkusuz azabım pek ağırdır.»"},{"n":8,"t":"Musa dedi ki; «Eğer siz, tüm yeryüzü halkı ile birlikte nankörlük etseniz, kuşku yok ki, Allah’ın hiçbir şeye ihtiyacı yoktur ve özü itibarı ile övgüye lâyıktır.»"},{"n":9,"t":"Daha önce yaşamış Nuh, Ad, Semud kavimlerine, ayrıca bunlardan sonra gelen ve haklarında Allah’dan başka hiç kimsenin bir şey bilmediği toplumlara ilişkin bilgi size ulaşmadı mı? Peygamberleri, bu toplumlara açık belgeler ile geldiler. Fakat onlar (sesleri yankılanarak gürleşsin diye) ellerini ağızlarına tutarak sizin bize getirdiğiniz mesajı reddediyoruz, bizi benimsemeye çağırdığınız ilkeler konusunda koyu bir kuşku içindeyiz» dediler."},{"n":10,"t":"Peygamberleri, onlara «Göklerin ve yerin yoktan varedicisi olan Allah hakkında şüphe olur mu hiç? O bazı günahlarınızı bağışlamak için sizi doğru yola çağırıyor, bu konuda size belirli bir sürenin sonuna kadar mühlet tanıyor» dediler."},{"n":11,"t":"Peygamberleri onlara dediler ki, «Evet biz de sizin gibi birer insanız, fakat Allah dilediği kuluna bağışta bulunur. Allah’ın izni olmadıkça biz size mucize gösteremeyiz. Mü’minler sırf Allah’a dayanmalıdır."},{"n":12,"t":"Allah bizi doğru yola ilettiğine göre, niye O’na dayanmayalım ki? Bize edeceğiniz eziyetlere kesinlikle katlanacağız. Dayanak arayanlar sırf Allah’a dayanmalıdırlar.»"},{"n":13,"t":"Kâfirler, peygamberlerine «Ya dinimize dönersiniz, ya da sizi yurdumuzdan kovarız» dediler. Fakat Rabbleri, onlara vahiy yolu ile bildirdi ki, «Biz zalimleri kesinlikle yokedeceğiz.»"},{"n":14,"t":"Ve onların arkasından yeryüzüne sizi yerleştireceğiz. Bu müjde benim karşıma çıkacağından çekinen ve benim tehditlerimden korkanlar içindir.»"},{"n":15,"t":"Peygamberler, Allah’dan zafer dilediler, bunun üzerine bütün inatçı zorbalar hüsrana uğradılar."},{"n":16,"t":"Ayrıca herbirinin önünde cehennem vardır, orada kendisine irinli su içirilecektir."},{"n":17,"t":"Bu irinli suyu yutkunarak içer, normal biçimde içemez. Her yandan ölümün saldırısına uğradığı halde ölemez. Önünde çetin bir azap vardır."},{"n":18,"t":"Rabblerini inkâr edenlerin iyi davranışları fırtınalı bir günde şiddetli rüzgârda savrulan küle benzer, yaptıkları iyi işler karşılığında ellerine hiçbir şey geçmez. İşte koyu sapıklık budur."},{"n":19,"t":"Allah’ın gökleri ve yeri hak ilkesine dayalı olarak yarattığını görmüyor musun? O eğer dilerse sizi yokedip yerinize yeni bir canlı türü geçirebilir."},{"n":20,"t":"Bu Allah için zor bir iş değildir."},{"n":21,"t":"Tüm insanlar Allah’ın huzuruna çıktıklarında güçsüz halk yığınları, büyüklük taslayan önderlere «Biz size bağlı idik, size uymuştuk. Şimdi Allah’ın bize vereceği azabın herhangi bir bölümünü başımızdan savabilecek misiniz?» derler. Önderler ise güçsüzlere şu karşılığı verirler, «Eğer Allah bizi doğru yola iletseydi, biz de sizi doğru yola erdirirdik. Şimdi feryad etsek de, sabretsek de farketmez. Çünkü kaçıp sığınabileceğimiz bir yer yok.»"},{"n":22,"t":"Herkese ilişkin hüküm verilip iş işten geçtikten sonra şeytan, cehennemliklere der ki; «Hiç kuşkusuz Allah’ın size yönelik vaadi doğru idi, ben ise size verdiğim sözü yerine getirmedim. Benim size yönelik, somut bir yaptırım gücüm yoktu, sadece sizi yoluma çağırdım, siz de çağrıma uyuverdiniz. O halde beni suçlamayınız, kendinizi suçlayınız, şimdi ne ben sizi kurtarabilirim, ne de siz beni kurtarabilirsiniz. Aslında vaktiyle beni Allah’a ortak koşmanızı da onaylamış değildim. Hiç kuşkusuz zalimler, acıklı bir azap çekeceklerdir."},{"n":23,"t":"İman edip iyi ameller işleyenler ise Rabblerinin izni ile içinde ebedi olarak kalacakları ve altlarından ırmaklar akan cennetlere yerleştirilirler, onlar orada esenlik dileği olarak «selâm» ile karşılanırlar."},{"n":24,"t":"Allah’ın güzel sözü neye benzettiğini görmüyor musun? O, onu yerin derinliklerine kök salmış ve dalları göğe tırmanan yararlı bir ağaca benzetiyor."},{"n":25,"t":"O ağaç sürekli olarak meyva verir. İnsanlar öğüt alsınlar diye Allah onlara çeşitli öğütler verir."},{"n":26,"t":"İğrenç söz de kökü yerden kesilmiş, dik duramayan acı meyvalı bir ağaca benzer."},{"n":27,"t":"Allah, gerek dünya hayatında, gerekse ahirette mü’minleri değişmez söze bağlı tutar. Allah zalimleri ise saptırır. Allah dilediğini yapar."},{"n":28,"t":"Allah’ın nimetini teperek yerine kâfirliği seçenleri ve milletlerini helâk yurduna sürükleyenleri görmüyor musun?"},{"n":29,"t":"O helâk yurdu, içine atılacakları cehennemdir. Orası ne fena bir barınaktır."},{"n":30,"t":"Onlar insanları Allah’ın yolundan saptırmak için O’na çeşitli ortaklar koştular. Onlara de ki; «Dünya nimetlerinden elinizden geldiği kadar yararlanın bakalım, çünkü sonunda varacağınız yer cehennem ateşidir."},{"n":31,"t":"Mü’min kullarıma de ki; «Namazı kılsınlar ve ne alışverişin ne de dostluğun geçerli olmadığı gün gelmeden önce kendilerine verdiğimiz rızıktan gizli ve açık biçimde bağışta bulunsunlar."},{"n":32,"t":"O Allah ki, gökleri ve yeri yarattı, gökten su indirerek, onun aracılığı ile size rızık olarak çeşitli meyvalar ortaya çıkardı, O’nun buyruğu ile denizde yüzen gemiyi yararınıza sundu, nehirleri yararınıza sundu."},{"n":33,"t":"Sürekli biçimde yörüngelerinde dönen güneşi ve ayı yararınıza sundu, gece ile gündüzü yararınıza sundu."},{"n":34,"t":"O size kendisinden isteyebileceğiniz her şeyi verdi. Eğer Allah’ın nimetlerini sayacak olursanız, onları bitiremezsiniz. Kuşkusuz insan çok zalim ve son derece nankördür."},{"n":35,"t":"Hani İbrahim dedi ki; «Ey Rabbim, bu beldeyi güvenli kıl, beni ve çocuklarımı putlara tapmaktan uzak tut.»"},{"n":36,"t":"Ey Rabbim, o putlar çoğu insanı yoldan çıkardı. Bundan böyle kim bana uyarsa bendendir, kim bana karşı çıkarsa, hiç kuşkusuz sen bağışlayıcısın, merhametlisin."},{"n":37,"t":"Ey Rabbimiz, ben âilemin bir bölümünü senin dokunulmaz evinin, Kâbe’nin yanıbaşındaki bitkisiz, kıraç bir vadiye yerleştirdim. Ey Rabbimiz, bunu namazı kılsınlar diye böyle yaptım. Buna göre insanlardan bir bölümünün gönüllerinde onlara karşı özlem uyandır ve onlara rızık olarak çeşitli meyvalar bağışla, umulur ki sana şükrederler."},{"n":38,"t":"Ey Rabbimiz, sen bizim gizlediğimiz ve açığa vurduğumuz her şeyi bilirsin. Çünkü yerdeki ve gökteki hiçbir şey Allah’dan gizlenemez."},{"n":39,"t":"Hayli ilerlemiş yaşıma rağmen, İsmail ile İshak’ı bana evlât olarak bağışlayan Allah’a hamdolsun. Hiç şüphesiz benim Rabbim duaları işitip kabul edendir."},{"n":40,"t":"Ey Rabbim, beni ve soyumdan gelenlerin bir bölümünü namaz kılanlardan eyle. Ey Rabbimiz, duamı kabul eyle."},{"n":41,"t":"Ey Rabbimiz, hesaba durulacağı günde beni, ana babamı ve tüm mü’minleri affeyle.»"},{"n":42,"t":"Sakın, Allah’ı, zalimlerin yaptıklarından habersiz sanma. Yalnız onlarla hesaplaşmayı gözlerin şaşkınlıktan donakalacağı bir güne erteliyor."},{"n":43,"t":"O gün onlar havaya dikilmiş başları ile, hiçbir tarafa bakamayan donuk gözleri ile duyarlıktan yoksun, bomboş gönülleri ile hızlı hızlı koşarlar."},{"n":44,"t":"İnsanları, azapla yüzyüze gelecekleri gün konusunda uyar. O gün zalimler «Ey Rabbimiz, bizimle hesaplaşmayı yakın bir sürenin sonuna ertele de senin çağrına olumlu cevap verip, peygamberlere uyalım» derler. «Peki, vaktiyle sürekli yaşayacağınıza, hiç ölmeyeceğinize yemin edenler sizler değil miydiniz?»"},{"n":45,"t":"Oysa daha önce kendilerine zulmetmiş olanların yurtlarında yaşadınız, onlara ne yaptığımızı açıkça öğrendiniz, size bu konuda çeşitli örnekler anlattık."},{"n":46,"t":"Onlar kuracakları tuzağı kurdular. Fakat tuzakları dağları yerlerinden oynatabilecek nitelikte olsa bile, Allah’ın denetimi altındadır."},{"n":47,"t":"Sakın Allah’ın, peygamberlerine yönelik vaadinden cayacağını sanma. Hiç kuşkusuz Allah üstün iradeli ve öç alıcıdır."},{"n":48,"t":"O gün yer başka bir yere, gökler de başka göklere dönüştürülürler ve tüm insanlar tek ve ezici iradeli Allah’ın huzuruna çıkarlar."},{"n":49,"t":"O gün günahkârların zincirlerle birbirlerine bağlandıklarını görürsün."},{"n":50,"t":"Elbiseleri katrandan olacak ve yüzlerini ateş saracaktır."},{"n":51,"t":"Amaç, Allah’ın herkese işlediğinin karşılığını vermesidir. Hiç kuşkusuz Allah’ın hesap görmesi pek çabuktur."},{"n":52,"t":"Bu Kur’an tüm insanlara yönelik bir duyurudur. Onun aracılığı ile insanlar uyarılsın, herkes Allah’ın tek olduğunu öğrensin ve sağduyulu kimseler onun ibret derslerinden yararlansın diye inmiştir."}],[{"n":1,"t":"Elif, Lâm, Ra; bunlar kitabın, Kur’an’ın ayetleridir."},{"n":2,"t":"Gün gelecek, kâfirler «keşke vaktiyle müslüman olsaydık» diyeceklerdir."},{"n":3,"t":"Bırak onları yesinler, dünya nimetlerinden yararlansınlar ve ihtirasları ile oyalansınlar, ilerde gerçeği öğreneceklerdir."},{"n":4,"t":"Yok ettiğimiz her beldenin mutlaka uğradığı akıbete ilişkin belirli bir yazısı vardır."},{"n":5,"t":"Hiçbir millet ne yokoluş gününü öne alabilir ve ne de yaşama süresini aşabilir."},{"n":6,"t":"Müşrikler dediler ki; «Ey kendisine Kur’an inen adam, sen kesinlikle delinin birisin.»"},{"n":7,"t":"Eğer söylediklerin doğru ise bize melekler ile birlikte gelseydin ya."},{"n":8,"t":"Oysa biz melekleri ancak gerektiğinde indiririz, o zaman da onlara artık mühlet tanınmaz.»"},{"n":9,"t":"Bu Kur’an’ı gerçekten biz indirdik ve onu koruyacak olan da biziz."},{"n":10,"t":"Ey Muhammed, biz senden önce de eskiden yaşamış çeşitli milletlere peygamberler göndermiştik."},{"n":11,"t":"Bu milletler, kendilerine gelen her peygamberi mutlaka alaya almışlardır."},{"n":12,"t":"Biz böylece peygamberleri alaya alma huyunu günahkârların kalplerine aşılarız."},{"n":13,"t":"Onlar Kur’an’a inanmazlar. Oysa daha önceki yoldaşları hakkında ilahi kanun işlemişti."},{"n":14,"t":"Eğer onlara bir kapı açsak da göğe çıkmaya koyulsalar."},{"n":15,"t":"«Gözlerimiz hayal görüyor, herhalde birileri bize büyü yaptı,» derler."},{"n":16,"t":"Gökte takım yıldızlar (ya da yörüngeler) yarattık ve onları gözetleyenler için çeşitli güzellikler ile donattık."},{"n":17,"t":"Göğü bütün kovulmuş şeytanlardan koruduk."},{"n":18,"t":"Ancak kulak hırsızlığına yeltenen bir şeytan olursa onu parlak ışıklı bir kayan yıldız kovalar."},{"n":19,"t":"Yerin alanını geniş yaptık, oraya sabit dağlar serpiştirdik ve orada belirli bir ölçü uyarınca her bitkiyi bitirdik."},{"n":20,"t":"Orada gerek sizin için ve gerekse rızıkları tarafınızdan sağlanması sözkonusu olmayan diğer canlılar için besin kaynakları yarattık."},{"n":21,"t":"Evrende varolan her şeyin hazinesi, ana kaynağı bizim yanımızdadır. Ve biz her şeyi size belirli bir ölçüye göre indiririz."},{"n":22,"t":"Gönderdiğimiz yağmur yükleyici rüzgârlar aracılığı ile size gökten su indirerek su ihtiyacınızı karşıladık. Yoksa su kaynağını oluşturan siz değilsiniz."},{"n":23,"t":"Dirilten de öldüren de yalnız biziz ve her şey sonunda bize kalır."},{"n":24,"t":"Biz sizin eskiden gelip geçenlerini de geride kalanlarını da biliriz."},{"n":25,"t":"Hiç kuşkusuz Rabbin tüm insanları biraraya toplayacaktır. O her işi yerinde yapar ve her şeyi bilir."},{"n":26,"t":"Gerçekten biz insanı kara çamurdan oluşmuş kuru balçıktan yarattık."},{"n":27,"t":"Cinni de daha önce dumansız alevden yarattık."},{"n":28,"t":"Hani Rabbin, meleklere dedi ki; «Ben kara çamurdan oluşmuş kuru balçıktan bir insan yaratacağım.»"},{"n":29,"t":"Ona biçim verip içine kendi ruhumdan bir soluk üflediğimde önünde secdeye kapanınız!»"},{"n":30,"t":"Bunun üzerine bütün melekler hep birlikte secdeye kapandılar."},{"n":31,"t":"Yalnız İblis, secdeye kapananlar arasında olmayı reddetti."},{"n":32,"t":"Allah «Ey İblis, seni secde edenler ile birlikte olmaktan alıkoyan nedir?» dedi."},{"n":33,"t":"İblis «Kara çamurdan oluşmuş kuru balçıktan yarattığın insana secde etmek bana yakışmaz» dedi."},{"n":34,"t":"Allah «Öyleyse defol oradan, artık sen rahmetimden kovulmuşsun» dedi."},{"n":35,"t":"Hesaplaşma gününe kadar sürekli olarak lânetim üzerinedir."},{"n":36,"t":"İblis, «Ey Rabbim, o halde insanların tekrar dirilecekleri güne kadar bana yaşama süresi tanı» dedi."},{"n":37,"t":"Allah, «Sen kendilerine yaşama süresi tanınanlardansın» dedi."},{"n":38,"t":"O belirli vaktin gününe kadar."},{"n":39,"t":"İblis dedi ki; «Ey Rabbim, beni kışkırtıp sapıklığa düşürdüğün için dünyada kötülüğü onlara cazip göstererek hepsini yoldan çıkaracağım."},{"n":40,"t":"Sadece onların arasındaki seçkin kulların hariç."},{"n":41,"t":"Allah dedi ki; «İşte bana ileten doğru yolum budur.»"},{"n":42,"t":"Sana uyan sapıklar dışındaki kullarım üzerinde senin hiçbir nüfuzun, hiçbir etkileme gücün yoktur."},{"n":43,"t":"Onların hepsinin buluşma yerleri cehennemdir."},{"n":44,"t":"Oranın yedi kapısı vardır. Her kapıdan hangi cehennemlik grupların içeriye girecekleri belirlenmiştir."},{"n":45,"t":"Kötülükten sakınanlar ise, cennetteler ve pınar başlarındadırlar."},{"n":46,"t":"Onlara «Esenlikle ve güven içinde oraya giriniz» denir."},{"n":47,"t":"Biz cennetliklerin kalplerindeki tüm kin tortularını çekip çıkardık, onlar orada karşılıklı koltuklarda oturan kardeşlerdir."},{"n":48,"t":"Onlar orada bıkkınlık hissetmezler, oradan çıkarılmaları da sözkonusu değildir."},{"n":49,"t":"Ey Muhammed, kullarıma haber ver ki, ben gerçekten affediciyim, merhametliyim."},{"n":50,"t":"Fakat azabım da son derece acıklı bir azaptır."},{"n":51,"t":"Onlara İbrahim’in konukları hakkında da bilgi ver."},{"n":52,"t":"Hani İbrahim’in yanına girip selâm verdiklerinde O «Biz sizden korkuyoruz» dedi."},{"n":53,"t":"Onlar «Korkma, biz sana bilgin bir oğlun olacağını müjdeliyoruz.»"},{"n":54,"t":"İbrahim «Hayli ilerlemiş yaşıma rağmen mi bana bu müjdeyi veriyorsunuz? O halde neye dayanarak müjde veriyorsunuz?» dedi."},{"n":55,"t":"’Seni hak ile müjdeledik. Şu halde ümit kesenlerden olma’ dediler."},{"n":56,"t":"İbrahim, «sapıklardan başka kim Allah’ın rahmetinden ümit keser» dedi."},{"n":57,"t":"İbrahim; «Ey elçiler göreviniz nedir?» dedi."},{"n":58,"t":"Onlar dediler ki, «Biz günahkâr bir topluma gönderildik."},{"n":59,"t":"Yalnız Lût’un bağlıları ile ailesi hariç; onların tümünü kurtaracağız."},{"n":60,"t":"Yalnız Lût’un eşi hariç, onun geride kalanlar arasında olmasını uygun gördük."},{"n":61,"t":"Bu elçiler Lût’un evine geldiklerinde."},{"n":62,"t":"Lût; «Siz benim tanımadığım kimselersiniz» dedi."},{"n":63,"t":"Onlar dediler ki; «Biz sana soydaşlarının kuşku ile karşıladıkları ilahi azabı haber vermeye geldik.»"},{"n":64,"t":"Sana gerçeği getirdik, kesinlikle doğru söylüyoruz."},{"n":65,"t":"Gecenin bir saatinde aileni ve bağlılarını yola çıkar, sen de peşlerinden git, hiçbiriniz arkasına bakmasın, emredildiğiniz yere doğru yol alın."},{"n":66,"t":"Böylece Lût’a bu önemli olayı, yani sabah olunca şu adamların soylarının kurumuş olacağı yolundaki hükmümüzü bildirdik."},{"n":67,"t":"Şehir halkı sevinç içinde Lût’un evine geldi."},{"n":68,"t":"Lût onlara dedi ki; «Bunlar benim konuklarımdır, sakın beni onlar karşısında rezil etmeyiniz.»"},{"n":69,"t":"Allah’dan korkunuz, beni utandırmayınız.»"},{"n":70,"t":"Hemşehrileri ona; «İnsanlar ile ilişki kurmayı biz sana yasaklamamış mıydık?» dediler."},{"n":71,"t":"\"Eğer yapmak istiyorsanız, işte bunlar, benim kızlarım.\""},{"n":72,"t":"Ey Muhammed, hayatın hakkı için onlar sarhoşlukları içinde debeleniyorlardı."},{"n":73,"t":"Tanyeri ağarırken korkunç bir gürültüye tutuldular."},{"n":74,"t":"Beldelerinin altını üstüne getirdik ve üzerlerine taşlaşmış balçık kütleleri yağdırdık."},{"n":75,"t":"Hiç şüphesiz görüntü aracılığı ile işin özünü kavrayabilenler için bu olayda alınacak birçok dersler vardır."},{"n":76,"t":"Bu beldenin yıkıntıları halâ işlek olan bir yol üzerindedir."},{"n":77,"t":"Bu yıkıntılarda mü’minler için ibret dersleri vardır."},{"n":78,"t":"Eyke halkı da, hiç kuşkusuz zalim kimselerdi."},{"n":79,"t":"Bu yüzden onlardan da öç aldık; bu beldelerin her ikisi de işlek bir yol üzerindedirler."},{"n":80,"t":"Hicr vadisinin halkı da gerçekten peygamberleri yalanlamışlardı."},{"n":81,"t":"Onlara mucizelerimizi gösterdik, fakat onlar yüz çevirdiler."},{"n":82,"t":"Onlar dağları oyup güvenli köşkler yapıyorlardı."},{"n":83,"t":"Gün doğarken korkunç bir gürültüye tutuldular."},{"n":84,"t":"Oydukları köşkler hiçbir işlerine yaramadı."},{"n":85,"t":"Biz gökleri, yeri ve ikisi arasındaki varlıkları bir gerekçeye dayalı olarak yarattık, boşuna yaratmadık. Kıyamet anı kesinlikle gelecektir. O halde onların küstahlıklarını soylu bir umursamazlıkla karşıla."},{"n":86,"t":"Her şeyi yaratan ve her şeyi bilen Rabbindir."},{"n":87,"t":"Gerçekten sana sürekli tekrarlanan yedi ayetli Fatiha suresini ve yüce Kur’an’ı verdik."},{"n":88,"t":"Erkek, kadın bazı kâfirlere verdiğimiz kimi dünya nimetlerine göz dikme ve (iman etmiyorlar diye) onlar için üzülme, mü’minlere karşı alçak gönüllülük kanatlarını indir."},{"n":89,"t":"Ben açık sözlü bir uyarıcıyım de."},{"n":90,"t":"Kutsal kitaplarının ayetleri arasında ayırım gözeten bölücülere de mesaj indirdik."},{"n":91,"t":"Onlar ki, Kur’an’ın ayetleri arasında da ayırım gözettiler."},{"n":92,"t":"Rabbin hakkı için, onların tümünü kesinlikle sorguya çekeceğiz."},{"n":93,"t":"Yaptıkları işler konusunda."},{"n":94,"t":"Sana buyurulanı açıktan açığa bildir. Ve müşriklere aldırış etme."},{"n":95,"t":"O istihzacılara karşı muhakkak ki biz sana yeteriz."},{"n":96,"t":"Onlar ki Allah’la beraber başka bir tanrı tanırlar. Onlar yakında bileceklerdir."},{"n":97,"t":"Andolsun ki onların dediklerinden göğsünün daraldığını biliyoruz."},{"n":98,"t":"Sen hemen Rabbini hamd ile tesbih et. Ve secde edenlerden ol."},{"n":99,"t":"Ve sana «yakîn» gelinceye kadar Rabbine ibadet et."}],[{"n":1,"t":"Allah’ın hükmü yakında gerçekleşecektir; buna göre onun bir an önce gerçekleşmesini boşu boşuna isteyip durmayınız. Allah, onların kendisine yakıştırdıkları ortaklardan uzaktır, yücedir."},{"n":2,"t":"Allah «Benden başka ilah yoktur, sırf benden korkunuz» uyarısını, mesajını insanlara duyursunlar diye dilediği kullarına kendi iradesi ile vahiy eşliğinde melekler gönderir."},{"n":3,"t":"Allah, gökleri ve yeri haklı bir gerekçe uyarınca yarattı; O, onların kendisine yakıştırdıkları ortaklardan uzaktır."},{"n":4,"t":"O insanı bir meni damlacığından yarattı; fakat o birdenbire pervasız bir tartışmacıya dönüştü."},{"n":5,"t":"Ve davarları da yarattı O. O hayvanlar ki, kendilerinden pekçok yararları yanında, sizi ısıtan giysiler, besleyen yiyecekler elde ediyorsunuz."},{"n":6,"t":"Bu hayvanlar, onları sabahleyin otlağa salarken ve akşam geri getirirken, size göz zevki sağlarlar."},{"n":7,"t":"Bu hayvanlar, ancak ağır sıkıntıya katlanarak varabileceğiniz uzaklıktaki beldelere yüklerinizi taşırlar. Hiç kuşkusuz Rabbiniz pek şefkatli ve merhametlidir."},{"n":8,"t":"Allah atları, katırları, eşekleri, binek ve süs hayvanı olarak yarattı. O sizin bilmediğiniz daha nice canlıları yarattı."},{"n":9,"t":"Yolun doğrusunu göstermek Allah’ın tekelindedir. Kimi yollar eğridir. Eğer o dileseydi, hepinizi doğru yola iletirdi."},{"n":10,"t":"Size gökten su indiren O’dur ve hayvan otlattığınız çayırlar O’nun sayesinde gelişir."},{"n":11,"t":"Allah su aracılığı ile sizin için ekinler, zeytinler, hurmalar, üzümler ve çeşit çeşit meyvalar bitirmektedir. Bunda düşünen kimseler için ibret dersi vardır."},{"n":12,"t":"Allah gece ile gündüzü, güneş ile ayı yararınıza sundu. Yıldızlar da O’nun buyruğu ile canlılara hizmet sunmaktadırlar. Bunlarda düşünen kimseler için ibret dersi vardır."},{"n":13,"t":"O yeryüzünde yarattığı çeşitli türdeki varlıkları da sizin yararınıza sundu. Bunda öğüt alan kimselere ibret dersi vardır."},{"n":14,"t":"O denizi de yararınıza sundu ki, oradan elde edilen taze etler yiyesiniz ve diplerinden süs olarak kullanacağınız takılar çıkarasınız; gemilerin, dalgaları yara yara denizde süzüldüklerini görürsün. Nimetlerini araştırasınız ve ola ki, kendisine şükredesiniz diye Allah, denizi yararınıza sundu."},{"n":15,"t":"Allah, yeryüzünde sarsılmayasınız diye köklü dağlar, yolunuzu şaşırmayasınız diye nehirler ve yollar meydana getirdi."},{"n":16,"t":"Çeşitli yol işaretleri de varetti. İnsanlar yıldızlar aracılığı ile de yönlerini belirler."},{"n":17,"t":"Yaratan, yaratamayan gibi olur mu? Hiç düşünmüyor musunuz?"},{"n":18,"t":"Eğer Allah’ın nimetlerini sayacak olursanız bitiremezsiniz. Hiç kuşkusuz Allah bağışlayıcıdır, merhametlidir."},{"n":19,"t":"Allah, gizlediklerinizi de açığa vurduklarınızı da bilir."},{"n":20,"t":"tersine kendileri birer yaratıktırlar."},{"n":21,"t":"Onlar cansızdırlar, canları yoktur. Kendilerine tapanların ne zaman yeniden diriltileceklerini bilmezler."},{"n":22,"t":"İlahınız tek ilahtır. Ahirete inanmayanların kalpleri inkârcıdır, onlar gerçeğe set çevirmiş, kendini beğenmişlerdir."},{"n":23,"t":"Hiç kuşkusuz Allah, onların gizli tuttuklarını da, açığa vurduklarını da bilir; O gerçeğe sırt çeviren kendini beğenmişleri kesinlikle sevmez."},{"n":24,"t":"Kendilerine «Rabbiniz ne indirdi» diye sorulduğunda «Bunlar eskilerin masallarıdır» dediler."},{"n":25,"t":"Böylece kıyamet günü hem kendi günahlarını tümü ile, hem de hiçbir bilgiye dayanmaksızın sapıklığa sürükledikleri kimselerin günahlarının bir bölümünü yüklenirler. Hey! Ne fena bir yükün altına giriyorlar!"},{"n":26,"t":"Onlardan öncekiler de peygamberlerine tuzaklar kurdular da, Allah kurdukları yapının temellerini çökerterek tavanını başlarına indirdi; Allah’ın azabı, hiç ummadıkları taraftan başlarına iniverdi."},{"n":27,"t":"Sonra kıyamet günü, Allah onlara «Uğurlarında peygamberler ile çatıştığınız ortaklarım hani nerede?» diyerek kendilerini rezil eder. Bilgi sahipleri de «Bugün rezillik ve kötü akıbet, kâfirleri kuşatmıştır» derler."},{"n":28,"t":"Kendilerine zulmederken canları alınan kâfirler «Biz hiçbir kötülük yapmamıştık» diyerek ölüm meleklerine kolayca teslim olurlar. «Hayır, öyle değil. Allah sizin neler yaptıklarınızı bilir.»"},{"n":29,"t":"Bunun için ebedi olarak cehennemde kalmak üzere oranın kapılarından içeri giriniz. Kendini beğenmişlerin barınağı ne kötü bir yerdir."},{"n":30,"t":"Kötülükten sakınanlara «Rabbiniz ne indirdi?» diye sorulduğunda «İyilik indirdi» derler. Bu dünyada iyi davrananlar iyilik görürler. Ahiret ise onlar için daha hayırlıdır. Kötülükten sakınanların yurdu ne güzel bir yerdir."},{"n":31,"t":"Onların girecekleri yer, altından çeşitli ırmaklar akan Adn cennetleridir. Orada diledikleri her şey kendilerine verilir. İşte Allah kötülükten sakınanları böyle ödüllendirir."},{"n":32,"t":"Melekler iyi kulların canlarını alırken kendilerine «Selam üzerinize olsun, yapmış olduğunuz iyiliklerin karşılığı olarak cennete giriniz» derler."},{"n":33,"t":"Kâfirler, kendilerine ölüm meleklerinin gelmesinden ya da Rabbinin ani azabına uğramaktan başka bir şey mi bekliyorlar. Kendilerinden öncekiler de öyle yapmışlardı. Allah onlara zulmetmiş değildi, tersine onlar kendi kendilerine zulmetmişlerdi."},{"n":34,"t":"Sonunda yaptıkları kötülüklerin acı akıbeti ile yüzyüze geldiler, alay konusu ettikleri ilahi azabın pençesine düştüler."},{"n":35,"t":"Allah’a ortak koşanlar «Eğer Allah dileseydi, ne biz ve ne de atalarımız O’nun dışında hiçbir ilaha tapmaz ve O’nun izni olmaksızın hiçbir şeyi yasak saymazdık» derler. Kendilerinden önceki müşrikler de böyle yapmışlardı. Peygamberlerin, ilahi mesajı açıkça duyurmaktan başka bir görevleri mi var ki?"},{"n":36,"t":"Biz her millete «Allah’a kulluk ediniz, tağuta (şeytana) tapmaktan sakınınız» diyen bir peygamber gönderdik. Kimini Allah doğru yola iletti, kimi de sapıklığı haketti. Yeryüzünde geziniz de peygamberlerini yalanlayanların sonunun ne olduğunu görünüz."},{"n":37,"t":"Ey Muhammed, sen onların doğru yola gelmelerini ne kadar ısrarla istesen de Allah, saptırdığı kimseleri kesinlikle doğru yola iletmez. Onlar hiçbir yardımcı bulamazlar."},{"n":38,"t":"Onlar en pekiştirici ifadeleri kullanarak «Allah, ölüleri yeniden diriltmez» diye yemin ettiler. Hayır, öyle değil. Ölüleri diriltmek, Allah’ın üstlendiği kesin bir vaaddir. Fakat çoğu insanlar bunu bilmezler."},{"n":39,"t":"İnsanlar arasındaki tartışmalı konular Allah tarafından açıklığa kavuşturulsun ve kâfirler, yalan söylediklerini öğrensinler diye ölüler tekrar diriltilecektir."},{"n":40,"t":"Biz bir şeyin olmasını isteyince söyleyeceğimiz tek söz ona «ol» dememizdir, o da hemen oluverir."},{"n":41,"t":"Zulme uğratıldıktan sonra Allah uğruna hicret edenleri dünyada güzel yurtlara yerleştireceğiz. Ahirette alacakları ödül ise daha büyüktür. Keşke bunu bilseler!"},{"n":42,"t":"Onlar ki, sabrederler ve sırf Allah’a dayanırlar."},{"n":43,"t":"Senden önceki peygamberlerimiz de kendilerine vahiy indirdiğimiz birer insandı. Eğer bilmiyorsanız, daha önce kendilerine kitap verilenlere sorunuz."},{"n":44,"t":"O peygamberleri açık deliller ile ve kitaplar ile göndermiştik. Sana da, insanlara indirilen ilahi mesajı açıklayasın da ola ki, düşünürler diye Kur’an’ı indirdik."},{"n":45,"t":"Peygamber’e iğrenç tuzak kuranlar, Allah’ın kendilerini yerin dibine geçirmeyeceğinden ya da beklemedikleri taraftan gelecek ilahi bir azaba uğramayacaklarından emin midirler?"},{"n":46,"t":"Ya da ilahi azabın gezilerinden biri sırasında kendilerini yakalamayacağından emin midirler? Onların Allah’ın yapacağını engellemeleri sözkonusu değildir."},{"n":47,"t":"Ya da ilahi azabın korkulu bir bekleyiş halindelerken başlarına gelmeyeceğinden emin midirler? Hiç şüphesiz Rabbiniz, şefkatli ve merhametlidir."},{"n":48,"t":"Kâfirler, Allah’ın yarattığı her şeyin gölgesinin uzayıp kısalarak sağdan sola döndüğünü ve böylece O’na boyun eğerek secde ettiğini görmüyorlar mı?"},{"n":49,"t":"Göklerde ve yerde bulunan bütün canlılar ve melekler, büyüklük taslamaksızın, Allah’a secde ederler."},{"n":50,"t":"Çünkü onlar üstlerindeki Rabblerinden korkarlar ve kendilerine emredileni yaparlar."},{"n":51,"t":"Allah «iki ilah edinmeyiniz, o tek bir ilahtır, yalnız benden korkunuz» dedi."},{"n":52,"t":"Göklerde ve yerde ne varsa O’nundur. İtaat mercii sürekli olarak hep O’dur. Siz Allah’dan başkasından mı korkuyorsunuz?"},{"n":53,"t":"Yararlandığınız her nimet Allah’dandır. Sonra başınıza bir sıkıntı gelince yalnız O’na yalvarırsınız."},{"n":54,"t":"Arkasından sıkıntınızı giderince, içinizden bazıları hemen Rabblerine ortak koşarlar."},{"n":55,"t":"Böylece, kendilerine verdiğimiz nimetlere karşı nankörlük ederler. «Dünya nimetleri ile oyalanın bakalım, yakında gerçeği öğreneceksiniz.»"},{"n":56,"t":"Kendilerine verdiğimiz rızıktan bilmediklerine hisse çıkarırlar. Allah’a andolsun ki uydurup durduğunuz şeylerden muhakkak suale çekileceksiniz."},{"n":57,"t":"Onlar, Allah’a kız çocuklarını mal ederler ki, O bu yakıştırmadan uzaktır, canlarının istediği erkek çocuklarını ise kendilerine ayırırlar."},{"n":58,"t":"Onlardan birine kız çocuğu olduğu müjdesi verildiğinde, üzüntüden yüzü simsiyah kesilir."},{"n":59,"t":"Aldığı kara haberden dolayı tanıdıklarına görünmekten kaçınır. Aşağılanmaya katlanarak onu alıkoysun mu, yoksa toprağa mı gömsün diye düşünür. Baksana, ne kötü hüküm veriyorlar!"},{"n":60,"t":"Ahirete inanmayanlar her konuda kötülüğün örneğini oluştururlar. Allah ise yüceliğin örneğidir. O üstün iradelidir ve her işi yerindedir."},{"n":61,"t":"Eğer Allah, zalimce davranışlarından ötürü insanların, hemen yakasına yapışsa yeryüzünde bir tek canlıyı sağ bırakmazdı. Fakat o insanlara belirli bir sürenin sonuna kadar mühlet tanır. Süreleri dolunca onu, ne bir an erteleyebilirler ve ne de öne alabilirler."},{"n":62,"t":"Hoşlarına gitmeyen şeyleri Allah’a yakıştırırlar. Buna rağmen en güzel akıbet kendilerinin olacak diye asılsız kuruntular gevelerler. Oysa, hiç kuşku yok ki, yerleri cehennemdir, oraya öncelikle gireceklerdir."},{"n":63,"t":"Allah’a andolsun ki, senden önce de çeşitli ümmetlere de peygamberler gönderdik. Şeytan onlara yaptıkları kötülükleri güzel gösterdi. O, bugün de onların dostudur. Onları acıklı bir azap bekliyor."},{"n":64,"t":"Biz sana bu kitabı, insanlara anlaşmazlığa düştükleri meseleleri açıklayasın, mü’minlere ise yol gösterici ve rahmet kaynağı olsun diye indirdik."},{"n":65,"t":"Allah gökten su indirerek, onunla yeri, ölümünden sonra diriltti. Gerçekleri işitebilecek kulakları olanlar için bunda ibret dersi vardır."},{"n":66,"t":"Sizin için süt hayvanlarında da ibret dersi vardır. Onların karınlarındaki (bağırsaklarındaki) posa ile kan arasından size halis ve tatlı içimli bir besin kaynağı olan sütü içiririz."},{"n":67,"t":"Hurma ağaçlarının meyvaları ile üzümlerden içki ve yararlı besin elde edersiniz. Düşünenler için bunda ibret dersi vardır."},{"n":68,"t":"Rabbin bal arısına ilham etti ki; «Dağ oyuklarında, ağaç kovuklarında ve asma yaprakları arasında petek ör.»"},{"n":69,"t":"Sonra her meyvadan ye, Rabbinin önüne açtığı bütün yolları aş.» Arının karnından değişik renkli ve insanlar için şifa kaynağı olan bir içecek (bal) çıkar. Bu olayda düşünen kimseler için ibret dersi vardır."},{"n":70,"t":"Allah sizi yarattı, sonra canınızı alır; kiminizin ömrü en rezil, en güçsüz yaşlara kadar uzatılır da adam vaktiyle bildiklerinin hiçbirini bilmez olur. Hiç şüphesiz Allah her şeyi bilir ve her şeyi yapabilir."},{"n":71,"t":"Allah rızık alanında bir bölümünüzü diğerlerinizden üstün kıldı. Üstün konumdakiler rızıklarını, buyrukları altındaki yoksullarla paylaşmıyorlar ki, herkes eşit geçim düzeyine kavuşsun. Acaba Allah’ın nimetlerini inkar mı ediyorsunuz?"},{"n":72,"t":"Allah size kendi türünüzden eşler sundu; bu eşlerinizden size çocuklar, torunlar verdi, size temiz rızıklar bağışladı. Durum böyleyken, onlar batıla inanıp Allah’ın nimetlerini inkâr mı ediyorlar?"},{"n":73,"t":"Onlar Allah’ı bırakıp kendilerine göklerden ya da yerden hiçbir rızık veremeyen buna asla gücü yetmeyen düzmece ilahlara taparlar."},{"n":74,"t":"Allah’a benzerler yakıştırmaya kalkışmayınız. Çünkü Allah bilir, siz bilmezsiniz."},{"n":75,"t":"Allah, özgürlüğünden yoksun, hiçbir şey yapmaya gücü yetmeyen, bir köle ile kendisine bağışladığımız güzel nimetlerin bir bölümünü başkalarına veren kimseyi size örnek veriyor. Hiç bunlar bir olur mu? Allah’a hamdolsun ki, gerçek meydana çıktı. Fakat onların çoğu bunu bilmez."},{"n":76,"t":"Adamlardan biri dilsizdir, hiçbir şey yapamaz efendisine yüktür, gönderildiği hiçbir yerden başarı ile dönmez. Şimdi bu adam hiç doğru yolda olan ve adalete uygun emirler veren bir kimse ile bir olur mu?"},{"n":77,"t":"Göklere ve yere ilişkin bilinmezlerin bilgisi Allah’ın tekelindedir. Kıyamet olayı, yakınlığı bakımından bir göz kırpması gibidir ya da bundan bile daha yakındır. Hiç şüphesiz, Allah’ın gücü her şeye yeter."},{"n":78,"t":"Allah sizi, hiçbir şey bilmez halde, analarınızın karınlarından çıkardı, size kendisine şükredesiniz diye işitme duyusu, gözler ve kalpler verdi."},{"n":79,"t":"Onlar gök boşluğunda, süzülen kuşları görmüyorlar mı? Onları dengede tutan Allah’dan başkası değildir. Bu olayda mü’minler için birçok ibret dersleri vardır."},{"n":80,"t":"Allah, evlerinizi size barınak yaptı. Süt hayvanlarından gerek geziye çıktığınız ve gerekse beldelerinizde oturduğunuz günlerde kolayca taşıyabileceğiniz çadırlar yaptı. Bu hayvanların yünlerinden, tüylerinden ve kıllarından yaşama sürenizin bitimine kadar yararlanabileceğiniz çeşitli giyim ve kullanım eşyası yapmanızı sağladı."},{"n":81,"t":"Allah, yarattıklarından size gölgeler sağladı; dağlarda sığınacağınız mağaralar varetti; size sıcaktan koruyucu elbiseler ile düşmanlarınızın darbelerinden koruyucu zırhlar sağladı. Böylece size yönelik nimetlerini tamama erdiriyor ki, ola ki buyruklarına uyasınız."},{"n":82,"t":"Eğer onlar sana sırt çevirirlerse senin görevin, buyruklarımızı onlara açıkça duyurmaktan ibarettir."},{"n":83,"t":"Aslında Allah’ın nimetinin pekala farkındalar, ama yine de O’nu tanıyıp doğrulamaya yanaşmıyorlar. Çünkü onların pek çoğu, Allah’tan gelen gerçekleri örtbas ediyorlar."},{"n":84,"t":"O gün her ümmetten bir tanık karşımıza getiririz. Ondan sonra artık kâfirlere ne itiraz izni verilir ve ne de Rabblerinden özür dilemeleri istenir."},{"n":85,"t":"Zalimler, azapla yüzyüze geldiklerinde, artık ne azapları hafifletilir ve ne de kendilerine mühlet verilir."},{"n":86,"t":"Allah’a ortak koşanlar, koştukları ortakları gördüklerinde «Ey Rabbimiz, seni bırakıp kendilerine yalvardığımız ortaklar bunlardı» derler. Koşulan ortaklar ise onlara «Sizler kesinlikle yalancısınız» diye hemen cevap yetiştirirler."},{"n":87,"t":"O gün müşrikler, çaresizlik içinde Allah’a teslim oluverirler ve uydurma ilahları tarafından yüzüstü bırakılırlar."},{"n":88,"t":"Onlar ki, kâfir oldular ve başkalarını da Allah yolundan alıkoydular, onların azaplarını katlayarak arttırırız."},{"n":89,"t":"Her ümmetin aleyhinde kendilerinden bir şahit göstereceğimiz günde seni de onların aleyhinde şahit tutarız. Sana bu kitabı her şeyi açıklayan bir bilge, bir doğru yol rehberi, bir rahmet kaynağı ve müslümanlara yönelik bir müjde olarak indirdik."},{"n":90,"t":"Allah size adaleti, iyiliği, akrabalara yardım etmeyi emreder. Çirkin davranışları ve iğrençlikleri yasaklar. Sözünü tutasınız diye O, size öğüt verir."},{"n":91,"t":"Allah’a söz verdiğinizde verdiğiniz sözü tutunuz. Pekiştirdiğiniz yeminlerinizi bozmayınız. Çünkü söylediklerinize Allah’ı şahit tutmuş oluyorsunuz. Hiç şüphesiz Allah, yaptıklarınızı bilir."},{"n":92,"t":"Bir ümmet diğer bir ümmetten (sayıca ve malca) daha gelişkindir diye, yeminlerinizi kendi aranızda bir bozuculuk unsuru yaparak, ipini kuvvetle eğirdikten sonra bozup çözen (kadın) gibi olmayın. Şüphesiz Allah, sizi bununla imtihan etmektedir. Kıyamet günü hakkında ihtilafa düştüğünüz şeyi size muhakkak açıklayacaktır."},{"n":93,"t":"Allah dileseydi, hepinizi tek bir ümmet yapardı. Fakat O, dilediğini saptırır, dilediğini de doğru yola iletir. Sizler yaptığınız işlerden kesinlikle sorguya çekileceksiniz."},{"n":94,"t":"Yeminlerinizi birbirinize karşı hile aracı kullanmayınız. Yoksa yere sağlam basan ayaklarınız kayıyor ve başkalarının Allah yoluna girmelerine engel olmanızın sonucu olarak ızdırap çekersiniz, ayrıca ahirette de büyük bir azaba çarpılırsınız."},{"n":95,"t":"Allah’a vermiş olduğunuz sözü birkaç paraya satmayınız. Çünkü gerçeğin bilincindeyseniz, Allah’ın katındaki ödül sizin için daha hayırlıdır."},{"n":96,"t":"Sizin yanınızdaki tükenir, fakat Allah’ın katındaki kalıcıdır, süreklidir. Biz sabredenleri, yaptıkları iyiliklerin en güzel karşılıkları ile ödüllendireceğiz."},{"n":97,"t":"İman etmiş olan hangi erkek ya da kadın, eğer iyi amel işlerse, ona dünyada mutlu bir hayat yaşatırız, böylelerini ahirette de yaptıkları iyiliklerin en güzel karşılığı ile ödüllendiririz."},{"n":98,"t":"Ey Muhammed, Kur’an okuyacağınız zaman, kovulmuş şeytandan Allah’a sığın."},{"n":99,"t":"Çünkü şeytanın, Rabblerine sığınan mü’minler üzerinde hiçbir nüfuzu, hiçbir etkinliği yoktur."},{"n":100,"t":"Şeytanın, sadece onu dost edinenler ve Allah’a ortak koşanlar üzerinde, nüfuzu ve etkinliği vardır."},{"n":101,"t":"Biz herhangi bir ayeti başka bir ayetle değiştirdiğimiz zaman kâfirler sana «Sen bunu yalandan uyduruyorsun» derler. Oysa Allah kullarına ne mesaj indireceğini herkesden iyi bilir. Aslında onların çoğu gerçeği bilmiyorlar."},{"n":102,"t":"Onlara de ki; «Bu Kur’an’ı, Ruh’ül-Kudüs (Cebrail) Rabbinin katından hakka dayalı olarak indirdi. Amacı, mü’minlerin inancını pekiştirmek, müslümanlara doğru yol kılavuzu ve müjde kaynağı olmaktır."},{"n":103,"t":"Onların «Bu Kur’an’ı, Muhammed’e biri öğretiyor» dediklerini kesinlikle biliyoruz. Bu asılsız yakıştırmayı ileri sürerken kastettikleri kişinin dili yabancıdır, Arapça değildir; oysa Kur’an’ın dili fasih bir Arapça’dır."},{"n":104,"t":"Allah’ın ayetlerine inanmayanları O doğru yola iletmez. Onları acıklı bir azap beklemektedir."},{"n":105,"t":"Allah’ın ayetlerine inanmayanlar yalan söylerler, iftira ederler; işte asıl onlardır yalancılar."},{"n":106,"t":"iman ettikten sonra kâfir olanlar, Allah’ın gazabına uğrarlar, onun için büyük bir azap vardır. Yalnız bu hüküm, kalpleri kesin bir imanın hazzı ile donanmış olduğu halde baskı altında kalanlar için değil, fakat gönüllerinin kapısını inkârcılığa açanlar için geçerlidir."},{"n":107,"t":"Çünkü onlar dünya hayatını ahirete tercih etmişlerdir ve çünkü Allah, kâfirleri doğru yola iletmez."},{"n":108,"t":"Bunlar var ya; Allah onların kalplerini, kulaklarını, gözlerini mühürlemiştir; onlar gafillerin, (aymazların) ta kendileridirler."},{"n":109,"t":"Hiç kuşkusuz, ahirette hüsrana uğrayanlar olacaklardır."},{"n":110,"t":"Buna karşılık dinlerinden dönsünler diye çeşitli işkencelere uğratıldıktan sonra göç edenler, arkasından cihad edenler ve karşılaştıkları zorluklara sabırla katlananlar da var. Hiç kuşkusuz Rabbin, tüm bu olup bitenlerden sonra onlar hakkında affedicidir, merhametlidir."},{"n":111,"t":"O gün herkes gelip kendini savunur ve hiç kimseye haksızlık yapılmaksızın herkese yaptıklarının karşılığı tam olarak verilir."},{"n":112,"t":"Allah size bir beldeyi örnek veriyor. Bu belde güven ve huzur içinde yaşıyordu, her yandan kendisine bol rızık akıyordu. Fakat halkı, Allah’ın nimetlerine karşı nankörce davrandı. Bunun üzerine bu tutumları yüzünden Allah, sırtlarına açlık ve korku elbisesi giydirdi."},{"n":113,"t":"Gerçi onlara kendi ırklarından peygamber gelmişti, fakat onu yalanladılar. Bunun üzerine zalimlikleri yüzünden azap yakalarına yapıştı."},{"n":114,"t":"Eğer kulluğunuzu Allah’a sunuyorsanız, O’nun size bağışlamış olduğu helal ve temiz rızıklardan yiyiniz ve O’nun nimetlerine şükrediniz."},{"n":115,"t":"Allah size sadece, leşi, kanı, domuz etini ve Allah’dan başkası adına boğazlanmış hayvanları yasakladı. Kim çaresiz kalır da başkasının payına el uzatmaksızın ve zorunluluk sınırını aşmaksızın bu yasak etlerden yerse, hiç kuşkusuz Allah affedicidir, merhametlidir."},{"n":116,"t":"Kendi dillerinizle uydurduğunuz asılsız nitelemelere dayanarak «Şu helaldir, şu da haramdır» diyerek Allah adına yalan uydurmayınız. Hiç şüphesiz Allah adına yalan uyduranlar iflah olmazlar. Kurtuluşa eremezler."},{"n":117,"t":"Kısa süreli bir dünya mutluluğu tadarlar, ama acıklı bir azap onları beklemektedir."},{"n":118,"t":"Yahudilere, sana daha önce anlattığımız yiyecekleri haram kıldık. Ama biz onlara zulmetmiş değiliz, tersine onlar kendi kendilerine zulmettiler."},{"n":119,"t":"Hiç kuşkusuz Rabbin bu aşamadan sonra onlar hakkında affedicidir, merhametlidir."},{"n":120,"t":"Hiç kuşkusuz İbrahim Allah’ın buyruğuna titizlikle uyan, tek Allah’a inanmış bir önderdi, O Allah’a ortak koşanlardan değildir."},{"n":121,"t":"Rabbinin nimetlerine şükreden bir kuldu, Allah onu seçip dosdoğru yola iletmişti."},{"n":122,"t":"Biz ona dünyada iyilik verdik, ahirette ise O, kesinlikle iyi kullar arasındadır."},{"n":123,"t":"Sonra sana «İbrahim’in tek Allah ilkesine dayalı inanç sistemine uy, O Allah’a ortak koşanlardan değildi» diye vahyettik."},{"n":124,"t":"Cumartesi günü yasağı, bu konuda anlaşmazlığa düşenler (yahudiler) için kondu. Hiç şüphesiz Rabbin kıyamet günü anlaşmazlığa düştükleri konularda, haklarında hüküm verecektir."},{"n":125,"t":"İnsanları Rabbinin yoluna maharetli bir yöntemle ve güzel öğütlerle çağır, onlarla üslupların en güzel, en etkilisi ile tartış. Hiç şüphesiz Rabbin, yolundan sapanları herkesten iyi bildiği gibi, doğru yolda olanları da herkesten iyi bilir."},{"n":126,"t":"Eğer kâfirlere işkence edecekseniz, onlara, vaktiyle size yapmış oldukları işkencenin benzerini uygulayınız. Ama eğer sabrederseniz bu tutum sabredenler hesabına daha hayırlıdır."},{"n":127,"t":"Sabret, sabretmeyi ancak Allah’ın yardımı ile başarabilirsin; onlar için üzülme, çevirdikleri entrikalar ve kurdukları tuzaklar sakın canını sıkmasın."},{"n":128,"t":"Çünkü Allah kesinlikle kötülükten uzak duranlarla ve iyi davranışlarla beraberdir."}],[{"n":1,"t":"Kulu Muhammed’i bir gece Mescidi Haram’dan (Kabe’den) yola çıkararak, kendisine bazı mucizelerimizi, olağanüstülüklerimizi gösterelim diye, çevresini kutsal kıldığımız Mescidi Aksa’ya (Kudüs’e) ulaştıran Allah, her türlü noksanlıktan uzaktır. O her şeyi işiten ve her şeyi görendir."},{"n":2,"t":"Musa ya Tevrat’ı verdik ve «Bundan başkasını dayanak edinmeyiniz» diyerek bu kitabı yahudilere doğru yol kılavuzu yaptık."},{"n":3,"t":"Ey Nuh ile beraber gemiye bindirdiklerimizin soyundan gelenler! Hiç şüphesiz Nuh, şükür görevini yerine getiren bir kuldu."},{"n":4,"t":"Tevrat’ta yahudiler hakkında «Yeryüzünde iki kez kargaşa çıkaracaksınız ve bu arada parlak bir yükseliş dönemi yaşayacaksınız» diye hüküm verdik."},{"n":5,"t":"Birinci kargaşaya ilişkin ilahi cezanın vadesi gelince üzerinize son derece atılgan ve acımasız kullarımızı saldık. Bunlar evlerinizin köşe bucaklarını arayarak sizi yakalamaya giriştiler. Bu, Allah’ın yerine gelmesi kaçınılmaz bir sözü idi."},{"n":6,"t":"Sonra eski iktidarınızı size geri vererek bu düşmanlarınıza karşı üstün konuma gelmenizi sağladık. Sizi mal ve evlâd artışı ile destekledik ve sizi güçlü orduya sahip kıldık."},{"n":7,"t":"Eğer, iyilik ederseniz, kendiniz için iyilik edersiniz, eğer kötülük ederseniz, o da kendiniz içindir. Çıkaracağınız ikinci kargaşaya ilişkin cezanın vadesi gelince üzerinize salacağımız başka saldırganlar acınızın yüzlerinize yansımasına yol açarlar. İlk seferinde gelenlerin yaptıkları gibi Mescid- ı Aksa’ya girerler ve yükselttiğiniz her şeyi yerle bir ederler."},{"n":8,"t":"Bundan sonra rabbiniz size merhametli davranır. Fakat eğer kargaşaya dönerseniz, biz de sizi tekrar cezalandırırız. Biz cehennemi kâfirler için içinden çıkılmaz bir kale yaptık."},{"n":9,"t":"Hiç kuşkusuz bu Kur’an insanları en doğru yola iletir ve iyi ameller işleyen mü’minlere, kendilerini büyük bir ödülün beklediği müjdesini verir."},{"n":10,"t":"Ahirete inanmayanlara gelince, onlar için acıklı bir azap hazırladığımızı bildirir."},{"n":11,"t":"İnsan iyiliğe kavuşması için dua ettiği gibi aynı yönelişle başına kötülük gelsin diye de dua eder. Gerçekten insan pek aceleci, pek fevridir."},{"n":12,"t":"Gece ile gündüzü varlığımızın ve yetkin gücümüzün iki ayeti, iki somut göstergesi olarak yarattık. Sonra Rabbinizin lütfu peşinde koşasınız ve yılların sayısı ile takvim hesabını bilesiniz diye geceyi karartarak gündüzü aydınlık yaptık. Her konuyu ayrıntılı biçimde anlattık."},{"n":13,"t":"Her insanın amelini halka yapıp boynuna takarız. Kıyamet günü açık olarak bulacağı bir amel defteri önüne çıkarırız."},{"n":14,"t":"\"Kitabını oku, bugün, kendi hesabını kendin göreceksin.\""},{"n":15,"t":"Kim doğru yolu izlerse kendisi için izler. Kim doğru yoldan saparsa kendi zararına sapıtmış olur. Hiç kimse bir başkasının günah yükünü taşımaz. Bir peygamber göndermedikçe hiç kimseyi azaba çarptırmayız."},{"n":16,"t":"Biz bir beldeyi yoketmek istediğimizde oranın şımarık ele başlarına emrederiz de kötülüğe dalarlar. Böylece o belde hakkında hükmümüz haklılık kazanır. Bunun üzerine orayı alt üst ederiz."},{"n":17,"t":"Biz Nuh’tan sonra gelen nice milletleri yokettik. Kulların günahlarından haberdar olucu ve onları görücü merci olarak Rabbin yeterlidir."},{"n":18,"t":"Kim geçici dünyanın mutluluğunu isterse dilediğimiz kimselere orada dilediğimiz kadar geçici nimet veririz. Fakat sonra onu cehenneme yollarız, horlanmış ve Allah’ın rahmetinden kovulmuş olarak oraya girer."},{"n":19,"t":"Buna karşılık, kim ahiret mutluluğunu ister de mü’min olmak şartı ile o uğurda gerekli çabayı harcarsa, böylelerinin çabaları takdir edilir, emeklerinin karşılığını alırlar."},{"n":20,"t":"Her iki grubu da yani berikilere de ötekilere de Rabbinin bağışından pay veririz. Hiç kimse Rabbinin bağışından mahrum edilmez. Onun bağış kapısı herkese açıktır."},{"n":21,"t":"Bir baksana, insanları dünyada nasıl birbirinden üstün kıldık. Oysa ahiretin dereceleri daha büyük olduğu gibi, aralarındaki üstünlük farkları daha geniş çaplıdır."},{"n":22,"t":"Allah’a yanısıra başka bir ilaha tapma. Yoksa horlanmış ve koruyucusuz bırakılmış olarak otura kalırsın."},{"n":23,"t":"Allah yalnız kendisine kulluk sunmanı ve ana babana karşı nazik davranmanı kesin hükme bağladı. Eğer ana babadan biri ya da her ikisi yanında yaşlılık çağına ererlerse, sakın onlara «öf be, bıktım senden» deme, onları azarlama; onlara tatlı ve saygılı sözler söyle."},{"n":24,"t":"Onlara karşı besleyeceğin acıma duygusunun etkisi ile önlerinde alçak gönüllülük kanatlarını indir ve de ki; «Ey Rabbim onlar küçükten beni nasıl büyüttüler ise, sen de öyle merhamet et.»"},{"n":25,"t":"Rabbiniz kalplerinizdeki duygularınızı herkesten iyi bilir. Eğer iyi kalpli kimselerseniz, O kendisine başvuranların günahlarını affeder."},{"n":26,"t":"Akrabalarına, yoksula ve yarı yolda kalan yolcuya hakkını ver. Fakat savurganca davranma."},{"n":27,"t":"Çünkü savurganlar; harcamalarında ölçü gözetmeyenler, şeytanın kardeşleridir ve şeytan da Rabbine karşı son derece nankördür."},{"n":28,"t":"Eğer Rabbinden umduğun bir bağışın beklentisi içinde o hak sahiplerinin haklarını verememenin ezikliği ile yüzlerine bakamıyorsun, bari onlara tatlı söz söyle."},{"n":29,"t":"Elini sıkıp boynuna bağlama (cimri olma) onu büsbütün de açma; sonra kınanmış ve eli boş kalırsın."},{"n":30,"t":"Rabbin dilediğine geniş rızık verir ve dilediğinin rızkını kısıtlar. Hiç şüphesiz O, kullarını iyi görür, onların durumundan yakından haberdardır."},{"n":31,"t":"Yoksulluk kaygısıyla evlâtlarınızı öldürmeyiniz. Onların da sizin de rızkınızı veren biziz. Onları öldürmek ağır bir suçtur."},{"n":32,"t":"Sakın zinaya yaklaşmayınız. Çünkü o iğrenç bir kötülük ve kötü sonuçlu bir yoldur."},{"n":33,"t":"Allah’ın dokunulmaz saydığı cana, gerekçesiz olarak kıymayınız. Gerekçesiz olarak öldürülen kimsenin aile temsilcisine, velisine yetki tanıdık. Ama o da ’cana karşılık can’ sınırlarını aşmasın. Çünkü yasalar kendisine arka çıkmıştır."},{"n":34,"t":"Erginlik çağına erişinceye kadar yetimin malına sadece niyetlerin en güzeli ile yaklaşınız. Verdiğiniz sözleşmeyi tutunuz. Çünkü verdiğiniz sözlerden sorguya çekileceksiniz."},{"n":35,"t":"Bir şey ölçerken tam ölçünüz, tartılarınızda doğru terazi kullanınız. Bu tutum hem dünyada daha hayırlıdır, hem de ahirete ilişkin sonucu bakımından daha güzeldir."},{"n":36,"t":"Bilmediğin şeyin ardına düşme. Çünkü kulak, göz, kalp var ya, bunların hepsi konusunda sorguya çekileceksiniz."},{"n":37,"t":"Yeryüzünde şımarıklık taslayarak yürüme. Çünkü sen ne yeri delebilirsin, ve ne de boyca dağlara erebilirsin."},{"n":38,"t":"Saydığımız bütün bu davranış ve tutumların kötü olanları, Rabbin tarafından çirkin ve iğrenç sayılmışlardır."},{"n":39,"t":"Bunlar, Rabbinin sana vahiy yolu ile bildirdiği bazı hikmetlerdir. Sakın Allah’ın yanısıra başka bir ilaha tapma. Yoksa yerilmiş ve Allah’ın rahmetinden kovulmuş olarak cehenneme atılırsınız."},{"n":40,"t":"Rabbiniz oğulları size ayırdı da kendisi meleklerden kızlar mı edindi? Siz gerçekten çok ağır; son derece küstahça bir söz söylüyorsunuz."},{"n":41,"t":"Kâfirler öğüt alıp, akıllarını başlarına toplasınlar diye bu Kur’an’da çeşitli uyarı yöntemleri kullandık. Fakat bu farklı uyarılar onların gerçekten daha da uzaklaşmalarından başka bir şeye yaramamıştır."},{"n":42,"t":"Ey Muhammed de ki; «Eğer müşriklerin dedikleri gibi evrende Allah’ın yanısıra başka ilahlar olsaydı, bu ilahlar Arş’ın ve kesin egemenliğin sahibi olan Allah ile boy ölçüşmenin yolunu ararlardı.»"},{"n":43,"t":"Haşa, O, onların saçma yakıştırmalarından uzaktır, yücedir, büyüktür."},{"n":44,"t":"Yedi kat gök, yer ve buralardaki varlıkların tümü O’nu tenzih ederler, noksanlıklardan uzak olduğunu dile getirirler. Evrendeki her varlık, O’nu överek tesbih eder, fakat siz bu varlıkların tesbihlerini anlayamazsınız. Hiç kuşkusuz O, kullarına karşı yumuşaktır, affedicidir."},{"n":45,"t":"Ey Muhammed, sen Kur’an okurken, seninle ahirete inanmayanlar arasına görünmez bir perde gereriz."},{"n":46,"t":"Kur’an’ı kavramasınlar diye kalplerini bir kılıfla kaplarız ve kulaklarının işitme yeteneğini zayıflatırız. Allah’ın ortaksız birliğini dile getiren Kur’an ayetlerini okuduğun zaman arkalarını dönüp kaçarlar."},{"n":47,"t":"Onların seni dinlerken ne maksatla dinlediklerini, sonra aralarında neler fısıldaştıklarını ve o zalimlerin müslümanlara «Siz kesinlikle büyülenmiş bir adamın peşinden gidiyorsunuz» dediklerini iyi biliyoruz."},{"n":48,"t":"Senin hakkında nasıl benzetmeler, ne tür yakıştırmalar yaptıklarına baksana! Sapıttılar, bir türlü doğru yolu bulamıyorlar."},{"n":49,"t":"Dediler ki; «Biz kemik ve toz haline dönüştükten sonra diriltilerek yaradılışın yeni bir aşamasına mı geçeceğiz?"},{"n":50,"t":"Onlara de ki; «İster taş olunuz, ister demir olunuz."},{"n":51,"t":"İster (canlılık olayı ile ilişkili olabileceğini) hafızalarınızın almadığı başka bir yaratık olunuz.» Diyecekler ki «Bizi kim yeniden diriltecek? De ki «Sizi ilk kere yoktan vareden... O zaman şaşkın şaşkın başlarını sallayarak «Peki ne zaman?» diyecekler. Onlara de ki; «Belki de yakında.»"},{"n":52,"t":"O gün Allah sizi çağırınca kendisine hamdederek çağrısına uyarsınız ve dünyada çok kısa bir süre kaldığınızı sanırsınız."},{"n":53,"t":"Mü’min kullarıma de ki; konuşurken en güzel sözleri söylesinler. Çünkü şeytan aralarındaki havayı gerginleştirir. Hiç kuşkusuz, şeytan insanın açık düşmanıdır."},{"n":54,"t":"Ey insanlar, Rabbiniz sizi herkesten iyi bilir. Dilerse size merhamet eder, dilerse azaba çarptırır. Biz seni onların davranışlarının sorumlusu olarak göndermedik."},{"n":55,"t":"Rabbin gerek göktekileri (melekleri) ve gerekse yerdekileri (insanları) herkesten iyi bilir."},{"n":56,"t":"«Allah dışında ilah olduklarını sandığınız putları imdada çağırınız bakalım. Onlar, başınızdaki belayı ne giderebilirler ve ne de başka birine aktarabilirler.»"},{"n":57,"t":"İmdada çağrılan bu ilahların Allah’a en yakın olanları dahil olmak üzere hepsi Allah’a yaklaşmanın yolunu ararlar. O’nun rahmetini diler ve azabından korkarlar. Çünkü Rabbinin azabı korkunçtur."},{"n":58,"t":"Kıyamet gününden önce her şehri ya yıkacak ya da ağır azaba uğratacağız. Bu hüküm kitapta yazılıdır."},{"n":59,"t":"Bizi somut mucizeler ortaya koymaktan alıkoyan sebep, daha önceki milletlerin bu tür mucizeleri yalanlamaları (ve bu yüzden ağır azaba çarptırılmayı haketmeleridir) Semudoğulları’na açık mucize olarak deveyi verdik. Fakat ona karşı zalimce davrandılar. Biz somut mucizeleri sadece insanları korkutmak için ortaya koyarız."},{"n":60,"t":"Ey Muhammed, hani sana «Rabbin insanları (Mekkeli müşrikleri) kuşatma altına aldı» dedik. (O gece) sana gösterdiğimiz görüntüleri ve Kur’an’da adı geçen lanetlenmiş ağacı da sırf insanlara bir sınav konusu olsun diye ortaya koyduk. Onları korkutuyoruz ama bu korkutmalarımız azgınlıklarını arttırmaktan başka bir işe yaramıyor."},{"n":61,"t":"Hani meleklere «Adem’e secde ediniz» dedik. Hepsi secde etti, yalnız İblis emrimize karşı geldi ve «Ben çamurdan yarattığın bir canlıya hiç secde eder miyim» dedi."},{"n":62,"t":"İblis dedi ki; «Benden üstün tuttuğun şu canlıyı görüyor musun? Eğer bana kıyamet gününe kadar mühlet verirsen, onun soyunu, pek az bir bölümü dışında, avucumun içine alıp mahvederim."},{"n":63,"t":"«Defol git. Onun soyundan kim sana uyarsa onlarla senin ortak ve yeterli cezanız cehennemdir."},{"n":64,"t":"Gücünün yettiklerini sesinle ayartıp siperlerinden çıkar, atlılarını ve piyadelerini nara attırarak, üzerlerine çullandır, mallarına ve evlâtlarına ortak ol, onlara çeşitli vaadler yap, şeytanın insanlara yaptığı vaadler aldatmacadan başka bir şey değildir."},{"n":65,"t":"Benim gerçek kullarıma gelince, senin onlar üzerinde hiçbir nüfuzun yoktur. Allah, onlar için yeterli koruyucudur."},{"n":66,"t":"Rabbinizin size sunduğu nimetleri arayasınız diye gemileri denizde yüzdüren O’dur. Hiç şüphesiz O, size karşı pek merhametlidir."},{"n":67,"t":"Eğer denizde başınıza bir bela gelirse, Allah dışında imdada çağırdığınız ilahlar ortalıkta görünmez olur. Allah sizi kurtarıp karaya çıkarınca O’na sırt çevirirsiniz. İnsan gerçekten son derece nankördür."},{"n":68,"t":"Allah’ın sizi karadayken yerin dibine geçirmeyeceğinden ya da üzerinize taş yağdırmayacağından emin misiniz ki, bu olayların arkasından bir koruyucu bulamazsınız."},{"n":69,"t":"Ya da Allah’ın sizi tekrar denize döndürüp üzerinize şiddetli bir kasırga estirmek suretiyle kâfirliğinizden ötürü sizi boğmayacağından emin misiniz ki, böyle bir olay üzerine bizden tazminatınızı isteyebilecek birini bulamazsınız."},{"n":70,"t":"Biz Ademoğulları’nı gerçekten çeşitli ayrıcalıklarla donattık. Onlara karada ve denizde taşıtlar sağladık, kendilerine temiz besin maddeleri bağışladık, onları yarattığımız diğer canlıların çoğundan üstün kıldık."},{"n":71,"t":"Biz o gün bütün insan gruplarını önderleri ile birlikte huzurumuza çağırırız. Kimlere amel defterleri sağ taraftan verilirse, onlar defterlerini sevine sevine okurlar. Onlara kıl kadar haksızlık edilmez."},{"n":72,"t":"Bu dünyada gerçekler karşısında kör olan kimse ahirette de kör, doğru yoldan sapmışlık oranı da daha büyük olur."},{"n":73,"t":"Ey Muhammed, müşrikler az kalsın seni, indirdiğimiz vahiyden ayırıp adımıza başka sözler uydurmanı sağlıyorlardı, eğer bunu başarabilselerdi, seni dost edineceklerdi."},{"n":74,"t":"Eğer sana direnme gücü vermeseydik, azıcık onlara yanaşmak üzereydin."},{"n":75,"t":"Eğer onlara yanaşsaydın sana dünya hayatının ve ölüm ötesinin azabını katlayarak tattırırdık da bize karşı kendine yardım edebilecek hiç kimse bulamazdın."},{"n":76,"t":"Gerçi müşrikler seni tedirgin ederek, bıktırarak Mekke’den çıkarmak amacındadırlar, ama o takdirde senden sonra orada ancak kısa bir süre kalabilirler."},{"n":77,"t":"Senden önce gönderdiğimiz peygamberlere ilişkin değişmez yasamız bu yolda işleye gelmiştir. Bizim yasamızın değiştiğini göremezsin."},{"n":78,"t":"Ey Muhammed, güneşin batmaya yöneldiği andan, gece kararıncaya kadar namaz kıl, sabahleyin Kur’an okumayı da ihmal etme. Çünkü sabahleyin okunan Kur’an’ı izleyen (melek)ler vardır."},{"n":79,"t":"Gecenin bir bölümünde sırf sana mahsus bir nafile olmak üzere Teheccüd ibadetini yap ki, belki Rabbin seni «övülmüş makam»’a erdirir."},{"n":80,"t":"De ki; «Ey Rabbim, bir yere girerken oraya doğru olarak girmemi ve bir yerden çıkarken oradan doğruluk ilkesine bağlı olarak çıkmamı nasip eyle. Bana kendi katından destekleyici bir güç ver.»"},{"n":81,"t":"De ki; «Hak geldi, batıl yokoldu. Zaten batıl yokolmaya mahkumdur.»"},{"n":82,"t":"Kur’an’da mü’minler için şifa ve rahmet olan ayetler indiriyoruz. Fakat bu ayetler zalimlere sadece yeni yıkımlar, yeni kayıplar getirirler."},{"n":83,"t":"Biz insana nimet verdiğimiz zaman sırt çevirir, bizden uzaklaşır. Başına bir kötülük gelince de umutsuzluğa kapılır."},{"n":84,"t":"De ki; «Herkes kendi kişiliği ve inancı uyarınca hareket eder. Rabbiniz kimin daha doğru yolda olduğunu herkesten daha iyi bilir.»"},{"n":85,"t":"Sana ruh hakkında soru sorarlar. De ki; «Ruh Rabbimin tekelinde olan bir olgudur. Size bilginin çok az bir bölümü verilmiştir. (Tercih edilen görüşe göre bu soruyu kitap ehli sormuştu. Bu ayet ve ondan sonraki yedi ayet yine bu görüşe göre Medine’de inmişlerdi.)"},{"n":86,"t":"İstesek sana vahiy yolu ile indirdiğimiz mesajları tümü ile ortadan kaldırırız. Sonra bu konuda bize karşı senin savunmanı üstlenebilecek birini bulamazsın."},{"n":87,"t":"Bunun böyle olmayışı, Rabbinin sana yönelik rahmetidir. Onun sana yönelik lütfu büyüktür."},{"n":88,"t":"De ki; «Eğer tüm insanlar ve cinler bu Kur’an’ın bir benzerini ortaya koymak amacı ile biraraya gelseler, ne kadar birbirlerine yardım etseler de onun bir benzerini ortaya koyamazlar.»"},{"n":89,"t":"Andolsun, bu Kur’an’da insanlar için her tür örneği çeşitli şekillerde açıkladık. Ama insanların çoğu inkarda ayak diretti."},{"n":90,"t":"Bunlar dediler ki; «Bize yer altından pınarlar fışkırtmadıkça sana kesinlikle inanmayız."},{"n":91,"t":"Ya da kendi hurmalıkların ve üzüm bağların olmalı, bunların arasından ırmaklar akıtmalısın."},{"n":92,"t":"Ya da iddia ettiğin gibi göğü parça parça başımıza indirmeli, yahut Allah’ı ve melekleri karşımıza getirmelisin."},{"n":93,"t":"Ya da altından bir köşkün olmalı veya göğe çıkmalısın. Gökte bize okuyabileceğimiz somut bir kitap indirmedikçe de oraya çıktığına kesinlikle inanmayız.» Onlara de ki; «Subhanallah! Ben peygamberlikle gönderilmiş bir insandan başka bir şey miyim ki?»"},{"n":94,"t":"«Allah bir insanı mı peygamber olarak gönderdi?» şeklindeki anlayışlarıdır."},{"n":95,"t":"De ki; «Eğer yeryüzünde doğallıkla, rahatça gezinen melekler yaşasaydı, onlara gökten melek kökenli bir peygamber gönderirdik.»"},{"n":96,"t":"De ki; «Benimle sizin aranızda Allah’ın şahitliği yeterlidir. O kullarının yaptıkları her işten haberdardır ve her şeyi görür.»"},{"n":97,"t":"Allah kimi doğru yola iletirse o doğru yolda olur. Kimleri saptırırsa da onlar için kendisinden başka bir kurtarıcı bulamazsın. Kıyamet günü biz onları kör, dilsiz ve sağır olarak yüzüstü süründürürüz. Varacakları yer cehennemdir. Oranın ateşi sönmeye yüz tuttukça onu yeniden tutuştururuz."},{"n":98,"t":"Onların cezaları budur. Çünkü ayetlerimizi yalanlamışlar ve «Biz kemik ve toz haline dönüştükten sonra diriltilerek yaratılışın yeni bir aşamasına mı geçeceğiz?» demişlerdi"},{"n":99,"t":"Onlar gökleri ve yeri yoktan vareden Allah’ın kendi benzerlerini bir kez daha yaratmaya gücünün yeteceğini görmüyorlar mı? Üstelik Allah onlar için bir gün sona ereceği kuşkusuz olan sınırlı bir yaşama süresi belirledi. Buna rağmen bu zalimler kâfirlikte direndiler."},{"n":100,"t":"Onlara de ki; «Rabbimin rahmet hazineleri sizin elinizde olsa, bu hazineler tükenir kaygısı ile kimseye bir şey vermezdiniz. Zaten insan son derece cimridir.»"},{"n":101,"t":"Biz Musa’ya dokuz somut mucize verdik. Sor İsrailoğulları’na istersen. Musa onlara peygamber olarak geldiğinde, Firavun kendisine «Ya Musa, benim görüşüme göre sen büyülenmişsin» dedi."},{"n":102,"t":"Musa ona dedi ki; «Bu mucizelerin, getirdiğimiz ilahi mesajın gerçek olduğunu gösteren kanıtlar olarak yerin ve göklerin Rabbi tarafından gönderildiklerini kesin biliyorsun. Ey Firavun, bana göre sen mahvolmaya aday oluyorsun.»"},{"n":103,"t":"Firavun İsrailoğulları’nı yurtlarından sürmek istedi, biz onu yanındakiler ile birlikte denizde boğuverdik."},{"n":104,"t":"Onun ardından İsrailoğulları’na «Bu ülkede oturunuz. Ahiret günü gelince sizleri hep birlikte mahşerde biraraya getiririz» dedik."},{"n":105,"t":"Biz Kur’an’ı Hak içerikli olarak indirdiğimiz gibi, onun iniş amacı da hakkı gerçekleştirmektir. Ey Muhammed, seni müjdeleyici ve uyarıcı olarak gönderdik."},{"n":106,"t":"Kur’an’ı insanlara ağır ağır okuyasın diye bölümlere ayırdık ve ihtiyaçlar gerektikçe bölüm bölüm indirdik."},{"n":107,"t":"De ki; «Siz bu Kur’an’a ister inanın, ister inanmayın, o bundan önce kendilerine bilgi verilenlere okunduğunda, onlar çeneleri üzerine secdeye kapanırlar.»"},{"n":108,"t":"Ve derler ki, «Rabbimizin şanı yücedir, O’nun verdiği söz kesinlikle yerine gelecektir.»"},{"n":109,"t":"Çeneleri üzerine secdeye kapanırlarken, gözyaşları dökerler. Kur’an onları ürpertir, saygılarını artırır."},{"n":110,"t":"De ki; «Onu ister «Allah» diye çağırın, ister «Rahman» diye çağırın. Hangisiyle çağırırsanız çağırın, en güzel isimler O’nundur. Namazda sesini fazla yükseltme, fazla da kısık tutma, bu ikisi arasında bir yol tut.»"},{"n":111,"t":"De ki; «Hamd, çocuk edinmemiş olan, egemenlikte ortağı bulunmayan ve güçsüzlüğünü telafi edecek bir destekçiye gerek duymayan Allah’a mahsustur.» O’nun büyüklüğünü gereğince dile getir."}],[{"n":1,"t":"Hiçbir çarpık yeri olmayan, bu tutarlı kitab’ı (Kur’an’ı) kulu Muhammed’e indiren Allah’a hamdolsun."},{"n":2,"t":"Peygamber, insanları, Allah’dan gelecek ağır bir azap konusunda uyarsın ve iyi amel işleyen mü’minlere de kendilerini iyi bir ödülün beklediği müjdesini versin diye bu dosdoğru kitap indirildi."},{"n":3,"t":"Mü’minler o ödül yerinde (cennette) sürekli kalacaklardır."},{"n":4,"t":"Bir de «Allah evlat edindi» diyenleri uyarsın diye."},{"n":5,"t":"Allah’ın evlat edindiği konusunda ne onların ve ne de atalarının hiçbir bilgisi yoktur. Rastgele ağızlarından çıkan bu söz ne ağır bir iftiradır! Söyledikleri, yalandan başka bir şey değildir."},{"n":6,"t":"Ey Muhammed, eğer onlar bu yeni mesaja (Kur’ana) inanmazlarsa, arkalarından duyacağın üzüntü sebebi ile neredeyse kendini mahvedeceksin."},{"n":7,"t":"Biz dünyadaki her şeyi yeryüzünün süsü yaptık. Amacımız, insanları sınavdan geçirerek hangilerinin daha iyi işler yapacaklarını görmektir."},{"n":8,"t":"Günü gelince yeryüzünün bütün gözalıcı yeşilliklerini kesinlikle kupkuru bir toprak düzlüğüne çevireceğiz."},{"n":9,"t":"Sen «Ashab-ı Kehf» ve «Ashab-ı Rakım» olayının, bizim şaşırtıcı mucizelerimizden biri olduğunu mu sanıyorsun?"},{"n":10,"t":"Hani birkaç genç o mağaraya sığınmışlar ve «Ey Rabb’imiz, bize katından rahmet bağışla ve şu işimizde bize çıkış yolu göster» dediler."},{"n":11,"t":"Bunun üzerine onları mağarada yıllarca uykuya yatırdık."},{"n":12,"t":"Sonra iki gruptan hangisinin ne kadar uyuduklarını doğru olarak hesap edebileceğini belirlemek üzere onları uyandırdık."},{"n":13,"t":"Biz sana onların hikâyelerini doğru olarak anlatıyoruz. Onlar Râbb’lerine inanmış, bir grup gençti; onların hidayet bilincini arttırmıştık."},{"n":14,"t":"Kalplerini pekiştirmiştik. Hani, kâfirlerin karşısına dikilip şöyle demişlerdi; «Bizim Rabb’imiz, göklerin ve yerin Rabb’idir; O’ndan başkasına yalvarmayız, yoksa saçmalamış oluruz.»"},{"n":15,"t":"Şu soydaşlarımız, Allah’ı bir yana bırakarak çeşitli ilahlar edindiler, onların gerçekten ilah olduklarına ilişkin kesin delil göstermeleri gerekmez mi? Allah’a karşı yalan uydurandan daha zalim kim olabilir?"},{"n":16,"t":"İçlerinden biri dedi ki; «Madem ki, soydaşlarınızla ve onların Allah’ı bir yana bırakarak taptıkları ile ilişkinizi kestiniz, öyleyse mağaraya sığınınız, Rabb’iniz engin rahmetinden size bir pay göndersin ve şu işinizde size kurtuluş yolu göstersin."},{"n":17,"t":"Eğer orada olsaydın görecektin ki, doğan güneşin ışınları mağaralarının sağına sapıyor, batan güneşin ışınları ise sol tarafa kayıyordu. Böylece mağara tabanının geniş bir alanına dağılmış olarak uyudukları halde güneşten rahatsız olmuyorlardı. Bu olay, Allah’ın mucizelerinden biridir. Allah kimi doğru yola iletirse, o doğru yolu bulur. O kimi saptırırsa sen ona, doğru yola iletici bir önder bulamazsın."},{"n":18,"t":"Onları görseydin, uyanık sanırdın; oysa uyuyorlardı. Biz onları gâh sağ yanlarına, gâh sol yanlarına çeviriyorduk. Köpekleri de ön ayaklarını mağaranın eşiğine dayamıştı. Eğer karşılarına çıksan hemen geri dönüp kaçardın, içine saldıkları korkudan ödün patlardı."},{"n":19,"t":"Sonra da günün birinde onları uyandırdık. Uyanınca birbirlerine soru sormaya başladılar. İçlerinden biri arkadaşlarına «Burada ne kadar kaldınız?» dedi. Arkadaşları «Birgün ya da daha az bir süre kaldık» dediler. Arkasından dediler ki; «Ne zamandan beri burada olduğumuzu Allah hepinizden iyi bilir. Şimdi şu gümüş para ile birinizi şehre gönderin de en temiz yiyeceği kimin sattığına baksın, birazını size getirsin. Fakat dikkatli olsun da kesinlikle burada olduğunuzu hissettirmesin.»"},{"n":20,"t":"Çünkü eğer hemşehrileriniz sizi ele geçirirlerse ya taşa tutarak öldürürler ya da kendi dinlerine döndürürler ki, o taktirde bir daha iflah olmazsınız.»"},{"n":21,"t":"Böylece hemşehrilerinin onları bulmalarını sağladık. Amacımız, Allah’ın vaadinin gerçek olduğunu, kıyamet gününün mutlaka geleceğini, bunda hiçbir kuşku olmadığını öğrenmeleridir. Hemşehrileri o sırada bu gençlerin durumunu tartışmaya koyuldular. Bir bölümü ’Uyudukları mağaranın önüne bir anıt dikin, Rabb’leri onları hepimizden iyi bilir’ dedi. Fakat inançlarının içyüzünü iyi bilenler ise ’Mağaralarının önünde mutlaka bir mescid yapacağız’ dediler."},{"n":22,"t":"Ey Muhammed, kimileri «Onlar üç kişi idi, dördüncüleri köpekleridir», kimileri «beş kişi idiler, altıncıları köpekleridir» diyeceklerdir. Bu sözler karanlığa taş atmaktır. Kimileri de «yedi kişi idiler, sekizincileri köpekleridir» diyeceklerdir. De ki; «Onların sayısını hepimizden iyi Rabb’im bilir.» Onlar hakkında derine dalan bir tartışmaya girme ve bu olay konusunda hiç kimseye bir şey sorma."},{"n":23,"t":"Hiçbir iş hakkında «Bunu yarın yapacağım» deme."},{"n":24,"t":"Bunun yerine, «Allah dilerse (inşaallah) yarın bu işi yapacağım» de. Böyle demeyi unuttuğunda ise Rabb’ini an ve «Umarım ki, beni şimdikinden daha çok doğruya yaklaştırır» de."},{"n":25,"t":"Kimileri derler ki, «O gençler mağarada üçyüz yıl kaldılar.» Buna dokuz daha eklerler."},{"n":26,"t":"De ki; «Onların mağarada ne kadar kaldıklarını herkesten iyi bilen Allah’dır. Göklerin ve yeryüzünün sırlarının bilgisi O’nun tekelindedir. O ne güzel görür ve ne güzel işitir. İnsanların O’nun dışında başka bir koruyucuları, başka bir önderleri yoktur ve O egemenliğine hiç kimseyi ortak etmez.»"},{"n":27,"t":"Sana vahyedilen Rabb’inin kitabını oku. Allah’ın sözlerini hiç kimse değiştiremez ve O’nun dışında sığınabileceğin başka bir kimse bulamazsın."},{"n":28,"t":"Sırf Rabb’lerinin rızasını dileyerek sabah akşam O’na yalvaranlarla birarada olmaya kendini zorla. Dünya hayatının çekiciliğini isteyerek böyle kimseleri gözardı etme. Adımızı anmayı kalbine unutturduğumuz ve ihtiraslarına tutsak olarak kendini akıntıya kaptırmış kimselerin arzularına uyma."},{"n":29,"t":"Onlara «Bu Kur’an, Allah tarafından gönderilmiş bir gerçektir, isteyen inansın, isteyen inkar etsin» de. O ateşe atılanlar «su, su» diye feryad ettiklerinde çığlıklarına karşılık kendilerine ergimiş metal gibi yüzleri kavuran bir sıvı sunulur. O ne fena bir içecek ve orası ne fena bir barınaktır."},{"n":30,"t":"İman edip iyi ameller işleyenlere gelince, biz iyilik yapanları kesinlikle ödülsüz bırakmayız."},{"n":31,"t":"Onlar için altlarından çeşitli ırmaklar akan Adn cennetleri vardır. Kolları altın bileziklerle süslüdür. Orada ince ve kalın ipekten yeşil elbiseler giyerek koltuklara kurulurlar. O ne güzel bir ödül ve orası ne güzel bir barınaktır."},{"n":32,"t":"Onlara şu iki adamı örnek olarak anlat. Adamlardan birine iki üzüm bağı vermiştik, bağlarını hurma ağaçları ile çevirmiş ve iki bağın arasına bir tahıl tarlası koymuştuk."},{"n":33,"t":"Bağlar meyvalarını cömertçe veriyorlar, hiçbir ürünlerini esirgemiyorlardı. İki bağ arasından bir de ırmak akıtmıştık."},{"n":34,"t":"Adamın bol serveti vardı. Bu yüzden tartışma sırasında arkadaşına dedi ki «Ben senden daha varlıklıyım ve tayfam da seninkinden daha kalabalıktır."},{"n":35,"t":"Kendine zulmetmiş olan bu adam (arkadaşını yanına alarak) bahçesine girdi ve dedi ki; «Bu bahçenin sonsuza dek yok olacağını sanmıyorum.»"},{"n":36,"t":"Kıyametin kopacağını da sanmıyorum. Ama eğer Rabb’ime döndürülecek olursam orada bundan daha iyi bir akıbetle karşılaşacağımdan eminim."},{"n":37,"t":"Aralarındaki tartışmayı sürdüren arkadaşı kendisine dedi ki; «Seni önce topraktan, sonra spermadan yaratan, sonunda da insan biçimine koyan Allah’ı inkâr mı ediyorsun?»"},{"n":38,"t":"Bana gelince, benim Rabb’im Allah’dır. O’na hiç kimseyi kesinlikle ortak koşmam."},{"n":39,"t":"Aslında bahçene girdiğinde ’Maşaellah’ gerçek güç, Allah’ın tekelindedir deseydin ya! Gerçi sen malımın ve evlatlarımın seninkilerden az olduğunu görüyorsun."},{"n":40,"t":"Fakat Rabb’im bana senin bahçenden daha iyisini verebilir ve senin bahçeni de gökten gelen bir afete uğratarak çıplak bir düzlüğe çevirebilir."},{"n":41,"t":"Ya da bahçenin suyu yerin öyle derin katmanlarına sızar ki, bir daha aramaya bile gücün yetmez."},{"n":42,"t":"Derken bahçesinin tüm ürünü ansızın yok oluverdi. Yerle bir olan üzüm kütüklerinin yıkıntıları karşısında yapmış olduğu masrafların iç yanıklığı ile vahlanmaya ve elleri ile dizlerini döverek «Keşke Rabb’ime hiç kimseyi ortak koşmasaydım» demeye koyuldu."},{"n":43,"t":"O anda ne Allah dışında, yardımına koşabilecek destekçiler bulabildi ve ne de kendi kendini kurtarabildi."},{"n":44,"t":"İşte orada koruyuculuk ve egemenlik, varlığı «gerçek» olan Allah’ın tekelindedir. En yararlı ödül ve en hayırlı akıbet yalnız O’nun katındadır."},{"n":45,"t":"Ey Muhammed, onlara anlat ki, dünya hayatı tıpkı şuna benzer. Gökten yağmur yağdırdık da bu yağmur sayesinde yer yeşermiş, güveren ekinlerin başakları birbirine girmiş. Derken bu ekinlerin tümü ansızın rüzgârların havada uçurduğu saman kırıntılarına dönüşüvermiş. Hiç kuşkusuz Allah’ın gücü her şeyi yapmaya yeter."},{"n":46,"t":"Mal ve evlatlar dünya hayatının süsüdürler. Kalıcı iyilikler ise Rabb’in katında sevap kazandırma bakımından daha yararlı ve umut kaynağı olmaya daha lâyıktırlar."},{"n":47,"t":"O gün dağları yerlerinden, söküp yürütürüz. Yeryüzünü çırılçıplak ve dümdüz görürsün. Tek bir kişiyi gözardı etmeksizin tüm insanları biraraya toplarız."},{"n":48,"t":"\"İşte sizi ilk kez yarattığımız günkü gibi, bütünüyle yapayalnız ve boyun eğmiş olarak huzurumuza geldiniz. Oysa siz, size verdiğimiz sözü yerine getirecek bir zaman tayin etmediğimizi sanmıştınız değil mi?\""},{"n":49,"t":"İnsanların amel defterleri (çalışma karneleri) ortaya getirilmiştir. Günahkârların bu defterlerin yazılarını korku dolu gözlerle incelediklerini görürsün. Bir yandan da «Vay başımıza gelenlere! Ne biçim deftermiş bu; küçük büyük hiçbir davranışımızı atlatmadan sayıp dökmüş,» derler. Yaptıkları her işin kaydını karşılarında bulmuşlardır. Rabb’in hiç kimseye haksızlık etmez."},{"n":50,"t":"Hani Rabb’in meleklere «Adem’e secde ediniz» dedi. Onlar da secde ettiler. Yalnız İblis (şeytan) secde etmedi. O cin kökenli idi ve Rabb’inin buyruğu dışına çıktı. Şimdi siz beni bırakıp onu ve soyunu dost mu ediniyorsunuz? Oysa onlar sizin düşmanlarınızdır. Zalimlerin yaptığı bu dost değişimi ne kötü tercihtir!"},{"n":51,"t":"Ben şeytanları ne gökler ile yerin yaratılışına ve ne de kendi yaratılışına tanık etmedim. Benim insanları yoldan çıkaranları kendime yardımcı tutmam sözkonusu değildir."},{"n":52,"t":"O Allah müşriklere «Benim ortaklarım olduklarını sandığınız düzmece ilahları yardıma çağırınız» der. İşte onları yardıma çağırdılar, fakat çağrılarına karşılık vermediler. Onların aralarına engel olarak bir cehennem vadisi koyduk."},{"n":53,"t":"Günahkârlar cehennem ateşini görünce oraya atılacaklarını anlarlar, fakat geri kaçarak sığınacakları bir başka yer bulamazlar."},{"n":54,"t":"Biz bu Kur’an’da insanlara her türlü örneği verdik. Fakat insan, tartışmaya son derece düşkün bir varlıktır."},{"n":55,"t":"İnsanlara doğru yola ileten bilgi geldikten sonra onların iman etmelerine ve tövbe edip Allah’a yönelmelerine engel olan tek şey, eski sapık milletler hakkında işleyen ilahi yasaların kendileri hakkında da işlemesini ya da somut azapla yüzyüze gelmeyi beklemeleridir."},{"n":56,"t":"Biz Peygamberleri sadece müjdeleyici ve uyarıcı olarak göndeririz. Oysa kâfirler hakkı (gerçeği) batıl (eğri) karşısında yenik düşürmeye uğraşırlar. Onlar ayetlerimi ve kendilerine yönelik uyarılarımı alaya aldılar."},{"n":57,"t":"Allah’ın ayetleri kendisine hatırlatıldığı halde, onlara sırt çevirenden ve işlediği kötülükleri hiç hatırına getirmeyenden daha zalim kim olabilir? Biz onların kalplerini, Kur’anı anlamalarına engel oluşturacak biçimde perdeledik ve kulaklarını sağırlaştırdık. Bu yüzden sen onları doğru yola çağırsan da doğru yola gelmezler."},{"n":58,"t":"Affedici ve merhametli Rabb’in, eğer onları kötülükleri karşılığında hemen cezalandırmak isteseydi, azaplarını çabuklaştırırdı. Fakat onların belirli bir vadesi vardır, o zaman gelince, kaçıp saklanacakları bir sığınak bulamazlar."},{"n":59,"t":"İşte şu kentler, halklarının zalimlikleri yüzünden onları yok ettik ve yok oluşları için belirli bir vakit kararlaştırdık."},{"n":60,"t":"Hani Musa, genç arkadaşına «Hiçbir güç beni durduramaz, ya iki denizin birleştiği yere varırım, ya da yıllarca yol yürürüm» demişti."},{"n":61,"t":"İki denizin birleştiği yere vardıklarında yanlarındaki balığı bir kenarda unuttular, o da bir yeraltı deliğinden kayarak denize kaçtı."},{"n":62,"t":"İki denizin birleştiği yeri geçtiklerinde Musa, genç arkadaşına, «Azığımızı getir bakalım, gerçekten bu yolculuğumuzda çok yorgun düştük» dedi."},{"n":63,"t":"Genç arkadaşı Musa’ya «Bak sen! Kayalığa vardığımızda balığı unutmuştum, bana onu hatırlatmayı unutturan mutlaka şeytandır, balık şaşırtıcı bir şekilde canlanarak denize kaçtı» dedi."},{"n":64,"t":"Musa; «Bizim aradığımız da buydu zaten» dedi. Hemen geldikleri yoldan kendi izlerini sürerek geri döndüler."},{"n":65,"t":"Orada kendisine tarafımızdan rahmet sunduğumuz ve katımızdan dolaysız biçimde ilim öğrettiğimiz bir kulumuzu buldular."},{"n":66,"t":"Musa, ona «Sana öğretilen bilginin birazını bana öğreterek olgunlaşmamı sağlaman amacı ile peşinden gelebilir miyim?» dedi."},{"n":67,"t":"O kulumuz, Musa’ya dedi ki; «Sen benimle beraber olmaya katlanamazsın.»"},{"n":68,"t":"Sebeplerini kavrayamayacağın olaylar karşısında nasıl sabredeceksin."},{"n":69,"t":"Musa «İnşaallah, beni sabırlı bulacaksın, hiçbir konuda sana karşı gelmeyeceğim.»"},{"n":70,"t":"O kulumuz, Musa’ya dedi ki; «Eğer benimle birlikte geleceksen yapacağım hiçbir iş hakkında bana soru sorma, benim sana o konuda açıklama yapmamı bekle.»"},{"n":71,"t":"Böylece yola koyuldular. Bir süre sonra bir gemiye bindiler. O kulumuz bu gemide bir delik açtı. Musa ona, «İçindekileri boğmak için mi gemiyi deldin? Gerçekten çok çirkin bir iş yaptın» dedi."},{"n":72,"t":"O kulumuz Musa’ya «Ben sana, benimle beraber olmaya katlanamazsın dememiş miydim?» dedi."},{"n":73,"t":"Musa; «Unutkanlığım yüzünden beni azarlama ve bilginden yararlanma konusunda bana zorluk çıkarma» dedi."},{"n":74,"t":"Yine yola koyuldular. Bir süre sonra bir genç ile karşılaştılar. O kulumuz, delikanlıyı öldürdü. Musa; «Bir cana karşılık olmaksızın masum bir cana mı kıydın? Gerçekten çok kötü bir iş yaptın» dedi."},{"n":75,"t":"O kulumuz Musa’ya; «Ben sana benimle beraber olmaya katlanamazsın dememiş miydim?’ dedi."},{"n":76,"t":"\"Bundan sonra, sana birşey soracak olursam, artık bana arkadaşlık etme. Çünkü bir daha özür dilemeyecek hale geldim.\""},{"n":77,"t":"Yine yola koyuldular. Bir süre sonra bir köye vardılar. Köylüden yemek istediler, fakat ağırlanma istekleri reddedildi. Az sonra yıkılmaya yüz tutmuş bir duvarla karşılaştılar. O kulumuz, eğri duvarı doğrulttu. Musa ona ’Eğer isteseydin bu yaptığın işe karşılık bir ücret alabilirdin’ dedi."},{"n":78,"t":"O kulumuz, Musa’ya dedi ki; «Bu olay, birbirimizden ayrılmamızın sebebidir. Şimdi sana sabırla karşılayamadığın olayların nedenlerini açıklayacağım."},{"n":79,"t":"O gemi var ya, yoksul deniz işçilerinin malı idi. Onda bir kusur meydana getirmek istedim. Çünkü bu denizcileri, rastladığı her sağlam gemiye zorla el koyan bir hükümdar kovalıyordu."},{"n":80,"t":"O delikanlıya gelince, onun ana babası mü’min kimselerdi. Onları azgınlığa ve kâfirliğe sürüklemesinden çekindik."},{"n":81,"t":"İstedik ki, Rabb’leri onlara o delikanlıdan daha temiz ve daha iyiliksever bir evlat bağışlasın."},{"n":82,"t":"O duvar var ya, o şehirde yaşayan iki yetim çocuğun malı idi ve duvarın altında bu yetimlere miras kalmış bir hazine vardı. Babaları iyi bir insandı. Rabb’in istedi ki, o yetimler, erginlik çağına erdikten sonra Rabb’lerinin bir merhameti olan hazinelerini kendi elleri ile duvarın altından çıkarsınlar. Yoksa ben bu işleri kendi kafamdan yapmadım. İşte sabırla karşılayamadığın olaylara ilişkin açıklamam budur."},{"n":83,"t":"Ey Muhammed, sana Zülkarneyn hakkında soru sorarlar. Onlara de ki; «Size onun hakkında bazı düşündürücü bilgiler vereceğim.»"},{"n":84,"t":"Biz onu yeryüzünde egemen kıldık ve her amaca ulaştıracak sebebi buyruğuna sunduk."},{"n":85,"t":"O da bir sebebe sarılarak yola koyuldu."},{"n":86,"t":"Sonunda güneşin battığı yere varınca güneşi, çamurlu bir su pınarında batarken buldu. Orada rastladığı bir toplum ile ilgili olarak kendisine «Ey Zülkarneyn, onlara istersen ceza ver, istersen kendilerine iyi davran» dedik."},{"n":87,"t":"Zülkarneyn o topluma dedi ki; «Aranızdaki zalimleri cezaya çarptıracağız. Onlar, ilerde Rabb’lerinin huzuruna vardıklarında eşi görülmemiş, ağır bir azaba uğrayacaklardır."},{"n":88,"t":"İman edip iyi ameller işleyenlere gelince onları, ödüllerin en güzeli beklemektedir. Böylelerine kolay işler buyuracağız."},{"n":89,"t":"Arkasından yine bir sebebe sarılarak yola koyuldu."},{"n":90,"t":"Sonunda güneşin doğduğu yere varınca güneşi, öyle bir toplumun üzerine doğarken buldu ki, bu adamlar ile güneşin ışınları arasında hiçbir engel, hiçbir sütre koymamıştık."},{"n":91,"t":"İşte böyle, onun serüveni, bütün ayrıntıları ile bilgimizin kapsamı içindedir."},{"n":92,"t":"Arkasından yine bir sebebe sarılarak yola koyuldu."},{"n":93,"t":"Sonunda iki seddin arasına varınca setlerin berisinde nerede ise hiç söz anlamayan bir toplumla karşılaştı."},{"n":94,"t":"Bu adamlar «Ey Zülkarneyn, Ye’cuc ile Me’cuc bu yörede sürekli kargaşa çıkaran topluluklardır. Sana bir miktar mal versek, karşılığında onlar ile aramızda bir set yapar mısın?» dediler."},{"n":95,"t":"Zülkarneyn onlara dedi ki; «Rabb’imin bana bağışladığı güç, sizin bana vereceğiniz maldan daha hayırlıdır. Siz bana beden gücünüzle yardımcı olunuz da onlar ile aranıza aşılmaz bir set çekeyim.»"},{"n":96,"t":"Bana demir parçaları getiriniz. Getirdikleri demir parçalarının oluşturduğu yığını yanlardaki setlerin tepeleri ile aynı düzeye çıkarınca adamlara «körükleri çalıştırınız» dedi. Demir yığınını ateş haline getirince «Bana biraz erimiş bakır getiriniz de üzerine dökeyim» dedi."},{"n":97,"t":"Ye’cuc ile Me’cuc, bu setin ne üzerinden aşabildiler ve ne de bir yerinde delik açabildiler."},{"n":98,"t":"Zülkarneyn «Bu set, Rabb’imin rahmetidir. Fakat Rabbimin belirlediği an gelince onu yerle bir eder. Hiç kuşkusuz Rabb’imin sözü gerçektir» dedi."},{"n":99,"t":"O gün biz insan yığınlarını önce dalgalanmaya bırakırız. Sonra Sur’a üflenince hepsini biraraya toplarız."},{"n":100,"t":"O gün cehennemi, kâfirlerin gözleri önüne dikeriz."},{"n":101,"t":"Dünyada onların gözlerini, bizi hatırlarına getirmelerini engelleyen bir perde örtmüştü ve kulakları da işitme yeteneğini yitirmişti."},{"n":102,"t":"Kafirler beni bırakıp da kullarımı dost edinmelerini kafi mi sandılar? Doğrusu biz cehennemi kafirlere konak olarak hazırladık."},{"n":103,"t":"Ey Muhammed, de ki; «Çalışmalarında en ağır kayba uğrayanları size haber verelim mi?»"},{"n":104,"t":"Dünya hayatında bütün emekleri boşa gittiği halde çok iyi işler yaptıklarını sananların (kimler olduğunu size söyleyelim mi?)"},{"n":105,"t":"Bunlar, Rabb’lerinin ayetlerini ve O’nun huzuruna çıkaracaklarını inkâr edenlerdir. Bu yüzden onların iyi işleri geçersiz olmuştur. Kıyamet günü onların yaptıkları işleri tartıya almayız, kendilerine değer vermeyiz."},{"n":106,"t":"İşte onların cezası cehennemdir. Bu ceza onların inkârcı tutumlarının, ayetlerimi ve peygamberimi alaya almalarının karşılığıdır."},{"n":107,"t":"İman edip iyi ameller işleyenlere gelince onlar, Firdevs cennetlerinde ağırlanacaklardır."},{"n":108,"t":"Orada sonsuza dek kalacaklar, başka bir yere taşınmak istemeyeceklerdir."},{"n":109,"t":"De ki; «Rabb’imin sözlerini yazmak için, denizler mürekkep olsa da onlara bir o kadarını daha katsak, Rabb’imin sözleri bitmeden önce denizler biterdi.»"},{"n":110,"t":"De ki; «Ben de tıpkı sizin gibi bir insanım, yanız bana vahiy yolu ile ilahınızın tek Allah olduğu bildiriliyor. Buna göre kim açık alınla Rabb’inin huzuruna çıkmayı istiyorsa, iyi ameller işlesin ve kulluk görevlerinde hiç kimseyi Rabb’ine ortak koşmasın.»"}],[{"n":1,"t":"Kâf, ha, ya, ayn, sad"},{"n":2,"t":"Bu ayetlerde Rabbinin, kulu Zekeriyya’ya yönelik rahmeti anlatılıyor."},{"n":3,"t":"Hani O, Rabbine içinden yalvarmış."},{"n":4,"t":"Ve demişti ki; «Ey Rabbim, kemiklerim yıprandı, yaşlılık alevi başımı sardı. Şimdiye kadar sana dua edip de bedbaht olduğum hiç olmadı.»"},{"n":5,"t":"Benden sonra yerime geçecek yakınlarımdan yana endişeliyim. Eşim de çocuktan kesilmiştir. Bana kendi katından bir oğul bağışla.»"},{"n":6,"t":"Bu oğul, benim ve Yakuboğullarının mirasını sürdürsün. Ya Rabbi, onu sevimli bir insan yap.."},{"n":7,"t":"Allah dedi ki; «Ya Zekeriyya, sana Yahya adında bir oğul müjdeliyoruz. Bu adı daha önce hiç kimseye vermemiştik.»"},{"n":8,"t":"Zekeriyya dedi ki; «Benim nasıl oğlum olabilir. Eşim çocuktan kesildi, ben ise ileri derecede yaşlandım.»"},{"n":9,"t":"Allah dedi ki; «Rabbin buyurdu ki, bu iş O’nun için kolaydır, vaktiyle ben seni hiçbir şey değilken yoktan varetmiştim.»"},{"n":10,"t":"Zekeriyya, «Ya Rabbi, bunun için bana bir belirti göster» dedi. Allah, ona «Bunun belirtisi, hiçbir organik rahatsızlığının sonucu olmaksızın üç gün, üç gece hiç kimse ile konuşamamandır, bu süre içinde dilinin dönmemesidir» dedi."},{"n":11,"t":"Bunun üzerine Zekeriyya mihrapta yüzünü soydaşlarına dönerek sabahları ve akşamları Allah’ı her tür noksanlıktan tenzih etmelerini işaret etti."},{"n":12,"t":"Allah, ona «Ey Yahya, tüm gücünle kitab’a (Tevrat’a) sarıl» dedi. Ona daha çocukken bilgelik verdik."},{"n":13,"t":"Yine ona tarafımızdan sevecenlik ve kalp temizliği bağışladık. O kötülüklerden sakınan bir kimse idi."},{"n":14,"t":"Yine ona ana babasına bağlılık duygusu aşıladık. O dik kafalı, serkeş ve huysuz biri değildi."},{"n":15,"t":"Doğduğu gün, öleceği gün ve tekrar diriltileceği gün ona selâm olsun."},{"n":16,"t":"Bu Kitap’ta Meryem hakkında anlattıklarımızı da hatırla. Hani O, ailesinden ayrılarak doğu tarafında bir yere çekilmişti."},{"n":17,"t":"Komşuları ile arasına bir perde germişti. Bu sırada ona ruhumuzu (Cebrail’i) gönderdik. O, ona normal bir erkek kılığında görünmüştü."},{"n":18,"t":"Meryem, O’na «Ben senden «Rahman» olan Allah’a sığınırım. Eğer kötülük yapmaktan sakınan biri isen bana dokunma!» dedi."},{"n":19,"t":"Cebrail dedi ki; «Gerçekten ben, sana temiz bir oğlan vermek için sırf Rabbinin gönderdiği elçiyim»"},{"n":20,"t":"Meryem, Cebrail’e «Benim nasıl oğlum olabilir? Bana hiç erkek eli değmiş değildir, hiç gayri meşru ilişkim de olmadı» dedi."},{"n":21,"t":"Bu iş benim için kolaydır. Bu olayı insanlara gücümüzü kanıtlayan bir mucize ve oğlunu da onlara rahmet kaynağı olarak sunmak istiyoruz. Bu olay kesinleşmiş bir hükümdür.’’"},{"n":22,"t":"Böylece Meryem, oğluna gebe kaldı. Bu döneminde gözlerden uzak bir köşeye çekildi."},{"n":23,"t":"Bir süre sonra doğum sancıları tutunca bir hurma ağacının altına sığınmak zorunda kaldı ve «Keşke, daha önce ölmüş ve hafızalardan silinmiş olsaydım» dedi."},{"n":24,"t":"Bu arada, ayakları altından şöyle bir ses duydu; «Sakın üzülme, Rabb’in senin için ayaklarının altından akan bir dere açtı.»"},{"n":25,"t":"Hurmanın dalını silkele de üzerine olgun ve taze hurmalar dökülsün."},{"n":26,"t":"Ye, iç, gönlün rahat olsun. Eğer birini görecek olursan ’Ben Rahman olan Allah’a konuşmama orucu adadım, bu yüzden bugün hiç kimse ile konuşmayacağım’ de."},{"n":27,"t":"Bebeğini kucağına alıp yakınlarının yanına gelince kendisine dediler ki; Ey Meryem, sen çok utandırıcı bir suç işledin."},{"n":28,"t":"Ey Harun’un kız kardeşi, senin ne baban kötü bir adamdı ve ne de annen iffetsiz bir kadındı."},{"n":29,"t":"Bunun üzerine Meryem, eli ile oğlunu göstererek onunla konuşmalarını önerdi. Onlar da «Biz beşikteki çocukla nasıl konuşabiliriz?» dediler."},{"n":30,"t":"O sırada beşikteki çocuk dile gelerek dedi ki; «Ben Allah’ın kuluyum. O bana kitap vererek beni peygamber yaptı.»"},{"n":31,"t":"Nerede olursam olayım, beni insanlara yararlı kıldı. Bana sağ oldukça namaz kılmamı ve zekatı emretti."},{"n":32,"t":"Beni anama düşkün bir evlat olarak yarattı; dik kafalı ve kötülük düşkünü biri olmaktan uzak tuttu."},{"n":33,"t":"Doğduğum gün, öleceğim gün ve tekrar diriltileceğim gün Allah’ın rahmeti ve bağışı benimle birliktedir."},{"n":34,"t":"İşte «gerçek söz» e göre Meryemoğlu İsa budur, oysa insanlar bu gerçek sözü kuşku ile karşılıyorlar."},{"n":35,"t":"Allah’a oğul edinmek yakışmaz. O böyle bir şeyden münezzehtir. O bir iş hakkında kesin hüküm verince o işe sadece «ol» der, o da hemen oluverir."},{"n":36,"t":"Kuşku yok ki Allah sizin de benim de Rabb’imizdir, öyleyse sırf O’na kulluk ediniz. İşte dosdoğru yol budur."},{"n":37,"t":"Çeşitli gruplara ayrılan insanlar, aralarında görüş ayrılığına düştüler. Vaygele kâfirlerin başına! O «büyük gün» de gözleri neler görecek."},{"n":38,"t":"Karşımıza gelecekleri gün kulakları ne güzel işitecek ve gözleri ne iyi görecek. Fakat o zalimler, bugün açık bir sapıklık içindedirler."},{"n":39,"t":"Ey Muhammed, onları o hayıflanma ve pişmanlık günü hakkında uyar. Hani o gün onlar halâ gaflet içinde yüzerken ve inanmazlıklarını sürdürürlerken haklarındaki hüküm kesinleşiverir."},{"n":40,"t":"Kuşku yok ki, yeryüzünün ve oradaki tüm varlıkların son mirasçısı biz olacağız, tüm insanlar bize döndürüleceklerdir."},{"n":41,"t":"Bu kitapta İbrahim hakkında anlattıklarımızı da hatırla. O son derece doğru sözlü ve dürüst bir peygamberdi."},{"n":42,"t":"Hani babasına dedi ki; «Ey babacığım, niye işitemeyen, göremeyen ve sana hiçbir yararı olmayan putlara tapıyorsun.»"},{"n":43,"t":"Babacığım, sana ulaşmayan bir ilim, geldi bana, ne olur bana tabi ol da seni dümdüz bir yola çıkarayım."},{"n":44,"t":"Ey babacığım, sakın şeytana kul olma; çünkü o, rahmeti bol olan Allah’a baş kaldırmıştır."},{"n":45,"t":"Ey babacığım, senin Allah’dan gelecek bir azaba çarptırılarak şeytanın dostu olacağından korkuyorum."},{"n":46,"t":"Babası, ona «Ey İbrahim, sen benim taptığım tanrılara sırt mı çeviriyorsun? Eğer bu tutumundan vazgeçmezsen seni taşa tutarak öldürürüm, uzun bir süre yanımdan uzaklaş» dedi."},{"n":47,"t":"İbrahim, babasına dedi ki; «Esenlik dilerim sana. Senin adına Rabbimden af dileyeceğim, hiç kuşkusuz benim Rabbim lütufkardır.»"},{"n":48,"t":"Sizleri, Allah’ı bir yana bırakarak taptığınız putlarla başbaşa bırakarak bir yana çekiliyor ve Allah’a yalvarıyorum. Umuyorum ki, Rabbime yalvarırsam kötü olmaktan kurtulurum."},{"n":49,"t":"Nihayet İbrâhim, onlardan ve Allah’tan başka taptıkları şeylerden uzaklaşıp bir tarafa çekildiğinde, biz ona İshak ve Ya‘kûb’u bağışladık ve her birini peygamber yaptık."},{"n":50,"t":"Onlara rahmetimizden pay verdik. Her dilde saygı ile anılmalarını sağladık."},{"n":51,"t":"Bu kitapta Musa hakkında anlattıklarımızı da hatırla. O tarafımızdan seçilerek gönderilmiş bir peygamberdi."},{"n":52,"t":"Ona Tur’un sağ yanından seslendik ve kendisi ile özel olarak konuşmak için onu yakınımıza getirdik."},{"n":53,"t":"Rahmetimizin bir sonucu olarak ona kardeşi Harun’u peygamber olarak armağan ettik."},{"n":54,"t":"Bu Kitapta İsmail hakkında anlattıklarımızı da hatırla. O sözünün eri idi ve tarafımızdan gönderilmiş bir peygamberdi."},{"n":55,"t":"O yakınlarına namaz kılmayı ve zekât vermeyi emrederdi. O Rabbinin hoşnutluğunu kazanmış bir kişi idi."},{"n":56,"t":"Bu Kitapta İdris hakkında anlattıklarımızı da hatırla o son derece doğru sözlü ve dürüst bir peygamberdi."},{"n":57,"t":"Onu yüce bir konuma çıkarmıştık."},{"n":58,"t":"Bunlar nimete erdirdiği kimselerdir. Bunların kimi Adem soyundan, kimi Nuh ile birlikte gemiye bindirdiklerimizin soyundan, kimi de İbrahim ile İsrail’in soyundan gelen peygamberler ile doğru yola ilettiğimiz seçkin mü’minlerdir. Bunlar rahmeti bol Allah’ın ayetleri kendilerine okunduğunda ağlayarak secdeye kapanırlardı."},{"n":59,"t":"Bunların yerine namazı umursamayan ve ihtiraslarına tutsak olmuş kuşaklar geçti. Bu kuşaklar sapıklıklarının cezasına çarpılacaklardır."},{"n":60,"t":"Yalnız tövbe ederek iman edip iyi ameller işleyenler bu genel hükmün kapsamı dışındadırlar. Onlar cennete girecekler ve en ufak bir haksızlığa uğratılmayacaklardır."},{"n":61,"t":"Rahmeti bol Allah’ın kullarına, somut olarak göstermeden vadettiği Adn cennetlerine gireceklerdir. Allah’ın vaadi kesinlikle gerçekleşecektir."},{"n":62,"t":"Orada boş sözler değil, sadece selam sözü işitirler. Ve sabah akşam rızıklarını hazır bulurlar orada."},{"n":63,"t":"İşte kötülüklerden kaçınan kullarımızın mirasçısı olacakları için de sürekli kalacakları cennet budur."},{"n":64,"t":"Cebrail, Muhammed’e dedi ki; «Biz ancak Rabbinin izni ile yere ineriz. Geleceğimiz, geçmişimiz ve bu ikisi arasındaki tüm olaylar O’nun tasarrufu altındadır. Senin Rabbin hiçbir şeyi unutmaz"},{"n":65,"t":"O göklerin, yerin ve bu ikisi arasındaki tüm varlıkların Rabbidir. O halde sırf O’na kulluk ediniz ve bu kulluğun omuzlarına bindirdiği tüm yükümlülüklere katlanınız. O’nun bir benzerini tanıyor musun?"},{"n":66,"t":"İnsan «Ben öldükten sonra mı yeniden diriltileceğim?» der."},{"n":67,"t":"İnsan, vaktiyle hiçbir şey değilken, kendisini yoktan varettiğimizi düşünmüyor mu?"},{"n":68,"t":"Rabb’inin yüceliği hakkı için, onları peşlerinden gittikleri şeytanları ile birlikte biraraya getireceğiz, sonra da dizüstü çöktürerek cehennemin çevresinde toplayacağız."},{"n":69,"t":"Sonra her grubun, rahmeti bol olan Allah’a baş kaldıran en azılı ele başlarını ayıracağız."},{"n":70,"t":"Sonra biz onların hangilerinin öncelikle cehenneme girmeleri gerektiğini, kuşkusuz, herkesten iyi biliriz."},{"n":71,"t":"Aranızda cehenneme uğramayacak hiç kimse kalmayacaktır. Bu Rabbinin kesinleşmiş bir hükmüdür."},{"n":72,"t":"Sonra sakınanları kurtararak zalimleri, dizüstü çökmüş durumda orada bırakırız."},{"n":73,"t":"Açık ayetlerimiz okunduğu zaman kâfirler, mü’minlere «Hangimizin sosyal konumu daha üstün, hangimizin itibarı daha yüksektir» derler."},{"n":74,"t":"Oysa biz eski dönemlerde onlardan daha varlıklı ve daha gösterişli nice kuşakları yokettik."},{"n":75,"t":"Onlara de ki; «rahmeti bol olan Allah sapık yolda olanlara ne kadar geniş maddi imkân verirse versin, sonunda tehdit edildikleri somut azab ile ya da kıyamet günü ile yüzyüze geldiklerinde nasıl olsa kimin sosyal konumunun daha düşük ve kimin askeri gücünün daha zayıf olduğunu öğreneceklerdir.»"},{"n":76,"t":"Allah doğru yolda olanların sapmazlıklarını pekiştirir. Kalıcı iyi ameller, Rabb’in katında daha iyi ödül kazandırıcı ve daha mutlu akıbete erdiricidirler."},{"n":77,"t":"Ey Muhammed, şu ayetlerimizi inkâr eden ve «Bana kesinlikle mal ve evlat verilecek» diyen adamı gördün mü?"},{"n":78,"t":"Gaybın bilgisi mi önüne açıldı, yoksa rahmeti bol olan Allah’dan kesin söz mü aldı?"},{"n":79,"t":"Hayır, öyle bir şey yok. Onun söylediklerini yazacağız ve uğrayacağı azabı alabildiğine arttıracağız."},{"n":80,"t":"ve onun (gururla) dile getirdiği (servet ve evlat) Bize kalacak; ve kendisi huzurumuza yalnız başına çıkacak."},{"n":81,"t":"Müşrikler, Allah’ı bir yana bırakarak kendilerine destek olsunlar diye çeşitli ilahlar edindiler."},{"n":82,"t":"Hayır. O düzmece ilahlar, müşriklerin kendilerine yönelik tapınmalarını reddedecekler ve onlara karşı çıkacaklardır."},{"n":83,"t":"Şeytanları, kâfirlerin üzerine kışkırtıcı olarak saldığımızı görmedin mi?"},{"n":84,"t":"Onların bir an önce yok edilmelerini isteme. Biz onların yaptıklarını ve alıp verdikleri nefesleri tek tek sayıyoruz."},{"n":85,"t":"O gün kötülükten sakınanları seçkin konuklara yaraşır bir saygınlıkla, rahmeti bol olan Allah’ın huzurunda biraraya getiririz."},{"n":86,"t":"Buna karşılık ağır günahkârları, susamış hayvan sürüleri gibi cehenneme süreriz."},{"n":87,"t":"Allah’ın bu yolda yetki verdiği kimseler dışında hiç kimse bir başkasına aracılık, şefaat edemez."},{"n":88,"t":"Bazı kâfirler «Rahmeti bol olan Allah, evlat edindi» dediler."},{"n":89,"t":"Sizler, böyle demekle son derece çirkin bir iddia ileri sürdünüz."},{"n":90,"t":"Bu iddia karşısında nerede ise gökler paramparça olacak, yer yarılacak ve dağlar gürültü ile göçerek yerle bir olacak."},{"n":91,"t":"Onlar rahmeti bol olan Allah’a çocuk yakıştırdılar diye."},{"n":92,"t":"Oysa rahmeti bol olan Allah’a çocuk edinmek yakışmaz."},{"n":93,"t":"Göktekilerin ve yerdekilerin tümü rahmeti bol olan Allah’ın huzuruna kul olarak geleceklerdir."},{"n":94,"t":"Allah, onları bir bir sayarak hesaba geçirmiştir."},{"n":95,"t":"Kıyamet günü hepsi O’nun huzuruna teker teker geleceklerdir."},{"n":96,"t":"İman edip iyi ameller işleyenlere gelince Allah, onlara sevgi armağan edecektir."},{"n":97,"t":"Ey Muhammed, kötülükten sakınanları müjdeleyesin ve inatçılar güruhunu uyarasın diye biz bu Kur’an’ı ana dilinde indirerek onu kolay anlamanı sağladık."},{"n":98,"t":"Biz bu inatçılardan önce nice kuşakları yokettik. Şimdi onların hiçbirini ortalıkta görüyor musun, yada onlardan kaynaklanan en zayıf bir ses kulağına geliyor mu?"}],[{"n":1,"t":"Ta, ha."},{"n":2,"t":"Biz sana bu Kur’an’ı sıkıntıya düşesin diye indirmedik."},{"n":3,"t":"Onu Allah’dan korkanlara uyarı olsun diye indirdik."},{"n":4,"t":"O, yeri ve yüce gökleri yaratan Allah tarafından indirildi."},{"n":5,"t":"O rahmeti bol olan Allah, Arş’a kurulmuştur."},{"n":6,"t":"Göklerdeki, yerdeki, bu ikisi arasındaki ve toprağın altındaki tüm varlıklar O’nundur."},{"n":7,"t":"Söyleyeceğin sözü ister sesli olarak, ister içinden söyle. Çünkü Allah saklıyı da, saklının saklısını da bilir."},{"n":8,"t":"O kendisinden başka ilah olmayan Allah’dır. Ve en güzel isimler O’nunkilerdir."},{"n":9,"t":"Sana «Musa olayı» na ilişkin bilgi geldi mi?"},{"n":10,"t":"Hani o bir ateş görünce ailesine dedi ki; «Siz burada kalın, ben bir ateş gördüm. Ya oradan size bir kor getiririm, ya ateşin yakınlarında bize yol gösterecek birini bulurum.»"},{"n":11,"t":"Ateşin yanına gelince kendisine şöyle seslenildi; «Ey Musa!»"},{"n":12,"t":"Hiç kuşkusuz ben senin Rabbi’nim. Pabuçlarını çıkar. Çünkü sen kutsal Tuva vadisindesin."},{"n":13,"t":"Seni ben peygamber seçtim. Şimdi vahyedilecek mesajı dinle."},{"n":14,"t":"Hiç kuşkusuz ben Allah’ım. Benden başka ilah yoktur. Öyleyse bana kulluk et. Beni anmak için namaz kıl."},{"n":15,"t":"Herkes yaptıklarının karşılığını görsün diye kıyamet anı kesinlikle gelecektir. Ben o anı neredeyse gizli tuttum."},{"n":16,"t":"Bu anın geleceğine inanmayanlar, ihtiraslarının tutsağı olanlar seni onun bilincinden uzaklaştırmasın. Yoksa mahvolursun, aşağı düşersin."},{"n":17,"t":"Sağ elindeki nedir, ya Musa."},{"n":18,"t":"Musa dedi ki; «O benim değneğimdir. Ona dayanırım. Onunla koyunlarıma yaprak silkerim. Bunlar dışında daha birçok işime de yarar o.»"},{"n":19,"t":"Allah «onu yere at!» dedi."},{"n":20,"t":"Musa değneği yere atıverdi. Birde ne görsün! Ansızın sürünen bir yılan oluvermiş!"},{"n":21,"t":"Allah dedi ki; «Al onu yerden, korkma, biz onu eski haline dönüştüreceğiz»"},{"n":22,"t":"Elini yenine sok da hiçbir organik bozukluk sonucu olmaksızın bir başka mucize olarak ak bir parıltı ile geri çıksın."},{"n":23,"t":"Böylece sana birkaç büyük mucizemizi göstermek istedik."},{"n":24,"t":"Şimdi sen Firavun’a git. Çünkü o gerçekten azıttı.»"},{"n":25,"t":"Musa dedi ki; «Ya Rabbi! Gönlümü genişlet."},{"n":26,"t":"Görevimi kolaylaştır."},{"n":27,"t":"Dilimin düğümünü çöz."},{"n":28,"t":"Böylece söyleyeceklerimi anlayabilsinler."},{"n":29,"t":"Ailemden bana bir yardımcı armağan et."},{"n":30,"t":"Kardeşim Harun’u yani."},{"n":31,"t":"Ona arkamı dayayıp güç kazanmamı sağla."},{"n":32,"t":"O’nu görevime ortak et."},{"n":33,"t":"Böylece seni daha çok noksanlıklardan tenzih edelim."},{"n":34,"t":"Senin adını daha çok analım."},{"n":35,"t":"Kuşku yok ki, biz senin gözetimin altındayız.»"},{"n":36,"t":"Ey Musa, bu istediklerin sana verilmiştir."},{"n":37,"t":"Biz, bundan önce de bir kere daha sana lütufta bulunmuştuk."},{"n":38,"t":"Hani, annene şu mesajımızı vahyetmiştik:"},{"n":39,"t":"Musa’yı bir sandukaya koy ve nehre at; nehir onu sahile atsın da oradan onu benim ve kendisinin ortak düşmanımız alsın. Gözümün önünde yetişesin diye seni sevgimin kanatları altına aldım."},{"n":40,"t":"\"Ona bakacak birini size göstereyim mi?\" İşte böylece annen üzülmesin de sevinsin diye seni ona geri vermiştik. Ve sen bir cana kıymıştın da, seni üzüntüden kurtarmıştık. Hem seni bir çok musibetlerle denemiştik. Böylece Medyen halkı arasında yıllarca kalmıştın. Sonra da takdire göre geldin ey Musa."},{"n":41,"t":"Şimdi seni sırf kendime ayırdım."},{"n":42,"t":"Sen ve kardeşin ayetlerimle, mucizelerimle gidiniz. Bu arada adımı anmayı hiç ihmal etmeyiniz."},{"n":43,"t":"Firavun’a gidiniz. Çünkü o gerçekten azıttı."},{"n":44,"t":"’Ona yumuşak söz söyleyin; olur ki öğüt alacağı veya Allah’tan korkacağı tutar.’"},{"n":45,"t":"Musa ve Harun dediler ki; «Ey Rabbi’miz, korkarız ki, Firavun bize karşı bir taşkınlık yapar, ya da azgınlığını artırır.»"},{"n":46,"t":"Allah, onlara dedi ki; «korkmayınız. Ben sizinle beraberim. Ben herşeyi işitir, her şeyi görürüm.»"},{"n":47,"t":"Ona varınız ve deyiniz ki; ’Biz Rabbinin sana gönderdiği elçileriz. İsrailoğullarının bizimle birlikte Mısır’dan ayrılmalarına izin ver. Onlara işkence etme. Sana Rabbi’inden, doğru söylediğimizi kanıtlayacak mucizeler ile geldik. Doğru yola girenler esenliğe ereceklerdir."},{"n":48,"t":"Bize gelen vahye göre Allah’ın ayetlerini yalanlayarak gerçeğe sırt çevirenler azaba uğrayacaklardır."},{"n":49,"t":"Firavun «Ey Musa, sizin Rabb’iniz kimdir?» dedi."},{"n":50,"t":"Musa «Bizim Rabb’imiz, her varlığı farklı niteliklerle donatarak yaratan, sonra da bu varlıkları nitelikleri doğrultusunda yönlendiren Allah’dır.»"},{"n":51,"t":"Firavun «Peki, bizden önceki kuşakların durumu ne olacak?» dedi."},{"n":52,"t":"Musa dedi ki; «Onlara ilişkin bilgi Rabb’imin katındaki kitapta yazılıdır benim Rabb’im ne yanılır ne de unutur.»"},{"n":53,"t":"O size yeryüzünü beşik yaptı, orada sizin için yollar açtı ve gökten su indirdi. O su sayesinde çiftler halinde çeşitli bitkiler bitirdik."},{"n":54,"t":"Bu bitkilerden kendiniz yiyesiniz ve hayvanlarınızı otlatasınız diye. Sağduyu sahiplerinin bu olaylardan alacakları birçok dersler vardır."},{"n":55,"t":"Sizleri topraktan yarattık, yine oraya döndüreceğiz ve tekrar dirilterek oradan çıkaracağız."},{"n":56,"t":"Biz Firavun’a tüm ayetlerimizi gösterdik, fakat o bunları yalanladı, kabul etmeye yanaşmadı."},{"n":57,"t":"Dedi ki; «Ey Musa, sen bizi büyücülüğünle yurdumuzdan çıkarmaya mı geldin?»"},{"n":58,"t":"Biz de seninki gibi bir büyü ile karşına çıkacağız. Seninle buluşacağımız bir zaman belirle. Bu randevudan sen de bizde caymayalım. Buluşma yerimiz açık bir düzlük olsun."},{"n":59,"t":"Musa «Sizinle buluşmamız süslenme gününüzde, halkın toplandığı kuşluk vakti olsun» dedi."},{"n":60,"t":"Bunun üzerine Firavun dönüp gitti, hilelerini hazırladıktan sonra randevu yerine geldi."},{"n":61,"t":"Musa onlara dedi ki; «Vay gele başınıza! Allah adına yalan uydurmayınız. Yoksa sizi bir azaba çarptırarak kökünüzü kurutur. Allah’a iftira atan gerçekten aldanmıştır.»"},{"n":62,"t":"Bunun üzerine büyücüler aralarında gizlice fısıldaşarak durumlarını tartıştılar."},{"n":63,"t":"Ve dediler ki; «Bu iki adam büyücüdür, sizleri büyüleyerek yurdunuzdan çıkarmak, sizin örnek dininizi ortadan kaldırmak istiyorlar.»"},{"n":64,"t":"Bütün hilelerinizi biraraya getiriniz, sonra sıra halinde buluşma yerine geliniz. Bugün üstün gelen başarıya ermiştir."},{"n":65,"t":"Büyücüler «Ey Musa, ya sen önce hünerini göster ya da önce biz hünerimizi ortaya koyalım» dediler."},{"n":66,"t":"\"Hayır siz koyun\" dedi. Bir de ne görsün ipleri ve değnekleri büyüleri yüzünden kendisine gerçekten yürüyorlarmış gibi geldi."},{"n":67,"t":"Bunun üzerine Musa’nın içine korku düştü."},{"n":68,"t":"Allah ona dedi ki; «Korkma, üstün gelecek olan sensin.»"},{"n":69,"t":"Sağ elindeki değneğini yere atıver de onların gösterdikleri marifetleri yutuversin. Onların hünerleri, bir büyücü hilesinden ibarettir. Büyücü hiçbir yerde başarılı olamaz."},{"n":70,"t":"Bunu üzerine büyücüler secdeye kapanarak «Biz Musa ile Harun’un Rabbine inandık» dediler."},{"n":71,"t":"Firavun dedi ki; «Ben size izin vermeden ona inandınız ha! O size büyücülüğü öğreten elebaşınızdır. andolsun ki, sağlı sollu birer el ve ayağınızı kesecek, arkasından sizi hurma dallarına asacağım, böylece hangimizin azabı daha ağır, daha sürekliymiş, öğreneceksiniz."},{"n":72,"t":"Büyücüler dediler ki; «Biz seni, bize gelen açık delillere ve yaratıcımıza tercih edemeyiz. Vereceğin hükmü ver. Senin hükmün ancak dünya hayatında geçerli olabilir."},{"n":73,"t":"Biz Rabbimize inandık. O’ndan günahlarımızı affetmesini ve bize zorla yaptırdığın büyücülüğümüzün suçunu bağışlamasını diliyoruz. Allah’ın ödülü, herkesinkinden daha üstün ve daha kalıcıdır."},{"n":74,"t":"Kim Rabbine günahkâr olarak gelirse onun için cehennem vardır. O orada ne ölür ve ne de dirilir."},{"n":75,"t":"Kim Rabbine, iyi ameller işlemiş bir mü’min olarak gelirse işte onlar için yüksek dereceler vardır."},{"n":76,"t":"Altlarından çeşitli ırmaklar akan «Adn» cennetleri yani. Onlar orada sürekli kalacaklardır. İşte günahlardan arınmışların ödülü budur."},{"n":77,"t":"Musa’ya «Kullarımı geceleyin yola çıkar, denize değneğini vurarak onlar için kuru bir yol aç, ne yakalanmaktan kork ve ne de boğulmaktan çekin» diye vahyettik."},{"n":78,"t":"Firavun, ordusu ile peşlerine düştü, fakat denizin suları onları korkunç bir saldırı ile kuşatıverdi!"},{"n":79,"t":"Firavun, soydaşlarını sapıklığa sürükledi, onları doğru yola iletemedi."},{"n":80,"t":"Ey İsrailoğulları, sizi düşmanınızdan kurtardık. Size Tur’un sağ yanında Tevrat’ı indirmeyi vadettik. Size gökten kudret helvası ile bıldırcın indirdik."},{"n":81,"t":"Size sunduğumuz temiz rızıklardan yiyiniz. Yiyeceklere ilişkin sınırlarımızı çiğnemeyiniz. Yoksa gazabıma çarpılırsınız. Kim gazabıma çarpılırsa mahvolur."},{"n":82,"t":"Kuşku yok ki, ben tövbe edip iman edenlere iyi ameller işleyip doğru yoldan ayrılmayanlara karşı affediciyim."},{"n":83,"t":"Ey Musa, «soydaşlarının önünden koşup gelmenin sebebi nedir?»"},{"n":84,"t":"Musa, «Ya Rabbi, işte onlar da arkamdan geliyorlar. Ben önlerinden koşarak sana geldim ki, hoşnutluğunu kazanayım» dedi."},{"n":85,"t":"Allah dedi ki «Biz senin arkandan soydaşlarını sınavdan geçirdik ve Samiri onları yoldan çıkardı.»"},{"n":86,"t":"«Rabb’iniz size güzel bir vaadde bulunmadı mı? Sizden ayrılalı çok uzun bir zaman mı geçti, yoksa Allah’ın gazabına çarpılmak istediniz de mi bana verdiğiniz sözden caydınız?"},{"n":87,"t":"Soydaşları dediler ki; «Biz sana verdiğimiz sözden kendi başımıza caymadık. Fakat yanımızda Mısırlılar’a ait birkaç insan yükü süs eşyası getirmiştik. Bu yükleri ateşe attık. Samiri de yanındaki süs eşyalarını ateşe atmıştı."},{"n":88,"t":"Samiri, o erimiş altınlardan böğüren bir buzağı heykelini yontarak İsrailoğullarının önlerine dikti. Onlar da birbirlerine «İşte sizin ve Musa’nın ilahı budur, fakat Musa onu unuttu» dediler."},{"n":89,"t":"Oysa onlar, o buzağı heykellerinin kendilerine cevap vermediğini, ne zarar ve ne de fayda dokunduramadığını görmüyorlar mı?"},{"n":90,"t":"Üstelik Harun daha önce onlara «Ey soydaşlarım, bu altın heykel aracılığı ile siz sınav geçiriyorsunuz. Aslında sizin Rabb’iniz rahmeti bol olan Allah’dır. Bana uyunuz ve dediğimi yapınız» demişti."},{"n":91,"t":"Onlar Harun’a «Musa bize dönünceye kadar bu buzağı heykeline tapmayı sürdüreceğiz» dediler."},{"n":92,"t":"«Ey Harun, onların sapıttıklarını gördüğünde seni engelleyen ne oldu?"},{"n":93,"t":"Niye beni izleyerek onlara karşı koymadın? Yoksa emrime karşı mı geldin?"},{"n":94,"t":"Harun Musa’ya «Ey anamın oğlu, saçımı sakalımı çekme, ben ’İsrailoğullarını birbirlerine düşürdün, sözümü tutmadın’ diyeceksin diye korktum» dedi."},{"n":95,"t":"Bunun üzerine Musa «Ey Samiri, peki senin amacın neydi?» dedi."},{"n":96,"t":"Samiri dedi ki; «Ben onların görmediklerini gördüm. Bana gelen ilahi elçinin ayak izlerinden avucumu doldurarak onu erimiş altın külçesinin bulunduğu potaya attım. Böyle yapmamın iyi olacağı içime doğdu.»"},{"n":97,"t":"«Çekil karşımdan» Sen hayatı boyunca insanlara ’Bana değmeyin’ demeye mahkûm oldun. Ayrıca asla yakanı kurtaramayacağın başka bir cezan daha vardır. Şimdi tapmaya devam ettiğin ilahının başına neler geleceğini gör. Onu ateşte eriteceğiz, sonra da parçalarını denize atacağız."},{"n":98,"t":"Aslında sizin ilahınız, kendisinden başka ilah olmayan Allah’dır. O’nun bilgisi her şeyi kapsamı içine almıştır."},{"n":99,"t":"Sana böylece geçmişin bazı olayların anlatıyoruz. Sana katımızdan öğüt içerikli bir kitap verdik."},{"n":100,"t":"Kim bu kitab’a yüz çevirirse, kıyamet günü ağır bir günah yükünü sırtında taşır."},{"n":101,"t":"Onlar ebedi olarak bu yükün altında kalırlar. Kıyamet günü bu yük onlar için ne kötü bir yüktür."},{"n":102,"t":"Sur’a üflendiği gün, o gün günahkârları korkudan ağarmış gözlerle biraraya toplarız."},{"n":103,"t":"Kısık bir ses tonu ile birbirlerine «Siz dünyada sadece on gün kaldınız» derler."},{"n":104,"t":"Aralarındaki konuşmaları biz herkesten iyi biliriz. Bu arada en isabetli görüşlüleri «Siz dünyada sadece bir gün kaldınız» derler."},{"n":105,"t":"Ey Muhammed, sana dağlara ilişkin soru sorarlar. De ki; Rabb’im onları ufalayıp havada savurur."},{"n":106,"t":"Yerlerini dümdüz ve çırılçıplak bir alana dönüştürür."},{"n":107,"t":"O alanda hiçbir engebe, hiçbir tümsek göremezsin."},{"n":108,"t":"O gün insanlar, hiç sağa sola sapmaksızın, kendilerini toplamaya çağıran görevlinin adımlarını izlerler. Rahmeti bol olan Allah’ın korkusu ile tüm sesler kısılmıştır. Bu yüzden fısıltıdan başka bir şey duyamazsın."},{"n":109,"t":"O gün rahmeti bol olan Allah’ın izin verdikleri ve sözünden hoşlandıkları dışında hiç kimsenin aracılığı, şefaati işe yaramaz."},{"n":110,"t":"Allah, insanların geçmişlerini ve geleceklerini tümü ile bilir,"},{"n":111,"t":"O gün bütün yüzler, diri ve tüm varlıkları gözetip yöneten Allah’ın karşısında öne eğiktir. Sırtında zulüm yükü taşıyanlar perişan olmuşlardır."},{"n":112,"t":"Mü’min oldukları halde iyi ameller işleyenler ne haksızlığa ve ne de ödül kısıntısına uğramaktan korkarlar."},{"n":113,"t":"Biz bu Kur’anı böylece sana Arapça bir kitap olarak indirdik. Bu kitapta çeşitli tehditlere yer verdik ki, insanlar kötülüklerden sakınsınlar ya da gönüllerinde uyarıcı bir iz bırakır."},{"n":114,"t":"Gerçek egemen olan Allah yücedir. Ey Muhammed, Kur’anın sana vahyedilişi sona ermeden onu okumakta acele etme ve ’Rabb’im bilgimi artır’ de!."},{"n":115,"t":"Biz vaktiyle Adem’e o yasak ağacın meyvasından yememesini tembih ettik. Fakat o bu tembihimizi unuttu. Onda güçlü irade bulamadık."},{"n":116,"t":"Hani meleklere «Adem’e secde ediniz» dedik de hemen secde ettiler. Yalnız iblis bu emre uymadı."},{"n":117,"t":"«Ey Adem, bu şeytan senin ve eşinin düşmanıdır. Sakın sizi cennetten çıkarmasın. Yoksa sıkıntı çeker, mutsuz olursun.»"},{"n":118,"t":"Şimdi cennette acıkmayacaksın, çıplak kalmayacaksın."},{"n":119,"t":"Yine burada susuzluk çekmeyecek, sıcaktan kavrulmayacaksın."},{"n":120,"t":"Fakat şeytan «Ey Adem, ölümsüzlük ağacını ve hiç yıkılmayacak egemenliğin sırrını sana göstereyim mi?» diyerek onu ayarttı."},{"n":121,"t":"Böylece ikisi de o ağacın meyvasından yediler. Meyvayı tadar tatmaz ayıp yerlerinin farkına vardılar. Bunun üzerine cennetteki ağaçların yaprakları ile örtünmeye koyuldular. Adem Rabb’inin emrine karşı geldi ve yoldan çıktı."},{"n":122,"t":"Fakat bir süre sonra Rabb’i, onu seçkinlerden yaptı, tövbesini kabul ederek kendisini doğru yola iletti."},{"n":123,"t":"Allah dedi ki; Her ikiniz de cennetten yere ininiz. Sizler birbirinizin düşmanısınız. Benden size bir hidayet geldiğinde kim benim doğru yola çağıran mesajıma uyarsa o, ne sapıtır ve ne de sıkıntıya düşer."},{"n":124,"t":"Ama kim benim uyarıcı mesajıma sırt çevirirse o geçim sıkıntısına düşer ve kıyamet günü onu kör olarak toplantı yerine süreriz."},{"n":125,"t":"O der ki «Ya Rabb’i, beni niye kör olarak toplantı yerine sürdün, oysa daha önce benim gözlerim görüyordu.»"},{"n":126,"t":"«İşte böyle. Vaktiyle sana ayetlerim geldi de onları unutmuştun. Bugün de böylece tarafımdan unutulursun."},{"n":127,"t":"Biz azıtarak Rabb’inin ayetlerine inanmayanları işte böyle cezalandırırız. Hiç kuşkusuz ahiret azabı daha ağır ve daha süreklidir."},{"n":128,"t":"Vaktiyle yok ettiğimiz nice eski kuşakların acı sonları onları doğru yola iletmiyor mu? Oysa onlar bu yok edilmiş kuşakların oturdukları konutları geziyorlar. Sağduyu sahiplerinin bu olaylardan çıkaracağı birçok dersler vardır."},{"n":129,"t":"Eğer Rabb’inin daha önce verilmiş bir hükmü ve belirlenmiş bir vadesi olmasaydı yok edilmeleri kaçınılmaz olurdu."},{"n":130,"t":"Ey Muhammed, öyleyse onların söylediklerine sabret. Güneşin doğuşundan ve batışından önce Rabb’ini övgü ile noksanlıklardan tenzih et; gecenin bir bölümü ile gündüzün başlangıcı ile sonunda da O’nu noksanlıklardan tenzih et ki, karşılığında hoşnut olasın."},{"n":131,"t":"Sınavdan geçirmek amacı ile bazı kâfirlere verdiğimiz dünya hayatına ilişkin çekici nimetlere sakın göz dikme. Rabb’inin katındaki rızık daha değerli ve daha süreklidir."},{"n":132,"t":"Ey Muhammed, yakınlarına namaz kılmayı emret, kendin de onu sürekli olarak kıl. Senden geçim peşinde koşmanı istemiyoruz. Biz geçimini sağlarız. Mutlu son, kötülüklerden sakınanların olacaktır."},{"n":133,"t":"Müşrikler «Muhammed bize Rabb’inden bir mucize getirseydi ya» dediler. Onlara daha önce inen kutsal sayfalara ilişkin açıklamalar gelmedi mi?"},{"n":134,"t":"Eğer onları daha önce azaba çarptırarak yok etseydik; «Ey Rabb’imiz, bu rezilliğe ve perişanlığa düşmeden önce bize bir peygamber gönderseydin de ayetlerine uysaydık, olmaz mıydı?» diyeceklerdi."},{"n":135,"t":"«Şimdi siz de biz de bekleme dönemindeyiz. Bekleyiniz, ilerde hangimizin düz yolda olduğunu, hangimizin doğru yönde ilerlediğini öğreneceksiniz.»"}],[{"n":1,"t":"İnsanların hesap verme günü yaklaştığı halde onlar halâ gaflet içinde gerçeğe yüz çeviriyorlar."},{"n":2,"t":"Onlar Rabb’lerinden gelen her yeni uyarıyı kesinlikle alaya alarak dinliyorlar."},{"n":3,"t":"Kalpleri oyundadır. Bu zalimler gizlice şöyle fısıldaştılar; «Şu Muhammed, sadece sizin gibi bir insan değil mi? Gözünüz göre göre büyüye mi kapılacaksınız?»"},{"n":4,"t":"Peygamber dedi ki; «Benim Rabb’im, gökte ve yerde söylenen her sözü bilir, o işiten ve bilendir."},{"n":5,"t":"O zalimler dediler ki; «Hayır, Muhammed’in söyledikleri birtakım karmaşık, birbirinden kopuk hayallerdir. Hayır, bu sözler O’nun uydurmasıdır. Hayır, O bir şairdir. Öyle değilse bize daha önceki peygamberlerin gösterdiklerine benzer bir mucize göstersin.»"},{"n":6,"t":"Oysa onlardan önceki helâk ettiğimiz kentlerin hiçbiri inanmamıştı. Şimdi onlar mı inanacaklar?"},{"n":7,"t":"Senden önce de kendilerine vahyettiğimiz erkeklerden başkasını göndermedik. Bilmiyorsanız şayet zikir ehline sorun."},{"n":8,"t":"Biz onları yemek yemez organizmalar olarak yaratmadık. Onlar ölümsüz de değillerdi."},{"n":9,"t":"Sonra sözümüzü tutarak onları ve dilediğimiz kimseleri kurtararak ölçülerimizi çiğneyen azgınları yokettik."},{"n":10,"t":"Andolsun ki, size namınızı yücelten, öğütler içeren bir kitap indirdik. Buna aklınız ermiyor mu?"},{"n":11,"t":"Halkları zalim olan nice şehri kırıp geçirdik de arkasından başka halklar ortaya çıkardık."},{"n":12,"t":"Bu zalimler azabımızın gelip çattığını farkettiklerinde derhal şehirlerinden kaçmaya koyuluyorlardı."},{"n":13,"t":"Kaçmayınız, sizi baştan çıkaran nimetlere ve evlerinize dönünüz ki, sorguya çekileceksiniz!"},{"n":14,"t":"Eyvahlar olsun! Biz gerçekten kendimize zulmetmişiz dediler."},{"n":15,"t":"Onlar böyle vahlanıp dururken biz kendilerini biçilmiş ekinler gibi cansız yere seriverdik."},{"n":16,"t":"Biz göğü, yeri ve ikisi arasındaki varlıkları oyun olsun diye yaratmadık."},{"n":17,"t":"Eğer bir eğlence edinmek isteseydik, özümüzden kaynaklanan bir eğlence edinirdik. Yapacak olsak böyle yapardık."},{"n":18,"t":"Hayır, biz hakkı (gerçeği), batılın (eğriliğin), başına çarparız da batılın beyni parçalanır ve yok oluverir. Allah’a yakıştırdığınız uygunsuz sıfatlardan ötürü vay gele başınıza!"},{"n":19,"t":"Göklerde ve yerde ne varsa hepsi O’nundur. O’nun katındakiler hiçbir büyüklük kompleksine kapılmaksızın ve hiç bıkmaksızın O’na ibadet ederler."},{"n":20,"t":"Hiç ara vermeksizin, gece gündüz O’nu noksanlıklardan tenzih ederler."},{"n":21,"t":"Yoksa müşrikler, ölüleri diriltebilecek yeryüzü kaynaklı ilahlar mı edindiler?"},{"n":22,"t":"Eğer yerde ve gökte Allah’dan başka ilahlar olsaydı yerin ve göğün düzeni altüst olurdu. Arş’ın rabbi olan Allah, o müşriklerin asılsız yakıştırmalarından münezzehtir."},{"n":23,"t":"O yaptıklarından sorumlu değildir. Oysa onlar davranışlarından sorumludurlar."},{"n":24,"t":"Yoksa onlar O’nun dışında başka ilahlar mı edindiler? Onlara de ki; «Bu konudaki delilinizi ortaya getiriniz. Bu kitap, gerek benimle birlikteki mü’minlere yönelik direktifleri ve gerekse benden önceki peygamberlere ilişkin bilgileri içeriyor.» Hayır onların çoğunluğu gerçeğin ne olduğunu bilmeksizin ona sırt çevirirler."},{"n":25,"t":"Senden önce gönderdiğimiz bütün peygamberlere «Benden başka ilah yoktur, sırf bana kulluk ediniz» diye vahyettik."},{"n":26,"t":"’Rahman çocuk edindi’ dediler. O münezzehtir. Hayır (melekler) şerefli kılınmış kullardır."},{"n":27,"t":"Onlar Allah’dan önce söz söylemezler ve ne yaparlarsa sırf O’nun emri ile yaparlar."},{"n":28,"t":"Allah, onların önlerindekini ve arkalarında bıraktıklarını (yapacaklarını ve yaptıklarını) bilir. Onlar sadece Allah’ın hoşnut olduğu kimselere şefaat ederler ve Allah’ın korkusundan titrerler."},{"n":29,"t":"Eğer onlardan biri «Ben Allah’ın dışında ilahım» derse onu cehennem ile cezalandırırız. Biz zalimleri böyle cezalandırırız."},{"n":30,"t":"Kâfirler, gökler ile yer birbirine yapışıkken onları ayırdığımızı ve bütün canlıları sudan meydana getirdiğimizi görmüyorlar mı? Onlar yine de iman etmiyorlar mı?"},{"n":31,"t":"Yeryüzü dengede dursun da insanları sarsmasın diye orada köklü dağlar yarattık ve istedikleri yere gidebilsinler diye o dağlarda geçit veren yollar açtık."},{"n":32,"t":"Göğü dengesizlikten korunmuş bir tavan, bir çatı yaptık. Onlar ise gökteki ayetlere, düşündürücü kanıtlara dönüp bakmıyorlar."},{"n":33,"t":"Geceyi, gündüzü, güneşi, ayı yaratan O’dur. Bunların herbiri kendi yörüngelerinde yüzerler."},{"n":34,"t":"Senden önceki hiçbir insana ölümsüzlük imkânı vermiş değiliz. Sanki sen ölürsen onlar sonsuza dek yaşayacaklar mı?"},{"n":35,"t":"Her canlı, ölümü tadacaktır. Nasıl davranacağınızı görelim diye sizi hem kötülükle ve hem de iyilikle sınavdan geçiririz. Sonunda bize döneceksiniz."},{"n":36,"t":"Kâfirler seni gördüklerinde birbirlerine «ilahlarınıza dil uzatan adam bu mu?» diyerek seni alaya almaktan geri durmazlar. Oysa kendileri «Rahman» olan Allah’ı hatırlamaya bile yanaşmazlar."},{"n":37,"t":"İnsanın yaratılışında «acelecilik» mayası vardır. Size ayetlerimi, mucizelerimi yakında göstereceğim; biraz sabırlı olunuz."},{"n":38,"t":"Eğer söylediğiniz doğru ise bu tehdidiniz ne zaman gerçekleşecek? dediler."},{"n":39,"t":"Kâfirler, cehennem ateşini yüzlerinden ve sırtlarından savamayacakları ve hiç kimseden yardım göremeyecekleri anın dehşetini eğer bilseler, böyle yapmazlardı!"},{"n":40,"t":"Aslında o tehdit, apansız bir şekilde karşılarına çıkıverir de şaşkınlıktan donakalırlar. O zaman onu ne başlarından savabilirler ve ne de kendilerine mühlet verilir."},{"n":41,"t":"Senden önceki peygamberler de alaya alınmıştı. Fakat o alaycılar, alay konusu ettikleri azabın pençesine düştüler."},{"n":42,"t":"De ki; «Gece gündüz sizi ’Rahman’ olan Allah’ın azabından kim koruyabilir?» Fakat onlar Rabb’lerini hatırlamaya yanaşmıyorlar."},{"n":43,"t":"Yoksa onların, kendilerini koruyacak bizim dışımızda başka ilahları mı var? O sözde ilahlar kendilerine bile yardım edecek güçte olmadıkları gibi bizden de destek göremezler."},{"n":44,"t":"Aslında biz onlara ve atalarına geniş geçim imkânları bağışladık da uzun yıllar refah içinde yaşadılar. Fakat bizim, kâfirlerin yurtlarını uçlarından kırptığımızı, müslümanlar lehine alanlarını daralttığımızı görmüyorlar mı? Acaba üstün gelen onlar mıdır?"},{"n":45,"t":"De ki; «Ben vahyin mesajına dayanarak sizi uyarıyorum.» Fakat sağırlar, uyarıldıklarında çağrıyı işitemezler."},{"n":46,"t":"Andolsun ki, Rabb’inin azabının en hafif bir fiskesi eğer onlara değse kesinlikle «Eyvahlar olsun! Biz gerçekten kendimize zulmetmişiz» derler."},{"n":47,"t":"Kıyamet günü doğru tartan, duyarlı teraziler kurarız. Orada hiç kimseye haksızlık edilmez. İşlenen amel, bir hardal tanesi kadar bile olsa onu ortaya kovarız. Hesap görücü olarak biz yeteriz."},{"n":48,"t":"Andolsun ki, biz Musa ile Harun’a doğru ile eğriyi ayırdeden ve takvalılar için ışık ve öğüt olan kitab’ı verdik."},{"n":49,"t":"Onlar Rabb’lerinden görmeden korkarlar ve kıyamet gününün dehşetinden ürkerler."},{"n":50,"t":"Bu Kur’an, tarafımızdan indirilmiş kutsal bir öğüttür. Siz onu inkâr mı ediyorsunuz?"},{"n":51,"t":"Andolsun ki, daha önce de İbrahim’e doğru ile eğriyi ayırdetme yeteneği vermiştik. Onun peygamberliğe elverişli olduğunu biliyorduk."},{"n":52,"t":"Hani O babasına ve soydaşlarına «Şu karşılarında saygı duruşu yaptığınız heykeller nedir?» dedi."},{"n":53,"t":"Onlar da «Babalarımızı onlara tapar bulduk» dediler."},{"n":54,"t":"İbrahim «Gerek siz, gerekse babalarınız gerçekten koyu bir sapıklığa düşmüşsünüz» dedi."},{"n":55,"t":"\"Sen bize gerçeği mi getirdin, yoksa şaka mı ediyorsun?\" dediler."},{"n":56,"t":"İbrahim dedi ki; «Hayır, Rabb’iniz göklerin ve yerin Rabb’idir, onları yoktan vareden O’dur. Ben bu gerçeğin tanıklarından biriyim.»"},{"n":57,"t":"Vallahi siz arkanızı dönüp gittikten sonra putlarınıza bir oyun oynayacağım, bir komplo düzenleyeceğim."},{"n":58,"t":"Arkasından o putları kırıp parça parça etti, fakat bilgisine (!) başvursunlar diye en büyük putu sağlam bıraktı."},{"n":59,"t":"Soydaşları «Bu işi ilahlarımıza kim yaptı? Kim yaptı ise o gerçekten bir zalimdir» dediler."},{"n":60,"t":"Duyduğumuza göre ’İbrahim adında bir delikanlı bu ilahlarımıza dil uzatıyordu’ dediler."},{"n":61,"t":"O halde onu yakalayıp halkın karşısına getiriniz ki, herkes bu suçunun tanığı olsun dediler."},{"n":62,"t":"Soydaşları O’na «Ey İbrahim, bu işi ilahlarımıza sen mi yaptın?» dediler."},{"n":63,"t":"İbrahim soydaşlarına dedi ki; «Aslında bu işi şu en büyükleri yapmıştır. Bunu onların kendilerine sorunuz. Tabii ki, eğer konuşabiliyorlarsa.»"},{"n":64,"t":"Bunun üzerine vicdanlarına başvurarak birbirlerine «asıl zalimler sizlersiniz» dediler."},{"n":65,"t":"Fakat sonra yine eski dik kafalılıklarına dönerek İbrahim’e «Sen de iyi bilirsin ki, bunlar konuşamazlar,» dediler."},{"n":66,"t":"Bunun üzerine İbrahim dedi ki; «Allah’ı bırakıp size ne fayda ve ne de zarar dokunduramayan bu putlara mı tapıyorsunuz?»"},{"n":67,"t":"Yuh olsun size ve Allah’ı bir yana bırakıp taptığınız putlarınıza! Sizin hiç kafanız çalışmıyor mu?"},{"n":68,"t":"O zaman soydaşları «Eğer ilahlarınızın tarafını tutacaksanız İbrahim’i ateşe atınız da böylece onları destekleyiniz» dediler."},{"n":69,"t":"Bunun üzerine biz dedik ki; «Ey ateş, İbrahim’e karşı yakıcılığını yitir, O’na zarar verme.»"},{"n":70,"t":"Onlar O’nu tuzağa düşürmek istediler. Biz ise onları en ağır hüsrana uğrattık."},{"n":71,"t":"Arkasından İbrahim’i, Lut ile birlikte kurtararak onları insanlar için verimli ve bereketli kıldığımız bir bölgeye yerleştirdik."},{"n":72,"t":"Üstelik İbrahim’e, İshak’ı ve fazladan bir bağış olarak Yakub’u lütfettik ve hepsini de salih kimseler yaptık."},{"n":73,"t":"Onları emrimiz uyarınca insanları doğru yola ileten önderler yaptık. Onlara yararlı işler yapmayı, namaz kılmayı, zekât vermeyi vahyettik. Onlar bize kulluk eden kimselerdi."},{"n":74,"t":"Lût’a da egemenlik ve bilgi verdik. Onu, halkı iğrenç işler yapan o kentten kurtardık. Onlar gerçekten çirkin davranışları huy edinmiş kötü bir toplumdur."},{"n":75,"t":"Lût’u rahmetimizin kapsamına aldık. O gerçekten salih kullarımızdan biri idi."},{"n":76,"t":"Nuh’a gelince hani O, daha önce bize yalvarmıştı. Biz de O’nun duasını kabul ederek kendisini ve yakınlarını o büyük afetten kurtardık."},{"n":77,"t":"Onu ayetlerimizi yalanlayan soydaşlarının şerrinden kurtardık. Onlar gerçekten kötü bir toplumdu. Bu yüzden hepsini sularda boğduk."},{"n":78,"t":"Davud ve Süleyman’a gelince, hani onlar geceleyin yabancı bir koyun sürüsünün içine dalarak ekinini mahvettiği bir tarlanın davasını hükme bağladıklarında verdikleri hükmün tanığı olmuştuk."},{"n":79,"t":"Davud’un verdiği bu hükmü, Süleyman’ın kavrayıp onaylamasını sağladık. Her ikisine de egemenlik ve bilgi verdik. Allah’ı noksanlıklardan tenzih etme konusunda dağları ve kuşları Davud’a boyun eğdirdik. Biz bunları yaparız."},{"n":80,"t":"Savaşta düşmanın darbelerinden korunasınız diye Davud’a zırh yapma sanatını öğrettik. Acaba buna şükredecek misiniz ki?"},{"n":81,"t":"Verimli ve bereketli kıldığımız bölgeye doğru akan fırtınayı O’nun buyruğuna verdik. Her şey bizim bilgimizin kapsamı içindedir."},{"n":82,"t":"Ayrıca O’nun hesabına derin sulara dalan ve başka işler yapan bazı şeytanları da Süleyman’ın emrine verdik. Biz onları gözetim altında tutuyorduk."},{"n":83,"t":"Eyyüb’e gelince hani O «Bir derde yakalandım, sen ise merhametlilerin en merhametlisisin» diye Rabb’ine seslenmişti."},{"n":84,"t":"Biz de duasını kabul ederek pençesine düştüğü derdi giderdik. Ayrıca karşılıksız rahmetimizin bir eseri olarak ve bize kulluk edenlerin her zaman anacakları bir örnek olsun diye eski ailesini kendisine bir kat fazlası ile yeniden bağışladık."},{"n":85,"t":"İsmail’i, İdris’i ve Zülkifli de hatırla. Bunların her üçü de sabırlı kimselerdi."},{"n":86,"t":"Her üçünü de rahmetimizin kapsamına aldık. Onlar gerçekten salih kullarımızdandı."},{"n":87,"t":"Zunnun’a (Yunus’a) gelince hani o öfke içinde yurdundan ayrılırken artık bizim kendisini sıkıntıya uğratmayacağımızı sanmıştı. Fakat sonra karanlıklar içinde «Senden başka ilah yoktur, sen her türlü noksanlıktan münezzehsin, ben gerçekten bir zalim oldum» diye bize seslendi."},{"n":88,"t":"Bunun üzerine duasını kabul ederek kendisini içine düştüğü sıkıntıdan kurtardık. İşte mü’minleri böyle kurtarırız."},{"n":89,"t":"Zekeriyya’yı da hatırla. Hani O Rabb’ine «Ya Rabb’i, beni tek, evlatsız bırakma, gerçi en hayırlı mirasçı sensin, her şey sonunda sana kalacaktır» diye seslendi."},{"n":90,"t":"Biz de duasını kabul ederek kendisine Yahya’yı armağan etmiş, eşini geçimli ve doğurgan yapmıştık. Bütün bu peygamberler iyi işler yapmaya koşarlar, umut ve korku içinde bize dua ederler, bize gönülden saygı beslerlerdi."},{"n":91,"t":"Irzına dokundurtmayan Meryem’e gelince ona ruhumuzdan bir soluk üfleyerek kendisini ve oğlunu tüm insanlar için gücümüzün sınırsızlığını kanıtlayan bir mucize yaptık."},{"n":92,"t":"İşte bu oluşturduğunuz ümmet, tek bir ümmettir, Rabb’iniz de benim. Öyleyse sırf bana kulluk ediniz."},{"n":93,"t":"Fakat insanlar inanç birliğinden ayrılarak çeşitli gruplara bölündüler. Ama hepsi sonunda bize döneceklerdir."},{"n":94,"t":"Kim mü’min olarak yararlı ameller işlerse emeği gözardı edilmez. Biz onu mutlaka yazıya geçiririz."},{"n":95,"t":"Yok ettiğimiz kentlerin halklarının hesap vermek üzere bize dönmemeleri imkânsızdır."},{"n":96,"t":"Sonunda Ye’cuc ile Me’cuc’un önündeki set yıkıldığında bunlar bütün tepelerden akarak her tarafa yayılırlar."},{"n":97,"t":"Gerçek vaadin (kıyamet gününün) eşiğine gelindiğinde kâfirlerin bakışları dehşetten donakalır ve «Eyvah halimize! Biz bu anın geleceğinden gafil yaşadık, biz gerçekten zalimlerden olduk» derler."},{"n":98,"t":"Siz ve Allah’ı bir yana bırakarak taptığınız sözde ilahlar, cehennem odunusunuz. Hepiniz oraya gireceksiniz."},{"n":99,"t":"Eğer o taptıklarınız, gerçekten ilah olsalardı, cehenneme girmezlerdi. Oysa hepsi sürekli olarak orada kalacaklardır."},{"n":100,"t":"Onlar orada hırıltılı sesler çıkararak inleyeceklerdir ve kulakları hiçbir ses işitemeyecektir."},{"n":101,"t":"Daha önce akıbetlerinin iyi olacağını takdir ettiğimiz kimselere gelince, onlar cehennemden uzak tutulacaklardır."},{"n":102,"t":"Onlar cehennem ateşinin uğultusunu duymazlar ve ebedi olarak canlarının çektiği nimetler içinde kalırlar."},{"n":103,"t":"Onları o en büyük korku ürkütmez. Melekler kendilerini «Bugün, size vaktiyle vadedilen gündür» diyerek karşılarlar."},{"n":104,"t":"O gün göğü, yazılı sayfaların dürüldüğü gibi düreriz. Varlıkları ilk başta nasıl yarattıksa, onları aynı şekilde yeni baştan diriltiriz. Bu yerine getirmeyi üstlendiğimiz bir sözdür. Biz onu mutlaka yaparız."},{"n":105,"t":"Andolsun ki, nezdimizdeki saklı belgelerden sonra peygamberlere indirdiğimiz kutsal kitaplara da «Ancak salih, yapıcı kullar yeryüzünün varisleri olabilirler» diye yazdık."},{"n":106,"t":"Hiç kuşkusuz bu Kur’an’da Allah’a kulluk edenler için yeterli olacak nitelikte bilgi ve mesaj vardır."},{"n":107,"t":"Biz seni tüm alemlere rahmet olarak gönderdik."},{"n":108,"t":"Müşriklere de ki; «Bana ilahınızın tek Allah olduğu vahyolundu. Siz bu ilkeyi benimseyip müslüman oluyor musunuz»"},{"n":109,"t":"Eğer bu çağrına sırt çevirirlerse onlara de ki; «Bana gelen mesajı duyurarak bu konuda sizi kendimle eşit bilgi düzeyine erdirdim. Size yöneltilen tehdit yakın mıdır, yoksa uzak mıdır, onu bilemem.»"},{"n":110,"t":"Hiç kuşkusuz Allah, açıkça söylediğiniz sözleri bildiği gibi içinizde sakladığınız duyguları da bilir."},{"n":111,"t":"Bilemem; belki de azabınızın ertelenmesi sizin sınavdan geçirilmeniz ve belirli bir sürenin sonuna kadar dünya nimetlerinden yararlandırılmanız içindir."},{"n":112,"t":"Peygamber dedi ki; «Ya Rabb’i, benim ile müşrikler arasındaki davayı hak ilkesi uyarınca hükme bağla. Sizin düzmece iddialarınız ve asılsız yakıştırmalarınız karşısında tek sığınağım, son derece merhametli olan Rabb’imin yardımıdır.»"}],[{"n":1,"t":"Ey insanlar Rabb’inizden korkunuz. Çünkü kıyamet anının sarsıntısı müthiş bir olaydır."},{"n":2,"t":"O sarsıntı ile karşılaştığınız gün bütün çocuk emziren kadınlar memedeki çocuklarını bir yana bırakıverirler, bütün hamile kadınlar çocuklarını düşürürler, insanları sarhoş gibi görürsün, oysa sarhoş değildirler. Ama Allah’ın azabı ağırdır."},{"n":3,"t":"Kimi insanlar doğru bir bilgiye dayanmaksızın Allah hakkında tartışırlar ve her şarlatan şeytana uyarlar."},{"n":4,"t":"Bu şeytana ilişkin kesinleşmiş hükme göre kim onun peşinden giderse kendisini doğru yoldan saptırarak alevli ateşin azabına sürükler."},{"n":5,"t":"Ey insanlar, şayet öldükten sonra tekrar dirilmek konusunda şüphede iseniz, bilin ki ne olduğunuzu size açıklamak için biz sizi topraktan, sonra insan suyundan, sonra pıhtılaşmış bir kandan, sonra yaratılışı belli belirsiz bir çiğnem etten yaratmışızdır. İstediğimizi belli bir süreye kadar rahimlerde tutarız. Sonra sizi çocuk olarak çıkarırız. Böylece yetişip erginlik çağına gelirsiniz. Kiminiz öldürülür, kiminiz de ömrünün en fena zamanına ulaştırılır ki bildiği halde bir şey bilmez olur. Yeryüzünü kupkuru olarak görürsünüz ama biz ona su indirdiğimiz zaman harekete geçer, kabarır ve her çeşit güzel bitkiden çift çift yetiştirir."},{"n":6,"t":"Bunlar gösteriyor ki, Allah gerçektir, O ölüleri diriltir, gücü her şeye yeter."},{"n":7,"t":"Ve kıyamet anı kesinlikle gelecektir, bunda kuşku yoktur, Allah mezarlardaki ölüleri diriltecektir."},{"n":8,"t":"İnsanlar arasında öylesi var ki, doğru bir bilgiye dayanmaksızın, yol göstereni ve aydınlatıcı bir kitabı olmaksızın Allah hakkında tartışmaya girişir."},{"n":9,"t":"Bu tartışma sırasında küstahça gerdan kırar. Amaç, başkalarını Allah yolundan saptırmaktır. Böylesini dünyada rezil edeceğimiz gibi kıyamet günü de ona kavurucu azabı tattırırız."},{"n":10,"t":"O gün ona «Bu ceza, vaktiyle kendi ellerinle işlediğin günahların karşılığıdır; Allah kullarına asla haksızlık etmez» denecektir."},{"n":11,"t":"İnsanlar arasında öylesi de var ki, sınırlı ve somut bir amaç uğruna Allah’a kulluk eder. Eğer işleri iyi giderse hoşnut olur. Fakat eğer sınav amaçlı bir sıkıntı ile karşılaşırsa yüzgeri eder, sırt çevirir. Böylesi hem dünyayı hem de ahireti kaybeder ki, işte apaçık hüsran budur."},{"n":12,"t":"Allah’ı bir yana bırakarak kendisine ne zarar ve ne de fayda dokunduramayan sözde ilahlara yalvarır. İşte koyu sapıklık budur."},{"n":13,"t":"O, zararı faydasından daha yakında olana yalvarır. Böylesi ne fena bir destekçi ve kötü bir yandaştır."},{"n":14,"t":"Allah, iman edip iyi ameller işleyenleri altlarından çeşitli ırmaklar akan cennetlere yerleştirir. Hiç kuşkusuz Allah istediğini yapar."},{"n":15,"t":"Kim dünyada ve ahirette Allah’ın kendisine yardım etmeyeceği vehmine (sanısına) kapılırsa evinin tavanına bağlayacağı bir ipi boğazına geçirdikten sonra onu kessin ve arkasından baksın bakalım, bu girişimi umutsuzluktan kaynaklanan öfkesini giderebiliyor mu?"},{"n":16,"t":"Biz Kur’anı işte böyle açık ayetler halinde indirdik. Hiç kuşkusuz Allah istediği kimseyi doğru yola iletir."},{"n":17,"t":"Mü’minler, yahudiler, sabiiler, hristiyanlar, ateşe tapanlar ve Allah’a ortak koşanlar var ya, Allah kıyamet günü bunlar hakkındaki ayırd edici hükmünü verecektir. Hiç kuşkusuz Allah her şeyin tanığıdır."},{"n":18,"t":"Göklerdeki ve yerdeki tüm varlıkların, güneşin, ayın, yıldızların, dağların, ağaçların, hayvanların ve çok sayıda insanın Allah’a secde ettiklerini, O’nun buyruğuna boyun eğdiklerini görmüyor musun? Birçok sayıdaki insan da azaba çarpılmayı haketmiştir. Allah’ın alçalttığı kimseye hiç kimse onur kazandıramaz. Hiç şüphesiz Allah dilediğini yapar."},{"n":19,"t":"Karşımızda Allah konusunda çatışan, iki çelişik inançlı insan kesimi, iki karşıt grup var. Bunlardan biri olan kâfirler için ateşten elbiseler biçilmiştir. Başlarından aşağıya kaynar sular dökülür."},{"n":20,"t":"Bu kaynar sular karın boşluklarındaki organlarını ve derilerini eritir."},{"n":21,"t":"Ayrıca onlar için demirden kamçılar hazırlanmıştır."},{"n":22,"t":"Onlar çektikleri acının baskısı altında cehennemden her çıkmak istediklerinde «kavurucu azabı tadınız» diye paylanarak oraya geri püskürtülürler."},{"n":23,"t":"Buna karşılık Allah, iman edip iyi ameller işleyenleri, altlarından çeşitli ırmaklar akan cennetlere yerleştirir. Orada altın bilezikler ve inciler takınırlar. Giydikleri elbiseler ipekten olur."},{"n":24,"t":"Onlar güzel söze yöneltilmişler ve övgüye lâyık yola iletilmişlerdir."},{"n":25,"t":"Kâfirlere, insanları, Allah’ın yolundan ve gerek Mekke yerlilerinin gerekse dışardan gelen herkesin ziyaretine eşitçe açtığımız Mescid-i Haram’a (Kâ’be’ye) girmekten alıkoyanlara gelince kim orada zalimce bir tutum takınarak Allah’ın emirlerini çiğnerse kendisine acıklı bir azap tattırırız."},{"n":26,"t":"Hani İbrahim’e Beytullah’ın yerini gösterdik ve kendisine şöyle dedik; «Bana hiçbir şeyi ortak koşma ve bu evimi tavaf edenler, ayakta dikilenler, rükua ve secdeye varanlar için temiz tut.»"},{"n":27,"t":"İnsanlara haccı ilân et. Gerek yaya olarak ve gerekse uzak yolları aşarak yorgun develer üzerinde sana gelsinler."},{"n":28,"t":"Gelsinler de çeşitli yararlarını gözleri ile görsünler ve Allah’ın kendilerine rızık olarak verdiği hayvanları belirli günlerde kurban ederken O’nun adını ansınlar. Bu hayvanların etinden hem kendiniz yiyiniz, hem de sıkıntı içinde bulunan yoksullara yediriniz."},{"n":29,"t":"Sonra kirlerini giderip temizlensinler, adaklarını yerine getirsinler ve bu tarihi evi (Kâ’be’yi) tavaf etsinler."},{"n":30,"t":"İşte böyle. Kim Allah’ın yasaklarına saygı gösterirse bu tutum Rabb’inin katında kendisi için hayırlıdır. Tek tek sayılarak yasaklananlar dışındaki bütün hayvanlar size helâl kılındı. Artık o pis putlardan ve yalan sözden kaçınınız."},{"n":31,"t":"Allah’ın birliğini onaylayan kimseler olunuz, O’na ortak koşmayınız. Kim Allah’a ortak koşarsa sanki gökten yere düşmüş de kuşlara yem olmuş ya da rüzgâr tarafından sürüklenerek ıssız bir köşeye atılmış gibi olur."},{"n":32,"t":"Bu böyledir. Kim Allah’ın emrettiği ibadet biçimlerine saygı gösterirse hiç kuşkusuz bu saygı kalplerdeki takvadan kaynaklanır."},{"n":33,"t":"Kurbanlık hayvanlar belirli bir süreye kadar size yararlı olur, sonra varacakları yer o tarihi evdir. (Beytullah’tır.)"},{"n":34,"t":"Biz her ümmete kurban kesmeyi, ibadet olarak emrettik. Amaç, Allah’ın insanlara rızık olarak sunduğu hayvanları keserken O’nun adını anmaktır. İlahınız tek ilahtır, yalnız O’na boyun eğiniz. Ey Muhammed, alçak gönüllü saygılıları müjdele."},{"n":35,"t":"Onlar ki, yanlarında Allah’ın adı anıldığında kalpleri ürperir, başlarına gelen belalara karşı sabrederler, namaz kılar ve kendilerine verdiğimiz rızıkların bir bölümünü Allah yolunda harcarlar."},{"n":36,"t":"Büyükbaş hayvan kurban etmeyi de Allah’ın size emrettiği ibadet biçimlerinden saydık. Onlar size çeşitli yararlar sağlarlar. Ön ayaklarını bağlayarak onları boğazlarken Allah’ın adını anınız. Yan üstü düşüp öldüklerinde, etlerinden hem kendiniz yiyiniz, hem de isteyene ve istemeyene yediriniz. Şükredesiniz diye o hayvanları böylece yararınıza sunduk."},{"n":37,"t":"Bu hayvanların ne etleri ve ne de kanları Allah’a ulaşacaktır. Allah’a ulaşacak olan şey, sadece gönlünüzdeki Allah saygısıdır, takvadır. Bu şekilde onları yararınıza sunduk ki, sizi doğru yola ilettiği gerekçesi ile Allah’ın yüceliğini dile getiresiniz. Ey Muhammed, iyi ameller işleyenleri müjdele."},{"n":38,"t":"Hiç kuşkusuz Allah mü’minleri destekler, savunur; yine hiç şüphesiz Allah hiçbir emanetine hıyanet edeni ve nankörü sevmez."},{"n":39,"t":"Saldırıya uğrayan mü’minlere savaşma izni verilmiştir. Çünkü onlar zulme uğramışlardır. Hiç kuşkusuz Allah’ın onlara yardım etmeye gücü yeter."},{"n":40,"t":"Onlar sırf «Rabb’imiz Allah’dır» dediler diye haksız yere yurtlarından çıkarıldılar. Eğer Allah bir kısım insanları diğer bir bölümü aracılığı ile savmasaydı nice manastır, havra ve içlerinde Allah’ın adı, çokça anılan cami yıkılıp giderdi. Kim Allah’a yardım ederse bilsin ki Allah da mutlaka kendisine yardım edecektir. Hiç şüphesiz Allah güçlü ve üstün iradelidir."},{"n":41,"t":"Onlar ki, eğer biz kendilerini yeryüzünde egemen kılarsak namazı kılarlar, zekâtı verirler, iyiliği emrederek kötülükten sakındırırlar. Her şeyin akıbeti Allah’a aittir."},{"n":42,"t":"Ey Muhammed, eğer müşrikler seni yalanlıyorlarsa bil ki, Nuh’un soydaşları, Adoğulları ve Semudoğulları da peygamberlerini yalanlamışlardı."},{"n":43,"t":"İbrahim’in soydaşları, Lût’un soydaşları da öyle."},{"n":44,"t":"Medyenliler de öyle. Musa’yı da yalanlamışlardı. Ben bütün bu kâfirlere önce mühlet tanıdım, sonra yakalarına yapıştım. Onlara indirdiğim darbe nasıldı?"},{"n":45,"t":"Halkı zalim olan nice kenti yok ettik. Yapılarının duvarları, yere inen tavan yıkıntılarının üzerine çökmüştür. Nice su kuyularını kullanan kalmamış, nice korunaklı köşkleri ıssız kalmıştır."},{"n":46,"t":"Müşrikler yeryüzünü gezmiyorlar mı ki, bu sayede kalpleri gördüklerinden ibret alabilsin ve kulakları söylenenleri işitebilecek bir duyarlık kazansın. Çünkü kör olan onların gözleri değildir, fakat göğüs boşluklarındaki kalpleri kördür, duyarsızdır."},{"n":47,"t":"Onlar senden azabımın bir an önce gerçekleşmesini istiyorlar. Oysa Allah sözünden caymaz ve Rabb’inin katındaki bir gün, sizin saydıklarınızdan bin yıl gibidir."},{"n":48,"t":"Halkı zalim olan nice kente önce mühlet tanıdım, sonra yakasına yapıştım. Sonunda bana dönülecektir."},{"n":49,"t":"De ki; «Ey insanlar, ben sizin için sadece açık sözlü bir uyarıcıyım.»"},{"n":50,"t":"İman edip iyi ameller işleyenler için bağışlanma ve onurlu rızık vardır."},{"n":51,"t":"Ayetlerimizi gözden düşürüp etkisiz bırakmak için birbirleri ile kıyasıya yarışanlar ise cehennemliktirler."},{"n":52,"t":"Senden önce gönderdiğimiz bütün resuller ve nebiler bir şey dilediklerinde şeytan bu dileklerini mutlaka birtakım beşeri arzular karıştırdı. Fakat Allah, şeytanın körüklediği bu arzuları her defasında gidererek arkasından ayetlerini pekiştirdi. Allah her şeyi bilir ve her yaptığı yerindedir."},{"n":53,"t":"Amaç şeytanın körüklediği bu arzular vesilesi ile kalpleri hasta olanları ve katı yüreklileri sınavdan geçirmektir. Hiç kuşkusuz zalimler gerçeğe son derece uzak düşen bir ayrılığa saplanmışlardır."},{"n":54,"t":"Diğer bir amaç, kendilerine bilgi verilenlerin, Kur’anın Rabb’inin gönderdiği bir gerçek olduğunu anlayarak ona inanmaları, ona karşı yürekten saygı duymalarıdır. Hiç kuşkusuz Allah, mü’minleri doğru yola iletir."},{"n":55,"t":"Kâfirler ise ansızın kıyamet günü ile karşı karşıya kalıncaya ya da «ertesi olmayan» o son günün azabına uğrayıncaya kadar Kur’an hakkında sürekli kuşku beslerler."},{"n":56,"t":"O gün kesin egemenlik Allah’ın tekelindedir. Onlar hakkında hükmünü verir. İman edip iyi ameller işleyenler nimet cennetlerine girerler."},{"n":57,"t":"Kâfir olup ayetlerimizi yalanlayanları ise onur kırıcı bir azap bekliyor."},{"n":58,"t":"Allah yolunda yurtlarından göçettikten sonra öldürülenlere ya da ölenlere gelince Allah onlara rızıkların en güzelini sunacaktır. Hiç kuşkusuz Allah rızık sunanların en hayırlısıdır."},{"n":59,"t":"O, onları kesinlikle hoşnut olacakları bir yere yerleştirecektir. Hiç kuşkusuz Allah her şeyi bilir ve yumuşak tutumludur."},{"n":60,"t":"Bu böyledir. Kim kendine haksızlık yapanlara gördüğü haksızlık kadar karşılık verdikten sonra saldırıya uğrarsa, Allah kendisine kesinlikle yardım eder. Hiç şüphesiz Allah bağışlayıcıdır, affedicidir."},{"n":61,"t":"Bu böyledir. Allah geceyi gündüze dönüştürür, gündüzü de geceye dönüştürür. Hiç şüphesiz Allah her şeyi işitir ve her şeyi görür."},{"n":62,"t":"Bu böyledir. Allah gerçektir ve onların Allah dışındaki imdada çağırdıkları düzmece ilahlar asılsızdır. Allah yüce ve uludur."},{"n":63,"t":"Allah’ın gökten su indirdiğini ve bu sayede yeryüzünün yemyeşil olduğunu görmüyor musun? Hiç kuşkusuz Allah latiftir ve her şeyden haberdardır."},{"n":64,"t":"Göklerde ve yerde bulunan tüm varlıklar O’nundur. Hiç kuşkusuz Allah zengindir ve övgüye layıktır.."},{"n":65,"t":"Görmüyor musun ki, Allah yeryüzündeki tüm varlıkları ve emri uyarınca denizde yüzen gemileri yararınıza sundu. O yeryüzüne düşmesin diye göğü askıda tutuyor. O ancak O’nun izni ile yere düşer. Hiç şüphesiz Allah, insanlara karşı şefkatli ve merhametlidir."},{"n":66,"t":"Sizi yaratan, sonra öldüren ve sonra tekrar diriltecek olan O’dur. Hiç kuşkusuz insan pek nankördür."},{"n":67,"t":"Biz her ümmet için uygulayacakları ayrı ibadet biçimleri belirledik. O halde müşrikler bu konuda seninle kesinlikle tartışmamalıdırlar. Sen insanları Rabb’ine çağır. Hiç kuşkusuz sen doğru yoldasın."},{"n":68,"t":"Eğer onlar seninle tartışmaya girerlerse de ki; «Allah, yaptıklarınızı çok iyi bilir.»"},{"n":69,"t":"Allah, kıyamet günü görüş ayrılığına düştüğünüz konulara ilişkin hükmünü verecektir."},{"n":70,"t":"Allah’ın gökte ve yerde bulunan her şeyi bildiğini bilmiyor musun? Bunların hepsi (O’nun katındaki) bir kitapta kayıtlıdır. Bu, Allah için kolay bir iştir."},{"n":71,"t":"Müşrikler, Allah’ı bir yana bırakarak haklarında hiçbir destekleyici delil indirilmemiş ve mahiyetlerine ilişkin hiçbir şey bilmedikleri sözde ilahlara tapıyorlar. Zalimler hiçbir destekçi bulamazlar."},{"n":72,"t":"Cehennem ateşi! Allah onu kâfirler için hazırladığını bildirmiştir. Ne kötü bir akıbettir o!»"},{"n":73,"t":"Allah’ı bir yana bırakarak yalvardığınız sözde ilahlar var ya, onların hepsi biraraya gelseler bir sinek bile yaratamazlar. Buna karşılık eğer sinek onların vücudundan son derece küçük bir parça kapıp götürse onu, onun ağzından geri alamazlar. Demek ki kovalayan da aciz, kovalanan da!"},{"n":74,"t":"Onlar Allah’ın ululuğunu gerektiği gibi kavrayamamışlardır. Hiç kuşkusuz Allah güçlüdür ve üstün iradelidir."},{"n":75,"t":"Allah, meleklerden de elçiler seçer, insanlardan da. Hiç kuşkusuz Allah her şeyi işitir, her şeyi görür."},{"n":76,"t":"O, onların önlerindekileri (geleceklerini) de bilir, arkada bıraktıklarını (geçmişlerini) de. Olup biten her şeyin son mercii O’dur."},{"n":77,"t":"Ey insanlar, ruküa varınız, secde ediniz, Rabb’inize kulluk ediniz ve iyi işler yapınız ki, kurtuluşa ve mutlu sona eresiniz."},{"n":78,"t":"Allah’ın rızası uğrunda gerektiği gibi cihad ediniz. O sizi bu görevi yapmak üzere seçti. Din konusunda size hiçbir zorluk yüklemedi. Atanız İbrahim’in dinidir bu. Allah sizi gerek daha önceki kutsal kitaplarda gerekse elinizdeki Kur’anda «müslüman» olarak adlandırdı. Amaç, Peygamberin size tanık ve canlı örnek olması, sizin de diğer insanlara tanık ve canlı örnek olmanızdır. Öyleyse namazı kılınız, zekâtı veriniz ve Allah’a sımsıkı bağlanınız. Sizin efendiniz, koruyucunuz O’dur. O ne güzel efendi ve ne güzel destekleyicidir!"}],[{"n":1,"t":"Mü’minler kurtuluşa, mutluluğa ermişlerdir."},{"n":2,"t":"Onlar ki, huşu içinde namaz kılarlar."},{"n":3,"t":"Onlar ki, boş ve yararsız şeylerle ilgilenmezler."},{"n":4,"t":"Onlar ki, zekâtı aksatmaksızın, tam olarak verirler."},{"n":5,"t":"Onlar ki; edep yerlerini sakınırlar."},{"n":6,"t":"Onlar yalnız eşleri ve cariyeleri dışında mahrem yerlerini herkesten korurlar. Bu iki durumda ayıplanmaları sözkonusu değildir."},{"n":7,"t":"Bunların ötesine geçmek isteyenler, yasal sınırı aşmış olurlar."},{"n":8,"t":"Onlar ki, uhdelerine verilen emanetleri korurlar ve sözlerini tutarlar."},{"n":9,"t":"Onlar ki, namazlarını aksatmaksızın kılarlar."},{"n":10,"t":"İşte onlar «varis» lerdir."},{"n":11,"t":"Yani «Firdevs» cennetinin mirasçılarıdırlar, sürekli olarak orada kalacaklardır."},{"n":12,"t":"Andolsun ki, biz insanı süzme çamurdan yarattık."},{"n":13,"t":"Sonra sperma halinde korunaklı bir yuvaya yerleştirdik."},{"n":14,"t":"Sonra spermayı embriyoya dönüştürdük. Arkasından embriyoyu et parçasına dönüştürdük, arkasından et parçasından kemikler yarattık, arkasından kemiklere et giydirdik. Sonra onu başka bir yaratığa dönüştürdük. Yaratıcıların en güzeli olan Allah ne yücedir!"},{"n":15,"t":"Sonra siz, bunun ardından öleceksiniz."},{"n":16,"t":"Sonra siz, kıyamet günü, yeniden diriltileceksiniz."},{"n":17,"t":"Üstünüzde birinden diğerine geçilebilen yedi katman yarattık. Bu yarattıklarımızı başıboş bırakmayız."},{"n":18,"t":"Biz gökten belirli miktarda su yağdırarak onu yerin yüzeyinde durdurduk. Hiç şüphesiz onu geri götürmeye de gücümüz yeter."},{"n":19,"t":"Bu su sayesinde sizin için hurma ve üzüm bağları yarattık. Bu bağlarda size yararlı birçok meyvalar yetişir, onları yiyorsunuz."},{"n":20,"t":"Yine su sayesinde asıl kaynağı Tur-i Sina olan ve yiyenlere yağ ve katık sağlayan ağacı da yarattık."},{"n":21,"t":"Büyükbaş hayvanlarda sizin için alınacak dersler vardır. Karınlarındaki sütten size içiriyoruz. Onlardan başka birçok yararlar sağlıyorsunuz ve etlerini yiyorsunuz."},{"n":22,"t":"Onların sırtlarında ve gemilerde taşınıyorsunuz."},{"n":23,"t":"Biz Nuh’u soydaşlarına peygamber olarak gönderdik. O dedi ki; «Ey soydaşlarım, Allah’a kulluk ediniz, O’ndan başka bir ilahınız yoktur. Allah’dan korkmaz mısınız?»"},{"n":24,"t":"Soydaşlarının önde gelen kâfirleri dediler ki; «Bu adam tıpkı sizin gibi bir insandır. Üzerinizde üstünlük kurmak istiyor. Eğer Allah dileseydi, bize bir melek gönderirdi. Onun söylediklerini eski atalarımızdan hiç duymamıştık.»"},{"n":25,"t":"Bu adam bir deliden başka bir şey değildir. Bir süre için onu gözetim altında tutunuz."},{"n":26,"t":"Nuh «Ya Rabb’i, onların bu yalanlamaları karşısında bana yardım et» dedi."},{"n":27,"t":"O’na vahiy yolu ile bildirdik ki; «Bizim gözlerimiz önünde ve vahyimiz uyarınca bir gemi yap. Emrimiz gelip de tandır kaynamaya (her yandan sular fışkırmaya) başlayınca her canlı türünün birer çifti ile boğulacağına ilişkin hükmümüzün kesinleştiği kimse dışında kalan aile bireylerini gemiye bindir. Zalimler konusunda bana başvurma; çünkü onlar kesinlikle boğulacaklardır.»"},{"n":28,"t":"Ey Nuh, sen ve beraberindekiler gemiye yerleştiğinizde «Bizi zalim soydaşlarımızdan kurtaran Allah’a hamdolsun» de."},{"n":29,"t":"Yine de ki; «Ya Rabb’i, beni bereketli bir yere indir. Sen kullarını en iyi yerlere konduransın.»"},{"n":30,"t":"Bu olayda alınacak birçok dersler vardır. Biz Nuh’u ve soydaşlarını bu yolla sınavdan geçirmiş olduk."},{"n":31,"t":"Onların ardından başka bir kuşak ortaya çıkardık."},{"n":32,"t":"Onlara da «Allah’a kulluk ediniz, O’ndan başka bir ilahınız yoktur, Allah’dan korkmaz mısınız» diyen kendilerinden bir peygamber gönderdik."},{"n":33,"t":"Soydaşları arasındaki ahiret buluşmasını yalanlayan ve kendilerine bol nimet verdiğimiz için baştan çıkan öncü kâfirler dediler ki; «Bu adam tıpkı sizin gibi bir insandır, sizin yediğinizden yiyor ve sizin içtiğinizden içiyor.»"},{"n":34,"t":"Eğer kendiniz gibi bir insana itaat edecek olursanız, o halde aldanmış cahiller olursunuz."},{"n":35,"t":"O sizi, ölüp toprak ve kemik olduktan sonra yeniden diriltileceksiniz diye mi korkutuyor?"},{"n":36,"t":"Heyhat, heyhat! Gerçekten ne kadar uzak bir korkutmadır bu!"},{"n":37,"t":"Hayat, bu dünyadaki hayatımızdan ibarettir. Kimimiz ölürüz, kimimiz yaşarız. Yeniden diriltileceğimiz sözkonusu değildir!"},{"n":38,"t":"O sadece Allah’a karşı yalan uyduran biridir. Biz ona inanmayız."},{"n":39,"t":"O peygamber «Ya Rabb’i, bunların yalanlamaları karşısında bana yardım et.»"},{"n":40,"t":"Allah «Onlar yakında pişman olacaklardır» dedi."},{"n":41,"t":"Derken ansızın hakettikleri müthiş bir gürültüye tutuluverdiler de kendilerini sel süprüntüsüne dönüştürdük. Kahrolsun zalimler güruhu!"},{"n":42,"t":"Onların ardından başka kuşaklar ortaya çıkardık."},{"n":43,"t":"Hiç bir ümmet, ecelini ne öne alabilir ve ne de erteleyebilir."},{"n":44,"t":"Sonra ardarda peygamberlerimizi gönderdik. Hangi ümmete peygamberi geldi ise onu yalanladılar. Biz de onları birbiri peşisırâ yokederek tarihi olaylara dönüştürdük. Kahrolsun inanmayanlar güruhu!"},{"n":45,"t":"Sonra Musa ile kardeşi Harun’u ayetlerimiz ile ve açık kanıtla destekli olarak gönderdik."},{"n":46,"t":"Firavun ile onun önde gelen adamlarına. Fakat onlar büyüklük kompleksine kapılarak iman etmeye yanaşmadılar. Zaten onlar kendilerini beğenmiş kimselerdi."},{"n":47,"t":"Onlar dediler ki; «Kendimiz gibi birer insan olan şu iki adama mı inanacağız ki, onların soydaşları bize tapıyorlar?»"},{"n":48,"t":"Onları yalanladılar ve bu yüzden yok edildiler."},{"n":49,"t":"Soydaşları doğru yolu bulsunlar diye Musa’ya kitap verdik."},{"n":50,"t":"Meryemoğlu İsa ile annesini gücümüzün bir kanıtı olarak ortaya çıkardık. Onları yaşamaya elverişli ve akarsulu bir tepeye yerleştirdik."},{"n":51,"t":"Ey peygamberler, temiz yiyeceklerden yiyiniz ve iyi ameller işleyiniz. Hiç kuşkusuz ben sizin neler yaptığınızı bilirim."},{"n":52,"t":"Sizin de bir parçasını oluşturduğunuz şu ümmet, tek bir ümmettir, ben de sizin Rabb’inizim. Öyleyse sırf benden korkunuz."},{"n":53,"t":"Fakat insanlar bu inanç birliğini yıkarak çeşitli gruplara ayrıldılar. Her grup kendi inanç sistemi ile övündü."},{"n":54,"t":"Bir süre için onları gafletleri ve sapıklıkları ile başbaşa bırak."},{"n":55,"t":"Onlar sanıyorlar mı ki, kendilerine verdiğimiz servetle ve evlatlarla,"},{"n":56,"t":"Onların iyiliklerine koşuyoruz? Aslında onlar işin farkında değildirler."},{"n":57,"t":"Onlar ki, Rabb’lerinin korkusu ile titriyorlar."},{"n":58,"t":"Ve onlar ki, Rabb’lerinin ayetlerine inanıyorlar."},{"n":59,"t":"Ve onlar ki, Rabb’lerine ortak koşmuyorlar."},{"n":60,"t":"Ve onlar ki, Rabb’lerine dönecekler diye kalpleri ürpererek verdikleri şeyi verirler."},{"n":61,"t":"İşte onlar iyiliklerde yarışanlar ve bu yarışı önde bitirenlerdir."},{"n":62,"t":"Biz herkese taşıyabileceği kadar yük yükleriz. Bizim katımızda, gerçeği olduğu gibi söyleyen bir kitap vardır. Onlara asla haksızlık edilmez."},{"n":63,"t":"Fakat kâfirlerin kalpleri, mü’minlerin bu davranışlarından tamamen habersizdir. Onların, bunlar dışında, birtakım kötü işleri var ki, sürekli olarak onlarla meşguldürler."},{"n":64,"t":"Ama onların azılı elebaşlarının yakasına azabımızla yapıştığımızda hemen feryadı basarlar."},{"n":65,"t":"Bugün boşuna feryad etmeyiniz, bizden yardım göremeyeceksiniz."},{"n":66,"t":"Vaktiyle ayetlerimiz size okunduğunda yüzünüzü arkanıza çevirirdiniz."},{"n":67,"t":"Ayetlerimize dudak bükerek gizli toplantılarınızda saçmalıyordunuz."},{"n":68,"t":"Acaba onlar Kur’anı incelemediler mi? Yoksa onlara, eski atalarına gelmemiş olan bir mesaj mı geldi?"},{"n":69,"t":"Yoksa peygamberlerini tanıyamadılar da bu yüzden mi ona karşı çıkıyorlar?"},{"n":70,"t":"Yoksa onun deli olduğunu mu söylüyorlar. Hayır, O onlara gerçeği getirdi ve onların çoğu gerçekten hoşlanmıyorlar."},{"n":71,"t":"Eğer gerçek onların keyfi arzularına uysaydı, göklerin, yerin ve gökler ile yerde bulunan canlı cansız tüm varlıkların düzeni ve dengesi bozulurdu. Aslında onlara nam ve şan bağışladık. Fakat onlar kendi nam ve şanlarına sırt dönüyorlar."},{"n":72,"t":"Yoksa sen onlardan ücret mi istiyorsun ki? Oysa Rabb’inin sana vereceği ücret daha üstündür. O rızık verenlerin en iyisidir."},{"n":73,"t":"Aslında sen onları doğru yola çağırıyorsun."},{"n":74,"t":"Ama ahirete inanmıyorlar doğru yolun uzağına düşüyorlar."},{"n":75,"t":"Eğer biz onlara acısak da başlarındaki sıkıntıyı gidersek yine azgınlıkları içinde debelenmeye ısrar ederler."},{"n":76,"t":"Biz onların yakalarına azapla yapıştık. Fakat ne Rabb’lerine boyun eğdiler ve ne de O’na yalvardılar."},{"n":77,"t":"Ama ağır bir azabın kapısını yüzlerine açtığımızda kurtuluş ümitlerini yitirerek ne yapacaklarını şaşırırlar."},{"n":78,"t":"Gözü, kulakları ve gönülleri yaratıp size veren O’dur. Ne kadar az şükrediyorsunuz!"},{"n":79,"t":"Sizi yeryüzüne yerleştiren O’dur ve O’nun huzurunda toplanacaksınız."},{"n":80,"t":"Sizi yaratan ve öldüren O’dur. Gecenin ve gündüzün birbirini izlemesi O’nun uygulamasıdır. Hiç düşünmeyecek misiniz?"},{"n":81,"t":"Tersine onlar daha önceki sapıkların dediklerini söylediler."},{"n":82,"t":"Biz ölüp de toprak ve kemik olduktan sonra yeniden mi diriltileceğiz?"},{"n":83,"t":"Bu tehdit şimdi bize yöneltildiği gibi daha önce atalarımıza da yöneltilmişti. Bu eskilerin masallarından başka bir şey değildir."},{"n":84,"t":"Onlara de ki, «Eğer biliyorsanız, söyleyiniz, yeryüzü ve üzerindeki tüm varlıklar kimindir?»"},{"n":85,"t":"Sana «Allah’ındır» diyecekler. De ki; «Siz kafanızı çalıştırmayacak mısınız?»"},{"n":86,"t":"Onlara de ki; «Yedi göğün ve yüce Arş’ın Rabb’i kimdir?"},{"n":87,"t":"Sana «Bunlar Allah’ındır» diyecekler. De ki; «Siz hiç O’ndan korkmaz mısınız?"},{"n":88,"t":"Onlara de ki; «Eğer biliyorsanız, söyleyiniz; tüm varlıkların egemenliği, elinde olan, her şeyi koruyup gözeten, Fakat koruyanı ve işine karışanı olmayan kimdir?»"},{"n":89,"t":"Sana «Bu yetki Allah’a aittir» diyecekler. De ki; «O halde nasıl oluyor da yanıltılıyorsunuz?»"},{"n":90,"t":"Aslında biz onlara gerçeği sunduk, fakat onlar yalan söylüyorlar."},{"n":91,"t":"Allah evlat edinmemiştir ve O’nun yanısıra bir başka ilah yoktur. Yoksa her ilah, kendi yaratıklarını otoritesi altına alıp bir yana gider ve biri öbürüne karşı üstünlük kurmaya çalışırdı. Allah onların bu asılsız yakıştırmalarından münezzehtir."},{"n":92,"t":"O görünmeyeni de görüneni de bilir. O onların koştukları ortaklardan münezzehtir."},{"n":93,"t":"De ki; «Ya Rabb’i, eğer onların tehdit edildikleri azabı eğer mutlaka bana göstereceksen.»"},{"n":94,"t":"Ya Rabb’i, beni zalimler arasında bırakma."},{"n":95,"t":"Onlara yönelttiğimiz tehdidin gerçekleştiğini sana göstermeye elbette gücümüz yeter."},{"n":96,"t":"Sana yaptıkları kötülüğü en iyi davranışla karşıla. Biz onların asılsız yakıştırmalarını herkesten iyi biliyoruz."},{"n":97,"t":"De ki; «Ya Rabb’i, şeytanların kışkırtmalarından sana sığınırım.»"},{"n":98,"t":"Onların yanımda olmalarından da sana sığınırım, ya Rabb’i."},{"n":99,"t":"Sonunda onlardan biri ölümün eşiğine geldiğinde der ki; «Ya Rabb’i, beni geri çeviriniz.»"},{"n":100,"t":"Ki, ihmalkâr davrandığım konularda iyi ameller işleyeyim. Asla. Bu söz, boş yere söylenmiş yararsız bir lâftır. Yeniden dirilecekleri güne kadar onların önünde geçit vermez bir engel vardır."},{"n":101,"t":"Sura üflendiği zaman, o gün artık aralarında soy bağı kalmaz ve birbirlerine hal hatır sormazlar."},{"n":102,"t":"Kimlerin tartıları ağır gelirse onlar kurtuluşa ermişlerdir."},{"n":103,"t":"Kimlerin tartıları hafif kalırsa onlar kendilerini mahvetmişlerdir, çünkü sonsuza dek cehennemde kalacaklardır."},{"n":104,"t":"Orada ateş yüzlerini yalar, bu yüzden dudakları kasılacağı için dişleri sırıtır."},{"n":105,"t":"Ayetlerimiz size okunduğunda onları yalanlıyordunuz, öyle değil mi?"},{"n":106,"t":"Cehennemlikler derler ki; «Ey Rabb’imiz, kötü arzularımıza yenik düşerek sapık bir topluluk olduk.»"},{"n":107,"t":"Ey Rabb’imiz, bizi buradan çıkar, eğer eski tutumumuza dönersek biz gerçekten zalim oluruz."},{"n":108,"t":"Allah, der ki; «Kesin sesinizi ve sürünün orada; bana bir şey söylemeyin.»"},{"n":109,"t":"Hani vaktiyle kullarımın bir bölümü ’Ey Rabb’imiz, biz sana inandık, bizi affeyle, bize merhamet et, sen merhamet edenlerin en iyisisin’ diyorlardı.»"},{"n":110,"t":"Siz onları alaya alıyordunuz. Sonunda bu tutumunuz beni anmayı size unutturdu, artık onlara hep gülüyordunuz."},{"n":111,"t":"Bugün ben onlara sabretmelerinin karşılığını verdim, şimdi onlar kurtuluşa, mutluluğa ermişlerdir."},{"n":112,"t":"Allah, cehennemliklere der ki; «Siz yeryüzünde kaç yıl yaşadınız?»"},{"n":113,"t":"Cehennemlikler derler ki; «Orada ya bir gün, ya da bir günden daha az yaşadık, saymış olanlara sor.»"},{"n":114,"t":"Allah, onlara der ki; «Orada az bir süre kaldınız. Keşki bunu vaktiyle bilmiş olsaydınız.»"},{"n":115,"t":"Sizi boşuna yarattığımızı ve huzurumuza döndürülmeyeceğinizi mi sandınız?"},{"n":116,"t":"Egemenliğin ortaksız sahibi ve gerçek olan Allah, her türlü noksanlıktan münezzehtir; O’ndan başka ilah yoktur ve yüce Arş’ın sahibidir."},{"n":117,"t":"Kim kanıtlayıcı bir delile dayanmadığı halde Allah’ın yanısıra başka bir ilaha taparsa onun hesabını Rabb’i görecektir. Hiç kuşkusuz kâfirler iflah olmazlar."},{"n":118,"t":"De ki; «Beni affeyle, bana merhamet et, sen merhamet edenlerin en iyisisin.»"}],[{"n":1,"t":"Bu indirip hükümlerini farz kıldığımız bir suredir. Öğüt alasınız diye onda apaçık ayetler indirdik."},{"n":2,"t":"Zina eden kadın ve erkeğin herbirine yüzer sopa vurunuz. Allah’a ve ahiret gününe inanıyorsanız, O’nun dini konusunda onlara acımayınız. Onların ceza görmesine mü’minlerden bir grup da şahit olsun."},{"n":3,"t":"Zina eden erkek, ancak zina eden ya da Allah’a ortak koşan bir kadınla evlenebilir. Zina eden kadınla da ancak zina eden ya da Allah’a ortak koşan bir erkek evlenebilir. Bu tür evlilikler mü’minlere yasaklanmıştır."},{"n":4,"t":"İffetli kadınlara zina etmekle suçladıktan sonra, bu konuda dört şahit gösteremeyenlere seksen sopa vurunuz ve artık şahitliklerini hiç kabul etmeyiniz. Onlar yoldan çıkmış kimselerdir."},{"n":5,"t":"Yalnız bu iftira suçunun arkasından tevbe ederek tutumlarını düzeltenler bu hükmün kapsamı dışındadırlar. Çünkü Allah affedicidir, merhametlidir."},{"n":6,"t":"Eşlerini zina etmekle suçlayan ve bu konuda kendilerinden başka şahit gösteremeyen erkekler, eğer Allah hakkı için doğru söylediklerine ilişkin dört kez yemin ederlerse, tek başlarına yaptıkları bu şahitlik, dört şahitlik yerine geçer."},{"n":7,"t":"Beşinci keresinde de «Eğer yalan söylüyorsam, Allah’ın lanetine uğrayayım» demeleri gerekir."},{"n":8,"t":"Fakat suçlanan kadının «Allah hakkı için kocam yalan söylüyor» diye kendi adına dört kez şahitlik etmesi, kendisini cezaya çarpılmaktan kurtarır."},{"n":9,"t":"Böyle bir kadının beşinci defasında da «Eğer kocamın söylediği doğru ise Allah’ın laneti üzerime olsun» demesi gerekir."},{"n":10,"t":"Eğer Allah’ın size yönelik lütfu ve merhameti olmasaydı, eğer O tövbelerin kabul edicisi ve hikmet sahibi olmasaydı, acaba haliniz ne olurdu?"},{"n":11,"t":"O ağır iftirayı ortaya atanlar, sizden bir gruptur. Bu olayı kendiniz için kötü bir şey sanmayınız. Tersine o sizin için iyidir. O grubun içinde bulunan herkes payına düşen günahın cezasını görecektir. Suçun büyük bölümünü omuzlarında taşıyan o grubun elebaşısı ise büyük bir azaba çarpılacaktır."},{"n":12,"t":"O iftirayı işittiğinizde erkek kadın bütün mü’minlerin, kendileri hakkında hüsn-ü zan besleyerek, özlerine leke kondurmaya yanaşmayarak «Bu apaçık bir iftiradır» demeleri gerekmez miydi?"},{"n":13,"t":"Bu konuda dört şahit göstermeleri gerekmez miydi? Madem ki, bu şahitleri gösteremediler, o halde onlar Allah katında yalancıların ta kendileridirler."},{"n":14,"t":"Eğer dünyada ve ahirette Allah’ın size yönelik lütfu ve merhameti olmasaydı, yoğun dedikodu yaptığınız bu iftiradan dolayı büyük bir azaba çarpılırdınız."},{"n":15,"t":"Hani bu iftirayı dilden dile yayıyordunuz. Hakkında hiçbir bilgiye sahip olmadığınız bu söylentiyi rastgele ağızlarınızda geveliyordunuz. Yaptığınız kötülüğü önemsiz sanıyordunuz. Oysa o, Allah katında ağır bir suçtu."},{"n":16,"t":"Onu işittiğiniz zaman «Bu konuda konuşmak bize yakışmaz. Haşa Allah’a! Bu ağır bir iftiradır» demeniz gerekmez miydi?"},{"n":17,"t":"Allah size öğüt veriyor ki, eğer mü’min iseniz böyle bir hataya bir daha asla düşmeyesiniz."},{"n":18,"t":"Allah, aynı zamanda, size ayetlerini ayrıntılı biçimde açıklıyor. Allah her şeyi bilir ve her yaptığını yerinde yapar."},{"n":19,"t":"Mü’minler arasında ahlâksızlığın ve edepsizliğin yayılmasını isteyenleri gerek dünyada ve gerekse ahirette acıklı bir azap beklemektedir. Allah bilir, oysa siz bilmezsiniz."},{"n":20,"t":"Eğer Allah’ın size yönelik lütfu ve merhameti olmasaydı, eğer o son derece esirgeyen ve acıyan olmasaydı, acaba haliniz ne olurdu?"},{"n":21,"t":"Ey mü’minler, sakın şeytanın izinden gitmeyiniz. Kim şeytanın izinden giderse bilsin ki, o edepsizliği, ahlâksızlığı ve çirkin davranışları emreder. Eğer Allah’ın size yönelik lütfu ve merhameti olmasaydı hiçbiriniz asla kötülüklerden arınamazdı. Ama Allah dilediği kimseleri kötülüklerden arındırır. Allah her şeyi işitir, her şeyi bilir."},{"n":22,"t":"Aranızdaki erdemli ve varlıklı kimseler yakınlarına, yoksullara ve Allah yolunda yurtlarından göçedenlere yardım etmeyeceklerine yemin etmesinler. Allah sizi affetsin istemez misiniz? Allah affedicidir, merhametlidir."},{"n":23,"t":"Zinadan haberi bulunmayan iffetli mümin kadınlara, zina isnad edenler, dünyada ve ahirette lanete uğramışlardır. Onlara büyük bir azap vardır."},{"n":24,"t":"O gün dilleri, elleri ve ayakları işledikleri kötülük konusunda aleyhlerinde şahitlik edecektir."},{"n":25,"t":"O gün Allah onlara hakettikleri cezayı tam olarak verecek ve onlar Allah’ın, apaçık «gerçek» olduğunu anlayacaklardır."},{"n":26,"t":"Kötü kadınlar, kötü erkeklere ve kötü erkekler, kötü kadınlara yakıştıkları gibi, temiz kadınlar, temiz erkeklere ve temiz erkekler, temiz kadınlara yakışırlar. Temizler, kötülerin kendilerine yönelik dedikodularından uzaktırlar. Bunları, Allah’ın bağışlayıcılığı ve onurlu rızık beklemektedir."},{"n":27,"t":"Ey mü’minler kendi evlerinizin dışındaki evlere izin alıp halkına selam vermeden girmeyiniz. Böyle davranmak sizin için daha hayırlıdır. Ola ki düşünür sebebini anlarsınız."},{"n":28,"t":"Eğer kapısını çaldığında evde hiç kimse yoksa size izin verilmedikçe içeriye girmeyiniz. Eğer size «geri dönün» denirse geri dönünüz. Böylesi, sizin için daha onurlu bir harekettir. Hiç kuşkusuz Allah, ne yaparsanız onu bilir."},{"n":29,"t":"Şenlik olmayan ve içinde eşyanızın bulunduğu evlere izinsiz girmenizin hiçbir sakıncası yoktur. Allah sizin gerek açığa vurduğunuz ve gerekse gizli tuttuğunuz bütün duygularınızı bilir."},{"n":30,"t":"Mü’min erkeklere gözlerini harama bakmaktan sakındırmalarını ve mahrem yerlerini korumalarını söyle. Bu onlar için en güvenceli arınma yoludur. Hiç şüphesiz onlar ne yaparsa Allah ondan haberdardır."},{"n":31,"t":"Mü’min kadınlara de ki; gözlerini harama bakmaktan sakındırsınlar, mahrem yerlerini korusunlar. Kendiliğinden görünenleri dışındaki süslerini teşhir etmesinler. Baş örtülerinin uçlarını yaka altlarına kadar sarkıtsınlar. Süslerini ve cazibelerini kocalarından, babalarından, kayınbabalarından, öz oğullarından, üvey oğullarından, erkek kardeşlerinden, erkek kardeşlerinin oğullarından, kız kardeşlerinin oğullarından, müslüman kadınlardan, elleri altındaki kölelerden, cinsel arzuları sönmüş erkek hizmetçilerden, kadınların avret yerlerinin henüz farkında olmayan erkek çocuklarından başka hiç kimseye göstermesinler. Yabancı bakışlardan gizledikleri süsleri ve cazibeleri belli olsun diye ses çıkaracak adımlarla yürümesinler."},{"n":32,"t":"Aranızdaki bekârlar ile iyi davranışlı köle ve cariyelerinizi evlendiriniz. Eğer bunlar fakir iseler, Allah’ın lütfu ile zenginleşirler. Allah’ın nimeti boldur ve O herşeyi bilir."},{"n":33,"t":"Evlenme imkanı bulamayanlar, Allah’ın lütfu ile kendilerini zenginleştirene kadar namuslu kalmaya özen göstersinler, zinadan kaçınsınlar. Ödeyecekleri belirli bir bedel karşılığında özgürlüklerine kavuşmak üzere sizinle sözleşme yapmak isteyen elinizin altındaki köleler ile, kendilerinde iyi insan olma belirtileri gördüğünüz taktirde sözleşme yapınız. Allah’ın size bağışladığı servetinizden onlara yardım ediniz. Namuslu kalmak isteyen cariyelerinizi dünyalık çıkarlarınız uğruna fuhuşa zorlamayınız. Kim onları zorlarsa bilsin ki, uğradıkları zorlamadan sonra Allah onlar hakkında affedicidir ve merhametlidir."},{"n":34,"t":"And olsun ki Biz apaçık ayetler ve sizden önce geçenlerden misaller ve takvaya erenler için de öğütler indirdik."},{"n":35,"t":"Allah göklerin ve yerin nurudur. O’nun nuru, içinde kandil yanan bir projektöre benzer, kandil bir fanus içindedir ve bu fanus sanki inci gibi parıldayan bir yıldızdır. Bu kandil yakıtını, bereketli bir zeytin ağacının yağından sağlar. Ağaç, ne doğuya ve ne de batıya bakmayan ve bu yüzden sürekli güneş alan bir arazide yetiştiği için yağı, hiç ateşe değmese bile kendiliğinden tutuşup ışıyacak kadar saftır. O nur üzerine nurdur. Allah dilediği kimseleri bu nura iletir. Allah insanlara somut örnekler verir. Allah herşeyi bilir."},{"n":36,"t":"Bu projektör; Allah’ın yüceltilmelerini ve içlerinde adının anılmasını emrettiği evlerde yanar. Bu evlerde birtakım kimseler sabah ve akşam Allah’ı her tür noksanlıktan tenzih ederler."},{"n":37,"t":"Bu kimseleri ne ticaret, ne alışveriş, Allah’ı anmaktan, namazı kılmaktan ve zekâtı vermekten alıkoymaz. Onlar kalplerin hoplayacakları ve gözlerin donakalacağı bir günün dehşetinden korkarlar."},{"n":38,"t":"Amaçları, Allah’ın kendilerini işledikleri amellerin en güzel karşılığı ile ödüllendirmesi ve lütfu ile bundan da daha fazlasını vermesidir. Allah dilediği kimselere hesapsız rızık bağışlar."},{"n":39,"t":"Kâfirlerin amelleri ise engin çöllerdeki serap gibidir. Susuz kimse onu su zanneder, fakat oraya varınca hiçbir şey bulamaz. Kâfir karşısında Allah’ı bulur. O da hesabını eksiksiz olarak görür. Zaten Allah’ın hesaplaşması çabuktur."},{"n":40,"t":"Kâfirlerin amellerinin bir başka benzeri engin bir denizin karanlıklarıdır. Bu denizi üstüste binen dalgalar ve dalgaları da bulut örter. Orada karanlıklar üstüste binmiştir. Öyle ki insan elini uzatsa onu farkedemez bile. Allah’ın nur vermediği kimsenin nuru olamaz."},{"n":41,"t":"Göklerdeki ve yerdeki tüm varlıkların ve havada süzülen kuşların Allah’ı noksanlıklardan tenzih ettiklerini görmüyor musun? Bu varlıkların tümü, Allah’a nasıl dua edeceğini, O’nu nasıl noksanlıklardan tenzih edeceğini bilir. Allah da onların ne yaptıklarını bilir."},{"n":42,"t":"Göklerin ve yerin egemenliği Allah’ın tekelindedir ve herkes Allah’a dönecektir."},{"n":43,"t":"Görmüyor musun ki, Allah bulutları oradan oraya sürüyor, sonra birleştiriyor, Sonra üstüste yığıp yoğunlaştırıyor. Arkasından aralarından yağmur yağdığını görürsün. Yine Allah gökten dağlar gibi dolu yüklü bulutlar indiriyor. Bu doluyu dilediklerinin başına yağdırıyor ve dilediklerinden uzak tutuyor. Bulutlardan çıkan şimşeğin parıltısı, gözleri kamaştırır."},{"n":44,"t":"Allah, geceyi gündüze ve gündüzü geceye dönüştürür. Hiç kuşkusuz dikkatli gözlemcilerin bu olaydan alacakları dersler vardır."},{"n":45,"t":"Allah bütün canlıları sudan yarattı. Bu canlıların kimi karnı üzerinde sürünür. Kimi iki ayakla yürür. Kimisi de dört ayakla yürür. Allah dilediği gibi yaratır. Hiç kuşkusuz Allah’ın gücü her şeye yeter."},{"n":46,"t":"Biz gerçekten ayrıntılı açıklamalar içeren ayetler indirdik. Allah, dilediği kimseleri doğru yola iletir."},{"n":47,"t":"Bazı kimseler «Allah’a ve Peygamber’e inandık ve direktiflerine uymayı kabul ettik» derler. Fakat bazıları bu sözlerinden sonra sırt çevirirler. Bunlar mü’min değildirler."},{"n":48,"t":"Aralarındaki davalarda Allah’ın ve Peygamberin vereceği hükme uymaya çağırıldıklarında bir bölümünün bu çağrıya yüz çevirdiğini görürsün."},{"n":49,"t":"Eğer davanın haklı tarafı iseler, Peygamber’e tam bir teslimiyetle koşa koşa gelirler."},{"n":50,"t":"Acaba kalplerinde hastalık mı var? Yoksa Peygamber’in gerçekten peygamber olup olmadığı hususunda kuşkulu mudurlar? Yoksa Allah’ın ve Peygamber’in kendilerine haksızlık edeceğinden mi korkuyorlar. Hayır, aslında onlar zalimdirler."},{"n":51,"t":"Aralarındaki davalarda Allah’ın ve Peygamberin vereceği hükme uymaya çağırılan mü’minlerin söyleyebilecekleri tek söz «Duyduk ve uyduk» sözüdür. İşte mutlu sona erenler onlardır."},{"n":52,"t":"Allah’a ve Peygambere itaat edenler, Allah’dan korkup buyruklarını çiğnemekten kaçınanlar var ya, işte kurtuluşa erenler onlardır."},{"n":53,"t":"Ey Muhammed, münafıklar kesin kesin bir dille yemin ederek kendilerine emir verecek olursan savaşa çıkacaklarını söylerler. Onlara de ki; «Yemin etmeyiniz. İtaatkârlığınız bellidir. Hiç kuşkusuz Allah, ne yaptığınızdan haberdardır.»"},{"n":54,"t":"Onlara de ki, «Allah’a itaat ediniz, Peygambere itaat ediniz. Eğer bu çağrıya yüz çevirirseniz, biliniz ki, Peygamber kendi görevinden sorumlu olduğu gibi, siz de kendi görevinizden sorumlusunuz. Peygambere düşen, sadece ilahi mesajı açık bir dille duyurmaktır.»"},{"n":55,"t":"Allah, aranızdaki iman edip iyi ameller işleyenlere, kendilerini tıpkı daha önceki mü’minler gibi yeryüzünde egemen kılacağını, kendileri için seçtiği dinlerini sarsılmaz temellere oturtacağını ve korkularını güvene dönüştüreceğini vadetti. Çünkü onlar bana kulluk ederler, hiçbir şeyi bana ortak koşmazlar. Bu aşamadan sonra kâfir olanlara gelince, onlar yoldan çıkmışların ta kendileridirler."},{"n":56,"t":"Namazı kılınız, zekâtı veriniz ve Peygambere itaat ediniz ki, Allah’ın rahmetinden pay alabilesiniz."},{"n":57,"t":"Kâfirlerin yeryüzündeki güçlerinin karşı konulmaz olduğunu sanmayınız. Onların varacakları yer cehennemdir. Orası ne kötü bir varılacak yerdir!.."},{"n":58,"t":"Ey Mü’minler, elinizin altındaki köleler ve hizmetçiler ile aranızdaki henüz ergenlik çağına girmemiş gençler, günün şu üç vaktinde, yani sabah namazından önce, öğle sıcağında soyunduğunuz saatlerde ve yatsı namazından sonra odanıza girerken sizden izin istesinler. Bu vakitler mahrem yerlerinizin açık olabileceği vakitlerdir. Bu vakitler dışında ne sizin için ve ne de onlara bir sakınca yoktur. Birbirinizin odalarına rahatça girebilirsiniz. İşte Allah size ayetlerini böylesine ayrıntılı biçimde açıklar. Allah her şeyi bilir ve O’nun her işinin, her buyruğunun mutlaka bir gerekçesi vardır."},{"n":59,"t":"Çocuklarınız ergenlik çağına girince günün saydığımız vakitlerinde odanıza girerken tıpkı kendilerinden büyüklerin yaptıkları gibi izin istesinler. İşte Allah size ayetlerini böylesine ayrıntılı biçimde açıklar. Allah her şeyi bilir ve O’nun hiçbir işi hiçbir buyruğu sebepsiz değildir."},{"n":60,"t":"Evlenme ümidi olmayan, doğurganlık çağını geride bırakmış yaşlı kadınların, süslerini göstererek erkeklerin ilgisini çekme amacı taşımamak şartı ile ev dışında giyilecek elbiselerini giymemelerinin sakıncası yoktur. Fakat kapalı giyim konusunda titiz davranmaları kendileri için daha iyidir. Allah her sözü işitir ve her şeyi bilir."},{"n":61,"t":"Körlerin, topalların ve hastaların anahtarları kendilerine emanet edilmiş evlere girip yemek yemekten çekinmeleri gereksizdir. Sizler de evlatlarınızın, babalarınızın, atalarınızın, erkek kardeşlerinizin, kız kardeşlerinizin, amcalarınızın, halalarınızın, dayılarınızın, teyzelerinizin, arkadaşlarınızın evlerinin veya anahtarları yanınızda bulunan evlerin yemeklerinden yiyebilirsiniz. Gerek birarada ve gerekse ayrı ayrı yemek yemenizin sakıncası yoktur. Şenlikli evlere girdiğinizde Allah tarafından yasallaştırılmış kutlu ve hoşnutluk uyandırıcı bir esenlik dileği olmak üzere içerdeki dindaşlarınıza selâm veriniz. Allah size ayetlerini düşünesiniz diye böyle açıklar."},{"n":62,"t":"Mü’minler ancak Allah’a ve Resul’üne iman edenler ve peygamberle birlikte bir işe karar vermek için toplandıklarında ondan izin isteyip alıncaya kadar gitmeyenlerdir. Gerçekten senden izin isteyenler, işte onlar Allah’a ve Resulüne inananlardır. Birtakım işleri için senden izin isterlerse içlerinden dilediğine izin ver. Ve Allah’tan onların bağışlanmalarını dile. Şüphesiz ki Allah, Gafur’dur, Rahim’dir."},{"n":63,"t":"Peygamberi çağırırken O’na, birbirinize seslendiğiniz gibi seslenmeyiniz. (Ya da Peygamber sizi çağırdığında O’nun çağrısını, aranızda birbirinize yönelttiğiniz çağrılarla bir tutmayınız.) Allah, arkadaşlarını siper ederek gizlice Peygamberin yanından sıvışanları iyi bilir. O’nun emrini çiğneyenler ya başlarına bir bela gelmesinden ya da acıklı bir azaba çarpılmaktan korkmalıdırlar."},{"n":64,"t":"Haberiniz olsun ki, göklerde ve yerde ne varsa hepsi Allah’a aittir. O, kullarının ne yaptıklarını ve ne düşündüklerini bilir. O’nun huzuruna çıkarıldıkları gün herkese yaptıklarını haber verecektir. Allah her şeyi bilir."}],[{"n":1,"t":"Eğri ile doğruyu birbirinden ayıran Kur’anı, tüm insanları ve cinnleri uyarsın diye kulu Muhammed’e indiren Allah’ın şanı yücedir."},{"n":2,"t":"O ki, göklerin ve yerin egemenliği O’nun tekelindedir hiç evlat edinmemiştir; egemenlikte ortağı yoktur; O her şeyi yaratmış ve bir ön tasarıya göre düzenlenmiştir."},{"n":3,"t":"Müşrikler Allah’ı bir yana bırakarak hiç bir şey yaratamayan kendileri birer yaratık olan, kendilerine ne zarar ve ne de fayda dokunduramayan; öldürmeye, yaşatmaya ve yeniden diriltmeye güçleri yetmeyen ilahlar edindiler."},{"n":4,"t":"Kafirler «Şu Kur’an, Muhammed’in uydurduğu bir yalandır. Bu uydurma işinde kendisine yardım eden başkaları da vardır» dediler. Onlar gerçekten zulüm işlemişler ve yalan söylemişlerdir."},{"n":5,"t":"Yine onlar «Bu Kur’an, eski milletlerin masallarıdır. Muhammed onu adamlarına kopya ettirmiştir ve bu kopyalar sabahları ve akşamları kendisine okunmaktadır» dediler."},{"n":6,"t":"Onlara de ki; «Bu Kur’anı, göklerin ve yerin sırlarını bilen Allah indirdi. Hiç kuşkusuz O, affedicidir ve merhametlidir.»"},{"n":7,"t":"Yine onlar dediler ki; «Bu ne biçim Peygamberdir ki, bizim gibi yemek yiyor ve çarşıda pazarda geziyor? Ona, kendisi ile birlikte uyarma görevi yürüten bir melek indirilseydi ya.»"},{"n":8,"t":"Ya da kendisine bir hazine verilseydi veya ürünleri ile beslenebileceği bir bahçesi olsaydı. Bu zalimler, müminlere «Sizler, büyülenmiş, akli dengesi bozuk bir adamın peşinden gidiyorsunuz» dediler."},{"n":9,"t":"Senin hakkında ne yakışıksız benzetmeler düzdüklerini görüyor musun? Onlar sapmışlardır ve doğru yolu bir türlü bulamıyorlar."},{"n":10,"t":"Eğer dilerse sana, onların sözünü ettiklerinden daha iyisini, yani altlarından çeşitli nehirler akan cennetleri verebilen ve senin için köşkler hazırlayabilen Allah’ın şanı yücedir."},{"n":11,"t":"Aslında onlar Kıyamet gününü yalanlamışlardır. Biz de Kıyamet gününü yalanlayanlara çılgın alevli bir ateş hazırladık."},{"n":12,"t":"Bu ateş onları uzaktan görünce onun uğultusu ve öfkeli solumaları kulaklarına gelir."},{"n":13,"t":"Zincirlerle elleri, ayaklarına bağlanmış olarak bu ateşin dar yerine atıldıklarında ise orada «yok olmayı» imdada çağırırlar."},{"n":14,"t":"Kendilerine «bugün bir kere yokolmayı değil, bir çok kez yokolmayı imdada çağırınız» diye seslenilir."},{"n":15,"t":"De ki; «Bu mu iyidir, yoksa Allah’tan korkanlara vaadedilen, onlar için ödül ve barınak olarak hazırlanan ebedi cennet mi?»"},{"n":16,"t":"Bu Rabb’inin gerçekleştirilmesi istenmiş vaadidir."},{"n":17,"t":"Rabb’in, müşrikler ile onların Allah’ı bir yana bırakarak taptıkları düzmece ilahlarını biraraya topladığı gün, düzmece ilahlara «Şu kullarımı siz mi saptırdınız, yoksa kendileri mi yoldan çıktılar?» der."},{"n":18,"t":"Düzmece ilahlar derler ki; «Sen her türlü noksanlıktan münezzehsin! Senin dışında başka korucular ve dayanaklar edinmek bize yakışacak bir tutum değildir. Fakat sen onlara ve atalarına o kadar bol nimetler verdin ki; sonunda seni anmayı unutarak yok edilmeyi hakeden bir topluluk oldular.»"},{"n":19,"t":"Bunun üzerine Allah, müşriklere der ki; «İşte düzmece ilahlarınız, sizin sözlerinizi yalanladılar. Artık ne azabımı başınızdan savabilirsiniz ve ne size yardım edecek birini bulabilirsiniz. Aranızdaki zalimlere büyük bir azap taddıracağız.»"},{"n":20,"t":"Senden önceki gönderdiğim bütün peygamberler de herkes gibi yemek yerler ve çarşıda, pazarda gezerlerdi. Sizleri birbirleriniz aracılığı ile sınavdan geçiriyoruz. Acaba karşılaştığınız sıkıntılara katlanabilecek misiniz diye. Hiç şüphesiz Rabb’in her şeyi görür."},{"n":21,"t":"Bizimle karşılaşacaklarını beklemeyenler «bize melekler gönderilmeli değil miydi, ya da doğrudan doğruya Rabb’imizi görmeli değil miydik» dediler. Onlar büyüklük kompleksine kapılarak azgınlıkta son derece ileri gitmişlerdir."},{"n":22,"t":"Melekleri görecekleri gün var ya, o gün o günahkarlara müjdeli bir haber verilecek değildir. Melekler onlara «Sizler aftan ve cennetten mahrumsunuz» derler."},{"n":23,"t":"Onların yapmış olduklarını ele alarak onları havada uçuşan toza dönüştürürüz."},{"n":24,"t":"O gün cennetlikler en iyi yerlerde oturacaklar, en güzel şekilde dinleneceklerdir."},{"n":25,"t":"O gün gök parçalanarak beyaz bulut kümelerine dönüşür ve melekler bölük bölük inerler."},{"n":26,"t":"Gerçek egemenliğin, Rahman olan Allah’ın tekelinde olacağı o gün kafirler için çetin bir gün olacaktır."},{"n":27,"t":"O gün her zalim öfkesinden parmaklarını ısırarak şöyle der; «Keşki Peygamber’in yoldaşı olsaydım.»"},{"n":28,"t":"Yazık bana! Keşke filancayı dost edinmeseydim!"},{"n":29,"t":"Bana Kur’anın mesajı geldikten sonra o beni Allah’ı anmaktan alıkoydu. Zaten şeytan, insanı ayarttıktan sonra yüzüstü bırakır."},{"n":30,"t":"Peygamber «Ya Rabbi, soydaşlarım bu Kur’anı boykot ettiler.» dedi."},{"n":31,"t":"Ey Muhammed, biz böylece her Peygamberin karşısına azılı günahkar bir düşman çıkardık. Rabb’in senin için yeterli bir yol gösterici ve yardım edicidir."},{"n":32,"t":"Kafirler «Kur’an, Muhammed’e bir defada topluca indirilseydi ya» dediler. Oysa biz senin moralini güçlendirmek, azmini pekiştirmek için onu böylesine bölüm bölüm indirdik ve ağır ağır okuduk."},{"n":33,"t":"Onların sana getirdikleri hiçbir örnek yoktur ki, sana doğrusunu ve daha açığını getirmeyelim."},{"n":34,"t":"O yüzüstü süründürülerek cehenneme atılacak olanlar var ya, en kötü yer onların yeri ve en sapık yol onların yoludur."},{"n":35,"t":"Andolsun ki, biz Musa’ya Kitabı (Tevratı) gönderdik ve kardeşi Harun’u’ da yanına yardımcı olarak verdik."},{"n":36,"t":"Onlara «Ayetlerimizi yalanlayan soydaşlarınızı uyarmaya gidin» dedik. Sonra o toplumu kökten yokettik."},{"n":37,"t":"Nuh’un soydaşlarını da yokettik. Onlar peygamberlerini yalanlayınca kendilerini suda boğduk, böylece onları diğer insanların ibret alacakları acı bir örneğe dönüştürdük ve zalimler için acıklı bir azap hazırladık."},{"n":38,"t":"Adoğullârını, Semudoğullarını, kuyunun yuttuklarını ve bunlar arasındaki dönemlerde yaşamış bir çok kuşakları da yokettik."},{"n":39,"t":"Hepsine bir çok uyarıcı örnekler gösterdik. Sonra da hepsini kökten yokettik."},{"n":40,"t":"Ey Muhammed, senin hemşehrilerin, bela yağmuruna tutulmuş olan o kente uğradılar. Acaba orayı görmüyorlar mıydı? Hayır, aslında onlar yeniden dirileceklerini beklemiyorlardı."},{"n":41,"t":"Onlar seni her gördüklerinde «Allah, bu adamı mı peygamber olarak gönderdi?» diye mutlaka alaya alırlar."},{"n":42,"t":"Eğer biz ilahlarımıza ısrarla bağlılığımızı sürdürmeseydik, az kalsın bu adam bizi onlardan vazgeçirecekti derler. Yakında azabımızı gördüklerinde kimin yolunun sapık olduğunu öğreneceklerdir."},{"n":43,"t":"İhtiraslarını ilah edinen kimseyi görüyor musun? Onu doğru yola iletme sorumluluğunu sen mi üstleneceksin?"},{"n":44,"t":"Yoksa sen, onların büyük çoğunluğunun gerçekten senin davetini dinleyeceğini, yahut akıllarını kullanacaklarını mı sanıyorsun? Onlar ancak hayvan gibidirler. Hatta onlar yolca daha da sapıktırlar."},{"n":45,"t":"Rabbinin gölgeyi nasıl uzattığını görmüyor musun? Eğer dileseydi onu hareketsiz kılardı. Sonra da güneşi onun belirleyici göstergesi yaptık."},{"n":46,"t":"Sonra onu yavaş yavaş kısaltarak kendimize çektik."},{"n":47,"t":"O, sizin için geceyi örtü, uykuyu dinlenme fırsatı ve gündüzü çevreye dağılıp çalışma zamanı yaptı."},{"n":48,"t":"O, rüzgarları rahmetinin öncesinde müjde habercisi olarak gönderdi. Size gökten arı su indirdik."},{"n":49,"t":"Amacımız bu su sayesinde ölü bir yöreyi diriltmek, yarattığımız çok sayıda hayvanın ve insanın su ihtiyacını karşılamaktır."},{"n":50,"t":"İnsanlar düşünüp ders alsınlar diye biz bu gerçeği onlara çeşitli şekillerde anlattık. Fakat onların çoğu ısrarla nankörlüklerini sürdürdüler."},{"n":51,"t":"Eğer dileseydik her şehre ayrı bir uyarıcı gönderirdik."},{"n":52,"t":"O halde sakın kafirlerin uzlaşma önerilerini kabul etme; Kur’an’a dayanarak olanca gücünle onlarla mücadele et."},{"n":53,"t":"O, birinin suyu tatlı ve içmeye elverişli ve öbürününki acı ve tuzlu olan iki denizi birbirine saldı, fakat bu iki tür suyun birbirine karışmasını önleyen bir engel, aşılmaz bir set koydu."},{"n":54,"t":"O sudan insanı yarattı ve bu insandan suyun taşıyıcısı erkek ile akrabalığın sürdürücüsü olan dişiyi meydana çıkardı. Rabbinin gücü herşeye yeter."},{"n":55,"t":"Onlar, Allah’ı bir yana bırakarak kendilerine ne fayda ve ne de zarar vermeye güçleri yetmeyen sözde ilahlara taparlar. Her kafir Rabb’inin düşmanlarının destekçisidir."},{"n":56,"t":"Ey Muhammed, biz seni sırf müjdeleyici ve uyarıcı olarak gönderdik."},{"n":57,"t":"Bu duyurma görevim karşılığında sizden herhangi bir ücret istemiyorum. Tek isteğim, dileyenlerinizi Rabb’lerine götüren yola girmeleridir."},{"n":58,"t":"Sen ölümsüz, diri olan Rabb’ine güven; onu överek her türlü noksanlıktan tenzih et. Kullarının günahlarından O’nun haberdar olması yeterlidir."},{"n":59,"t":"O gökleri, yeryüzünü ve ikisi arasındaki tüm varlıkları altı günde yarattı, sonra Arşa kuruldu. O’nun rahmeti boldur. Onu bir bilene sor."},{"n":60,"t":"Onlara «Rahman’a secde edin» denildiğinde «Rahman da ne oluyor? Senin secde etmemizi emrettiğin ilah’a secde eder miyiz hiç?» derler. Bu çağrı nefretlerini daha da arttırır."},{"n":61,"t":"Gökteki gezegenlere yörüngeler belirleyen, orada ışık kaynağı olan güneşi ve aydınlık saçan ayı yaratan Allah’ın şanı yücedir."},{"n":62,"t":"O, düşünmek ya da şükretmek isteyenler için gece ile gündüzü birbirine ardışık yapmıştır."},{"n":63,"t":"Rahman’ın hâs kulları o kimselerdir ki, onlar yeryüzünde yumuşak adımlar atarak yürürler. Kendini bilmezler onlara sataştıklarında yumuşak sözlerle karşılık verirler."},{"n":64,"t":"Onlar geceleri Rabblerine secde ederler ve onun huzurunda ayakta dikilirler."},{"n":65,"t":"Onlar derler ki; Ey Rabbimiz, cehennem azabını bizden uzak tut, çünkü cehennemin azabı sürekli bir afettir."},{"n":66,"t":"Orası ne fena bir konut ve ne fena bir barınaktır."},{"n":67,"t":"Onlar harcamalarında ne savurganca ve ne de eli sıkıca davranmayarak bu iki karşıt kutup arasında ölçülü bir tutum benimserler."},{"n":68,"t":"Onlar Allah’ın yanısıra başka bir ilaha yalvarmazlar. Allah’ın yasakladığı cana, sebepsiz yere kıymazlar ve zina etmezler. Bu suçları işleyenler cezalarını görürler."},{"n":69,"t":"Kıyamet günü azapları kat kat olur ve horlanmış olarak ebediyyen bu azabın pençesinde kalırlar."},{"n":70,"t":"Yalnız tevbe edip iyi ameller işleyenler hariç. Allah, böylelerinin kötülüklerini iyiliklere çevirir. Allah affedicidir ve merhametlidir."},{"n":71,"t":"Kim tevbe eder de arkasından iyi amel işlerse o kimse kararlı bir pişmanlıkla Allah’a yönelmiş olur."},{"n":72,"t":"Yine onlar yalanın semtine yanaşmazlar. Kötülükler ile karşılaştıklarında yanlarından onurlarına toz kondurmadan geçip giderler."},{"n":73,"t":"Onlara Allah’ın ayetleri hatırlatıldığında bu ayetler karşısında kör ve sağır kesilmezler."},{"n":74,"t":"\"Rabbimiz, eşlerimiz ve çocuklarımız hususunda gözümüzü aydın kıl, bizi Allah’a karşı gelmekten sakınanlara önder yap.\" derler."},{"n":75,"t":"Bu odalarda esenlik dilekleri ve selamla karşılanırlar."},{"n":76,"t":"Orada sürekli kalacaklardır. Orası ne güzel bir konut ve ne güzel bir barınaktır."},{"n":77,"t":"De ki; «Eğer yalvarmanız, kulluğunuz olmasa Rabbim size ne değer versin? Sizler Allah’ın ayetlerini yalanladığınız için azap hiç yakanızı bırakmayacaktır.»"}],[{"n":1,"t":"Ta, sin, mim."},{"n":2,"t":"Bu ayetler, açık anlamlı Kitabın ayetleridir.?"},{"n":3,"t":"Ey Muhammed, onlar mü’min olmuyorlar diye neredeyse canına kıyacaksın."},{"n":4,"t":"Eğer dilesek onlara gökten bir mucize indiririz de karşısında boyunları eğik kalır."},{"n":5,"t":"Onlar son derece merhametli olan Allah’ın kendilerine gönderdiği her yeni uyarıya burun kıvırarak set çevirirler."},{"n":6,"t":"Onlar yalanladılar. Fakat, alay konusu ettikleri gerçeklerin somut olayları ile yakında yüzyüze geleceklerdir."},{"n":7,"t":"Onlar yeryüzüne bakarak orada ne kadar yararlı bitki türleri yarattığımızı görmezler mi?"},{"n":8,"t":"Hiç kuşkusuz bunda, üstün gücümüzü kanıtlayan bir ayet vardır, ama onların çoğu inanmazlar."},{"n":9,"t":"Hiç kuşkusuz senin Rabb’in üstün iradeli ve merhametlidir."},{"n":10,"t":"Hani Rabb’in Musa’ya şöyle seslenmişti, «Şu zalim topluma git."},{"n":11,"t":"Firavun’un soydaşlarına. Onlar hiç mi başlarına geleceklerden korkmuyorlar?»"},{"n":12,"t":"«Ya Rabbi, onlar beni yalanlayacaklar diye korkuyorum.»"},{"n":13,"t":"Bu yüzden canım sıkılır ve öfkemden dilim tutulur. Onun için Harun’a da peygamberlik görevi ver."},{"n":14,"t":"Hem onların bana isnat ettikleri bir suç var, bu gerekçe ile beni öldürürler diye korkuyorum."},{"n":15,"t":"Allah dedi ki; «Hayır, korkma, İkiniz birlikte ayetlerimizle gidiniz. Biz sizinle birlikteyiz ve söylenecek her sözü işitiriz.»"},{"n":16,"t":"Firavun’un yanına vararak ona deyiniz ki; «Biz bütün alemlerin Rabb’i olan Allah’ın peygamberiyiz."},{"n":17,"t":"İsrailoğullarının bizimle birlikte buradan ayrılmalarına izin ver."},{"n":18,"t":"«Biz seni çocukken yanımıza alarak büyütmedik mi? Ömrünün birçok yılını aramızda geçirmedin mi?»"},{"n":19,"t":"Sonunda o ağır suçu işledin. Sen o sırada bir kafirdin."},{"n":20,"t":"«O suçu işlediğim sırada ben henüz doğru yolu bulmuş değildim."},{"n":21,"t":"Bu yüzden sizden korkunca yanınızdan kaçtım. Sonra Rabb’im bana hikmet bağışlayarak beni peygamberlerinden biri yaptı."},{"n":22,"t":"O nimet diye başıma kaktığın şey israiloğullarını köleleştirmenin sonucudur.»"},{"n":23,"t":"Firavun, «alemlerin Rabb’i dediğin nedir?» dedi."},{"n":24,"t":"Musa «Eğer kesin gerçeği öğrenmek istiyorsanız, O göklerin, yerin ve bu ikisi arasındaki bütün varlıkların Rabbidir» dedi."},{"n":25,"t":"Firavun çevresindekilere «dediklerini duyuyor musunuz?» dedi."},{"n":26,"t":"«O hem sizin hem de sizden önceki atalarınızın Rabbidir» dedi."},{"n":27,"t":"«Size peygamber olarak gönderilen bu adam kesinlikle bir delidir» dedi."},{"n":28,"t":"Musa, «Eğer düşünme yeteneğiniz varsa anlarsınız ki, O doğunun, batının ve bu ikisi arasındaki bütün varlıkların Rabbidir.» dedi."},{"n":29,"t":"Firavun «Eğer benden başka bir ilah edinirsen yemin ederim ki, seni hapse attırırım» dedi."},{"n":30,"t":"Musa «Sana doğru söylediğimi kanıtlayan apaçık bir delil göstersem de mi? dedi."},{"n":31,"t":"Firavun «Eğer doğru söylüyorsan kanıtını göster bakalım» dedi."},{"n":32,"t":"Bunun üzerine Musa elindeki değneği yere attı, değnek o anda sahici bir yılan oluverdi."},{"n":33,"t":"Ve elini yeninin altından çıkardı; bakanlar, onun ak bir parıltı saçtığını gördüler."},{"n":34,"t":"Bunun üzerine Firavun, çevresindeki seçkin yakınlarına dedi ki, «bu adam bilgili bir büyücüdür»"},{"n":35,"t":"Sizi büyücülüğü ile yurdunuzdan çıkarmak istiyor. Peki ne buyuruyorsunuz?»"},{"n":36,"t":"Dediler ki; «Onu kardeşi ile birlikte oyala ve adam toplayacak elçilerini bütün kentlere gönder."},{"n":37,"t":"Bütün bilgili büyücüleri bulup sana getirsinler."},{"n":38,"t":"Bir süre sonra büyücüler belirli bir günün kararlaştırılan saatinde biraraya geldiler."},{"n":39,"t":"Halka da dediler ki, haydi toplanın bakalım."},{"n":40,"t":"Toplanın da eğer büyücüler galip gelirlerse onların peşinden gideriz."},{"n":41,"t":"Büyücüler gelince Firavun’a «Eğer biz yenecek olursak herhalde bize bir ödül verilecek değil mi? dediler."},{"n":42,"t":"Firavun evet, yakın adamlarım arasına gireceksiniz, dedi."},{"n":43,"t":"Musa, «Ne atacaksanız atın, hünerinizi gösterin bakalım» dedi."},{"n":44,"t":"Büyücüler, «Firavun’un ululuğuna andolsun ki, üstün gelen taraf biz olacağız» diyerek iplerini ve değneklerini attılar."},{"n":45,"t":"Arkasından Musa değneğini atınca, değnek büyücülerin bütün göz boyayıcılıklarını yutuverdi."},{"n":46,"t":"Bunun üzerine bütün büyücüler secdeye kapandılar."},{"n":47,"t":"Ve «bütün varlıkların Rabbine inandık."},{"n":48,"t":"Musa ile Harun’un Rabbine dediler."},{"n":49,"t":"Firavun, «ben izin vermeden O’na inandınız, öyle mi? Hiç kuşkusuz O size büyücülüğü öğreten elebaşınızdı. Ama yakında başınıza neler geleceğini öğreneceksiniz. Andolsun ki, sağlı sollu birer el ve ayağınızı kesecek ve arkasından hepinizi asacağım» dedi."},{"n":50,"t":"Büyücüler de dediler ki, «zararı yok, nasıl olsa Rabb’imize döneceğiz."},{"n":51,"t":"Bizler ilk inananlar olduğumuz için Rabb’imizin kusurlarımızı bağışlayacağını umarız.»"},{"n":52,"t":"Arkasından Musa’ya «Bana inanan kullarımı geceleyin yola çıkar; sizi takip edecekler» diye vahyettik."},{"n":53,"t":"Firavun asker toplamakla görevli adamlarını şehirlere saldı."},{"n":54,"t":"Toplanan askerlerine dedi ki, «Bu adamlar, bir avuçluk, az sayıda bir toplulukturlar.»"},{"n":55,"t":"Fakat bizi öfkelendiriyorlar."},{"n":56,"t":"Biz ihtiyatlı bir toplumuz."},{"n":57,"t":"Böylece biz, Firavun ve soydaşlarını bahçelerden ve pınar başlarından çıkardık."},{"n":58,"t":"Hazinelerden ve konforlu köşklerden de."},{"n":59,"t":"Böylece bunlara, İsrailoğullarını mirasçı kıldık."},{"n":60,"t":"Firavun ile soydaşları gün doğar doğmaz İsrailoğullarının ardına düştüler."},{"n":61,"t":"İki topluluk birbirlerini gördüklerinde Musa’nın taraftarları «Eyvah, yakalandık» dediler."},{"n":62,"t":"Musa «Hayır endişelenmeyin, Rabb’im benimle birliktedir, O bana bir çıkış yolu gösterecektir’ dedi."},{"n":63,"t":"O sırada Musa’ya; «Değneğinle denize vur» diye vahyettik. Bunun üzerine deniz yarılarak içinde oniki yol açıldı. Denizin her parçası yüce bir dağ gibi oldu."},{"n":64,"t":"Arkadan gelenleri oraya yaklaştırdık."},{"n":65,"t":"Musa ile yanındakilerin tümünü kurtardık."},{"n":66,"t":"Arkasından öbürlerini suda boğduk."},{"n":67,"t":"Kuşku yok ki, bu olaydan alınacak dersler vardır. Fakat insanların çoğu buna inanmadı."},{"n":68,"t":"Ve yine kuşku yok ki, senin Rabb’in üstün iradeli ve merhametlidir."},{"n":69,"t":"Ey Muhammed, o müşriklere İbrahim’in olayını da anlat."},{"n":70,"t":"Hani İbrahim, babası ile soydaşlarına, «Neye tapıyorsunuz?» dedi."},{"n":71,"t":"Onlar da «Putlara tapıyoruz ve biz tapınmayı hep sürdüreceğiz» dediler."},{"n":72,"t":"İbrahim dedi ki, «O putlar, kendilerini imdada çağırdığınızda sesinizi işitirler mi?"},{"n":73,"t":"Ya da size yarar veya zarar dokundurabiliyorlar mı?»"},{"n":74,"t":"Onlar, «Hayır ama, atalarımızın böyle yaptıklarını gördük» dediler."},{"n":75,"t":"İbrahim dedi ki, «Nelere taptığınızı görüyor musunuz?»"},{"n":76,"t":"Gerek sizin ve gerekse eski atalarınızın."},{"n":77,"t":"O putlar, benim düşmanlarımdırlar. Benim tek dostum alemlerin Rabb’i olan Allah’tır."},{"n":78,"t":"O beni yaratan ve doğru yola iletendir."},{"n":79,"t":"O beni doyuran ve içirendir."},{"n":80,"t":"Hastalığımda beni iyileştiren O’dur."},{"n":81,"t":"O, beni öldürecek ve sonra yeniden diriltecek olandır."},{"n":82,"t":"Hesaplaşma günü günahlarımı affedeceğini umduğum da O’dur."},{"n":83,"t":"Ya Rabbi, bana yararlı bilgi ve egemenlik ver ve beni iyi kullarının arasına kat."},{"n":84,"t":"İlerdeki kuşaklar arasında doğruluğun sözcüsü olmamı nasip eyle."},{"n":85,"t":"Beni bol nimetli cennette sürekli kalanlardan eyle."},{"n":86,"t":"Babamı affeyle. Çünkü o sapıklardandır."},{"n":87,"t":"İnsanların yeniden dirilecekleri gün beni mahcup etme."},{"n":88,"t":"Ki, o gün, insana ne malı ve ne de evlatları yarar sağlamaz."},{"n":89,"t":"Yalnız temiz kalple Allah’ın huzuruna gelen kurtulur."},{"n":90,"t":"O gün, cennet, kötülüklerden sakınanların yakınına getirilir."},{"n":91,"t":"Cehennem de sapıkların gözleri önünde dikilir."},{"n":92,"t":"Sapıklara denir ki; «Hani vaktiyle taptığınız sözde ilahlar."},{"n":93,"t":"Allah’ı bir yana bırakarak ilah edindiğiniz putlar? Şimdi size yardım edebiliyorlar ya da kendilerini kurtarabiliyorlar mı?"},{"n":94,"t":"Düzmece ilahlar ile sapıklar başaşağı cehenneme atılırlar."},{"n":95,"t":"Şeytanın bütün askerleri de."},{"n":96,"t":"Orada birbirleri ile tartışmaya tutuşarak derler ki,"},{"n":97,"t":"Vallahi bizler apaçık bir sapıklığa saplanmıştık."},{"n":98,"t":"Çünkü sizleri alemlerin Rabb’ine denk tutmuştuk."},{"n":99,"t":"Bizi ağır suçlular yoldan çıkarmışlardır."},{"n":100,"t":"Şimdi bizim bir şefaatçimiz yok."},{"n":101,"t":"Cana yakın bir dostumuz da yok."},{"n":102,"t":"Ah keşki, bir daha dünyaya dönebilsek de mü’minlerden olsak."},{"n":103,"t":"Kuşku yok ki, bu olaydan alınacak dersler vardır. Onların çoğunluğu inanmamış kimselerdi."},{"n":104,"t":"Ve yine kuşku yok ki, senin Rabb’in üstün iradeli ve merhametlidir."},{"n":105,"t":"Nuh’un soydaşları peygamberlerini yalanladılar."},{"n":106,"t":"Hani kardeşleri Nuh, onlara dedi ki, Siz hiç Allah’tan korkmaz mısınız?"},{"n":107,"t":"Ben size gönderilmiş, güvenilir bir Allah elçisiyim."},{"n":108,"t":"Öyleyse Allah’tan korkunuz ve çağrıma uyunuz."},{"n":109,"t":"Ben bu çağrı hizmetime karşılık sizden herhangi bir ücret istemiyorum, benim çabamın karşılığını verecek olan alemlerin Rabb’idir."},{"n":110,"t":"O halde Allah’tan korkunuz ve çağrıma uyunuz."},{"n":111,"t":"Soydaşları, «peşinden gelenler aramızdaki ayak takımı iken hiç biz sana inanır mıyız» dediler."},{"n":112,"t":"Nuh dedi ki; «Onların neler yaptıklarını ben bilemem.»"},{"n":113,"t":"Onların hesabını görmek, sadece Rabb’ime düşer. Keşke bu gerçeğin bilincinde olsanız."},{"n":114,"t":"Mü’minleri yanımdan kovmak bana yakışmaz."},{"n":115,"t":"Ben sadece açık sözlü bir uyarıcıyım."},{"n":116,"t":"Soydaşları; «Ey Nuh, eğer bu dediklerinden vazgeçmezsen taşa tutulup öldürülenlerden olacaksın» dediler."},{"n":117,"t":"«Ya Rabbi, soydaşlarım beni yalanladılar."},{"n":118,"t":"Onlar ile aramdaki meseleyi sen kesin çözüme bağla; beni ve yanımdaki mü’minleri kurtar.»"},{"n":119,"t":"Bunun üzerine Nuh’u ve yanındakileri dolu bir gemiye bindirerek kurtardık."},{"n":120,"t":"Bunun arkasından dışarda kalanları suda boğduk."},{"n":121,"t":"Kuşku yok ki, bu olaydan alınacak dersler vardır. Onların çoğunluğu inanmamış kimselerdi."},{"n":122,"t":"Ve yine kuşku yok ki, senin Rabb’in üstün iradeli ve merhametlidir."},{"n":123,"t":"Adoğulları da peygamberlerini yalanladılar."},{"n":124,"t":"Hani kardeşleri Hud, onlara dedi ki, «Siz hiç Allah’tan korkmaz mısınız?»"},{"n":125,"t":"Ben size gönderilmiş, güvenilir bir Allah elçisiyim."},{"n":126,"t":"Öyleyse Allah’tan korkunuz da, çağrıma uyunuz."},{"n":127,"t":"Ben bu çağrı hizmetime karşılık sizden herhangi bir ücret istemiyorum, benim çabamın karşılığını verecek olan alemlerin Rabb’idir."},{"n":128,"t":"Sizler her yüksek tepeye gösteriş amaçlı bir anıt dikerek boş işlerle mi oyalanıyorsunuz.?"},{"n":129,"t":"Hiç ölmemek ümidi ile sağlam köşkler mi yapıyorsunuz?"},{"n":130,"t":"Birini yakalayınca zorbaca yakalıyorsunuz."},{"n":131,"t":"Allah’tan korkunuz da çağrıma uyunuz."},{"n":132,"t":"Size bildiğiniz nimetleri bağışlayan Allah’tan korkunuz."},{"n":133,"t":"O size davar sürüleri ile evlatlar bağışladı."},{"n":134,"t":"Bahçeler ve pınarlar armağan etti."},{"n":135,"t":"Sizin hesabınıza ’büyük gün’ün azabından endişe ederim."},{"n":136,"t":"Adoğulları dediler ki, «İster öğüt ver, ister öğüt verenlerden olma, bizim için birdir.»"},{"n":137,"t":"Bu uygulamalarımız, eski atalarımızdan bize gelen geleneklerden başka birşey değildir."},{"n":138,"t":"Bizim azaba çarpılmamız sözkonusu değildir."},{"n":139,"t":"Böylece peygamberlerini yalanladılar. Biz de onları yokettik. Kuşku yok ki, bu olaydan alınacak dersler vardır. Onların çoğu inanmamış kimselerdir."},{"n":140,"t":"Ve yine kuşku yok ki, senin Rabb’in üstün iradeli ve merhametlidir."},{"n":141,"t":"Semudoğulları da peygamberlerini yalanladılar."},{"n":142,"t":"Hani kardeşleri Salih onlara dedi ki, siz hiç Allah’tan korkmaz mısınız?"},{"n":143,"t":"Ben size gönderilmiş güvenilir bir Allah elçisiyim."},{"n":144,"t":"Öyleyse Allah’tan korkunuz da çağrıma uyunuz."},{"n":145,"t":"Ben bu çağrı hizmetime karşılık sizden herhangi bir ücret istemiyorum; benim çabalarımın karşılığını verecek olan, alemlerin Rabb’idir."},{"n":146,"t":"Siz bu dünyada hep güven içinde yaşatılacağınızı mı sanıyorsunuz?"},{"n":147,"t":"Bahçeler ve pınarlar arasında"},{"n":148,"t":"Ekinler ve olgun tomurcuklar hurmalar arasında"},{"n":149,"t":"Dağları maharetle oyup alımlı köşkler yapıyorsunuz?"},{"n":150,"t":"Allah’tan korkunuz da çağrıma uyunuz."},{"n":151,"t":"Aranızdaki azıtmışların emirlerine uymayınız."},{"n":152,"t":"Onlar yeryüzünde kargaşa çıkarırlar, hiçbir bozukluğu düzeltmezler."},{"n":153,"t":"Semudoğulları dediler ki; «Sen büyüye çarpılmış birisin.»"},{"n":154,"t":"Sen sadece bizler gibi bir insansın. Eğer doğru söylüyorsan bize bir mucize göster."},{"n":155,"t":"İstediğiniz mucize işte şu dişi devedir. Su içme sırası bir gün onun ve belli bir günde sizindir."},{"n":156,"t":"Ona bir kötülük dokundurmayınız. Yoksa Büyük Gün’ün azabına çarpılırsınız.’"},{"n":157,"t":"Buna rağmen devenin ayaklarını keserek onu cansız yere devirdiler. Fakat hemen pişman oldular."},{"n":158,"t":"Arkasından azab, yakalarına yapıştı. Kuşku yok ki, bu olaydan alınacak dersler vardır. Onların çoğunluğu inanmamış kimselerdi."},{"n":159,"t":"Ve yine kuşku yok ki, senin Rabb’in üstün iradeli ve merhametlidir."},{"n":160,"t":"Lut’un soydaşları da peygamberlerini yalanladılar."},{"n":161,"t":"Hani kardeşleri Lut, onlara dedi ki; «Siz hiç Allah’tan korkmaz mısınız?"},{"n":162,"t":"Gerçekten ben, size gönderilen güvenilir bir peygamberim."},{"n":163,"t":"Öyleyse Allah’tan korkunuz da çağrıma uyunuz."},{"n":164,"t":"Ben bu çağrı hizmetime karşılık sizden hiçbir ücret istemiyorum, benim çabalarımın karşılığını verecek olan alemlerin Rabb’idir."},{"n":165,"t":"Sizler erkekler ile cinsel ilişki kuruyorsunuz, öyle mi?"},{"n":166,"t":"Buna karşılık Rabb’inizin sizin için eş olarak yarattığı kadınları bırakıyorsunuz? Sizler doğal sınırları çiğneyen, sapık bir toplumsunuz."},{"n":167,"t":"Soydaşları «Ey Lut, eğer bu dediklerinden vazgeçmezsen kesinlikle seni buradan süreceğiz» dediler."},{"n":168,"t":"Lut dedi ki; Ben sizin bu sapık davranışınızdan tiksinenlerdenim."},{"n":169,"t":"Ya Rabbi, beni ve ailemi bunların sapık davranışlarının yaygın cezasından kurtar."},{"n":170,"t":"Biz de Lut’u ve ailesini kurtardık."},{"n":171,"t":"Ailesinden sadece yaşlı bir kadın, sapıklar arasında kaldı."},{"n":172,"t":"Sonra geride kalanları yokettik."},{"n":173,"t":"Onların başlarına müthiş bir yağmur yağdırdık. Uyarıcıları umursamayanların başlarına yağan yağmur ne fenadır."},{"n":174,"t":"Kuşku yok ki, bu olaydan alınacak dersler vardır. Onların çoğunluğu inanmamış kimselerdir."},{"n":175,"t":"Ve yine kuşku yok ki, senin Rabb’in üstün iradeli ve merhametlidir."},{"n":176,"t":"Eyke halkı da peygamberlerini yalanladılar."},{"n":177,"t":"Hani Şuayb, onlara dedi ki; «Siz hiç Allah’tan korkmaz mısınız?»"},{"n":178,"t":"Ben size gönderilmiş, güvenilir bir elçiyim."},{"n":179,"t":"Öyleyse Allah’tan korkunuz da çağrıma uyunuz."},{"n":180,"t":"Ben bu çağrı hizmetime karşılık sizden hiçbir ücret istemiyorum; benim çabalarımın karşılığını verecek olan, alemlerin Rabb’idir."},{"n":181,"t":"Ölçme işlemlerinizde dürüst olunuz, eksik ölçenlerden olmayınız."},{"n":182,"t":"Tartma işlemlerinde doğru ve duyarlı terazi kullanınız."},{"n":183,"t":"Halkın mallarına düşük değer biçmeyiniz, yeryüzünde kargaşa çıkarıp dirliği bozmayınız."},{"n":184,"t":"Sizi ve sizden önceki kuşakları yaratan Allah’tan korkunuz."},{"n":185,"t":"Eykeliler dediler ki; «Sen büyüye çarpılmış birisin.»"},{"n":186,"t":"Sen de sadece bizler gibi bir insansın. Senin kesinlikle yalan söylediğin kanısındayız."},{"n":187,"t":"Eğer doğru söylüyorsan başımıza gökten parçalar yağdır."},{"n":188,"t":"Şuayb «Rabbim neler yaptığınızı herkesten iyi bilir.»"},{"n":189,"t":"Eykeliler, Şuayb’i yalanladılar. Bunun üzerine «Yakar bulut günü» nün azabı yakalarına yapıştı. O gerçekten müthiş bir günün azabı idi."},{"n":190,"t":"Kuşku yok ki, bu olaydan alınacak dersler vardır. Onların çoğunluğu inanmamış kimselerdi."},{"n":191,"t":"Ve yine kuşku yok ki, senin Rabb’in üstün iradeli ve merhametlidir."},{"n":192,"t":"Ve hakıkat bu (kur’an) rabbül’âlemînin şübhesiz bir tenzilidir"},{"n":193,"t":"Onu «güvenilir ruh» (Cebrail) indirdi."},{"n":194,"t":"Senin kalbine; uyarıcılardan biri olasın diye."},{"n":195,"t":"Açık, yalın bir arapça ile"},{"n":196,"t":"Kur’an’ın temel ilkeleri, daha önceki ümmetlerin kutsal kitaplarında da yer almıştı."},{"n":197,"t":"İsrailoğulları bilginlerinin bu Kur’an’dan haberdar olmaları müşrikler için bir delil değil mi?"},{"n":198,"t":"Eğer biz Kur’an’ı ana dili arapça olmayan birine indirseydik de,"},{"n":199,"t":"Onu o müşriklere okusaydı ona yine inanmazlardı."},{"n":200,"t":"İşte Biz vahyin, günaha batmışların kalplerinde (etki etmeden) geçip gitmesini böyle sağlamışızdır."},{"n":201,"t":"Onlar acıklı azabı görmedikçe ona inanmazlar."},{"n":202,"t":"O azapla hiç farkında olmadıkları bir sırada, ansızın yüzyüze gelirler."},{"n":203,"t":"O zaman «Acaba bize mühlet verilir mi?» derler."},{"n":204,"t":"Onlar azabımızın bir an önce gerçekleşmesini mi istiyorlar?"},{"n":205,"t":"Baksana, eğer onları yıllarca refah içinde yaşatsak da,"},{"n":206,"t":"Sonra tehdit edildikleri azap başlarına gelse;"},{"n":207,"t":"Vaktiyle refah içinde geçirdikleri hayat kendilerine hiçbir fayda sağlamaz."},{"n":208,"t":"Yok ettiğimiz her ülkeye mutlaka uyarıcılar gönderdik."},{"n":209,"t":"Amaç başlarına gelecekleri kendilerine önceden haber vermektir. Biz zalim değiliz."},{"n":210,"t":"Kur’an, şeytanlar tarafından indirilmiş değildir."},{"n":211,"t":"Bu onların sıfatları ile bağdaşmaz. Zaten onlar bunu yapamazlar da."},{"n":212,"t":"Çünkü onların vahyi işitmeleri engellenmiştir."},{"n":213,"t":"Sakın Allah’ın yanısıra başka bir ilaha yalvarma; yoksa azaba çarpılanlardan olursun."},{"n":214,"t":"Öncelikle en yakın akrabalarını uyar."},{"n":215,"t":"Sana uyan mü’minlere karşı alçak gönüllülük kanatlarını indir."},{"n":216,"t":"Eğer hemşehrilerin sana karşı gelirlerse onlara «Ben sizin yaptıklarınızdan uzağım» de."},{"n":217,"t":"Üstün iradeli ve merhametli olan Allah’a dayan."},{"n":218,"t":"O seni namaza durduğunda görür."},{"n":219,"t":"Secde edenler ile birlikte eğilip dikildiğini de görür."},{"n":220,"t":"Hiç kuşkusuz O, herşeyi işitir ve herşeyi görür."},{"n":221,"t":"Size haber vereyim mi kimlerin üzerine şeytanların iniverdiğini?"},{"n":222,"t":"Onlar ne kadar aşırı yalancı ve günah düşkünü varsa onlara inerler."},{"n":223,"t":"Onlar, çoğunluğu yalancı olan şeytanların söylediklerine kulak verirler."},{"n":224,"t":"Şairlere gelince ancak amaçsız, havai insanlar onların peşinden gider."},{"n":225,"t":"Görmüyor musun ki, onlar her vadiye dalarlar."},{"n":226,"t":"Ve yapmadıklarını söylerler."},{"n":227,"t":"Yalnız iman edip iyi ameller işleyenler, sık sık Allah’ı ananlar ve zulme uğradıklarında zalimlere karşı koyanlar böyle değildirler. Zalimler ne acı bir akıbetle yüzyüze geleceklerini yakında anlayacaklardır."}],[{"n":1,"t":"Ta sin, bunlar Kur’an’ın, açık anlamlı kitabın ayetleridir."},{"n":2,"t":"Bu ayetler mü’minler için doğru yol kılavuzu ve müjde içeriklidirler."},{"n":3,"t":"Onlar namaz kılarlar, zekâtı verirler ve ahirete kesinlikle inanırlar."},{"n":4,"t":"ahirete inanmayanlara gelince onlara yaptıkları kötü işleri güzel gösteririz de sapıklıkları içinde bilinçsizce debelenirler."},{"n":5,"t":"Onlar azapların en kötüsüne çarpılacaklardır ve yine onlar ahirette en ağır zarara uğrayanlar olacaklardır."},{"n":6,"t":"Bu Kur’an sana, her işi yerinde olan ve her şeyi bilen Allah katından indirilmektedir."},{"n":7,"t":"«Ben uzaklarda bir ateş gördüm gideyim de oradan size ya bir haber getiririm ya da bir kor parçası alıp gelirim de ısınırsınız» dedi."},{"n":8,"t":"Gerek ateşin yanındakiler ve gerekse çevresinde bulunanlar kutsanmıştır. Tüm varlıkların Rabb’ı olan Allah her türlü noksanlıklardan münezzehtir."},{"n":9,"t":"Ya Musa, kesin olarak bil ki, ben üstün iradeli ve her işi yerinde olan Allah’ım."},{"n":10,"t":"«Elindeki değneği yere at!» Musa yere düşen değneğin yılan gibi kıvrılıp yürüdüğünü görünce geriye döndü ve arkasına bakmadan kaçmaya başladı. Bu sırada şöyle bir ses duydu «Ya Musa korkma! Çünkü Peygamberler benim huzurumdayken korkuya kapılmazlar.»"},{"n":11,"t":"Yalnız zalimlerin durumu başka. Fakat eğer böyleleri kötülük yaptıktan sonra tutumlarını değiştirip iyilik yapmaya koyulurlarsa, hiç kuşkusuz ben affedici ve merhametliyim."},{"n":12,"t":"Dışarı çıkardığında, hiçbir hastalık belirtisi olmaksızın, ak bir parıltı saçacaktır. Bu olağanüstülükler, Firavun ile soydaşlarına göstereceğin dokuz mucizenin ikisidir. Onlar kesinlikle yoldan çıkmış bir toplumdur.»"},{"n":13,"t":"Mucizelerimiz onların gözleri önüne serilince «Bu apaçık bir büyüdür» dediler."},{"n":14,"t":"Vicdanların kesinlikle doğru kabul ettiği bu mucizeleri gerçeği çiğneyerek ve küstahça burun kıvırarak inkâr ettiler. Gör bakalım, o bozguncuların sonu nice oldu?"},{"n":15,"t":"Biz Davud’a ve Süleyman’a ilim verdik. Onlar da «Bizi birçok müslüman kulundan daha üstün kılan Allah’a hamd olsun» dediler."},{"n":16,"t":"«Ey insanlar, bize kuş dili öğretildi ve her şey bol bol verildi, kuşku yok ki, bu apaçık bir lütuftur.»"},{"n":17,"t":"Süleyman’ın cinlerden, insanlardan ve kuşlardan oluşan ordusu toplanarak disiplinli bir halde biraraya gelerek, düzgün saflar halinde ve uygun adımlarla yürüyüşe geçti."},{"n":18,"t":"Ordu karınca vadisine vardığında ordudaki karıncalardan biri «Ey karıncalar yuvalarınıza giriniz ki, Süleyman ve ordusu farkında olmadan sizi çiğnemesin» dedi."},{"n":19,"t":"Süleyman, karıncanın dediklerini işitince gülümseyerek dedi ki; «Ya Rabbi gerek bana ve gerekse ana babama bağışladığın nimetlere olanca gücümle şükretmemi ve hoşnut olacağın iyi işler yapmamı nasip eyle, rahmetinle beni iyi kullarının arasına kat.»"},{"n":20,"t":"Süleyman, ordusunun kuşlardan oluşan birliğini denetleyince dedi ki «Hüdhüd’ü niçin göremiyorum, yoksa burada değil mi?"},{"n":21,"t":"Onu ya ağır bir cezaya çarptıracağım, ya keseceğim ya da bana mazeretini belgeleyen açık bir kanıt getirecek."},{"n":22,"t":"«Senin bilmediğin bir şeyi öğrendim, sana Saba’dan çok önemli bir haber getirdim.»"},{"n":23,"t":"Ben o yörenin halkını yöneten bir kadınla karşılaştım. Allah ona her şeyi vermiş, görkemli bir tahtı var."},{"n":24,"t":"Onun ve soydaşlarının Allah’ı bir yana bırakarak güneşe secde ettiklerini gördüm. Şeytan, yaptıkları yanlış işleri onlara güzel göstererek kendilerine doğru saptırmış, bu yüzden doğru yolu bulamıyorlar."},{"n":25,"t":"Şeytanın amacı, onları göklerdeki ve yeryüzündeki gizli şeyleri meydana çıkaran gerek saklı tuttukları ve gerekse açığa vurdukları tüm duygularını bilen Allah’a secde etmelerini engellemektir."},{"n":26,"t":"O Allah ki, kendisinden başka ilah yoktur ve yüce Arş’ın Rabb’idir."},{"n":27,"t":"Süleyman, hüdhüd’e dedi ki; «Göreceğiz bakalım, doğru mu söylüyorsun yoksa yalancının biri misin?»"},{"n":28,"t":"Şu mektubumu götürüp onlara at, sonra seni göremeyecekleri bir yere çekil de bak bakalım ne gibi bir sonuca varacaklar?"},{"n":29,"t":"\"Ey ileri gelenler, gerçekten bana çok şerefli bir mektup bırakıldı.\""},{"n":30,"t":"Mektup, Süleyman’dan geliyor, Rahman ve Rahim olan Allah’ın adı ile başlıyor."},{"n":31,"t":"İçinde «Bana karşı büyüklük taslamayınız, boyun eğerek huzuruma geliniz» diyor."},{"n":32,"t":"Kraliçe «Ey devletin ileri gelenleri, bu konuda ne yapmam gerektiğine ilişkin görüşlerinizi söyleyiniz, ben sizin görüşünüzü almadan hiçbir işi kesin sonuca bağlamam."},{"n":33,"t":"İleri gelen devlet adamları dediler ki; «Biz güçlüyüz, yaman savaşçılarız, ferman senindir, düşün de ne buyuracağına karar ver.»"},{"n":34,"t":"Kraliçe dedi ki; «Hükümdarlar bir ülkeye ayak bastıklarında oranın düzenini alt üst ederler ve halkının seçkinlerini hor ve itibarsız duruma düşürürler. Onlar hep böyle yaparlar.»"},{"n":35,"t":"Şimdi ben onlara bir hediye göndereceğim ve elçilerimin nasıl bir cevapla döneceklerini göreceğim."},{"n":36,"t":"Kraliçenin elçisi gelince Süleyman ona dedi ki; «Beni mal ile mi kandıracaksınız? Allah’ın bana bağışladığı ayrıcalıklar size verdiklerinden daha üstündür. Siz bu hediyenizle övünebilirsiniz?»"},{"n":37,"t":"Şimdi efendilerine dön. Yemin ederim ki, karşı koyamayacakları kadar güçlü bir ordu ile üzerlerine yürürüz. Ve onurlarını çiğneyerek burunlarını yere sürte sürte onları yurtlarından çıkarırız."},{"n":38,"t":"Süleyman (yanındakilere dönerek) Ey devletin ileri gelenleri, bu adamlar boyun eğerek huzuruma gelmeden önce hanginiz kraliçenin o tahtını bana getirebilir? dedi."},{"n":39,"t":"Cinlerin ele başlarından biri «Sen şu oturduğun yerden kalkmadan önce o tahtı sana getiririm. Hem bu işi başaracak gücüm vardır ve hem de bu konuda güvenilir bir kişiyim» dedi."},{"n":40,"t":"Kutsal Kitap kaynaklı bilgisi olan biri ise «Gözünü açıp kapamadan o tahtı sana getireyim» dedi. Süleyman tahtı önünde yere konmuş görünce, «Bu, şükür mü edeceğim yoksa, nankörce mi davranacağım diye beni sınavdan geçirmek isteyen Rabbimin bana yönelik bir lütfudur. Kim şükrederse kendisi için şükretmiş olur. Nankörlük eden de bilsin ki, yüce Allah’ın hiçbir şeye ihtiyacı yoktur ve bağışı karşılıksızdır.» dedi."},{"n":41,"t":"Sonra yanındakilere dönerek «Tahtı kraliçenin tanımayacağı şekilde değiştirin! bakalım onu tanıyabilecek mi, yoksa tanımayacak mı?» dedi."},{"n":42,"t":"«Bu senin tahtın mıdır? diye soruldu. O da dedi ki; «Sanki odur. Zaten bu mucizeden önce bize bilgi verilmiş ve biz senin çağrına boyun eğmeye hazırlanmıştık.»"},{"n":43,"t":"O’nu, Allah’ı bir yana bırakarak taptığı putlar doğru yola girmekten alıkoymuştu. Çünkü kafir toplumun bir üyesi idi."},{"n":44,"t":"Ona \"Köşke gir\" denildi. Salonu görünce onu derin bir su sandı. Ve iki ayağını açtı. Süleyman da \"Doğrusu bu camdan yapılmış mücella bir salondur\" dedi. Kadın \"Rabbim şüphesiz ben kendime zulmetmiştim. Süleyman’la beraber alemlerin Rabbi olan Allah’a teslim oldum\" dedi."},{"n":45,"t":"Semudoğullarına da «Allah’a kulluk ediniz» çağrısını seslendirsin diye kardeşleri Salih’i peygamber olarak gönderdik. Fakat Semudoğulları, birbirleri ile çatışan iki karşı gruba ayrıldılar."},{"n":46,"t":"Salih onlara «Ey soydaşlarım, niye iyilikten önce kötülüğü istiyorsunuz, neden çarpılacağınız cezanın bir an önce başınıza gelmesini diliyorsunuz? Allah’tan af dilesenize,; ola ki O’nun merhametinden pay alırsınız.»"},{"n":47,"t":"Semudoğulları, Salih’e «Sen ve yanındakiler bize uğursuzluk getirdiniz» dediler. Salih dedi ki; «Sizin kısmetiniz Allah katında belirlenmiştir. Aslında siz toplum olarak sınavdan geçiriliyorsunuz.»"},{"n":48,"t":"O şehirde, toplumda sürekli kargaşa çıkaran, hiç bir bozukluğu düzeltmeye yanaşmayan dokuz tane elebaşı vardı."},{"n":49,"t":"Bunlar «Bir gece Salih’in evini basarak kendisini ve ailesini öldürelim, sonra da güvenliğini üstlenen akrabasını ’Onun ailesinin öldürülme olayından haberimiz yok, kesinlikle doğru söylüyoruz’ diyelim» diye aralarında Allah adına and içtiler."},{"n":50,"t":"Böylece onlar bir tuzak kurdular. Fakat biz de onlara, farkında olmadıkları bir tuzak kurduk."},{"n":51,"t":"Şimdi bak bakalım, onların tuzaklarının sonu nice oldu? Biz onları ve soydaşlarını hep birlikte yok ettik."},{"n":52,"t":"İşte enkaz yığınına dönüşmüş evleri! Sebep zalimlikleridir. Hiç kuşkusuz Allah’ın değişmez yasasını bilenlerin bu olaydan alacakları dersler vardır."},{"n":53,"t":"Buna karşılık mü’minleri ve Allah’ın yasalarını çiğnemekten sakınanları yok olmaktan kurtardık."},{"n":54,"t":"«Sizler, normal cinsel ilişki düzenine ters düştüğünüze göre ve birbirlerinizin gözleri önünde o iğrenç işi yapıyorsunuz, öyle mi?»"},{"n":55,"t":"Siz kadınları bırakıp erkeklerle cinsel ilişkide bulunuyorsunuz öyle mi? Aslında sizler her türlü bilgiden yoksun, beyinsiz bir toplumsunuz."},{"n":56,"t":"«Lut’un yakınlarını şehrinizden çıkarınız, çünkü onlar temizliğe pek meraklı kimselermiş!»"},{"n":57,"t":"Lût’u ve eşi dışındaki yakınlarını kurtardık. Eşinin ise geride kalarak yok olmasını kararlaştırdık."},{"n":58,"t":"Onların başlarına müthiş bir yağmur yağdırdık. Uyarıları umursamayanların başlarına yağan yağmur ne fenadır!"},{"n":59,"t":"Ey Muhammed de ki; «Allah’a hamd ve seçtiği kullarına da selâm olsun. Allah mı daha iyidir, yoksa onların Allah’a ortak koştukları düzmece ilahlar mı?"},{"n":60,"t":"(Bu düzmece ilahlar mı daha iyi) yoksa gökleri ve yeri yaratan, gökten size su indiren Allah mı? Biz o su sayesinde bir tek ağacını bile bitirmeye gücünüzün yetmeyeceği alımlı bahçeler bitirdik. Allah’ın yanı sıra başka bir ilah mı var? Aslında onlar gerçekten sapan bir toplumdurlar."},{"n":61,"t":"Bu düzmece ilahlar mı daha iyi yoksa dünyayı dengeli bir yaşama alanı yapan, kara parçaları üzerindeki nehirler akıtan, yeryüzünde köklü dağlar yükselten ve farklı yoğunluktaki iki deniz arasına set koyan Allah mı?"},{"n":62,"t":"(Bu düzmece ilahlar mı daha iyi) yoksa sıkıntıya düşene, kendisine yalvardığı takdirde cevap vererek sıkıntısını gideren ve sizi ardarda gelen kuşaklar halinde yeryüzüne egemen kılan Allah mı? Allah’ın yanı sıra başka bir ilah mı var? Ne kadar kıt düşüncelisiniz"},{"n":63,"t":"(Bu düzmece ilâhlar mı daha iyi) yoksa karaların ve denizlerin karanlıkları içinde size yolunuzu bulduran, rahmetinin önünden rüzgârları müjde habercisi olarak gönderen Allah mı? Allah’ın yanı sıra başka bir ilah mı var? Allah, onların kendisine koştukları ortaklardan münezzehtir."},{"n":64,"t":"(Bu düzmece ilahlar mı daha iyi) yoksa canlıları ilk kez yaratan ve ölüleri yeniden diriltecek olan, gökten ve yerden size besin kaynakları sağlayan Allah mı? Allah’ın yanı sıra başka bir ilah mı var? De ki; «Eğer doğru söylüyorsanız, açık delilinizi getiriniz.»"},{"n":65,"t":"De ki; «Bilinmezi, gaybı ne göktekiler bilir ne de yerdekiler. Onu sadece Allah bilir». Onlar ne zaman yeniden diriltileceklerini de bilemezler."},{"n":66,"t":"Onların bilgileri ahirete erememiş, o alemin berisinde kalmıştır. Aslında onlar ahiret konusunda kuşku içindedirler. Hatta ondan yana kördürler."},{"n":67,"t":"Kâfirler dediler ki; «Bizler ve atalarımız, toprak olduktan sonra yeniden mi diriltileceğiz?»"},{"n":68,"t":"Bu tehdit gerek bize ve gerekse atalarımıza daha önce de yapılmıştı. Bu, eskilerin masallarından başka bir şey değildir.»"},{"n":69,"t":"Onlara de ki; «Yeryüzünü geziniz de ağır suçluların sonunun nice olduğunu görünüz.»"},{"n":70,"t":"Ey Muhammed, onlar için üzülme ve sana kurdukları tuzaklarda canını sıkmasın."},{"n":71,"t":"Eğer doğru söylüyorsanız bize yönelttiğiniz tehdit ne zaman gerçekleşecek? diyorlar."},{"n":72,"t":"Onlara de ki; «Bir an önce gerçekleşsin diye sabırsızlandığınız azabın bir bölümü belki de yanı başınızdadır.»"},{"n":73,"t":"Kuşku yok ki senin Rabb’in insanlara karşı lütufkârdır, ama onların çoğunluğu O’na şükretmezler."},{"n":74,"t":"Kuşku yok ki, senin Rabb’in onların gerek içlerinde sakladıkları ve gerekse açığa vurdukları tüm duyguları bilir."},{"n":75,"t":"Göklerdeki ve yeryüzündeki bütün bilinmezler, tüm sırlar mutlaka apaçık kitapta yer alır."},{"n":76,"t":"Kuşku yok ki, Bu Kur’an, İsrailoğulları’na anlaşmazlığa düştükleri konuların çoğunu açık açık anlatmaktadır."},{"n":77,"t":"Ve yine kuşku yok ki, Kur’an, mü’minler için doğru yol kılavuzu ve rahmettir."},{"n":78,"t":"Hiç kuşkusuz Rabb’in İsrailoğulları hakkında kesin hükmünü verecektir. O üstün iradelidir ve her şeyi bilir."},{"n":79,"t":"Ey Muhammed, öyleyse sen Allah’a dayan. Çünkü apaçık gerçeği savunuyorsun."},{"n":80,"t":"Sen ölülere söz işittiremezsin. Arkalarını dönüp yanından kaçan sağırlara da çağrını duyuramazsın."},{"n":81,"t":"Sen körleri de sapıklıklarından kurtarıp doğru yola iletemezsin. Sen ancak ayetlerimize inanan ve Rab’lerine boyun eğmiş müslümanlara söz dinletebilirsin."},{"n":82,"t":"insanlara yönelttiğimiz o tehdidin gerçekleşme günü yaklaşınca karşılarına yerden bitme bir hayvan çıkarırız. Bu hayvan dile gelerek insanların ayetlerimize inanmadıklarını açıklar."},{"n":83,"t":"O gün her ümmetten ayetlerimizi yalanlayanları grup grup bir yere topladıktan sonra saf düzeninde yürüyüşe geçiririz."},{"n":84,"t":"Hesaplaşma yerine geldiklerinde Allah, onlara der ki; «Ayetlerimi anlamadığınız halde yalanladınız, değil mi? Yoksa yaptığınız, başka neydi ki?»"},{"n":85,"t":"Zalimliklerinden ötürü haklarındaki hüküm kesinleşmiştir. Bu yüzden artık konuşamaz olurlar."},{"n":86,"t":"Geceyi dinlenesiniz diye karanlık ve gündüzü de çalışasınız diye aydınlık olarak yarattığımızı onlar görmüyorlar mı? Bu olgulardan mü’minlerin alacakları birçok dersler vardır."},{"n":87,"t":"Sur’a üflendiği gün, Allah’ın diledikleri dışında kalan göklerdeki ve yeryüzündeki herkes dehşete kapılır. Herkes boyun eğerek O’nun huzuruna gelir."},{"n":88,"t":"Sen dağları görünce onların yerlerinden hiç kımıldamadıkları sanırsın. Oysa onlar bulutlar gibi hareket ederler. Bu her şeyi özenerek yaratan Allah’ın ustalığıdır. Hiç kuşkusuz O, yaptığınız her şeyden haberdardır."},{"n":89,"t":"Kimler iyilikle gelirse karşılığında daha iyisini alırlar. Böyleleri o gün hiç korkuya kapılmazlar, gönülleri rahat olur."},{"n":90,"t":"Kimler kötülükle gelirse yüzükoyun cehenneme atılırlar. Kendilerine «Bu sadece vaktiyle işledikleriniz (kötülükler)in cezası değil midir» denir."},{"n":91,"t":"Ey Muhammed de ki; «Bana sırf bu şehrin Rabb’ine kulluk etmem emredildi. O bu şehri dokunulmaz kıldı. Her şey O’nundur. Bana O’nun buyruğuna boyun eğenlerin ilki olmam emredildi."},{"n":92,"t":"Bana bir de Kur’an okumam emredildi. Kim doğru yola gelirse kendi iyiliği için doğru yola gelmiş olur. Kim eğri yola saparsa de ki; ben sadece bir uyarıcıyım."},{"n":93,"t":"De ki; Hamd Allah’a mahsustur. O ilerde size ayetlerini gösterecek, siz de onları tanıyacaksınız. Rabb’in onların yaptıkları işlerden kesinlikle habersiz değildir."}],[{"n":1,"t":"Ta. sin. mim."},{"n":2,"t":"Bunlar apaçık Kitab’ın ayetleridir."},{"n":3,"t":"Ey Muhammed! İnanan bir kavim için. Musa ve Firavun olayının bir kısmını sana dosdoğru anlatacağız."},{"n":4,"t":"Firavun ülkesinde ululandı ve zorbalığa kalktı, halkını çeşitli sınıflara böldü. Onlardan bir topluluğu (İsrailoğulları’nı) zayıflatıyor, oğullarını kesiyor, kadınları sağ bırakıyordu. Çünkü o bozguncunun biriydi."},{"n":5,"t":"Biz istiyorduk ki o yerde zayıflatılanlara lutfedelim, onları önderler yapalım, onları diğerlerinin yerine mirasçı kılalım."},{"n":6,"t":"Ve onları o ülkede hakim kılalım. Firavun’a Haman’a ve askerlerine; başlarına gelmesinden korktukları şeyi gösterelim."},{"n":7,"t":"Musa’nın annesine, «Çocuğu emzir. Başına bir şey gelmesinden korkuyorsan bir sandık içinde suya bırak, korkma, üzülme, biz onu tekrar sana vereceğiz ve onu peygamber yapacağım» diye bildirmiştik."},{"n":8,"t":"Nihayet Firavun ailesi onu buldu ve aldı. Çünkü o, sonunda kendileri için bir düşman ve dert olacaktı. Şüphesiz Firavun, Haman ve askerleri suçlu oldukları için yanılıyorlardı."},{"n":9,"t":"Firavun’un karısı; «İkimizin de gözü aydın! Onu öldürmeyin, belki bize faydası dokunur ya da onu evlat ediniriz» dedi. Onu almakla hata ettiklerini bilmiyorlardı."},{"n":10,"t":"Musa’nın annesi, gönlü bomboş, sabaha kadar oğlunu düşündü. Eğer biz, vaadimize inananlardan olması için kalbini iyice pekiştirmemiş olsaydık, saraya alınan çocuğun oğlu olduğunu açığa vuracaktı."},{"n":11,"t":"Annesi Musa’nın ablasına; «Onun izini takip et» dedi. O da kimse farkına varmadan, Musa’yı gözetledi."},{"n":12,"t":"Önceden, süt annelerinin memesini kabul etmemesini sağladık. Musa’nın ablası; «Sizin için onun bakımını üstlenecek ve ona öğüt verip onu güzelce eğitecek bir aileyi göstereyim mi?» dedi"},{"n":13,"t":"Böylece biz onu annesine geri verdik ki gözü aydın olsun, üzülmesin ve Allah’ın vaadinin gerçek olduğunu bilsin. Fakat çoğu bunu bilmez."},{"n":14,"t":"Musa, yiğitlik çağına gelip olgunlaşınca, biz ona hikmet ve ilim verdik. İşte güzel davrananları böyle mükâfatlandırırız."},{"n":15,"t":"Musa, halkının haberi olmadığı bir zamanda şehre girdi. Orada, biri kendi tarafından diğeri düşman tarafından olan iki adamın birbiriyle dövüştüklerini gördü. Kendi tarafından olan, düşman olana karşı Musa’dan yardım istedi. Musa’da onun düşmanına bir yumruk vurdu, ölümüne sebep oldu. Sonrada; «Bu şeytanın işidir; çünkü o apaçık saptıran bir düşmandır.» dedi."},{"n":16,"t":"Musa; «Rabb’im! Ben nefsime zulmettim, beni bağışla» dedi. Allah onu bağışladı. Çünkü O, çok bağışlayan ve çok esirgeyendir."},{"n":17,"t":"Musa; «Rabb’im! Bana verdiğin nimete andolsun ki, suçlulara asla yardımcı olmayacağım» dedi."},{"n":18,"t":"Şehirde korku içinde etrafı gözetleyerek sabahladı. Dün kendisinden yardım isteyen kişi bağırarak yine ondan yardım istiyordu. Musa ona; «Besbelli sen bir azgınsın.» dedi."},{"n":19,"t":"Nihayet Musa ikisininde düşmanı olan adamı yakalamak isteyince; «Ey Musa! Dün bir canı öldürdüğün gibi beni de mi öldürmek istiyorsun? Sen yeryüzünde islah edenlerden değil de zorba olmak istiyorsun.» dedi."},{"n":20,"t":"Şehrin öbür ucundan bir adam koşarak geldi; «Ey Musa, ileri gelenler seni öldürmek için aralarında görüşüyorlar. Hemen uzaklaş. Doğrusu ben sana öğüt veriyorum» dedi."},{"n":21,"t":"Musa, korku içinde çevresini gözetleyerek şehirden çıktı. «Rabb’im! Beni şu zalim kavimden kurtar.» dedi."},{"n":22,"t":"’Umarım, Rabbim beni doğru, normal bir yola yöneltti’ dedi."},{"n":23,"t":"’Onlarla birlikte hayvanlarınızı sulamanıza engel olan sebep ne?’ dedi. ’Çobanlar hayvanlarını sulayıp çekilmeden, biz onların içine sokulup hayvanlarımızı sulayamayız. Babamız da çok yaşlı.’ dediler."},{"n":24,"t":"Musa onların hayvanlarını suladı, sonra gölgeye çekildi; «Rabb’im, doğrusu bana indireceğin her hayra muhtacım» dedi."},{"n":25,"t":"O sırada iki kızdan biri utana utana Musa’nın yanına geldi; «Babam sulama ücretini ödemek için seni çağırıyor» dedi. Musa kızların babalarının yanına gelerek başından geçen olayları anlatınca O; «Korkma, o zalim kavimden kurtuldun» dedi."},{"n":26,"t":"Kızlardan biri; «Babacığım, bunu çoban olarak tut, ücretle tuttuklarının en hayırlısı budur. Çünkü hem güçlü hem de güvenilir.»"},{"n":27,"t":"Kızların babası; «Bana sekiz yıl çalışmana karşılık bu iki kızımdan birini sana nikahlamak istiyorum. Eğer bu süreyi on yıla tamamlarsan o senin tarafından bir iyiliktir. Ben sana zahmet vermek istemem. İnşallah, beni iyi kimselerden bulacaksın» dedi."},{"n":28,"t":"Musa; «Bu seninle benim aramda bir sözleşmedir. Hangi süreyi yerine getirirsem bana düşmanlık yoktur. Konuştuklarımıza Allah vekildir.» dedi."},{"n":29,"t":"Musa süreyi bitirince ailesi ile beraber yola çıktı. Tur tarafında bir ateş gördü. Ailesine «Siz durun, ben bir ateş gördüm; belki oradan size bir haber yada bir ateş koru getiririm de ısınırsınız.» dedi."},{"n":30,"t":"«Ey Musa, muhakkak ki alemlerin Rabb’i olan Allah benim ben!»"},{"n":31,"t":"«Asanı at Musa!» Attığı kocaman asasının küçük bir yılan gibi hareket ettiğini görünce, dönüp arkasına bakmadan kaçtı. «Ey Musa, dön gel, korkma, sen güvende olanlardansın.»"},{"n":32,"t":"«Elini koynuna sok, kusursuz olarak bembeyaz çıksın. Korkudan açılan kollarını kendine çek. İşte bunlar, Firavun’a ve onun adamlarına karşı Rabb’inin verdiği iki delildir. Çünkü onlar yoldan çıkmış bir kavimdirler» denildi."},{"n":33,"t":"Musa; «Rabb’im! Ben onlardan bir cana kıydım, beni öldürmelerinden korkuyorum.» dedi."},{"n":34,"t":"«Kardeşim Harun’un dili benimkinden daha düzgündür onu da beni destekleyen bir yardımcı olarak benimle gönder, çünkü beni yalanlayacaklarından korkarım.» dedi."},{"n":35,"t":"Allah; «Seni kardeşinle destekleyeceğiz; ikinize bir kudret vereceğiz ki, onlar size el uzatamayacaklar. Ayetlerim sayesinde onlar size erişemeyecekler. İkiniz ve size uyanlar üstün geleceksiniz.» dedi."},{"n":36,"t":"Musa onlara apaçık ayetlerimizle gelince uydurulmuş büyüden başka bir şey değildir. Bizden önceki atalarımızdan böylesini işitmedik dediler."},{"n":37,"t":"Musa; «Rabb’im, katında bir doğruluk rehberini kimin getirdiğini ve bu dünyâ hayatının sonunda güzel sonucun kime nasip olacağını daha iyi biliyor. Muhakkak ki, zalimler iflah olmaz» dedi."},{"n":38,"t":"Firavun; «Ey ileri gelenler! Sizin için benden başka bir ilah tanımıyorum. Ey Haman, haydi, benim için çamur üzerinde ateş yak ve tuğla imal et, bana bir kule yap ki, Musa’nın tanrısına çıkayım; ancak sanıyorum ki, O mutlak yalan söyleyenlerdendir» dedi."},{"n":39,"t":"Firavun ve askerleri yeryüzünde haksız yere büyüklük tasladılar ve gerçekte Bize döndürülmeyeceklerini sandılar."},{"n":40,"t":"Biz de onu ve askerlerini yakalayıp suya attık. Bir bak, o zalimlerin sonu nasıl oldu."},{"n":41,"t":"Biz onları ateşe çağıran önderler yaptık. Kıyamet günü onlar yardım görmeyeceklerdir."},{"n":42,"t":"Bu dünya hayatında biz onların peşine bir lânet taktık. Kıyamet günü de iğrenç kimselerden olacaklar."},{"n":43,"t":"Andolsun biz, ilk nesilleri helak ettikten sonra Musa’ya, insanların kalp gözlerini aydınlatacak nur ve onlara yol gösterici olarak Kitab’ı verdik. Belki düşünür, öğüt alırlar diye."},{"n":44,"t":"Ey Muhammed! Musa’ya emrimizi vahyettiğimiz zaman sen mukaddes vadinin batı tarafında değildin, onu görenlerden de değildin."},{"n":45,"t":"Biz nice nesiller var etmiştik de onların üzerinden uzun zamanlar geçti. Ey Muhammed! Sen Medyen halkı arasında bulunup onlara ayetlerimizi okumuyordun. Fakat o haberleri sana gönderen biziz."},{"n":46,"t":"Sen Musa’ya hitab ettiğimiz zaman Tur’un yanında da değildin. Fakat Rabb’inden bir rahmet olarak orada geçenleri sana bildirdik ki senden önce bir uyarıcı peygamber gelmemiş olan kavmi uyarasın; belki düşünüp öğüt alırlar."},{"n":47,"t":"Kendi elleriyle yaptıkları günahlar yüzünden başlarına bir felaket geldiği zaman; «Rabbimiz ne olurdu bize bir peygamber gönderseydin de ayetlerine uysak ve mü’minlerden olsaydık» demesinler diye peygamber gönderdik."},{"n":48,"t":"Fakat onlara katımızdan gerçek gelince; «Musa’ya verildiği gibi buna da mucize verilmesi gerekmez mi? derler. Daha önce Musa’ya verileni de inkar etmemişler miydi? «Yardımlaşan iki sihirbaz»; «Hepsini inkâr edenleriz» demişlerdi."},{"n":49,"t":"De ki; «Eğer doğru iseniz, Allah katından bu ikisinden, Musa’ya ve bana inen kitaplardan daha doğru bir kitap getirinde ben ona uyayım.»"},{"n":50,"t":"Eğer sana cevap vermezlerse bil ki onlar, keyiflerine uyuyorlar. Allah’dan bir yol gösterici olmaksızın kendi hevesine uyandan daha sapık kim olabilir? Elbette Allah, zalim kavmi doğru yola iletmez."},{"n":51,"t":"Andolsun biz, düşünüp öğüt alsınlar diye vahyi birbirine bitiştirdik."},{"n":52,"t":"Bundan önce kendilerine kitap verdiklerimiz de Kur’an’a inanırlar."},{"n":53,"t":"Kur’an onlara okunduğu zaman; «Ona inandık, doğrusu O Rabb’imizden gelen gerçektir, zaten biz ondan önce de müslüman idik» derler."},{"n":54,"t":"İşte onlara sabretmelerinden dolayı mükafatları iki defa verilir. Onlar kötülüğü iyilikle savarlar ve kendilerine verdiğimiz rızıktan hayır yolunda harcarlar."},{"n":55,"t":"Boş söz işittikleri zaman ondan yüz çevirirler. «Bizim işlerimiz bize, sizin işleriniz sizedir. Size selâm olsun, biz cahillerle sohbet etmeyi istemeyiz.» derler."},{"n":56,"t":"Ey Muhammed! Sen sevdiğini doğru yola eriştiremezsin, ancak Allah dilediğini doğru yola eriştirir. Doğru yola girecekleri en iyi O bilir."},{"n":57,"t":"Dediler ki; «Biz seninle beraber doğru yola gelirsek yurdumuzdan atılırız.» Onları katımdan bir rızık olarak her şeyin ürünlerinin toplanıp getirildiği, kutlu bir yere yerleştirmedik mi? Fakat onların çoğu bilmezler."},{"n":58,"t":"Biz refah içinde şımarmış nice şehirleri helak ettik. İşte yerleri! Kendilerinden sonra pek az kimse oturabilmiştir. Onlara hep biz varis olmuşuzdur."},{"n":59,"t":"Rabb’in memleketlerin ana merkezlerinin halkına ayetlerimizi okuyacak bir elçi göndermedikçe ülkeleri helâk edici değildir. Zaten biz halkı zalim olan memleketleri helak etmişizdir."},{"n":60,"t":"Size verilen her şey, dünya hayatının geçimi ve süsüdür. Allah’ın katında olan ise daha hayırlı ve kalıcıdır. Aklınızı kullanmıyor musunuz?"},{"n":61,"t":"Şu halde kendisine güzel bir söz verdiğimiz ve ardından o söze kavuşan kimse; dünya hayatında kendisine bir geçimlik verdiğimiz, sonra kıyamet günü azap içinde getirilen kimse gibi midir?"},{"n":62,"t":"«Benim ortağım olduğunu iddia ettikleriniz nerededirler?»"},{"n":63,"t":"«Rabb’imiz, azdırdıklarımız şunlar. Kendimiz azdığımız gibi onları da azdırdık. Onlardan uzaklaşıp sana geldik, zaten, aslında bize tapmıyorlardı» derler."},{"n":64,"t":"Koştuğunuz ortaklarınızı çağırın denir; onlar da çağırırlar. Ancak kendilerine cevap veremezler; cehennem azabını görünce doğru yolda olmadıklarına yanarlar."},{"n":65,"t":"Allah onlara seslenerek; «Peygamberlere ne cevap verdiniz» der."},{"n":66,"t":"O gün haberlere karşı körleşirler, verilecek cevapları kalmaz, birbirlerine de soramazlar."},{"n":67,"t":"Fakat tevbe eden, inanıp yararlı iş işleyen kimsenin, kurtuluşa erenlerden olması umulur."},{"n":68,"t":"Rabbin dilediğini yaratır, seçer. Seçim onlara ait değildir. Allah onların ortak koştuğu şeylerden uzaktır, yücedir."},{"n":69,"t":"Rabbin, gönüllerinin gizlediklerini ve açığa vurduklarını bilir."},{"n":70,"t":"Allah odur ki; O’ndan başka ilah yoktur. Hamd dünya ve ahirette O’nun içindir. Hüküm de O’nundur. Yalnız O’na döndürüleceksiniz."},{"n":71,"t":"Ey Muhammed! De ki; «söyleyin bakalım; Allah, üzerinize geceyi Kıyamet gününe kadar sürekli kılsa, Allah’dan başka size ışık getirecek ilah kimdir. İşitmiyormusunuz?»"},{"n":72,"t":"De ki; «Allah gündüzü kıyamete kadar üzerinizden kaldırmasa, Allah’dan başka hangi tanrı, dinleneceğiniz geceyi getirebilir? Görmez misiniz?»"},{"n":73,"t":"Allah dinlenmeniz için geceyi ve lütfedip verdiği rızkı aramanız için gündüzü yaratmıştır. Bunlar O’nun rahmetidir. Belki artık şükredersiniz."},{"n":74,"t":"O gün onlara seslenerek; «Benim ortağım olduğunu iddia ettikleriniz nerede?» der."},{"n":75,"t":"Her ümmetten bir şahit çıkarırız. «Delillerinizi getirin» deriz. O zaman, gerçeğin Allah’a ait olduğunu bilirler ve uydurdukları şeylerin kendilerini bırakıp kaçtığını anlarlar."},{"n":76,"t":"Karun, Musa’nın kavmindendi. Onlara karşı azgınlık etmişti. Biz ona öyle hazineler vermiştik ki, anahtarlarını güçlü kuvvetli bir topluluk zor taşırdı. Kavmi ona demişti ki; «Şımarma, Allah şımaranları sevmez.»"},{"n":77,"t":"Allah’ın sana verdiği bu servet içinde ahiret yurdunu ara, dünyadan da nasibini unutma, Allah sana nasıl iyilik ettiyse, sen de öyle iyilik et, yeryüzünde bozgunculuk isteme, çünkü Allah bozguncuları sevmez."},{"n":78,"t":"«Bu servet, ancak bende mevcut bir bilgi sayesinde bana verildi» dedi. O bilmiyor mu ki, kendisinden daha güçlü ve ondan daha çok cemaati bulunan nice kimseleri Allah helâk etmişti. Suçlulardan günahları sorulmaz. Çünkü Allah onları bilir."},{"n":79,"t":"Karun süsü, debdebesi içinde kavminin karşısına çıktı. Dünya hayatını isteyenler; «Keşke Karun’a verilenlerin bir benzeri de bize verilse, doğrusu o büyük varlık sahibidir» demişlerdi."},{"n":80,"t":"Kendilerine ilim verilmiş olanlar ise; «Size yazıklar olsun, inanan ve yararlı iş yapanlar için Allah’ın sevabı daha hayırlıdır. Buna ancak sabredenler kavuşur» dediler."},{"n":81,"t":"Sonunda biz onu da sarayını da yerin dibine geçirdik. Allah’a karşı ona yardım edecek bir topluluğu olmadı. Kendi kendini kurtarabilecek kimselerden de değildi."},{"n":82,"t":"Dün onun yerinde olmayı isteyenler; «Demek Allah, kullarından dilediğinin rızkını genişletip bir ölçüye göre veriyor. Allah bize lutfetmemiş olsaydı, bizi de yerin dibine batırırdı. Demek ki, kâfirler kurtulmazlar» demeye başladı."},{"n":83,"t":"İşte ahiret yurdu. Onu yeryüzünde böbürlenmeyen ve bozgunculuk yapmayanlara veririz. Güzel sonuç Allah’a karşı gelmekten sakınanlarındır."},{"n":84,"t":"Kim bir iyilik getirirse, ona ondan daha güzeli vardır. Kim kötülük getirirse, kötülükleri yapanlar, ancak yaptıkları kötülük kadar cezalandırılırlar."},{"n":85,"t":"Ey Muhammed! Kur’an’ı sana indiren ve onu okumayı sana farz kılan Allah, elbette seni dönülecek yere döndürecek. De ki; «Rabbim kimin hidayet getirdiğini ve kimin apaçık bir sapıklık içinde bulunduğunu bilir.»"},{"n":86,"t":"Sen Kitab’ın senin kalbine bırakılacağını ummazdın. O Rabb’inden bir rahmettir. O halde kâfirlere yardımcı olma."},{"n":87,"t":"Ve Allah’ın, ayetleri sana indikten sonra sakın seni onlardan alıkoymasınlar. Rabb’ine davet et, ortak koşanlardan olma."},{"n":88,"t":"Allah ile beraber başka bir ilaha yalvarma. O’ndan başka ilah yoktur. O’ndan başka her şey yok olacaktır. Hüküm O’nundur ve O’na döndürüleceksiniz."}],[{"n":1,"t":"Elif. Lâm. Mim."},{"n":2,"t":"İnsanlar sırf ’inandık’ demekle; hiçbir sınavdan geçirilmeksizin bırakılıvereceklerini mi sanıyorlar?"},{"n":3,"t":"Biz onlardan önceki kuşakları sınavdan geçirdik. Bu sınav sonucunda Allah, doğru sözlüler ile yalancıları kesinlikle belirleyecektir."},{"n":4,"t":"Yoksa kötülük işleyenler bizim elimizden kurtulabileceklerini mi sanıyorlar? Ne kadar yanlış düşünüyorlar?"},{"n":5,"t":"Kim Allah’a kavuşmayı özlüyorsa, bilsin ki, Allah’ın bu buluşma için belirlediği vakit kesinlikle gelecektir. O her şeyi işitir ve her şeyi bilir."},{"n":6,"t":"Kim kötülüklere karşı savaşırsa bu savaşı kendisi için vermiş olur. Kuşku yok ki, Allah’ın hiçbir yaratığa ihtiyacı yoktur."},{"n":7,"t":"İman edip iyi ameller işleyenlerin kötülüklerini kesinlikle silecek ve onları iyiliklerinin daha üstün karşılıkları ile ödüllendireceğiz."},{"n":8,"t":"Biz insana ana babasına iyi davranmayı tavsiye ettik. Fakat eğer annen ve baban, ne idüğü belirsiz bir putu bana ortak koşmaya seni zorlarsa, sakın sözlerini dinleme. Hepiniz bana döneceksiniz. O zaman neler yaptığınızı size haber veririm."},{"n":9,"t":"İman edip iyi ameller işleyenleri kesinlikle iyi kullar arasına katarız."},{"n":10,"t":"Öyle kimseler var ki, «Allah’a inandık» derler. Fakat Allah uğrunda işkenceye uğradıklarında insanların işkencesini Allah’ın azabı ile bir tutarlar. Eğer sana Rabb’inin bir yardımı gelecek olursa, böyleleri kesinlikle «Biz sizlerle beraberdik» derler. Acaba Allah, insanların içlerinde sakladıkları duyguları herkesten iyi bilmez mi?"},{"n":11,"t":"Hiç kuşkusuz Allah, kimlerin iman ettiklerini iyi bildiği gibi, kimlerin münafık olduklarını da iyi bilir."},{"n":12,"t":"Kâfirler, mü’minlere «Bizim yolumuzu izleyin de günahlarınızı biz yüklenelim» derler. Oysa onların, mü’minlerin omuzlarındaki hiçbir günahı yüklenmeleri söz konusu değildir. Onlar kesinlikle yalan söylüyorlar."},{"n":13,"t":"Kafirler, hem kendi günah yüklerini ve hem de bu yüklerin yanında başka birçok günah yüklerini taşıyacaklar ve kıyamet günü düzmece iddiaları konusunda kesinlikle sorguya çekileceklerdir."},{"n":14,"t":"Biz Nuh’u, soydaşlarına peygamber olarak gönderdik. Dokuzyüzelli yıllık bir süre boyunca aralarında kaldı. Sonunda zalimliklerini inatla sürdürürlerken, Tufan’a yakalandılar."},{"n":15,"t":"Buna karşılık Nuh’u ve gemidekileri kurtararak bu olayı bütün insanların ders alacakları bir mucize yaptık."},{"n":16,"t":"İbrahim’i de peygamber olarak gönderdik. Hani o soydaşlarına dedi ki; «Allah’a kulluk ediniz, O’ndan korkunuz. Eğer bilirseniz bu sizin için daha hayırlıdır.»"},{"n":17,"t":"Sizler Allah’ı bir yana bırakarak birtakım putlara tapıyor, düzmece iddialar ortaya atıyorsunuz. Allah’ı bir yana bırakarak taptığınız putlar size rızık veremezler. Rızkınızı Allah katında arayınız, O’na kulluk ediniz, O’na şükrediniz, O’nun huzuruna döndürüleceksiniz."},{"n":18,"t":"Eğer peygamberinizi yalanlıyorsanız, biliniz ki, sizden önceki milletler de peygamberlerini yalanlamışlardı. Peygamberin görevi, ilahi mesajı açıkça duyurmaktan ibarettir."},{"n":19,"t":"Kâfirler, Allah’ın, canlıları ilk kez nasıl yarattığını ve ölüleri nasıl yeniden dirilteceğini görmüyorlar mı? Bu işlem Allah için kolaydır."},{"n":20,"t":"Onlara de ki; «Yeryüzünde geziniz de Allah’ın canlıları ilk kez nasıl yarattığını görünüz.» Allah bu yaratma işlemini ilerde bir kere daha tekrarlayacaktır. Hiç kuşkusuz Allah’ın her şeye gücü yeter."},{"n":21,"t":"Allah dilediğini azaba çarptırır ve dilediğine merhamet eder. Hepiniz O’nun huzuruna döndürüleceksiniz."},{"n":22,"t":"Ne yerde ve ne gökte Allah’ın yapacaklarına engel olamazsınız. Allah’dan başka hiçbir koruyucu dostunuz, hiçbir destekçiniz yoktur."},{"n":23,"t":"Allah’ın ayetlerini ve O’nun karşısına çıkacaklarını yalanlayanlar var ya, onlar rahmetimden ümitlerini kesmiş kimselerdir. Onları acıklı bir azap beklemektedir."},{"n":24,"t":"Soydaşlarının İbrahim’e verdikleri cevap sadece «Bu adamı öldürünüz, ya da yakınız» biçiminde oldu. Fakat Allah onu ateşte yanmaktan kurtardı. Hiç kuşkusuz bu olayda mü’minlerin alacakları birçok ders vardır."},{"n":25,"t":"İbrahim soydaşlarına dedi ki; «Sizler dünya hayatında birbirinizin hatırı için Allah’ı bir yana bırakarak putları ilah edindiniz. Ama ilerde kıyamet günü birbirinizi tanımazlıktan gelecek, birbirinize lânet okuyacaksınız. Varacağınız yer cehennemdir. Orada size yardım elini uzatan hiçbir kimse olmayacaktır.»"},{"n":26,"t":"Bunun üzerine Lût ona inandı ve soydaşlarına «Ben sizden uzaklaşıp Rabb’ime gidiyorum. Hiç kuşkusuz O üstün iradelidir ve her yaptığı yerindedir» dedi."},{"n":27,"t":"İbrahim’e İshak’ı ve Yakub’u armağan ettik. O’nun soyuna peygamberlik ve kitap sunduk. O’nu dünyada ödüllendirdiğimiz gibi hiç kuşkusuz ahirette de iyi kullarımız arasındadır."},{"n":28,"t":"«Sizler kesinlikle şimdiye kadar hiç kimsenin işlemediği, iğrenç bir eylemi yapıyorsunuz.»"},{"n":29,"t":"Sizler, kadınları bırakıp erkek erkeğe cinsel ilişkide bulunuyor, kervanların yolunu kesiyor ve aranızda düzenlediğiniz toplantılarda o çirkin eylemi işliyorsunuz. Öyle mi? Soydaşlarının tek cevabı «Eğer doğru söylüyorsan, Allah’ın azabını başımıza getir bakalım» demeleri oldu."},{"n":30,"t":"Lut dedi ki; «Rabb’im, şu bozgunculara karşı bana yardım et.»"},{"n":31,"t":"Elçilerimiz İbrahim’e oğlu olacağına ilişkin müjde ile geldiklerinde «Biz şu kentin halkını yok edeceğiz, çünkü oranın halkı zalimdir» dediler."},{"n":32,"t":"«Biz orada kimlerin olduğunu herkesten iyi biliyoruz. Lût’u ve yakınlarını kurtaracağız. Yalnız eşi orada kalarak azaba çarpılanlardan olacaktır.»"},{"n":33,"t":"Elçilerimiz yanına varınca Lût’un canı sıkıldı, gelişleri yüzünden telaşa kapıldı. Bunun üzerine elçilerimiz ona dediler ki; «Korkma, tasalanma. Biz seni ve yakınlarını kurtaracağız. Yalnız eşin geride kalıp azaba çarpılanlardan olacaktır.»"},{"n":34,"t":"Biz bu kent halkının iğrenç sapıklığı yüzünden başlarına gökten ağır bir azap yağdıracağız."},{"n":35,"t":"Biz o yıkık kentten, geriye düşünen kimselerin ders çıkarmalarına yarayacak belirgin izler bıraktık."},{"n":36,"t":"Medyenliler’e de kardeşleri Şuayb’ı peygamber olarak gönderdik. Şuayb dedi ki; «Ey soydaşlarım, Allah’a kulluk sununuz, ahiret gününü hiç aklınızdan çıkarmayınız, yeryüzünde kargaşa çıkarıp dirliği bozmayınız.»"},{"n":37,"t":"Fakat Medyenliler Şuayb’ı yalanladılar. Bunun üzerine ani bir yer sarsıntısına tutuldular da oldukları yerde yığılıp kalıverdiler."},{"n":38,"t":"Adoğulları ile Semudoğulları’nı da yok ettik. Bunu vaktiyle oturdukları evlerin yıkıntıları size açıkça göstermektedir. Şeytan onlara işledikleri kötülükleri güzel göstererek kendilerini yoldan çıkardı. oysa isteselerdi gerçeği görebilirlerdi."},{"n":39,"t":"Karun’u, Firavun’u ve Haman’ı yok ettik. Musa onlara açık kanıtlar getirdi. Fakat yeryüzünde büyüklük tasladılar, ama elimizden kurtulamadılar."},{"n":40,"t":"Her birini teker teker suçüstü yakaladık. Kimini önünde taşları savuran müthiş bir kasırgaya tuttuk, kimi korkunç bir gök gürültüsüne tutularak cansız yere düştü, kimini yerin dibine geçirdik, kimini de denizde boğduk. Allah’ın onlara zulmetmesi söz konusu değildi, fakat onlar kendilerine zulmettiler."},{"n":41,"t":"Allah dışında başka dostlar, başka dayanaklar edinenlerin durumu; ağdan örülmüş bir yuva edinen örümceğin durumuna benzer. Hiç kuşkusuz en dayanıksız ev, örümcek yuvasıdır. Onlar keşke bunun bilincine erselerdi."},{"n":42,"t":"Hiç kuşkusuz Allah onların kendisini bir yana bırakıp ne gibi şeylere taptıklarını bilir. O üstün iradelidir ve her yaptığı yerindedir."},{"n":43,"t":"Biz insanlara bu örnekleri anlatıyoruz, ama onların anlamını bilgililerden başkası kavrayamaz."},{"n":44,"t":"Allah gökleri ve yeri hak ilkesine dayalı olarak yarattı. Mü’minlerin bu olgudan alacakları birçok dersler vardır."},{"n":45,"t":"Ey Muhammed! Sana vahiy yolu ile indirilen Kitab’ı oku ve namazı kıl. Hiç kuşkusuz namaz, insanı iğrenç işlerden, kötülüklerden alıkor, Allah’ı anmak en büyük ibadettir. Allah ne yaptığınızı bilir."},{"n":46,"t":"Yahudilerin ve Hıristiyanların zalim olanları dışında kalanları ile tartışırken olabildiğince gönül alıcı ve etkili bir dil kullanınız. Onlara deyiniz ki, «Bizler hem bize ve hem de size indirilen kitaplara inanıyoruz. Bizim de sizin de ilahınız birdir, biz O tek ilaha teslim olmuşuz.»"},{"n":47,"t":"Ey muhammed, sana indirdiğimiz Kitab’ın niteliği işte budur. Buna göre daha önce kitap verdiklerimiz ona inanırlar. Şu müşriklerden de ona inananlar vardır. Bizim ayetlerimizi inkâr edenler, sadece inatçı kâfirlerdir."},{"n":48,"t":"Sen Kur’an’dan önce hiçbir kitap okumuş ya da eline kalem alarak yazmış biri değilsin. Öyle olsaydı batıl yanlısı inkârcılar kuşkulanırlardı."},{"n":49,"t":"Aslında Kur’an, kendilerine bilgi verilenlerin içlerine sinen açık ayetlerden, inandırıcı kanıtlardan oluşmuştur. Bizim ayetlerimizi inkâr edenler, sadece inatçı zalimlerdir."},{"n":50,"t":"Onlar «Allah Muhammed’e mucizeler indirseydi ya!» derler. Onlara de ki; «Mucizeler, Allah’ın tekelindedir. Ben sadece açık sözlü bir uyarıcıyım.»"},{"n":51,"t":"Kendilerine okunan bu Kitab’ı sana indirmiş olmamız onlara yetmiyor mu? Bu olay, mü’minler için ders alınacak, düşündürücü bir rahmettir."},{"n":52,"t":"Onlara de ki; «Benimle sizin aranızda Allah’ın tanıklığı yeterlidir. O göklerde ve yerde ne varsa hepsini bilir. Batıla, eğriye inanıp Allah’ı inkar edenler var ya, onlar hüsrana uğrayacak kimselerdir.»"},{"n":53,"t":"Onlar senden azabımın bir an önce gerçekleşmesini isterler. Eğer azabımın belirli bir vadesi olmasaydı, hemen başlarına gelirdi. Fakat azabım hiç beklemedikleri bir anda, farkında olmadan başlarına gelecektir."},{"n":54,"t":"Onlar senden azabımın bir an önce gerçekleşmesini isterler. Oysa cehennem, kâfirleri çepeçevre kuşatmıştır."},{"n":55,"t":"O gün azap, tepelerinden inerek ve ayakları altından çıkarak onları sarar ve kendilerine «yaptığınız kötülüklerin karşılığını tadınız bakalım» denir."},{"n":56,"t":"Ey mü’min kullarım, benim yarattığım bu yeryüzü geniştir. O halde gerektiğinde yurt değiştirmeyi göze alarak sırf bana kulluk ediniz."},{"n":57,"t":"Her canlı ölümü tadacak ve sonra hepiniz benim huzuruma döndürüleceksiniz."},{"n":58,"t":"İman edip iyi ameller işleyenleri, altlarından çeşitli ırmaklar akan ve içlerinde sürekli kalacakları yüksek köşklere yerleştiririz. İyi işler yapanların alacakları ödül ne güzeldir!"},{"n":59,"t":"Onlar ki, sıkıntılar karşısında sabrederler ve sadece Rabb’lerine güvenirler."},{"n":60,"t":"Nice hayvanlar var ki, rızıklarını sağlamaya güçleri yetmez. Onların ve sizin rızkınızı Allah sağlar. O her şeyi işitir, her şeyi bilir."},{"n":61,"t":"Eğer müşriklere «Gökleri ve yeri yaratan, güneşi ve ayı insanların yararına sunan kimdir?» diye sorarsan kesinlikle «Allah’tır» derler. Öyleyse nasıl gerçekten saptırtıyorlar?"},{"n":62,"t":"Allah, dilediği kulunun rızkını bol verir, dilediği kulunun rızkını da kısar. Hiç kuşkusuz Allah her şeyi bilir."},{"n":63,"t":"Eğer müşriklere «Gökten yere su indirerek onun aracılığı ile ölmüş toprağı canlandıran kimdir?» diye sorarsan kesinlikle «Allah’dır» derler. De ki, «Hamd olsun Allah’a». Aslında onların çoğu düşünme yeteneğinden yoksun kimselerdir."},{"n":64,"t":"Bu dünya hayatı oyundan ve eğlenceden başka bir şey değildir. Asıl hayat ahiret yurdundaki hayattır. Kâfirler keşki bunun bilincine varsalardı."},{"n":65,"t":"Onlar gemiye bindikleri zaman sırf Allah’a yönelik bir inançla O’na yalvarırlar. Fakat Allah onları denizin tehlikelerinden kurtararak karaya çıkarınca hemen eski puta tapan inançlarına dönerler."},{"n":66,"t":"Böylece kendilerine verdiğimiz nimetlere nankörlük etsinler ve dünyada zevkleri ile oyalansınlar bakalım! Nasıl olsa ilerde gerçeği öğreneceklerdir.!"},{"n":67,"t":"Çevrelerindeki beldelerde oturan insanlar kaçırılırken, can güvenliğinden yoksun bir hayat yaşarken onların kentini dokunulmaz ve güvenli bir belde yaptığımızı görmüyorlar mı? Buna rağmen hâlâ asılsız ilahlara inanıp Allah’ın nimetlerini inkâr mı ediyorlar?"},{"n":68,"t":"Allah hakkında yalan uydurarak O’na iftira edenden ya da gerçeği yalanlayandan daha zalim kim olabilir? Kâfirlerin yeri cehennem değil mi?"},{"n":69,"t":"Uğrumuzda cihad edenleri, kesinlikle bize ulaştıran yollara erdiririz. Hiç kuşkusuz Allah iyi işler yapanlarla beraberdir."}],[{"n":1,"t":"Elif, lâm, mim."},{"n":2,"t":"Rumlar yenildi."},{"n":3,"t":"En yakın bir yerde. Onlar bu yenilgilerinden sonra yeneceklerdir."},{"n":4,"t":"Birkaç yıl içinde, eninde sonunda emir Allah’ındır. O gün mü’minler sevinir."},{"n":5,"t":"Allah dilediğine yardım eder. O güçlüdür (galibdir) esirgeyendir."},{"n":6,"t":"fakat insanların çoğu bunu bilmezler."},{"n":7,"t":"Onlar dünya hayatının görülen kısmını bilirler. Ahiretten ise habersizdirler."},{"n":8,"t":"Kendi kendilerine hiç düşünmediler mi ki, Allah göklerde, yerde ve bu ikisi arasında bulunan her şeyi ancak hak ile, belirlenmiş bir süre ile yaratmıştır. İnsanların çoğu, Rabb’lerine kavuşmayı inkâr ederler."},{"n":9,"t":"Yeryüzünde gezip, kendilerinden önceki insanların sonlarının nasıl olduğuna bakmazlar mı? Onlar kendilerinden daha güçlü idiler. Yeryüzünü kazıp altüst etmişler ve onu, bunların imar ettiklerinden daha çok imar etmişlerdir. Onlara da elçileri, delillerle gelmişti. Böylece Allah onlara zulmetmiyor, onlar kendilerine zulmediyorlardı."},{"n":10,"t":"Sonra kötülük edenlerin sonu çok kötü oldu. Çünkü Allah’ın ayetlerini yalanladılar. Ve onlarla alay ediyorlardı."},{"n":11,"t":"Allah önce yaratır, ölümünden sonra tekrar diriltir. Sonunda O’na döneceksiniz."},{"n":12,"t":"Kıyamet kopacağı gün suçlular ümitsizlik içinde susarlar."},{"n":13,"t":"Allah’a ortak koştuklarından kendilerine hiçbir şefaatçı çıkmaz. O zaman ortaklarını inkâr ederler."},{"n":14,"t":"Kıyamet kopacağı gün, işte o gün mü’minlerle kâfirler birbirinden ayrılırlar."},{"n":15,"t":"İnanıp iyi işler yapanlar, cennette bir bahçe içinde neşelendirilirler."},{"n":16,"t":"İnkâr edip ayetlerimizi ve ahiret buluşmasını yalanlayanlara gelince; işte onlar azapla yüz yüze bırakılırlar."},{"n":17,"t":"Öyle ise akşama girdiğiniz zaman ve sabaha erdiğiniz zaman Allah’ı tesbih edin."},{"n":18,"t":"Göklerde ve yerde, günün sonunda, öğleye erdiğiniz zaman da hamd O’nundur."},{"n":19,"t":"O ölüden diri çıkarır, diriden ölü çıkarır. Yeryüzünü ölümden sonra o canlandırır."},{"n":20,"t":"Sizi topraktan yaratması O’nun delillerindendir. Sonra birer insan olup yeryüzüne yayılırsınız."},{"n":21,"t":"İçinizden kendileri ile huzura kavuşacağınız eşler yaratıp aranızda sevgi ve esirgeme var etmesi de O’nun ayetlerindendir. Şüphesiz ki bunlarda düşünen kavim için ayetler vardır."},{"n":22,"t":"O’nun delillerinden biri de, göklerin ve yerin yaratılması, dillerinizin ve renklerinizin ayrı ayrı olmasıdır. Şüphesiz bunda, bilenler için ibretler vardır."},{"n":23,"t":"O’nun delillerinden biri de, geceleyin uyumanız, gündüz de O’nun lütfundan rızık aramanızdır. Şüphesiz, bunda işiten bir toplum için ibretler vardır."},{"n":24,"t":"O’nun delillerinden biri de, size korku ve ümit veren şimşeği göstermesi, gökten su indirip ölümden sonra yeri diriltmesidir. Şüphesiz bunda düşünen bir toplum için ibretler vardır."},{"n":25,"t":"O’nun delillerinden biri de, göğün ve yerin O’nun buyruğu ile ayakta durmasıdır. Sonra sizi kabirlerinizden bir çağırmaya görsün, hemen çıkıverirsiniz."},{"n":26,"t":"Göklerde ve yerde olanlar O’nundur, hepsi O’na boyun eğmiştir."},{"n":27,"t":"O’dur önce yaratan sonra onu tekrar eden. Bu O’nun için daha kolaydır. Göklerde ve yerde en üstün sıfatlar O’nundur. Ve O Aziz’dir, Hakim’dir."},{"n":28,"t":"Size verdiğimiz rızıklarda, emrinize verilen kölelerin, hizmetçilerin eşit suretle hak sahibi olmalarına razı olur ve birbirinizden çekindiğiniz gibi onlardan da çekindiğiniz ortaklar var mı? İşte biz aklını kullanan bir toplum için delillerimizi böyle açıklıyoruz."},{"n":29,"t":"Hayır o zulmedenler körü körüne kendi heveslerine uymuşlardır. Allah’ın saptırdığı kimseyi kim doğru yola iletebilir? Onların yardımcıları da yoktur."},{"n":30,"t":"Allah’ın yaratma kanununa uygun olarak dine dön ki, insanları ona göre yaratmıştır. Allah’ın yaratması değiştirilemez. İşte doğru din budur. Fakat insanların çoğu bilmezler."},{"n":31,"t":"Yalnız O’na yönelin ve O’ndan korkun; namazı kılın ve Allah’a ortak koşanlardan olmayın."},{"n":32,"t":"Müşrikler dinlerini parçaladılar ve bölük bölük oldular. Bunlardan her fırka kendi yanındakiyle böbürlenmektedir."},{"n":33,"t":"İnsanlara bir zarar dokundu mu, Rabb’lerine yönelerek O’na yalvarırlar. Sonra Rabb’leri, onlara kendinden bir rahmet tattırınca, hemen onlardan bir grup, Rabb’lerine ortak koşarlar."},{"n":34,"t":"Böyle yaparlar ki kendilerine verdiğimiz nimete karşı nankörlük etsinler. Haydi! Biraz eğlenin bakalım, yakında sonunuzun ne olduğunu bileceksiniz."},{"n":35,"t":"Yoksa onlara ortak koşmalarını söyleyen bir delil mi indirdik?"},{"n":36,"t":"Biz insanlara bir rahmet tattırdığımız zaman sevinirler. Şayet yaptıklarından dolayı başlarına bir kötülük gelirse hemen ümitsizliğe düşerler."},{"n":37,"t":"Görmediler mi, Allah dilediğine rızkı genişletiyor da, daraltıyor da. Şüphesiz inanan bir toplum için bunda ibretler vardır."},{"n":38,"t":"Akrabaya, yoksula, yolcuya hakkını ver. Allah’ın rızasını isteyenler için bu daha hayırlıdır. işte onlar kurtuluşa erenlerdir."},{"n":39,"t":"İnsanların mallarında artış olsun diye verdiğiniz herhangi bir faiz, Allah katında artmaz. Allah’ın rızasını isteyerek verdiğiniz zekât böyle değildir. İşte zekât veren o kimseler, sevaplarını ve mallarını kat kat arttıranlardır."},{"n":40,"t":"Sizi yaratan, sonra rızıklandıran, sonra öldüren daha sonra da dirilten Allah’dır. O’na koştuğunuz ortaklarınızdan böyle bir şey yapan var mıdır? Allah onların ortak koştuklarından münezzehtir ve yücedir."},{"n":41,"t":"İnsanların elleriyle kazandıkları (günahları) yüzünden karada ve denizde fesat çıktı. Allah da belki dönerler diye yaptıklarının bir kısmını böylece kendilerine tattırır."},{"n":42,"t":"De ki; «Yeryüzünde dolaşın da daha öncekilerden ortak koşanların sonunun nasıl olduğuna bir bakın.»"},{"n":43,"t":"Allah katından dönüşü olmayan bir gün gelmeden önce yönünü dosdoğru dine çevir! O gün insanlar bölük bölük ayrılacaklardır."},{"n":44,"t":"Kim inkâr ederse inkârı kendi aleyhine olur. Yararlı bir iş yapanlar da cennette kendileri için yer hazırlamaktadırlar."},{"n":45,"t":"Çünkü Allah inanıp yararlı iş işleyenlere lütfundan karşılık verecektir. Doğrusu O, inkârcıları sevmez."},{"n":46,"t":"Rüzgârları müjdeciler olarak göndermesi, size rahmetini tattırması, buyruğu ile gemilerin yürümesi, lütfundan rızık istemeniz O’nun varlığının delillerindendir. Belki şükredersiniz."},{"n":47,"t":"Andolsun ki, biz senden önce de elçileri kavimlerine gönderdik, onlar belgeler getirdiler; dinleyip suç işleyenlerden öç aldık, zira inananlara yardım etmek bize hak olmuştur."},{"n":48,"t":"Rüzgârları gönderip, bulutları yürüten, onları gökte dilediği gibi yayan ve kısım kısım yığan Allah’dır. Sen de aralarından yağmurun çıktığını görürsün. Derken onu kullarından dilediğine verince hemen sevinirler."},{"n":49,"t":"Oysa onlar, daha önce üzerlerine yağmur yağdırılmasından iyice ümitlerini kesmişlerdi."},{"n":50,"t":"Allah’ın rahmetinin belirtilerine bir bak. Nasıl yeri ölümden sonra diriltiyor? Şüphe yok ki, o ölüleri diriltir. O her şeye kadirdir."},{"n":51,"t":"Andolsun bir rüzgâr göndersek te ekini sararmış görseler, hemen nankörlüğe başlarlar."},{"n":52,"t":"Ey Muhammed! Sen ölülere işittiremezsin; arkalarını dönüp giden sağırlara da çağrını işittiremezsin."},{"n":53,"t":"Ve sen, körleri de sapıklıklarından çıkarıp yola getiremezsin. Sen ancak ayetlerimize inananlara işittirirsin de onlar müslüman olurlar."},{"n":54,"t":"Sizi güçsüz olarak yaratan, güçsüzlükten sonra kuvvetli yapan, sonra da kuvvetliliğin ardından güçsüz ve ihtiyar yapan Allah’dır., Çünkü O, dilediğini yaratır; bilendir ve kudret sahibidir."},{"n":55,"t":"Kıyamet koptuğu gün, suçlular dünyada bir saatten fazla kalmadıklarına yemin ederler. İşte onlar dünyada da aldatılıp haktan böyle dönüyorlardı."},{"n":56,"t":"Kendilerine bilgi ve iman verilenler dediler ki; «Andolsun siz, Allah’ın yazgısınca tayin edilen yeniden dirilme gününe kadar kaldınız. İşte bu yeniden dirilme günüdür. Fakat siz bilmiyordunuz.»"},{"n":57,"t":"Artık zulmedenlere o gün mazeretleri fayda vermeyecek, onlardan Allah’ı hoşnut etmeleri de istenmez."},{"n":58,"t":"Andolsun; biz bu Kur’an’da insanlara her çeşit misali getirip anlattık. Onlara bir ayet getirdiğin zaman inkâr edenler; «Siz ancak geleneklerinizi iptal edenlerden başkası değilsiniz» derler."},{"n":59,"t":"İşte Allah, bilmeyenlerin kalplerini böyle mühürler."},{"n":60,"t":"Sen şimdi sabret! Bil ki, Allah’ın sözü gerçektir. İnanmayanlar seni telaşa ve gevşekliğe düşürmesinler."}],[{"n":1,"t":"Elif, lam, mim."},{"n":2,"t":"Bunlar, hikmetli Kitab’ın ayetleridir."},{"n":3,"t":"Bunlar güzel davrananlara yol gösterici ve rahmettir."},{"n":4,"t":"İşte onlar ki, namaz kılarlar, zekât verirler, ahirete de kesin olarak inanırlar."},{"n":5,"t":"İşte onlar Rabb’lerinin göstermiş olduğu doğru bir yol üzeredirler ve kurtuluşa erenlerdir."},{"n":6,"t":"İnsanlardan öyleleri var ki, herhangi bir bilgiye dayanmadan insanları Allah’ın yolundan saptırmak ve onunla alay etmek için gerçeği boş sözlerle değişirler. İşte alçaltıcı azap bunlar içindir."},{"n":7,"t":"Ayetlerimiz o sapık kimseye okunduğu zaman sanki onları hiç işitmemiş, sanki kulaklarında ağırlık varmış gibi büyüklenerek sırt çevirir. İşte onu can yakıcı azapla müjdele!"},{"n":8,"t":"İnanıp yararlı iyi işler yapanlar için nimeti bol cennetler vardır."},{"n":9,"t":"Orada ebedi olarak kalacaklardır. Bu, Allah’ın gerçek vaadidir. O güçlüdür, hakimdir."},{"n":10,"t":"Gökleri gördüğünüz gibi direksiz olarak yaratmış, sizi sarsar diye yere ağır baskılar koymuş, orada her türlü canlıyı yaymıştır. Gökten su indirip orada her sınıf güzel nebatlar yetiştirmişizdir."},{"n":11,"t":"İşte bunlar Allah’ın yarattıklarıdır. O’ndan başkası ne yarattı? Doğrusu o zalimler, açık bir sapıklık içindedirler."},{"n":12,"t":"Andolsun ki, biz Lokman’a hikmet verdik. «Allah’a şükret» dedik, kim şükrederse kendisi için şükreder. Kim nankörlük ederse bilsin ki, Allah zengindir, övülmeye lâyık olandır."},{"n":13,"t":"Lokman oğluna öğüt vererek; «Ey oğulcuğum! Allah’a ortak koşma, çünkü ortak koşmak, büyük bir zulümdür.»"},{"n":14,"t":"Biz insana, ana babasına iyi davranmasını tavsiye etmişizdir. Anası onu zayıflık üstüne zayıflık çekerek karnında taşımıştır. Onun sütten kesilmesi de iki yıl içinde olur. Bana ve ana babana şükret diye tavsiyede bulunmuşuzdur. Dönüş Allah’adır."},{"n":15,"t":"Eğer onlar seni körü körüne bana ortak koşman için zorlarlarsa, onlara itaat etme; dünya işlerinde onlarla iyi geçin, Allah’a yönelen kimsenin yoluna uy. Sonunda dönüşünüz banadır. O zaman size yaptıklarınızı haber vereceğim."},{"n":16,"t":"«Oğulcuğum! Yaptığın iyi veya kötü iş, bir hardal tanesi ağırlığınca olsa ve bu bir kayanın içinde, göklerde veya yerde bulunsa, yine de Allah onu karşına getirir. Doğrusu Allah lâtiftir, haberdardır."},{"n":17,"t":"Oğulcuğum namazı kıl, iyiliği emret, kötülükten vazgeçmeye çalış ve başına gelene sabret. Çünkü bunlar yapılması gereken işlerdir."},{"n":18,"t":"İnsanları küçümseyip yüz çevirme! Yeryüzünde böbürlenerek yürüme! Allah, kendini beğenmiş övünen kimseyi sevmez."},{"n":19,"t":"Yürüyüşünde tabii ol (ölçülü hareket et) sesini de kıs. Çünkü seslerin en çirkini eşeklerin sesidir."},{"n":20,"t":"Allah, göklerde ve yerde bulunanları emrinize açık ve gizli olarak nimetlerini bol bol verdiğini görmediniz mi? Yine de insanlardan bazıları ne bilgisi ne yol göstereni ne de aydınlatıcı bir Kitab’ı olmadan Allah hakkında tartışır."},{"n":21,"t":"Onlara; «Allah’ın indirdiğine uyun!» dense; «Hayır biz babalarımızı üzerinde bulduğumuz yola uyarız» derler. Şeytan babalarınızı alevli ateşin azabına çağırmış olsa da mı?"},{"n":22,"t":"Kim güzel davranarak kendini Allah’a teslim ederse, o en sağlam kulpa yapışmıştır. Sonunda bütün işler Allah’a döner."},{"n":23,"t":"Kim de inkâr ederse onun inkârı seni üzmesin; onların dönüşü bizedir. O zaman yaptıklarını kendilerine haber veririz. Allah kalplerde olanı şüphesiz bilir."},{"n":24,"t":"Onlara biraz geçim sağlar, sonra ağır bir azaba sürükleriz."},{"n":25,"t":"Andolsun ki onlara; «Gökleri ve yeri kim yarattı» diye sorsan «Allah» derler. Hamd Allah’a mahsustur. Hayır onların çoğu bilmiyor."},{"n":26,"t":"Göklerde ve yerde ne varsa hepsi Allah’ındır. Şüphesiz Allah müstağnidir, övülmeye lâyık olandır."},{"n":27,"t":"Yeryüzünde bulunan ağaçlar kalem olsa, denizlerde mürekkep olsa ve yedi deniz daha eklense, yine Allah’ın sözleri yazmakla tükenmez. Doğrusu Allah güçlüdür, hakimdir."},{"n":28,"t":"Ey insanlar! Sizin yaratılmanız ve tekrar dirilmeniz tek bir kişinin yaratılması ve tekrar diriltilmesi gibidir. Şüphesiz Allah, işitendir. görendir."},{"n":29,"t":"Görmedin mi Allah, geceyi gündüzün içine; gündüzü gecenin içine sokuyor. Güneş ve ayı emrine boyun eğdirmiştir. Her biri belirli bir süreye kadar hareket eder. Allah yaptıklarınızdan haberdardır."},{"n":30,"t":"Bu, Allah’ın hak olmasından ve O’ndan başka taptıklarının batıl olmasındandır. Doğrusu Allah yücedir, büyüktür."},{"n":31,"t":"Allah size, bir kısım delillerini göstersin diye, Allah’ın izniyle gemilerin denizde akıp gittiğini görmediniz mi? Şüphesiz bunda çok sabreden çok şükreden herkes için ibretler vardır."},{"n":32,"t":"Dağlar gibi dalgalar insanları kuşattığı zaman dini yalnız Allah’a has kılarak O’na yalvarırlar. Allah onları karaya çıkarıp kurtardığı zaman, içlerinden bir kısmı gevşeme gösterirler. Zaten bizim ayetlerimizi nankör gaddarlardan başkası inkâr etmez."},{"n":33,"t":"Ey insanlar, Rabb’inizden korkun ve babanın, çocuğuna yaptığından ceza görmeyeceği, çocuğun da babasının yaptığından ceza görmeyeceği bir günden çekinin. Allah’ın vaadi gerçektir. Dünya hayatı sizi aldatmasın ve şeytan, Allah’ın affına güvendirerek sizi kandırmasın."},{"n":34,"t":"Kıyamet vakti hakkındaki bilgi ancak Allah’ın katındadır. Yağmuru yağdırır, rahimlerde olanı O bilir. Hiç kimse yarın ne kazanacağını bilemez ve hiç kimse nerede öleceğini bilemez. Her şeyi bilen ve her şeyden haberi olan yalnız Allah’dır."}],[{"n":1,"t":"Elif Lam Mim."},{"n":2,"t":"Şüphe yok ki, Kitab’ın indirilişi, alemlerin Rabb’i tarafındandır."},{"n":3,"t":"Yoksa «onu peygamber uydurdu mu» diyorlar? Hayır, O senden önce bir peygamber gönderilmemiş olan kavmi uyarması için sana Rabb’inden gelen bir gerçektir. Umulur ki, doğru yolu bulurlar."},{"n":4,"t":"Gökleri, yeri ve ikisinin arasında bulunanları altı günde yaratan, sonra arşa hükmeden (istiva eden) Allah’tır. O’ndan başka bir dostunuz ve şefaatcınız yoktur. Düşünüp öğüt almıyor musunuz?"},{"n":5,"t":"Allah, gökten yere kadar olan bütün işleri düzenleyip yönetir. Sonra işler, sizin hesabınızla bin yıl kadar tutan bir gün içinde O’na çıkar."},{"n":6,"t":"O görüleni de görülmeyeni de bilendir üstün ve merhametli olandır."},{"n":7,"t":"O Allah ki, her şeyin yaratılışını güzel yaptı ve insanı yaratmaya çamurdan başladı."},{"n":8,"t":"Sonra onun soyunu nutfeden, hakir bir suyun özünden çoğalttı."},{"n":9,"t":"Sonra ona biçim verdi, ona kendi ruhundan üfledi ve sizin için kulaklar, gözler ve gönüller yarattı. Ne kadar az şükrediyorsunuz?"},{"n":10,"t":"«Biz yerde toprağa karışıp yok olduktan sonra yeniden mi yaratılacağız?» derler. Doğrusu onlar Rabb’ine kavuşmayı inkâr edenlerdir."},{"n":11,"t":"De ki; «Sizin üzerinize vekil edilen ölüm meleği, canınızı alacak, sonra Rabb’inize döndürüleceksiniz.»"},{"n":12,"t":"Suçluları Rabb’lerinin huzurunda utançtan başlarını öne eğmiş olarak «Rabb’imiz! Gördük, dinledik, artık bizi dünyaya geri gönder de iyi iş yapalım; artık kesin olarak inandık» derken bir görsen."},{"n":13,"t":"Dileseydik herkese hidayeti verirdik. Fakat benden «mutlaka cehennemi, insanlardan ve cinlerden bir kısmıyla tamamen dolduracağım» sözü çıkmıştır."},{"n":14,"t":"Bugüne kavuşmayı unutmanızın cezasını şimdi tadın bakalım! Doğrusu biz de sizi unuttuk. Yaptıklarınıza karşılık ebedi azabı tadın."},{"n":15,"t":"Bizim ayetlerimize inanan kimselere, ayetlerimiz hatırlatıldığı zaman hemen secdeye kapanırlar. Rabb’lerini överek tesbih ederler, büyüklük taslamazlar."},{"n":16,"t":"Gece teheccüd namazı kılmak için yanlarını yataklardan ayırıp kalkarlar, korkarak ve ümit ederek Rabb’lerine dua ederler ve kendilerine verdiğimiz rızıktan hayır için harcarlar."},{"n":17,"t":"Yaptıklarına karşılık olarak, onlar için nice sevindirici ve göz kamaştırıcı nimetlerin saklı olduğunu hiç kimse bilmez."},{"n":18,"t":"Hiç inanan kimse yoldan çıkan kimse gibi olur mu? Elbette bunlar bir olmaz."},{"n":19,"t":"İnanıp yararlı iş işleyenlere gelince, yaptıklarına karşılık varacakları cennet konakları vardır."},{"n":20,"t":"Yoldan çıkanların barınacakları yer de ateştir. Ne zaman oradan çıkmak isterlerse, yine oraya geri çevrilirler ve onlara «yalanlamakta olduğunuz ateşin azabını tadın» denir."},{"n":21,"t":"Belki dönüp yola gelirler diye onlara büyük azapdan önce mutlaka daha yakın azabı da tattıracağız."},{"n":22,"t":"Kendisine Rabb’inin ayetleri hatırlatıldıktan sonra onlardan yüz çevirenden daha zalim kim vardır? Muhakkak ki biz, suçlulardan öç alıcıyız."},{"n":23,"t":"Andolsun biz Musa’ya kitabı verdik. Ey Muhammed! Sakın sen ona kavuşacağından şüphe etme. Ona İsrailoğullarını yol gösterici yaptık."},{"n":24,"t":"Sabrettikleri ve ayetlerimize kesinlikle inandıkları zaman, onların içinden, buyruğumuzla doğru yola götüren önderler yaptık."},{"n":25,"t":"Şüphesiz Rabb’in kıyamet günü, ayrılığa düştükleri konularda onların aralarında hükmedecektir."},{"n":26,"t":"Bugün yurtlarında dolaştıkları nice kuşakları daha önce helâk etmiş olmamız, halâ onları yola getirmedi mi? Şüphesiz bunda ibretler vardır. Halâ dinlemeyecekler mi?"},{"n":27,"t":"Kuru yerlere suyu gönderip, onunla hayvanlarının ve kendilerinin yedikleri ekinleri çıkardığımızı görmezler mi? Görmüyorlar mı?"},{"n":28,"t":"Doğru söylüyorsanız bu fetih ne zaman? diyorlar."},{"n":29,"t":"De ki; «Fetih günü gelince inkâr edenlere, o zaman inanmaları fayda vermez ve kendilerine mühlet de verilmez.»"},{"n":30,"t":"Sen onlardan yüz çevir ve bekle, zaten onlar da beklemektedirler."}],[{"n":1,"t":"Ey Peygamber! Allah’tan kork, kafirlere ve münafıklara itaat etme. Şüphesiz, Allah her şeyi bilir ve her yaptığı yerindedir."},{"n":2,"t":"Sana Rabbin tarafından vahyedilen kitaba uy; şüphesiz Allah, yaptıklarınızdan haberdardır."},{"n":3,"t":"Allah’a güven, dost ve dayanak olarak Allah yeter."},{"n":4,"t":"Allah bir insanın göğüs boşluğunda iki kalp yaratmadığı gibi zihar yaptığınız (sen bana anamın sırtı gibisin dediğiniz) eşlerinizi, sizin anneleriniz yapmadı ve evlatlıklarınızı da öz oğullarınız gibi saymanızı meşru kılmamıştır. Bunlar sizin dillerinize doladığınız boş sözlerdir. Allah gerçeği söyler ve O, doğru yola iletir."},{"n":5,"t":"Evlatlıkları öz babalarına nisbet ederek çağırın, bu Allah katında en doğru olanıdır. Şayet öz babalarını bilmiyorsanız, onlar sizin din kardeşleriniz ve dostlarınızdır. Yanılarak yaptığınızda size bir günah yok, fakat kalbinizin bile bile yaptığınızda günah vardır. Allah çok bağışlayan, çok esirgeyendir."},{"n":6,"t":"Peygamber mü’minlere canlarından ileridir. O’nun eşleri de mü’minlerin anneleridir. Akraba olanlar miras hususunda Allah’ın kitabına göre birbirlerine muhacirlerden ve ensardan daha yakındır. Dostlarınıza yapacağınız uygun bir vasiyet bunun dışındadır. Bunlar kitapta yazılmıştır."},{"n":7,"t":"Hani «biz Peygamberlerden söz almıştık, senden, Nuh’tan, İbrahim’den, Musa’dan ve Meryem oğlu İsa’dan, pek sağlam bir söz aldık.»"},{"n":8,"t":"Allah, doğrulardan doğruluklarını sormak ve kafirlere can yakıcı azap hazırlamak için bunu yapmıştır."},{"n":9,"t":"Ey mü’minler! Allah’ın size yönelik nimetini hatırlayın, bir zaman üzerinize ordular gelmişti de, biz onların üzerine rüzgar ve sizin görmediğiniz ordular göndermiştik. Allah yaptıklarınızı görüyordu."},{"n":10,"t":"Onlar size yukarınızdan ve aşağınızdan gelmişlerdi; gözler kaymış, yürekler ağızlara gelmişti. Allah hakkında türlü zanlarda bulunuyordunuz."},{"n":11,"t":"İşte orada mü’minler denenmiş, şiddetli bir sarsıntı ile sarsılmışlardı."},{"n":12,"t":"«Allah ve Resulü bize sadece boş vaadlerde bulundu» diyorlardı."},{"n":13,"t":"Onlardan bir grup ta demişti ki; «Ey Medine halkı, artık tutunacak yeriniz yok, geri dönün!» Onlardan bir topluluk da «Evlerimiz düşmana açıktır» diye izin istemişlerdi. Oysa onların evleri düşmana açık değildi. Sadece kaçmak istiyorlardı."},{"n":14,"t":"Eğer Medine’nin etrafından üzerlerine saldırılsaydı, sonra da kendilerinden dinlerinden dönmeleri istense, çok azı hariç hemen dinlerinden dönerlerdi."},{"n":15,"t":"Oysa arkalarına dönüp kaçmayacaklarına dair Allah’a söz vermişlerdi. Allah’a verilen sözden sorumluydular."},{"n":16,"t":"«Eğer ölümden veya öldürülmekten kaçıyorsanız, kaçmak size fayda vermez. Kaçsanız bile az zaman yaşatılırsınız.»"},{"n":17,"t":"«Allah size bir kötülük dilerse veya bir rahmet isterse, O’na karşı kim sizi koruyabilir? Allah’tan başka dost ve yardımcı bulamazsınız.»"},{"n":18,"t":"Allah içinizde savaştan alıkoyanları ve kardeşlerine «Bize gelin zorlanmadıkça savaşmayın» diyenleri gerçekten bilir. Zaten bunlardan pek azı savaşa gelir."},{"n":19,"t":"Geldikleri zaman da size karşı çok hassastırlar, size yardım etmek istemezler. Ancak savaşta bir korku gelince, onların üzerine ölüm baygınlığı çökmüş insan gibi gözleri dönerek sana baktıklarını görürsün. Korku gidip te sıra ganimetleri paylaşmaya gelince, mala düşkünlük göstererek, sizi sivri dilleriyle incitirler. Onlar inanmamışlar, bu yüzden Allah onların işlerini boşa çıkarmıştır. Bu Allah’a göre kolaydır."},{"n":20,"t":"Bunlar, düşman birliklerinin (Medine’den) gitmediklerini sanıyorlardı. Bu birlikler tekrar gelmiş olsalardı, kendilerini çölde bedevilerin yanında bulunup, sadece sizin haberlerini sormayı dilerlerdi. İçinizde olsalardı, pek azı savaşırlardı."},{"n":21,"t":"Andolsun ki, Allah’ın elçisinde sizin için, Allah’a ve ahiret gününe kavuşmaya inanan ve Allah’ı çok anan kimseler için en güzel bir örnek vardır."},{"n":22,"t":"Mü’minler düşman ordularını gördükleri zaman; «Bu Allah’ın ve Resulünün bize vaad ettiği zaferdir. Allah ve Resulü doğru söylemiştir» dediler. Bu, onların sadece imanlarını ve teslimiyetlerini arttırdı."},{"n":23,"t":"Mü’minler arasında öyleleri var ki, Allah’a verdikleri sözde dururlar. Kimileri sözünü yerine getirip o yolda canını vermiştir; kimileri de şehitlik beklemektedir. Onlar hiç sözlerini değiştirmediler."},{"n":24,"t":"Bu sebeple Allah, doğruları doğrulukları ile mükafatlandırır; münafıkları da dilerse azaplandırır veya tevbelerini kabul eder. Şüphesiz Allah çok bağışlayan, çok esirgeyendir."},{"n":25,"t":"Allah, o kafirleri hiçbir şey elde edemeden öfkeleriyle geri çevirdi. Allah’ın yardımı savaşta mü’minlere yetti. Allah güçlüdür, mutlak galiptir."},{"n":26,"t":"Allah, kitap ehlinden onlara yardım eden Kureyze yahudilerini de kalelerinden indirdi ve kalplerine korku düşürdü. Onlardan bir kısmını öldürüyorsunuz, bir kısmını da esir alıyordunuz."},{"n":27,"t":"Topraklarını, evlerini, mallarını ve henüz ayağınızı dahi basmadığınız yerleri Allah size miras olarak verdi. Allah’ın gücü her şeye yeter."},{"n":28,"t":"Eğer dünya hayatını ve süslerini istiyorsanız gelin size boşanma bedelinizi vereyim ve güzellikle salıvereyim.»"},{"n":29,"t":"Eğer Allah’ın Peygamberini ve ahiret yurdunu istiyorsanız bilin ki, Allah içinizden iyi davrananlara büyük mükâfat hazırlamıştır."},{"n":30,"t":"Ey Peygamber hanımları! Sizden kim açık bir edepsizlik yaparsa, onun azabı iki kat olur. Bu Allah’a kolaydır."},{"n":31,"t":"Fakat sizden kim Allah’a ve Resulüne uymaya devam eder ve yararlı iş yaparsa ona da mükafatı iki kat veririz ve cennette onun için bol bir rızık hazırlamışızdır."},{"n":32,"t":"Ey Peygamber hanımları! Eğer Allah’tan sakınıyorsanız sizler herhangi bir kadın gibi değilsiniz. Sözü yumuşak, tatlı bir eda ile söylemeyin ki, kalbinde hastalık bulunan kimse kötü şeyler ümit etmesin, daima ciddi ve ağır başlı söz söyleyin."},{"n":33,"t":"Evlerinizde oturun, ilk cahiliye dönemi kadınlarının açılıp saçılması gibi açılıp saçılmayın. Namaz kılın, zekat verin, Allah’a ve Peygamberine itaat edin. Ey ehl- i beyt (Ey Peygamberin ev halkı) şüphesiz Allah sizden pisliği giderip sizi tertemiz yapmak ister."},{"n":34,"t":"Evlerinizde okunan Allah’ın ayetlerini ve hikmeti hatırlayın, şüphesiz Allah latiftir, her şeyden haberdardır."},{"n":35,"t":"Müslüman erkekler ve müslüman kadınlar, mü’min erkekler ve mü’min kadınlar, boyun eğen erkekler ve boyun eğen kadınlar, doğru erkekler ve doğru kadınlar, sabreden erkekler ve sabreden kadınlar, mütevazi erkekler ve mütevazi kadınlar, sadaka veren erkekler ve sadaka veren kadınlar, oruç tutan erkekler ve oruç tutan kadınlar, ırzlarını koruyan erkekler ve ırzlarını koruyan kadınlar, Allah’ı çok anan erkekler ve Allah’ı çok anan kadınlar; işte Allah bunlar için bağış ve büyük bir mükafat hazırlamıştır."},{"n":36,"t":"Allah ve Resulü, bir işte hüküm verdiği zaman, artık inanmış bir erkek ve kadına, o işi kendi isteklerine göre seçme hakkı yoktur. Kim Allah’a ve Resulüne karşı gelirse, apaçık bir sapıklığa düşmüş olur."},{"n":37,"t":"Ey Muhammed! Allah’ın nimet verdiği ve senin de nimetlendirdiğin kimseye, eşini bırakma, Allah’tan sakın diyor, Allah’ın açığa vuracağı şeyi içinde saklıyordun. İnsanlardan çekiniyordun; oysa Allah’tan çekinmen daha uygundu. Sonunda Zeyd eşiyle ilgisini kesince onu seninle evlendirdik ki evlatlıkları eşleriyle ilgilerini kestiklerinde onlara evlenmek konusunda mü’minlere bir sorumluluk olmadığı bilinsin. Allah’ın buyruğu yerine gelecektir."},{"n":38,"t":"Allah’ın, Peygambere takdir ettiği bir şeyde O’na bir güçlük yoktur. Bu Allah’ın sizden öncekilere de uyguladığı yasadır. Allah’ın emri şüphesiz gereği gibi yerine gelecektir."},{"n":39,"t":"O Peygamberler Allah’ın buyruklarını tebliğ ederler, Allah’tan korkarlar ve O’ndan başka kimseden korkmazlar. Allah hesap görücü olarak yeter."},{"n":40,"t":"Muhammed içinizden herhangi bir adamın babası değil, fakat O Allah’ın Resulü ve Peygamberlerin sonuncusudur. Allah her şeyi hakkıyla bilendir."},{"n":41,"t":"Ey inananlar Allah’ı çok anın."},{"n":42,"t":"ve O’nu sabah akşam tesbih ediniz."},{"n":43,"t":"Sizi karanlıklardan aydınlığa çıkarmak için üzerinize melekleriyle beraber rahmetini gönderen Allah’tır. Mü’minlere karşı çok bağışlayıcı, çok esirgeyici de O’dur."},{"n":44,"t":"O’na kavuştukları gün, Allah’ın onlara iltifatı selam’dır. Allah onlara güzel bir mükafat hazırlamıştır."},{"n":45,"t":"Ey Peygamber, biz seni tanık, müjdeci ve uyarıcı olarak gönderdik."},{"n":46,"t":"Allah’ın izniyle, bir davetçi ve aydınlatan bir lamba olarak görevlendirdik."},{"n":47,"t":"Mü’minlere Allah’tan büyük bir lütfa ereceklerini müjdele."},{"n":48,"t":"Kafirlere ve münafıklara itaat etme. Onların eziyetlerine aldırma, Allah’a güven; koruyucu olarak Allah sana yeter."},{"n":49,"t":"Ey iman edenler! Mü’min kadınları nikahlayıp da, henüz dokunmadan onları boşarsanız, onları iddet müddetince beklemeniz gerekmez. Kendilerine bağışta bulunarak onları güzellikle serbest bırakın."},{"n":50,"t":"Ey Peygamber! Mehirlerini verdiğin eşlerini, Allah’ın sana ganimet olarak verdiği cariyelerini, seninle beraber hicret eden amcanın kızlarını, halalarının kızlarını, dayının kızlarını, teyzelerinin kızlarını ve peygamber nikahlamayı dilediği takdirde mü’minlerden ayrı sırf sana mahsus olmak üzere, kendisinin mehrini Peygambere hibe eden mü’min kadını almanı helal kılmışızdır. Biz zorluğa uğramaman için mü’minlerin eşleri ve cariyeleri hakkında onların üzerine neyi farz kılmış olduğumuzu bildirmiştik. Allah bağışlayandır, merhamet edendir."},{"n":51,"t":"Ey Muhammed! Onların dilediğini geri bırakır dilediğini de yanına alırsın. Kendilerinden uzak durduğun kadınlardan arzu ettiğini tekrar yanına almanda, senin üzerine bir günah yoktur. Bu onların gözlerinin aydın olmasını, üzülmemelerini, hepsine verdiğin şeylere razı olmalarını daha iyi sağlar. Allah kalplerinizde olanı bilir; Allah bilendir, halimdir."},{"n":52,"t":"Ey peygamber! Bunların dışında artık sana başka kadınlarla evlenmek helal olmaz. Onlardan birinin güzellikleri hoşuna gitse bile, başka eşlerle değiştirmen de sana helal değildir. Ancak yasal olarak sahip olunan cariyeler hariç. Allah herşeyi görüp, gözetendir."},{"n":53,"t":"Ey inananlar! Peygamberin evlerine, yemeğe çağrılmaksızın vakitli vakitsiz girmeyin fakat davet edilirseniz girin ve yemeği yeyince dağılın. Sohbet etmek için de gidip oturmayın. Bu haliniz peygamberi üzüyor, o da size bir şey söylemeye çekiniyordu. Allah gerçeği söylemekten çekinmez. Peygamber eşlerinden bir şey isteyeceğinizde onu perde arkasından isteyin. Bu sayede sizin kalpleriniz de onların kalpleri de daha temiz kalır. Allah’ın Peygamberini üzmeniz ve O’ndan sonra eşlerini nikahlamanız asla caiz değildir. Çünkü bu Allah katında büyük bir günahtır."},{"n":54,"t":"Bir şeyi açıklasanız da gizleseniz de Allah şüphesiz hepsini bilir."},{"n":55,"t":"Onlara (Peygamber hanımlarına); babaları, oğulları, erkek kardeşleri, erkek kardeşlerinin oğulları, kız kardeşlerinin oğulları, hizmetçi kadınları ve cariyeleri hakkında bir günah yoktur. Ey Peygamber hanımları, Allah’tan korkun, şüphesiz Allah, her şeyi görmektedir."},{"n":56,"t":"Şüphesiz Allah ve melekleri Peygamberi överler. Ey inananlar! Siz de O’nu övün, O’na salat ve selam getirin."},{"n":57,"t":"Allah’ı ve Rasûlünü incitenlere gelince, Allah onları bu dünyada ve ahirette rahmetinden yoksun bırakacak ve onlar için alçaltıcı bir azap hazırlayacaktır."},{"n":58,"t":"Mü’min erkek ve kadınları, yapmadıkları bir şeyle suçlayıp inciltenler, iftira etmiş ve apaçık bir günah yüklenmiş olurlar."},{"n":59,"t":"Bir ihtiyaç için dışarı çıktıklarında örtülerini üstlerine alsınlar, vücutlarını örtsünler. Bu onların hür ve namuslu bilinmelerini ve bundan dolayı inciltilmemelerini daha iyi sağlar. Allah çok bağışlayan, çok esirgeyendir."},{"n":60,"t":"İki yüzlüler, kalplerinde fesat bulunanlar, şehirde bozguncu haberler yayanlar, eğer bundan vazgeçmezlerse, andolsun ki seni onlarla mücadeleye davet ederiz; sonra çevrende az bir zamandan fazla kalamazlar."},{"n":61,"t":"Lanetlenmiş olarak, nerede bulunurlarsa yakalanır ve öldürülürler."},{"n":62,"t":"Allah’ın geçmiş milletlere uyguladığı yasa budur ve Allah’ın yasasında bir değişme bulamazsın."},{"n":63,"t":"«Onun bilgisi Allah katındadır, ne bilirsin, belki de zaman yakındır.»"},{"n":64,"t":"Allah kafirlere lanet etmiş ve onlar için çılgın bir ateş hazırlamıştır."},{"n":65,"t":"Orada ebedi olarak kalacaklar kendilerini koruyacak ne bir dost, ne bir yardımcı bulamayacaklardır."},{"n":66,"t":"«Keşke Allah’a itaat etseydik, keşke Peygambere itaat etseydik» derler."},{"n":67,"t":"«Rabbimiz! Biz yöneticilerimize ve büyüklerimize itaat etmiştik, fakat onlar bizi yoldan saptırdılar» derler."},{"n":68,"t":"«Rabbimiz! Onlara iki kat azab ver ve onları büyük bir lanetle rahmetinden kov!»"},{"n":69,"t":"Ey inananlar! Siz de Musa’yı incitenler gibi olmayın. Allah onu, onların dedikleri şeyden temize çıkardı. O Allah’ın yanında gözde, itibarlı bir kul idi."},{"n":70,"t":"Ey inananlar! Allah’tan korkun ve doğru söz söyleyin."},{"n":71,"t":"Ki Allah işlerinizi düzeltsin ve günahlarınızı bağışlasın. Kim Allah’a ve Peygamberine itaat ederse, şüphesiz büyük bir kurtuluşa ermiş olur."},{"n":72,"t":"Biz emaneti, göklere, yere ve dağlara sunduk; onu yüklenmekten kaçındılar, sorumluluğundan korktular. Pek zalim ve cahil olan insan onu yüklendi."},{"n":73,"t":"Bunun sonucu olarak, Allah münafık erkek ve kadınlara, müşrik erkek ve kadınlara azab edecektir. Mümin erkek ve kadınların tevbelerini kabul edecektir. Allah çok bağışlayan, çok merhamet edendir."}],[{"n":1,"t":"Hamd, göklerdeki ve yeryüzündeki tüm varlıkların sahibi olan Allah’a mahsustur. Ahirette de hamd O’na mahsustur. O her işi yerinde yapar ve her şeyden haberdardır."},{"n":2,"t":"O yeraltına giren ve oradan çıkan, gökten inen ve oraya yükselen her şeyi bilir. O merhametli ve bağışlayıcıdır."},{"n":3,"t":"«Hayır, gaybın bilgisi tekelinde olan Rabb’im adına yemin ederim ki, o an mutlaka gelecektir. Göklerdeki ve yerdeki zerre kadar küçük bir nesne ya da zerrenin daha küçüğü ve daha büyüğü O’nun bilgisi dışında değildir, bunların tümü apaçık bir kitaptadır.»"},{"n":4,"t":"Amaç, iman edip iyi ameller işleyenleri ödüllendirmektir. Onları bağışlanma ve onurlu bir rızık beklemektedir."},{"n":5,"t":"Bizimle başa çıkabileceklerini sanarak olanca güçleri ile ayetlerimize karşı çıkanlara gelince; onları tiksindirici ve acıklı bir azap beklemektedir."},{"n":6,"t":"Kendilerine bilgi verilenler Rabb’in tarafından sana indirilen mesajın, insanları üstün iradeli ve övgüye lâyık Allah’ın yoluna iletici bir gerçek olduğunu görürler."},{"n":7,"t":"Kâfirler biribirlerine dediler ki; «Ölen vücutlarınız didik didik parçalanıp iyice dağıldıktan sonra yeni bir aşamada tekrar dirileceğinizi ileri süren biri var, onu size gösterelim mi?»"},{"n":8,"t":"Bu adam Allah adına yalan mı uyduruyor, yoksa deli midir? Hayır aslında ahirete inanmayanlar, koyu bir sapıklığın ve azabın pençesindedirler."},{"n":9,"t":"Onlar önlerindeki ve arkalarındaki göğü ve yeri görmüyorlar mı? Dilesek onları yerin dibine geçirir ya da göğü parçalayıp başlarına indirirdik. Allah’a bağlı her kulun bundan alacağı ders vardır."},{"n":10,"t":"Biz gerçekten Davud’a kendi katımızdan ayrıcalık sunduk. «Ey dağlar, o tesbih ettikçe siz de söylediklerini tekrarlayın. Ey kuşlar sizde» dedik. Ayrıca demiri avucunda yumuşattık."},{"n":11,"t":"Ona «İnsan vücudunu iyice saracak geniş zırhlar yap ve zırhların parçalarını biribirine ölçülü biçimde tak» dedik. Ey Davudoğulları, iyi ameller işleyiniz. Çünkü ben yaptıklarınızı görüyorum."},{"n":12,"t":"Süleyman’ın buyruğuna da rüzgârı vermiştik. Bu rüzgâr sabahleyin esince bir aylık uzaklığa gider ve akşamleyin de bir aylık mesafeyi aşarak geri gelirdi. Onun için erimiş bakırı su gibi akıttık. Rabb’inin izni ile yanında çalışan bazı cinleri de buyruğuna sunmuştuk. Bu cinlerden buyruğumuzun dışına çıkanlara kızgın alevli ateşin azabını tattırırız."},{"n":13,"t":"Onlar, Süleyman’a, isteği uyarınca mabetler, heykeller, havuz gibi geniş çanaklar ve yerlerinden kımıldatılamaz koca kazanlar yaparlardı. Ey Davudoğulları, şükrediniz. Kulların içinde şükredenler pek azdır."},{"n":14,"t":"Süleyman’ın canını aldığımızda ancak değneğini kemiren bir kurt onun öldüğünü cinlere fark ettirdi. Onun ölüsü yere düşünce belli oldu ki, eğer cin’ler gaybı bilselerdi, o onur kırıcı angaryaların sıkıntısını çekmeye devam etmezlerdi."},{"n":15,"t":"Gerçekten bir vadinin sağında ve solunda uzayan iki ovadan oluşmuş Sebe yurdundan alınacak ibret dersi vardır. Onlara «Rabb’inizin verdiği rızıkları yiyiniz ve O’na şükrediniz, işte size güzel bir ülke ve bağışlayıcı bir Rabb» dendi."},{"n":16,"t":"Fakat onlar bu buyruğa sırt çevirdiler. Bu yüzden üzerlerine Arim selini göndererek o verimli ovalarını dikenli, kuru çalılıklı ve az sayıda sedir ağaçlı iki çorak ovaya dönüştürdük."},{"n":17,"t":"Yaptıkları nankörlükten ötürü onları işte böyle cezalandırdık. Biz nankörden başkasını hiç cezalandırır mıyız ki?"},{"n":18,"t":"Onların yurtları ile kutsal kentler arasına, birinden bakınca öbürü görünebilen kısa aralıklı kentler serpiştirerek konaktan konağa mesafeleri ölçülebilir bir yolculuk yapmalarını sağladık. Onlara «Bu yol boyunca hem geceleyin hem de gündüzün güven içinde yolculuk yapın» dedik."},{"n":19,"t":"Fakat onlar «Ey Rabbimiz! Seferlerimizi uzun aralıklı yap!» diyerek kendilerine yazık ettiler. Bunun üzerine onları dillere düşürdük, toplumlarını parçalayarak öteye beriye dağıttık. Hiç kuşkusuz sabırlıların ve şükredenlerin bu olaylardan çıkaracakları bir çok dersler vardır."},{"n":20,"t":"Şeytan, onlara ilişkin beklentisini gerçekleştirmiş ve bir grup mü’min dışında hepsi ona uymuştu."},{"n":21,"t":"Aslında şeytanın onlar üzerinde hiçbir nüfuzu, hiçbir yaptırım gücü yoktu. Ama biz ahirete inananları, o konuda kuşku içinde olanlardan ayırd etmek istedik. Her şey, senin Rabb’inin gözetimi altındadır."},{"n":22,"t":"Müşriklere de ki; «Allah dışında ilâh olduklarını sandığınız putları imdada çağırınız bakalım. Onlar ne göklerde ve ne de yeryüzünde zerre kadar bir şeye sahip değildirler. Gökler ile yeryüzü üzerinde hiçbir ortaklıkları olmadığı gibi onların hiçbiri Allah’ın yardımcısı da değildir.»"},{"n":23,"t":"Allah katında O’nun izin verdiği kimseler dışında hiç kimse şefaat, aracılık edemez. Bu konuda izin bekleyenlerin yüreklerini ürperten korku yatıştırılınca biribirlerine «Rabb’iniz ne dedi?» diye sorarlar. Cevap verenler «O gerçeği söyledi, O yüce ve büyüktür» derler."},{"n":24,"t":"Ey Muhammed, müşriklere «Gerek göklerden inen ve gerekse yerden çıkan rızıkları size sunan kimdir?» diye sor. Sonra de ki; «Allah sunuyor. Öyleyse ya biz doğru yoldayız ve siz açık bir sapıklık içindesiniz, ya da bunun tersi doğrudur.»"},{"n":25,"t":"De ki; «Ne bizim suçlarımız size sorulacak ve ne de sizin işlediğiniz kötülükler bize sorulacaktır.»"},{"n":26,"t":"De ki; «Rabb’imiz bizi biraraya getirecek, sonra aramızdaki uyuşmazlıkları hak uyarınca çözecektir. O son derece âdil bir yargıç ve her şeyi bilendir.»"},{"n":27,"t":"De ki; «Allah’a koştuğunuz ortakları bana gösterin bakalım. Olacak şey değil bu. Aslında O üstün iradeli ve her işi yerinde olan Allah’dır.»"},{"n":28,"t":"Ey Muhammed, biz seni bütün insanlara müjde verici ve uyarıcı olarak gönderdik. Fakat insanların çoğu bunu bilmiyorlar."},{"n":29,"t":"Onlar «Eğer doğru söylüyorsanız, şu tehdit ne zaman gerçekleşecek?» derler."},{"n":30,"t":"Onlara de ki; «Sizin belirlenmiş bir gününüz vardır, ne bir an ertelenir ve ne de önceye alınır.»"},{"n":31,"t":"Kâfirler «Biz ne bu Kur’an’a ve ne de ondan önceki kutsal kitaplara asla inanmayız» dediler. Sen bu zalimleri bir de Rabb’lerinin huzurunda dikilmiş durumda biribirlerini suçlarken görsen! O zaman ayak takımını oluşturan güdülenler kendini beğenmiş elebaşlarına «Siz olmasaydınız, biz mü’min olacaktık» derler."},{"n":32,"t":"Kendini beğenmiş elebaşları da güdülenlere derler ki; «Size doğru yola ilişkin mesaj geldikten sonra biz mi sizleri o yoldan alıkoyduk? Aslında siz kendiniz suça girdiniz»"},{"n":33,"t":"«Tersine, işiniz gücünüz, gece gündüz komplo düzenlemek, dolap çevirmekti. Hani bize Allah’ı inkâr etmemizi, O’na eş koşmamızı emrediyordunuz.» Azabı görünce pişmanlığı yüreklerine gömdüler. Biz kâfirlerin boyunlarına demir halkalar geçiririz. Çarpıldıkları ceza sadece işledikleri kötülüklerin karşılığı değil mi?"},{"n":34,"t":"Uyarıcı gönderdiğimiz her kentin şımarık elebaşları mutlaka şöyle dediler. «Biz, sizin getirdiğiniz mesajı kesinlikle inkâr ediyoruz»"},{"n":35,"t":"Bizim herkesten çok servetimiz ve evlâdımız vardır, bizim azaba çarptırılmamız söz konusu değildir."},{"n":36,"t":"Onlara de ki; «Hiç kuşkusuz, Rabb’im dilediğine bol servet verir ve dilediğinin rızkını kısar. Fakat insanların çoğu bu gerçeği bilmezler.»"},{"n":37,"t":"Ne mallarınız ve ne de evlâtlarınız size bizim katımızda yakınlık kazandırmaz. Yalnız iman edip iyi amel işleyenler var ya, onların yaptıkları iyilikler kat kat fazlası ile ödüllendirilir. Onlar cennetin yüksek köşklerinde güven içinde ağırlanırlar."},{"n":38,"t":"Bizimle başa çıkabileceklerini sanarak olanca güçleri ile ayetlerimize karşı çıkanlara gelince onlar azapla başbaşa kalacaklardır."},{"n":39,"t":"De ki; «Hiç kuşkusuz Rabb’im dilediği kuluna bol servet verir ve dilediği kulun rızkını kısar. Siz Allah için bir şey verirseniz, O verdiğinizin boşluğunu doldurur. O rızık verenlerin en hayırlısıdır.»"},{"n":40,"t":"O gün Allah, onların hepsini diriltip bir araya getirir ve sonra meleklere «Bu adamlar size mi tapıyorlar?» der."},{"n":41,"t":"Melekler derler ki; «Seni her türlü noksanlıktan tenzih ederiz. Bizim dayanağımız, koruyucumuz onlar değil sensin. Hayır, onlar cinlere tapıyorlardı, çoğu onlara inanıyorlardı.»"},{"n":42,"t":"O zaman zalimlere deriz ki; «Bu gün biribirinize ne faydalı olabilirsiniz ve ne de zarar verebilirsiniz. Vaktiyle inkâr ettiğiniz cehennem ateşinin azabını şimdi tadınız bakalım.»"},{"n":43,"t":"Onlara apaçık anlamlı ayetlerimiz okunduğunda «Bu adamın tek istediği şey, sizi atalarınızın taptığı putlardan vazgeçirmektir» ve «şu Kur’an, düzmece bir yalandan başka bir şey değildir.» dediler. Kâfirler, kendilerine gelen ’gerçek’ için «Bu apaçık bir büyüden ibarettir.» demişlerdi."},{"n":44,"t":"Ey Muhammed, oysa biz o müşriklere daha önce okuyacakları bir Kitap vermemiş, kendilerine senden önce bir uyarıcı göndermemiştik."},{"n":45,"t":"Onlardan önceki bir çok milletler de mesajımızı yalanlamışlardı., Bu müşrikler onlara verdiğimiz dünyalıkların onda birine bile ermiş değillerdir. Buna rağmen peygamberlerimi yalanladılar, ama bu inkârcılığın karşılığı nice oldu?"},{"n":46,"t":"İkişer ikişer ve teker teker Allah ile vicdanınızla başbaşa kalınız ve düşününüz ki, bu dostunuz deli değildir, o sadece ağır bir azabın eşiğinde sizleri uyaran bir peygamberdir.»"},{"n":47,"t":"De ki; «Sizden hiçbir ücret istemiyorum. Ücretiniz sizin olsun. Benim ücretimi Allah verecektir. O her şeyin tanığıdır.»"},{"n":48,"t":"De ki; «Gaybleri çok iyi bilen Rabb’im, gerçeği eğrinin başına çarpar.»"},{"n":49,"t":"De ki; «Hak geldi, artık batıl hiçbir tarafa doğru kımıldayamaz.»"},{"n":50,"t":"De ki; «Eğer ben eğri yolda isem sapıtmamın zararını kendim çekerim. Eğer doğru yolda isem, bu Rabb’imin bana ilettiği vahiy sayesindedir. Hiç kuşkusuz O her şeyi işitir ve kullarına çok yakındır.»"},{"n":51,"t":"Onları bir de paniğe kapıldıklarında görsen! Kaçacakları hiçbir yer yok. Cehennemin yakınında yakayı ele vermişlerdir."},{"n":52,"t":"O’na inandık derler, ama artık iyice uzağında kaldıkları imanı nasıl yakalayacaklardır?"},{"n":53,"t":"Vaktiyle onu inkâr etmişlerdi, o zaman uzaktan karanlığa taş atıyorlardı."},{"n":54,"t":"Şimdi kendileri ile özlemleri arasına perde gerildi. Tıpkı daha önceki yoldaşlarına yapıldığı gibi. Hiç kuşkusuz onlar koyu bir şüphe içinde idiler."}],[{"n":1,"t":"Gökleri ve yeryüzünü yoktan var eden; iki, üç ve dört kanatlı melekleri elçi olarak görevlendiren Allah’a ham dolsun. O yaratma işleminde dilediği eklemeleri yapar. Hiç kuşkusuz O’nun gücü her şeye yeter."},{"n":2,"t":"Allah’ın insanlara açtığı bir rahmeti hiç kimse alıkoyamaz. O’nun alıkoyduğunu da O’nun dışında hiç kimse salamaz. O üstün iradelidir ve her işi yerinde yapar."},{"n":3,"t":"Ey insanlar, Allah’ın size yönelik nimetlerini hatırlayınız. Size gökten ve yeryüzünden rızık sağlayan Allah’tan başka bir yaratıcı var mı? O’ndan başka ilâh yoktur. Nasıl oluyor da bu gerçeği göz ardı ediyorsunuz?"},{"n":4,"t":"Ey Muhammed, eğer onlar seni yalanlıyorlarsa bil ki, senden önceki nice peygamberler de yalanlanmıştır. Her işin çözümü Allah’a götürülecektir."},{"n":5,"t":"Ey insanlar, Allah’ın verdiği söz gerçektir. Sakın dünya hayatı sizi aldatmasın, sakın şeytan, sizi Allah’ın affına güvendirerek ayartmasın."},{"n":6,"t":"Şeytan kesinlikle size düşmandır. Onu siz de düşman tutunuz. O taraftarlarını cehennemliklerden olmaya sürükler."},{"n":7,"t":"Kâfirler ağır bir azaba çarptırılacaktır. İman edip iyi ameller işleyenleri ise bağışlanma ve büyük ödül beklemektedir."},{"n":8,"t":"Kötü işi allandırılıp pullandırılarak gözüne güzel gösterilen kimse davranışlarını süzgeçten geçiren, gerçekçi biri gibi olur mu? Allah dilediğini saptırır, dilediğini de doğru yola iletir. Sakın onlar için hayıflanma. Hiç kuşkusuz onların neler yaptıklarını Allah iyi bilir."},{"n":9,"t":"Bulutları sürükleyen rüzgârların estiricisi Allah’dır. Biz bulutları ölü bir yöreye göndererek onlar aracılığı ile ölü toprağı diriltiriz. İşte yeniden diriliş olayı da böyledir."},{"n":10,"t":"Kim itibar ve üstünlük isterse bilsin ki, itibar ve üstünlük tümü ile Allah’ın tekelindedir. Güzel söz O’na yükselir, iyi ameli de O yükseltir. Kötü amaçlı komplolar düzenleyenler ağır bir azaba çarpılacaklardır. Ayrıca onların komplosu da boşa çıkar, verimsiz olur."},{"n":11,"t":"Allah sizi önce topraktan, sonra spermadan yarattı. Sonra erkekli dişili çiftlere dönüştürdü. O’nun bilgisi dışında hiçbir dişi ne hâmile kalabilir ve ne de doğurabilir. Ömrü uzun olanın çok yaşaması ve kısa ömürlülerin az yaşamaları kesinlikle bir kitapta kayıtlıdır. Hiç kuşkusuz bu Allah için kolay bir iştir."},{"n":12,"t":"İki deniz aynı değildir. Birinin suyu tatlı kolay içimli, öbürününki tuzlu ve acıdır. Her ikisinden de taze balık eti yer ve takı olarak kullandığınız süs eşyaları çıkarırsınız. Allah’ın size yönelik bağışını aramanız ve O’na şükretmeniz için geminin suları yararak yol aldığını görürsünüz."},{"n":13,"t":"O geceyi gündüze ve gündüzü geceye dönüştürür. Güneşi ve ayı buyruğu altına almıştır. Her biri belirli bir sürenin sonuna kadar hareket eder. İşte Rabb’iniz bu Allah’dır. Egemenlik O’nun tekelindedir. O’nu bir yana bırakarak taptığınız düzmece ilahlar bir çekirdek kabuğunun bile sahibi değildirler."},{"n":14,"t":"Eğer onları imdadınıza çağırırsanız, çağrınızı işitmezler. Sesinizi işitseler bile size karşılık veremezler. Üstelik kıyamet günü, sizin kendilerini Allah’a ortak koşmuş olmanızı reddederler. Hiç kimse, her şeyin içyüzünü bilen Allah gibi sana haber vermez."},{"n":15,"t":"Ey insanlar, siz Allah’a muhtaçsınız; oysa Allah hiç kimseye muhtaç değildir ve övgüye lâyıktır."},{"n":16,"t":"Eğer dilerse sizi yok eder ve yerinize başka bir canlı türü getirir."},{"n":17,"t":"Bunu yapmak, Allah için zor değildir."},{"n":18,"t":"Hiç kimse başkasının günahını yüklenmez. Eğer günah yükü ağır bir kimse, yükünün sırtından alınmasını istese, en yakını bile yükünün en küçük bölümünü kendi sırtına almaz. Sen sadece görmeden Rabb’lerinden korkanları ve namaz kılanları uyarabilirsin. Kim kötülüklerden arınırsa kendi yararına arınmış olur. Sonunda Allah’a dönülecektir."},{"n":19,"t":"Kör ile görebilen bir olmaz."},{"n":20,"t":"Karanlıklar ile ışık da bir olmaz."},{"n":21,"t":"Gölge ile aşırı sıcaklık da bir olmaz."},{"n":22,"t":"Diriler ile ölüler de bir değildir. Allah dilediğine ses işittirir. Fakat sen mezarlıktakilere sesini işittiremezsin."},{"n":23,"t":"Sen sadece bir uyarıcısın."},{"n":24,"t":"Biz seni gerçeğin müjdecisi ve uyarıcısı (korkutucusu) olarak gönderdik. Her millete mutlaka bir uyarıcı gönderilmiştir."},{"n":25,"t":"Eğer onlar seni yalanlıyorlarsa bil ki, daha önceki milletler de peygamberlerini yalanlamışlardı. Oysa peygamberleri onlara açık kanıtlar, kutsal sayfalar ve ışık saçan kitap getirmişlerdi."},{"n":26,"t":"Sonra ben kâfirlerin yakalarına yapıştım. Benim karşı darbem nasıl oldu?"},{"n":27,"t":"Allah’ın gökten su indirdiğini görmüyor musun? O su aracılığı ile türlü türlü renkte meyvalar yetiştirdik. Dağlarda beyaz, kırmızı, koyu siyah değişik renklerde yollar, patikalar açtık."},{"n":28,"t":"Yine böyle değişik renkte insanlar, hayvanlar ve davarlar yarattık. Allah’dan asıl korkanlar, O’nun bilgin kullarıdır. Hiç kuşkusuz Allah üstün iradeli ve bağışlayıcıdır."},{"n":29,"t":"Allah’ın kitabını okuyanlar, namazı kılanlar, kendilerine verdiğimiz rızıkların bir bölümünü gizlice ve açıkça ihtiyacı olanlara verenler, hiçbir zaman zarar etmeyecek bir ticaret yaptıklarını umabilirler."},{"n":30,"t":"Çünkü Allah onların ücretlerini eksiksiz olarak öder ve kendi bağışı olarak fazlasını verir. Hiç kuşkusuz O affedicidir, iyiliklerin karşılığını bol bol verir."},{"n":31,"t":"Ey Muhammed, sana vahiy yolu ile indirdiğimiz bu Kitap daha önceki kutsal kitapları onaylayan gerçek kitaptır. Hiç şüphesiz Allah, kullarını iyi tanır ve her şeyi görür."},{"n":32,"t":"Sonra bu Kitab’ı seçtiğimiz kullarımıza miras bıraktık. Bunların kimi kendilerine yazık eder, kiminin davranış notu ortadır, kimi de Allah’ın izni ile iyiliklerde öncüdür. İşte büyük lütuf budur."},{"n":33,"t":"Bunların mükafatı \"Adn\" cennetleridir. Oraya girerler. Orada altın bilezikler ve incilerle süslenirler. Oradaki elbiseleri de ipektir."},{"n":34,"t":"Onlar şöyle derler; «içimizdeki üzüntüyü gideren Allah’a hamd olsun. Hiç kuşkusuz Rabb’imiz affedicidir ve iyiliklerin karşılığını bol bol verir.»"},{"n":35,"t":"«O bizi lütfu ile içinde sürekli oturacağımız bir yurda yerleştirdi. Burada bize ne yorgunluk değecek ve ne de bıkkınlık ilişecektir.»"},{"n":36,"t":"Kâfiri ise cehennem ateşi beklemektedir. Ne ölümlerine karar verilir de ölürler ve ne de azapları hafifletilir. İşte biz azılı kâfirleri böyle cezalandırırız."},{"n":37,"t":"Onlar orada «Ey Rabbimiz, bizi buradan çıkar da daha önce yaptıklarımızdan farklı, iyi işler yapalım» diye feryad ederler. Düşünmek isteyenlerin düşünmelerine yetecek kadar uzun bir süre sizi yaşatmadık mı? Ayrıca size uyarıcı da gelmişti, Şimdi azabı tadınız bakalım. Zalimlere yardım eden bulunmaz."},{"n":38,"t":"Hiç kuşkusuz Allah, göklerin ve yeryüzünün \"gaybı\"nı bilir. O kalplerin özünü bilir."},{"n":39,"t":"Yeryüzünde sizleri daha önceki kuşakların yerine geçirip egemen kılan O’dur. Kâfirlerin inkârcılıkları kendi zararlarınadır. Kâfirlik, kâfirlere Rabb’leri katında sadece daha çok nefret kazandırır. Kâfirlik, kâfirlerin sadece zararlarını arttırır."},{"n":40,"t":"Ey Muhammed, müşriklere de ki; «Baksanıza, Allah’a ortak koşarak imdada çağırdığınız, O’nun dışındaki düzmece ilahlarınız var ya. Onların yeryüzünde neyin yaratıcıları olduklarını bana göstersenize. Yoksa onların göklerin yaratılmasında payları, katkıları mı var? Yoksa onlara bir kitap indirdik de ondaki kanıtlara mı dayanıyorlar?» Hayır, o putperest zalimler birbirlerini sadece asılsız vaadlerle aldatıyorlar."},{"n":41,"t":"Gökleri ve yer yuvarlağını dengede tutarak yörüngelerinden çıkmalarını önleyen sadece Allah’dır. Eğer onlar yörüngelerinden çıkacak olsalar onları O’ndan başka hiç kimse dengeye getiremez. Hiç kuşkusuz O, hoşgörülü ve bağışlayıcıdır."},{"n":42,"t":"Onlar, Allah kendilerine uyarıcı gönderdiği taktirde herhangi bir milletten daha sıkı biçimde doğru yola bağlanacaklarına dair kesin bir dille Allah adına yemin etmişlerdi. Fakat kendilerine uyarıcı gelince bu olay nefretlerini arttırmaktan başka bir işe yaramadı."},{"n":43,"t":"Bu nefretlerinin sebebi yeryüzünde büyüklük taslamaları ve kötü niyetli komplolar kurmalarıdır. Oysa kötü niyetli komplolar, sadece düzenleyicilerini tuzağa düşürür. Onlar daha önceki yoldaşları hakkında işleyen yasalardan başka bir akıbet mi bekliyorlar? Allah’ın yasasının değiştiğini göremezsin. Allah’ın yasasında herhangi bir sapma göremezsin."},{"n":44,"t":"Onlar yeryüzünü gezip daha önceki yoldaşlarının karşılaştıkları acı sonu görmezler mi? Oysa onlar kendilerinden daha güçlü idiler. Göklerde ve yeryüzünde Allah ile başa çıkabilecek hiçbir güç yoktur. Hiç kuşkusuz O her şeyi bilir ve gücü her şeye yeter."},{"n":45,"t":"Eğer Allah, insanların davranışlarının cezasını hemen verseydi yeryüzünde hiçbir canlı yaratık bırakmazdı. Fakat O, onları belirli bir sürenin sonuna kadar erteliyor. Söz konusu süreleri dolunca, kuşku yok ki, Allah kullarının durumunu görmektedir."}],[{"n":1,"t":"Yasin."},{"n":2,"t":"Hikmetli Kur’an’a andolsun."},{"n":3,"t":"Sen elbette gönderilmiş peygamberlerdensin."},{"n":4,"t":"Dosdoğru bir yol üzerinde."},{"n":5,"t":"Bu Kur’an üstün ve çok merhametli Allah tarafından indirilmiştir."},{"n":6,"t":"O Kitap, sana, ataları uyarılmamış, bu yüzden kendileri de gaflet içinde kalmış bir toplumu uyarman için indirilmiştir."},{"n":7,"t":"Andolsun ki, hüküm çoğunun aleyhine gerçekleşmiştir, bunun için artık inanmazlar."},{"n":8,"t":"Biz onların boyunlarına halkalar geçirdik. Çenelere kadar dayanan o halkalar yüzünden kafaları kalkıktır."},{"n":9,"t":"Önlerine ve arkalarına set çektik. Gözlerini perdelediğimizden artık göremezler."},{"n":10,"t":"Onları uyarsan da uyarmasan da onlar için birdir, inanmazlar."},{"n":11,"t":"Sen ancak zikre (Kur’an’a) uyan ve görmeden Rahman’dan korkan kimseyi uyarabilirsin. İşte öylesini bir mağfiret ve güzel bir mükâfatla müjdele."},{"n":12,"t":"Biziz, biz ki, ölüleri diriltiriz ve öne sürdükleri işleri ve bıraktıkları eserleri yazarız. Biz; her şeyi, apaçık bir Kitab’a yazmışızdır."},{"n":13,"t":"İnsanlara, elçilerin geldiği şu kent halkını misal olarak anlat."},{"n":14,"t":"Biz onlara iki elçi gönderdik, onları yalanladılar, biz de elçileri üçüncü biriyle destekledik. Onlar «biz size gönderilen elçileriz» dediler."},{"n":15,"t":"Kentliler dediler ki; «siz de bizim gibi insansınız. Rahman’da bir şey indirmemiştir. Siz sadece yalan söylüyorsunuz.»"},{"n":16,"t":"Elçiler dediler ki; «Rabb’imiz bilir ki, biz size gönderilmiş elçileriz.»"},{"n":17,"t":"Bizim üzerimize düşen, yalnızca açıkça duyurmaktır."},{"n":18,"t":"Kentliler dediler ki; «doğrusu biz sizin yüzünüzden uğursuzluğa uğradık. Eğer bu işten vazgeçmezseniz sizi mutlaka taşlarız ve bizden size acı bir azab dokunur.»"},{"n":19,"t":"Elçiler dediler ki; «uğursuzluk kendinizdendir. Bu uğursuzluk size öğüt verildiği için mi oldu? Hayır, siz aşırı giden bir kavimsiniz.»"},{"n":20,"t":"«Ey kavmim, elçilere uyun» dedi."},{"n":21,"t":"Sizden bir ücret istemeyenlere uyun, onlar doğru yoldadırlar."},{"n":22,"t":"Ben niçin beni yaratana kulluk etmeyeyim? Sizde O’na döndürüleceksiniz."},{"n":23,"t":"Onu bırakıp da tanrılar edinir miyim? Eğer rahman olan Allah bana bir zarar vermek isterse, o tanrıların şefaati bana hiçbir fayda sağlamaz ve onlar beni kurtaramazlar."},{"n":24,"t":"O takdirde apaçık bir sapıklık içinde olurum."},{"n":25,"t":"Şüphesiz ben Rabb’inize inandım, beni dinleyin."},{"n":26,"t":"O’na «cennete gir» denilince «Keşke kavmim bilseydi.»"},{"n":27,"t":"Rabb’imin beni bağışladığını ve beni ikram edilenlerden kıldığını dedi."},{"n":28,"t":"Ondan sonra, kavminin üzerine gökten bir ordu indirmedik, zaten indirecek te değildik."},{"n":29,"t":"Sadece korkunç bir ses oldu, hemen sönüp gittiler."},{"n":30,"t":"Yazık şu kullara! Kendilerine hangi elçi gelse, onu alaya alıyorlardı."},{"n":31,"t":"Görmediler mi kendilerinden önce nice nesilleri yok ettik. Onlar bir daha kendilerine dönüp gelmezler."},{"n":32,"t":"Hepsi toplandığı zaman huzurumuza getirileceklerdir."},{"n":33,"t":"Ölü toprak onlar için bir delildir. Biz onu dirilttik, ondan taneler çıkarırız da ondan yerler."},{"n":34,"t":"Orada hurma ve üzüm bahçeleri yarattık; orada çeşmeler akıttık."},{"n":35,"t":"Ki, onun ürününden ve ellerinin emeğinden yesinler. Hala şükretmiyorlar mı?"},{"n":36,"t":"Allah ne yücedir ki, toprağın bitirdiklerinden, kendilerinden ve daha bilmedikleri nice şeylerden olan bütün çiftleri yaratmıştır."},{"n":37,"t":"Gecede onlar için bir delildir. Gündüzü ondan soyup alırız, birden onlar karanlıkta kalıverirler."},{"n":38,"t":"Güneş’te yörüngesinde akıp gitmektedir. Bu, üstün ve bilen Allah’ın kanunudur."},{"n":39,"t":"Ay içinde bir takım yörüngeler tayin ettik. Nihayet o eğri hurma dalı gibi hilal olur da geri döner."},{"n":40,"t":"Ne güneş aya erişebilir, ne de gece gündüzün önüne geçebilir. Hepsi belli bir yörüngede (felekte) yüzmektedirler."},{"n":41,"t":"Onlar için bir delil de, onların çocuklarını dolu gemide taşımamız."},{"n":42,"t":"Ve kendilerine onun gibi binecekleri nice şeyler yaratmamızdır."},{"n":43,"t":"Dilersek, onları suda boğardık; ne yardımlarına koşan bulunur ve ne de kendileri kurtulabilirdi."},{"n":44,"t":"Ancak bizden bir rahmet ve belli bir süreye kadar yaşatma vardır."},{"n":45,"t":"Onlara; «geçmişinizden ve geleceğinizden sakının, belki esirgenmeniz umulur» dendiği zaman yüz çevirirler."},{"n":46,"t":"Zaten Rabb’inin ayetlerinden herhangi biri kendilerine geldiğinde onlardan hep yüz çevire gelmişlerdir."},{"n":47,"t":"Onlara; «Allah’ın size verdiği rızıktan sarf edin» denilince inkâr edenler inananlara; «Allah dileseydi, doyurabileceği bir kimseyi biz mi doyuralım? Siz gerçekten sapıtmış kimselersiniz?»"},{"n":48,"t":"Ve «eğer doğru söylüyorsanız bu tehdit ettiğiniz azab ne zaman gelecek» diyorlar."},{"n":49,"t":"Onlar tek bir çığlıktan başka bir şey beklemiyorlar. Onlar birbirleriyle çekişip dururlarken o kendilerini yakalar."},{"n":50,"t":"O zaman, artık ne vasiyet edebilirler ne de ailelerine dönebilirler."},{"n":51,"t":"Sur’a üflenince, kâbirlerinden Rabb’lerine koşarak çıkarlar."},{"n":52,"t":"Dediler; «vah bize, bizi yattığımız yerden kim kaldırdı? İşte Rahman’ın vadettiği şey budur. Demek peygamber doğru söylemiş.»"},{"n":53,"t":"Sadece bir tek nara olur, hemen onların hepsi huzurumuza getirilirler."},{"n":54,"t":"O gün, hiç kimseye bir haksızlık yapılmaz ve siz ancak yaptığınızın cezasını çekersiniz."},{"n":55,"t":"Doğrusu bugün, cennetlikler eğlence ile meşguldürler."},{"n":56,"t":"Kendileri ve eşleri gölgelerde, koltuklara yaslanmışlar."},{"n":57,"t":"Orada her çeşit meyve onlar içindir. Bütün arzuları yerine getirilir."},{"n":58,"t":"Merhametli olan Rabb katından onlara selâm vardır."},{"n":59,"t":"Ey suçlular, bugün şöyle ayrılın."},{"n":60,"t":"Ey insanoğulları, size and vermedim mi? Şeytana tapmayın o sizin apaçık düşmanınızdır."},{"n":61,"t":"Bana tapın doğru yol budur."},{"n":62,"t":"Andolsun ki, o sizden nice nesilleri saptırmıştır, akletmez misiniz?"},{"n":63,"t":"İşte bu, size vaad edilen cehennemdir."},{"n":64,"t":"\"İnkârınız sebebiyle bugün oraya giriniz.\""},{"n":65,"t":"O gün ağızlarını mühürleriz, elleri bize söyler ayakları yaptıklarına şahitlik eder."},{"n":66,"t":"Dilersek, gözlerini kör ederdik de, yol bulmaya çalışırlardı. Nasıl görebilirlerdi?"},{"n":67,"t":"Dileseydik kılıklarını değiştirip onları oldukları yerde dondururduk, ne ileri gidebilir, ne de geri dönebilirdi."},{"n":68,"t":"Kime uzun ömür versek, onun yaratılışı baş aşağı çevirir, gücünü azaltırız, sonunda ihtiyarlar, zayıflar. Akıllarını kullanmıyorlar mı?"},{"n":69,"t":"Biz Muhammed’e şiir öğretmedik, zaten ona gerekmezdi. Bu bir öğüt ve apaçık Kur’an’dır."},{"n":70,"t":"Diri olanları uyarsın ve inkâr edenlere de azab hak olsun."},{"n":71,"t":"Kudretimizle kendileri için hayvanlar yarattığımızı görmezler mi? Onlara sahip olmaktadırlar."},{"n":72,"t":"Bu hayvanları onların emrine verdik. Onların bir kısmını binek olarak kullanırlar, bir kısmını da gıda olarak yerler."},{"n":73,"t":"Onlarda daha nice faydalar, içecekler vardır. Şükretmezler mi?"},{"n":74,"t":"Belki kendilerine yardım edilir diye Allah’dan başka tanrılar edindiler."},{"n":75,"t":"Oysa onlar yardım edemezler, ancak kendileri o tanrılara koruyuculuk için nöbet beklerler."},{"n":76,"t":"Onların sözü seni üzmesin. Biz onların gizlediklerini de açığa vurduklarını da biliyoruz."},{"n":77,"t":"İnsan, bizim kendisini nasıl bir nutfeden (sperm) yarattığımızı görmedi mi? Ki, şimdi apaçık bir hasım kesildi."},{"n":78,"t":"Kendi yaratılışını unutarak «çürümüş kemikleri kim yaratacak?» diyerek bize misal vermeye kalkar."},{"n":79,"t":"De ki; «Onları ilk defa yaratan diriltecek. O, her yaratmayı bilir.»"},{"n":80,"t":"O size yeşil ağaçtan ateş yaptı da siz ondan yakıyorsunuz."},{"n":81,"t":"Gökleri ve yeri yaratan, onların benzerlerini yaratamaz mı? Elbette yaratır. O, çok bilen yaratıcıdır."},{"n":82,"t":"Bir şey dilediği zaman. O’nun buyruğu sadece, o şeye «Ol» demektir, hemen olur."},{"n":83,"t":"Her şeyin hükümranlığı elinde olan ve sizin de kendisine döneceğiniz Allah münezzehtir."}],[{"n":1,"t":"Andolsun sıra sıra duranlara"},{"n":2,"t":"Önlerindekini sürdükçe sürenlere"},{"n":3,"t":"Zikir okuyanlara"},{"n":4,"t":"Ki, ilahınız birdir."},{"n":5,"t":"Göklerin, yerin ve ikisi arasında bulunanların Rabb’idir. Doğuların da Rabb’idir."},{"n":6,"t":"Bize en yakın göğü, bir süsle ve yıldızlarla süsledik."},{"n":7,"t":"Ve onu itaat etmeyen her şeytandan koruduk."},{"n":8,"t":"O şeytanlar, yüce alemi (Mele-i A’la’yı) dinleyemezler; her yandan kendilerine mermi gibi yıldızlar atılır."},{"n":9,"t":"Kovulup atılırlar. Ve onlar için sürekli azap vardır."},{"n":10,"t":"Ancak meleklerin konuşmalarından bir sözü kapan olursa, onu da delen ve yakan alevli yıldızlar takip eder."},{"n":11,"t":"Şimdi sor onlara; «Kendilerini yaratmak mı daha zordur, yoksa, Bizim yarattıklarımız mı?» Aslında biz kendilerini özlü ve yapışkan çamurdan yarattık."},{"n":12,"t":"Ey Muhammed! Evet; sen onlara şaşıyorsun, onlar da seninle alay ediyorlar."},{"n":13,"t":"Onlara öğüt verildiği vakit düşünüp öğüt almazlar."},{"n":14,"t":"Bir mucize görseler onunla alay ederler."},{"n":15,"t":"«Bu apaçık büyüdür» derler."},{"n":16,"t":"Yani biz öldüğümüz, toprak ve kemik olduğumuz zaman mı dirilecekmişiz?"},{"n":17,"t":"Bizden önceki atalarımızda mı dirilecek?"},{"n":18,"t":"De ki; «Evet, hem de hor ve hakir olarak dirileceksiniz.»"},{"n":19,"t":"O dirilme sahnesi korkunç bir çığlıktan ibarettir. Hemen o anda gözlerini birdenbire açıp etrafa bakacaklar."},{"n":20,"t":"«Vah bize, bu ceza günüdür» derler."},{"n":21,"t":"Onlara «İşte bu yalanladığınız hüküm günüdür» denir."},{"n":22,"t":"«Zalimleri, onların aynı yoldaki arkadaşlarını ve taptıklarını"},{"n":23,"t":"Allah’dan başka (taptıklarına) onlara cehennemin yolunu gösterin."},{"n":24,"t":"Durdurun onları, çünkü onlar sorguya çekileceklerdir."},{"n":25,"t":"«Size ne oldu ki, birbirinizle yardımlaşmıyorsunuz?»"},{"n":26,"t":"Hayır; bugün onların hepsi teslim olmuşlardır."},{"n":27,"t":"Onlardan kimi kimine yönelip birbirini mesul tutmaya kalkışırlar."},{"n":28,"t":"«Doğrusu siz bize sağdan gelirdiniz» derler."},{"n":29,"t":"«Hayır; siz inanmış kimseler değildiniz.»"},{"n":30,"t":"«Ve bizim size karşı bir hakimiyetimiz de yoktu. Bilakis siz azgınlar güruhu idiniz.»"},{"n":31,"t":"«Bu sebeple, Rabbimizin sözü hepimizin üzerine hak olmuştur. Şüphesiz azabı tadacağız.»"},{"n":32,"t":"«Çünkü biz sizi baştan çıkardık. Zira biz de azgın kimselerdik.»"},{"n":33,"t":"O gün hepsi azapta birleşirler."},{"n":34,"t":"İşte biz, suçlulara böyle yaparız."},{"n":35,"t":"Çünkü onlara ’Allah’dan başka ilah yoktur’ denildiği zaman büyüklük taslarlardı."},{"n":36,"t":"Deli bir şair için tanrılarımızı mı bırakalım? derlerdi."},{"n":37,"t":"Hayır! O gerçeği getirmiş ve peygamberleri de doğrulamıştı."},{"n":38,"t":"Şüphesiz siz can yakıcı azabı tadacaksınız."},{"n":39,"t":"Sadece yaptığınız işlerle cezalandırılıyorsunuz."},{"n":40,"t":"Ancak Allah’a gönülden bağlı kulları bu cezanın dışındadır."},{"n":41,"t":"Onlar için bilinen rızık vardır."},{"n":42,"t":"Çeşit çeşit meyveler vardır."},{"n":43,"t":"Nimet cennetlerinde."},{"n":44,"t":"Tahtlar üzerinde karşılıklı otururlar."},{"n":45,"t":"Önlerinden akan kaynaktan doldurulmuş kadehler dolaştırılır."},{"n":46,"t":"Berraktır, içenlere lezzet veren bir içki."},{"n":47,"t":"O içkide ne sersemletme var, ne de onunla sarhoş olurlar."},{"n":48,"t":"Yanlarında da bakışlarını yalnız kendisine çevirmiş iri gözlü eşler vardır."},{"n":49,"t":"Saklı yumurtalar gibi bembeyaz eşler."},{"n":50,"t":"Cennet ehli birbirine dönmüş sorarlar."},{"n":51,"t":"«Benim de bir arkadaşım vardı.»"},{"n":52,"t":"Bana «Sende mi doğrulayanlardansın?»"},{"n":53,"t":"Biz ölüp toprak ve kemik olduğumuz zaman mı dirilip yaptığımız işlere göre cezalanacağız?"},{"n":54,"t":"Yanındakilere; «Siz onu bilir misiniz?» der."},{"n":55,"t":"Bir bakar, onu cehennemin ortasında görür."},{"n":56,"t":"Ona der ki; «Yemin ederim ki, sen az daha beni helâk edecektin."},{"n":57,"t":"Rabb’imin lütfu olmasaydı şimdi ben de cehenneme götürülürdüm» dedi."},{"n":58,"t":"«Biz bir daha ölmeyecek miyiz?» der."},{"n":59,"t":"İlk ölümümüzden başka ölüm yok ve biz azaba da uğramayacağız ha!"},{"n":60,"t":"İşte büyük başarı ve mutluluk budur."},{"n":61,"t":"Çalışanlar bunun için çalışsınlar."},{"n":62,"t":"Cennet gibi konak mı hayırlı, yoksa zakkum ağacı mı?"},{"n":63,"t":"Biz, o ağacı zalimler için fitne yaptık."},{"n":64,"t":"O, cehennemin dibinde çıkan bir ağaçtır."},{"n":65,"t":"Tomurcukları, şeytanın başı gibidir."},{"n":66,"t":"İşte cehennemlikler bundan yer ve karınlarını bununla doldururlar."},{"n":67,"t":"Sonra, bu yemeğin üzerine kaynar su katılmış içki onlar içindir."},{"n":68,"t":"Sonra dönüşleri yine cehennemedir."},{"n":69,"t":"Çünkü onlar atalarını sapık yolda buldular."},{"n":70,"t":"Öyle iken yine de düşünmeden atalarının peşinden koşuyorlardı."},{"n":71,"t":"Andolsun onlardan öncekilerinin çoğu da sapmıştır."},{"n":72,"t":"Biz onların içine de uyarıcılar göndermiştik."},{"n":73,"t":"Bak, o uyarılanların sonu nice oldu."},{"n":74,"t":"Ancak, Allah’a gönülden bağlı kullar o azabın dışında kaldı."},{"n":75,"t":"Andolsun Nuh bize dua etmişti de ne güzel kabul etmiştik."},{"n":76,"t":"Onu ve ailesini büyük sıkıntıdan kurtarmıştık."},{"n":77,"t":"Ancak O’nun soyunu sürekli kıldık."},{"n":78,"t":"Sonra gelenler arasında O’na iyi bir ün bıraktık."},{"n":79,"t":"Alemler içinde Nuh’a selâm olsun."},{"n":80,"t":"İşte biz güzel davrananları böyle mükafatlandırırız."},{"n":81,"t":"Çünkü O bizim, inanan kullarımızdandı."},{"n":82,"t":"Sonra ötekileri (inanmayanları) suda boğduk."},{"n":83,"t":"İbrahim de Nuh’un milletindendi."},{"n":84,"t":"Çünkü tertemiz bir kalp ile Rabb’ine gelmişti."},{"n":85,"t":"«Neye tapıyorsunuz?» demişti."},{"n":86,"t":"Allah’dan başka uydurma tanrılar mı istiyorsunuz?"},{"n":87,"t":"Alemlerin Rabb’i hakkındaki düşünceniz, zannınız nedir?"},{"n":88,"t":"İbrahim yıldızlara bir baktı."},{"n":89,"t":"Ben hastayım dedi."},{"n":90,"t":"Bunun üzerine onun yanından kaçtılar."},{"n":91,"t":"İbrahim de; gizlice onların tanrılarına sokuldu. «Size sundukları yiyecekleri yemiyor musunuz?»"},{"n":92,"t":"Neyiniz var konuşamıyor musunuz? dedi."},{"n":93,"t":"Ve gizlice üzerlerine yürüyüp sağ eliyle putlara kuvvetli bir darbe indirdi."},{"n":94,"t":"Bunun üzerine puta tapanlar koşarak İbrahim’in yanına geldiler."},{"n":95,"t":"İbrahim onlara «Elinizle yonttuğunuz şeylere mi tapıyorsunuz?»"},{"n":96,"t":"Oysa sizi de, yaptığınız bu şeyleri de Allah yaratmıştır dedi."},{"n":97,"t":"«Onun için bir bina yapın da onu ateşe atın» dediler."},{"n":98,"t":"İbrahim’e bir tuzak kurmak istediler, biz de onların tuzaklarını boşa çıkardık, onları alçalttık."},{"n":99,"t":"«Ben Rabb’ime gidiyorum, O beni doğru yola iletecek.»"},{"n":100,"t":"Rabb’im bana iyilerden olacak bir çocuk ver."},{"n":101,"t":"Biz ona yumuşak huylu bir erkek çocuk müjdeledik."},{"n":102,"t":"Çocuk onun yanında koşma yaşına gelince ona; «Yavrum! Ben uykuda iken seni kestiğimi görüyorum, bir düşün ne dersin? Çocuk; «Babacığım sana emredileni yap, inşaallah beni sabredenlerden bulacaksın» dedi."},{"n":103,"t":"İkisi de Allah’a teslimiyet gösterip babası, oğlunu alnı üzerine yere yatırınca."},{"n":104,"t":"Biz ona «Ey İbrahim» diye seslendik."},{"n":105,"t":"Sen rüyayı doğruladın; biz güzel davrananları böyle mükafatlandırırız."},{"n":106,"t":"Gerçekten bu apaçık bir imtihan idi."},{"n":107,"t":"Ona fidye olarak büyük bir kurban verdik."},{"n":108,"t":"Sonra gelenler arasında ona iyi bir ün bıraktık."},{"n":109,"t":"İbrahim’e selâm olsun."},{"n":110,"t":"İşte biz güzel davrananları böyle mükafatlandırırız."},{"n":111,"t":"Çünkü o bizim mü’min kullarımızdandı."},{"n":112,"t":"Biz ona iyilerden bir peygamber olacak İshak’ı müjdeledik."},{"n":113,"t":"Kendisini ve İshak’ı kutlu ve bereketli kıldık. Her ikisinin neslinden iyi kimseler olacağı gibi, açıkça kendisine zulmeden de olacaktır."},{"n":114,"t":"Andolsun Musa’ya ve Harun’a da lütuflarda bulunduk."},{"n":115,"t":"Onları ve kavimlerini büyük sıkıntılardan kurtardık."},{"n":116,"t":"Onlara yardım ettik de üstün geldiler."},{"n":117,"t":"Onlara, apaçık anlaşılan bir Kitap vermiştik."},{"n":118,"t":"Ve onları doğru yola ilettik."},{"n":119,"t":"Sonra gelenler arasında onlara iyi bir ün bıraktık."},{"n":120,"t":"Musa’ya ve Harun’a bizden selâm olsun."},{"n":121,"t":"İşte biz güzel davrananları böyle mükafatlandırırız."},{"n":122,"t":"Çünkü onların ikisi de bizim mü’min kullarımızdı."},{"n":123,"t":"İlyas da peygamberlerdendir."},{"n":124,"t":"Kavmine demişti ki; «Allah’ın azabından korkmaz mısınız?"},{"n":125,"t":"Yaratanların en güzeli olan Allah’ı bırakıp da Ba’l putuna mı tapıyorsunuz?"},{"n":126,"t":"Sizin ve babalarınızın Rabb’i olan Allah’ı terk mi ediyorsunuz?»"},{"n":127,"t":"Onu yalanladılar, bunun üzerine hepsi cehenneme götürülecekler."},{"n":128,"t":"Yalnız Allah’a gönülden bağlı kulları bunun dışındadır."},{"n":129,"t":"Sonra gelenler arasında ona iyi bir ün bıraktık."},{"n":130,"t":"İlyas’a selâm olsun."},{"n":131,"t":"İşte biz güzel davrananları böyle mükafatlandırırız."},{"n":132,"t":"Çünkü O bizim mü’min kullarımızdandı."},{"n":133,"t":"Lût da gönderilen peygamberlerdendi."},{"n":134,"t":"Onu ve ailesini kurtardık."},{"n":135,"t":"Yalnız azaba uğrayanlar arasında kalan ihtiyar bir kadın hariç."},{"n":136,"t":"Sonra diğerlerini yok etmiştik."},{"n":137,"t":"Ey insanlar! Sabahleyin onların yanından geçip gidiyorsunuz."},{"n":138,"t":"Ve geceleyin. Düşünmüyor musunuz?"},{"n":139,"t":"Yunus da gönderilen peygamberlerdendi."},{"n":140,"t":"Dolu bir gemiye kaçmıştı."},{"n":141,"t":"Gemide olanlar arasında kura çekilmişti de yenilenlerden olmuştu, bu sebepten denize atılmıştı."},{"n":142,"t":"Yunus kendini kınarken, balık onu yutmuştu."},{"n":143,"t":"Eğer Allah’ı tesbih edenlerden olmasaydı."},{"n":144,"t":"İnsanların yeniden dirileceği güne kadar balığın karnında kalırdı."},{"n":145,"t":"Biz de onu halsiz bir durumda ağaçsız çıplak bir yere attık."},{"n":146,"t":"Üzerine gölge yapması için geniş yapraklı bitki yetiştirdik."},{"n":147,"t":"Ve onu yüz bin insan ya da daha çok kişiye peygamber olarak gönderdik."},{"n":148,"t":"İnandılar, biz de onları belli bir süreye kadar geçindirdik."},{"n":149,"t":"Ey Muhammed! Putperestlere sor bakalım kızlar Rabb’inin de erkekler onların mı?"},{"n":150,"t":"Yoksa biz melekleri kız olarak yaratırken onlar yanında mıydı?"},{"n":151,"t":"Dikkat edin, onlar iftiraları yüzünden diyorlar ki:"},{"n":152,"t":"Allah doğurdu onlar elbette yalancıdırlar."},{"n":153,"t":"Allah, kızları oğullara tercih mi etmiş?"},{"n":154,"t":"Ne oluyorsunuz? Ne biçim hükmediyorsunuz?"},{"n":155,"t":"Hiç mi düşünmüyorsunuz?"},{"n":156,"t":"Yoksa sizin açık deliliniz mi var?"},{"n":157,"t":"Eğer doğru iseniz kitabınızı getirin."},{"n":158,"t":"Allah’la cinler arasında soy bağı uydurdular. Andolsun cinler de, kendilerinin hesap yerine götürüleceklerini bilirler."},{"n":159,"t":"Haşa! Allah, onların taktıkları sıfatlardan münezzehtir."},{"n":160,"t":"Allah’a gönülden bağlı kullar, bunların dışındadır."},{"n":161,"t":"Ey inkârcılar! Ne siz ne de taptıklarınız."},{"n":162,"t":"Kimseyi Allah’a karşı kandırıp yoldan çıkaramazsınız."},{"n":163,"t":"Ancak cehenneme girecek olanları kandırırsınız."},{"n":164,"t":"«Bizim içimizden herkesin belli makamı vardır.»"},{"n":165,"t":"Şüphesiz biz sıra sıra duranlarız."},{"n":166,"t":"Allah’ı tesbih edenleriz."},{"n":167,"t":"Putperestler şöyle diyorlardı."},{"n":168,"t":"Eğer yanımızda evvelkilere gelen bir uyarı kitabı olsaydı."},{"n":169,"t":"Elbette biz Allah’ın temiz kulları olurduk."},{"n":170,"t":"Ancak o uyarıyı inkâr ettiler, yakında inkârlarının sonucunu bileceklerdir."},{"n":171,"t":"Andolsun ki, peygamber kullarımıza şu sözleri vermişizdir."},{"n":172,"t":"Mutlaka kendilerine yardım edilecektir."},{"n":173,"t":"Ve galip gelecek olanlar, mutlaka bizim ordumuzdur."},{"n":174,"t":"Ey Muhammed! Bir süreye kadar onlardan yüz çevir."},{"n":175,"t":"Onlara inecek azabı gözetle, onlar da göreceklerdir."},{"n":176,"t":"Azabımıza uğramakta acele mi ediyorlar?"},{"n":177,"t":"Fakat o azap yurtlarına indiği vakit uyarılmış olanların hali ne kötü olur!"},{"n":178,"t":"Bir süreye kadar onları kendi hallerine bırak."},{"n":179,"t":"Ve bekle de gör, onlar da göreceklerdir."},{"n":180,"t":"Kudret ve şeref sahibi Rabb’in, onların taktıkları sıfatlardan münezzehtir, yücedir."},{"n":181,"t":"Selâm gönderilen peygamberlere."},{"n":182,"t":"Hamd, alemlerin Rabb’i Allah’a!"}],[{"n":1,"t":"Sad, zikir sahibi, şanlı Kur’an’a and olsun ki."},{"n":2,"t":"İnkâr edenler bir gurur ve ayrılık içindedirler."},{"n":3,"t":"Onlardan önce nice nesilleri helak ettik de feryad ettiler. Oysa artık kurtuluş zamanı değildi."},{"n":4,"t":"Aralarından bir uyarıcı gelmesine şaşırdılar. İnkârcılar; «bu yalancı bir sihirbazdır» dediler."},{"n":5,"t":"Tanrıları bir tek tanrı mı yapıyor? Bu, cidden tuhaf bir şeydir."},{"n":6,"t":"Onlardan ileri gelenler; «yürüyün, tanrılarınıza bağlılıkta direnin, sizden istenen şüphesiz budur.»"},{"n":7,"t":"Biz bunun söylediğini babalarımızın bağlı olduğu son dinde de işitmedik. Bu uydurmadan başka bir şey değildir."},{"n":8,"t":"Kur’an, aramızda O’na mı indirilmeliydi?» dediler. Doğrusu bunlar Kur’an hakkında şüphe içindedirler. Hayır, onlar azabımı henüz tadmadılar.»"},{"n":9,"t":"Yoksa, güçlü ve çok ihsan sahibi olan Rabb’inin rahmet hazineleri, onların yanında mıdır?"},{"n":10,"t":"Yahut, göklerin, yerin ve ikisi arasında bulunanların hükümranlığı, onların elinde midir? Öyle ise sebeplere sarılıp ta göğe yükselsinler (de hükümranlığı ele geçirsinler bakalım)."},{"n":11,"t":"Onlar derme çatma hiziplerden meydana gelmiş ordudur ki, işte şurada bozguna uğratılmışlardır."},{"n":12,"t":"Onlardan önce de Nuh kavmi, Ad kavmi ve sarsılmaz bir saltanat sahibi Firavun’da yalanlamıştı."},{"n":13,"t":"Semud kavmi, Lut kavmi ve Eyke halkı da yalanlamıştı. İşte bunlar da peygamberlerine karşı birleşen kabilelerdir."},{"n":14,"t":"Hepsi peygamberleri yalanladılar da azabımı hak ettiler."},{"n":15,"t":"Bunlar da ancak, bir an gecikmesi olmayan tek bir çığlık beklemektedirler."},{"n":16,"t":"İnkârcılar ise dediler ki; «Rabb’imiz! Bizim azab payımızı hesap gününden önce ver.»"},{"n":17,"t":"Ey Muhammed! Onların söylediklerine sabret, kulumuz, Davut’u an. Çünkü o daima Allah’a yönelirdi."},{"n":18,"t":"Biz dağları onun emrine verdik. Sabah akşam onunla beraber tesbih ederler."},{"n":19,"t":"Her taraftan toplanıp gelen kuşları da onun buyruğu altına vermiştik. Her biri ona yönelmekteydi."},{"n":20,"t":"O’nun hükümranlığını kuvvetlendirmiş, O’na hikmet ve açık, güzel konuşma yeteneği vermiştik."},{"n":21,"t":"Sana davacılarının haberi geldi mi? Hani odasının duvarına tırmanmışlardı."},{"n":22,"t":"Hani Davud’un yanına girmişlerdi de, Davud onlardan korkmuştu. «Korkma dediler, biz iki davacıyız. Birimiz ötekinin hakkına saldırdı. Şimdi sen aramızda hak ile hükmet, adaletten ayrılıp bize zulmetme, bizi doğru yola çıkar.»"},{"n":23,"t":"Bu kardeşimin doksandokuz dişi koyunu var. Benim ise bir tek dişi koyunum var. Böyle iken onu da bana ver dedi ve tartışmada beni yendi."},{"n":24,"t":"«And olsun ki, senin dişi koyununu kendi dişi koyunlarına katmak istemekle, sana büyük haksızlık etmiştir. Doğrusu ortakların çoğu birbirlerinin haklarına tecavüz ederler. İnanıp yararlı iyi iş yapanlar bunun dışındadır ki, sayıları ne kadar azdır.» demişti. Davud kendisini denediğimizi sanmıştı da, Rabb’inden mağfiret dileyerek eğilip secdeye kapanmış, tevbe etmiş, Allah’a yönelmişti."},{"n":25,"t":"Böylece onu bağışladık. Yanımızda onun yüksek bir makamı ve güzel bir geleceği vardır."},{"n":26,"t":"Ey Davud! Biz seni yeryüzünde hükümdar yaptık. İnsanlar arasında adaletle hükmet, keyfine uyma, sonra bu seni Allah’ın yolundan saptırır. Allah’ın yolundan sapanlara, hesap gününü unuttuklarından dolayı çetin azab vardır."},{"n":27,"t":"Göğü, yeri ve ikisi arasında bulunanları boşuna yaratmadık, inkâr edenler, kainatın boş bir tesadüf eseri olduğunu söylerler, bu onların zannıdır. Vay ateşe uğrayacak inkârcıların haline."},{"n":28,"t":"Yoksa biz iman edip de güzel amel ve hareket edenleri yeryüzünde fesat çıkaranlar gibi mi tutacağız? Yahut Allah’tan korkanları doğru yoldan sapanlar gibi mi sayacağız?"},{"n":29,"t":"Bu, sana indirdiğimiz Kur’ân, hayrı öğreten, insanlara faydalı mübarek bir kitaptır. Akıl ve vicdan sahipleri âyetlerini ciddi ciddi düşünüp, kendilerine neler kazandırabileceğini hesap etsinler, öğüt alsınlar diye indirdik."},{"n":30,"t":"Biz Davud’a Süleyman’ı hediye ettik. Süleyman ne güzel kuldu! Doğrusu O daima Allah’a yönelirdi."},{"n":31,"t":"Ona bir akşam üstü, çalımlı ve safkan koşu atları sunulmuştu."},{"n":32,"t":"Süleyman, «Gerçekten ben at (mal) sevgisine Rabb’imi anmayı sağladıkları için düştüm» dedi. Atlar koşup toz perdesi arkasından kayboldular."},{"n":33,"t":"Süleyman, «Atları bana getirin» dedi. Bacaklarını ve boyunlarını okşamaya başladı."},{"n":34,"t":"Andolsun, Süleyman’ı denedik. Tahtının üstüne bir ceset bıraktık, sonra O, yine eski haline döndü."},{"n":35,"t":"«Rabb’im! Beni bağışla, bana benden sonra kimsenin ulaşamayacağı bir hükümranlık ver. Sen şüphesiz daima bağışta bulunansın» dedi."},{"n":36,"t":"Bunun üzerine Süleyman’ın buyruğu ile istediği yere kolayca giden rüzgârı emrine verdik."},{"n":37,"t":"Bina ustalarını ve dalgıçlık yapan şeytanları da emrine verdik."},{"n":38,"t":"Demir zincirlere bağlı diğer yaratıkları da onun emrine verdik."},{"n":39,"t":"İşte bizim bağışımız budur; «ister ver, ister tut, hesapsızdır» dedik."},{"n":40,"t":"Doğrusu onun, bizim yanımızda yüksek bir makamı ve güzel bir geleceği vardı."},{"n":41,"t":"Ey Muhammed! Kulumuz Eyyub’u da an. O Rabb’ine «Doğrusu şeytan bana yorgunluk ve azab verdi» diye seslenmişti."},{"n":42,"t":"Biz de ona «Ayağını yere vur! İşte yıkanacak ve içilecek soğuk bir su» dedik."},{"n":43,"t":"Ona bizden bir rahmet ve sağduyu sahiplerine bir ibret olarak ailesini ve onlarla beraber bir eş daha bağışladık."},{"n":44,"t":"«Eline bir demet sap al, onunla vur, yeminini bozma» demiştik. Gerçekten O çok sabırlı bir kulumuzdu, daima Allah’a yönelirdi"},{"n":45,"t":"Ey Muhammed! Güçlü ve anlayışlı olan kullarımız İbrahim, İshak ve Yakub’u da an."},{"n":46,"t":"Biz onları Ahiret yurdunu düşünen, gönülden bağlı kullar yaptık."},{"n":47,"t":"Onlar bizim yanımızda seçkin ve hayırlı kimselerdir."},{"n":48,"t":"İsmail’i, Elyas’ı, Zülkifl’i de an. Hepsi iyilerdendir."},{"n":49,"t":"Bu bir hatırlatmadır. Korunanlar için güzel bir gelecek vardır."},{"n":50,"t":"Kapıları onlara açılmış, Adn cennetleri vardır."},{"n":51,"t":"Orada tahtlara yaslanmış olarak çeşitli meyveler ve içecekler isterler."},{"n":52,"t":"Yanlarında bakışlarını yalnız kocalarına diken kendileriyle yaşıt güzeller vardır."},{"n":53,"t":"İşte hesap günü için size söz verilen bunlardır."},{"n":54,"t":"Doğrusu, verdiğimiz rızıklar tükenmez."},{"n":55,"t":"Bu böyledir; ancak azgınlara kötü bir gelecek vardır."},{"n":56,"t":"Cehenneme girerler. Orası ne kötü bir konaktır."},{"n":57,"t":"İşte bu kaynar su ve irindir, artık onu tatsınlar."},{"n":58,"t":"Ve daha başka çeşit çeşit azab vardır."},{"n":59,"t":"İnkârcıların ileri gelenlerine «işte bu topluluk sizinle beraber gerçeğe karşı direnenlerdir. Onlar rahat yüzü görmesin. Onlar mutlaka ateşe gireceklerdir» denir."},{"n":60,"t":"Toplulukta bulunanlar ise; «Hayır, asıl siz rahat yüzü görmeyin; bizi buraya getiren sizsiniz, ne kötü bir duraktır» derler."},{"n":61,"t":"«Rabb’imiz! Bunu kim başımıza getirdiyse, ateşte onun azabını kat kat artır» derler."},{"n":62,"t":"«Bize ne oldu ki, dünyada iken kötülerden saydığımız adamları burada niçin görmüyoruz?» derler."},{"n":63,"t":"Hani onlarla alay ederdik. Yoksa onları gözden mi kaçırdık?"},{"n":64,"t":"İşte ateş halkının tartışmaları böyledir ve bunlar gerçektir."},{"n":65,"t":"Ey Muhammed! De ki, «Ben sadece bir uyarıcıyım. Gücü her şeye yeten tek Allah’tan başka tanrı yoktur."},{"n":66,"t":"Göklerin, yerin ve ikisi arasında bulunanların Rabb’ı olan Allah, daima üstündür, çok bağışlayandır.»"},{"n":67,"t":"De ki; «Bu Kur’an, büyük bir haberdir.»"},{"n":68,"t":"«Fakat siz ondan yüz çeviriyorsunuz?»"},{"n":69,"t":"Mele-i A’la’da kendi aralarındaki tartışmaları hakkında benim hiçbir bilgim yoktu."},{"n":70,"t":"Ben gelecek tehlikeleri apaçık uyarıcı olduğum içindir ki, bana vahy olunuyor."},{"n":71,"t":"Rabb’im Meleklere demişti ki; ben çamurdan bir insan yaratacağım."},{"n":72,"t":"Onu biçimlendirip ona ruhumdan üflediğim zaman derhal ona secde edin."},{"n":73,"t":"Meleklerin hepsi birden secde ettiler."},{"n":74,"t":"Yalnız İblis secde etmedi, büyüklük tasladı ve kafirlerden oldu."},{"n":75,"t":"«Ey İblis, iki elimle yarattığıma secde etmekten seni alıkoyan nedir? Böbürlendin mi, yoksa yücelerden mi oldun?»"},{"n":76,"t":"«Ben ondan üstünüm. Beni ateşten yarattın. Onu çamurdan yarattın» dedi."},{"n":77,"t":"«Çık oradan sen artık kovulmuş birisin."},{"n":78,"t":"Ceza gününe kadar lanetim senin üzerinedir» dedi."},{"n":79,"t":"İblis «Ey Rabbim! O halde tekrar dirilecekleri güne kadar bana mühlet ver!» dedi."},{"n":80,"t":"«Haydi sana mühlet verildi."},{"n":81,"t":"O belli vaktin gününe kadar.»"},{"n":82,"t":"«senin izzet ve şerefine andolsun ki, onların tümünü azdıracağım» dedi."},{"n":83,"t":"«Yalnız onlardan ihlas sahibi kullar hariç.»"},{"n":84,"t":"«İşte bu doğrudur. Ben gerçeği söylüyorum."},{"n":85,"t":"Sen ve sana uyanların hepsiyle cehennemi dolduracağım» dedi."},{"n":86,"t":"Ey Muhammed! De ki; «Buna karşılık sizden bir ücret istemiyorum, kendimden bir şey teklif edenlerden de değilim.»"},{"n":87,"t":"Bu Kur’an, alemler için bir öğüttür."},{"n":88,"t":"Onun haberlerinin doğruluğunu bir süre sonra gayet iyi anlayacaksınız."}],[{"n":1,"t":"Bu Kitab’ın indirilmesi, aziz ve hikmet sahibi Allah katındandır."},{"n":2,"t":"Ey Muhammed! Şüphesiz ki, Kitab’ı sana hak olarak indirdik. O halde sen de dini Allah’a has kılarak ihlas ile kulluk et."},{"n":3,"t":"İyi bil ki, halis din yalnız Allah’ındır. O’ndan başka dostlar edinerek, «Onlar bizi Allah’a yaklaştırsınlar diye kulluk ediyoruz» derler. Doğrusu Allah, ayrılığa düştükleri şeylerde hüküm verecektir. Allah, yalancı, inkârcı insanı doğru yola iletmez."},{"n":4,"t":"Allah çocuk edinmek isteseydi, yarattıklarından dilediğini seçerdi. O bundan münezzehtir, yücedir. O, tek ve kahredici Allah’dır."},{"n":5,"t":"Allah, gökleri ve yeri hak ile yarattı. Geceyi gündüzün üzerine örtüyor; gündüzü de gecenin üzerine sarıyor. Her biri belli bir süreye kadar yörüngelerinde akıp giden güneş ve ayı buyruk altında tutar. İyi bil ki, O, aziz ve çok bağışlayandır."},{"n":6,"t":"Sizi tek bir candan yarattı; sonra ondan eşini yarattı ve sizin için hayvanlardan sekiz çift meydana getirdi. Sizi annelerinizin karnında üç karanlık içinde yaratılıştan yaratılışa (zigottan embriyoya embriyodan et giydirilmiş kemiklere) geçirerek yaratmıştır. İşte Rabb’iniz olan Allah budur. Mülk O’nundur. O’ndan başka ilah yoktur. Öyleyse nasıl oluyor da O’na kulluktan döndürülüyorsunuz?"},{"n":7,"t":"Eğer inkâr ederseniz bilin ki, Allah sizin imanınıza muhtaç değildir. Fakat kulları için küfre razı olmaz. Ve eğer şükrederseniz sizden hoşnut olur. Hiçbir günahkâr, diğerinin günahını çekmez. Sonra dönüşünüz Rabb’inizedir. O size, yaptıklarınızı haber verir. O, kalblerde olanı bilir."},{"n":8,"t":"«İnkârınla az bir müddet zevklen, sen cehennemliklerdensin.»"},{"n":9,"t":"«Bilenlerle bilmeyenler bir olur mu?» Doğrusu ancak aklı selim sahipleri öğüt alır."},{"n":10,"t":"«Ey inanan kullarım! Rabb’inize karşı gelmekten sakının; bu dünyada iyilik yapanlara iyilik vardır. Allah’ın yarattığı yeryüzü geniştir. Ancak sabredenlere, mükâfatları hesapsız ödenecektir.»"},{"n":11,"t":"«Dini Allah’a halis kılarak O’na kulluk etmekle emrolundum."},{"n":12,"t":"Ve müslümanların ilki olmakla emrolundum.»"},{"n":13,"t":"«Ben, Rabbime isyan edersem, büyük günün azabından korkarım.»"},{"n":14,"t":"«Ben, dinimi Allah’a halis kılarak O’na kulluk ederim.»"},{"n":15,"t":"«Ziyana uğrayanlar, kıyamet günü hem kendilerini, hem de ailelerini ziyana sokanlardır. Dikkat edin, işte bu, apaçık bir ziyandır.»"},{"n":16,"t":"Onların üstlerinde ateşten gölgeler, altlarında da ateşten gölgeler vardır. İşte Allah, kullarını bu azabıyla korkutuyor. Ey kullarım! Benden korkun."},{"n":17,"t":"Tağuta kulluk etmekten kaçınan ve Allah’a yönelenlere müjde var. Müjdele kullarımı."},{"n":18,"t":"Onlar ki, sözü dinler ve onun en güzeline uyarlar. İşte onlar, Allah’ın kendilerini doğru yola ilettiği kimselerdir. İşte onlar akıl sahipleridir."},{"n":19,"t":"Hakkında azab hükmü kesinleşmiş, ateşte olan kimseyi sen mi kurtaracaksın?"},{"n":20,"t":"Fakat Rabb’lerinden korkanlar için üst üste yapılmış, altlarından ırmaklar akan köşkler vardır. Bu, Allah’ın verdiği sözdür. Allah verdiği sözden caymaz."},{"n":21,"t":"Allah’ın, gökten su indirip, onu yerdeki kaynaklara yerleştiren, sonra onunla çeşitli renklerde ekinler yetiştiren olduğunu görmüyor musun? Sonra ekin kurur; onu sararmış görürsün. Sonra Allah onu bir çöpe dönüştürür. Şüphesiz bunlarda akıl sahipleri için öğüt vardır."},{"n":22,"t":"Allah kimin gönlünü İslam’a açmışsa o, Rabb’inden gelen bir nur üzere olmaz mı? Kalpleri Allah’ı anmak hususunda katılaşmış olanlara yazıklar olsun! İşte bunlar apaçık sapıklık içindedirler."},{"n":23,"t":"Allah, ayetleri birbirine benzeyen ve yer yer tekrar eden Kitab’ı, sözlerin en güzeli olarak indirmiştir. Rabb’lerinden korkanların bu Kitap’dan derileri ürperir; sonra hem derileri hem de kalpleri Allah’ın zikriyle yumuşar. İşte bu Kitap, Allah’ın doğruluk rehberidir; O’nunla dilediğini doğru yola iletir. Allah kimi de saptırırsa, onu doğru yola eriştirecek kimse bulunmaz."},{"n":24,"t":"Kıyamet günü kötü azaptan yüzüyle korunmaya çalışan kimse, güven içinde olan kimse gibi midir? Ve zalimlere, «Kazandıklarınızın karşılığını tadın!» denir."},{"n":25,"t":"Onlardan öncekiler de peygamberi yalanlamışlardı da farkına varmadıkları yerden onlara bir azab çattı."},{"n":26,"t":"Allah, dünya hayatında da onlara rezillik taddırdı. Ahiret azabı, elbette daha büyüktür. Keşke bilselerdi."},{"n":27,"t":"Andolsun biz, bu Kur’an’da insanlara, öğüt alsınlar diye her türlü misali verdik."},{"n":28,"t":"O, pürüzsüz Arapça Kur’an’dır. Belki sakınırlar."},{"n":29,"t":"Birbiriyle çekişen bir çok ortakların sahip olduğu bir adam (yani köle) ile yalnız bir kişiye bağlı olan bir adam. Şimdi bu ikisinin durumu bir oluyor mu? Hamd yalnız Allah’a mahsustur; fakat çokları bilmiyor."},{"n":30,"t":"Sen de öleceksin onlar da ölecekler."},{"n":31,"t":"Sonra siz, kıyamet günü, Rabb’inizin huzurunda muhakeme olacaksınız."},{"n":32,"t":"Allah hakkında yalan uyduran ve kendisine gelen doğruyu yalanlayandan daha zalim kim vardır? Cehennemde kâfirlere yetecek kadar yer yok mudur?"},{"n":33,"t":"Gerçeği getirene ve onu doğrulayanlara gelince; «İşte takva sahipleri onlardır.»"},{"n":34,"t":"Onlara, Rabb’lerinin katında diledikleri şeyler vardır; bu, iyilerin mükâfatıdır."},{"n":35,"t":"Zira Allah, onların yaptıkları kötülükleri örter; onlara, yaptıkları iyiliğin en güzel karşılığı verilir."},{"n":36,"t":"Allah, kuluna yetmez mi? Seni O’ndan başkalarıyla korkutuyorlar. Allah kimi saptırırsa onu artık doğru yola ileten olmaz."},{"n":37,"t":"Allah kime de doğru yolu gösterirse; artık onu şaşırtan olmaz. Allah, galip ve öç alan değil mi?"},{"n":38,"t":"«Allah bana yeter. Dayananlar O’na dayanır.»"},{"n":39,"t":"«Ey kavmim! Durumunuza göre bildiğinizi yapın! Ben de bildiğimi yapıyorum. Yakında bileceksiniz.»"},{"n":40,"t":"Kendisini rezil edecek azap kime geliyor? Kime sürekli azab inecek?"},{"n":41,"t":"Biz, insanlar için bu Kitab’ı hak ile sana indirdik. Artık kim doğru yola gelirse kendi yararınadır; kim de saparsa kendi zararınadır. Sen onların üzerine vekil değilsin."},{"n":42,"t":"Allah, öleceklerin ölümleri anında, ölmeyeceklerinde uykuları esnasında ruhlarını alır. Sonra ölümlerine hükmettiği kimselerinkini tutar; diğerlerini bir süreye kadar salıverir. Doğrusu bunda, düşünen bir toplum için ibretler vardır."},{"n":43,"t":"«Onlar, hiçbir şeye sahip olmadıkları, akıl da edemedikleri halde mi şefaat edecekler?»"},{"n":44,"t":"«Bütün şefaat Allah’ın iznine bağlıdır. Göklerin ve yerin hükümranlığı O’nundur. Sonra O’na döneceksiniz.»"},{"n":45,"t":"Allah, onların tanrılarından ayrı olarak tek başına anıldığı zaman, Ahirete inanmayanların kalbleri nefretle çarpar; ancak Allah’dan başka putlar anıldığı zaman hemen yüzleri güler."},{"n":46,"t":"«Ey gökleri ve yeri yoktan var eden, görüleni ve görülmeyeni bilen Allah’ım! Kullarının ayrılığa düştükleri konularda sen hükmedersin.»"},{"n":47,"t":"Eğer yeryüzünde olanların hepsi ve onunla birlikte bir misli daha fazlası da zalimlerin olsaydı; kıyamet günündeki kötü azabdan kurtulmak için onu fidye olarak verirlerdi. Çünkü hiç hesap etmedikleri şeyler Allah tarafından karşılarına çıkarılmıştır."},{"n":48,"t":"Yaptıkları işlerin kötülükleri kendilerine görünmüştür ve alay ettikleri şeyler onları kuşatmıştır."},{"n":49,"t":"«Bu bana bilgimden dolayı verilmiştir» der. Hayır, bir imtihandır; fakat çokları bilmezler."},{"n":50,"t":"Bunu onlardan öncekiler de söylemişti; ancak kazandıkları şeyler onlara fayda vermedi."},{"n":51,"t":"Bunun için işledikleri kötülükler başlarına geldi. Bunlardan zulmedenlerin de kazandıkları kötülükler başlarına gelecektir. Bu hususta Allah’ı aciz bırakamazlar."},{"n":52,"t":"Onlar bilmiyorlar mı ki, Allah dilediği kimsenin rızkını bol bol verir; dilediğini de kısar. Doğrusu bunda, inanan bir toplum için ibretler vardır."},{"n":53,"t":"«Ey kendilerine kötülük edip, aşırı giden kullarım! Allah’ın rahmetinden umudunuzu kesmeyin. Allah bütün günahları bağışlar. Çünkü O çok bağışlayan, çok esirgeyendir.»"},{"n":54,"t":"Rabb’inize yönelin. Azap size gelmeden önce O’na teslim olun sonra size yardım edilmez."},{"n":55,"t":"Ansızın ve hiç farkına varmadığınız bir sırada size azap gelmeden önce Rabb’inizden size indirilen en güzel söze, Kur’an’a uyun."},{"n":56,"t":"Kişinin «Allah’a karşı aşırı gitmemden dolayı bana yazıklar olsun! Gerçekten ben alay edenlerdendim» diyeceği günden sakının."},{"n":57,"t":"«Allah beni doğru yola ulaştırsaydı sakınanlardan olurdum.»"},{"n":58,"t":"Yahut azabı gördüğü zaman; «Keşke benim için bir kez daha dünyaya dönüş olsa da iyilerden olsam» diyeceği günden sakının."},{"n":59,"t":"«Evet, ayetlerim sana gelmişti de sen onları yalanlamış, büyüklük taslamış ve inkârcılardan olmuştun.»"},{"n":60,"t":"Allah’a karşı yalan uyduranların yüzlerinin kapkara olduğunu görürsün. Kibirlenenlere yetecek kadar, cehennemde yer yok mudur?"},{"n":61,"t":"Allah, sakınanları, başarılarından ötürü kurtarır. Onlara hiçbir kötülük gelmez, onlar üzülmezler."},{"n":62,"t":"Allah her şeyin yaratıcısıdır. O, her şeyin yöneticisidir."},{"n":63,"t":"Göklerin ve yerin anahtarları O’nundur. Allah’ın ayetlerini inkâr edenler var ya, işte onlar hüsrandadırlar."},{"n":64,"t":"«Ey cahiller! Allah’dan başkasına kulluk etmemi mi bana emrediyorsunuz?»"},{"n":65,"t":"«Andolsun, eğer Allah’a ortak koşarsan işlerin boşa gider ve hüsranda kalanlardan olursun.»"},{"n":66,"t":"Hayır, yalnız Allah’a kulluk et ve şükredenlerden ol!"},{"n":67,"t":"Onlar, Allah’ı gereği gibi bilemediler. Oysa kıyamet günü yeryüzü, bütünü ile O’nun avucu içindedir. Gökler de O’nun sağ elinde dürülmüştür. O, müşriklerin ortak koşmalarından uzak ve yücedir."},{"n":68,"t":"Sur’a üflenince, göklerde ve yerde olanlar korkudan düşüp bayılırlar. Ancak Allah’ın dilediği kalır. Sonra sur’a bir daha üflenince hemen ayağa kalkıp bakışıp dururlar."},{"n":69,"t":"Yeryüzü, Rabb’inin nuruyla aydınlanır. Kitap açılır. Peygamberler ve şahitler getirilir. Ve onlara haksızlık yapılmadan, aralarında adaletle hüküm verilir."},{"n":70,"t":"Herkese, yaptığının karşılığı tam verilir. Allah, onların yaptıklarını en iyi bilendir."},{"n":71,"t":"\"Size içinizden Rabbinizin ayetlerini okuyan ve bugüne kavuşacağınızı ihtar eden peygamberler gelmedi mi?\" derler. \"Evet geldi\" derler. Lakin azap sözü kafirlerin üzerine gerçekleşir."},{"n":72,"t":"«O halde içinde ebedi kalmak üzere cehennemin kapılarından girin. Kibirlenenlerin durağı ne kötüdür,» denir."},{"n":73,"t":"\"Selam size, hoş geldiniz, iyi ettiniz, ne hoşsunuz, işte buyurun içinde temelli ve ebedi kalacağınız bu cennete girin!\" diyeceklerdir."},{"n":74,"t":"«Bize verdiği sözde duran ve bizi buraya yerleştiren Allah’a hamd olsun. Cennette istediğimiz yerde oturabiliriz. Yararlı iş işleyenlerin ücreti ne güzelmiş!» derler."},{"n":75,"t":"Melekleri, arş’ın etrafını çevirmiş oldukları halde, Rabb’lerini hamd ile överken görürsün. Artık insanların aralarında adaletle hükmedilmiştir. «Övgü, alemlerin Rabb’i olan Allah içindir» denir."}],[{"n":1,"t":"Hâ Mim."},{"n":2,"t":"Bu kitabın indirilmesi, güçlü ve her şeyi en iyi bilen Allah katındandır."},{"n":3,"t":"O günahı bağışlayan, tevbeyi kabul eden, cezası şiddetli, lütfu bol olandır. O’ndan başka ilah yoktur. Dönüş O’nadır."},{"n":4,"t":"İnkar edenlerden başkası Allah’ın ayetleri hakkında mücadeleye girişmez. Ey Muhammed! İnkarcıların memlekette gezip dolaşması seni aldatmasın."},{"n":5,"t":"Onlardan önce Nuh kavmi ve onlardan sonra gelen kollar da yalanladı. Her millet, Peygamberlerini yakalamağa yeltendi; Batılı hakkın yerine koymak için mücadele etmişlerdi. Bu yüzden onları yakaladım. (Bak işte) azabım nasıl oldu?!"},{"n":6,"t":"İnkar edenlerin cehennemlik olduklarına dair Rabb’inin sözü böylece gerçekleşti."},{"n":7,"t":"«Rabbimiz! İlmin ve rahmetin her şeyi kapladı. Tevbe edip senin yoluna uyanları bağışla; onları cehennem azabından koru» diye bağışlama dilerler."},{"n":8,"t":"«Rabbimiz! Mü’minleri ve babalarından, eşlerinden, soylarından iyi olanları, kendilerine söz verdiğin Adn cennetlerine koy; şüphesiz güçlü olan, hakim olan ancak sensin."},{"n":9,"t":"Onları kötülüklerden koru! O gün kötülüklerden kimi korursan, ona şüphesiz rahmet etmiş olursun. Bu büyük kurtuluştur.»"},{"n":10,"t":"«Allah’ın gazabı sizin birbirinize olan öfkenizden daha büyüktür. Zira siz imana çağrıldığınızda inkar ederdiniz.»"},{"n":11,"t":"«Rabbimiz, bizi iki kez öldürdün ve iki kez dirilttin. Günahlarımızı itiraf ettik. Şimdi şu ateşten çıkmak için bize bir yol var mı?»"},{"n":12,"t":"Tek Allah’a çağrıldığınız zaman inkar ederdiniz. O’na ortak koşulunca inanırdınız. Artık hüküm yüce ve büyük Allah’ındır.»"},{"n":13,"t":"Size mucizelerini gösteren, size gökten rızık indiren O’dur. Allah’a yönelenden başkası ibret almaz."},{"n":14,"t":"Ey inananlar! Kafirlerin hoşuna gitmese de siz, dini yalnız Allah’a halis kılarak O’na çağırın."},{"n":15,"t":"Arş sahibi, varlıkların en yücesi olan Allah, kavuşma gününü ihtar etmek için kullarından dilediğine emriyle vahyi indirir."},{"n":16,"t":"O gün onlar meydana çıkarlar; onların hiçbir şeyi Allah’a gizli kalmaz. «Bugün hükümranlık kimindir?» denir. Hepsi «Gücü her şeye yeten tek Allah’ındır» derler."},{"n":17,"t":"Bugün herkese, kazandığının karşılığı verilir. Bugün haksızlık yoktur. Doğrusu Allah, hesabı çabuk görendir."},{"n":18,"t":"Ey Muhammed! Onları yüreklerin ağıza geleceği, tasadan yutkunacakları yaklaşan Kıyamet günü ile uyar. Zalimlerin ne dostu ne de sözü dinlenecek şefaatçisi olur."},{"n":19,"t":"Allah gözlerin hainliğini ve gönüllerin gizlediğini bilir."},{"n":20,"t":"Allah adaletle hükmeder. O’ndan başka çağırdıkları tanrılar ise, hiçbir şeye hükmedemezler. Çünkü işiten, gören yalnız Allah’tır."},{"n":21,"t":"Onlar, yeryüzünde gezip dolaşmadılar mı ki, kendilerinden önce gelenlerin sonunun nasıl olduğunu görsünler. Onlar kuvvet ve yeryüzündeki eserleri bakımından kendilerinden daha üstün idiler. Fakat Allah, onları günahları yüzünden yakaladı. Onları Allah’ın azabından koruyan da olmadı."},{"n":22,"t":"Çünkü onlar öyle kimselerdir ki, elçileri onlara açık belgeler getirdiği halde kabul etmemişlerdi. Bu yüzden Allah onları yakaladı. Zira O üstündür, cezası çetin olandır."},{"n":23,"t":"Doğrusu Biz Musa’yı, mesajlarımızla ve (sahibinin doğruluğuna şahit olan) apaçık bir belgeyle elçi göndermiştik:"},{"n":24,"t":"Firavun’a, Haman’a ve Karun’a gönderdik. «Bu yalancı bir büyücüdür» dediler."},{"n":25,"t":"«Onunla beraber inananların oğullarını öldürün, kadınlarını sağ bırakın!» dediler. Fakat kafirlerin tuzağı hep boşa çıkar."},{"n":26,"t":"«Ben bırakın da Musa’yı öldüreyim. O Rabb’ine yalvaradursun. Onun sizin dininizi değiştireceğinden veya yeryüzünde bozgunculuk çıkaracağından korkuyorum.» dedi."},{"n":27,"t":"Ben hesap gününe inanmayan her kibirliden, benim de Rabbim sizin de Rabbiniz olan Allah’a sığınırım."},{"n":28,"t":"«Rabb’im Allah’tır diyen bir adamı mı öldüreceksiniz? Oysa size Rabb’inizden belgeler gelmiştir. Eğer yalancı ise yalanı kendinedir; eğer doğru sözlü ise, sizi tehdit ettiklerinin bir kısmı başınıza gelebilir. Şüphesiz Allah aşırı giden, yalancı kimseyi doğru yola iletmez."},{"n":29,"t":"«Ben size kendi görüşümden başkasını söylemiyorum. Ben size ancak doğru yolu gösteriyorum» dedi."},{"n":30,"t":"«Ey kavmim, ben üzerinize önceki toplulukların uğradıkları bir günün benzerinden korkuyorum."},{"n":31,"t":"Nuh kavminin, Ad ve Semud’un ve onlardan sonrakilerin durumu gibi bir durumla karşılaşmanızdan korkuyorum. Allah kullara zulmetmek istemez."},{"n":32,"t":"Ey kavmim, sizin için insanların korku ve dehşetten bağırıp birbirlerinden yardım isteyecekleri o çağırma gününden korkuyorum."},{"n":33,"t":"Arkanıza dönüp kaçacağın gün Allah’a karşı sizi koruyan bulunmaz. Allah kimi şaşırtırsa artık ona yol gösteren olmaz."},{"n":34,"t":"«Allah ondan sonra peygamber göndermez» dediniz. İşte Allah, aşırı giden, şüpheci kimseleri böyle saptırır.»"},{"n":35,"t":"Bunlar, Allah’ın ayetleri üzerinde kendilerine gelmiş bir delil bulunmadan tartışırlar. Bu Allah katında da, inananların yanında da öfkeyi artırır. Allah büyüklük taslayan her zorbanın kalbini bundan dolayı mühürler."},{"n":36,"t":"Ey Haman, bana yüksek bir kule yap ki o sebeplere (yollara) erişeyim.»"},{"n":37,"t":"Göklerin yollarına erişeyim de Musa’nın tanrısına çıkıp bakayım. Çünkü ben onu (Musa’yı, peygamberlik davasında) yalancı sanıyorum. Böylece yaptığı kötü iş, Firavuna süslü gösterildi ve o yoldan çıkarıldı. Firavun’un tuzağı tamamen boşa çıktı."},{"n":38,"t":"«Ey kavmim! Bana uyun, sizi doğru yola götüreyim.»"},{"n":39,"t":"Ey kavmim! Bu dünya hayatı kısa bir geçimdir. Ahiret ise ebedi olarak durulacak yerdir."},{"n":40,"t":"Kim bir kötülük işlerse onun kadar ceza görür. Kadın veya erkek, kim, inanarak yararlı iş yaparsa, cennete girerler ve orada kendilerine hesapsız rızıklar verilir."},{"n":41,"t":"Ey kavmim! Neden ben sizi kurtuluşa çağırdığım halde siz beni ateşe çağırıyorsunuz?"},{"n":42,"t":"Siz beni Allah’ı inkar etmeye, bilmediğim bir şeyi O’na ortak koşmaya çağırıyorsunuz. Ben ise, güçlü olan, çok bağışlayan Allah’a çağırıyorum."},{"n":43,"t":"Sizin beni davet ettiğiniz şeyin ne dünyada, ne de ahirette hiçbir davet yetkisi yoktur. Gerçekte dönüşümüz Allah’adır. Aşırı gidenlere gelince, işte onlar ateş ehlidirler."},{"n":44,"t":"Benim size söylediklerimi yakında hatırlayacaksınız. Ben işimi Allah’a bırakıyorum. Şüphesiz Allah kulları görür."},{"n":45,"t":"Allah o adamı, kurmak istedikleri tuzaktan korudu. Kötü azab, Firavun’un adamlarını sardı."},{"n":46,"t":"\"Firavun’un adamlarını azabın en ağırına sokun!\" denir."},{"n":47,"t":"«Biz size uymuştuk. Şimdi siz şu ateşin ufak bir parçasını bizden savabilir misiniz?»"},{"n":48,"t":"«Doğrusu hepimiz de onun içindeyiz. Allah kulları arasında şüphesiz hüküm vermiştir.» derler."},{"n":49,"t":"«Ne olur Rabbinize dua edin de hiç değilse bir gün, bizden azabı biraz hafifletsin.»"},{"n":50,"t":"«Öyleyse yalvarıp durun. Nankörlerin yalvarması hep çıkmazdadır» dediler."},{"n":51,"t":"Elbette biz, peygamberlerimize ve inananlara dünya hayatında ve şahitlerin şahitlik edecekleri günde yardım ederiz."},{"n":52,"t":"O gün zalimlere, özür beyan etmeleri fayda vermez, lanet onlaradır. Yurdun kötüsü de onlaradır."},{"n":53,"t":"Andolsun! Biz Musa’ya hidayet verdik ve İsrailoğullarına o Kitab’ı miras kıldık."},{"n":54,"t":"O, akıl sahipleri için bir öğüt ve doğruluk rehberidir."},{"n":55,"t":"Ey Muhammed! Sabret, Allah’ın verdiği söz şüphesiz gerçektir. Suçunun bağışlanmasını dile. Rabbini akşam sabah överek tesbih et."},{"n":56,"t":"Allah’ın ayetleri üzerinde kendilerine gelen bir delil olmadan tartışanların gönüllerinde, ulaşamayacakları bir büyüklenme vardır. Sen Allah’a sığın. O şüphesiz işitendir, görendir."},{"n":57,"t":"Göklerin ve yerin yaratılması, insanların yaratılmasından daha büyük bir şeydir. Fakat insanların çoğu bilmezler."},{"n":58,"t":"Körle gören bir olmaz. İnanan ve iyi işler yapanlarla, kötülük yapan bir olmaz. Ne kadar az düşünüyorsunuz."},{"n":59,"t":"Kıyamet saati mutlaka gelecektir. Bunda asla şüphe yoktur. Fakat insanların çoğu inanmazlar."},{"n":60,"t":"«Bana dua edin, duanızı kabul edeyim. Bana kulluk etmeye tenezzül etmeyenler, aşağılık olarak cehenneme gireceklerdir.»"},{"n":61,"t":"Allah O’dur ki, geceyi içinde istirahat etmeniz için (serin ve karanlık) gündüzü de işinizi görmeniz için aydınlık yaptı. Şüphesiz Allah, insanlara lütufkârdır fakat insanların çoğu şükretmezler."},{"n":62,"t":"İşte her şeyin yaratıcısı Rabbiniz olan Allah budur. O’ndan başka ilah yoktur. Nasıl da aldatılıp döndürülüyorsunuz?"},{"n":63,"t":"Allah’ın ayetlerini bile bile inkar edenler böylece döndürülüyorlardı."},{"n":64,"t":"Sizin için yeri durak, göğü bina eden, size şekil verip de, şeklinizi güzel yapan, sizi temiz şeylerle rızıklandıran Allah’tır. İşte Rabbiniz olan Allah budur. Alemlerin Rabbi Allah ne yücedir."},{"n":65,"t":"O diridir. O’ndan başka ilah yoktur. Dini yalnız O’na has kılarak O’na yalvarın. Övgü, alemlerin rabbi Allah içindir."},{"n":66,"t":"«Sizin, Allah’ı bırakıp da kulluk ettiklerinize kulluk etmek bana yasak kılınmıştır. Zira bana Rabbimden belgeler gelmiştir. Ben, alemlerin Rabbine teslim olmakla emrolundum.»"},{"n":67,"t":"Sizi topraktan, sonra nutfeden, sonra kan pıhtısından yaratan; sonra erginlik çağına ulaşmanız, sonra da yaşlanmanız için sizi yaşatan O’dur. Kiminiz daha önce öldürülür, kiminiz de belirlenmiş süreye ulaşırsınız. Belki artık düşünürsünüz."},{"n":68,"t":"Yaşatan ve öldüren O’dur. Bir işin olmasını istedi mi, ona sadece «ol» der o da olur."},{"n":69,"t":"Allah’ın ayetleri hakkında tartışanların nasıl Hak’tan çevrildiklerini görmedin mi?"},{"n":70,"t":"O, Kitab’ı duyurulması için elçilerimize gönderdiğimiz şeyleri yalanlayanlar, yakında bileceklerdir."},{"n":71,"t":"Boyunlarında demir halkalar ve zincirler olduğu halde sürükleneceklerdir."},{"n":72,"t":"Kaynar suda sonra da ateşte yakılacaklardır."},{"n":73,"t":"«Ortak koştuklarınız nerede?"},{"n":74,"t":"«Bizden uzaklaşıp kayboldular; hayır, meğer biz önceden hiçbir şeye tapmamışız. (Taptıklarımız hiçbir şey değilmiş).» İşte Allah kafirleri böyle şaşırtır."},{"n":75,"t":"Bu durum sizin yeryüzünde haksız olarak şımarmanızdan ve aşırı derecede sevinip böbürlenmenizdendir."},{"n":76,"t":"Cehennemin kapılarından, girin orada ebedi kalacaksınız. Kibirlenenlerin yeri ne kötüdür."},{"n":77,"t":"Ey Muhammed! Sabret, şüphesiz Allah’ın verdiği söz gerçektir. Onlara söz verdiğimiz azabın bir kısmını sana gösteririz veya seni öldürürüz, nasıl olsa onların dönüşü Bize’dir."},{"n":78,"t":"Andolsun, biz senden önce de Peygamberler gönderdik. Onlardan kiminin hayatını sana anlattık, kimini de anlatmadık. Hiçbir elçi, Allah’ın izni olmadan bir mucize getiremez. Allah’ın emri geldiği zaman hak yerine getirilir ve işte o zaman Allah’ın ayetlerini boşa çıkarmağa çalışanlar, hüsrana uğrarlar."},{"n":79,"t":"Binek olarak kullanmanız ve yemeniz için hayvanları sizin için yaratan Allah’tır."},{"n":80,"t":"Onlardan sizin için daha nice faydalar vardır, gönüllerinizdeki arzulara, onlara binerek ulaşırsınız. Onların ve gemilerin üstünde taşınırsınız."},{"n":81,"t":"Allah size her türlü delillerini göstermektedir. Allah’ın bunca delillerinden hangisini inkâr edebilirsiniz?"},{"n":82,"t":"Yeryüzünde dolaşıp, kendilerinden daha çok, daha kuvvetli, yeryüzünde bıraktıkları eserler, daha sağlam olan, öncekilerin sonlarının nasıl olduğunu görmezler mi? Kazandıkları, onlara bir fayda vermemişti."},{"n":83,"t":"Peygamberleri, onlara belgelerle gelince, kendilerinden olan bilgiden gururlandılar da, alaya aldıkları şey kendilerini salıverdi."},{"n":84,"t":"«Tek Allah’a inandık ve O’na ortak koştuğumuz şeyleri inkar ettik.» dediler."},{"n":85,"t":"Fakat şiddetimizi gördüklerinde iman etmeleri kendilerine fayda sağlamadı. Allah’ın kulları hakkında carî olan uygulaması hep böyle olmuştur. İşte kâfirler burada hüsrana uğramışlardır."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Bu Kitab, Rahman ve Rahim olan Allah katından indirilmiştir."},{"n":3,"t":"Bilen bir toplum için ayetleri açıklanmış; arapça okunan bir Kitab’dır."},{"n":4,"t":"Müjdeleyici ve uyarıcı olarak gönderilmiştir. Fakat insanların çoğu onu düşünüp kabul etmekten yüz çevirmiştir. Onlar işitmezler."},{"n":5,"t":"«Ey Muhammed! Bizi çağırdığın şeye karşı kalbimiz kapalıdır, kulaklarımızda bir ağırlık ve seninle bizim aramızda bir perde vardır. Sen istediğini yap, biz de istediğimizi yapıyoruz.»"},{"n":6,"t":"«Ben de ancak sizin gibi bir insanım. Bana ilahınızın tek bir ilah olduğu vahyediliyor. O’na yönelerek işlerinizi düzeltin, O’ndan mağfiret dileyin. O’na ortak koşanların vay haline!»"},{"n":7,"t":"Onlar zekat vermezler ve ahireti de inkar ederler."},{"n":8,"t":"İnanıp iyi işler yapanlara gelince; onlar için kesintisiz mükafat vardır."},{"n":9,"t":"«Siz mi yeryüzünü iki günde yaratana nankörlük ediyor ve O’na ortaklar koşuyorsunuz? O alemlerin Rabb’idir.»"},{"n":10,"t":"Yeryüzüne sabit dağlar yerleştirdi. Onda bereketler yarattı ve orada rızıklarını arayanlar için dört günde düzene koydu."},{"n":11,"t":"«İsteyerek veya istemeyerek buyruğuma gelin» dedi. «İsteyerek geldik» dediler."},{"n":12,"t":"Böylece onları, iki gün içinde yedi gök var etti ve her göğün görevini vahyetti. Yakın göğü ışıklarla donattık ve bozulmaktan koruduk. İşte bu bilen, güçlü olan Allah kanunudur."},{"n":13,"t":"«Ben sizi Ad ve Semud kavimlerinin başlarına gelen yıldırıma benzer bir yıldırıma karşı uyardım.»"},{"n":14,"t":"Onlara «Allah’tan başkasına kulluk etmeyin» diyerek önlerinden ve arkalarından peygamberler geldiği vakit, «Rabb’imiz dileseydi melekler indirirdi. Onun için biz sizinle gönderilen şeyleri inkar ediyoruz» demişlerdi."},{"n":15,"t":"«Bizden daha kuvvetli kim var?» dediler. Onlar kendilerini yaratan Allah’ın kendilerinden daha kuvvetli olduğunu görmediler mi? Onlar bizim ayetlerimizi kasten inkar ediyorlardır."},{"n":16,"t":"Biz de onlara dünya hayatında rezillik azabını taddırmak için o uğursuz günlerde, üzerlerine dondurucu bir rüzgar gönderdik. Ahiret azabı ise daha da kepazeliktir ve onlara hiç yardım edilmez."},{"n":17,"t":"Semud kavmine gelince onlara doğru yolu gösterdik; fakat onlar, körlüğü doğru yola tercih ettiler. Böylece yaptıkları yüzünden alçaltıcı azab yıldırımı onları yakaladı."},{"n":18,"t":"İnananları ve Allah’a karşı gelmekten sakınmış olanları kurtardık."},{"n":19,"t":"Allah’ın düşmanları ateşe sürüldükleri gün toplanıp bir araya getirilirler."},{"n":20,"t":"Nihayet oraya vardıklarında kulakları, gözleri ve derileri, yaptıkları hakkında onların aleyhine şahitlik ettiler."},{"n":21,"t":"«Her şeyi konuşturan Allah bizi konuşturdu. İlk defa sizi O yaratmıştı, işte O’na döndürülüyorsunuz» cevabını verirler."},{"n":22,"t":"Siz kulaklarınızın, gözlerinizin ve derilerinizin, aleyhinize şahidlik etmesinden sakınmıyordunuz, yaptıklarınızdan çoğunu Allah’ın bilemeyeceğini sanıyordunuz."},{"n":23,"t":"İşte Rabb’inize karşı beslediğiniz bu zannınız, sizi helak etti, ziyana uğrayanlardan olup çıktınız."},{"n":24,"t":"İster sabretsinler ister etmesinler, onların durağı ateştir. Hoş tutulmalarını isteseler de artık hoş tutulmazlar."},{"n":25,"t":"şüphe yok ki onlar, daima kaybeden taraf oldular."},{"n":26,"t":"«Bu Kur’an’ı dinlemeyin, okunurken gürültü yapın, belki ona galip gelirsiniz» dediler."},{"n":27,"t":"İnkar edenlere şiddetli bir azab taddıracağız ve onları, yaptıklarının en kötüsüyle cezalandıracağız."},{"n":28,"t":"İşte böyle; Allah’ın düşmanlarının cezası ateştir. Ayetlerimizi bile bile inkar etmeleri karşılığı orası onların temelli kalacakları yerdir."},{"n":29,"t":"«Rabb’imiz cinlerden ve insanlardan bizi saptıranları göster, onları ayaklarımızın altına alalım. Ki altta kalanlar olsunlar.»"},{"n":30,"t":"Şüphesiz Rabb’imiz Allah’tır deyip, sonra dosdoğru yolda yürüyenlerin üzerine melekler iner. Onlara «Korkmayın, üzülmeyin, size söz verilen cennetle sevinin!» derler."},{"n":31,"t":"Biz dünya hayatında da ahiret hayatında da sizin dostlarınızız. Orada canlarınızın çektiği ve istediğiniz her şey sizindir."},{"n":32,"t":"Bütün bunlar, O bağışlayan ve esirgeyen Allah’tan bir ağırlama olarak size lûtfedilmiştir."},{"n":33,"t":"İnsanları Allah’a çağıran, iyi iş yapan ve «Ben müslümanlardanım» diyenden daha güzel sözlü kim olabilir?"},{"n":34,"t":"İyilikle kötülük bir olmaz. Sen kötülüğü en güzel bir tavırla sav! O zaman bakarsın ki seninle arasında düşmanlık bulunan kimse, sanki sıcak bir dost oluvermiştir."},{"n":35,"t":"Bu haslete ancak sabredenler kavuşturulur. Buna ancak hayırda büyük pay sahibi olan kimse kavuşturulur."},{"n":36,"t":"Eğer şeytandan gelen kötü bir düşünce seni dürtecek olursa, hemen Allah’a sığın. Çünkü O, işiten ve bilendir."},{"n":37,"t":"Gece, gündüz, güneş ve ay onun ayetlerindendir. Eğer Allah’a kulluk ediyorsanız, güneşe ve aya secde etmeyin. Onları yaratan Allah’a secde edin!"},{"n":38,"t":"Eğer büyüklük taslarlarsa bilsinler ki, Rabb’inin yanında bulunanlar (melekler), gece gündüz O’nu tesbih ederler ve onlar hiç usanmazlar."},{"n":39,"t":"Sen toprağı boynu bükük kupkuru görürsün. Onun üzerine suyu döktüğümüz zaman titreşir ve kabarır. Onu dirilten Allah elbette ölüleri de diriltir. O’nun herşeye gücü yeter."},{"n":40,"t":"Ayetlerimiz hakkında doğruluktan ayrılıp eğriliğe sapanlar bize gizli kalmazlar. O halde ateşin içine atılan mı daha iyidir, yoksa kıyamet günü güvenle gelen mi? Dilediğinizi yapın, O, yaptıklarınızı görmektedir."},{"n":41,"t":"Kendilerine gelen Kur’ân’ı inkar ettiler. Halbuki o yüce bir Kitab’dır."},{"n":42,"t":"Geçmişte ve gelecekte ona batıl karışmaz. Her yaptığını bir hikmete göre yapan ve övülmeye layık Allah katından indirilmiştir."},{"n":43,"t":"Ey Muhammed! Sana söylenen, senden önceki elçilere söylenmiş olandan başka birşey değildir. Senin Rabb’in hem bağışlama sahibi, hem de acı azap sahibidir."},{"n":44,"t":"«O mü’minler için doğru yolu gösteren bir kılavuz ve şifadır.» İnanmayanlara gelince, onların kulaklarında bir ağırlık vardır ve Kur’an, onlara bir körlüktür. Sanki onlar uzak bir yerden çağrılıyorlar."},{"n":45,"t":"Andolsun ki Musa’ya kitap vermiştik de onda ayrılığa düşmüşlerdi. Rabb’inin verilmiş bir sözü olmasaydı, aralarında hükmedilmiş olurdu. Doğrusu onlar, onun hakkında şüphe içindedirler."},{"n":46,"t":"Kim iyi bir iş yaparsa faydası kendisinedir ve kim kötülük yaparsa zararı kendisinedir. Rabb’in kullara zulmedici değildir."},{"n":47,"t":"«Sana arz ederiz ki bizde hiçbir gören yok» derler."},{"n":48,"t":"Önceden yalvarıp durdukları tanrıları onlardan uzaklaşmıştır. Kendilerinin kaçacak yerlerinin olmadığını anlamışlardır."},{"n":49,"t":"İnsan hayır istemekten yorulmaz. Ancak kendisine bir şer dokundu mu hemen üzgündür, ümitsizdir."},{"n":50,"t":"«Bu benim hakkımdır; kıyametin kopacağını sanmıyorum. Rabb’ime götürülmüş olsam bile muhakkak O’nun yanında benim için güzel şeyler vardır» der. Biz inkar edenlere, yaptıklarını mutlaka haber vereceğiz ve mutlaka onlara acı azabdan taddıracağız."},{"n":51,"t":"İnsana bir nimet verdik mi yüz çevirir; yan çizer. Ona bir şer dokundu mu yalvarıp durur."},{"n":52,"t":"«Kur ân Allah katından gelmiş olup da sizde onu inkar etmişseniz, söyleyin bana derin bir çıkmazda bulunan kimseden daha sapık kim vardır?»"},{"n":53,"t":"Biz onlara iç ve dış alemdeki ayetlerimizi göstereceğiz ki, o Kur’an’ın gerçek olduğu, onlara iyice belli olsun. Rabb’inin her şeye şahit olması yetmez mi?"},{"n":54,"t":"İyi bil ki onlar, Rabb’ine kavuşmaktan kuşku içindedirler. İyi bil ki O, herşeyi kuşatmıştır."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Ayn, Sin, Kaf."},{"n":3,"t":"O üstün iradeli ve her yaptığını bir hikmete göre yapan Allah, sana ve senden önceki peygamberlere böyle vahyeder."},{"n":4,"t":"Göklerde ve yerde ne varsa hepsi O’nundur. O, yücedir, büyüktür."},{"n":5,"t":"Neredeyse gökler onların Allah’a ortak koşmaları karşısında tepelerinden çatlayacaklar. Melekler, Rab’lerini hamd ile tesbih ederler, yerdekiler için bağışlanma dilerler. İyi bilinki Allah, çok bağışlayan, çok esirgeyendir."},{"n":6,"t":"Allah’tan başka dostlar edinenleri Allah gözetlemektedir. Sen onların üzerinde vekil değilsin."},{"n":7,"t":"Ey Muhammed! Şehirlerin anası Mekke’de ve onun çevresinde bulunanları uyarman; hakkında asla şüphe olmayan toplanma gününe karşı korkutman için sana Arapça bir Kur’an vahyettik. O gün insanların bir kısmı cennete, bir kısmı da çılgın alevli cehenneme girerler."},{"n":8,"t":"Allah dilemiş olsaydı, onları bir tek ümmet yapardı. O dilediğine rahmetini kavuşturur. Zalimlerin ise bir dost ve yardımcısı olmaz."},{"n":9,"t":"Yoksa onlar Allah’tan başka dostlar (veli)mi edindiler? Halbuki dost (veli) yalnız Allah’tır. O ölüleri diriltir ve O’nun gücü herşeye yeter."},{"n":10,"t":"Görüş ayrılığına düştüğünüz herhangi bir meselede hüküm vermek Allah’a aittir. İşte bu, benim Rabb’im olan Allah’tır. O’na dayandım, O’na yöneldim."},{"n":11,"t":"Gökleri ve yeri yoktan var edendir. Size kendinizden eşler, hayvanlardan da çiftler yarattı. Bu düzen içinde çoğalmanızı sağlamıştır. O’nun benzeri hiçbir şey yoktur. O herşeyi işitir, görür."},{"n":12,"t":"Göklerin ve yerin anahtarları Allah’ındır. Dilediğine rızkı bol verir, dilediğinden de kısar. O, herşeyi bilendir."},{"n":13,"t":"Allah, dinden Nuh’a tavsiye ettiği, sana vahyettiğimiz, İbrahim’e, Musa’ya ve İsa’ya tavsiye ettiğimiz ’Allah’ın dinini hayata egemen kılın ve bu konuda görüş ayrılığına düşmeyin’ direktifini sizin için bir hayat düsturu olarak öngördü. Fakat kendilerini çağırdığın bu düstur Allah’a ortak koşanlara ağır geldi. Allah dilediğini kendisine seçer ve kendisine yöneleni de doğru yola iletir."},{"n":14,"t":"Onlar, kendilerine ilim geldikten sonra sadece aralarındaki çekememezlik yüzünden ayrılığa düştüler. Eğer belli bir süre için Rabb’inin verilmiş sözü olmasaydı, aralarında hemen hükmedilirdi. Onlardan sonra Kitab’a varis kılınanlar da ondan kuşku duymaktadırlar."},{"n":15,"t":"«Ben Allah’ın indirdiği her Kitab’a inandım; aranızda adaleti gerçekleştirmekle emrolundum. Allah bizim de Rabb’imiz, sizin de Rabb’inizdir. Bizim amellerimiz bize, sizin amelleriniz size aittir. Bizimle sizin aranızda tartışılacak birşey yoktur. Allah hepimizi bir araya toplar, dönüşte O’nadır.»"},{"n":16,"t":"İnsanlar Allah’ın çağrısını kabul ettikten sonra, Allah’ın dini hakkında tartışanların delilleri, Rab’leri yanında batıldır. Onların aleyhine bir gazab ve çetin bir azab vardır."},{"n":17,"t":"Gerçeği taşıyan kitabı ve adalet ölçüsünü hak olarak indiren Allah’tır. Ne biliyorsun, belki de kıyamet saati yakındır![520]"},{"n":18,"t":"O’na inanmayanlar çabucak gelmesini isterler. İman edenler ise ondan korku ile titrerler. Ve O’nun hakkın kendisi olduğunu bilirler. Dikkat edin kıyamet günü hakkında tartışanlar derin bir sapıklık içindedirler."},{"n":19,"t":"Allah kullarına lütufkardır, dilediğini rızıklandırır. O kuvvetlidir, galibtir."},{"n":20,"t":"Ahiret kazancı isteyenin kazancını artırırız; dünya kazancını isteyene de ondan veririz; fakat onun ahirette bir payı bulunmaz."},{"n":21,"t":"Yoksa, Allah’ın dinde izin vermediği bir şeyi onlara kanun kılacak ortakları mı vardır? Eğer azabı erteleme sözü olmasaydı, derhal aralarında hüküm verilirdi. Şüphesiz zalimler için can yakıcı bir azap vardır."},{"n":22,"t":"Yaptıkları işler başlarına inerken zalimlerin, korkudan titrediklerini görürsün. Utanıp iyi işler yapanlar da cennet bahçelerindedirler. Rab’lerinin yanında onlara diledikleri herşey vardır. İşte büyük lütuf budur."},{"n":23,"t":"«Ben sizden buna karşı yakınlara sevgiden başka bir ücret istemem.» Kim güzel bir amel işlerse onun güzelliğini arttırırız. Doğrusu Allah bağışlayandır. Şükrün karşılığını verendir."},{"n":24,"t":"Yoksa «Allah’a yalan uydurdu» mu diyorlar? Allah dilerse senin kalbine mührü basar; batılı mahveder, hakkı sözleriyle gerçekleştirir. Doğrusu O, kalplerde olanı bilendir."},{"n":25,"t":"O, kullarından tevbeyi kabul eden, kötülükleri bağışlayan ve yaptıklarınızı bilendir."},{"n":26,"t":"Allah, iman edip iyi işler yapanların tevbesini kabul eder. Lütfundan onlara fazlasını verir. Kafirlere gelince onlara da çetin bir azap vardır."},{"n":27,"t":"Allah kullarına rızkı bollaştırsaydı, yeryüzünde azarlardı. Fakat O rızkı dilediği ölçüde indirir. Çünkü O, kullarından haberdardır, onları görür."},{"n":28,"t":"İnsanların umutsuzluğa düşmelerinin ardından yağmuru indiren ve rahmetini yayan Allah’tır. O, gerçek dosttur, övülmeye layık olandır."},{"n":29,"t":"Gökleri, yer ve bunların içine yayıp ürettiği canlıları yaratması da O’nun ayetlerindendir. O, dilediği zaman onları tekrar toplamaya da kaadirdir"},{"n":30,"t":"Başınıza gelen herhangi bir musibet kendi ellerinizin yaptığı işler yüzündendir. O, yine de çoğunu affeder."},{"n":31,"t":"Yeryüzünde O’nu aciz bırakamazsınız. Allah’tan başka bir dostunuz da yardımcınız da yoktur."},{"n":32,"t":"Denizde dağlar gibi akıp giden gemiler de O’nun ayetlerindendir."},{"n":33,"t":"Allah dilerse rüzgarı durdurur, gemiler denizin yüzünde durakalır. Elbette bunda çok sabreden, çok şükreden herkes için ibretler vardır."},{"n":34,"t":"Yahut yaptıkları yüzünden gemileri helak eder. Bir çoğunu da affeder."},{"n":35,"t":"Ayetlerimiz hakkında tartışanlar, kendileri için kaçacak bir yer olmadığını bilsinler."},{"n":36,"t":"Size verilen şeyler, dünya hayatının geçimidir. İnanıp Rabb’lerine güvenenler için Allah’ın yanında bulunanlar daha iyi ve daha kalıcıdır."},{"n":37,"t":"Onlar büyük günahlardan ve çirkin işlerden kaçınırlar; kızdıkları zaman da affederler."},{"n":38,"t":"Rabb’lerinin çağrısına gelirler, namaz kılarlar. Onların işleri aralarında danışma (İstişare) iledir. Kendilerine verdiğimiz rızıktan hayır için harcarlar."},{"n":39,"t":"Bir zulüm ve saldırıya uğradıkları zaman, yardımlaşarak kendilerini savunurlar."},{"n":40,"t":"Kötülüğün cezası, yine onun gibi bir kötülüktür. Kim affeder, barışırsa onun mükafatı Allah’a aittir. Doğrusu Allah zalimleri sevmez."},{"n":41,"t":"Zulüm gördükten sonra hakkını alan kimselerin aleyhine bir yol yoktur."},{"n":42,"t":"İnsanlara zulmedenlere, yeryüzünde haksız yere taşkınlık edenlere karşı durulmalıdır. İşte can yakıcı azap bunlaradır."},{"n":43,"t":"Fakat kim sabreder kendisine yapılan kötülüğü affederse şüphesiz bu hareketi, yapılmaya değer işlerdendir."},{"n":44,"t":"«Geri dönecek bir yol var mı?» dediklerini görürsün."},{"n":45,"t":"«İşte asıl ziyana uğrayanlar, kıyamet günü kendilerini ve ailelerini ziyana sokanlardır» derler. Bakın, gerçekten zalimler sürekli bir azap içindedirler."},{"n":46,"t":"Onların, Allah’tan başka kendilerine yardım edecek dostları yoktur. Allah kimi sapıklıkta bırakırsa artık onun için bir kurtuluş yolu yoktur."},{"n":47,"t":"Allah’tan, geri çevrilmesi imkansız bir gün gelmeden önce, Rabb’inizin çağrısına uyun. Çünkü o gün hiçbiriniz sığınacak bir yer bulamazsınız, inkar da edemezsiniz."},{"n":48,"t":"Eğer yüz çevirirlerse üzülme; biz seni onların üzerine bekçi göndermedik. Sana düşen sadece duyurmaktır. Biz insana katımızdan bir rahmet tattırdığımız zaman ona sevinir. Ancak elleriyle yaptıkları yüzünden başlarına bir kötülük gelirse işte o zaman görürsün ki insan gerçekten pek nankördür."},{"n":49,"t":"Göklerin ve yerin hükümranlığı Allah’ındır. Dilediğini yaratır, dilediğine kız çocuğu, dilediğine de erkek çocuğu verir."},{"n":50,"t":"Yahut hem kız hem erkek çocuk verir. Dilediğini de kısır yapar. O herşeyi bilendir, herşeye gücü yetendir."},{"n":51,"t":"Allah bir insanla ancak vahiy yoluyla veya perde arkasında konuşur. Yahut bir elçi gönderip izniyle ona dilediğini vahyeder. O, yücedir ve her yaptığı yerindedir."},{"n":52,"t":"İşte böylece sana da emrimizle Kur’an’ı vahyettik. Sen kitap nedir, iman nedir bilmezdin. Fakat biz onu (Kitab’ı), bir nur yaptık. Kullarımızdan dilediğimizi, onunla hidayete iletiyoruz. Ve şüphesiz ki sen, doğru yola götürüyorsun."},{"n":53,"t":"Göklerde ve yerde bulunan herşeyin sahibi Allah’ın yoluna. Dikkat edin, bütün işler sonunda Allah’a döner."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Apaçık Kitab’a andolsun ki."},{"n":3,"t":"Düşünüp anlamanız için onu Arapça bir Kur’an yaptık."},{"n":4,"t":"O, katımızda bulunan ana kitabdadır. Şanı yücedir, hikmetle doludur."},{"n":5,"t":"Siz, haddi aşan kimseler oldunuz diye, sizi Kur’an’la uyarmaktan vaz mı geçelim?"},{"n":6,"t":"Biz, sizden önce gelenlere nice peygamberler gönderdik."},{"n":7,"t":"Onlar, kendilerine gelen her peygamberi mutlaka alaya alırlardı."},{"n":8,"t":"Bizde bunlardan daha güçlü oları o kavimleri helak ettik. Öncekilere dair nice misaller geçmiştir."},{"n":9,"t":"«Gökleri ve yeri kim yarattı?» diye sorsan elbette «Onları, çok üstün, çok bilen Allah yarattı» diyeceklerdir."},{"n":10,"t":"O; size yeri beşik kılan ve doğru gitmeniz için yeryüzünde size yollar gösterendir."},{"n":11,"t":"Gökten bir ölçüye göre suyu indiren O’dur. Biz onunla kupkuru ölü bir memlekete hayat verdik. İşte böyle sizde tekrar diriltileceksiniz."},{"n":12,"t":"Bütün çiftleri Allah yarattı, size bineceğiniz gemiler ve hayvanlar var etti."},{"n":13,"t":"Böylece onların sırtına binip, üzerlerine yerleşince, Rabbinizin nimetini anarak «Bunu bizim hizmetimize veren Allah’ın şanı yücedir, yoksa biz bunlara güç yetiremezdik» demeniz içindir."},{"n":14,"t":"Biz şüphesiz Rabbimize döneceğiz deyin."},{"n":15,"t":"Böyle iken kafirler Allah’a çocuk isnad ettiler. İnsan gerçekten apaçık nankördür, gerçeği inkar eder."},{"n":16,"t":"Demek Allah, yarattıkları arasından kızları kendisine alıp da oğulları size verdi öyle mi?"},{"n":17,"t":"Fakat Rahman olan Allah’a isnad ettiği kız evlat kendilerinden birine müjdelenince, o kimsenin yüzü simsiyah kesilir, öfkesinden yutkunup durur."},{"n":18,"t":"Demek süs içinde yetiştirilerek mücadele gücü olmayanı mı Allah’a isnad ediyorsunuz?"},{"n":19,"t":"Onlar Rahman’ın kulları olan melekleri de dişi saydılar. Acaba meleklerin yaratılışını mı gördüler? Onların bu şahidlikleri yazılacak ve sorguya çekilecekler."},{"n":20,"t":"\"Eğer Rahman dilemiş olsaydı biz onlara kulluk etmezdik.\" Buna dair bir bilgileri yoktur onların. Onlar sadece vehimde bulunuyorlar."},{"n":21,"t":"Yoksa bundan önce onlara bir kitab verdik de ona mı sarılıyorlar?"},{"n":22,"t":"Hayır! Sadece «Biz babalarımızı bu din üzerinde bulduk, biz de onların izinde gidiyoruz» dediler."},{"n":23,"t":"«Biz babalarımızı bir din üzerinde bulduk, biz de onların izlerine uyarız» dediler."},{"n":24,"t":"«Doğrusu biz seninle gönderileni inkar ediyoruz.»"},{"n":25,"t":"Biz de onlardan intikam aldık. Bak, yalanlayanların sonu nasıl oldu?"},{"n":26,"t":"Bir zaman İbrahim babasına ve kavmine demişti ki; «Ben sizin taptıklarınızdan uzağım.»"},{"n":27,"t":"Ben yalnız beni yaratana taparım. Çünkü O, bana doğru yolu gösterecektir."},{"n":28,"t":"ve bu tevhid sözünün ardından kalıcı bir söz yaptı ki, insanlar Allah’a dönsünler."},{"n":29,"t":"Doğrusu bunları da, babalarını da kendilerine hak ve hakikatı açıklayan bir peygamber gelinceye kadar geçindirdim."},{"n":30,"t":"«Bu büyüdür biz onu tanımayız.» dediler."},{"n":31,"t":"«Bu Kur’an iki şehrin birinden bir büyük adama indirilmeli değil miydi?»"},{"n":32,"t":"Rabbinin rahmetini onlar mı paylaştırıyorlar? Dünya hayatında onların geçimliliklerini Biz taksim ettik; birbirlerine iş gördürmeleri için kimini ötekine derecelerle üstün kıldık. Rabbinin rahmeti, onların toplayıp yığdıklarından daha hayırlıdır."},{"n":33,"t":"İnsanlar küfürde birleşen bir tek ümmet olmayacak olsaydı, Rahman’ı inkar edenlerin evlerinin tavanları ve üzerine binip çıkacakları merdivenleri gümüşten yapardık."},{"n":34,"t":"Evlerinin kapılarını ve üzerlerine yaslanacakları koltukları da hep gümüşten yapardık."},{"n":35,"t":"ve nice süsler verirdik. Bütün bunlar sadece dünya hayatının geçici malından ibarettir. Ahiret nimeti ise, Rabbinin katında, Allah’ın azabından sakınıp rahmetine sığınanlara mahsustur."},{"n":36,"t":"Kim Rahman’ın Kur’an’ından yüz çevirirse ona, bir şeytanı arkadaş veririz ve o şeytan artık onun ayrılmaz dostudur."},{"n":37,"t":"O şeytanlar bunları doğru yoldan çıkardıkları halde bunlar doğru yolda olduklarını sanırlar."},{"n":38,"t":"«Keşke benimle senin aranda doğu ile batı arası kadar uzaklık olsaydı» der. Meğer ne kötü arkadaşmış."},{"n":39,"t":"İkiniz de zalim olduğunuz için bugün pişman olmanız size hiçbir fayda vermeyecektir. Çünkü siz azapta ortaksınız."},{"n":40,"t":"Ey Muhammed! Sen mi sağırlara işittireceksin, yahut kör ve apaçık sapıklıkta olanı doğru yola ileteceksin?"},{"n":41,"t":"Eğer biz seni alıp götürürsek (vefat ettirirsek) onlardan intikam alacağız."},{"n":42,"t":"Yahut onları tehdit ettiğimiz şeyi sana gösteririz. Bizim onlara gücümüz yeter."},{"n":43,"t":"Sen, sana vahyedilene sımsıkı sarıl. Zira sen, dosdoğru yoldasın."},{"n":44,"t":"Doğrusu bu Kur’an sana ve ümmetine bir öğüttür, ondan sorumlu tutulacaksınız."},{"n":45,"t":"Senden önce gönderdiğimiz peygamberlere sor. Biz Rahman olan Allah’tan başka tapılacak tanrılar mı yapmışız?"},{"n":46,"t":"«Ben alemlerin Rabbinin elçisiyim» demişti."},{"n":47,"t":"Onlara ayetlerimizi getirince, birden bire onlarla alay etmeye koyuldular."},{"n":48,"t":"Onlara biri diğerinden daha büyük olmayan hiçbir ayet göstermedik. Doğru yola dönmeleri için azaba uğrattık."},{"n":49,"t":"«Ey büyücü, bizim için Rabb’ine dua et, sende bulunan ahdi hürmetine bizi bağışlamasını dile, artık yola geleceğiz» dediler."},{"n":50,"t":"Fakat biz onlardan azabı kaldırınca sözlerinden dönmeye başladılar."},{"n":51,"t":"«Ey kavmim, Mısır mülkü ve şu altından akıp giden ırmaklar benim değil mi? Görmüyor musunuz?"},{"n":52,"t":"Yoksa ben, kendisi zayıf ve neredeyse söz anlatamayacak durumda bulunan şu adamdan daha hayırlı değil miyim?"},{"n":53,"t":"Ona altın bilezikler verilmeli, yahud yanında kendisiyle beraber yardımcı melekler gelmeli değil miydi?"},{"n":54,"t":"İşte Firavun bu şekilde kavmini küçümsedi. Onlar da ona boyun eğdiler. Çünkü onlar yoldan çıkmış bir kavimdi."},{"n":55,"t":"Bizi öfkelendirince onlardan intikam aldık, böyle hepsini suda boğduk."},{"n":56,"t":"Böylece onları, sonrakiler için hem bir örnek, hem de bir ibret yaptık."},{"n":57,"t":"Meryemoğlu İsa, bir misal olarak anlatılınca hemen kavmin yaygarayı bastı."},{"n":58,"t":"Bizim tanrılarımız mı hayırlı yoksa o mu? dediler. Bunu sana ancak tartışmak için söylediler. Öyle ya onlar, kavgacı bir toplumdur."},{"n":59,"t":"O, sadece kendisine nimet verdiğimiz ve İsrailoğullarına örnek kıldığımız bir kuldur."},{"n":60,"t":"Eğer biz dileseydik, sizin yerinize, yeryüzünde melekler yaratırdık da sonra yerinize geçerlerdi."},{"n":61,"t":"O kıyametin kopacağını gösterir bir ilimdir. O saatin geleceğinden hiç şüphe etmeyin, bana uyun. Doğru yol budur."},{"n":62,"t":"Şeytan sizi bundan alıkoymasın. Çünkü o, sizin için açık bir düşmandır."},{"n":63,"t":"«Size hikmetle ve ayrılığa düştüğünüz şeylerin bir kısmını açıklamak üzere geldim. Allah’a karşı gelmekten sakının, bana itaat edin.»"},{"n":64,"t":"Çünkü Allah benim de Rabbim, sizin de Rabbinizdir. O’na ibadet edin. İşte bu, doğru bir yoldur."},{"n":65,"t":"Ama aralarından çıkan gruplar, birbiriyle ihtilafa düştüler. Acı bir günün azabı karşısında vay o zulmedenlerin haline!"},{"n":66,"t":"Onlar illa o saatin kendilerinin hiç farkında olmadıkları bir sırada, ansızın başlarına gelmesini mi bekliyorlar?"},{"n":67,"t":"O gün takva sahipleri dışında, dost olanlar birbirlerine düşman olurlar."},{"n":68,"t":"\"Ey kullarım! Bugün size korku yoktur ve siz üzülmeyeceksiniz de.\""},{"n":69,"t":"Onlar, ayetlerimize inanmış ve müslüman olmuş kullarımdı."},{"n":70,"t":"Siz ve eşleriniz, ağırlanmış olarak cennete giriniz."},{"n":71,"t":"Onların önünde altın tepsiler ve kadehler dolaştırılır. Orada canların çektiği, gözlerin hoşlandığı herşey var. Ve siz, orada ebedi kalacaksınız."},{"n":72,"t":"İşte yaptıklarınıza karşılık size miras verilen cennet budur."},{"n":73,"t":"Orada sizin için bol bol meyveler vardır, onlardan yersiniz"},{"n":74,"t":"Suçlular, cehennem azabında ebedi kalacaklardır."},{"n":75,"t":"Kendilerinden azab hiç hafiflemeyecektir. Onlar azab içinde ümitsizdirler."},{"n":76,"t":"Biz onlara zulmetmedik; fakat onlar kendileri zalim idiler"},{"n":77,"t":"«Ey Malik! Rabbin bizim işimizi bitirsin!» diye seslenirler. Malik de «Siz böyle kalacaksınız» der."},{"n":78,"t":"Andolsun biz size hakkı getirdik; fakat sizin çoğunuz haktan hoşlanmıyorsunuz."},{"n":79,"t":"Yoksa bir işe mi karar verdiler? Doğrusu Biz de kararlıyız."},{"n":80,"t":"Yoksa bizim, kendilerinin sırlarını ve gizli konuşmalarını işitmediğimizi mi sanıyorlar? Aksine işitiriz ve yanlarındaki elçilerimiz yazmaktadırlar."},{"n":81,"t":"\"Eğer Rahmân’ın bir çocuğu olsaydı, ona kulluk edenlerin ilki ben olurdum.\""},{"n":82,"t":"Göklerin ve yerin Rabbi, Arş’ın da Rabbi olan Allah onların uydurdukları noksan sıfatlardan yücedir, münezzehtir."},{"n":83,"t":"Bırak onları, kendilerine söylenen günlerine kavuşuncaya kadar dalsın, oyalansınlar!"},{"n":84,"t":"Gökteki ilah da, yerdeki ilah da O’dur. O, hakimdir, alimdir."},{"n":85,"t":"Göklerin, yerin ve ikisi arasında bulunan herşeyin mülkü kendisine ait olan Allah yücedir. Kıyametin ilmi de O’nun yanındadır ve siz O’na döndürüleceksiniz."},{"n":86,"t":"Allah’tan başka tanrı diye yalvardıkları şeyler, şefaat gücüne ve yetkisine sahip değillerdir. Ancak bilerek Hakka şahidlik edenler bunun dışındadır."},{"n":87,"t":"Andolsun onlara «kendilerini kim yarattı?» diye sorsan, elbette «Allah» Derler. O halde nasıl haktan çeviriliyorlar?"},{"n":88,"t":"Resulullah’ın «Ya Rabbi! Bunlar inanmayan bir kavimdir» demesini de Allah biliyor."},{"n":89,"t":"Ey Muhammed! Sen şimdilik onlardan yüz çevir ve esenlik dile; yakında bileceklerdir."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Apaçık Kitab’a andolsun ki,"},{"n":3,"t":"Biz onu mübarek bir gecede indirdik. Çünkü Biz, insanları uyarmaktayız."},{"n":4,"t":"Her hikmetli iş o mübarek gecede ayırd edilir."},{"n":5,"t":"Bu katımızdan verilen her emirdir. Çünkü Biz elçi göndericiyiz."},{"n":6,"t":"Bu Rabbinden bir rahmettir. Allah, işitendir, bilendir."},{"n":7,"t":"Göklerin, yerin ve bu ikisinin arasındakilerin Rabbidir. Eğer gerçeği kesin bir şekilde bilebilecek kimselerseniz!"},{"n":8,"t":"O’ndan başka ilah yoktur, yaşatır, öldürür. Sizinde Rabbiniz, önceki atalarınızın da Rabbidir."},{"n":9,"t":"Fakat onlar şüphe içinde eğlenip duruyorlar."},{"n":10,"t":"Göğün gözle görülür bir duman getireceği günü gözetle."},{"n":11,"t":"Duman, insanları bürüyecektir. Bu, acı bir azabtır."},{"n":12,"t":"«Rabbimiz, bizden azabı kaldır, çünkü biz artık inanıyoruz» derler."},{"n":13,"t":"Artık onlar nasıl düşünüp öğüt alacaklar? Öğüt alma zamanı geçti. Oysa kendilerine gerçeği açıklayan bir elçi gelmişti."},{"n":14,"t":"Ondan yüz çevirdiler «Bu, deli görünümünde eğitilmiş biridir» dediler."},{"n":15,"t":"Biz sizden azabı birazcık kaldıracağız, fakat siz yine inkara döneceksiniz."},{"n":16,"t":"O gün büyük bir şiddetle çarparız; zira Biz öç alıcıyız!"},{"n":17,"t":"Andolsun, onlardan önce Firavun toplumuna da imkanlar vererek sınamıştık. Onlara saygın bir peygamber gelmişti."},{"n":18,"t":"Ey Allah’ın kulları! Bana gelin, doğrusu ben size gönderilmiş güvenilir bir elçiyim."},{"n":19,"t":"Allah’a karşı büyüklük taslamayın. Ben size apaçık bir delil getiriyorum."},{"n":20,"t":"Ben, beni taşlayıp öldürmenizden, benim de Rabbim sizin de Rabbiniz olan Allah’a sığındım."},{"n":21,"t":"Eğer bana inanmadınızsa bari yolumdan çekilin."},{"n":22,"t":"«Bunlar, suç işleyen bir toplum» diye Rabbine dua etti."},{"n":23,"t":"«Kullarımı geceleyin yola çıkar; şüphesiz takip olunacaksınız.»"},{"n":24,"t":"Denizi yarıp toplumunu geçirdikten sonra olduğu gibi açık bırak. Çünkü onlar boğulacak bir ordudur."},{"n":25,"t":"Onlar geride nice şeyler bıraktılar; bahçeler, çeşmeler."},{"n":26,"t":"Ekinler, güzel makamlar!"},{"n":27,"t":"Ve zevkü sefa sürecekleri nice nimetler!"},{"n":28,"t":"İşte böyle oldu ve biz onları başka bir topluma miras verdik."},{"n":29,"t":"Onlara gök ve yer ağlamadı ve kendilerine mühlet de verilmedi."},{"n":30,"t":"Andolsun biz, İsrailoğullarını o küçültücü azaptan kurtardık"},{"n":31,"t":"Yani Firavun’dan. Çünkü o haddi aşanlardan bir zorba idi."},{"n":32,"t":"Andolsun, biz bilerek İsrâiloğulları’nı çağların insanlarına tercih ettik."},{"n":33,"t":"Onlara, içinde açık bir imtihan bulunan ayetler verdik."},{"n":34,"t":"Bu inkarcılar da diyorlar ki:"},{"n":35,"t":"Bir kez öleceğiz ve herşey bitecek. Biz dirilecek değiliz."},{"n":36,"t":"Doğru söylüyorsanız, babalarımızı getirin."},{"n":37,"t":"Peki onlar mı hayırlı, yoksa Tubba kavmi ve onlardan önce gelen kavimler mi? Suç işledikleri için biz onların hepsini helak ettik."},{"n":38,"t":"Biz gökleri, yeri ve bunlar arasında bulunanları eğlenmek için yaratmadık!"},{"n":39,"t":"Onları sadece hak ilkesine dayalı olarak yarattık. Fakat onların çoğu bilmiyorlar."},{"n":40,"t":"Hüküm günü, hepsinin buluşacağı gündür."},{"n":41,"t":"O gün, dostun dosta hiçbir faydası olmaz, yardım da görmezler."},{"n":42,"t":"Yalnız Allah’ın merhamet ettiği bunun dışındadır. Şüphesiz Allah, üstündür, esirgeyendir."},{"n":43,"t":"Zakkum ağacı."},{"n":44,"t":"Günahkarların yemeğidir."},{"n":45,"t":"Tıpkı erimiş madenler gibi karınlarında kaynar."},{"n":46,"t":"Sıcak suyun kaynaması gibi."},{"n":47,"t":"Tutun onu, cehennemin ortasına sürükleyin."},{"n":48,"t":"Sonra başının üzerine kaynar su azabından dökün."},{"n":49,"t":"Tad bakalım, hani şerefli olan, üstün olan yalnız sendin?"},{"n":50,"t":"İşte o kuşkulanıp durduğunuz şey budur!"},{"n":51,"t":"Müttakiler ise güvenli bir makamdadır."},{"n":52,"t":"Bahçelerde ve çeşme başlarında."},{"n":53,"t":"İnce ipekten ve parlak atlastan giysiler giyerek karşılıklı otururlar."},{"n":54,"t":"Ayrıca onları, iri gözlü hurilerle de evlendirmişizdir."},{"n":55,"t":"Orada, güven içinde, her meyveyi isterler."},{"n":56,"t":"Orada ilk ölümden başka ölüm tatmazlar, sürekli yaşarlar ve Allah onları cehennem azabından korumuştur."},{"n":57,"t":"Cehennemden korunmaları Rabbinden bir lütuftur. İşte büyük kurtuluş budur."},{"n":58,"t":"Biz o Kur’an’ı senin dilinde indirerek kolaylaştırdık ki, düşünüp öğüt alsınlar."},{"n":59,"t":"Öyleyse bekle, onlar da beklemektedirler."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Kitab’ın indirilmesi, üstün iradeli ve her yaptığını bir hikmete göre yapan Allah’ın katındandır."},{"n":3,"t":"Göklerde ve yerde müminler için nice dersler vardır."},{"n":4,"t":"Sizin yaratılmanızda ve canlıların yeryüzünde yayılmasında, kesin olarak inanan kimseler için ibretler vardır."},{"n":5,"t":"Gecenin ve gündüzün birbiri ardına gelmesinde, gökten, Allah’ın rızık vermek için yağmur indirip, yeri onunla ölümünden sonra diriltmesinde, rüzgarı estirmesinde aklını kullanan kimseler için dersler vardır."},{"n":6,"t":"İşte bunlar Allah’ın ayetleridir. Bunları sana hak ilkesine göre okuyoruz. Allah’tan ve O’nun ayetlerinden sonra hangi söze inanacaklar"},{"n":7,"t":"Her yalancı, günah yüklü kimsenin vay haline."},{"n":8,"t":"Allah’ın ayetlerinin kendisine okunduğunu işitir de sonra büyüklük taslayarak sanki onları hiç işitmemiş gibi küfründe direnir. Onu, acı bir azabla müjdele."},{"n":9,"t":"Ayetlerimizden birşey öğrendiği zaman onunla alay eder. İşte böyleleri için alçaltıcı azab vardır."},{"n":10,"t":"Cehennem onların peşindedir. Kazandıkları şeyler de, Allah’ı bırakıp edindikleri dostlar da onlara hiçbir fayda vermez. Onlar için büyük bir azap vardır."},{"n":11,"t":"İşte doğru yolu gösteren bu Kur’an’dır. Rabblerinin ayetlerini tanımayanlar için çok kötü, acı bir azap vardır."},{"n":12,"t":"Allah emri gereğince denizde yüzmek üzere gemileri, lütfedip verdiği rızkı aramanız için denizi buyruğunuz altına vermiştir. Belki artık şükredersiniz."},{"n":13,"t":"Gökte olanları, yerde olanları, hepsini sizin buyruğunuz altına vermiştir. Doğrusu bunlarda, düşünen kimseler için dersler vardır."},{"n":14,"t":"Allah’ın, her milletin yaptıklarının karşılığını vereceği günlerinin geleceğine inanmayanları bağışlasınlar."},{"n":15,"t":"Kim iyi bir iş yaparsa faydası kendisinedir ve kim kötülük yaparsa zararı kendisinedir. Sonra Rabbinize döndürüleceksiniz."},{"n":16,"t":"Andolsun ki biz İsrailoğullarına kitab, hüküm ve peygamberlik verdik; onları temiz şeylerle rızıklandırdık; onları dünyada üstün kıldık."},{"n":17,"t":"Din konusunda onlara açık deliller verdik. Onlar kendilerine bilgi geldikten sonra sadece aralarındaki çekememezlik yüzünden ayrılığa düştüler. Şüphesiz, Rabbin kıyamet günü, ayrılığa düştükleri şeylerde onlar arasında hüküm verecektir."},{"n":18,"t":"Sonra ey Muhammed! Sana da insanların uyacakları bir hayat sistemi (şeriat) verdik. Sen ona uy, bilmeyenlerin arzularına uyma."},{"n":19,"t":"Çünkü onlar, Allah’tan gelecek hiçbir şeyi senden savamazlar. Zalimler birbirlerinin dostlarıdır. Allah ta müttakilerin dostudur."},{"n":20,"t":"Bu Kur’an, insanlara kurtuluş yollarını gösteren kanıtlar sunmaktadır; kesin olarak inananlara kılavuz ve rahmettir."},{"n":21,"t":"Yoksa kötülükleri işleyen kimseler kendilerini inanıp iyi ameller işleyenlerle bir tutacağımızı mı sandılar? Yaşamaları ve ölmeleri bir olacak öyle mi? Ne kötü hüküm veriyorlar."},{"n":22,"t":"Allah, gökleri ve yeri hak ilkesine dayalı olarak yarattı, ta ki herkes kazandığının karşılığını görsün. Onlara haksızlık edilmez."},{"n":23,"t":"Ey Muhammed! Heva ve hevesini tanrı edinen Allah’ın bir bilgiye dayalı olarak şaşırttığı, kulağını ve kalbini mühürlediği, gözünü perdelediği kimseyi gördün mü? Onu Allah’tan başka kim doğru yola eriştirebilir? Hala anlamıyor musunuz?"},{"n":24,"t":"«Hayat, ancak bu dünyadaki hayatımızdır. Ölürüz ve yaşarız; bizi ancak zaman yok eder» derler. Onların bu hususta bir bilgisi yoktur; sadece böyle zannederler."},{"n":25,"t":"«Doğru sözlü iseniz babalarımızı getirin bakalım!» demek olur."},{"n":26,"t":"«Sizi Allah diriltir, sonra öldürür, sonra sizi şüphe götürmeyen kıyamet gününde toplar. Fakat insanların çoğu bilmezler.»"},{"n":27,"t":"Göklerin ve yerin hükümranlığı Allah’ındır. Kıyamet kopacağı gün, işte o gün batıl sözlere uymuş olanlar hüsranda kalırlar."},{"n":28,"t":"«Bugün size işlediğinizin karşılığı verilecektir.»"},{"n":29,"t":"İşte kitabımız aleyhinize konuşuyor, gerçeği söylüyor. Çünkü biz yaptıklarınızı yazıyorduk.."},{"n":30,"t":"İnanıp iyi işler yapanlara gelince; Rabbleri onları rahmetinin kapsamına alır. İşte apaçık kurtuluş budur."},{"n":31,"t":"«Ayetlerim size okunurdu, fakat siz büyüklük tasladınız ve suçlu bir toplum oldunuz değil mi?»"},{"n":32,"t":"\"Kıyametin ne olduğunu bilmiyoruz. Ancak birtakım tahminlerde bulunuyoruz. Onun hakkında kesin bir bilgi elde etmiş değiliz.\""},{"n":33,"t":"Yaptıklarının kötülükleri onlara göründü ve alay edip durdukları şey onları kuşattı."},{"n":34,"t":"«Siz bu günümüze kavuşacağınızı nasıl unutmuşsanız, biz de bugün sizi unuttuk. Yeriniz ateştir, yardımcılarınız da yoktur.»"},{"n":35,"t":"Bunun böyle olmasının sebebi \"Sizin Allah’ın ayetlerini alaya almanız ve dünya hayatının sizi aldatmış olmasıdır.\" O gün oradan çıkarılmayacaklar ve özür de aranmayacaktır onlardan."},{"n":36,"t":"Hamd, göklerin Rabbi, yerin Rabbi ve bütün alemlerin Rabbi olan Allah’a mahsustur."},{"n":37,"t":"Göklerde yerde ululuk, yalnız O’na aittir. O, üstün iradelidir, her yaptığını bir hikmete göre yapar."}],[{"n":1,"t":"Ha, Mim."},{"n":2,"t":"Bu Kitab’ın indirilişi aziz, hakim olan Allah katındandır."},{"n":3,"t":"Biz, gökleri, yeri ve ikisinin arasında bulunanları, ancak gerçek üzere ve belirli bir süre için yarattık; inkar edenler, uyarıldıkları şeylerden yüz çevirmektedirler."},{"n":4,"t":"«Allah’ı bırakıp taptığınız şeyleri gördünüz mü? Bana gösterin, onlar yerden neyi yarattılar? Yoksa göklerin yaratılışında onların bir ortağı mı var? Eğer doğru iseniz bundan önce inmiş olan bir kitap, yahut bir bilgi kalıntısını getirin.»"},{"n":5,"t":"Allah’ı bırakıp da kıyamet gününe kadar kendisine cevap veremeyecek şeylere yalvarandan daha sapık kim olabilir? Oysa onlar, bunların yalvardıklarından habersizdirler."},{"n":6,"t":"İnsanlar kıyamet günü toplatılınca, putları onlara düşman olurlar ve tapınmalarını inkar ederler."},{"n":7,"t":"«Bu, apaçık bir büyüdür» derler."},{"n":8,"t":"«Eğer ben onu uydurduysam, beni Allah’a karşı hiçbir şekilde savunamazsınız. O Kur’an için yaptıklarınız taşkınlıkları daha iyi bilir. Benimle sizin aranızda şahid olarak Allah yeter. O, bağışlayandır, merhamet edendir.»"},{"n":9,"t":"«Ben Peygamberlerin ilki değilim; benim ve sizin başınıza gelecekleri bilmem; ben sadece bana vahyedilene uyuyorum. Ben sadece apaçık bir uyarıcıyım.»"},{"n":10,"t":"«Hiç düşündünüz mü? Eğer bu Kur’an Allah katından olduğu halde siz onu tanımamışsanız; İsrailoğullarından bir şahid de bunun benzerini Tevrat’ta görüp inandığı halde siz inanmaya tenezzül etmemişseniz durumunuz nice olur? Şüphesiz Allah, zalim bir toplumu doğru yola iletmez.»"},{"n":11,"t":"«Eğer İslam iyi bir şey olsaydı, onlar ona uymada bizi geçemezlerdi» derler. Onlar doğru yola girmedikleri için de «Bu, eski bir uydurmadır» derler."},{"n":12,"t":"Kur’an’dan önce, Musa’nın kitabı Tevrat, bir rahmet ve rehberdi. Bu Kur’an, zulmedenleri uyarmak ve güzel davrananlara müjde olmak üzere arap diliyle indirilmiş, kendinden öncekileri doğrulayan bir Kitap’tır."},{"n":13,"t":"Doğrusu, «Rabbimiz Allah’tır» deyip, sonra da dosdoğru gidenlere korku yoktur, onlar üzülmeyeceklerdir."},{"n":14,"t":"İşte onlar cennetliklerdir; yaptıklarına karşılık olarak, içinde temelli kalacaklardır."},{"n":15,"t":"«Ya Rabbi, dedi, beni, bana ve anama, babama verdiğin nimete şükretmeye razı olacağın yararlı işler yapmaya sevk eyle. Benim için de zürriyetim için de iyiliği devam ettir. Ben sana döndüm ve elbette ki ben müslümanlardanım.»"},{"n":16,"t":"Onlar öyle kişilerdir ki, yaptıklarının en iyisini onlardan kabul ederiz ve onların günahlarını bağışlarız, cennet halkı arasındadırlar. Bu dünyada kendilerine söylenen doğru sözün gerçekleşmesidir."},{"n":17,"t":"«Öf size, benden önce nice nesiller gelip geçmiş iken benim öldükten sonra dirilip çıkarılacağımı mı bana va’dediyorsunuz?» dedi. Onlarsa Allah’a sığınarak «Yazık sana, etme, gel inan; Allah’ın sözü gerçektir» derken O; «Bu, eskilerin masallarından başka birşey değildir» der."},{"n":18,"t":"İşte onlar da kendilerine azab sözü gerekli olmuş kimselerdir. Kendilerinden önce geçen cin ve insan toplulukları arasında azab içinde bulunacaklardır. Gerçekten onlar ziyana uğrayanlardır."},{"n":19,"t":"Herkesin yaptıklarına göre dereceleri vardır. Allah, onlara yaptıklarının karşılığını verir, asla kendilerine haksızlık yapılmaz."},{"n":20,"t":"«Dünya hayatında bütün güzel şeylerinizi zayi ettiniz; onların zevkini sürdürdünüz. Yeryüzünde haksız yere büyüklük taslamanızdan ve yoldan çıkmanızdan ötürü bugün, alçaltıcı bir azab ile cezalandırılacaksınız.»"},{"n":21,"t":"Ey Muhammed! Ad kavminin kardeşi Hud’u an; ondan önce ve sonra, «Allah’tan başkasına kulluk etmeyin» diyen nice uyarıcılar gelmişken, Ahkaf bölgesindeki kavmini uyarmış, «Doğrusu sizin için büyük günün azabından korkuyorum» demişti."},{"n":22,"t":"«Sen bizi tanrılarımızdan çevirmek için mi geldin? Doğrulardan isen bizi tehdit ettiğin şeyi getir.»"},{"n":23,"t":"«Azabın ne zaman geleceğine dair bilgi, ancak Allah katındadır. Ben görevlendirildiğim şeyi size duyuruyorum; fakat sizi cahillik eden bir kavim görüyorum.»"},{"n":24,"t":"Nihayet azabın ufukta geniş bir bulut halinde vadilerine doğru geldiğini görünce «Bu, bize yağmur yağdıracak bir buluttur» dediler. Hayır, o sizin acele gelmesini istediğiniz şey, içinde acı azab bulunan bir rüzgardır."},{"n":25,"t":"Rabb’inin emriyle herşeyi yıkar, mahveder. Derken onlar o hale geldiler ki evlerinden başka birşey görünmez oldu. İşte biz suç işleyen toplumu böyle cezalandırırız."},{"n":26,"t":"Onlara size vermediğimiz servet ve kuvvet vermiştik, onlara kulaklar, gözler ve gönüller yaratmıştık. Fakat ne kulakları ne gözleri ne de gönülleri kendilerine bir yarar sağlamadı. Zira düşünüp ibret almıyorlardı, tersine bile bile Allah’ın ayetlerini inkar ediyorlar. Ve alay edip durdukları şey kendilerini kuşatıverdi."},{"n":27,"t":"Andolsun, Biz çevrenizdeki kentleri de yok ettik ve belki küfredenlerden dönerler diye ayetleri tekrar tekrar açıkladık."},{"n":28,"t":"O zamanlar, Allah’ı bırakıp da O’na yakınlık sağlamak için edindikleri tanrılar kendilerine yardım etmeli değil miydi? Hayır, tanrılar onlardan uzaklaştılar. Bu, onların yalanı ve uydurdukları şeydir."},{"n":29,"t":"Bir zamanlar cinlerden bir topluluğu Kur’an dinlemek üzere sana yöneltmiştik. Ona geldiklerinde «Susun dinleyin» dediler. Kur’an okuması bitince uyarıcılar olarak kavimlerine döndüler."},{"n":30,"t":"«Ey kavmimiz, dediler, biz Musa’dan sonra indirilen kendinden öncekini doğrulayan, Hakk’a ve doğru yola götüren bir Kitab dinledik."},{"n":31,"t":"Ey kavmimiz, Allah’ın davetçisine uyun ve O’na inanın ki Allah günahlarınızdan bir kısmını bağışlasın ve sizi, acı bir azabdan korusun."},{"n":32,"t":"Kim Allah’ın davetçisine uymazsa, yeryüzünde başına inecek belaya engel olamaz. Onlar apaçık bir sapıklık içindedirler."},{"n":33,"t":"Gökleri ve yeri yaratan, bunları yaratmakla yorulmayan Allah’ın, ölüleri diriltmeye de kadir olduğunu görmediler mi? Evet O, herşeye kadirdir."},{"n":34,"t":"«Nasıl bu gerçek değil miymiş?» der. «Evet. Rabb’imizin hakkı için gerçekmiş!» derler. «Öyleyse inkar etmenizden dolayı azabı tadın!» der."},{"n":35,"t":"O halde peygamberlerden azim sahibi olanların sabrettiği gibi sen de sabret. Onlar hakkında acele etme, onlar va’dedildikleri azabı gördükleri gün sanki dünyada gündüzün sadece bir saat kadar kaldıklarını sanırlar. Bu, bir tebliğdir. Yoldan çıkmışlardan başkası helak edilir mi hiç?"}],[{"n":1,"t":"Allah, inkar edip kendisinin yoluna engel olanların işlerini boşa çıkarmıştır."},{"n":2,"t":"İnanıp iyi ameller işleyenlerin, Rabbleri tarafından Muhammed’e indirilen gerçeğe inananların da günahlarını örtmüş ve hallerini düzeltmiştir."},{"n":3,"t":"Bunun sebebi, inkar edenlerin batıla uymaları, inananların da Rablerinden gelen hakka uymuş olmalarındandır. İşte Allah, onların durumlarını, insanlara böyle anlatır."},{"n":4,"t":"İnkar edenlerle karşılaştığınız zaman boyunlarını vurun. Nihayet onları iyice vurup sindirince bağı sıkıca bağlayın (onları esir alın). Savaş sona erince de artık ya karşılıksız veya fidye karşılığı salıverin. Allah dileseydi onlardan başka türlü de öç alabilirdi. Bunun öyle olması kiminizi kiminizle denemek içindir. Ancak kendi yolunda ölenlerin yaptıklarını boşa çıkarmaz."},{"n":5,"t":"Allah onları hidayete iletecek ve durumlarını düzeltecek."},{"n":6,"t":"Onları dünyada iken tanıttığı cennete koyar."},{"n":7,"t":"Ey inananlar! Siz Allah’ın dinine yardım ederseniz, O da size yardım eder, ayaklarınızı savaşta sabit kılar."},{"n":8,"t":"İnkar edenlere gelince, onların hakkı yıkımdır. Allah, onların yaptıklarını boşa çıkarmıştır."},{"n":9,"t":"Bu onların Allah’ın indirdiğine nefret duymaları yüzünden olacaktır. Bu sebeple Allah, onların bütün yapıp ettiklerini değersiz hale getirecektir."},{"n":10,"t":"Yeryüzünde dolaşıp kendilerinden öncekilerin sonlarının nasıl olduğuna bakmazlar mı? Allah onları yere geçirmiştir; inkarcılara da onların başına gelenin benzerleri vardır."},{"n":11,"t":"Çünkü Allah inananların sahibidir. Kafirlerin ise sahibi yoktur."},{"n":12,"t":"Doğrusu Allah, inanıp iyi işler yapanları, altlarından ırmaklar akan cennetlere sokar, inkar edenler ise dünya hayatında zevklenirler, hayvanların yediği gibi yerler. Onların yeri ateştir."},{"n":13,"t":"Biz, halkı seni yurdundan çıkaran şehirden daha kuvvetli nice şehirleri yok ettik, fakat onlara bir yardım eden çıkmadı."},{"n":14,"t":"Rabbinin katından bir belgesi olan kimse, kötü işi kendisine güzel gösterilen ve kötü arzularına uyan kimse gibi olur mu?"},{"n":15,"t":"İçinde bozulmayan sudan ırmaklar, tadı değişmeyen sütten ırmaklar, içenlere lezzet veren şaraptan ırmaklar ve süzme baldan ırmaklar vardır. Onlar için orada her türlü meyve, Rablerinden de bağışlanma vardır. Bunların durumu, ateşte ebedi kalan ve bağırsaklarını parça parça edecek kaynar su içirilen kimselerin durumu gibi olur mu hiç?"},{"n":16,"t":"Ey Muhammed! Onların içinde seni dinleyenler vardır; sonra senin yanından çıkınca, bilgili kimselere «Az önce ne demişti?» diye sorarlar. İşte bunlar, Allah’ın kalplerini mühürlemiş olduğu, kendi heveslerine uyan kimselerdir."},{"n":17,"t":"Hidayeti bulanlara gelince, Allah onların hidayetlerini artırır ve onlara takvasını (ateşten nasıl korunacaklarını) öğretir."},{"n":18,"t":"Onlar kıyamet gününün ansızın gelip çatmasını mı bekliyorlar? İşte onun belirtileri geldi. O uyarıldıkları saat kendilerine gelip çatınca öğüt almaları neye yarar?"},{"n":19,"t":"Ey Muhammed! Allah’tan başka ilah olmadığını bil ve kendi günahına, inanan erkeklerin ve inanan kadınların günahları için Allah’tan mağfiret dile. Allah, gezip dolaştığınız ve duracağınız yeri bilir."},{"n":20,"t":"İnananlar «Keşke cihad hakkında bir sure indirilmiş olsaydı!» derler. Fakat hükmü açık bir sure indirilip de onda savaştan söz edilince, kalplerinde hastalık bulunanların sana ölümden bayılıp düşen kimsenin bakışı gibi baktıklarını görürsün. Oysa onlara düşen:"},{"n":21,"t":"İtaat etmek ve güzel söz söylemektir. İş ciddiye bindiği zaman Allah’a sadakat gösterselerdi, elbette kendileri için daha hayırlı olurdu."},{"n":22,"t":"\"Durumunuz bu iken, ey münafıklar, iktidarı ele geçirirseniz yeryüzünde bozgunculuk çıkarmanız ve akrabalık bağlarını koparmanız sizden beklenmez mi?\""},{"n":23,"t":"İşte bunlar, Allah’ın kendilerini lanetlediği, bu yüzden kendilerini sağır ve gözlerini kör kıldığı kimselerdir."},{"n":24,"t":"Onlar Kur’an’ı düşünmüyorlar mı? Yoksa kalpleri kilitli mi?"},{"n":25,"t":"Şüphesiz ki kendilerine doğru yol belli olduktan sonra, ona arka dönenleri, şeytan sürüklemiş ve kendilerine ümit vermiştir."},{"n":26,"t":"’Bazı önemli planları uygulamada, biz sizinle işbirliği yapacağız.’ demeleri sebebiyledir. Allah onların gizli konuşmalarını, halkı yanıltan fısıltılar yayarak yaptıkları faaliyetleri biliyor."},{"n":27,"t":"Ya melekler onların yüzlerine ve sırtlarına vurarak canlarını alırken durumları nasıl olacak?"},{"n":28,"t":"Bu, Allah’ı gazaplandıran şeye uymaları ve O’nun rızasından hoşnut olmamalarından ötürüdür. Allah ta onların işlerini boşa çıkarmıştır."},{"n":29,"t":"Yoksa, kalplerinde hastalık olanlar, Allah’ın onların kinlerini dışarı vurmayacağını mı sandılar?"},{"n":30,"t":"Biz isteseydik onları sana gösterirdik de, sen onları yüzlerinden tanırdın. Andolsun ki sen onları, konuşma üslubundan tanırsın. Allah bütün yaptıklarınızı bilir."},{"n":31,"t":"Andolsun ki içinizden cihad edenlerle sabredenleri belirleyinceye kadar ve söylediğiniz sözlerin doğru olup olmadığını açıklayıncaya kadar sizi imtihan edeceğiz."},{"n":32,"t":"Nankörlük edip Allah yolundan alıkoyanlar ve kendilerine doğru yol belli olduktan sonra peygamberi incitenler, Allah’a hiçbir zarar veremezler. Allah onların işlerini boşa çıkaracaktır."},{"n":33,"t":"Ey inananlar, Allah’a ve Rasulüne itaat edin, işlerinizi boşa çıkarmayın."},{"n":34,"t":"Nankörlük edip Allah yoluna engel olan, sonra kafir olarak ölenleri Allah affetmeyecektir."},{"n":35,"t":"Sakın gevşemeyin. Üstün olduğunuz halde barışa davet etmeyin. Allah sizinle beraberdir. O amellerinizi asla eksiltmez."},{"n":36,"t":"Doğrusu dünya hayatı ancak oyun ve eğlencedir. Eğer iman eder sakınırsanız Allah size mükafatlarını verir ve sizden mallarınızın tümünü sarf etmenizi istemez."},{"n":37,"t":"Eğer sizden onları isteyip de sizi zorlasa, cimrilik edecektiniz. O da kinlerinizi ortaya çıkaracaktı."},{"n":38,"t":"İşte sizler, Allah yolunda harcamaya çağrılıyorsunuz; fakat içinizden kiminiz cimrilik ediyor. Kim cimrilik ederse o ancak kendisine cimrilik eder. Allah zengindir, sizler fakirsiniz. Eğer yüz çevirecek olursanız, yerinize başka bir toplum gelir de onlar sizin gibi olmazlar."}],[{"n":1,"t":"Biz sana apaçık fetih verdik."},{"n":2,"t":"Allah böylece, senin geçmiş ve gelecek günahlarını bağışlar, sana olan nimetini tamamlar, seni doğru yola iletir."},{"n":3,"t":"Ve sana şanlı bir zaferle yardım eder."},{"n":4,"t":"İnananların, imanlarını kat kat artırmaları için, kalblerine güven indiren O’dur. Göklerdeki ve yerdeki ordular Allah’ındır. Allah bilendir, Hakim olandır."},{"n":5,"t":"İnanan erkek ve kadınları, içinde temelli kalacakları, içinden ırmaklar akan cennetlere koyar, onların kötülüklerini örter. Allah katında büyük kurtuluş budur."},{"n":6,"t":"İnananlara yardım etmez diye Allah hakkında kötü zanda bulunan iki yüzlü erkek ve kadınlar, puta tapan erkek ve kadınlara Allah azab etsin, kötü zanları kendi başlarına gelsin! Allah onlara gazab etmiş onları lanetlemiş ve cehennemi kendilerine hazırlamıştır. Ne kötü dönüş yeridir."},{"n":7,"t":"Göklerdeki ve yerdeki ordular Allah’ındır. Allah güçlü olandır, Hakim olandır."},{"n":8,"t":"Biz seni şahid, müjdeleyici ve uyarıcı olarak gönderdik."},{"n":9,"t":"Ki Allah’a ve Resulüne inanasınız O’nun dinini destekleyesiniz. O’na saygı gösteresiniz ve sabah akşam O’nu tesbih edip şanını yüceltesiniz."},{"n":10,"t":"Sana biat edenler, Allah’a biat etmektedirler. Allah’ın eli, onların ellerinin üzerindedir. Kim ahdini bozarsa, kendi aleyhine bozmuş olur. Ve kim Allah’a verdiği sözü tutarsa Allah ona büyük bir mükafat verecektir."},{"n":11,"t":"«Allah size bir zarar vermek dilemiş, yahut size bir fayda vermek istemiş olsa Allah’ın, sizin için dilediğine kim engel olabilir? Hayır hiç kimse engel olamaz, Allah yaptıklarınızdan haberdardır.»"},{"n":12,"t":"Aslında siz Peygamberin ve mü’minlerin ailelerine bir daha dönmeyeceklerini sanmıştınız. Bu sizin gönlünüze güzel göründü de kötü zanda bulundunuz ve helakı hak etmiş bir topluluk oldunuz."},{"n":13,"t":"Kim Allah’a ve Resulüne inanmazsa bilsin ki biz, kafirler için alevli bir ateş hazırlamışızdır."},{"n":14,"t":"Göklerin ve yerin mülkü Allah’ındır. O dilediğini bağışlar, dilediğine azab eder. Allah bağışlayandır, esirgeyendir."},{"n":15,"t":"«Hayır bizi kıskanıyorsunuz» diyecekler. Hayır aksine, kendileri ancak pek az söz anlayan kimsedirler."},{"n":16,"t":"«Siz yakında çok kuvvetli olan bir kavme karşı savaşmaya çağrılacaksınız. Onlarla savaşırsınız ya da müslüman olurlar. Eğer itaat ederseniz, Allah size güzel bir mükafat verir. Fakat önceden döndüğünüz gibi yine dönecek olursanız sizi acıklı bir azaba uğratır.»"},{"n":17,"t":"Gözleri görmeyen, topal ya da hasta olanların savaşa gitmemelerinde bir sorumluluk yoktur. Kim Allah’a ve Peygamberine itaat ederse, Allah onu, içlerinden ırmaklar akan cennetlere koyar. Kim yüz çevirirse onu can yakıcı azaba uğratır."},{"n":18,"t":"Andolsun ki, o ağacın altında sana biat ederken, Allah, mü’minlerden razı olmuştur. Allah onların gönüllerinden geçeni bildiği için onların üzerine huzur ve güven indirdi ve onlara yakın bir fetih verdi."},{"n":19,"t":"Yine onlara alacakları birçok ganimetler bahş eyledi. Allah üstündür, hüküm ve hikmet sahibidir."},{"n":20,"t":"Allah size elde edeceğiniz birçok ganimetler va’detti. Bunu size hemen vermiş ve insanların ellerini sizden çekmiştir ki bu mü’minlere bir işaret olsun ve Allah sizi dosdoğru yola iletsin."},{"n":21,"t":"Bundan başka sizin güç yetiremediğiniz, ancak Allah’ın sizin için kuşattığı ganimetler de vardır. Allah her şeye kadirdir."},{"n":22,"t":"Eğer kafirler sizinle savaşsalardı, arkalarına dönüp kaçarlardı, sonra ne bir koruyucu ne de bir yardımcı bulamazlardı."},{"n":23,"t":"Allah’ın öteden beri süregelen yasasıdır. Allah’ın yasasında bir değişme bulamazsın."},{"n":24,"t":"Mekke’nin ortasında, sizi onlara galip getirdikten sonra onların ellerini sizden, sizin ellerinizi onlardan çeken O’dur. Allah, yaptıklarınızı görmektedir."},{"n":25,"t":"Onlar inkar eden ve sizin Mescid-i Haram’ı ziyaretinizi ve bekletilen kurbanların yerine ulaşmasını men edenlerdir. Eğer Mekke’de kendilerini henüz tanımadığınız mü’min erkekler ve kadınları bilmeyerek eziyet etmenizi önlemek için, Allah savaşı önledi. Dilediklerine rahmet etmek için Allah böyle yapmıştır. Eğer onlar birbirinden ayrılsaydı elbette onlardan inkar edenleri, elemli bir azaba çarptırırdık."},{"n":26,"t":"O zaman inkar edenler, kalplerine öfke ve gayretin cahiliyye çağının öfke ve gayretini koymuşlardı. Allah da elçisine ve mü’minlere huzur ve güveni indirdi; onları takva sözüne tutunmalarını sağladı. Onlar, bu söze layık ve ehil kimselerdi. Allah herşeyi bilmektedir."},{"n":27,"t":"Andolsun ki Allah, Peygamberinin rüyasının gerçek olduğunu tasdik eder. Ey inananlar! Siz, Allah dilerse, güven içinde başlarınızı tıraş etmiş veya saçlarınız kısaltılmış olarak, korkmadan Mescid-i Haram’a gireceksiniz. Allah sizin bilmediğinizi bilir. Size bundan başka, yakın zamanda bir zafer verecektir."},{"n":28,"t":"Resulünü, hidayet ve hak dinle gönderdi ki o hak dini, bütün dinlere üstün kılsın. Şahid olarak Allah yeter."},{"n":29,"t":"Filizini çıkarmış onu kuvvetlendirmiş, kalınlaşmış, gövdesi üzerine dikilmiş, ekincilerin hoşuna giden ekin gibidirler. Allah böylece bunları çoğaltıp kuvvetlendirmekle inkarcıları öfkelendirir. Allah, inanıp yararlı işler yapanlara mağfiret ve büyük mükafat va’detmiştir."}],[{"n":1,"t":"Ey inananlar! Allah’ın ve peygamberinin önüne geçmeyin, Allah’tan korkun. Şüphesiz Allah, işitendir, bilendir."},{"n":2,"t":"Ey inananlar! Seslerinizi, peygamberin sesini bastıracak şekilde yükseltmeyin. Birbirinize yüksek sesle konuştuğunuz gibi onunla da öyle yüksek sesle konuşmayın; yoksa siz farkında olmadan amelleriniz boşa gider."},{"n":3,"t":"Allah’ın peygamberinin yanında seslerini kısanlar, şüphesiz Allah’ın kalplerini takva ile imtihan ettiği kimselerdir. Onlara mağfiret ve büyük bir mükafat vardır."},{"n":4,"t":"Ey Muhammed! Odaların arkasından sana bağıranların çoğu, düşüncesiz kimselerdir."},{"n":5,"t":"Onlar, sen kendilerinin yanına çıkıncaya kadar bekleselerdi, elbette kendileri için daha iyi olurdu. Allah, bağışlayandır, esirgeyendir."},{"n":6,"t":"Ey inananlar! Size fasık (yoldan çıkmış) bir adam bir haber getirirse onun doğruluğunu araştırın. Yoksa bilmeyerek bir topluluğa karşı kötülük edersiniz de sonra yaptığınıza pişman olursunuz."},{"n":7,"t":"Bilin ki, Allah’ın elçisi içinizdedir. Şayet birçok işte size uysaydı, sıkıntıya düşerdiniz. Fakat Allah size imanı sevdirdi ve onu sizin kalplerinizde süsledi ve size küfrü, fıskı ve isyanı çirkin gösterdi. İşte doğru yolda olanlar bunlardır."},{"n":8,"t":"Bu size Allah’ın bir lütuf ve nimetidir Allah bilendir, hakimdir."},{"n":9,"t":"Eğer mü’minlerden iki topluluk birbirleriyle savaşırlarsa aralarını düzeltiniz; eğer biri diğeri üzerine saldırırsa, saldıranlarla Allah’ın buyruğuna dönmelerine kadar savaşınız; eğer dönerlerse aralarını adaletle bulunuz, adil davranınız, şüphesiz Allah adil davrananları sever."},{"n":10,"t":"Muhakkak mü’minler kardeştirler. Kardeşlerinizin arasını düzeltin ve Allah’tan korkun ki size rahmet edilsin."},{"n":11,"t":"Ey inananlar! Bir topluluk başka bir toplulukla alay etmesin. Belki alay ettikleri kimseler, kendilerinden iyidirler. Kadınlarda başka kadınlarla alay etmesin. Belki onlar kendilerinden iyidirler. Birbirinizde kusur aramayın; birbirinizi kötü lakaplarla çağırmayın. İnandıktan sonra fasık (yoldan çıkmış) olmak ne kötü bir addır. Kim tevbe etmezse, işte onlar, zalimlerdir."},{"n":12,"t":"Ey inananlar! Zandan çok sakının. Zira zanların bir kısmı günahtır. Birbirinizin gizli şeylerinizi araştırmayın; biriniz diğerinizi arkasından çekiştirmesin. Biriniz ölmüş kardeşinin etini yemeyi sever mi? İşte bundan iğrendiniz. O halde Allah’tan korkun, şüphesiz Allah, tevbeyi çok kabul eden, çok esirgeyendir."},{"n":13,"t":"Ey insanlar, biz sizi bir erkek ve bir kadından yarattık ve birbirinizi tanımanız için sizi milletlere ve kabilelere ayırdık. Allah yanında en üstün olanınız Allah’tan en çok korkanınızdır. Allah bilendir, haber alandır."},{"n":14,"t":"«İnanmadık fakat İslam olduk deyin; inanç henüz gönüllerinize yerleşmedi; eğer Allah’a ve Peygamberine itaat ederseniz yaptıklarınızdan birşey eksilmez; doğrusu Allah, bağışlar, merhamet eder.»"},{"n":15,"t":"Gerçek mü’minler ancak Allah’a ve Resulüne iman eden, ondan sonra asla şüpheye düşmeyen, Allah yolunda mallarıyla canlarıyla savaşanlardır. İşte iman sözlerinde doğru olanlar onlardır."},{"n":16,"t":"«Siz mi Allah’a dininizi öğreteceksiniz? Allah, göklerde ve yerde olanları bilir, Allah, herşeyi bilendir.»"},{"n":17,"t":"«Müslüman olmanızı benim başıma kakmayın. Tersine, size imanı nasip ettiği için Allah sizi minnet altında bırakır.»"},{"n":18,"t":"Şüphesiz Allah, göklerin ve yerin gizlisini bilir. Allah yaptıklarınızı görmektedir."}],[{"n":1,"t":"Kaf. Şerefli Kur’an’a andolsun!"},{"n":2,"t":"Kafirler aralarından bir uyarıcının gelmesine şaştılar da «Bu şaşılacak bir şeydir» dediler."},{"n":3,"t":"Biz öldüğümüz ve toprak olduğumuz zaman mı dirileceğiz? Bu uzak bir dönüştür."},{"n":4,"t":"Biz toprağın onlardan neleri eksilttiğini kesinlikle bilmekteyiz. Yanımızda o bilgileri koruyan bir kitap vardır."},{"n":5,"t":"Doğrusu onlar, hak kendilerine gelince onu yalanladılar. Şimdi onlar şaşırmış bir haldedirler."},{"n":6,"t":"Üzerlerindeki göğe bakmazlar mı ki, onu nasıl bina etmiş ve nasıl donatmışız? Onda hiçbir çatlak ta yoktur."},{"n":7,"t":"Yeryüzünü de yaydık, ona sağlam dağlar yerleştirdik, onda her güzel çifti bitirdik."},{"n":8,"t":"Bütün bunları, Allah’a yönelen her kulun, gönül gözünü açmak için ve ona ibret vermek için yaptık."},{"n":9,"t":"Gökten bereketli su indirdik, onunla bahçeler ve biçilecek taneli ekinler bitirdik."},{"n":10,"t":"Birbirine girmiş kat kat tomurcukları olan yüksek hurma ağaçları yetiştirdik."},{"n":11,"t":"Kullara rızık olması için. Ve o su ile ölü bir memlekete can verdik. İşte insanların yeniden dirilmesi de böyledir."},{"n":12,"t":"Onlardan önce Nuh kavmi, Res halkı ve Semud kavmi de yalanlamıştı."},{"n":13,"t":"Ad, Firavun ve Lut’un kardeşleri de."},{"n":14,"t":"Eyke halkı ve Tubba’ kavmi de. Bütün bunların hepsi peygamberleri yalanladılar da üzerlerine tehdidim hak oldu."},{"n":15,"t":"İlk yaratma ile yorulup aciz mi kaldık ki yeniden yaratamayalım? Doğrusu onlar yeniden yaratılmaktan şüphe etmektedirler."},{"n":16,"t":"Andolsun insanı biz yarattık ve nefsinin ona ne fısıldadığını biliriz, çünkü biz ona şah damarından daha yakınız."},{"n":17,"t":"Çünkü onun sağında ve solunda oturan, her davranışı yakalayıp tesbit eden iki melek vardır."},{"n":18,"t":"İnsan hiçbir söz söylemez ki yanında gözetliyen, dediklerini zapteden bir melek hazır bulunmasın."},{"n":19,"t":"Ölüm sarhoşluğu bir gün Hakk’ı getirir de «İşte ey insan bu, senin öteden beri kaçtığın şeydir» denir."},{"n":20,"t":"Sur’a üfürülür. İşte bu geleceği söz verilen gündür."},{"n":21,"t":"Her can, yanında bir sürücü ve bir şahidle gelir."},{"n":22,"t":"«Andolsun ki, sen, bundan gafilsin; işte senden gaflet perdesini kaldırdık, bugün artık görüşün keskindir» denir."},{"n":23,"t":"«İşte yanımdaki hazır» dedi."},{"n":24,"t":"«Haydi ikiniz, atın cehenneme her inatçı nankörü.»"},{"n":25,"t":"Hayra engel olan, saldırgan şüpheciyi."},{"n":26,"t":"O ki Allah ile beraber başka tanrılar edindi, bundan dolayı onu çetin bir azaba atın."},{"n":27,"t":"«Rabb’imiz, ben onu azdırmadım, zaten o kendisi derin bir sapıklık içinde idi.»"},{"n":28,"t":"«Huzurumda çekişmeyin. Ben size daha önce uyarı göndermiştim.»"},{"n":29,"t":"Benim katımda söz değişmez; Ben kullara asla zulmetmem der."},{"n":30,"t":"«Doldun mu?» deriz. «Daha yok mu?» der."},{"n":31,"t":"Cennet Allah’a karşı gelmekten sakınanlara yaklaştırılır, zaten uzak değildir."},{"n":32,"t":"İşte size vaadedilen budur. Daima tevbe ile Allah’a dönen, O’nun buyruklarını koruyan."},{"n":33,"t":"Görmediği Rahman’dan korkan ve Allah’a yönelmiş bir kalble gelen sizlere, hepinize söz verilen yerdir."},{"n":34,"t":"Oraya esenlikle girin; işte sonsuzluk günü budur denir."},{"n":35,"t":"Orada istedikleri herşey vardır. Katımızda daha fazlası da vardır."},{"n":36,"t":"Biz onlardan önce nice nesilleri helak ettik. Gerçekte onlar bunlardan daha güçlü idiler. Buna rağmen ölümden kurtulmak için memlekette delikler aradılar. Kurtuluş var mı?"},{"n":37,"t":"Doğrusu bunda, kalbi olana veya şahid olarak kulak veren kimse için bir öğüt vardır."},{"n":38,"t":"Andolsun Biz, gökleri, yeri ve ikisi arasında bulunanları altı günde yarattık. Bize hiçbir yorgunluk dokunmadı."},{"n":39,"t":"Ey Muhammed! Onların dediklerine sabret. Güneşin doğuş ile batışında önce Rabb’ini hamd ile tesbih et."},{"n":40,"t":"Gecenin bir bölümünde ve secdelerin ardından O’nu tesbih et."},{"n":41,"t":"Bir çağırıcının yakın bir yerde çağıracağı güne kulak ver."},{"n":42,"t":"O gün çığlığı gerçekten duyarlar; işte o, kabirden çıkış günüdür."},{"n":43,"t":"Doğrusu Biz diriltiriz, Biz öldürürüz, dönüş Bizedir."},{"n":44,"t":"O gün yer onların üstünden yarılıp açılır. Ve onlar kabirlerinden çıkıp süratle koşarlar. İşte bu toplanmadır, bize göre kolaydır."},{"n":45,"t":"Biz onların ne dediklerini biliyoruz. Sen onların üstünde bir zorlaştırıcı değilsin, sadece tehdidimden korkanlara Kur’an’la öğüt ver."}],[{"n":1,"t":"Esip savuranlara."},{"n":2,"t":"Yükünü yüklenenlere."},{"n":3,"t":"Kolayca süzülenlere."},{"n":4,"t":"İşi ayıranlara and olsun."},{"n":5,"t":"Size va’dedilen, mutlaka doğrudur."},{"n":6,"t":"Ceza muhakkak olacaktır."},{"n":7,"t":"Yolları bulunan göğe andolsun ki."},{"n":8,"t":"Ey inkarcılar, siz, şüphesiz çeşitli görüştesiniz."},{"n":9,"t":"Çevrilen, ondan çevriliyor."},{"n":10,"t":"O çeşitli görüşleri atan yalancılar kahrolsun."},{"n":11,"t":"Onlar aptallık içinde ne yaptıklarını bilmezler."},{"n":12,"t":"Ceza günü ne zaman? diye sorarlar."},{"n":13,"t":"O gün onların ateşe sokulacakları gündür."},{"n":14,"t":"Azabımızı tadın! Acele gelmesini beklediğiniz şey budur işte denir."},{"n":15,"t":"Doğrusu Allah’a karşı gelmekten sakınanlar, cennetlerde, pınar başlarındadırlar."},{"n":16,"t":"Rab’lerinin, kendilerine verdiğini alırlar. Çünkü onlar bundan önce de güzel davranırlardı."},{"n":17,"t":"Geceleri pek az uyurlardı."},{"n":18,"t":"Seher vaktinde de istiğfar ederlerdi."},{"n":19,"t":"Mallarında dilenci ve yoksul için bir hak vardı."},{"n":20,"t":"Kesin inanacak insanlar için yeryüzünde nice deliller vardır."},{"n":21,"t":"Kendi canlarınızda da nice deliller vardır. Görmüyor musunuz?"},{"n":22,"t":"Rızkınız da, size va’dedilen azab da göktedir."},{"n":23,"t":"Göklerin ve yerin Rabb’ine and olsun ki bu vaad, sizin konuşmanız kadar kesin ve gerçektir."},{"n":24,"t":"İbrahim’in şerefli misafirlerinin haberi sana geldi mi?"},{"n":25,"t":"«Selam size» demişti. İçinden de, onların «tanınmamış bir topluluk» olduklarını geçirmişti."},{"n":26,"t":"Gizlice ailesinin yanına gitti, semiz bir buzağı getirdi"},{"n":27,"t":"Onu, önlerine yaklaştırdı «Yemez misiniz?» dedi."},{"n":28,"t":"Yemediklerini görünce içine bir korku düştü. «Korkma» dediler ve ona bilgin bir oğlan çocuğu müjdelediler."},{"n":29,"t":"Karısı hayretle çığlık içinde geldi. Yüzünü kapayarak «Ben kısır bir kocakarıyım» dedi."},{"n":30,"t":"«Rabb’in böyle dedi. O, hüküm ve hikmet sahibidir, bilendir.»"},{"n":31,"t":"«O halde işiniz nedir ey elçiler?» dedi."},{"n":32,"t":"«Biz suçlu bir kavme gönderildik.»"},{"n":33,"t":"Ki onların üzerine çamurdan taşlar salalım;"},{"n":34,"t":"Rabbinin katında, haddi aşanlar için işaretlenmiş taşlar."},{"n":35,"t":"Orada mü’minlerden kim varsa çıkardık."},{"n":36,"t":"Zaten orada bir ev halkından başka müslüman da bulamadık."},{"n":37,"t":"Acı azabdan korkanlar için orada bir ibret bıraktık."},{"n":38,"t":"Musa’nın başından geçenlerde de ibretler vardır. Onu apaçık bir delille Fir’avn’a gönderdik."},{"n":39,"t":"Fir’avn ordusuyla birlikte yüz çevirmiş ve «Musa, ya bir büyücü ya da bir delidir» dedi."},{"n":40,"t":"Sonunda onu ve ordularını yakalayıp denize attık. O, kınanmayı haketmişti."},{"n":41,"t":"Ad kavminde de ibretler vardır. Onlara kasıp kavuran rüzgarı göndermiştik."},{"n":42,"t":"Üzerinden geçtiği şeyi canlı bırakmıyor, onu kül edip savuruyordu."},{"n":43,"t":"Onlara, «Bir süreye kadar zevklenin» denmişti."},{"n":44,"t":"Rab’lerinin buyruğuna baş kaldırdılar, bu yüzden bakıp dururlarken onları yıldırım yakaladı."},{"n":45,"t":"Ayağa kalkacak güçleri kalmamış, yardım edenleri de olmamıştı."},{"n":46,"t":"Daha önce de Nuh kavmini helak etmiştik. Çünkü onlar da yoldan çıkmış bir toplum idiler."},{"n":47,"t":"Göğü gücümüzle biz kurduk; şüphesiz biz onu genişleticiyiz."},{"n":48,"t":"Yeri biz döşedik biz ne güzel döşeyiciyiz."},{"n":49,"t":"Her şeyden çift çift yarattık ki düşünüp öğüt alasınız."},{"n":50,"t":"O halde Allah’a koşun. Çünkü ben, sizi O’ndan açık bir şekilde korkutuyorum."},{"n":51,"t":"Allah ile beraber başka tanrılar uydurmuyorum. Ben size O’nun tarafından görevlendirilmiş apaçık bir uyarıcıyım."},{"n":52,"t":"«Büyücü veya cinlenmiş» dediler."},{"n":53,"t":"Bunu birbirlerine vasiyet mi ettiler? Hayır onlar azgın bir topluluktur."},{"n":54,"t":"Onlardan yüz çevir, sen kınanacak değilsin."},{"n":55,"t":"Ancak yine de hatırlat, çünkü hatırlatmak, mü’minlere fayda verir."},{"n":56,"t":"Ben cinleri ve insanları, ancak bana kulluk etsinler diye yarattım."},{"n":57,"t":"Ben onlardan rızık istemiyorum, beni beslemelerini de istemiyorum."},{"n":58,"t":"Şüphesiz rızık veren, güç ve kuvvet sahibi olan ancak Allah’tır."},{"n":59,"t":"Muhakkak ki bu zulmedenlerin de, geçmiş arkadaşlarının payı gibi bir azab payı vardır. Acele etmesinler."},{"n":60,"t":"Söz verilen günün azabından vay o kafirlerin haline!"}],[{"n":1,"t":"Andolsun Tur’a."},{"n":2,"t":"Satır satır yazılmış Kitab’a;"},{"n":3,"t":"Yayılmış ince deri üzerine."},{"n":4,"t":"Ma’mur bir ev olan Ka’be’ye."},{"n":5,"t":"Yükseltilmiş tavan gibi göğe."},{"n":6,"t":"Kaynatılmış denize"},{"n":7,"t":"Rabbinin azabı hiç şüphesiz gelecektir."},{"n":8,"t":"Ona engel olacak bir şey yoktur."},{"n":9,"t":"O gün gök, sarsıldıkça çalkalanacak."},{"n":10,"t":"Dağlar bir yürüyüş yürür ki..."},{"n":11,"t":"O gün, yalanlayanların vay haline."},{"n":12,"t":"Ki onlar o daldıkları batıl içinde oyalanıp duranlardır."},{"n":13,"t":"O gün şöyle denilerek cehennem ateşine itilirler:"},{"n":14,"t":"«İşte yalanlayıp durduğunuz cehennem budur!"},{"n":15,"t":"Bir büyü müdür bu, yoksa görmüyor musunuz?"},{"n":16,"t":"Girin ona ister dayanın, ister dayanmayın, sizin için birdir. Anlattıklarımıza göre cezalandırılacaksınız.»"},{"n":17,"t":"Allah’a karşı gelmekten sakınanlar da cennetlerde, nimet içindedirler."},{"n":18,"t":"Rabblerinin kendilerine verdikleriyle sefa sürerler. Rabbleri onları, cehennem azabından korumuştur."},{"n":19,"t":"Yaptıklarınıza karşılık afiyetle yeyin, için!"},{"n":20,"t":"Sıra sıra dizilmiş koltuklara yaslanarak. Onları, iri gözlü hurilerle evlendirmişizdir."},{"n":21,"t":"İnanan, soyları da inançta kendilerine uyan kimselere soylarını da katarız. Onların işlediklerinden hiçbir şey eksiltmeyiz. Herkes kazancına bağlıdır."},{"n":22,"t":"Cennette olanlara diledikleri meyve ve etten bol bol veririz."},{"n":23,"t":"Orada bir kadehi kapışırlar fakat onda ne saçmalama vardır, ne de günaha sokma."},{"n":24,"t":"Sedefteki inciler gibi olan gençler yanlarında dolaşırlar."},{"n":25,"t":"Cennettekiler birbirlerine dönüp sorarlar:"},{"n":26,"t":"«Daha önce biz, ailemiz içinde korkardık.»"},{"n":27,"t":"Allah bize lütfetti de bizi vücudun içine işleyen azabtan korudu."},{"n":28,"t":"Biz bundan önce yalnız O’na yalvarırdık. Çünkü iyilik eden, esirgeyen O’dur O."},{"n":29,"t":"Ey Muhammed! Sen hatırlat, öğüt ver. Rabbinin nimetiyle sen, ne kahinsin ne de delisin."},{"n":30,"t":"«Muhammed bir şairdir, zamanın onun aleyhine dönmesini gözlüyoruz» mu diyorlar?"},{"n":31,"t":"«Gözleyin, doğrusu ben de sizinle beraber gözlemekteyim.»"},{"n":32,"t":"Onların akılları mı bunu emreder, yoksa onlar, azgın bir topluluk mudur?"},{"n":33,"t":"Yoksa «Onu uydurdu» mu diyorlar? Hayır, onlar inanmıyorlar."},{"n":34,"t":"İddialarında samimi iseler haydi onun gibi bir söz getirsinler."},{"n":35,"t":"Yoksa kendileri, hiçbir şey olmadan mı yaratıldılar. Yoksa yaratanlar kendileri midir?"},{"n":36,"t":"Yoksa gökleri ve yeri mi yarattılar? Hayır, onlar düşünüp te inanmazlar."},{"n":37,"t":"Yoksa Rabbinin hazineleri onların yanında mıdır? Ya da herşeye hakim olan kendileri midir?"},{"n":38,"t":"Yoksa onlar, üzerine çıkıp gizli sırları dinledikleri bir merdivenleri mi var? Öyleyse, dinleyenleri açık bir delil getirsin."},{"n":39,"t":"Yoksa kızlar Allah’a, oğullar size mi?"},{"n":40,"t":"Yoksa sen onlardan bir ücret istiyorsun da onlar ağır bir borç altında mı kalıyorlar?"},{"n":41,"t":"Yoksa gayb kendilerinin yanındadır da kendileri mi istediklerini yapıyorlar?"},{"n":42,"t":"Yoksa bir tuzak mı kurmak istiyorlar? Asıl tuzağa düşecek olanlar, o inkar edenlerin kendileridir."},{"n":43,"t":"Yoksa onların Allah’tan başka bir tanrısı mı var? Allah’ın şanı onların ortak koştuklarından yücedir."},{"n":44,"t":"Gökten bir parçanın düştüğünü görsek «Üst üste yığılmış bulutlardır» derler."},{"n":45,"t":"Korkudan bayılacakları günlerine kavuşuncaya kadar bırak onları."},{"n":46,"t":"O gün, tuzakları kendilerine hiçbir yarar sağlamaz ve onlara yardım da edilmez."},{"n":47,"t":"Zulmedenlere, şüphesiz bundan başka da azab vardır; fakat onların çoğu bilmezler."},{"n":48,"t":"Rabbinin hükmüne sabret, çünkü sen, gözlerimizin önündesin, kalktığın zaman Rabbini övgü ile an."},{"n":49,"t":"Gecenin bir kısmında ve yıldızların ardından da Allah ı tesbih et."}],[{"n":1,"t":"Kayan yıldız hakkı için."},{"n":2,"t":"Arkadaşınız Muhammed ne sapıttı ne de azıttı."},{"n":3,"t":"O havadan konuşmuyor."},{"n":4,"t":"Söyledikleri, kendisine indirilen bir vahiydir."},{"n":5,"t":"Bu vahyi O’na müthiş güçleri olan Cebrail öğretti."},{"n":6,"t":"O üstün yetenekli melek doğruldu."},{"n":7,"t":"Yüce ufuktayken."},{"n":8,"t":"Sonra yaklaştı, yere doğru uzandı."},{"n":9,"t":"Öyle ki, Peygamberle araları iki yay aralığı ya da daha yakın oldu."},{"n":10,"t":"O anda Allah dilediği mesajı Kul’una vahyetti."},{"n":11,"t":"O’nun gönlü, gözünün gördüğünü yalanlamadı."},{"n":12,"t":"Siz şimdi gözü ile gördükleri hakkında O’nunla tartışmaya mı girişiyorsunuz?"},{"n":13,"t":"O, Cebrail’i bir başka inişinde de görmüştü."},{"n":14,"t":"Sidretu’l-Munteha’nın yanında."},{"n":15,"t":"Yanıbaşında me’va cenneti vardı."},{"n":16,"t":"O sırada ağacı yaman bir şey bürümüştü."},{"n":17,"t":"Muhammed’in gözü ne yana kaydı ve ne de öteye geçti"},{"n":18,"t":"O gerçekten Rabb’inin bazı büyük ayetlerini gördü."},{"n":19,"t":"Lât ve Uzza hakkındaki görüşünüz nedir?"},{"n":20,"t":"Ya bunların öbürü, üçüncüsü olan Menat hakkında ne düşünüyorsunuz?"},{"n":21,"t":"Demek erkekler sizin, dişiler Allah’ın, öyle mi?"},{"n":22,"t":"Öyleyse bu haksız bir bölüştürmedir."},{"n":23,"t":"Aslında bunlar sizin ve atalarınızın uydurduğu kuru isimlerdir. Allah, onlara ilişkin hiçbir kanıt indirmemiştir. Onlar sadece sanılarının ve canlarının istediğinin peşinden gidiyorlar. Oysa onlara Rabbleri katından doğru yola ilişkin bilgi geldi."},{"n":24,"t":"Yoksa insanın her hayal ettiği şey gerçekleşir mi sanıyorsunuz?"},{"n":25,"t":"Oysa hayatın sonu da ilki de (ahiret de dünya da) Allah’a aittir."},{"n":26,"t":"Göklerde nice melek var ki, Allah’ın dilediklerine ve hoşlandıklarına ilişkin izni olmadıkça, şefaatleri hiçbir yarar sağlamaz."},{"n":27,"t":"Ahirete inanmayanlar meleklere dişi adları takıyorlar."},{"n":28,"t":"Oysa onların bu konuda hiçbir bilgileri yoktur. Sadece sanılarının peşinden gidiyorlar. Sanıları ise gerçeğin kırıntısının bile yerini tutamaz."},{"n":29,"t":"Bizi anmaktan yüz çeviren ve sadece dünya hayatını isteyenlerden yüz çevir."},{"n":30,"t":"Onların bilgilerinin erişebileceği sınır budur. Hiç kuşkusuz senin Rabb’in kimin yolundan saptığını bildiği gibi kimin doğru yolda olduğunu da bilir."},{"n":31,"t":"Göklerde ve yeryüzünde ne varsa hepsi Allah’a aittir. Amaç kötülük işleyenlere kötülüklerinin ve iyilik yapanlara da iyiliklerinin karşılığını vermektir."},{"n":32,"t":"İyilik işleyenler büyük günahlardan ve çirkin davranışlardan uzak dururlar. Sadece küçük kusurları olabilir. Senin Rabb’inin bağışlayıcılığı geniş kapsamlıdır. O sizi gerek ilk başta topraktan yaratırken ve gerekse annelerinizin karınlarında cenin aşamasındayken bilir. Öyleyse kendinizi temize çıkarmayınız. Çünkü o kimin kötülüklerden sakındığını herkesten iyi bilir."},{"n":33,"t":"Ey Muhammed, görüyor musun, şu gerçeğe sırt çevireni?"},{"n":34,"t":"Önce biraz verip de arkasını getirmeyeni."},{"n":35,"t":"Acaba gaybın bilgisine sahiptir de o alemin sırlarını mı görüyor?"},{"n":36,"t":"Yoksa Musa’ya indirilen kutsal sayfaların içeriğinden haberi olmadı mı?"},{"n":37,"t":"Ve görevini titizlikle yerine getiren İbrahim’e inmiş olan kutsal sayfaların içeriğinden haberdar olmadı mı?"},{"n":38,"t":"Ki, hiç kimse başkasının günah yükünü taşımaz."},{"n":39,"t":"İnsan ancak kendi çalışmasının karşılığını elde edebilir."},{"n":40,"t":"Çalışması da ileride görülecektir."},{"n":41,"t":"Sonra çalışmasının karşılığı kendisine eksiksiz olarak verilecektir."},{"n":42,"t":"Sonunda kesinlikle Rabb’inin huzuruna varılacaktır."},{"n":43,"t":"Güldüren de, ağlatan da O’dur."},{"n":44,"t":"Öldüren de dirilten de O’dur."},{"n":45,"t":"Erkeği ve dişiyi çiftler halinde yaratan O’dur."},{"n":46,"t":"Fışkıran spermadan."},{"n":47,"t":"Tekrar diriltecek olan da O’dur."},{"n":48,"t":"İnsana zenginlik veren de gözünü doyuran da O’dur."},{"n":49,"t":"(Bazı müşriklerin taptıkları) «Şira» yıldızının Rabb’i de O’dur."},{"n":50,"t":"Eski dönemlerde yaşamış Adoğullarını yokeden O’dur."},{"n":51,"t":"Semudoğullarının da. Kazıdı köklerini."},{"n":52,"t":"Daha önce de Nuh’un soydaşlarını yoketmişti. Çünkü onlar son derece zalim ve azgın kimselerdi."},{"n":53,"t":"Lût’un soydaşlarının yaşadıkları yöreleri alt üst eden O’dur."},{"n":54,"t":"Buraları yerin dibine O geçirmiştir."},{"n":55,"t":"Ey insanoğlu, öyleyse Rabb’inin hangi nimetinden kuşku duyuyorsun?"},{"n":56,"t":"Bu Peygamber de eski uyarıcıların bir halkasıdır:"},{"n":57,"t":"Kıyamet günü iyice yaklaştı"},{"n":58,"t":"Onun dehşetini Allah’tan başka hiç kimse başınızdan savamaz."},{"n":59,"t":"Siz bu sözü ve bu haberleri mi tuhaf buluyorsunuz?"},{"n":60,"t":"Onu dinlerken ağlayacağınıza gülüyorsunuz, öyle mi?."},{"n":61,"t":"Gaflet içinde yüzüyorsunuz, değil mi?"},{"n":62,"t":"Haydi, hemen Allah’a secde ediniz, O’na kulluk ediniz."}],[{"n":1,"t":"Kıyamet anı yaklaştı, ay ikiye ayrıldı."},{"n":2,"t":"Onlar bir mucize görseler yüz çevirirler ve «Bu öteden beri gördüğümüz bir büyüdür» derler."},{"n":3,"t":"Yalanladılar, keyfi arzularına uydular; ama herşey yerinde duruyor."},{"n":4,"t":"Onlara bu tutumlarından vazgeçmelerini sağlayacak haberler geldi."},{"n":5,"t":"Bu haberler son derece anlamlı ve etkilidir, ama uyarılar yararlı olmuyor."},{"n":6,"t":"Sen de yüz çevir onlara. Görevli melek, o gün onları benzeri yaşanmamış olaya çağırdığında;"},{"n":7,"t":"Mezarlarından donuk ve ürkek bakışlarla çıkarak çekirge sürüsü gibi etrafa yayılırlar."},{"n":8,"t":"Kendilerini çağıran görevliye doğru koşarlar. O zaman kafirler «Bu zor bir gündür» derler."},{"n":9,"t":"Onlardan önce Nuh’un soydaşları da yalanlamışlardı. Onlar kulumuz Nuh’u yalanlayarak «Bu adam delidir» dediler, onu görevinden alıkoydular."},{"n":10,"t":"O da «Ben yenik düştüm, yardım et bana» diye Rabb’ine dua etti."},{"n":11,"t":"Göğün kapılarını açarak bardaktan su boşanır gibi bir yağmur yağdırdık."},{"n":12,"t":"Yeri de coşkun kaynaklar halinde fışkırttık. Her iki yönden gelen su belirlenen bir görevi yerine getirmek üzere birleşti."},{"n":13,"t":"Onu çivilerle tutturulmuş tahtalardan yapılan bir gemiye bindirdik."},{"n":14,"t":"Mesajı inkar edilen kulumuza ödül olarak bu gemi gözetimimiz altında yüzüyordu."},{"n":15,"t":"Biz onu bir ibret dersi olarak geride bıraktık. İbret alan yok mu?"},{"n":16,"t":"Benim azabım ve uyarılarım nasılmış?"},{"n":17,"t":"Biz Kur’an’dan öğüt alınabilsin diye onu kolay anlaşılır kıldık. Yok mu öğüt alan?"},{"n":18,"t":"Adoğulları da peygamberlerini yalanladılar. Ama benim azabım ve uyarmam nasılmış?"},{"n":19,"t":"Baştan başa uğursuz bir günde üzerlerine sert ve dondurucu bir kasırga saldık."},{"n":20,"t":"Bu kasırga insanları sökülmüş hurma kütükleri gibi havaya kaldırıp savuruyordu."},{"n":21,"t":"Peki benim azabım ve uyarılarım nasılmış?"},{"n":22,"t":"öyleyse yok mudur ders alan?"},{"n":23,"t":"Semudoğulları da uyarıları yalanlamışlardı."},{"n":24,"t":"«İçimizden bir insanın peşinden mi gideceğiz? Öyle yaparsak sapıtmış ve kendimizi ateşe atmış oluruz.»"},{"n":25,"t":"Bizler dururken vahiy ona indirildi, öyle mi? Hayır, o şımarık bir yalancıdır!"},{"n":26,"t":"Onlar yarın kimin şımarık bir yalancı olduğunu öğreneceklerdir."},{"n":27,"t":"Biz onları sınavdan geçirmek için dişi deveyi göndereceğiz. Sabret de gör bakalım, ne yapacaklar?"},{"n":28,"t":"Onlara suyun deve ile aralarında bölüştürüldüğünü bildir. Kimin sırası ise gelir, su içer."},{"n":29,"t":"Ama onlar bir arkadaşlarını çağırdılar. O da kılıcını çekerek hayvanı cansız yere serdi."},{"n":30,"t":"Peki benim azabım ve uyarılarım nasılmış?"},{"n":31,"t":"Onların üzerine bir tek çığlık saldık da ağıl bekçisinin biriktirdiği kuru ot yığınlarına dönüştüler."},{"n":32,"t":"Biz Kur’an’dan öğüt alınabilsin diye onu kolay anlaşılır kıldık. Yok mu öğüt alan?"},{"n":33,"t":"Lut’un soydaşları da uyarıları yalanlamışlardı."},{"n":34,"t":"Biz de üzerlerine taşları savuran bir kasırga gönderdik. Yalnız Lut’un taraftarları hariç. Onları sabahleyin erkenden kurtardık."},{"n":35,"t":"Tarafımızdan sunulmuş bir nimet olarak. Biz şükredenleri işte böyle ödüllendiririz."},{"n":36,"t":"Lut onları bizim sillemiz konusunda uyarmıştı. Fakat, onlar bu uyarıları kuşku ile karşıladılar."},{"n":37,"t":"Onlar Lut’un konuklarını elde etmek istediler. Bunun üzerine gözlerini kör ettik. «Tadın bakalım azabımı ve uyarılarımın sonuçlarını.»"},{"n":38,"t":"Sabah erkenden sürekli bir azaba yakalandılar."},{"n":39,"t":"Tadın bakalım azabımı ve uyarılarımın sonuçlarını."},{"n":40,"t":"Biz Kur’an’dan öğüt alınabilsin diye onu kolay anlaşılır kıldık. Yok mu öğüt alan?"},{"n":41,"t":"Firavun yanlılarına da uyarılar gelmişti."},{"n":42,"t":"Fakat bütün ayetlerimizi yalanladılar. Biz de güçlü ve üstün iradeli birine yaraşacak bir sertlikle onların yakalarına yapıştık."},{"n":43,"t":"Acaba sizin içinizdeki kafirler onlardan daha mı iyidir, yoksa kutsal kitaplarda size ilişkin bir suçsuzluk belgesi mi var?"},{"n":44,"t":"Yoksa onlar «Biz karşımıza çıkacak herkesi yenen güçlü bir orduyuz» mu diyorlar?"},{"n":45,"t":"Yakında orduları bozguna uğratılacak ve geri püskürtüleceklerdir."},{"n":46,"t":"Asıl azaba kıyamet günü çarpılacaklardır. Kıyamet günü onlar için daha feci ve daha acıdır."},{"n":47,"t":"Suçlular şaşkınlık ve ateş içindedirler."},{"n":48,"t":"O gün onlar yüzüstü sürüklenerek cehenneme atılırlar; «Ateşin vücudunuza değişini tadınız» diye."},{"n":49,"t":"Biz her şeyi belirli bir plan uyarınca yarattık."},{"n":50,"t":"Bizim buyruğumuz göz kırpması kadar kısa sürede gerçekleşen bir tek sözdür."},{"n":51,"t":"Biz sizin gibi sapıkları daha önce yokettik. Öğüt alan yok mu?"},{"n":52,"t":"Onların yaptıkları herşey defterlere geçmiştir."},{"n":53,"t":"Küçük büyük bütün davranışları satırlara işlenmiştir."},{"n":54,"t":"Kötülüklerden sakınanlar cennetlerde ve ırmak kenarlarındadırlar."},{"n":55,"t":"Güçlü hükümdarın katında güvenli bir konutta ağırlanacaklardır."}],[{"n":1,"t":"Rahman olan Allah."},{"n":2,"t":"Kur’an’ı öğretti."},{"n":3,"t":"İnsanı yarattı."},{"n":4,"t":"Ona düşüncesini açıklamayı öğretti."},{"n":5,"t":"Güneşin ve ayın konumları ve hareketleri belirli bir hesaba dayanır."},{"n":6,"t":"Bitkiler ve ağaçlar O’nun buyruğuna boyun eğerler."},{"n":7,"t":"O, göğü yüksek yarattı ve tartı ilkesini koydu."},{"n":8,"t":"Tartıda titiz olun diye."},{"n":9,"t":"Teraziyi doğru tutunuz, sakın eksik tartmayız."},{"n":10,"t":"Allah, yeryüzünü canlıların ayakları altına serdi."},{"n":11,"t":"Orada türlü türlü meyvalar, salkımlı hurma ağaçları var."},{"n":12,"t":"Yine orada yapraklı taneler, hoş kokulu bitkiler var."},{"n":13,"t":"Ey insanlar ve cinler, peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":14,"t":"O insanı pişmiş çamuru andıran kuru balçıktan yarattı."},{"n":15,"t":"Cinleri de dumansız alevden yarattı."},{"n":16,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":17,"t":"O iki doğunun da Rabbidir, iki batının da."},{"n":18,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":19,"t":"Acı ve tatlı sulu iki denizi birbiri üzerine salarak yanyana getirdi."},{"n":20,"t":"Ama aralarında birbirlerine karışmalarını önleyen bir engel vardır."},{"n":21,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":22,"t":"Her iki denizden de inci ve mercan çıkar."},{"n":23,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":24,"t":"O’nun denizlerde yüzen, dağlar gibi iri gemileri vardır."},{"n":25,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":26,"t":"Yeryüzündeki her şey yok olacaktır."},{"n":27,"t":"Sadece kerem sahibi, yüce Rabbinin varlığı süreklidir."},{"n":28,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":29,"t":"Göktekiler ve yerdekiler hep O’ndan bir şey isterler. O her gün (her an) yeni bir işle meşguldür."},{"n":30,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":31,"t":"Ey insanlar ve cinler, yakında sizinle hesaplaşmak için özel vakit ayıracağız."},{"n":32,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":33,"t":"Ey cinler ve insanlar, eğer göklerin ve yerin sınırlarını aşarak kaçmaya gücünüz yetiyorsa kaçınız. Fakat ancak özel bir gücünüz varsa bunu başarabilirsiniz."},{"n":34,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":35,"t":"Üzerinize dumansız alev ve bakır eriyiği püskürtülür de bu azaptan sizi kurtaran bulunmaz."},{"n":36,"t":"Ey insanlar ve cinler, bu durumda, Rabbinizin nimetlerinden hangisini, Kuran’dan hangi ilkeyi önemsemeyerek sınırsız rahmetini, kudretini yalanlayabilirsiniz?"},{"n":37,"t":"Gök parçalanıp da kırmızı gül renginde bir yağ eriyiğine dönüştüğü zaman;"},{"n":38,"t":"öyleyse siz ey iki topluluk! Rabbinizin hangi nimet ve kudretini inkâr edebilirsiniz?"},{"n":39,"t":"O gün ne insana ne de cinne suçu sorulmaz."},{"n":40,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":41,"t":"Suçlular yüz ifadelerinden tanınarak perçemlerinden ve ayaklarından yakalanırlar."},{"n":42,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":43,"t":"İşte suçluların yalanladıkları cehennem budur."},{"n":44,"t":"Cehennem ile kaynar su arasında mekik dokurlar."},{"n":45,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":46,"t":"Rabbinin huzuruna çıkacağı andan korkanlara cennette bir konut verilecektir."},{"n":47,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":48,"t":"Bu cennet konutlarının bahçeleri sık dallı ağaçlarla kaplıdır."},{"n":49,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":50,"t":"Bu iki konutta birer pınar akmaktadır."},{"n":51,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":52,"t":"Bu konutların bahçelerindeki ağaçlarda her meyvanın iki çeşidi vardır."},{"n":53,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":54,"t":"Bu konutlarda ağırlananlar astarları yaldızlı atlastan minderlere yaslanırlar. Her iki konutun bahçelerindeki ağaçların meyvaları yere yakındır, kolayca devşirilebilirler."},{"n":55,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":56,"t":"Bu konutlarda gözleri erkeklerinden başkasını görmeyen, daha önce ne insan ve ne de cin kökenli bir erkeğin, el değdirmediği eşler vardır."},{"n":57,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":58,"t":"O eşler sanki birer yakut ve mercandırlar."},{"n":59,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":60,"t":"İyiliğin, iyilikten başka bir karşılığı olabilir mi?"},{"n":61,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":62,"t":"Bu iki cennet konutunda ali düzeyde iki cennet konutu daha vardır."},{"n":63,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":64,"t":"Bu konutların renkleri koyu yeşildir."},{"n":65,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":66,"t":"İki konutta sürekli kaynayan iki pınar vardır:"},{"n":67,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":68,"t":"İki konutun bahçelerinde de çeşitli meyva, hurma ve nar ağaçları vardır."},{"n":69,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":70,"t":"O konutlarda iyi huylu, güzel kadınlar vardır."},{"n":71,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":72,"t":"O kadınlar ceylan gözlüdürler ve çadırlarının dışına hiç çıkmazlar."},{"n":73,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":74,"t":"Daha önce onlara ne cin ne insan kökenli hiçbir erkeğin eli değmemiştir."},{"n":75,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz"},{"n":76,"t":"Bu konutlarda ağırlananlar yeşil yastıklara ve güzel işlemeli minderlere yaslanırlar."},{"n":77,"t":"Peki, Rabbinizin hangi nimetini yalanlıyorsunuz?"},{"n":78,"t":"Kerem sahibi, ulu Rabbinin adı ne yücedir!"}],[{"n":1,"t":"Kıyamet koptuğu zaman,"},{"n":2,"t":"Onu hiç kimse yalanlayamayacaktır."},{"n":3,"t":"O kimini alçaltır, kimini de yükseltir."},{"n":4,"t":"Yeryüzü şiddetle sarsıldığı zaman."},{"n":5,"t":"Dağlar paramparça olup,"},{"n":6,"t":"Toz halinde boşluğa dağıldığı zaman."},{"n":7,"t":"Sizler üç gruba ayrıldığınız zaman."},{"n":8,"t":"Defterleri sağdan verilenler. Ne mutlu onlara!"},{"n":9,"t":"Defterleri soldan verilenler. Vay gele başlarına!"},{"n":10,"t":"Ve öncüler, hep önden gidenler."},{"n":11,"t":"Onlar Allah’a yakındırlar."},{"n":12,"t":"Bol nimetli cennetlerdedirler."},{"n":13,"t":"Çoğu öncü ümmetlerden,"},{"n":14,"t":"Birazı da sonrakilerdendir."},{"n":15,"t":"Altın işlemeli tahtlarda otururlar."},{"n":16,"t":"Karşılıklı olarak bu tahtlara kurulurlar."},{"n":17,"t":"Hiç ölmeyecek genç hizmetçiler aralarında dolaşır,"},{"n":18,"t":"Gürül gürül akan bir çeşmeden doldurulmuş testiler, ibrikler ve kadehlerle."},{"n":19,"t":"Bu içki ne başlarını ağrıtır, ne de sarhoş eder."},{"n":20,"t":"Hoşlarına giden meyvalarla,"},{"n":21,"t":"İştahla yiyecekleri kuş etleri ile,"},{"n":22,"t":"Onlara iri gözlü huriler sunulur,"},{"n":23,"t":"Tıpkı sedefteki inciler gibi."},{"n":24,"t":"Yaptıkları iyiliklerin karşılığı olarak,"},{"n":25,"t":"Orada ne boş ve ne günah içerikli bir söz işitirler."},{"n":26,"t":"İşittikleri tek söz «selâm, selâm» dır."},{"n":27,"t":"Defterleri sağdan verilenler. Ne mutlu onlara!"},{"n":28,"t":"Onlar dikensiz sedir ağaçları,"},{"n":29,"t":"Meyva yüklü muz ağaçları arasında,"},{"n":30,"t":"Kesintisiz gölgeler altında,"},{"n":31,"t":"Çağlayan akarsu boylarında,"},{"n":32,"t":"Bol meyvalar yanında,"},{"n":33,"t":"Sürekli ve yasaksız,"},{"n":34,"t":"Yüksek döşekler üzerindedirler."},{"n":35,"t":"Biz oradaki hurileri yeniden yarattık."},{"n":36,"t":"Onları bakire yaptık."},{"n":37,"t":"Eşlerine aşık ve onlarla aynı yaşta,"},{"n":38,"t":"Defterleri sağdan verilenler için,"},{"n":39,"t":"Bunların bazıları eski ümmetlerden,"},{"n":40,"t":"Bazıları da sonrakilerdendir."},{"n":41,"t":"Defterleri soldan verilenler. Vay gele başlarına!"},{"n":42,"t":"Onlar gözeneklerine işleyen kavurucu bir rüzgar önünde ve kaynar su içinde,"},{"n":43,"t":"Kara ve boğucu bir dumanın gölgesi altındadırlar."},{"n":44,"t":"Ne serinliği ve ne de okşayıcılığı var."},{"n":45,"t":"Çünkü onlar vaktiyle varlık içinde azıtmışlardı."},{"n":46,"t":"Büyük günahı (Allah’a ortak koşmayı) işlemekte ısrar ediyorlardı."},{"n":47,"t":"«Ölüp toprak ve kemik yığını olduktan sonra, biz yeniden mi diriltileceğiz?"},{"n":48,"t":"Eski atalarımız da mı?» diyorlardı."},{"n":49,"t":"«Öncekiler de, sonrakiler de.»"},{"n":50,"t":"Belirlenmiş bir günün randevusunda bir araya getirileceklerdir."},{"n":51,"t":"Sonra siz, ey sapık yalanlayıcılar,"},{"n":52,"t":"Size kesinlikle Zakkum ağacının meyvası yedirilecektir."},{"n":53,"t":"Onunla karınlarınız doldurulacaktır."},{"n":54,"t":"Üzerine de kaynar su içeceksiniz."},{"n":55,"t":"Onu, içtikçe susayan develer gibi içeceksiniz."},{"n":56,"t":"Onlar hesap günü işte böyle ağırlanacaklardır."},{"n":57,"t":"Sizleri yaratan biziz, bunu onaylasanıza."},{"n":58,"t":"Fışkırttığınız meniyi görüyor musunuz?"},{"n":59,"t":"Onu siz mi yaratıyorsunuz, yoksa onu yaratan biz miyiz?"},{"n":60,"t":"Ölümü aranızda plânlayan biziz. Hiç kimse bizim önümüze geçemez."},{"n":61,"t":"Amacımız benzerlerinizi yerinize geçirmek ve hepinizi bilmediğiniz bir alemde yeniden diriltmektir."},{"n":62,"t":"İlk yaratılmayı bildiniz. Bunu düşünüp ders alsanıza!"},{"n":63,"t":"Ektiğiniz tohumu görüyor musunuz?"},{"n":64,"t":"Onu siz mi bitiriyorsunuz, yoksa onu bitiren biz miyiz?"},{"n":65,"t":"Eğer isteseydik o ekinlerinizi ot kırıntılarına dönüştürürdük de şaşakalırdınız."},{"n":66,"t":"Derdiniz ki; «Biz borca battık.»"},{"n":67,"t":"Daha doğrusu her şeyimizi kaybettik."},{"n":68,"t":"İçtiğiniz suyu görüyor musunuz?"},{"n":69,"t":"Onu siz mi buluttan yere indiriyorsunuz, yoksa onu indiren biz miyiz?"},{"n":70,"t":"Eğer isteseydik onu acı yapardık. Şükretsenize!"},{"n":71,"t":"Tutuşturduğunuz ateşi görüyor musunuz?"},{"n":72,"t":"Onun ağacını siz mi yaratıyorsunuz, yoksa onu yaratan biz miyiz?"},{"n":73,"t":"Biz onu hem düşündürücü, ibret verici bir uyarıcı, hem de ihtiyacı olanlar için bir yararlanma kaynağı olarak yarattık."},{"n":74,"t":"Öyleyse yüce Rabbinin adını noksanlıklardan tenzih et."},{"n":75,"t":"Yıldızların yörüngeleri üzerine yemin ederim ki;"},{"n":76,"t":"Keşke bilseniz bu ne büyük bir yemindir"},{"n":77,"t":"Bu kitap, yüce Kur’an’dır."},{"n":78,"t":"Aslı (Allah katındaki) bir kitapta saklıdır."},{"n":79,"t":"Ona sadece tertemiz kimseler el sürebilir."},{"n":80,"t":"O, Allah tarafından indirilmiştir."},{"n":81,"t":"Şimdi siz bu sözü bu mesajı hafife mi alıyorsunuz?"},{"n":82,"t":"Yalanlamayı kendinize rızık ve ileriye dönük birikim mi yapıyorsunuz?"},{"n":83,"t":"Canın boğaza dayandığı an var ya,"},{"n":84,"t":"O sırada sizler gözlerinizi o can çekişen adama dikersiniz."},{"n":85,"t":"Biz ona sizden daha yakınız, ama siz göremezsiniz."},{"n":86,"t":"Eğer yeniden diriltilip hesaba çekilmeyecekseniz,"},{"n":87,"t":"Eğer söylediğiniz doğru ise o çıkmak üzere olan canı geriye döndürsenize!"},{"n":88,"t":"Eğer ölmek üzere olan kişi Allah’a yakın olanlardan ise;"},{"n":89,"t":"Esenlik, hoş kokulu çiçekler ve bol nimetli cennet onu bekliyor"},{"n":90,"t":"Eğer adam defteri sağdan verileceklerden ise,"},{"n":91,"t":"Defterlerini sağdan alacak olan arkadaşlarının selâmı var sana."},{"n":92,"t":"Eğer adam sapık bir inkarcı ise,"},{"n":93,"t":"O kaynar su sunularak ağırlanır."},{"n":94,"t":"Ve cehenneme atılır."},{"n":95,"t":"Bu kesin gerçektir."},{"n":96,"t":"Öyleyse yüce Rabbinin adını noksanlıklardan tenzih et."}],[{"n":1,"t":"Göklerdeki ve yerdeki tüm varlıklar Allah’ı noksanlıklardan tenzih ederler. O üstün iradelidir ve her işi yerinde yapar."},{"n":2,"t":"Göklerin ve yerin egemenliği O’nun tekelindedir. Can verir ve öldürür. O’nun herşeye gücü yeter."},{"n":3,"t":"O hem ilktir hem sondur; hem açıktır hem gizlidir. O herşeyi bilir."},{"n":4,"t":"O gökleri ve yeri altı günde yarattı, sonra Arş’a kuruldu. O yeraltına giren ve oradan çıkan, gökten inen ve oraya yükselen herşeyi bilir. Nerede olsanız sizinle beraberdir. O Allah yaptığınız her işi görür."},{"n":5,"t":"Göklerin ve yerin egemenliği O’nun tekelindedir. Her işin sonu Allah’a varır."},{"n":6,"t":"O geceyi gündüze, gündüzü de geceye dönüştürür. O kalplerin özünü bilir."},{"n":7,"t":"Allah’a ve peygambere inanınız. Allah’ın kullanma yetkisini elinize verdiği malların bir bölümünü O’nun için harcayınız. İçinizdeki iman edenleri ve hayır yolunda mal harcayanları büyük bir ödül bekliyor."},{"n":8,"t":"Peygamber sizi Allah’a inanmaya çağırdığı halde niçin O’na inanmıyorsunuz? Oysa o bu konuda sizden söz almıştı. Eğer inanacaksanız ne duruyorsunuz?"},{"n":9,"t":"O sizi karanlıklardan aydınlığa çıkarmak için kulu Muhammed’e apaçık ayetler indiriyor. Hiç kuşkusuz Allah size karşı son derece şefkatli ve merhametlidir."},{"n":10,"t":"Niçin malınızı Allah yolunda harcamıyorsunuz? Oysa gökler ve yer Allah’a miras kalacaktır. İçinizden Mekke fethinden önce mal harcayanlar ve savaşanlar, daha sonra mal harcayanlar ve savaşanlarla bir değildirler. Onların derecesi daha sonra mal harcayıp savaşanların derecesinden daha üstündür. Bununla birlikte Allah her iki gruba da en güzel ödülü vadetmiştir. Allah sizin neler yaptığınızı bilir."},{"n":11,"t":"Çıkar amacı gütmeksizin gönüllü olarak Allah’a borç verecek olan var mı? Allah ona verdiğini kat kat fazlası ile geri verir. Ayrıca ona onurlandırıcı bir ödül vardır."},{"n":12,"t":"O gün erkek kadın bütün müminlerden çıkan nurun önleri ve sağ yanları yönünde ilerlediğini görürsün. Onlara «Müjdeler olsun ki, altlarından ırmaklar akan ve içlerinde sürekli kalacağınız cennetler sizi bekliyor. İşte büyük başarı budur!» denir."},{"n":13,"t":"O gün erkek kadın bütün münafıklar, müminlere «bize doğru bakın da yüzünüzün nurundan ışık alalım» derler. Fakat onlara «geldiğiniz yere dönün de nuru orada arayın» diye seslenilir. Bu sırada aralarına kapısı olan bir duvar çekilir. Bu duvarın gerisinde rahmet ve dış tarafında azap vardır."},{"n":14,"t":"Münafıklar, müminlere «Dünyada sizinle birlikte değil miydik?» diye seslenirler. Müminler de onlara şöyle derler; «Evet, birlikteydik. Fakat siz kendiniz eğri yola saptınız, hep komplo peşinde koştunuz, gerçeklerden kuşku duydunuz, asılsız kuruntulara kapıldınız, sonunda Allah’ın emri gelince öldünüz, o yaman ayartıcı (şeytan) sizi Allah’ın affediciliğine güvendirerek baştan çıkardı.»"},{"n":15,"t":"bu gün ne sizden ve ne de kâfirlerden fidye kabul edilmez. Varacağınız yer cehennem ateşidir. Size orası yaraşır. Orası ne kötü bir yerdir!"},{"n":16,"t":"Allah’tan gelen öğütlerin ve O’nun indirdiği gerçeğin etkisi ile müminlerin kalplerinin yumuşayacağı, ürpereceği gün halâ gelmedi mi? Müminler daha önce kendilerine kutsal kitap verilenler gibi olmasınlar. Uzun zaman geçince onların kalpleri katılaştı ve çoğu yoldan çıkmış kimseler oldu."},{"n":17,"t":"Biliniz ki, Allah, ölmüş toprağa hayat verir. Size ayetlerimizi açıkladık ki, üzerlerinde düşünesiniz."},{"n":18,"t":"Sadaka veren erkekler ve kadınlar ile çıkar amacı gütmeksizin gönüllü olarak Allah’a borç verenler var ya, onlar verdiklerini kat kat fazlası ile geri alırlar, ayrıca kendilerine onurlandırıcı bir ödül verilir."},{"n":19,"t":"Allah’a ve Peygambere inananlar var ya, onlar özü sözü doğru olanlar ile şehitlerdir. Allah katında onlara ödül ve nur verilir. Ayetlerimizi yalanlayan kafirler ise cehennemliktirler."},{"n":20,"t":"Biliniz ki, dünya hayatı oyundan, eğlenceden, süs ve gösterişten, birbirinize karşı övünmeden, mal ve evladı çoğaltma yarışından ibarettir. Bu hayat, ekini ve bitkisi çiftçisinin yüzünü güldüren bol yağmura benzer. Fakat bir süre sonra kuruyan bu bitki örtüsünün sarardığını görürsün. Arkasından da ot kırıntılarına dönüşür. Ahirette ise bir yanda ağır bir azab, öbür yanda Allah’ın bağışlaması ve hoşnutluğu vardır. Dünya hayatı, aldatıcı bir hazdan başka bir şey değildir."},{"n":21,"t":"O halde Rabbinizin bağışlaması ve Allah ile Peygambere inananlar için hazırlanmış, gökle yer arası kadar genişliği olan cennet uğruna yarışınız. Bu Allah’ın dilediklerine verdiği bir lütfudur. Allah büyük lütuf sahibidir."},{"n":22,"t":"Gerek yeryüzünde görülen, gerekse başınıza gelen her musibet tarafımızdan yaratılmadan önce kesinlikle bir kitapta belirlenmiştir. Bu ayrıntılı planlama Allah için kolay bir iştir."},{"n":23,"t":"Amaç, kaybettiklerinize üzülmemeniz ve O’nun size verdikleri yüzünden şımarmamanızdır. Allah kendini beğenmiş şımarıkları sevmez."},{"n":24,"t":"Bunlar hem kendileri cimrice davranırlar hem de başkalarına cimri olmayı önerirler. Kim hayr yapmaktan kaçınırsa bilsin ki, Allah hiçbir şeye muhtaç değildir ve özü itibarı ile övgüye layıktır."},{"n":25,"t":"Biz Peygamberlerimizi kesin kanıtlarla gönderdik, insanlar arasında adil bir düzen kurulsun diye onlarla birlikte kitabı ve ölçüyü indirdik. Ayrıca büyük caydırıcılığı ve sertliği yanında insanlara yönelik birçok faydaları olan demiri indirdik. Böylece kimlerin görmedikleri halde Allah’ı ve Peygamberi destekleyeceklerini ortaya çıkarmak istedik. Hiç kuşkusuz Allah güçlü ve üstün iradelidir."},{"n":26,"t":"Biz Nuh’u ve İbrahim’i peygamber olarak gönderdik. İkisinin soyuna da peygamberlik ve kitap verdik. Onların soylarından türeyenlerin bir bölümü doğru yola bağlı kaldı, fakat çoğu yoldan çıktı."},{"n":27,"t":"Onların arkasından ardarda diğer peygamberlerimizi gönderdik, bu arada Meryemoğlu İsa’yı da gönderdik. O’na İncil’i verdik, bağlılarının kalplerine şefkat ve merhamet duygusu aşıladık. Biz onlara aşırı sofuluğu farz kılmış değildik. Bunu akılları sıra Allah’ın hoşnutluğunu kazanmak için kendileri uydurdular. Buna rağmen onun gereklerini yerine getirmediler. Biz onların inananlarına ödüllerini verdik, fakat çoğu yoldan çıkmış kimselerdir."},{"n":28,"t":"Ey müminler, Allah’tan korkunuz ve Peygambere inanınız ki, O size vereceği rahmeti ikiye katlasın, size yolunuzu aydınlatacak bir nur bağışlasın, günahlarınızı affetsin. Çünkü Allah affedici ve merhametlidir."},{"n":29,"t":"Böylece yahudiler ile hristiyanlar bilsinler ki, Allah’ın lütfu kendi tekellerinde değildir. Lütuf O’nun elindedir, dilediğine verir onu. Allah büyük lütuf sahibidir."}],[{"n":1,"t":"Allah, kocası hakkında seninle tartışan ve Allah’a şikayette bulunan kadının sözünü işitti. Allah sizin konuşmanızı işitir. Çünkü Allah işitendir, bilendir."},{"n":2,"t":"Sizden eşlerine zihar yapanlar, bilmelidir ki o kadınlar, onların anaları değildir. Onların anaları, ancak kendilerini doğurmuş kadınlardır. Şüphesiz onlar çirkin ve yalan bir söz söylüyorlar. Şüphesiz Allah, affedici, bağışlayıcıdır."},{"n":3,"t":"Eşlerinden zihar ile ayrılmak isteyip de sonra söylediklerinden dönenlerin eşleriyle temas etmeden önce bir köleyi hürriyetine kavuşturmaları gerekir. Size öğütlenen budur. Allah, yaptıklarınızdan haberi olandır."},{"n":4,"t":"Buna imkan bulamayan kimse, temas etmeden önce aralıksız olarak iki ay oruç tutar. Buna da gücü yetmeyen, altmış fakiri doyurur. Bu kolaylık, Allah’a ve peygamberine inanmış olmanızdan ötürüdür; bunlar Allah’ın koyduğu sınırlardır. İnkar edenler için çok yakıcı azap vardır."},{"n":5,"t":"Allah’a ve Peygamberine karşı gelenler, kendilerinden öncekiler nasıl alçaltıldı ise öyle alçaltılacaklardır. Biz, apaçık ayetler indirmişizdir, bunları inkar edene alçaltıcı azap vardır."},{"n":6,"t":"O gün Allah onların hepsini diriltecek ve yaptıklarını kendilerine haber verecektir. Allah onları birbir saymıştır. Onlar ise unutmuşlardır. Allah herşeye şahiddir."},{"n":7,"t":"Göklerde ve yerde olanları, Allah’ın bildiğini bilmiyor musun? Üç kişi gizli konuşsa mutlaka dördüncüsü O’dur. Beş kişi gizli konuşsa mutlaka altıncısı O’dur. Bunlardan az veya çok olsunlar ve nerede bulunursalar bulunsunlar mutlaka O onlarla beraberdir. Sonra kıyamet günü onlara yaptıklarını haber verecektir. Doğrusu Allah, herşeyi bilendir."},{"n":8,"t":"Görmedin mi şu adamları ki gizli gizli konuşmaları yasaklandığı halde yine o yasaklanan işi yapıyorlar. Günah, düşmanlık ve Resule isyan hususunda gizli gizli konuşuyorlar. Onlar sana geldiklerinde seni, Allah’ın selamlamadığı bir tarzda selamlıyorlar. Kendi içlerinden de «Bu söylediklerimiz yüzünden Allah’ın bize azap etmesi gerekmez miydi?» derler. Cehennem onlara yeter. Oraya gireceklerdir, ne kötü gidilecek yerdir orası."},{"n":9,"t":"Ey iman edenler! Aranızda gizli konuştuğunuz zaman günah, düşmanlık ve peygambere karşı gelmek üzere konuşmayın. İyilik ve takva üzerine konuşun, huzuruna varacağınız Allah’tan korkun."},{"n":10,"t":"Gizli konuşmalar (fiskoslar) şeytanın yapacağı işlerdendir. Bu iman edenleri üzmek içindir. Oysa şeytan, Allah’ın izni olmadıkça, mü’minlere hiçbir zarar veremez.. Mü’minler Allah’a dayanıp güvensinler!"},{"n":11,"t":"«Meclislerde yer açın» denildiği zaman yer açın ki Allah ta size yeriniz ve rızkınızda genişlik versin. Size «Kalkın» denildiği zaman, kalkın ki Allah sizden inananları ve kendilerine ilim verilenleri derecelerle yükseltsin. Allah yaptıklarınızı haber almaktadır."},{"n":12,"t":"Ey iman edenler! Peygamber ile gizli (özel) bir şey konuşacağınız zaman bu konuşmanızdan önce bir sadaka veriniz. Bu sizin için daha hayırlı ve daha temizdir. Şayet sadaka verecek bir şey bulamazsanız, Allah bağışlayan, esirgeyendir."},{"n":13,"t":"Gizli konuşmanızdan önce sadaka vermenizden korktunuz mu? Çünkü yapmadınız. Allah sizi affetti. Artık namaz kılın, zekat verin, Allah’a ve Resulüne itaat edin! Allah yaptıklarınızı haber alandır."},{"n":14,"t":"Allah’ın kendilerine gazap ettiği bir topluluğu dost edinenleri görmedin mi? Onlar ne sizdendirler, ne de onlardan. Bile bile yalan yere yemin ediyorlar."},{"n":15,"t":"Allah onlara çetin bir azap hazırlamıştır. Gerçekten onların yaptıkları şey çok kötüdür."},{"n":16,"t":"Yeminlerini kalkan yapıp Allah’ın yoluna engel oldular. Onlar için küçük düşürücü azap vardır."},{"n":17,"t":"Onların ne malları, ne de evlatları kendilerini Allah’a karşı koruyamaz. Onlar ateş halkıdır. Orada ebedi kalacaklardır."},{"n":18,"t":"Allah’ın onların hepsini yeniden dirilteceği gün, dünyada şu yemin ettikleri gibi, Allah’a da yemin ederler. Kendilerinin doğru yolda olduklarını sanırlar. İyi bilin ki onlar gerçekten yalancıdırlar."},{"n":19,"t":"Şeytan onları istila etmiş, onlara Allah’ı anmayı unutturmuştur. Onlar şeytanın taraftarlarıdır. İyi bilin ki şeytanın taraftarları mutlaka kaybedenlerdir."},{"n":20,"t":"Allah’a ve peygamberine düşman olanlar, onlar en alçak kimselerle beraberdirler."},{"n":21,"t":"Allah’a andolsun ki «ben ve elçilerim galip geleceğiz.» diye yazmıştır. Şüphesiz Allah güçlüdür, galiptir."},{"n":22,"t":"Allah’a ve ahiret gününe inanan bir kavmin; babaları, oğulları, kardeşleri, yahut akrabaları da olsa Allah’a ve Peygamberine düşman olanlarla dostluk ettiğini göremezsin. Allah onların kalplerine imanı yazmış ve onları katından bir ruh ile desteklemiştir. Onları, altlarından ırmaklar akan cennetlere sokacak, orada ebedi kalacaklardır. Allah onlardan razı olmuş onlar da O’ndan razı olmuşlardır. İşte onlar Allah’ın taraftarlarıdır. Muhakkak ki başarıya ulaşacak olanlar, Allah’ın taraftarlarıdır."}],[{"n":1,"t":"Göklerde ve yerde olanların hepsi Allah’ı tesbih etmektedir. O üstündür, hikmet sahibidir."},{"n":2,"t":"Kitap ehlinden inkar edenleri, ilk sürgünde yurtlarından çıkaran O’dur. Siz onların çıkacaklarını sanmamıştınız. Onlarda kalelerinin, kendilerini Allah’tan koruyacağını sanmışlardı. Allah onlara ummadıkları yerden geldi, yüreklerine korku saldı; öyle ki evlerini kendi elleriyle ve müminlerin elleriyle yıkıyorlardı. Ey akıl sahipleri ibret alın!"},{"n":3,"t":"Eğer Allah onlara sürgün yazmamış olsaydı, mutlaka onlara dünyada azap ederdi. Ahirette de onlar için ateş azabı vardır."},{"n":4,"t":"Onlar Allah’a ve Peygamberine karşı geldiler; kim Allah’a karşı gelirse bilsin ki Allah’ın azabı çetindir."},{"n":5,"t":"Hurma ağaçlarından herhangi bir şeyi kesmeniz veya kökleri üzerinde bırakmanız hep Allah’ın izniyledir. Bu izin yoldan çıkan fasıkları rezil etmek içindir."},{"n":6,"t":"Allah’ın onların mallarında Peygamberine verdiği ganimetler için siz at ve deveye binip onları sürmüş değilsiniz. Fakat Allah, Peygamberlerini dilediği kimselere karşı üstün kılar. Allah herşeye kadirdir."},{"n":7,"t":"Allah’ın fethedilen ülkeler halkının mallarından Peygamberine verdiği ganimetler, Allah, Peygamber, yakınları, yetimler, yoksullar ve yolda kalmışlar içindir. Böylece o mallar, yalnızca zenginler arasında dolaşan bir ayrıcalık olmaz. Peygamber size ne verdiyse onu alın, size neyi yasakladıysa ondan sakının ve Allah’tan korkun. Çünkü Allah’ın azabı şiddetlidir."},{"n":8,"t":"Allah’ın verdiği bu ganimet malları, yurtlarından ve mallarından çıkmış olan, Allah’tan bir lütuf ve rıza dileyen, Allah’ın dinine ve Peygamberine yardım eden fakir muhacirlerindir. İşte doğru olanlar bunlardır."},{"n":9,"t":"Daha önce Medine’yi yurt edinmiş ve gönüllerine imanı yerleştirmiş olan kimseler, kendilerine göç edip gelenleri severler ve onlara verilenler karşısında içlerinde bir kaygı duymazlar. Kendilerinin ihtiyaçları olsa dahi, göç eden yoksul kardeşlerini öz canlarına tercih ederler. Kim nefsinin cimriliğinden korunursa, işte onlar başarıya erenlerdir."},{"n":10,"t":"«Rabbimiz, bizi ve bizden önce inanan kardeşlerimizi bağışla, kalplerimizde inananlara karşı bir kin bırakma! Rabbimiz sen çok şefkatli, çok merhametlisin!»"},{"n":11,"t":"Münafıkların, kitap ehlinden inkar eden dostlarına «Eğer siz yurdunuzdan çıkartılırsanız, mutlaka biz de sizinle beraber çıkarız; sizin aleyhinizde kimseye asla uymayız. Şayet sizinle savaşırlarsa mutlaka size yardım ederiz» derler. Allah, onların yalancı olduklarına şahidlik eder."},{"n":12,"t":"Andolsun eğer onlar, çıkarılsalar, onlarla beraber çıkmazlar; eğer onlarla savaşılsa onlara yardım etmezler, yardım etseler bile arkalarına dönüp kaçarlar, sonra kendilerine de yardım edilmez."},{"n":13,"t":"Ey inananlar! Onların yüreklerine korku salan, Allah’tan çok sizlersiniz; çünkü onlar anlamayan bir topluluktur."},{"n":14,"t":"Onlar sizinle toplu olarak savaşamazlar, ancak müstahkem şehirlerde yahut duvarların ardından sizinle savaşmak isterler. Kendi aralarındaki çekişmeleri şiddetlidir. Sen onları toplu sanırsın, ancak onların kalpleri dağınıktır. Böyledir, çünkü onlar düşünmez bir topluluktur."},{"n":15,"t":"Onların durumu, kendilerinden az önce, yaptıklarının vebalini tatmış olan, ahirette de kendileri için acı bir azap bulunan kimselerin durumu gibidir."},{"n":16,"t":"«Doğrusu ben senden uzağım; alemlerin Rabbi olan Allah’tan korkarım» diyen şeytanın durumu gibidir."},{"n":17,"t":"Nihayet ikisinin de sonu, içinde ebedi kalacakları ateş olacaktır. İşte bu zalimlerin cezasıdır."},{"n":18,"t":"Ey iman edenler! Allah’tan korkun ve herkes yarına ne hazırladığına baksın. Allah’tan korkun. Çünkü Allah yaptıklarınızı haber almaktadır."},{"n":19,"t":"Allah’ı unutup da, Allah’ın da kendilerini unutturduğu kimseler gibi olmayın. Çünkü onlar sapık kimselerdir."},{"n":20,"t":"Cehennemliklerle cennetlikler bir olmaz. Kurtulanlar ancak cennetlik olanlardır."},{"n":21,"t":"Eğer biz bu Kur’an’ı bir dağa indirseydik muhakkak ki onu Allah korkusundan baş eğerek parça parça olmuş görürdün. Bu örnekleri düşünsünler diye insanlara veriyoruz."},{"n":22,"t":"O görüleni de görülmeyeni de bilen kendisinden başka ilah olmayan Allah’tır. Çok esirgeyen, çok merhamet edendir."},{"n":23,"t":"O kendisinden başka ilah olmayan, hüküm sahibi mukaddes, esenlik veren, güven veren gözetip koruyan üstün ve galip olan otorite sahibi, gerçekten ulu olan Allah’tır. Yüce Allah onların ortak koştuklarından münezzehtir."},{"n":24,"t":"O yaratan, yoktan var eden, varlıklara şekil veren Allah’tır. İsimlerin en güzelleri O’na aittir. Göklerde ve yerde olanların hepsi O’nu takdis etmektedir. Üstün güç sahibi ve herşeyi hikmeti uyarınca yapandır."}],[{"n":1,"t":"Ey iman edenler! Benim de düşmanım, sizin de düşmanınız olanları dost edinmeyin. Onlar size gelen gerçeği inkar etmişken, onlara sevgi gösteriyorsunuz. Halbuki onlar Rabbiniz olan Allah’a inandığınızdan dolayı, Peygamberi ve sizi yurdunuzdan çıkarıyorlar. Eğer siz benim yolumda savaşmak ve rızamı kazanmak için çıkmışsanız, onlara nasıl sevgi gösteriyorsunuz? Oysa ben sizin gizlediğinizi de açığa vurduğunuzu da bilirim. Sizden kim bunu yaparsa doğru yoldan sapmış olur."},{"n":2,"t":"Onlar sizi ele geçirseler, size düşman olurlar, size ellerini, dillerini kötülükle uzatırlar ve inkar etmenizi isterler."},{"n":3,"t":"Kıyamet günü yakınlarınız ve çocuklarınız size fayda veremezler. Allah aranızı ayırır. Allah, yaptıklarınızı görendir."},{"n":4,"t":"«Rabbimiz, sana güvendik, sana yöneldik, dönüşümüz sanadır.»"},{"n":5,"t":"Rabbimiz! Bizi, inkar edenlerle imtihan etme; bizi bağışla, doğrusu sen, güçlü olan, Hakim olansın."},{"n":6,"t":"Andolsun, Allah’ı ve ahiret gününü arzu edenler için, bunlarda güzel örnekler vardır. Kim yüz çevirirse şüphesiz Allah, zengindir, övülmeye lâyık olandır."},{"n":7,"t":"Belki de Allah sizinle, onlardan düşman olduklarınız arasına ağır sevgi koyar, Allah buna kadirdir. Allah çok bağışlayan çok esirgeyendir."},{"n":8,"t":"Allah, sizinle din uğrunda savaşmayan ve sizi yurtlarınızdan çıkarmayanlara iyilik yapmanız ve adil davranmanızı yasaklamaz. Çünkü Allah, adaletli olanları sever."},{"n":9,"t":"Allah, yalnız sizinle din uğrunda savaşanları, sizi yurtlarından çıkaranları ve çıkarılmanız için yardım edenleri dost edinmenizi yasaklar. Kim onları dost edinirse, işte zalim onlardır."},{"n":10,"t":"Ey iman edenler! Mümin kadınlar hicret ederek size gelirse, onları imtihan edin. Allah onların imanlarını daha iyi bilir. Eğer siz de onların gerçekten inanmış olduklarını anlarsanız onları kafirlere geri döndürmeyin. Bu kadınlar, o inkarcılara helal değildir. Onlar da bunlara helal olmazlar. Onların kocalarının sarfettiğini (mehirleri) geri verin. Mehirlerini kendilerine geri verdiğiniz zaman onlarla evlenmenizde size bir günah yoktur. Kafir kadınları nikahınızda tutmayın, harcadığınızı isteyin. Onlarda harcadığını istesinler. Allah’ın hükmü budur. Aranızda O hükmeder. Allah bilendir, hikmet sahibidir."},{"n":11,"t":"Eğer eşlerinizden biri, sizden kafirlere kaçar da siz de savaşta galip durumda olursanız, eşleri gitmiş olanlara ganimetten, harcadıkları kadar verin. İnandığınız Allah’a karşı gelmekten sakının."},{"n":12,"t":"Ey Peygamber! İnanmış kadınlar, Allah’a hiçbir şeyi ortak koşmamak, hırsızlık yapmamak, zina etmemek, çocuklarını öldürmemek, elleri ile ayakları arasında bir iftira uydurup getirmemek, iyi bir işte sana karşı gelmemeleri hususunda sana biat etmeye geldikleri zaman, biatlarını kabul et ve onlar için Allah’tan mağfiret dile. Şüphesiz Allah, çok bağışlayan, çok esirgeyendir."},{"n":13,"t":"Ey iman edenler, Allah’ın gazabına uğrayan bir topluluğu dost edinmeyin. Çünkü bunlar kafirlerin mezardakilerden ümitlerini kestikleri gibi ahiretten ümitlerini kesmişlerdir."}],[{"n":1,"t":"Göklerde ve yerde bulunanların hepsi Allah’ı tesbih etmiştir. O üstündür, hikmet sahibidir."},{"n":2,"t":"Ey iman edenler! Yapmayacağınız şeyi niçin söylüyorsunuz?"},{"n":3,"t":"Yapmayacağınız şeyi söylemek, Allah katında büyük gazaba sebep olur."},{"n":4,"t":"Doğrusu Allah, kendi yolunda kenetlenmiş bir duvar gibi saf bağlıyarak savaşanları sever."},{"n":5,"t":"«Ey kavmim! Benim Allah’ın size gönderdiği elçisi olduğumu bildiğiniz halde niçin beni incitiyorsunuz?» demişti. Onlar yoldan sapınca Allah da kalplerini saptırmıştı. Allah, yoldan çıkan milleti doğru yola eriştirmez."},{"n":6,"t":"’Bu apaçık büyüdür’ dediler."},{"n":7,"t":"İslama çağrılırken Allah’a karşı yalan uydurandan daha zalim kimdir? Allah zalimler topluluğunu doğru yola iletmez."},{"n":8,"t":"Onlar ağızlarıyla Allah’ın nurunu söndürmek istiyorlar. Halbuki zalimler istemese de Allah nurunu tamamlayacaktır."},{"n":9,"t":"Müşrikler istemese de dinini bütün dinlere üstün kılmak için peygamberini hidayet ve hak ile gönderen O’dur."},{"n":10,"t":"Ey iman edenler! Sizi acı bir azaptan kurtaracak ticareti size göstereyim mi?"},{"n":11,"t":"böyle yapmanız sizin için daha hayırlıdır; tabi eğer bilgiyle (hareket) ederseniz."},{"n":12,"t":"Böyle yaparsanız Allah günahlarınızı bağışlar, sizi altlarından akan cennetlere Adn cennetlerindeki güzel meskenlere koyar. İşte en büyük kurtuluş budur."},{"n":13,"t":"Seveceğiniz bir şey daha var Allah’tan bir zafer ve yakın bir fetih, müminleri müjdele!"},{"n":14,"t":"«Allah yolunun yardımcıları biziz» demeleri gibi. İsrail oğullarından bir zümre inandı, bir zümre inkar etti. Biz de inananları, düşmanlarına karşı destekledik, onlar üstün geldiler."}],[{"n":1,"t":"Göklerde ve yerde olanların hepsi mülkün sahibi, mukaddes, aziz, hakim olan Allah’ı tesbih eder."},{"n":2,"t":"Ümmiler arasından kendilerine Allah’ın ayetlerini okuyan, onları arındıran, onlara kitabı ve hikmeti öğreten bir peygamber gönderen Allah’tır. Halbuki onlar daha önceleri apaçık bir sapıklık içindeydiler."},{"n":3,"t":"Bu peygamberi, yine onlardan olup henüz kendilerine yetişmemiş bulunan başka insanlara da gönderdik. O Azizdir, Hakimdir."},{"n":4,"t":"Bu Allah’ın dilediğine verdiği lütuftur. Allah büyük lütuf sahibidir."},{"n":5,"t":"Kendilerine Tevrat öğretildiği halde, onun gereğini yapmayanların durumu, sırtına kitap yüklü eşeğin durumu gibidir. Allah’ın ayetlerini yalanlayanların durumu ne kötüdür. Allah zalimler topluluğunu doğru yola iletmez."},{"n":6,"t":"«Ey yahudiler! Bütün insanlar bir yana, yalnız kendinizin Allah’ın dostları olduğunuzu iddia ediyorsanız ve bu iddianızda samimi iseniz, ölümü dileyin bakalım.»"},{"n":7,"t":"Dünyada yaptıklarından dolayı, ölümü asla istemezler. Allah, zalimleri çok iyi bilendir."},{"n":8,"t":"«Doğrusu kendisinden kaçtığınız ölüm mutlaka karşınıza çıkacaktır; sonra, görüleni de görülmeyeni de bilen Allah’a döndürüleceksiniz. O size yaptıklarınızı haber verecektir.»"},{"n":9,"t":"Ey iman edenler! Cuma günü namaza çağrıldığınız zaman, hemen Allah’ı anmaya koşun ve alışverişi bırakın. Eğer siz gerçeği anlayan kimseler iseniz elbette bu, sizin için daha hayırlıdır."},{"n":10,"t":"Namaz bitince yeryüzüne dağılın ve Allah’ın lütfunu isteyin. Allah’ı çok zikredin, umulur ki kurtuluşa erersiniz."},{"n":11,"t":"«Allah’ın yanında bulunan eğlenceden ve ticaretten daha hayırlıdır. Allah rızık verenlerin en hayırlısıdır.»"}],[{"n":1,"t":"Ey Muhammed! Münafıklar sana geldiklerinde, «şahitlik ederiz ki, sen Allah’ın peygamberisin» derler. Allah ta bilir ki sen elbette, kendisinin peygamberisin. Bununla birlikte Allah münafıkların yalancı olduklarını da bilir."},{"n":2,"t":"Çünkü, onlar yeminlerini kalkan yapıp insanları Allah’ın yolundan alıkorlar. Onların yaptıkları ne kötüdür."},{"n":3,"t":"Bunun sebebi, onların önce iman edip sonra inkar etmeleridir. Bu yüzden kalpleri mühürlenmiştir artık onlar hiç anlamazlar."},{"n":4,"t":"Onları gördüğün zaman kalıpları hoşuna gider, konuşurlarsa onların sözlerini dinlediğin zaman sanki elbise giydirilmiş (bir yere dayandırılmış) kütük gibidirler. Her gürültüyü kendi aleyhlerine sanırlar. Onlar düşmandır; onlardan sakın. Allah onları kahretsin! Nasıl da Hak’tan döndürülüyorlar?"},{"n":5,"t":"«Gelin de Allah’ın Rasulü sizin için bağışlanma dilesin denildiği zaman, başlarını çevirirler ve onların, büyüklük taslayarak yüz çevirdiklerini görürsün."},{"n":6,"t":"Onlar için bağışlanma dilesen de dilemesen de birdir; Allah onları bağışlamayacaktır. Çünkü Allah yoldan çıkmış topluluğu doğru yola iletmez."},{"n":7,"t":"«Allah’ın Peygamberinin yanında bulunanlara bir şey vermeyin de dağılıp gitsinler» diyen kimselerdir. Oysa göklerin ve yerin hazineleri Allah’ındır. Fakat münafıklar anlamazlar."},{"n":8,"t":"«Andolsun, eğer Medine’ye dönersek şerefli olan, alçak olanı oradan mutlaka çıkaracaktır.» Şeref ancak Allah’ın, O’nun Peygamberinin ve müminlerindir. Fakat münafıklar bunu bilmezler."},{"n":9,"t":"Ey iman edenler! Mallarınız ve çocuklarınız sizi Allah’ı anmaktan alıkoymasın. Kim bunu yaparsa işte onlar ziyana uğrayanlardır."},{"n":10,"t":"«Rabbim beni yakın bir süreye kadar ertelesen de, sadaka versem, iyilerden olsam» diyeceği zaman gelmezden önce, size verdiğimiz rızklardan sarf edin."},{"n":11,"t":"Allah, yaşama süresi dolduğu zaman hiçbir canı ertelemez. Allah yaptıklarınızdan haberdardır."}],[{"n":1,"t":"Göklerde ve yerde ne varsa hepsi Allah’ı tesbih eder. Mülk O’nundur, hamd O’nadır. O’nun gücü her şeye yeter."},{"n":2,"t":"Sizi yaratan Allah’tır. Bununla beraber kiminiz kâfirdir, kiminiz mü’min. Allah yaptıklarınızı görmektedir."},{"n":3,"t":"Gökleri ve yeri hakka dayalı olarak gerektiği gibi yaratmıştır. Size şekil vermiş ve şeklinizi güzel yapmıştır. Dönüş O’nadır."},{"n":4,"t":"Göklerde ve yerde olanları bilir. Gizlediklerinizi ve açığa vurduklarınızı da bilir. Allah kalplerde olanı bilendir."},{"n":5,"t":"Daha önce inkar etmiş olanların haberi size gelmedi mi? Onlar dünyada günahlarının cezasını çektiler. Ayrıca ahrette de onlar için acı bir azap vardır."},{"n":6,"t":"Bunun nedeni onlara elçileri, açık deliller getirdiğinde «Bir insan mı bize yol gösterecek?» deyip inkar etmeleri, yüz çevirmeleriydi. Allah ta hiçbir şeye muhtaç olmadığını gösterdi. Allah zengindir, övülmüştür."},{"n":7,"t":"«Hayır Rabbime And olsun ki mutlaka diriltileceksiniz, sonra yaptıklarınız kesinlikle size haber verilecektir. Bu Allah’a göre kolaydır.»"},{"n":8,"t":"Öyleyse Allah’a, peygamberine ve indirdiğimiz nur’a (Kur’an’a) inanın. Allah yaptıklarınızı haber almaktadır."},{"n":9,"t":"Toplanma günü (hesap günü) için, sizi bir araya getirdiği zaman, işte o, kimin aldandığının ortaya çıkacağı gündür. Kim Allah’a inanmış ve yararlı işler yapmışsa, Allah onun kötülüklerini örter ve onu, altlarından ırmaklar akan cennetlere sokar orada ebedi kalırlar. İşte büyük başarı budur."},{"n":10,"t":"Kafir olup ayetlerimizi yalanlayanlara gelince onlar da ateş halkıdır. Orada ebedi kalacaklardır. Orası gidilecek ne kötü yerdir."},{"n":11,"t":"Allah’ın izni olmaksızın hiçbir musibet isabet etmez. Kim Allah’a inanırsa, Allah onun kalbini doğruya götürür. Allah her şeyi bilendir."},{"n":12,"t":"Allah’a itaat edin, Peygamber’e itaat edin. Yüz çevirirseniz bilin ki, elçimize düşen apaçık bir duyurmadır."},{"n":13,"t":"Allah O’dur ki, O’ndan başka ilah yoktur. Mü’minler yalnız Allah’a dayanıp güvensinler."},{"n":14,"t":"Ey inananlar! Eşlerinizden ve çocuklarınızdan bazıları size düşmandır. Onlardan sakının. Eğer affeder, hoş görür, bağışlarsanız muhakkak ki Allah da çok bağışlayan, çok esirgeyendir."},{"n":15,"t":"Mallarınız ve evlatlarınız bir sınav konusudur. Büyük mükafat ise Allah katındadır."},{"n":16,"t":"O halde gücünüzün yettiği kadar Allah’tan korkun. Dinleyin, itaat edin, kendi iyiliğinize olarak mallarınızı Allah yolunda harcayın. Kim nefsinin cimriliğinden korunursa işte onlar kurtuluşa erenlerdir."},{"n":17,"t":"Eğer Allah’a güzel borç verirseniz, Allah onu sizin için kat kat yapar ve sizi bağışlar. Allah şükredenlere karşılık verendir, halimdir."},{"n":18,"t":"Görünmeyeni ve görüneni bilendir. Üstündür, hikmet sahibidir."}],[{"n":1,"t":"Ey Peygamber! Kadınları boşamak istediğiniz zaman onları iddetleri içinde boşayın ve iddeti de sayın. Rabbiniz Allah’tan korkun. Apaçık bir hayasızlık yapmaları bir yana, onları evlerinden çıkarmayın, kendileri de çıkmasınlar. Bunlar Allah’ın sınırlarıdır. Kim Allah’ın sınırını aşarsa, şüphesiz kendisine zulmetmiş olur. Bilemezsin, olur ki, Allah bunun ardından (gönlünüzde sevgi gibi) bir hal meydana getirir."},{"n":2,"t":"İddet müddetlerini doldurduklarında onları ya güzelce tutun veya onlardan uygun bir şekilde ayrılın. İçinizden adalet sahibi iki kişiyi şahit tutun. Şahitliği Allah için yapın. İşte bu Allaha ve ahiret gününe inananlara verilen öğüttür. Kim Allah’tan korkarsa, Allah ona bir çıkış yolu ihsan eder."},{"n":3,"t":"Ve ona beklemediği yerden rızk verir. Kim Allah’a güvenirse kendisine yeter. Şüphesiz Allah, emrini yerine getirendir. Allah her şey için bir ölçü koymuştur."},{"n":4,"t":"Kadınlarınızdan adetten kesilmiş olanlarla henüz adet görmemiş olanların (iddetlerinden) şüphe ederseniz, onların iddetleri üç aydır. Hamile olanların bekleme süreleri ise yüklerini bırakmalarına (doğum yapmalarına) kadardır. Kim Allah’tan sakınırsa (Allah) ona işinde bir kolaylık verir."},{"n":5,"t":"Bu Allah’ın size indirdiği buyruğudur. Kim Allah’tan korkarsa Allah onun kötülüklerini örter ve onun mükafatını büyütür."},{"n":6,"t":"Boşadığınız kadınları gücünüz ölçüsünde oturduğunuz yerin bir bölümünde oturtun, onları sıkıştırıp, gitmelerini sağlamak için zarar vermeye kalkışmayın. Eğer hamile iseler, doğum yapıncaya kadar nafakalarını verin. Sizin için çocuğu emzirirlerse onlara ücretini verin, aranızda uygun bir şekilde anlaşın. Eğer güçlüğe uğrarsanız çocuğu, başka bir kadın emzirecektir."},{"n":7,"t":"İmkanı geniş olan, nafakayı imkanlarına göre versin. Rızkı daralmış bulunan da nafakayı, Allah’ın kendisine verdiğinden versin. Allah hiç kimseye gücünün yettiğinden başkasını yüklemez. Allah daima bir güçlükten sonra bir kolaylık yaratır."},{"n":8,"t":"Nice şehirler var ki Rabbinin ve elçilerinin emirlerine baş kaldırdı, biz de onu çetin bir hesaba çektik ve ona görülmemiş şekilde azab ettik."},{"n":9,"t":"Onlar yaptıklarının karşılığını tatmışlardır. İşlerinin sonu tam bir hüsran olmuştur."},{"n":10,"t":"Allah onlara şiddetli bir azab hazırlamıştır. Ey inanan akıl sahipleri. Allah’tan korkun. Allah size gerçekten bir uyarıcı kitab indirmiştir."},{"n":11,"t":"İman edip salih amel işleyenleri, karanlıklardan aydınlığa çıkarmak için size Allah’ın apaçık ayetlerini okuyan bir peygamber göndermiştir. Kim Allah’a inanır ve faydalı iş yaparsa Allah onu, altlarından ırmaklar akan, içinde ebedi kalacakları cennetlere sokar. Allah böylesine gerçekten güzel bir rızk vermiştir."},{"n":12,"t":"Allah yedi kat göğü ve yerden bir o kadarını yarattı. Allah’ın buyruğu bunlar arasında iner ki, böylece Allah’ın her şeye kadir olduğunu ve her şeyi ilmiyle kuşattığını bilesiniz."}],[{"n":1,"t":"Ey peygamber! Niçin Allah’ın sana helal kıldığı şeyi, eşlerinin hayrı için kendine haram kılıyorsun? Allah çok bağışlayan, çok esirgeyendir."},{"n":2,"t":"Allah size yeminlerinizi kefaretle geri almanızı meşru kılmıştır. Allah sizin dostunuzdur. O her şeyi bilir ve her yaptığı yerindedir."},{"n":3,"t":"«Bilen, her şeyden haberi olan Allah, bana söyledi» dedi."},{"n":4,"t":"Eğer her ikinizde Allah’a tevbe ederseniz kaymış olan kalpleriniz düzelmiş olur. Şayet onun aleyhinde birbirinize arka verirseniz hiç şüphesiz ki Allah bizzat onun yardımcısıdır. Cebrail de, mü’minlerin salih olanları da. Bunların ardından bütün melekler de yardımcıdır."},{"n":5,"t":"Eğer o sizi boşarsa Rabbi ona, sizden daha iyi, kendini Allah’a veren, inanan, gönülden itaat eden, tevbe eden, ibadet eden, Allah’ın uçsuz bucaksız mülkünün yaratılışını düşünen, dul ve bakire eşler verir."},{"n":6,"t":"Ey inananlar! Kendinizi ve ailenizi, yakıtı insanlar ve taşlar olan ateşten koruyun. Onun başında, iri gövdeli, haşin, Allah’ın kendilerine buyurduğuna karşı gelmeyen ve emredildiklerini yapan melekler vardır."},{"n":7,"t":"Ey kafirler! Bugün özür dilemeyin, çünkü siz ancak yaptıklarınızın cezasını çekeceksiniz denir."},{"n":8,"t":"Ey iman edenler! Samimi bir tevbe ile Allah â dönün. Umulur ki Rabbiniz sizin kötülüklerinizi örter, Peygamberi ve O’nunla birlikte iman edenleri utandırmayacağı günde Allah sizi, içlerinden ırmaklar akan cennetlere sokar. Çünkü onların, nurları, önlerinden ve yanlarından koşar da «Ey Rabbimiz! Nurumuzu tamamla, bizi bağışla, çünkü sen her şeye kadirsin» derler."},{"n":9,"t":"Ey Peygamber! Kafirler ve münafıklarla savaş, onlara karşı sert davran. Onların varacağı yer cehennemdir. O gidecekleri yer ne kötüdür."},{"n":10,"t":"«Haydi, ateşe girenlerle beraber siz de girin!» denildi."},{"n":11,"t":"Allah inananlara da Firavun’un karısını misal gösterdi. O «Rabbim! Bana katında, cennette bir ev yap, beni Firavun’dan ve onun kötü işinden kurtar ve şu zalimler topluluğundan kurtar!» demişti."},{"n":12,"t":"Irzını korumuş olan, İmran kızı Meryem’i de Allah misal verdi. Biz, onun içine ruhumuzdan üfledik ve Rabbinin sözlerini, kitaplarını tasdik etti. Ve o gönülden itaat etti."}],[{"n":1,"t":"Sınırsız hükümdarlık elinde olan Allah, yüceler yücesidir ve O’nun her şeye gücü yeter."},{"n":2,"t":"O hanginizin daha güzel iş yapacağınızı denemek için, ölümü ve hayatı yarattı. O, üstündür, bağışlayandır."},{"n":3,"t":"Yedi göğü tabakalar halinde yaratan O’dur. Rahman’ın bu yaratmasında bir düzensizlik bulamazsın. Gözünü bir çevir bak, bir çatlak görebilir misin?"},{"n":4,"t":"Sonra gözünü iki kez daha döndür bak. Göz aradığı kusuru bulmaktan umudu keserek yorgun ve bitkin bir halde sana döner."},{"n":5,"t":"And olsun biz, dünyaya en yakın göğü lambalarla donattık. Bunları şeytanlara atılan taşlar yaptık ve onlara ateş azabını hazırladık."},{"n":6,"t":"Rablerini inkar edenler için cehennem azabı vardır. O ne kötü dönüştür."},{"n":7,"t":"Oraya atıldıklarında onun kaynarken çıkardığı uğultuyu işitirler."},{"n":8,"t":"Neredeyse cehennem öfkesinden çatlayacak! Her topluluk onun içine atıldıkça cehennem bekçileri onlara; «Size bir uyarıcı gelmedi mi?» diye sorarlar."},{"n":9,"t":"Onlar; «Evet, doğrusu bize bir uyarıcı geldi, fakat biz yalanladık ve Allah hiçbir şey indirmedi, siz büyük bir sapıklık içindesiniz» dedik."},{"n":10,"t":"Eğer kulak vermiş veya akletmiş olsaydık, çılgın alevli cehennemlikler içinde olmazdık derler."},{"n":11,"t":"Böylece günahlarını itiraf ederler. Çılgın alevli cehennemlikler yok olsunlar!"},{"n":12,"t":"Fakat görmeden Rablerinden korkanlar var ya, işte onlar için bağışlanma ve büyük mükafat vardır."},{"n":13,"t":"Sözünüzü ister gizleyin, ister açığa vurun; bilin ki O, kalplerde olanı bilir."},{"n":14,"t":"Yaratan bilmez olur mu? O, latiftir, haberdardır."},{"n":15,"t":"Yeryüzünü size boyun eğdiren O’dur. Şu halde yerin sırtlarında dolaşın ve Allah’ın rızkından yiyin. Dönüş ancak O’nadır."},{"n":16,"t":"Gökte olanın sizi yere batırmayacağından emin misiniz? O zaman yer sarsıldıkça sarsılır."},{"n":17,"t":"Gökte olanın başınıza taş yağdırmasından güvende misiniz? Benim uyarmamın nasıl olduğunu yakında bileceksiniz."},{"n":18,"t":"And olsun ki, onlardan öncekiler de peygamberlerini yalanlamışlardı, ancak benim intikamım nasıl olmuştu?"},{"n":19,"t":"Üzerlerinde kanat çırparak uçan dizi dizi kuşları görmezler mi? Onları havada Rahman olan Allah’tan başkası tutmuyor; doğrusu o her şeyi görendir."},{"n":20,"t":"Rahman olan Allah’a karşı size yardım edecek askerleriniz hani kimlerdir? Kâfirler derin bir gaflet ve aldanma içindedirler."},{"n":21,"t":"Allah, rızkını tutacak olursa size rızk verecek kimdir? Doğrusu onlar azgınlık ve nefret içinde direnmektedirler."},{"n":22,"t":"Yüzükoyun sürünen mi, yoksa doğru yolda düpedüz yürüyen mi daha doğru yoldadır?"},{"n":23,"t":"«Sizi yaratan, size kulaklar, gözler ve kalpler veren O’dur. Ne az şükrediyorsunuz.»"},{"n":24,"t":"Sizi yeryüzünde çoğaltıp yayan O’dur, ancak O’nun huzuruna gelip toplanacaksınız."},{"n":25,"t":"«Doğru sözlü iseniz söyleyin, bu tehdit hani ne zaman gerçekleşecek?» derler."},{"n":26,"t":"«O bilgi ancak Allah’a mahsustur. Ben ise sadece açık sözlü bir uyarıcıyım.»"},{"n":27,"t":"Fakat azabı gördükleri zaman, inkar edenlerin yüzleri kararır ve kendilerine «işte sizin arayıp durduğunuz budur» denir."},{"n":28,"t":"«Allah beni ve benimle beraber bulunanları isterse yok eder veya isterse merhamet eder; söyleyin bu taktirde kâfirleri can yakıcı azaptan kim kurtarabilir?»"},{"n":29,"t":"«O Allah, Rahmandır; biz O’na iman etmiş ve sırf O’na güvenip dayanmışızdır. Siz kimin apaçık sapıklıkta olduğunu yakında öğreneceksiniz.»"},{"n":30,"t":"«Suyunuz yere batarsa söyleyin, size kim temiz bir su kaynağı getirebilir?»"}],[{"n":1,"t":"Nun. Kaleme ve onunla yazdıranlara and olsun."},{"n":2,"t":"Rabbinin vahyi, sana ihsan ettiği peygamberlik nimeti sebebiyle, sana deli de, cinlere mahkûm olmuş biri de diyemezler. Sen deli de, cinlere mahkûm olmuş biri de değilsin."},{"n":3,"t":"Senin için kesintisiz bir mükafat vardır."},{"n":4,"t":"Ve sen yüce bir ahlaka sahipsin."},{"n":5,"t":"Sen de göreceksin, onlar da görecekler."},{"n":6,"t":"Hanginizin sınandığını."},{"n":7,"t":"Şüphesiz Rabbin, kimlerin kendi yolundan saptığını ve kimlerin doğru yolda olduğunu herkesten iyi bilir."},{"n":8,"t":"Öyleyse yalanlayanlara itaat etme."},{"n":9,"t":"Onlar istediler ki, sen yumuşak davranasın da onlar da sana yumuşak davransınlar."},{"n":10,"t":"Yemin edip duran aşağılık."},{"n":11,"t":"Herkesi kınayan, söz götürüp getiren."},{"n":12,"t":"Hayra engel olan, saldırgan, günahkar."},{"n":13,"t":"Kaba, sonra da soysuz, alçak."},{"n":14,"t":"Mal ve oğullar sahibi olmuş diye (yolunu şaşırmış)"},{"n":15,"t":"«Eskilerin masalları» dedi."},{"n":16,"t":"Biz yakında onun burnuna damga vuracağız."},{"n":17,"t":"Biz, vakti ile «bahçe sahiplerini» sınadığımız gibi, onları da sınadık. Hani onlar (bahçe sahipleri) sabah olurken kimse görmeden onun mahsullerini toplayacaklarına yemin etmişlerdi."},{"n":18,"t":"Onlar istisna da etmiyorlardı."},{"n":19,"t":"Ancak onlar uyurken Rabbin katından gönderilen bir salgın o bahçeyi sarıvermişti de."},{"n":20,"t":"Bahçe simsiyah olmuştu."},{"n":21,"t":"Sabahleyin birbirlerine seslendiler."},{"n":22,"t":"Haydi ürünleri toplayacaksanız erkenden ekininize gidin diye."},{"n":23,"t":"Derken yürüdüler ve şöyle fısıldaşıyorlardı:"},{"n":24,"t":"Sakın bugün hiçbir yoksul bahçeye girip yanınıza sokulmasın."},{"n":25,"t":"Ürünleri toplayacaklarından emin olarak erkenden gittiler."},{"n":26,"t":"Fakat bahçeyi görünce «Herhalde biz yolu şaşırdık» dediler."},{"n":27,"t":"Hayır doğrusu biz mahrum bırakıldık."},{"n":28,"t":"Ortancaları, «Ben size demedim mi? Allah’ı noksan sıfatlardan tenzih etmeniz gerekmez miydi?» dedi."},{"n":29,"t":"«Rabbimizi tesbih ederiz, doğrusu biz kendi kendimize zulüm etmişiz» dediler."},{"n":30,"t":"Ardından, kabahati birbirlerine yüklemeye başladılar."},{"n":31,"t":"«Yazıklar olsun bize! Gerçekten biz azgın kimselermişiz.»"},{"n":32,"t":"Belki Rabbimiz bize bundan daha iyisini verir; doğrusu artık, Rabbimizden dilemekteyiz."},{"n":33,"t":"İşte azab böyledir. Ahiret azabı ise elbette daha büyüktür. Keşke bilselerdi."},{"n":34,"t":"Muttakiler içinde Rabbleri katında nimet bahçeleri vardır."},{"n":35,"t":"Öyle ya biz Müslümanları o günahkarlarla bir tutar mıyız hiç?"},{"n":36,"t":"Size ne oluyor? Ne biçim hüküm veriyorsunuz?"},{"n":37,"t":"Yoksa bir kitabınız var da ondan mı bu hükümleri okuyorsunuz?"},{"n":38,"t":"Onda beğendiğiniz her şeyi mi buluyorsunuz?"},{"n":39,"t":"Yoksa «İstediğiniz gibi hükmedebilirsiniz» diye sizin lehinize olarak tarafımızdan verilmiş kıyamet gününe kadar geçerli kesin sözler mi var?"},{"n":40,"t":"Bu iddiayı onların hangisi savunacak?"},{"n":41,"t":"Yoksa kendilerinin ortakları mı var? Doğru iseler ortaklarını çağırsınlar."},{"n":42,"t":"O gün işin dehşetinden baldırlar açılır; ve secdeye davet edilecekleri gün secde edemezler."},{"n":43,"t":"Gözleri dönmüş olarak yüzlerini zillet kaplar. Onlar sağlam iken de secdeye davet edildiler fakat secde etmezlerdi."},{"n":44,"t":"Bu sözü yalanlayanı bana bırak; onları bilmedikleri yerden derece derece azaba yaklaştıracağız."},{"n":45,"t":"Onlara mühlet veriyorum. Doğrusu benim tuzağım sağlamdır."},{"n":46,"t":"Yoksa sen onlardan bir ücret istiyorsun da onlar ağır borç altında mı kalıyorlar?"},{"n":47,"t":"Yoksa gaybın bilgisi kendi yanlarında da onlar mı istedikleri gibi yazıyorlar?"},{"n":48,"t":"Sen Rabbinin hükmünü sabırla bekle. Balık sahibi Yunus gibi olma, o pek üzgün olarak Rabbine seslenmişti."},{"n":49,"t":"Şayet Rabbinden ona bir nimet yetişmemiş olsaydı, o mutlaka çırıl çıplak, kınanacak bir halde bir yere atılırdı."},{"n":50,"t":"Fakat Rabbi O’nun duasını kabul etti de onu salih insanlardan yaptı."},{"n":51,"t":"Doğrusu kafirler Kuran’ı dinlediklerinde neredeyse seni gözleriyle yıkıp devireceklerdi. «O delidir» diyorlardı."},{"n":52,"t":"Oysa Kur’an alemler için bir öğütten başka bir şey değildir."}],[{"n":1,"t":"Elbette gerçekleşecek olan"},{"n":2,"t":"Nedir o muhakkak gerçekleşecek olan"},{"n":3,"t":"O gerçekleşecek olanı sana bildiren nedir?"},{"n":4,"t":"Semûd ve Âd, mutlaka patlak verecek olan kıyameti yalan saydılar."},{"n":5,"t":"Böylece Semûd korkunç bir sesle yıkıma uğratıldı."},{"n":6,"t":"Âd’a gelince onlar da, uğultu yüklü, azgın bir kasırga ile yıkıma uğratıldı."},{"n":7,"t":"Onu, yedi gece ve sekiz gün, aralık vermeksizin onların üzerine musallat etti. Öyle ki, o kavmi, orada içi kof hurma kütükleriymiş gibi onların çarpılıp yere yıkıldığını görürsün."},{"n":8,"t":"Şimdi onlardan hiç arta kalan görüyor musun?"},{"n":9,"t":"Firavun, ondan öncekiler ve yerle bir olan şehirler o hata ile geldiler."},{"n":10,"t":"Böylece Rablerinin elçisine isyan ettiler. Bu yüzden onları, şiddeti gittikçe artan bir yakalayışla yakaladı."},{"n":11,"t":"Sular kabarınca biz sizi akıp giden (gemide) taşıdık ki;"},{"n":12,"t":"Onu size bir ibret yapalım ve belleyen kulaklar onu bellesin."},{"n":13,"t":"Sura birinci üfleme üflendiği,"},{"n":14,"t":"Yer ve dağlar yerlerinden kaldırılıp bir çarpışla birbirlerine çarpıldığı zaman,"},{"n":15,"t":"İşte o vak’a olmuştur."},{"n":16,"t":"Gök yarılmış, o gün o; zayıflamış sarkmıştır."},{"n":17,"t":"Melekler de onun kenarlarındadır. O gün Rabblerinin tahtını, bunların da üstünde sekiz (melek) taşır."},{"n":18,"t":"O gün hesap için huzura alınırsınız. Hiçbir sırrınız gizli kalmaz."},{"n":19,"t":"«Alın kitabımı okuyun,"},{"n":20,"t":"Ben hesabımın inceleneceğini sezmiştim» der."},{"n":21,"t":"Artık o memnun edici bir hayat içindedir."},{"n":22,"t":"Yüksek bir bahçede ki,"},{"n":23,"t":"Meyvelerin devşirilmesi kolaydır."},{"n":24,"t":"Geçmiş günlerde yaptığınız işlerden ötürü afiyetle yiyin için."},{"n":25,"t":"«Keşke bana kitabım verilmeseydi,"},{"n":26,"t":"Şu hesabımı hiç görmemiş olsaydım!"},{"n":27,"t":"Keşke (ölüm işimi) bitirmiş olsaydı!"},{"n":28,"t":"Malım bana hiçbir fayda vermedi,"},{"n":29,"t":"Gücüm benden yok olup gitti.»"},{"n":30,"t":"«Tutun onu, bağlayın onu,"},{"n":31,"t":"Sonra cehenneme sallayın onu."},{"n":32,"t":"Sonra uzunluğu yetmiş arşın olan zincire vurun onu!"},{"n":33,"t":"Çünkü o Büyük Allah’a inanmıyordu."},{"n":34,"t":"Yoksulu doyurmaya önayak olmazdı.»"},{"n":35,"t":"Bugün onun için candan bir dost yoktur."},{"n":36,"t":"İrinden başka yiyecek yoktur."},{"n":37,"t":"Onu (bile bile) hata işleyenlerden başkası yemez."},{"n":38,"t":"Yoo yemin ederim; gördüklerinize"},{"n":39,"t":"Ve görmediklerinize ki,"},{"n":40,"t":"O (Kur’an), elbette şerefli bir peygamberin sözüdür."},{"n":41,"t":"O, bir şairin sözü değildir. Ne de az inanıyorsunuz!"},{"n":42,"t":"Bir kâhinin sözü de değildir. Ne kadar da az düşünüyorsunuz!"},{"n":43,"t":"Kur’an alemlerin Rabbinden indirilmiştir."},{"n":44,"t":"Eğer Muhammed, bize karşı ona bazı sözler katmış olsaydı."},{"n":45,"t":"Biz onu kuvvetle yakalardık,"},{"n":46,"t":"Sonra onun şah damarını koparırdık."},{"n":47,"t":"Hiçbiriniz de onu koruyamazdınız."},{"n":48,"t":"Doğrusu Kur’an Allah’a karşı gelmekten sakınanlara bir öğüttür."},{"n":49,"t":"İçinizde yalanlayanlar bulunduğunu şüphesiz bilmekteyiz."},{"n":50,"t":"Doğrusu Kur ân inkarcılar için bir üzüntüdür."},{"n":51,"t":"O, şüphesiz kesin gerçektir."},{"n":52,"t":"Öyleyse ey insanlar! Çok büyük olan Rabbinin adını tesbih et."}],[{"n":1,"t":"Bir isteyen, inecek azabı istedi."},{"n":2,"t":"Kafirlerin başına; ki onu savacak yoktur."},{"n":3,"t":"Yükselme derecelerinin sahibi Allah’tandır."},{"n":4,"t":"Melekler ve ruh, miktarı elli bin yıl süren bir gün içinde O’na yükselir."},{"n":5,"t":"Şimdi sen güzelce sabret."},{"n":6,"t":"Onlar onu uzak görüyorlar."},{"n":7,"t":"Biz ise onu yakın görüyoruz."},{"n":8,"t":"O gün gök, erimiş bakır gibi olur."},{"n":9,"t":"Dağlar, atılmış renkli yün gibi olur."},{"n":10,"t":"Dost dostun halini sormaz."},{"n":11,"t":"oğullarını,"},{"n":12,"t":"eşini ve kardeşini,"},{"n":13,"t":"kendisini barındıran, içinde yetiştiği tüm ailesini."},{"n":14,"t":"Ve yeryüzünde bulunanların hepsini versin de tek kendisini kurtarsın."},{"n":15,"t":"Hayır! O alevden bir ateştir."},{"n":16,"t":"Deriler kavurur, soyar."},{"n":17,"t":"Kendine çağırır; sırtını dönüp gideni."},{"n":18,"t":"Mal toplayıp kasada yığanı."},{"n":19,"t":"Doğrusu insan hırslı ve huysuz yaratılmıştır."},{"n":20,"t":"Kendisine kötülük dokundu mu sızlanır."},{"n":21,"t":"Kendisine hayır dokundu mu yoksullara yardım etmez.."},{"n":22,"t":"Ancak namaz kılanlar bunun dışındadır."},{"n":23,"t":"Namazlarını sürekli kılarlar aksatmazlar."},{"n":24,"t":"Mallarında belli bir hisse vardır."},{"n":25,"t":"Saile ve mahruma."},{"n":26,"t":"Ceza gününü tasdik ederler."},{"n":27,"t":"Ve onlar ki; Rabblarının azabından korkarlar."},{"n":28,"t":"Çünkü Rabblerinin azabına güven olmaz."},{"n":29,"t":"Irzlarını korurlar."},{"n":30,"t":"Yalnız eşlerine ya da ellerinin altında bulunan cariyelere karşı korumazlar. Bundan ötürü de onlar kınanmazlar."},{"n":31,"t":"Ama kim bundan ötesini ararsa, onlar sınırı aşanlardır."},{"n":32,"t":"Emanetlerini ve ahidlerini gözetirler."},{"n":33,"t":"Şahidliklerini yaparlar."},{"n":34,"t":"Namazlarını korurlar."},{"n":35,"t":"İşte onlar cennetlerde ağırlanırlar."},{"n":36,"t":"O nankörlere ne oluyor ki sana doğru koşuyorlar"},{"n":37,"t":"Sağdan, soldan, ayrı ayrı gruplar halinde gelip etrafını sarıyorlar."},{"n":38,"t":"Onlardan her biri, nimet cennetine sokulacağını mı umuyor yoksa?"},{"n":39,"t":"Hayır! Öyle şey yok. Aldatıcı akıbetten kurtulamazlar onlar. Biz onları bildikleri şeyden yarattık."},{"n":40,"t":"Yoo, doğuların ve batıların Rabbine yemin ederim ki bizim gücümüz yeter."},{"n":41,"t":"Onları, kendilerinden daha hayırlı olanlarla değiştirmeğe. Bizim önümüze geçilmez."},{"n":42,"t":"Bırak onları kendilerine va’dedilen günlerine kavuşuncaya kadar dalsın oynasınlar."},{"n":43,"t":"O gün kabirlerden hızlı hızlı çıkarlar. Onlar dikilen putlara yahut hedeflere doğru koşar gibi koşarlar."},{"n":44,"t":"Gözleri düşük, yüzlerini alçaklık bürümüş bir durumda. İşte onlara vaadedilen gün, bugündür."}],[{"n":1,"t":"Milletine can yakıcı bir azab gelmezden önce onları uyar diye Nuh’u milletine peygamber olarak gönderdik."},{"n":2,"t":"«Ey milletim! Şüphesiz ben, size gönderilmiş apaçık bir uyarıcıyım.»"},{"n":3,"t":"Allah’a kulluk edin; ondan sakının ve bana itaat edin."},{"n":4,"t":"Ki Allah günahlarınızı size bağışlasın ve sizi belli bir süreye kadar ertelesin; doğrusu Allah’ın belirttiği süre gelince geri bırakılmaz; keşki bilseniz."},{"n":5,"t":"«Rabbim! Doğrusu ben, milletimi gece gündüz çağırdım.»"},{"n":6,"t":"Fakat benim çağırmam, sadece benden uzaklıklarını artırdı.»"},{"n":7,"t":"Doğrusu ben senin onları bağışlaman için kendilerini her çağrışımda, parmaklarını kulaklarına tıkadılar, elbiselerine büründüler, direndiler, büyüklendikçe büyüklendiler."},{"n":8,"t":"Sonra, doğrusu ben onları açıkça çağırdım."},{"n":9,"t":"Sonra onlara açıktan açığa, gizliden gizliye de söyledim."},{"n":10,"t":"«Rabbiniz’den bağışlanma dileyin; doğrusu O, çok bağışlayandır.."},{"n":11,"t":"Size gökten bol bol yağmur indirsin.»"},{"n":12,"t":"Sizi, mallar ve oğullarla desteklesin; sizin için bahçeler var etsin, ırmaklar akıtsın."},{"n":13,"t":"Ne oluyorsunuz ki Allah’a büyüklüğü yakıştıramıyorsunuz."},{"n":14,"t":"Oysa sizi merhalelerden geçirerek O yaratmıştır."},{"n":15,"t":"Allah’ın, göğü yedi kat üzerine nasıl yarattığını görmez misiniz?"},{"n":16,"t":"Aralarında Ay’a aydınlık vermiş ve güneşin ışık saçmasını sağlamıştır."},{"n":17,"t":"Allah sizi yerden bitirir gibi yetiştirmiştir."},{"n":18,"t":"Sonra sizi oraya döndürür ve yine oradan çıkarır."},{"n":"19-20","t":"Yeryüzünde dolaşabilmeniz, orada yollar ve geniş geçitlerden geçebilmeniz için, onu size yayan O’dur."},{"n":21,"t":"«Rabbim doğrusu bunlar bana isyan ettiler. Ve malı, çocuğu kendisine sadece zarar getiren kimseye uydular.»"},{"n":22,"t":"Birbirinden büyük düzenler kurdular."},{"n":23,"t":"İnsanlara ’sakın tanrılarınızı bırakmayın, Ved, Suva, Yağus, Yeuk ve Nesr putlarından asla vazgeçmeyin’ dediler."},{"n":24,"t":"Böylece birçoğunu saptırdılar; Rabbim! Sen bu zalimlerin sadece şaşkınlığını arttır."},{"n":25,"t":"Onlar, günahları yüzünden suda boğuldular; ateşe sokuldular, kendilerine Allah’tan başka yardımcı bulamadılar."},{"n":26,"t":"\"Ey Rabbim!\" diye yakardı. \"Yeryüzünde senden gelen gerçekleri örtbas edenlerden bir tek kişi bile bırakma."},{"n":27,"t":"Doğrusu sen onları bırakırsan kullarını saptırırlar, sadece ahlâksız ve çok inkarcıdan başkasını doğurup yetiştirmezler."},{"n":28,"t":"\"Ey Rabbim! Beni, anne babamı, evime inanmış olarak gireni, inanan erkek ve kadınları bağışla. Bu zâlimlerin de helâklerinden başka bir şeyini arttırma!\"[682]"}],[{"n":1,"t":"Biz harikulâde bir Kur’an dinledik."},{"n":2,"t":"O doğru yola iletiyor. Hemen inandık ona. Artık Rabbimize hiçbir ortak koşmayacağız."},{"n":3,"t":"Rabbimiz yüceler yücesidir, ne eş ne evlat edinmemiştir."},{"n":4,"t":"Meğer aramızdaki aptallar Allah hakkında asılsız sözler söylüyorlarmış."},{"n":5,"t":"Oysa biz insanların ve cinlerin Allah katında yalan sözler söyleyebileceklerine ihtimal vermiyorduk."},{"n":6,"t":"Birtakım insanlar birtakım cinlere sığınırlar ve bu tutum onların sapıklıklarını arttırır."},{"n":7,"t":"O sapık insanlar, tıpkı sizler gibi, Allah’ın hiç kimseyi yeniden diriltmeyeceğini sanmışlardır."},{"n":8,"t":"Göğü yokladık, orayı sert bekçilerle ve göktaşları ile dopdolu bulduk."},{"n":9,"t":"Daha önce göğün elverişli dinleme yerlerinde pusuya yatardık. Fakat şimdi hangimiz oranın seslerini işitmeye çalışsa kendisini bekleyen göktaşları ile karşılaşır."},{"n":10,"t":"Acaba yeryüzündekiler için kötülük mü dileniyor, yoksa Rabbleri onlar hakkında iyilik mi diliyor, bunu bilmiyoruz."},{"n":11,"t":"Aramızda iyiler de var, bu düzeye erişememiş olanlar da var; farklı yollara ayrıldık."},{"n":12,"t":"Yeryüzünde Allah ile baş edemeyeceğimizi ve O’ndan kaçıp kurtulamayacağımızı kesinlikle anladık."},{"n":13,"t":"Biz doğru yola ileten Kur’ân’ı işitir işitmez ona inandık. Kim Rabbine inanırsa ne haksızlığa uğramaktan ve ne zora koşulmaktan korkar."},{"n":14,"t":"Aramızda Müslümanlar olduğu gibi gerçeğe sırt çevirenler de var. Müslüman olanlar, doğruyu arayıp bulanlardır."},{"n":15,"t":"Gerçeğe sırt çevirenler ise cehennem odunlarıdırlar."},{"n":16,"t":"Eğer onlar doğru yola girselerdi kendilerine gürül gürül su sunardık."},{"n":17,"t":"Böylece onları sınavdan geçirirdik. Kim Rabbini anmaktan vazgeçerse gittikçe artan ağır azaba çarptırılır."},{"n":18,"t":"Mescidler, camiler Allah içindirler. Öyleyse oralarda Allah’ın yanısıra başkasına yalvarmayınız."},{"n":19,"t":"Allah’ın kulu Muhammed, Rabbine yalvarmaya durunca müşrikler birbirlerine abanarak keçe gibi çevresini sararlardı."},{"n":20,"t":"«Ben sırf Rabbime yalvarırım, O’na hiç kimseyi ortak koşmam.»"},{"n":21,"t":"«Ben size ne zarar verebilirim ve ne de fayda sağlayabilirim.»"},{"n":22,"t":"«Hiç kimse beni Allah’ın elinden kurtaramaz; ben O’nun dışında hiçbir sığınak bulamam.»"},{"n":23,"t":"Benim görevim, sadece Allah’tan gelen direktifleri, O’nun mesajını duyurmaktır. Allah’a ve Peygamber’e başkaldıranları, içinde sürekli kalacakları cehennem ateşi bekliyor."},{"n":24,"t":"Onlar kendilerine yönelik tehditlerin somut olarak gerçekleştiğini gördüklerinde hangi tarafın destek bakımından zayıf ve sayıca az olduğunu anlayacaklardır."},{"n":25,"t":"«Size yöneltilen tehdit yakın mıdır, yoksa Rabbim onun için uzun bir vade mi belirlemiştir, bilmiyorum.»"},{"n":26,"t":"Gaybın bilgisi O’nun tekelindedir. O gaybın sırlarını hiç kimseye açmaz."},{"n":27,"t":"Bu sırları sadece seçtiği peygamberlerine açar. Onların önlerinden ve arkalarından gözcüler, korucular salar."},{"n":28,"t":"Böylece onların, Rabblerinin mesajlarını insanlara duyurduklarını belirler. O onların durumlarını ve tutumlarını bilgisi ile kuşatmış, herşeyi bir bir saymıştır."}],[{"n":1,"t":"Ey örtüye bürünerek saklanan Muhammed,"},{"n":2,"t":"Geceleyin biraz uyuduktan sonra kalk"},{"n":3,"t":"Gecenin yarısında uyanık ol, ya bu miktarı biraz eksilt"},{"n":4,"t":"Ya da artır da ağır ağır Kur’an oku."},{"n":5,"t":"Çünkü biz sana sorumluluğu ağır bir söz indireceğiz."},{"n":6,"t":"Kuşkusuz gece ibadeti, gündüze göre daha zor, fakat sözü daha etkilidir."},{"n":7,"t":"Çünkü gündüzleri, seni uzun uzun uğraştıracak işlerin vardır."},{"n":8,"t":"Rabbinin adını an, bütün varlığınla O’na yönel!"},{"n":9,"t":"O doğunun da, batının da Rabbidir, O’ndan başka ilah yoktur. O halde tek dayanağın O olsun."},{"n":10,"t":"Müşriklerin senin için dediklerine sabret, yanlarından nazik bir şekilde ayrıl."},{"n":11,"t":"Ayetlerimi yalanlayan o zenginlerin işini bana bırak, onlara biraz süre tanı."},{"n":12,"t":"Çünkü bizim yanımızda ağır zincirler ile cehennem vardır."},{"n":13,"t":"İnsan boğazından geçmez yiyecekler ile acıklı azap vardır."},{"n":14,"t":"O gün yer ve dağlar şiddetle sarsılır, dağlar gevşek kum yığınlarına dönüşür."},{"n":15,"t":"Ey insanlar, biz nasıl Firavuna bir peygamber gönderdiysek size de davranışlarınızı yakından gözleyecek bir peygamber gönderdik."},{"n":16,"t":"Firavun, gönderdiğimiz peygambere karşı geldi de kendisini sert bir şekilde yakalayıverdik."},{"n":17,"t":"Eğer kafir olursanız, çocukların saçlarını anında ağartan o günün dehşetinden paçayı nasıl kurtaracaksınız?"},{"n":18,"t":"O günün dehşetinden gökler parçalanacaktır. Allah’ın sözü kesinlikle yerine gelir."},{"n":19,"t":"Bu söylenenler bir öğüttür. Dileyen, Rabbine erdirecek yolu tutar."},{"n":20,"t":"Senin ve bazı arkadaşlarının, gecenin ya üçte ikisine yakın bölümünü ya yarısını ya da üçte birini ibadetle geçirdiğinizi Rabbin biliyor. Gecenin ve gündüzün sürelerini belirleyen Allah’tır. O bu gece ibadetinin temposuna dayanamayacağınızın farkındadır. Bundan böyle kolayınıza gelecek kadar Kur’an okuyunuz. Aranızda hastalar olacağını, bir bölümünüzün Allah’ın lütfettiği geçim payını elde edebilmek için yeryüzünde oradan oraya koştuğunu, bir bölümünüzün de O’nun yolunda savaştığını Allah biliyor. Öyleyse kolayınıza gelecek kadar Kur’an okuyunuz. Namazı kılınız, zekatı veriniz, gönüllü olarak ve karşılık beklemeksizin Allah’a borç veriniz. Kendiniz için yaptığınız hayırları ilerde Allah katında daha yararlı ve daha büyük ödüllü olarak bulursunuz. Allah’tan af dileyiniz. Hiç kuşkusuz Allah bağışlayıcı ve merhametlidir."}],[{"n":1,"t":"Ey örtüye bürünerek saklanan Muhammed!"},{"n":2,"t":"Kalk da uyar."},{"n":3,"t":"Rabbinin büyüklüğünü dile getir."},{"n":4,"t":"Elbiselerini temizle."},{"n":5,"t":"Çirkin davranışlardan uzak dur."},{"n":6,"t":"Yaptığın iyiliği çok görüp başa kakma."},{"n":7,"t":"Rabbin için sabret."},{"n":8,"t":"O Sur’a üflendiği zaman,"},{"n":9,"t":"O gün çetin bir gündür."},{"n":10,"t":"Kafirler için hiç de kolay değildir."},{"n":11,"t":"Şu adamın işini bana bırak ki, kendisini yarattığımda yapayalnızdı."},{"n":12,"t":"Ona bol bol mal verdim."},{"n":13,"t":"Gözü önünden ayrılmayan evlatlar verdim."},{"n":14,"t":"Her işini yoluna koydum."},{"n":15,"t":"Böyleyken halâ daha çoğunu vermemi bekliyor."},{"n":16,"t":"Hayır, hayır! O ayetlerimize inatla karşı çıkıyor."},{"n":17,"t":"Onu sarp bir yokuşa saracağım."},{"n":18,"t":"O düşündü ve değerlendirme yaptı."},{"n":19,"t":"Kahrolası, nasıl bir değerlendirme yaptı?"},{"n":20,"t":"Bir daha kahrolası, nasıl bir değerlendirme yaptı?"},{"n":21,"t":"Sonra baktı,"},{"n":22,"t":"Sonra suratını astı ve kaşlarını çattı."},{"n":23,"t":"Sonra yüz çevirdi, büyüklük tasladı."},{"n":24,"t":"Ve dedi ki; «Bu Kur’an eskilerden aktarılan bir büyüdür."},{"n":25,"t":"O kesinlikle insan sözüdür.»"},{"n":26,"t":"Onu Sekar’a atacağım."},{"n":27,"t":"Sekar nedir, biliyor musun?"},{"n":28,"t":"Geride hiçbir şey bırakmaz, ondan hiçbir şey kurtulmaz."},{"n":29,"t":"Bütün insanların dikkatlerini üzerinde yoğunlaştırır."},{"n":30,"t":"On dokuz tane görevlisi vardır."},{"n":31,"t":"\"Allah bununla ne demek istedi\" desinler. İşte böyle. Allah dilediğini saptırır, dilediğini de hidayete eriştirir. Rabbinin ordularının sayısını ancak kendisi bilir. Bu insan için bir öğüttür."},{"n":32,"t":"Hayır, hayır! Andolsun aya,"},{"n":33,"t":"Gerileyen gece karanlığına,"},{"n":34,"t":"Söken şafağa."},{"n":35,"t":"Sakar (cehennem) büyük gerçeklerden biridir."},{"n":36,"t":"İnsanlar için uyarıcıdır."},{"n":37,"t":"Aranızdaki ilerlemek isteyenler için de, geriye gitmeyi tercih edenler için de."},{"n":38,"t":"Herkes tutumunun ve davranışlarının tutsağıdır."},{"n":39,"t":"Yalnız defterleri sağ yanlarından verilenler hariç."},{"n":40,"t":"Onlar cennetlerde ağırlanırlar. Sorarlar."},{"n":41,"t":"Günahkârlara:"},{"n":42,"t":"Sakar’a (cehenneme) girmenizin sebebi nedir? diye."},{"n":43,"t":"Cehennemlikler derler ki; «Biz namaz kılanlardan değildik."},{"n":44,"t":"Yoksulların karnını doyurmazdık."},{"n":45,"t":"Bizim gibi olanlarla birlikte asılsız ve bozguncu konuşmalara dalardık."},{"n":46,"t":"Hesap verme gününü inkar ederdik."},{"n":47,"t":"Sonunda bir de ölüm gelip çattı.»"},{"n":48,"t":"Artık onlara şefaat edebilecek olanların aracılığı yarar sağlamaz."},{"n":49,"t":"O halde onlar niye hatırlatmalara, öğütlere yüz çeviriyorlar?"},{"n":50,"t":"Yaban eşekleri gibidirler."},{"n":51,"t":"Arslandan korkup kaçan."},{"n":52,"t":"Aslında bunların her biri, kendisine okunmaya hazır kutsal sayfalar inmesini istiyor."},{"n":53,"t":"Hayır, hayır! Aslında onlar ahiretten korkmuyorlar."},{"n":54,"t":"Hayır, hayır! Bu Kur’an bir öğüt, bir hatırlatmadır."},{"n":55,"t":"İsteyen ondan ders alır."},{"n":56,"t":"Fakat Allah dilemedikçe onlar bundan ders alamazlar. O kendisinden korku duyulmaya ve affetmeye lâyıktır."}],[{"n":1,"t":"Yoo, andolsun kıyamet gününe."},{"n":2,"t":"Yoo andolsun, özünü eleştiren, kendini kınayan nefse."},{"n":3,"t":"İnsan, kemiklerini biraraya toplayamayız mı sanıyor?"},{"n":4,"t":"Hayır, onun parmak uçlarını bile yeniden yapılandırmaya gücümüz yeter."},{"n":5,"t":"Aslında insan günahkârlığı önüne, geleceğine yaymak istiyor."},{"n":6,"t":"Bu yüzden «Kıyamet günü ne zaman?» diye soruyor."},{"n":7,"t":"Gözler korkudan fıldır fıldır döndükleri zaman,"},{"n":8,"t":"Ay karardığı zaman,"},{"n":9,"t":"Güneş ile ay biraraya getirildiği zaman,"},{"n":10,"t":"İnsan o gün «Nereye kaçmalı?» der."},{"n":11,"t":"Hayır hayır! Sığınılacak bir yer yok."},{"n":12,"t":"O gün tek varılacak yer Rabbinin huzurudur."},{"n":13,"t":"O gün insanın gerek yapıp önünden gönderdiği, gerekse arkasında izleri kalan tüm işleri kendisine bildirilir."},{"n":14,"t":"Aslında insan kendi kendinin denetleyicisidir."},{"n":15,"t":"Birtakım mazeretler ileri sürse de."},{"n":16,"t":"Ey Muhammed, Cebrail sana Kur’an’ı okurken, acele edip onun söylediklerini tekrarlama."},{"n":17,"t":"Bu Kur’an’ı senin hafızanda toplamak ve sana okumak bize düşen bir iştir."},{"n":18,"t":"Sana onu okuduğumuzda, onun okunuşunu izle."},{"n":19,"t":"Sonra onu sana açıklamak da bize düşen bir iştir."},{"n":20,"t":"Hayır hayır! Ey insanlar, sizler şu kısa süreli dünyayı seviyorsunuz."},{"n":21,"t":"Ahireti gözardı ediyorsunuz."},{"n":22,"t":"O gün birtakım yüzler ışıl ışıl parlar."},{"n":23,"t":"Onlar Rabblerine bakar."},{"n":24,"t":"O gün birtakım suratlar da asıktır."},{"n":25,"t":"Bel kırıcı bir belaya uğrayacakları kaygısını taşırlar."},{"n":26,"t":"Hayır hayır, can köprücük kemiğine dayandığı zaman."},{"n":27,"t":"Bu hastayı iyileştirecek biri yok mu? diye sorarlar."},{"n":28,"t":"Adam, ayrılma zamanının geldiğini anlar."},{"n":29,"t":"Çırpınırken ayakları birbirine dolaşır."},{"n":30,"t":"O gün Rabbine doğru yolculuk vardır."},{"n":31,"t":"Adam ne inandı, ne namaz kıldı."},{"n":32,"t":"Tersine inkâr etti ve sırt çevirdi."},{"n":33,"t":"Sonra çalım satarak ailesinin yanına döndü."},{"n":34,"t":"Vay başına geleceklere!"},{"n":35,"t":"Yine vay başına geleceklere!"},{"n":36,"t":"İnsanoğlu, başıboş bırakılacağını mı sanıyor?"},{"n":37,"t":"O fışkıran meniden oluşmuş bir sperma değil miydi?"},{"n":38,"t":"Sonra embriyoya dönüştü, sonra Allah onu yaratıp biçimlendirdi."},{"n":39,"t":"Sonra ondan erkek ve dişi çiftler türetti."},{"n":40,"t":"Bunları yapan Allah, ölüleri diriltemez mi?"}],[{"n":1,"t":"İnsan, anılmaya değer bir varlık olmadan önce uzun yıllar geçti, öyle değil mi?"},{"n":2,"t":"Biz insanı sınavdan geçirmek amacı ile karışım nitelikli bir sıvı damlasından yarattık. Bunun için onu işitme ve görme yetenekleri ile donattık."},{"n":3,"t":"Biz ona yolu gösterdik. Artık ister şükreder isterse nankör olur."},{"n":4,"t":"Biz kafirler için zincirler, kelepçeler ve çılgın alevli cehennem hazırladık."},{"n":5,"t":"İyiler kâfur karışımlı bir içeceği tastan içerler."},{"n":6,"t":"Bu Allah’ın iyi kullarının istedikleri yere akmasını sağlayarak içebilecekleri bir pınardır."},{"n":7,"t":"Onlar verdikleri sözleri tutarlar ve kötülüğü yaygın günden korkarlar."},{"n":8,"t":"Onlar içleri çektiği halde yemeklerini yoksullara, yetimlere ve tutsaklara yedirirler."},{"n":9,"t":"Yemek ikram ederken derler ki; «Biz size sırf Allah rızası için yemek veriyoruz. Sizden karşılık ya da teşekkür beklemiyoruz.»"},{"n":10,"t":"Çünkü biz asık suratlı ve çetin bir günde Rabbimizden korkarız."},{"n":11,"t":"Allah da onları o günün kötülüğünden korur, yüzlerine parlaklık ve gönüllerine sevinç sunar."},{"n":12,"t":"Sabretmelerinin karşılığında kendilerini cennetle ve ipekli elbiselerle ödüllendirir."},{"n":13,"t":"Koltuklara kurulurlar. Orada ne yakıcı güneş, ne de dondurucu soğuk görürler."},{"n":14,"t":"Ağaçların gölgeleyici saçakları başlarına yakın alçaklıkta ve meyvalarının devşirilmesi son derece kolay olur."},{"n":15,"t":"Onlara gümüş tabaklarla ve saydam kadehlerle servis yapılır."},{"n":16,"t":"Bu gümüşten saydam kadehlerin büyüklükleri ihtiyaçlarına göre belirlenmiştir."},{"n":17,"t":"Onlara orada taslar içinde zencefil karışımlı içecekler sunulur."},{"n":18,"t":"Bu «selsebil» adı verilen bir cennet pınarıdır."},{"n":19,"t":"Onlara hiç ölmeyecek gençler hizmet ederler. Bu gençleri görsen, ortalığa saçılmış birer inci sanırsın."},{"n":20,"t":"Nereye baksan bir nimet ve büyük bir saltanat görürsün."},{"n":21,"t":"Üzerlerinde ince, yeşil ipekten ve atlastan elbiseler vardır, bileklerine gümüş bilezikler takılmıştır. Rabbleri onlara temiz içecekler sunmuştur."},{"n":22,"t":"Bütün bunlar iyiliklerinizin karşılığıdır, çabalarınız, hoşnutluğumuzu kazanmıştır."},{"n":23,"t":"Ey Muhammed, bu ’Kur’an’ı sana indiren biziz."},{"n":24,"t":"Rabbin hükmünü verinceye dek sabret, onların günahkârlarının ve inatçı inkârcılarının sözlerine uyma."},{"n":25,"t":"Sabah ve akşam Rabbinin adını an."},{"n":26,"t":"Gecenin bir bölümünde O’na secde et, geceleri O’nu uzun uzun tesbih et."},{"n":27,"t":"Bu adamlar şu geçici dünyayı severler ve önlerindeki o zorlu günü gözardı ederler."},{"n":28,"t":"Onları yaratan ve vücutlarına biçim veren biziz. İstediğimiz zaman onları benzerleri ile değiştiririz."},{"n":29,"t":"Bu bir hatırlatmadır. İsteyen Rabbine giden yolu tutar."},{"n":30,"t":"Allah dilemedikçe siz bir şey dileyemezsiniz. Hiç kuşkusuz Allah herşeyi bilir ve her işi yerinde yapar."},{"n":31,"t":"O dilediklerini rahmetinin kapsamı altına Alır. Zalimlere gelince O, onlar için acıklı bir azap hazırlamıştır."}],[{"n":1,"t":"Dalga dalga salınanlara,"},{"n":2,"t":"Kasırga gibi esip savuranlara,"},{"n":3,"t":"Her yana dağıtanlara,"},{"n":4,"t":"Doğruyu eğriden kesin çizgilerle ayıranlara,"},{"n":5,"t":"İlahi mesajı peygamberlere iletenlere andolsun."},{"n":6,"t":"Ya bahaneleri boşa çıkarmak ya da uyarmak amacı ile,"},{"n":7,"t":"Size söz verilen kıyamet kesinlikle kopacaktır."},{"n":8,"t":"Yıldızlar karardığı zaman,"},{"n":9,"t":"Gök parçalandığı zaman,"},{"n":10,"t":"Dağlar ufalanıp dağıldığı zaman,"},{"n":11,"t":"Peygamberlerin tanıklık sıraları geldiği zaman,"},{"n":12,"t":"Bu tanıklık hangi güne ertelendi?"},{"n":13,"t":"Hüküm gününe."},{"n":14,"t":"Hüküm gününün ne olduğunu biliyor musun?"},{"n":15,"t":"O gün inkarcıların vay haline!"},{"n":16,"t":"Önceki inkarcı toplumları yoketmedik mi?"},{"n":17,"t":"Sonraki inkarcıları da katarız onlara."},{"n":18,"t":"İşte biz günahkârlara böyle yaparız."},{"n":19,"t":"O gün inkarcıların vay haline!"},{"n":20,"t":"Sizi basit bir sıvı damlasından yaratmadık mı?"},{"n":21,"t":"Sonra o sıvı damlasını korunaklı bir yuvaya yerleştirmedik mi?"},{"n":22,"t":"belli bir süreye kadar."},{"n":23,"t":"Biz o sıvı damlacığın gelişmesini aşamalı bir plâna bağladık. Biz ne güzel plân yaparız."},{"n":24,"t":"O gün inkarcıların vay haline!"},{"n":25,"t":"Biz yeryüzünü barınak yapmadık mı?"},{"n":26,"t":"Ölüler için de diriler için de."},{"n":27,"t":"Orada yüksek dağlar yaratmadık ve size tatlı sular içirmedik mi?"},{"n":28,"t":"O gün inkarcıların vay haline!"},{"n":29,"t":"Şimdi inkar ettiğiniz yere koşunuz!"},{"n":30,"t":"Üç çatallı gölgeye koşunuz."},{"n":31,"t":"Serinlik sağlamayan ve alevden korumayan gölgeye!"},{"n":32,"t":"O saray gibi kocaman kıvılcımlar saçar."},{"n":33,"t":"Her biri birer sarı deve gibi kıvılcımlar,"},{"n":34,"t":"O gün inkarcıların vay haline!"},{"n":35,"t":"Bugün onların konuşamayacakları bir gündür."},{"n":36,"t":"Özür dilemelerine de izin verilmez."},{"n":37,"t":"O gün inkarcıların vay haline!"},{"n":38,"t":"Bugün sizi ve sizden öncekileri biraraya getirdiğimiz bir hüküm günüdür."},{"n":39,"t":"Eğer bana karşı oynayacağınız bir oyununuz varsa haydi, oynayın bakalım."},{"n":40,"t":"O gün inkarcıların vay haline!"},{"n":41,"t":"Kötülüklerden sakınanlara gelince anlar ağaç gölgeleri altında ve pınar başlarındadırlar."},{"n":42,"t":"Canlarının çektiği meyvalarla başbaşadırlar."},{"n":43,"t":"Kendilerine, \"Yaptıklarınızın karşılığı olarak şimdi âfiyetle yiyiniz, içiniz\" denilecektir. İşte biz, güzel amel yapanları böyle ödüllendiririz."},{"n":44,"t":"Biz iyilik yapanları, İşte böyle ödüllendiririz."},{"n":45,"t":"O gün inkarcıların vay haline!"},{"n":46,"t":"Şimdi yiyiniz, azıcık safa sürünüz, sizler suçlusunuz."},{"n":47,"t":"O gün inkarcıların vay haline!"},{"n":48,"t":"Onlara «rükûa varın» dendiğinde rüküa varmazlar."},{"n":49,"t":"O gün inkârcıların vay haline!"},{"n":50,"t":"Onlar Kur’an’a inanmadıktan sonra hangi söze inanacaklar?"}],[{"n":1,"t":"O inkârcıların birbirlerine sorup durdukları nedir?"},{"n":2,"t":"O büyük haberi mi?"},{"n":3,"t":"Ki onlar onda ayrılığa düştüler."},{"n":4,"t":"Hayır yakında bilecekler."},{"n":5,"t":"Yine hayır, yakında bilecekler."},{"n":6,"t":"Yeryüzünü bir beşik,"},{"n":7,"t":"Dağları da onun için birer direk kıldık."},{"n":8,"t":"Ve sizi çift çift yarattık."},{"n":9,"t":"Uykunuzu dinlenme vakti yaptık."},{"n":10,"t":"Geceyi bir örtü yaptık."},{"n":11,"t":"Gündüzü geçiminiz için çalışıp kazanma zamanı yaptık."},{"n":12,"t":"Üstünüze yedi sağlam gök bina ettik."},{"n":13,"t":"Oraya parlak kandiller astık."},{"n":14,"t":"Sıkışan bulutlardan şarıl şarıl su indirdik ki,"},{"n":"15-16","t":"Onunla taneler, bitkiler ve birbirine sarmaş dolaş olmuş ağaçlı bahçeler çıkaralım."},{"n":17,"t":"Muhakkak ki hüküm günü, belirlenmiş bir vakittir."},{"n":18,"t":"Sur’a üflendiği gün, bölük bölük Allah’a gelirsiniz."},{"n":19,"t":"O gün gökyüzü açılır ve orada pek çok kapılar oluşur."},{"n":20,"t":"Dağlar yürütülür, serap haline gelir."},{"n":21,"t":"Cehennem de suçluları gözetleyip durmaktadır."},{"n":22,"t":"Orası azgınların varacağı yerdir."},{"n":23,"t":"Orada sonsuza dek kalacaklardır."},{"n":24,"t":"Orada ne bir serinlik ne de içilecek bir şey tadarlar."},{"n":25,"t":"Yalnız kaynar su ve irin içerler."},{"n":26,"t":"Yaptıklarına uygun bir ceza olarak"},{"n":27,"t":"Çünkü onlar bir hesab görüleceğini ummuyorlardı."},{"n":28,"t":"Ayetlerimizi de tamamen yalanlamışlardı."},{"n":29,"t":"Biz de herşeyi sayıp yazmıştık."},{"n":30,"t":"Şimdi tadın, artık size azabtan başka bir şeyi artırmıyacağız."},{"n":31,"t":"Takva sahipleri için de başarı ödülü vardır."},{"n":32,"t":"Nice bahçeler, bağlar,"},{"n":33,"t":"Göğüsleri tomurcuklanmış yaşıt kızlar ve"},{"n":34,"t":"Dolu dolu kadehler"},{"n":35,"t":"Orada ne boş bir söz ve ne de yalan işitirler."},{"n":36,"t":"Bunlar Rabbinin katından yaptıklarına karşılığı verilenlerdir."},{"n":37,"t":"O, göklerin yerin ve ikisi arasında olanların Rabbidir. O, önünde kimsenin konuşamayacağı Rahman olan Allah’tır."},{"n":38,"t":"Cebrail ve meleklerin dizi dizi durdukları gün, Rahman olan Allah’ın izni olmadan kimse konuşamayacaktır. Konuştuğu zaman da doğruyu söyleyecektir."},{"n":39,"t":"işte gerçek gün budur. Dileyen kimse Rabbine götürecek bir yol benimser."},{"n":40,"t":"Sizi yakın gelecekteki azabla uyardık; o gün kişi elleriyle sunduğuna bakar ve inkarcı da «Keşke toprak olsaydım» der."}],[{"n":"1-2","t":"Andolsun doğup batan yıldızlara, yörüngelerinden çıkmadan hareket edenlere, uzayda sakin sakin yüzenlere, hayırda yarışanlara, işini mükemmel yapanlara. [713][714]"},{"n":3,"t":"Yüzüp gidenlere."},{"n":4,"t":"Yarışıp, geçenlere."},{"n":5,"t":"Derken işi düzenliyenlere!"},{"n":6,"t":"O gün bir sarsıntı sarsar."},{"n":7,"t":"Ardından bir başka sarsıntı gelir."},{"n":8,"t":"O gün kalpler titrer."},{"n":9,"t":"Gözler korkudan aşağı kayar."},{"n":10,"t":"«Biz yine eski halimize döndürülecek miyiz?"},{"n":11,"t":"Biz çürümüş kemikler olduktan sonra ha?"},{"n":12,"t":"Öyle ise bu, ziyanlı bir dönüştür» dediler."},{"n":13,"t":"Doğrusu bir tek çığlık yetecektir."},{"n":14,"t":"Hepsi hemen bir düzlüğe dökülecektir."},{"n":15,"t":"Musa’nın haberi sana geldi mi?"},{"n":16,"t":"Tuva’da, kutsal bir vadide, Rabbi ona şöyle hitab etmişti:"},{"n":17,"t":"Firavuna git çünkü o azdı."},{"n":18,"t":"«Arınmağa niyetin var mı?"},{"n":19,"t":"Rabbine giden yolu göstereyim ki O’na saygı duyup korkasın.»"},{"n":20,"t":"Bunun üzerine ona en büyük mucizeyi gösterdi."},{"n":21,"t":"Fakat o Musa’yı yalanladı, karşı geldi."},{"n":22,"t":"Sonra sırtını döndü; çalışmağa koyuldu."},{"n":23,"t":"Adamlarını toplayıp seslendi:"},{"n":24,"t":"Sizin en yüce Rabbiniz benim dedi."},{"n":25,"t":"Allah bunun üzerine onu dünya ve ahiret azabına uğrattı."},{"n":26,"t":"Doğrusu bunda Allah’tan korkan kimseye ders vardır."},{"n":27,"t":"Ey inkarcılar! Sizi yaratmak mı daha zordur, yoksa göğü yaratmak mı?"},{"n":28,"t":"Ki Allah onu bina edip yükseltmiş ve ona şekil vermiştir."},{"n":29,"t":"Gecesini karanlık yapmıştır. Gündüzünü aydınlatmıştır."},{"n":30,"t":"Ardından yeri düzenlemiştir."},{"n":31,"t":"Suyunu ondan çıkarmış ve otlak yer meydana getirmiştir."},{"n":32,"t":"Dağları yerleştirmiştir."},{"n":33,"t":"Bunları sizin ve hayvanların geçinmesi için yapmıştır."},{"n":34,"t":"Her şeyi bastıran o büyük felaket geldiği zaman."},{"n":35,"t":"O gün insan, neyin peşinde koşmuş olduğunu hatırlar."},{"n":36,"t":"Gören kimseler için cehennem ortaya çıkarılmıştır."},{"n":37,"t":"Artık kim azmışsa."},{"n":38,"t":"ve şu yakın hayatı yeğlemişse."},{"n":39,"t":"Onun barınağı cehennemdir."},{"n":40,"t":"Ancak kim Rabbinin huzurunda durup hesap vermekten korkmuş ve nefsini kötü heveslerden menetmişse."},{"n":41,"t":"Onun barınağı da cennettir."},{"n":42,"t":"Ey Muhammed! Senden kıyametin ne zaman gelip çatacağını sorarlar."},{"n":43,"t":"Sen nerede, onun vaktini söylemek nerede?"},{"n":44,"t":"Onun bilgisi Rabbine aittir."},{"n":45,"t":"Sen ancak, ondan korkacak olanları uyarırsın."},{"n":46,"t":"Onlar onu gördükleri zaman sanki dünyada bir akşam veya onun kuşluk vaktinden fazla kalmamış gibi olurlar."}],[{"n":1,"t":"Surat astı ve döndü."},{"n":2,"t":"Yanına âma geldi diye."},{"n":3,"t":"Ne bileceksin sen belki o arınacak?"},{"n":4,"t":"Yahut öğüt alacak da bu öğüt, kendisine fayda verecek."},{"n":5,"t":"Kendisini yeterli görüp tenezzül etmeyene gelince."},{"n":6,"t":"Sen onunla ilgileniyorsun!"},{"n":7,"t":"Onun arınmamasından sana ne?"},{"n":8,"t":"Fakat koşarak sana gelene;"},{"n":9,"t":"Allah’tan sakınarak gelmişken."},{"n":10,"t":"Sen onunla ilgilenmiyorsun!"},{"n":11,"t":"Asla olmaz böyle şey! Kur’an ayetleri birer hatırlatmadır öğüttür."},{"n":12,"t":"Dileyen onu düşünüp öğüt alır."},{"n":13,"t":"Sahifeler içindedirler, değerli, şanslı."},{"n":14,"t":"Yükseltilen ve tertemiz tutulan (sahifeler)"},{"n":15,"t":"Taşıyıcıların ellerindedirler."},{"n":16,"t":"(Allah’a göre) değerli ve çok iyi (yazıcı ve taşıyıcıların)."},{"n":17,"t":"Kahrolası insan ne kadar da nankördür."},{"n":18,"t":"Allah onu hangi şeyden yarattı."},{"n":19,"t":"Nutfe (sperm)den. Onu yarattı ve ona biçim verdi."},{"n":20,"t":"Sonra ona yolu kolaylaştırmıştır."},{"n":21,"t":"Sonra onu öldürdü, kabre koydurdu."},{"n":22,"t":"Sonra dilediği zaman onu yeniden diriltti."},{"n":23,"t":"Hayır, insan hala Allah’ın kendisine emrettiğini yapmadı."},{"n":24,"t":"İnsan yiyeceğine bir baksın."},{"n":25,"t":"O suyu döktükçe döktük."},{"n":26,"t":"Sonra toprağı güzelce yardık."},{"n":27,"t":"Orada bitirdik, taneleri."},{"n":28,"t":"Üzümler, yoncalar,"},{"n":29,"t":"Zeytinler, hurmalar."},{"n":30,"t":"İri ve sık ağaçlı bahçeler."},{"n":31,"t":"Meyveler ve çayırlar."},{"n":32,"t":"Sizin ve hayvanlarınızın yararına."},{"n":33,"t":"Kulakları sağır edercesine yüksek o gürültü geldiği zaman."},{"n":34,"t":"İşte o gün kişi kaçar, kardeşinden,"},{"n":35,"t":"Anasından, babasından,"},{"n":36,"t":"Eşinden ve oğullarından."},{"n":37,"t":"O gün herkesin başından aşkın işi vardır."},{"n":38,"t":"Bazı yüzler o gün parıl parıldır."},{"n":39,"t":"Güleç ve sevinçli."},{"n":40,"t":"Bazı yüzler o gün tozlanmış."},{"n":41,"t":"Karanlıklar bürümüştür onları."},{"n":42,"t":"İşte onlar hayasız pis kafirlerdir."}],[{"n":1,"t":"Güneş dürüldüğü zaman"},{"n":2,"t":"Yıldızlar kararıp dağıldığı zaman"},{"n":3,"t":"Dağlar sökülüp dağıldığı zaman"},{"n":4,"t":"Gebeliğinin onuncu ayındaki develer kendi haline bırakıldığı zaman"},{"n":5,"t":"Yabani hayvanlar bir araya toplandığı zaman"},{"n":6,"t":"Denizler kaynatıldığı zaman"},{"n":7,"t":"Nefisler eşleştirildiği, ruhlar bedenlere girdiği zaman,"},{"n":8,"t":"Ve sorulduğu zaman o diri diri toprağa gömülen kıza;"},{"n":9,"t":"Hangi suçtan ötürü gömüldü? diye"},{"n":10,"t":"Siciller açılıp yayıldığı zaman"},{"n":11,"t":"Gökkubbe yıkıldığı zaman"},{"n":12,"t":"Cehennem kızıştırıldığı zaman"},{"n":13,"t":"Cennet yaklaştırıldığı zaman"},{"n":14,"t":"Herkes ne getirdiğini öğrenecektir."},{"n":15,"t":"Yemin ederim geri kalıp gizlenenlere."},{"n":16,"t":"Akıp giderken ışık verenlere."},{"n":17,"t":"Kararan geceye."},{"n":18,"t":"Soluk almaya başlayan sabaha."},{"n":19,"t":"Şüphesiz o şerefli bir elçinin sözüdür."},{"n":20,"t":"Kuvvet sahibidir. Arşın sahibi Allah katında yücedir."},{"n":21,"t":"Orada kendisine itaat edilir, güvenilir."},{"n":22,"t":"Arkadaşımız deli değildir."},{"n":23,"t":"Şüphesiz (Muhammed) onu apaçık ufukta görmüştür."},{"n":24,"t":"O, gayb hakkında töhmet altında tutulamaz."},{"n":25,"t":"O, kovulmuş şeytanın sözü değildir."},{"n":26,"t":"O halde nereye gidiyorsunuz?"},{"n":27,"t":"O alemlere öğütten başka birşey değildir."},{"n":28,"t":"Sizden düzelmeyi dileyenler için."},{"n":29,"t":"Ancak alemlerin Rabbi Allah dilemedikçe siz dileyemezsiniz."}],[{"n":1,"t":"Gök yarıldığı zaman."},{"n":2,"t":"Yıldızlar saçıldığı zaman."},{"n":3,"t":"Denizler patladığı zaman."},{"n":4,"t":"Kabirlerin içi dışına çıktığı zaman."},{"n":5,"t":"Herkes neyi öne, neyi geriye aldığını öğrenir."},{"n":6,"t":"Ey insan! Seni engin kerem sahibi Rabbine, karşı aldatan nedir?"},{"n":7,"t":"O, seni yaratan, belini doğrultan ve seni dengeli kılan."},{"n":8,"t":"Dilediği biçimde sana şekil veren Rabbine."},{"n":9,"t":"Hayır! Aksine siz dini yalanlıyorsunuz."},{"n":10,"t":"Şüphesiz başınızda bekçiler vardır."},{"n":11,"t":"Şerefli katipler."},{"n":12,"t":"Yaptıklarınızı bilirler."},{"n":13,"t":"Şüphesiz iyiler cennettedirler."},{"n":14,"t":"Kötüler de cehennemdedirler."},{"n":15,"t":"Din günü oraya sürülürler."},{"n":16,"t":"Oradan bir daha çıkamazlar."},{"n":17,"t":"Din gününün ne olduğunu bilir misin sen?"},{"n":18,"t":"Hem din gününün ne olduğunu sen nereden bileceksin?"},{"n":19,"t":"O gün kimsenin kimseye faydası olmaz. O gün yetki sadece Allah’ındır."}],[{"n":1,"t":"Ölçü ve tartıda hile yapanların vay haline."},{"n":2,"t":"Onlar insanlardan bir şey ölçüp aldıkları zaman eksiksiz alırlar."},{"n":3,"t":"Kendileri onlara birşey ölçtükleri veya tarttıkları zaman (ölçü ve tartıyı) eksik verirler."},{"n":4,"t":"Onlar, tekrar dirileceklerini sanmıyorlar mı?"},{"n":5,"t":"Büyük bir gün"},{"n":6,"t":"İnsanların alemlerin Rabbinin huzurunda durdukları gün."},{"n":7,"t":"Hayır. Allah’ın buyruğundan dışarı çıkanların yazısı muhakkak siccindedir."},{"n":8,"t":"Siccin’in ne olduğunu bilir misin sen?."},{"n":9,"t":"O, mühürlenmiş bir kitabdır."},{"n":10,"t":"Vay haline o gün yalanlayanların."},{"n":11,"t":"Kıyamet gününü yalanlamış olanların."},{"n":12,"t":"Oysa onu azgın, günahkardan başkası yalanlamaz."},{"n":13,"t":"Ayetlerimiz kendisine okunduğu zaman ’eskilerin masalları’ der."},{"n":14,"t":"Hayır, aksine kazandıkları, kalplerini karatmıştı."},{"n":15,"t":"Hayır, şüphesiz onlar o gün, Rabblerinden mahrum kalacaklardır."},{"n":16,"t":"Sonra onlar, şüphesiz cehenneme sürükleneceklerdir."},{"n":17,"t":"«İşte bu, yalanlayıp durduğunuz şeydir» denilecek."},{"n":18,"t":"Fakat iyilerin yazısı İlliyyin’dedir."},{"n":19,"t":"İlliyyinin ne olduğunu bilir misin sen."},{"n":20,"t":"Mühürlenmiş bir kitaptır o."},{"n":21,"t":"Yakınlaştırılmış olanlar onu görürler."},{"n":22,"t":"İyiler şüphesiz cennette nimetler içindedirler."},{"n":23,"t":"Tahtlar üzerinde kurulup etrafı seyrederler."},{"n":24,"t":"Yüzlerinde cennetin aydınlığını görürsün."},{"n":25,"t":"Onlara mühürlü saf bir içecekten içirilir."},{"n":26,"t":"Sonu misktir, onun. İşte yarışanlar bunda yarışsınlar."},{"n":27,"t":"Karışımı tesnimdendir."},{"n":28,"t":"Yakınlaştırılmış olanların kendisinden içtiği kaynaktan."},{"n":29,"t":"Suçlular, şüphesiz inanmış olanlara gülerlerdi."},{"n":30,"t":"Yanlarından geçtikleri zaman da birbirlerine göz kırparlardı."},{"n":31,"t":"Ailelerinin yanına döndükleri zaman da eğlenmeye başlarlardı."},{"n":32,"t":"İnananları gördüklerinde «Bunlar sapıklardır» derlerdi."},{"n":33,"t":"Oysa kendileri, onların üzerine bekçi olarak gönderilmemişlerdi."},{"n":34,"t":"İşte bugün de inananlar kafirlere gülerler."},{"n":35,"t":"Tahtlar üzerinde kurulup bakarlar;"},{"n":36,"t":"Kafirler, yaptıklarının cezasını gördüler mi? diye."}],[{"n":1,"t":"Gök yarıldığı,"},{"n":2,"t":"Rabbini dinleyip O’na yaraşır şekilde boyun eğdiği zaman!"},{"n":3,"t":"Yer uzatılarak dümdüz yapıldığı,"},{"n":4,"t":"İçindekileri dışarı atıp boşaldığı,"},{"n":5,"t":"Yeryüzü dümdüz hale getirildiğinde, içindeki her şeyi dışarı atarak tamamen boşaldığında ve tabiatı gereği Rabbine kulak verdiğinde,"},{"n":6,"t":"Ey insanoğlu! Sen Rabbine kavuşuncaya kadar çalışıp çabalayacak, sonunda O’na kavuşacaksın."},{"n":7,"t":"O zaman kimin kitabı sağından verilirse,"},{"n":8,"t":"O kolay bir hesaba çekilecek."},{"n":9,"t":"Ve sevinçli olarak ailesine dönecektir."},{"n":10,"t":"Kimin kitabı da sırtının arkasından verilirse."},{"n":11,"t":"O, ölümü çağıracak."},{"n":12,"t":"Ve çılgın alevli cehenneme girecektir."},{"n":13,"t":"Çünkü o, dünyada ailesi arasında sevinç içinde idi."},{"n":14,"t":"Rabbine hiç dönmeyeceğini sanmıştı."},{"n":15,"t":"Aksine Rabbi onu görmekte idi."},{"n":16,"t":"Akşamın alaca karanlığına,"},{"n":17,"t":"Geceye ve gecenin içinde barındırdığına."},{"n":18,"t":"Dolunay halindeki Ay’a andolsun ki,"},{"n":19,"t":"Şüphesiz siz bir durumdan diğerine uğrayacaksınız."},{"n":20,"t":"Onlara ne oluyor da inanmıyorlar?"},{"n":21,"t":"Kendilerine Kur’an okunduğu zaman secde etmiyorlar?"},{"n":22,"t":"Aksine kafir olanlar yalanlıyorlar."},{"n":23,"t":"Oysa Allah onların içinde gizlediklerini biliyor."},{"n":24,"t":"Onları acıklı bir azab ile müjdele."},{"n":25,"t":"İman edenler ve salih ameller işleyenler hariç. Onlar için bitip tükenmeyen mükafat vardır."}],[{"n":1,"t":"Burçları olan göğe."},{"n":2,"t":"Vaad edilen güne."},{"n":3,"t":"Şahitlik edene ve şahitlik edilene andolsun ki."},{"n":4,"t":"Hendekleri hazırlayanların canı çıksın."},{"n":5,"t":"Bol yakıtı olan ateşi oralara dolduranların."},{"n":6,"t":"Hani onlar hendeklerin başında oturuyorlardı."},{"n":7,"t":"Müminlere yaptıkları işkenceleri seyrediyorlardı."},{"n":8,"t":"Müminlerden öç almalarının tek sebebi aziz, övgüye lâyık Allah’a inanmalarıydı."},{"n":9,"t":"O Allah ki göklerin ve yerin sahibi olan Allah’a. Allah herşeye şahittir."},{"n":10,"t":"İnanmış erkek ve kadınlara işkence edip, sonra yaptıklarına tevbe etmeyenler, var ya. Şüphesiz onlar için cehennem azabı vardır. Yakıp kavuran azap ta onlaradır,"},{"n":11,"t":"inananlar ve iyi işler yapanlar için de altlarından ırmaklar akan cennetler vardır. İşte büyük kurtuluş budur."},{"n":12,"t":"Doğrusu Rabbinin yakalaması şiddetlidir."},{"n":13,"t":"İlk yaratan ve tekrar yaratacak olan da O’dur."},{"n":14,"t":"O, bağışlayan ve sevendir."},{"n":15,"t":"Arş’ın sahibidir, yücedir."},{"n":16,"t":"İstediğini yapandır."},{"n":17,"t":"Sana orduların haberi geldi mi?"},{"n":18,"t":"Firavun ve Semud’a ait orduların."},{"n":19,"t":"Doğrusu kâfirler bir yalanlama içindedirler."},{"n":20,"t":"Halbuki Allah onları artlarından kuşatmıştır."},{"n":21,"t":"Aksine, o şerefli bir Kur’an’dır."},{"n":22,"t":"Korunan bir levhada (Levh-i Mahfuz’da)’dır."}],[{"n":1,"t":"Göğe ve târıka and olsun."},{"n":2,"t":"Târıkın ne olduğunu bilir misin sen?"},{"n":3,"t":"O karanlığı delen yıldızdır."},{"n":4,"t":"Hiçbir can yoktur ki başında bir koruyucu olmasın."},{"n":5,"t":"İnsan nereden yaratıldığına bir baksın.[746]"},{"n":6,"t":"Fışkıran su damlacığından yaratıldı."},{"n":7,"t":"Bel ile kaburga kemikleri arasından çıkan."},{"n":8,"t":"Allah onu tekrar yaratmaya kadirdir."},{"n":9,"t":"Gizli işlerin ortaya çıkarıldığı günde."},{"n":10,"t":"Onun hiçbir gücü ve hiçbir yardımcısı olmaz."},{"n":11,"t":"Yağmurun sahibi göğe."},{"n":12,"t":"Bitkinin yeşerdiği yere andolsun ki."},{"n":13,"t":"Şüphesiz Kur’an kesin bir sözdür."},{"n":14,"t":"O saçma bir söz değildir."},{"n":15,"t":"Onlar bir tuzak kuruyorlar."},{"n":16,"t":"Ben de bir tuzak kuruyorum."},{"n":17,"t":"Sen kâfirlere mühlet ver. Onlara biraz zaman tanı."}],[{"n":1,"t":"Rabbinin yüce adını takdis et."},{"n":2,"t":"O yaratan ve düzeltendir."},{"n":3,"t":"Ölçüleri belirleyip yolunu gösterendir."},{"n":4,"t":"Yemyeşil meraları bitirendir."},{"n":5,"t":"Sonra da onları kupkuru çöpe çevirendir."},{"n":6,"t":"Ey Muhammed! Sana Kur’an’ı biz okutacağız ve asla unutmayacaksın."},{"n":7,"t":"Yalnız Allah’ın dilediği başka. O açığı da bilir gizliyi de."},{"n":8,"t":"Seni en kolay yolu tutmağa muvaffak edeceğiz."},{"n":9,"t":"O halde hatırlatmak fayda verirse hatırlat."},{"n":10,"t":"Allah’tan korkan, öğüt alır."},{"n":11,"t":"Bedbaht olan ondan kaçacaktır."},{"n":12,"t":"O en büyük ateşe yaslanacaktır."},{"n":13,"t":"Sonra onun içinde ne ölür ne de yaşar."},{"n":14,"t":"Doğrusu mutluluğa ermiştir arınan,"},{"n":15,"t":"Rabbinin adını anıp namaz kılan."},{"n":16,"t":"Fakat siz şu dünya hayatını üstün tutuyorsunuz."},{"n":17,"t":"Oysa ahiret daha iyi ve daha kalıcıdır."},{"n":18,"t":"Bu hüküm elbette ilk sahifelerde de vardır."},{"n":19,"t":"İbrahim’in ve Musa’nın sahifelerinde."}],[{"n":1,"t":"Ey insanoğlu! Herşeyi kaplayacak kıyametin haberi sana gelmedi mi?"},{"n":2,"t":"O gün birtakım yüzler zillete bürünmüştür."},{"n":3,"t":"Zor işler altında bitkin düşmüştür."},{"n":4,"t":"Yakıcı ateşe yaslanırlar."},{"n":5,"t":"Kızgın bir kaynaktan içirilirler."},{"n":6,"t":"Onlar için kuru dikenden başka yiyecek de yoktur."},{"n":7,"t":"Ne semirtir, ne de açlığı giderir."},{"n":8,"t":"İnanmış olanların yüzleri, o gün, pırıl pırıldır."},{"n":9,"t":"Yaptıklarından hoşnutturlar."},{"n":10,"t":"Yüksek bir bahçededirler."},{"n":11,"t":"Orada boş söz işitmezler."},{"n":12,"t":"Orada akan bir kaynak vardır."},{"n":13,"t":"Orada yükseltilmiş tahtlar vardır."},{"n":14,"t":"Konulmuş kadehler."},{"n":15,"t":"Dizilmiş yastıklar."},{"n":16,"t":"Serilmiş halılar vardır."},{"n":17,"t":"Bu insanlar bakmıyorlar mı, develerin nasıl yaratıldığına?"},{"n":18,"t":"Göğün nasıl yükseltildiğine?"},{"n":19,"t":"Dağların nasıl dikildiğine?"},{"n":20,"t":"Yerin nasıl yayıldığına?"},{"n":21,"t":"Ey Muhammed! Sen öğüt ver. Çünkü sen ancak öğüt verensin."},{"n":22,"t":"Onların üzerinde zorlayıcı değilsin."},{"n":23,"t":"Ancak kim yüz çevirir, inkar ederse,"},{"n":24,"t":"Allah onu en büyük azaba uğratır."},{"n":25,"t":"Dönüşleri bizedir."},{"n":26,"t":"Sonra onların hesabını görmek bize düşer."}],[{"n":1,"t":"Andolsun sökmekte olan şafağa!"},{"n":2,"t":"On geceye,"},{"n":3,"t":"Çifte ve teke."},{"n":4,"t":"Gitmekte olan geceye."},{"n":5,"t":"Ki bunlarda akıl sahipleri için birer yemin değeri var."},{"n":6,"t":"Görmedin mi Rabbin ne yaptı Ad kavmine?"},{"n":7,"t":"Yüksek sütunlu İrem’e."},{"n":8,"t":"Ki ülkeler arasında onun eşi yaratılmamıştı."},{"n":9,"t":"Vadide kayaları oyarak evler yapan Semud kavmine?"},{"n":10,"t":"ve kazıklar sahibi Firavun’a."},{"n":11,"t":"Bunlar ülkelerinde azmışlardı."},{"n":12,"t":"Oralarda çok kötülük etmişlerdi."},{"n":13,"t":"Bu yüzden Rabbin onların üzerine azab kırbacını çarptı"},{"n":14,"t":"Çünkü Rabbin her an gözetlemektedir."},{"n":15,"t":"«Rabbim beni şerefli kıldı» der."},{"n":16,"t":"«Rabbim bana hor baktı» der."},{"n":17,"t":"Hayır yetime karşı cömert davranmıyorsunuz."},{"n":18,"t":"Yoksulu yedirmek konusunda birbirinizi özendirmiyorsunuz."},{"n":19,"t":"Size kalan mirası hak gözetmeden yiyorsunuz."},{"n":20,"t":"Malı pek çok seviyorsunuz."},{"n":21,"t":"Hayır, yer çarpılıp paralandığı zaman,"},{"n":22,"t":"Melekler sıra sıra dizilip, Rabbinin buyruğu gelince,"},{"n":23,"t":"Ki cehennem de o gün getirilmiştir. İşte o gün insan anlar, ancak artık anlamanın kendisine ne faydası var?"},{"n":24,"t":"O zaman insan, ’Ah keşke ben bu hayatım için önceden iyi işler yapıp gönderseydim’ der."},{"n":25,"t":"O gün O’nun yapacağı azabı kimse yapamaz."},{"n":26,"t":"O’nun vuracağı bağı hiç kimse vuramaz."},{"n":27,"t":"Ey huzura eren nefis!"},{"n":28,"t":"Razı edici ve razı edilmiş olarak Rabbine dön."},{"n":29,"t":"İyi kullarım arasına katıl."},{"n":30,"t":"Cennetime gir."}],[{"n":1,"t":"Hayır, and içerim bu şehre."},{"n":2,"t":"Ki sen bu şehre girmektesin."},{"n":3,"t":"Doğurana ve doğurduğuna andolsun ki,"},{"n":4,"t":"Biz insanı birtakım zorluklar, zahmetler ve sıkıntılar içinde yarattık."},{"n":5,"t":"İnsan hiç kimsenin kendisine güç yetiremeyeceğini mi sanıyor?"},{"n":6,"t":"Yığın yığın mal tüketmişimdir diyor."},{"n":7,"t":"Kimsenin kendisini görmediğini mi sanıyor?"},{"n":8,"t":"Biz ona iki göz vermedik mi?"},{"n":9,"t":"Bir dil, iki dudak vermedik mi?"},{"n":10,"t":"Biz ona eğri ve doğru iki yol göstermedik mi?"},{"n":11,"t":"Fakat o zor geçidi aşmaya girişmedi."},{"n":12,"t":"O zor geçidin ne olduğunu sen bilir misin?"},{"n":13,"t":"O geçit bir köle ve esir azad etmektir."},{"n":14,"t":"Yahut açlık gününde doyurmaktır."},{"n":15,"t":"Akraba olan yetimi,"},{"n":16,"t":"Hiçbir şeyi olmayan yoksulu,"},{"n":17,"t":"Sonra inanıp birbirlerine sabır tavsiye eden ve merhamet tavsiye edenlerden olmak."},{"n":18,"t":"İşte bunlar amel defterleri sağdan verilenlerdir."},{"n":19,"t":"Ayetlerimizi inkar edenler. İşte onlar amel defterleri soldan verilenlerdir."},{"n":20,"t":"Onlar her yönden ateşe kapatılacaklardır."}],[{"n":1,"t":"Güneşe ve onun ışığına,"},{"n":2,"t":"Ardından gelmekte olan Ay’â,"},{"n":3,"t":"Onu ortaya koyan gündüze,"},{"n":4,"t":"Onu bürüyen geceye,"},{"n":5,"t":"Göğe ve onu yapana,"},{"n":6,"t":"Yere ve onu yayana."},{"n":7,"t":"Kişiye ve onu şekillendirene,"},{"n":8,"t":"Sonra da ona iyilik ve kötülük kabiliyeti verene andolsun ki,"},{"n":9,"t":"Kendini arıtan saadete ermiştir."},{"n":10,"t":"Kendini fenalıklara gömen kimse de ziyana uğramıştır."},{"n":11,"t":"Semud kavmi azgınlığı yüzünden Hakkı yalanladı."},{"n":12,"t":"İçinden azgını ileri atılınca"},{"n":13,"t":"’Allah’ın devesine ve onun su içme hakkına dokunmayın’ dedi."},{"n":14,"t":"Onu yalanladılar, deveyi kestiler. Rabbleri de, günahları yüzünden azabı başlarına geçirdi, orayı dümdüz etti."},{"n":15,"t":"Çünkü Allah bu işin sonundan korkmazdı ki."}],[{"n":1,"t":"Örttüğü zaman geceye andolsun,"},{"n":2,"t":"Ortaya çıkıp göründüğü zaman gündüze andolsun,"},{"n":3,"t":"Erkeği ve dişiyi yaratana andolsun."},{"n":4,"t":"Sizin işiniz çeşit çeşittir,"},{"n":5,"t":"Kim verir korunursa,"},{"n":6,"t":"ve en güzel sözü doğrularsa,"},{"n":7,"t":"Onu en kolay başarıya ulaştırırız."},{"n":8,"t":"Fakat kim cimrilik eder, kendini zengin görüp kendisini Allah’tan müstağni sayarsa,"},{"n":9,"t":"Ve en güzel sözü de yalanlarsa,"},{"n":10,"t":"Biz de onu en zora yöneltiriz."},{"n":11,"t":"Çukura düştüğü zaman malı ona hiçbir fayda sağlamaz."},{"n":12,"t":"Doğru yola iletmek bize aittir."},{"n":13,"t":"Şüphesiz ahiret de dünya da bize aittir."},{"n":14,"t":"Ben sizi alev saçan bir ateşe karşı uyardım."},{"n":15,"t":"Ona ancak bedbaht kimse girer."},{"n":16,"t":"O ki yalanladı ve döndü."},{"n":17,"t":"En çok korkan ondan uzak tutulur."},{"n":18,"t":"O ki malını Allah rızası için vererek arınır, yücelir."},{"n":19,"t":"O yaptığı iyiliği birinden karşılık görmek için yapmaz."},{"n":20,"t":"Ancak yüce Rabbinin hoşnutluğunu gözeterek yapar."},{"n":21,"t":"Elbette kendisi de hoşnut olacaktır."}],[{"n":1,"t":"Kuşluk vaktine andolusun."},{"n":2,"t":"Durgunlaşan geceye andolsun ki,"},{"n":3,"t":"Rabbin seni bırakmadı ve sana darılmadı,"},{"n":4,"t":"Andolsun senin için ahiret dünyadan daha hayırlıdır,"},{"n":5,"t":"Rabbin sana verecek ve sen razı olacaksın."},{"n":6,"t":"O seni yetim bulup barındırmadı mı?"},{"n":7,"t":"Şaşırmış bulup da yol göstermedi mi?"},{"n":8,"t":"Fakir iken seni zengin etmedi mi?"},{"n":9,"t":"Yetime gelince sakın onu üzme,"},{"n":10,"t":"Dileneni de azarlama."},{"n":11,"t":"Yalnızca Rabbinin nimetini anlat."}],[{"n":1,"t":"Ey Muhammed! Senin göğsünü açmadık mı?"},{"n":2,"t":"Yükünü üzerinden almadık mı?"},{"n":3,"t":"Ki o belini bükmüştü,"},{"n":4,"t":"Senin şanını yüceltmedik mi?"},{"n":5,"t":"Muhakkak ki her güçlükle beraber bir kolaylık vardır,"},{"n":6,"t":"Gerçekten güçlükle beraber bir kolaylık vardır."},{"n":7,"t":"Öyleyse bir işi bitirince diğerine giriş,"},{"n":8,"t":"Ümit edeceğini Rabbinden iste."}],[{"n":1,"t":"Andolsun incir ve zeytine,"},{"n":2,"t":"Andolsun sina dağına,"},{"n":3,"t":"Andolsun bu güvenli Mekke şehrine,"},{"n":4,"t":"Biz insanı en güzel bir şekilde yarattık,"},{"n":5,"t":"Sonra onu aşağıların en aşağısı kıldık."},{"n":6,"t":"Yalnız inanan iyi işler yapanlar hariç. Onlar için kesintisiz bir mükafat vardır."},{"n":7,"t":"Ey insan! Öyleyken sana dini yalan saydırtan nedir?"},{"n":8,"t":"Allah hükmedenlerin en güzel hükmedeni değil midir?"}],[{"n":1,"t":"Yaratan Rabbinin adıyla oku."},{"n":2,"t":"O, insanı bir kan pıhtısından yarattı."},{"n":3,"t":"Oku, Rabbin en büyük kerem sahibidir."},{"n":4,"t":"O, insana kalemle yazmayı öğretti."},{"n":5,"t":"İnsana bilmediğini öğretti."},{"n":6,"t":"Hayır insan azar."},{"n":7,"t":"Kendini zengin gördüğü için."},{"n":8,"t":"Dönüş Rabbinedir."},{"n":9,"t":"Gördün mü şu men edeni."},{"n":10,"t":"Bir kulu namaz kılarken."},{"n":11,"t":"Gördün mü, ya o kul doğru yolda ise."},{"n":12,"t":"Yahut kötülüklerden sakınmayı emrederse."},{"n":13,"t":"Gördün mü, ya bu adam yalanlar, yüz çevirirse."},{"n":14,"t":"O, Allah’ın gördüğünü bilmiyor mu?"},{"n":15,"t":"Hayır eğer bundan vazgeçmezse onu perçeminden yakalarız."},{"n":16,"t":"O yalancı günahkar perçeminden."},{"n":17,"t":"O zaman gitsin de taraftarlarını çağırsın."},{"n":18,"t":"Biz de zebanileri çağıracağız."},{"n":19,"t":"Hayır ona boyun eğme. Rabbine secde et ve yaklaş."}],[{"n":1,"t":"Biz Kur’ân’ı kadir gecesinde indirdik."},{"n":2,"t":"Kadir gecesinin ne olduğunu sen nereden bileceksin?"},{"n":3,"t":"Kadir gecesi bin aydan hayırlıdır."},{"n":4,"t":"Melekler ve Ruh (Cebrail) o gecede Rablerinin izniyle her türlü iş için iner."},{"n":5,"t":"O gece, tan yerinin ağarmasına kadar bir esenliktir."}],[{"n":1,"t":"Apaçık delil kendilerine gelinceye kadar kitap ehlinden ve müşriklerden inkarcılar küfürden ayrılacak değillerdi."},{"n":2,"t":"Allah tarafından gönderilmiş tertemiz sahifeler okuyan bir elçidir."},{"n":3,"t":"O, sahifelerde doğru yazılmış hükümler vardır."},{"n":4,"t":"Ama, kendilerine kitab verilenler, onlara apaçık belge geldikten sonra ayrılığa düştüler."},{"n":5,"t":"Oysa onlar, doğruya yönelerek, dini yalnız Allah’a has kılarak O’na kulluk etmek, namazı kılmak ve zekatı vermekle emrolunmuşlardı. Dosdoğru olan din de budur."},{"n":6,"t":"Kitap ehlinden ve müşriklerden inkar edenler, sürekli olarak cehennem ateşindedirler. Onlar halkın en şerlileridir."},{"n":7,"t":"İnanıp ve iyi işler yapanlar da halkın en hayırlılarıdır."},{"n":8,"t":"Onların Rabbleri katındaki mükafatı içinde temelli ve sonsuz kalacakları, içlerinden ırmaklar akan Adn cennetleridir. Allah onlardan razıdır. Onlar da Allah’tan razıdır. Bu mükafat Rabbinden korkan kimseyedir."}],[{"n":1,"t":"Yer dehşetle sarsıldıkça sarsıldığı,"},{"n":2,"t":"Yeryüzü ağırlıklarını dışarı çıkardığı,"},{"n":3,"t":"Ve insanın «Buna ne oluyor» dediği zaman,"},{"n":4,"t":"İşte o gün yer haberlerini söyler,"},{"n":5,"t":"Çünkü Rabbin ona vahiy ile herşeyi bildirmiştir."},{"n":6,"t":"O gün insanlar ayrı ayrı gruplar halinde, ilahi divana çıkarlar ki, yaptıkları işler kendilerine gösterilsin."},{"n":7,"t":"Artık kim zerre ağırlığınca hayır yapmışsa onu görür,"},{"n":8,"t":"Ve kim zerre ağırlığınca şer yapmışsa onu görür."}],[{"n":1,"t":"Andolsun Allah yolunda koştukça koşanlara,"},{"n":2,"t":"Andolsun kıvılcımlar saçanlara,"},{"n":3,"t":"Sabah akşam akına çıkanlara,"},{"n":4,"t":"Ve tozu dumana katanlara,"},{"n":5,"t":"Düşman topluluğu içine dalanlara ki,"},{"n":6,"t":"İnsan Rabbine karşı çok nankördür."},{"n":7,"t":"Ve kendisi de buna şahittir."},{"n":8,"t":"Doğrusu o, malı çok sever."},{"n":9,"t":"Bilmez mi o, kabirlerde olanlar dışarı atıldığı,"},{"n":10,"t":"Kalplerde olanlar ortaya konulduğu zaman."},{"n":11,"t":"Doğrusu Rabbleri o gün herşeyinden haberdardır."}],[{"n":1,"t":"Gürültü koparacak olan,"},{"n":2,"t":"Nedir o gürültü koparacak olan,"},{"n":3,"t":"O gürültü koparacak olanın ne olduğunu sen nereden bileceksin?"},{"n":4,"t":"O gün insanlar yayılmış pervane gibi olurlar."},{"n":5,"t":"Dağlar atılmış renkli yün gibi olurlar."},{"n":6,"t":"Kimin tartıları ağır gelirse,"},{"n":7,"t":"O hoş bir hayat içinde olur,"},{"n":8,"t":"Kimin tartıları hafif gelirse,"},{"n":9,"t":"Onların yeri, (haviye) çukurdur,"},{"n":10,"t":"Onun ne olduğunu sen nereden bileceksin?"},{"n":11,"t":"O kızgın bir ateştir."}],[{"n":1,"t":"Mal ve evlat çoğaltma yarışı sizi oyaladı."},{"n":2,"t":"Nihayet kabirleri ziyaret ettiniz."},{"n":3,"t":"Hayır yakında bileceksiniz."},{"n":4,"t":"Yine hayır yakında bileceksiniz."},{"n":5,"t":"Hayır gerçeği kesin bilgi ile bilseydiniz,"},{"n":6,"t":"Andolsun ki cehennemi göreceksiniz."},{"n":7,"t":"Andolsun ki onu gözünüzle kesin olarak göreceksiniz."},{"n":8,"t":"Sonra o gün size verilmiş olan her nimetten sorguya çekileceksiniz"}],[{"n":1,"t":"Asr’a andolsun ki."},{"n":2,"t":"İnsan mutlak hüsrandadır."},{"n":3,"t":"Ancak iman edenler, iyi işler yapanlar, birbirlerine hakkı ve sabrı öğütleyenler bunun dışındadır."}],[{"n":1,"t":"İnsanları dilleri ile arkalarından çekiştiren ve karşılarında kaş, göz hareketleri ile onları aşağılayan herkese yazıklar olsun!"},{"n":2,"t":"Malı toplayıp onu teker teker sayana."},{"n":3,"t":"Malının kendisini ölümsüzleştireceğini zannedene yazıklar olsun."},{"n":4,"t":"Hayır. O kırıp geçen yere atılacaktır."},{"n":5,"t":"O kırıp geçenin ne olduğunu bilir misin sen?"},{"n":6,"t":"Allah’ın tutuşturulmuş ateşidir o."},{"n":7,"t":"Tırmanıp yüreklerin üstüne çıkan."},{"n":8,"t":"Cehennem onların üzerine kapatılacaktır."},{"n":9,"t":"Uzun sütunlar içinde."}],[{"n":1,"t":"Rabbinin fil sahiplerine yaptığını görmedin mi?"},{"n":2,"t":"Onların tuzaklarını boşa çıkarmadı mı?"},{"n":3,"t":"Onların üzerine sürülerle kuşlar gönderdi."},{"n":4,"t":"Onların üzerine pişkin tuğladan taşlar atıyorlardı."},{"n":5,"t":"Nihayet onları yenik ekin yaprağı gibi yapıverdi."}],[{"n":1,"t":"Kureyş’in uzlaşıp anlaşması için,"},{"n":2,"t":"Yaz ve kış yolculuklarında uzlaşıp anlaşması için."},{"n":3,"t":"Bu evin Rabbine kulluk etsin onlar."},{"n":4,"t":"O Rabb ki kendilerini açlıktan doyurmuş ve korkudan güvenliğe eriştirmiştir."}],[{"n":1,"t":"Dini yalanlayanı gördün mü?"},{"n":2,"t":"İşte o, öksüzü iter, kakar."},{"n":3,"t":"Yoksulu doyurmaya önayak olmaz."},{"n":4,"t":"Vay, o namaz kılanların haline ki;"},{"n":5,"t":"Onlar kıldıkları namazdan gafildirler."},{"n":6,"t":"Onlar gösteriş yaparlar."},{"n":7,"t":"En ufak bir yardımı esirgerler."}],[{"n":1,"t":"Ey muhammed! Doğrusu biz sana pek çok nimet vermişizdir."},{"n":2,"t":"Öyleyse Rabbin için namaz kıl ve kurban kes."},{"n":3,"t":"Doğrusu adı sanı ortadan kalkacak olan sana kin tutan kimsedir."}],[{"n":1,"t":"Ey kâfirler."},{"n":2,"t":"Ben sizin taptıklarınıza tapmam."},{"n":3,"t":"Siz de benim taptığıma tapmazsınız."},{"n":4,"t":"Ben sizin taptıklarınıza tapacak değilim."},{"n":5,"t":"Sizler de benim taptığıma tapacak değilsiniz."},{"n":6,"t":"Sizin dininiz size, benim dinim bana."}],[{"n":1,"t":"Allah’ın yardımı ve fethi geldiğinde"},{"n":2,"t":"İnsanların dalga dalga Allah’ın dinine girdiğini gördüğünde,"},{"n":3,"t":"Rabbini överek tesbih et, O’ndan mağfiret dile. Çünkü O tevbeleri kabul edendir."}],[{"n":1,"t":"Ebu Leheb’in iki eli kurusun, kurudu da!"},{"n":2,"t":"Malı ve kazandığı kendisine fayda vermedi."},{"n":3,"t":"Alevli ateşte yanacaktır."},{"n":4,"t":"Karısı da odun hamalı olarak."},{"n":5,"t":"Boynunda sağlam hurma lifinden örülmüş bir ip bulunacaktır."}],[{"n":1,"t":"O Allah tektir."},{"n":2,"t":"Allah Samed’dir."},{"n":3,"t":"O doğurmamış ve doğmamıştır."},{"n":4,"t":"Hiçbir şey O’nun dengi olmamıştır."}],[{"n":1,"t":"De ki; «Sığınırım ben, karanlığı yarıp sabahı ortaya çıkaran Rabbime."},{"n":2,"t":"Yarattığı şeylerin şerrinden."},{"n":3,"t":"Karanlığı çöktüğü zaman gecenin şerrinden."},{"n":4,"t":"Düğümlere üfleyip tüküren büyücü kadınların şerrinden."},{"n":5,"t":"ve hased ettiği zaman hasedcinin şerrinden.»"}],[{"n":1,"t":"Sığınırım ben, insanların Rabbine,"},{"n":2,"t":"insanların Melikine,"},{"n":3,"t":"insanların Tanrısına."},{"n":4,"t":"O sinsi vesvesecinin şerrinden."},{"n":5,"t":"O ki insanların göğüslerine kötü düşünceleri fısıldar."},{"n":6,"t":"Gerek cinlerden, gerek insanlardan."}]];
